if not addon.active then return end
local rows = addon.quests
rows[40755]={title={{24,1135967806},"스크류퓨즈 1000 작동"},description={{754,507289601},"저기, 부탁 하나만 들어줄래? 정말 중요한 부탁인데. 매몰비용 오류라는 거 알아? 내 세상에서는 그게 딱 맞는 말이야. 몇 년 동안, 그리고 엄청난 돈을 들여서 바나나를 수확할 가치가 있는지 없는지 판별하는 기계를 만들었거든. 익은 정도, 나이, 그리고 온갖 요소를 판단해서 수확할 가치가 있는지 없는지 결정해 주는 기계지. 그런데 $B$B말이야, 내가 그 기계를 맡긴 얼간이들이 길을 잃어서 여기 서쪽에 있는 캠프에 두고 왔어. $B$B베놈플레어한테 찢겨 죽을 각오로 사람들을 보내서 직접 가져오게 할 순 없거든. 그러니까 네가 좀 해 주면 안 될까? 스크루퓨즈 1000을 찾아서 조심스럽게 가져와 줘. 서쪽으로 조금만 가면 버려진 작은 캠프가 있을 거야."},objectives={{92,2138681820},"텔아빔에 있는 빅슬의 창고에서 빅슬 스크류퓨즈를 위해 스크류퓨즈 1000을 찾아 회수하세요."},progress={"So, you have any luck yet $c?","그래서,$c님, 혹시 좋은 소식 있으세요?"},completion={{142,510733394},"내 귀에 들리는 바로 이거예요! 정말 잘하셨어요. 덕분에 엄청난 시간을 절약할 수 있었어요. 아시다시피 시간은 금이죠, 특히 이런 경우에는 더더욱요."}}
rows[40756]={title={{28,2103406378},"작전명 FIX: 스크류퓨즈 1000"},description={{622,985139456},"저 멍청이들! 전체 $B$B메커니즘이 고장 났어. 내 예비 비전 레귤레이터랑 스프링어지 플랜지 둘 다 망가졌다고! 케잔에서 특별 주문한 저런 희귀 부품들을 구하는 데 얼마나 오래$B$B 걸렸는지 알아? 저놈들이 살아있었으면 내가 직접 저놈들을 지옥으로 보내버렸을 텐데. 케잔에서 희귀품을 구할 수 있는 곳은 딱 한 군데뿐인데, 네가 그놈과 얘기 좀 해 줘야 해. '재비'라는 가명을 쓰는 놈인데, 케잔의 비밀 요원이야. 여러 뒷거래 경로를 통해 일을 처리하지. 가서 -빅슬-이 보냈다고 말하고, 이 물품 목록을 가져다 줘."},objectives={{50,132500116},"타나리스의 스팀휘들 항구에 있는 자비와 대화하세요."},progress={{4,273767400},"예?"},completion={{167,656261629},"어, 무슨 용건이세요? 특별한 일로 오셨나요?$B$B아, 빅슬이 보냈군요, 그 바보 자식? 바나나 분류기를 만드는 데 5년이나 썼는데, 뭐가 필요하신가요?"}}
rows[40757]={title={{21,1601568532},"재비 지원 작전"},description={{745,1065930665},"<자비는 믿을 수 없다는 표정으로 목록을 보고는 웃었다.>하하!$B$B 내가 그렇게 귀중한 물건들을 쉽게 줄 거라고 생각하는 건가? 꼬마야, 이 물건들은 희귀하고 엄청나게 값비싼 물건이지만, 그 녀석이 필요로 하고 원한다면, 내가 먼저 부탁할 일이 있어. 그 전에는 그런 걸 줄 생각은 전혀 $B$B없어. 쉽지? 내가 검은무쇠 종족 중 하나인 '다르네그 다크비어드'라는 놈과 거래를 좀 했었는데, 그놈에게 강력한 물건들을 꽤 많이 빌려줬지. 그런데 그놈에게서 아무 소식도 없고, 사기를 당했다는 걸 확신하게 됐어. 자네가 검은바위 심층부의 섀도우포지에 가서 그놈에게서 '극강의 코담배'를 되찾아 와야 해. 그놈은 거기 있는 집 어딘가에 있을 거야."},objectives={{156,834624888},"블랙록 심층부로 들어가, 거주지 근처에 있는 다르넥 다크비어드에게서 '극강의 코담배'를 회수하여 타나리스의 스팀휘들 항구에 있는 자비에게 전달하세요."},progress={{97,1259710197},"그 쓸모없는 도둑놈을 잡아서 정의를 구현해 줄 수 있나요?$B$B아니면, 제 물건이라도 되찾아 주실 수 있나요?"},completion={{100,1178527149},"<재비는 작은 코담배 더미를 못마땅한 표정으로 바라본다.>$B$B이건 정말 실망스럽군."}}
rows[40758]={title={{23,1021867588},"재비 지원 작전 2"},description={{619,1759390882},"음, 꼬마야, 이런 말 하기는 좀 그렇지만, 그 드워프가 코담배를 거의 다 써버렸어. 운이 좀 없군. 이 돈으로는 네가 원하는 부품 값의 극히 일부도 충당할 수 없겠지만, 부탁 하나만 들어주면 나머지는 해결될 거야. $B$B내 의뢰인들이 과학적 목적으로 독성 물질을 '연구'하려고 하는데, 동부 역병지대에 있는 타락한 공포 괴물에게서 얻을 수 있는 '타락한 정수'를 구하려고 하거든. 그러니까 그 타락한 정수를 구해다 주면 나머지 부품 값은 쉽게 해결될 거야, 그렇지?"},objectives={{128,1338954426},"동부 역병지대로 가서 타나리스의 스팀휘들 항구에 있는 자비에게 '역병의 정수'를 얻기 위해 역병에 걸린 괴물들을 처치하세요."},progress={{125,942423380},"그 저주받은 정수를 여기로 가져올 때는 조심해. 스팀휘들 지역에 끔찍한 질병이 퍼지는 건 절대 원치 않아."},completion={{140,246676187},"음, 네가 실제로 돌아올 줄은 몰랐어. 아쉽네. 뭐, 어쩔 수 없지. 고블린의 단어는 이 세상에서 나름의 의미가 있으니까, 적어도 몇몇 사람들에게는 말이야."}}
rows[40759]={title={{29,4234837},"스크류퓨즈로 복귀하는 작업"},description={{308,1263881451},"물건 다 구해다 줘서 고마워. 시간도 얼마 안 걸렸고. 케잔은 너 같은 사람이 필요해. 자, $B$B이제 그 바보 빅슬 물건들 상자에 넣었으니, 빨리 가져다 줘. 여기서 너무 오래 머물게 놔두지 않았어. 내 사업이 들통나는 건 절대 원치 않아. 알겠지?"},objectives={{86,2081353281},"빅슬의 고가 부품을 텔아빔에 있는 빅슬 창고의 빅슬 스크류퓨즈로 가져오세요."},progress={{24,1199010185},"그래서 자비는 뭐라고 말했죠?"},completion={{132,1296051090},"아, 구하기가 그렇게 어려웠나 보군요. 저 때문에 이거 구해다 주시느라 너무 수고 많으셨겠어요? 자, 수고비로 동전 좀 드릴게요."}}
rows[40760]={title={{23,1024854469},"최종 수리 작전"},description={{396,1255460879},"이제 필요한 재료는 다 모았으니 마지막 수리 작업만 하면 되는데, 그러려면 재료가 좀 더 필요해요. 혹시 너무 귀찮게 $B$B해드리는 건 아닌지 모르겠지만, 공업용품 좀 구해다 주시겠어요? 토륨 막대 6개, 금 전력 코어 1개, 퓨즈선 1개, 그리고 토륨 위젯 1개가 필요해요. 이 재료들만 있으면 스크류퓨즈 1000을 고칠 수 있을 것 같아요."},objectives={{135,1696734597},"텔아빔에 있는 빅슬의 창고에서 빅슬 스크류퓨즈 제작에 필요한 토륨 막대 6개, 금 동력 코어 1개, 퓨즈 와이어 1개, 토륨 위젯 1개를 모으세요."},progress={{29,1630146748},"그 모든 것들을 다 얻으셨나요?"},completion={{427,218394087},"<빅슬은 안도의 한숨을 내쉬며 입가에 미소를 가득 떴다.>$B$B정말 큰 도움이 됐어. 텔아빔에서 일하는 건 모든 걸 복잡하게 만들거든. 특히 위치가 워낙 외진 곳이라 더 그렇고.$B$B친구, 정말 고마웠어. 그래서 뭔가 보답해야겠어. 좋은 게 생각났어.$B$B있잖아, 혹시 또 필요한 게 있으면 언제든 말해. 네 덕분에 몇 년 동안 벌었을 돈보다 더 많은 골드를 아낄 수 있었고, 시간도 거의 그만큼 절약했어!"}}
rows[40761]={title={{35,1844395088},"어둠의 철을 모독하는 자의 비밀"},description={{528,222004479},"이봐, 자네가 내게 정말 큰 도움을 줬는데, 아직도 그 은혜를 갚아야 하네. 혹시 총에 관심 있는 거 없나? 아무 총이나 원하는 게 아니라, 검은무쇠 디세크레이터 말이야. 내가 스팀휘들한테 희귀품을 구하러 데려다주겠다고 도와준 사람이 있는데, 그 은혜를$B$B 갚지 못했거든. 혹시 관심 있다면, 구하는 데 시간이 좀 걸릴 거라는 걸 알아둬. 겔웨그 다크브로우에게 가서 내가 보냈다고, 그리고 설계도를 달라고 한다고 말해 봐."},objectives={{141,1823347277},"스팀휘들 항구의 겔웨그 다크브로우에게서 다크 아이언 디세크레이터 설계도를 획득한 후, 빅슬 스크루퓨즈에게 돌아가십시오."},progress={{27,623273660},"그래서, 그와 이야기해 보셨나요?"},completion={{334,994210643},"그가 불평했겠지, 그렇지?$B$B<빅슬이 웃는다.>$B$B그래, 이건 아주 비밀스러운 다크 아이언 엔지니어의 프로토타입이야. 그래서 우리가 이걸 완벽하게 마스터하려는 거지.$B$B상상도 못 하겠지만, 난 꽤 유명한 엔지니어고, 이 '다크 아이언'들과도 여러 번 마주친 적이 있어. 심지어 그들의 자랑스러운 도시에서 몇몇 일을 의뢰받은 적도 있지."}}
rows[40762]={title={{24,142466304},"검은무쇠 디세크레이터"},description={{852,1171866520},"음, 이 계획은 제가 처음 예상했던 것보다 훨씬 복잡하군요. 구하기 쉽지 않은 희귀 재료들이 많이 필요해요... 우선, $B$B기본 검은무쇠 소총이 필요합니다. 제작 기술을 가진 엔지니어가 만들어 줄 수 있죠. 둘째로, 검은바위 심층부에서 마그마 응축기가 필요한데, 골렘 연구실 근처에서 찾을 수 있습니다. 셋째로, 극한의 열을 견딜 수 있는 정교한 아르카나이트 총열이 필요합니다. 이것은 하층 검은바위 첨탑 깊숙한 곳, 보급관 근처에서 찾을 수 있습니다. 마지막으로, 가장 찾기$B$B 어려운 재료인 용암 조각이 필요합니다. 이 아이템은 용암 핵 심층부의 용암 파괴자에게서 얻을 수 있습니다. 제작을 완료하려면 $B$B용암 핵에서 찾을 수 있는 불타는 핵 3개와 마법이 부여된 토륨 막대 10개도 필요합니다. 이 재료들을 $B$B모두 모으면 저에게 오세요. 그럼 제작을 시작할 수 있습니다."},objectives={{152,138384274},"텔아빔에 있는 빅슬의 창고에서 빅슬 스크류퓨즈를 위해 다크 아이언 소총, 마그마 응축기, 정교한 아르카나이트 총열, 용융 파편을 모으세요."},progress={"Have any luck recovering the materials yes $N?","$N번 자료를 복구하는 데 성공하셨나요?"},completion={"Behold, a creation of great magnitude, the ideas of wicked dwarven design, crafted by yours truly.$B$BI hope this serves you well, and does what damage you need to deal on those that may be your enemy.$B$BWe are even now, this surely is worth quite a bit of gold after all, maybe not as much as my Screwfuse 1000, but close enough.$B$BBest of luck out there $N, I hope we cross paths again.","자, 이것이 바로 그 엄청난 걸작이다. 사악한 드워프의 아이디어로 탄생한, 바로 내가 직접 만든 것이다.$B$B이게 자네에게 큰 도움이 되고, 자네의 적들에게 필요한 피해를 입히는 데 효과적이길 바란다.$B$B이제 우리는 비겼군. 어쨌든 이건 꽤 많은 금화 가치가 있지. 내 스크루퓨즈 1000만큼은 아니겠지만, 거의 비슷하군.$B$B행운을 빌어.$N다시 만날 수 있기를."}}
rows[40763]={title={{26,1371184306},"깊이 파고들 기회"},description={"Yo $R, fancy seeing a capable adventurer out here! Interested in some work? You see, when Tel Co. came here, this place was deserted. Just monkeys and bananas.$B$BBut that wasn't the case before, you know? Thousands of years ago, this island was a mountain range on the border of nations, and there's sure to be riches hidden here. To begin with, my surveyors have discovered some ancient Zandalari ruins on the northern coast dating back over ten thousand years.$B$BHowever, the ruins are infested with restless ghosts! As muscle, go there and slay those ghosts, and bring any tablets or writings you find. I'll make it worth your time. Promise, yeah?","$R야, , 여기서 유능한 모험가를 만나다니 반갑군! 일거리 좀 해볼래? 있잖아, 텔 컴퍼니가 여기 왔을 땐 완전히 버려진 곳이었어. $B$B원숭이랑 바나나밖에 없었지.하지만 전에는 그렇지 않았어. 수천 년 전, 이 섬은 여러 나라의 국경에 있는 산맥이었고, 분명 엄청난 보물이 숨겨져 있을 거야. 우선, 우리 측량사들이 북쪽 해안에서 만 년이 넘는 고대 잔달라 유적을 발견했어.하지만, 그 $B$B유적에는 불안한 유령들이 득실거리고 있어! 자, 가서 그 유령들을 처치하고, 발견한 석판이나 문서들을 가져와. 그만한 값진 보상을 해줄게. 약속하지, 알았지?"},objectives={{131,1278734322},"텔아빔의 텔 코 베이스캠프에서 영적 방랑자 8명을 처치하고 고대 트롤 석판 4개를 수집하여 고고학자 트릭시아 골드스파크에게 전달하세요."},progress={{20,1455674097},"자, 어떻게 됐어?"},completion={"This is a nice haul and the ghosts are gone, yeah? I will order the crew to start diggin' once we make sure there's no further complications. Now let's see about these texts... Hmm, very fascinating! $r I may need your assistance again.","꽤 괜찮은 수확이군. 유령들도 사라졌고, 그렇지? 더 이상 문제가 없는지 확인하는 대로 인부들에게 발굴 작업을 시작하라고 지시하겠어. 자, 이제 이 문자들을 살펴볼까... 흠, 아주 흥미롭군!$r, 네 도움이 다시 필요할지도 몰라."}}
rows[40764]={title={{11,377991773},"아조타 골드"},description={{658,1994061653},"만 년 전, 잔달라리족은 아조타라는 문명과 경쟁하고 있었습니다. 세상이 산산조각 나고 조상의 땅덩어리 대부분이 바다에 잠기면서 그들의 싸움은 끝이 났습니다. 텔아빔은 바로 그 두 문명이 충돌했던 지역입니다. 트롤족은 이 석판에 언급된 전투에서 패배한 것으로$B$B 보이며, 석판에는 트롤들이 의식 장소에서 신들에게 제물로 바쳐지고 그들의 재물이 묻혔다고 기록되어 있습니다. 즉, 이 의식 장소 아래에 금이 묻혀 있을 가능성이 있다는 뜻입니다! 그리고 어쩌면 우리는 이미 그것을 발견했을지도 모릅니다.$B$B 톱니 모양 군도의 가장 서쪽 섬으로 가서 눈에 띄는 의식 장소를 찾아보세요. 찾으면 땅을 파기 시작하세요!"},objectives={{127,1847375599},"텔아빔의 텔 코 베이스캠프에 있는 의식 장소 주변을 파헤쳐 고고학자 트릭시아 골드스파크를 위한 아조타 의식 유물 보관소를 찾으세요."},progress={{46,2124331703},"그래서? 날 애태우지 마, 해냈어?"},completion={{282,188205225},"와! 바로 이거야! 이 전리품으로 우리는 엄청난 명성과 찬사를 얻게 될 거야. 아조타, 트롤, 그리고 다른 문명들이 묻어둔 금까지! 당신은 당연히 몫을 받을 자격이 있어! 앞으로 또 함께 일할 기회가 있을지도 몰라. 정말 큰 도움이 됐어!"}}
rows[40765]={title={{15,556921191},"빅슬을 찾아서!"},description={{514,2109357365},"몇 주 전에 버려진 캠프와 빅슬의 창고와의 연락이 끊겼습니다. 빅슬의 창고는 북부 자원 채취 사업의 수익에 아주 중요한 곳이었습니다. 사업을 다시 시작하려면 그곳이 폐허가 되거나 원숭이들로 뒤덮여 있지 않은지 확인해야 합니다. 더 $B$B중요한 건, 빅슬은 쓸모없는 장치를 만드는 데만 정신이 팔려 있긴 하지만, 물류의 달인이었다는 겁니다. 북쪽으로 멀리 $B$B떨어진 빅슬의 창고로 가세요. 길을 따라가면 바로 도착할 겁니다. 거기서 빅슬이 살아 있는지 확인해 보세요."},objectives={{91,1798973346},"텔아빔 북쪽에 있는 빅슬의 창고로 가서 빅슬이 아직 살아 있는지 확인하십시오."},progress={{4,273767400},"예?"},completion={{126,1924252532},"어, 텔라즈가 보냈어? 텔라즈가 언제쯤 연락할까 궁금했는데, 아무래도 요즘 여기 상황이 꽤 정신없나 봐!"}}
rows[40766]={title={{20,1501900239},"빅슬의 보고서"},description={{294,469699635},"자, 우리는 여전히 건재합니다. 물론 이곳 야생 동물들과 꽤 많은 마주침을 겪긴 했지만요. I가 텔라즈 $B$B남작에게 보고서를 작성했으니, 텔 코퍼레이션 기지 캠프로 가져가세요. 그러면 그가 특공대를 투입해서 사태를 수습할 때 우리가 아직 건재하다는 걸 알게 될 겁니다."},objectives={{74,1523081751},"빅슬의 보고서를 텔아빔에 있는 텔 코퍼레이션 기지 캠프의 텔라즈 남작에게 가져다 주십시오."},progress={{49,1219141158},"빅슬의 창고 소식 들으셨나요?"},completion={{321,1579624532},"빅슬 본인이 보낸 보고서라고? 당장 가져와!$B$B<텔라즈 남작은 호기심 가득한 눈으로 편지를 정신없이 읽다가 안도의 한숨을 내쉬었다.>$B$B오, 정말 다행이군! 빅슬이 없었더라면 저 위 상황을 어떻게 처리해야 할지 전혀 몰랐을 거야. 수고했어, 꼬마야. 자, 수고비로 동전 좀 줄게."}}
rows[40767]={title={{31,775705043},"베놈플레어의 마지막 비행"},description={{412,986359164},"이봐 친구, 좀 도와줄래?$B$B 이 지역에 베놈플레어들이 우글거려서 골치가 아파. 벌써 몇 명이나 죽었어. 부탁인데, 이 근처 정글에서 베놈플레어 몇 마리만 처리해 주면 훨씬 수월해질 $B$B거야. 서쪽이랑 남서쪽 일대에 널려 있으니까, 12마리 정도 처치하고 돌아오면 돼."},objectives={{83,289402185},"텔아빔에 있는 빅슬의 창고에서 잘위즈 하드루그를 위해 독살자 뱀 12마리를 처치하세요."},progress={{34,252659189},"그 벌레들 다 없앴어요?"},completion={{186,660710037},"어머나, 정말 재주가 많으시군요. 이렇게 빨리 해낼 줄은 몰랐습니다.$B$B자, 이거 받으세요. 단속반이 남쪽으로 도망가 버려서 여분이 많이 남아있거든요."}}
rows[40768]={title={{22,1833840724},"파도 마루를 가로지르다"},description={{440,746750025},"매일 점점 더 많은 나가들이 주변 섬 해안으로 몰려들고 있습니다. 무슨 목적으로 오는지는 모르겠지만, 일주일$B$B 후에 수백 마리로 불어나기 전에 지금 처리하는 게 낫겠습니다. 나가들이 얼마나 빨리 한 지역을 뒤덮는지 소문을 들었습니다. 북쪽의 뾰족한$B$B 섬들 ​​주변에서 나가들을 찾을 수 있을 겁니다. 그들을 찾아 처치하고, 증거로 비늘 스무 개를 가져오십시오."},objectives={{81,71792521},"텔아빔에 있는 빅슬의 창고에서 잘위즈 하드루그를 위해 파도 능선 비늘 20개를 모으세요."},progress={{35,2064870707},"그래, 얘야, 저울은 이제 제대로 잡혔니?"},completion={{133,1307079846},"나쁘지 않네요, 수고 많으셨습니다. 정글을 조금이라도 더 다루기 쉽게 만드는 일은 우리에게 언제나 숭고한 일이죠.$B$B감사의 표시로 드립니다."}}
rows[40769]={title={{15,452356671},"칠윈드 아머"},description={{733,1492196009},"제대로 된 일을 한 지 정말 오래됐네요. 솔직히 말해서, 진짜 일이 너무 간절해요. 텔아빔에 갇혀서 한동안 그저 좀 나은 수리공 노릇이나 하고 있었거든요. 제 안의 대장장이$B$B 본능이 불타오르는데, 미쳐버리기 전에 뭔가 특별한 걸 만들어보고 싶어요. 오래전 에버룩에서 일할 때, 눈 덮인 툰드라를 누비는 엄청나게 강력한 생명체인 칠윈드 키메라에 매료됐었죠.$B$B 몇몇 칠윈드 키메라에게서 희귀한 서리 뿔이 자란다는 소문이 돌았는데, 그걸 구해서 갑옷으로 만들어보고 싶어요. 혹시 해주실 수 있나요? 칠윈드 키메라는 여기에서 북쪽으로 한참 떨어진 윈터스프링에서 찾을 수 있어요."},objectives={{120,1432661306},"텔아빔에 있는 빅슬의 창고에서 라진 브라스라이트를 위해 냉기바람 키메라를 처치하고 서리가 내린 냉기바람 뿔피리를 모으세요."},progress={{79,1674293746},"혹시 마음에 드는 코트를 찾으셨나요? 아니면 추운 날씨에 입을 코트를 찾으러 오신 건가요?"},completion={{225,1863798023},"음, 이건 정말 희귀한 물건이군요. 당신이 없는 동안 뿔을 갑옷에 접목시킬 수 있는 몇 가지 아이디어를 생각해 봤는데, 완벽한 아이디어를 떠올린 것 같습니다.$B$B도움에 대한 감사의 표시로 이걸 받으세요!"}}
rows[40770]={title={{18,592903011},"멀록-원숭이 전쟁"},description={{251,2087805112},"에부는 위험에 처한 부족을 지켜야 해요! 오랫동안 원숭이들은 멀록과 싸워왔는데, 멀록은 항상 원숭이 근처에 있으면서 공격했어요. 제가 우리를 안전하게 지키고 멀록과 싸워요. 혹시$B$B 여러분도 멀록과 싸우시나요? 에부와 친구들을 위해 큰 멀록도 처치해 주세요. 도와주셔서 정말 감사해요!"},objectives={{125,1932167074},"텔아빔의 톱니섬에서 스파이트핀 타이드헌터 8마리, 스파이트핀 웨이브크리퍼 6마리, 스파이트핀 오라클 4마리, 그리고 글르그블을 처치하여 에부를 얻으세요."},progress={{29,32986066},"멀록을 다치게 했나요? 멀록을 이겼나요?"},completion={{54,1543089770},"에부를 도와주셔서 감사합니다!$B$B원숭이들이 감사드립니다, 저희도 감사드립니다!"}}
rows[40771]={title={{19,2138638429},"사라진 친구!"},description={{218,78348510},"부족에서 친구를 납치당했어요, 멀록들이 친구를 훔쳐갔어요, 도와주시겠어요?$B$B 친구가 멀록 캠프 근처에 있어요, 친구를 되찾아 멀록들에게서 구해 주세요, 너무 늦기 전에! 도와주시겠어요? 니부는 강한 원숭이예요, 니부를 구하고 부족을 도와주세요!"},objectives={{72,930021492},"텔아빔에 있는 에부를 위해, 뾰족한 섬의 멀록 캠프에서 니부를 구출하세요."},progress={{29,82107970},"니부를 찾았나요? 니부를 구했나요?"},completion={{91,1607759613},"에부, 감사합니다. 에부가 당신에게 가장 큰 선물을 드립니다.$B$B저희는 모든 것에 감사드립니다!"}}
rows[40772]={title={{19,183282132},"끔찍한 예티"},description={{458,2123795715},"우리 예티들이 모두 악한 것은 아닙니다. 한때 우리 종족은 거대한 나무 곁에 서서 아제로스의 주민들에게 선물을 주던 시절이 있었습니다. 하지만 이제 $B$B그런 시대는 지나갔고, 많은 예티들이 어둠의 길을 걷고 있습니다. 남쪽에는$B$B 그들의 소굴이 있는데, 그곳에는 사악한 스노우볼이 있습니다. 그 이름을 입에 담는 것만으로도 저조차도 $B$B오싹해집니다. 부디 그들의 세력을 약화시켜 주시고, 축제를 즐기는 이들이 악이 축제의 선을 가리는 걱정 없이 평화롭게 축제를 즐길 수 있도록 해주시길 바랍니다."},objectives={{61,669746102},"겨울의 장막 계곡에서 끔찍한 눈 예티 8마리를 처치하여 콜드하울을 획득하세요."},progress={{71,1197798549},"친구여, 경고하건대 도움을 요청해야 할 것이다. 그들은 강하고 만만치 않은 상대다."},completion={{233,1855537634},"정말 훌륭한 일을 해내셨습니다! 덕분에 연휴를 무사히 보낼 수 있었을지도 몰라요! 이제 많은 사람들이 안심하고 잠들 수 있게 되었으니, 주변에 악이 덜 도사리고 있다는 사실에 감사드리고 싶습니다. 개인적으로 진심으로 감사드립니다.$B$B이것을 가져가세요. 가장 추운 곳에서 당신에게 도움이 되기를 바랍니다."}}
rows[40773]={title={{23,431800832},"블러드 엘프의 침입"},description={{625,226053870},"우리 정찰병들이 펠우드 지역에 새로운 침입자들이 나타났다는 것을 확인했습니다. 그들은 먼 이국 땅에서 온 외래종으로, 저 멀리 떨어진 외부 세력에 충성하는$B$B 자들입니다. 그들이 여기서 무엇을 하려는지는 확실하지 않지만, 그들의 $B$B정체는 분명합니다. 그들은 블러드 엘프이며, 그들의 군주이자 악마 사냥꾼인 일리단에게 충성하는 자들입니다. 그들이 좋은 의도를 갖고 있지 않다는 것이 확실하며, 그들의 계획을 저지하고 싶습니다. 그들은 블러드베놈 폭포 북동쪽, 섀터 스카 베일 근처 배신자의 낡은 동상 주위에 모여 있습니다. 그곳으로 가서 블러드 엘프 배지 7개를 모으십시오. $B$B그러면 그들이 메시지를 알아듣고 왔던 곳으로 돌아갈지도 모릅니다."},objectives={{140,106609964},"펠우드의 블러드베놈 포스트에 있는 배신자의 신전 주변에 있는 블러드 엘프 충성파들에게서 블러드 엘프 배지 7개를 모아 토르겐 블랙스카에게 전달하세요."},progress={"So, has the deed been done $r?","그래서,$r번 일은 끝난 건가요?"},completion={{87,882139264},"잘했어, 네 실력을 증명했군. 이제 그들은 펠우드를 떠나 다시는 돌아오지 않을지도 몰라."}}
rows[40774]={title={{20,1158522011},"오염된 점액 샘플"},description={{468,1845670071},"왕립 약제학회는 항상 다양한 문제에 대한 새로운 해결책과 연구 및 실험에 사용할 새로운 화합물을 찾고 있습니다. 제가 펠우드에$B$B 온 이유 중 하나가 바로 그런 문제 때문인데, 혹시 도움을 주실 수 있을까요? 블러드베놈 폭포 주변에는 상당히 독성이 강한 점액질 덩어리들이 널려 있습니다. 저는 언더시티에서 진행할 여러 연구에 필요한 오염된 점액질 슬러지가$B$B 필요합니다. 샘플 15개를 모아주시면 수고비로 지불하겠습니다. 어떠신가요?"},objectives={{122,385635352},"펠우드에 있는 블러드베놈 포스트의 약제사 클락슨을 위해 블러드베놈 폭포 근처의 점액 괴물들에게서 오염된 점액 슬러지 15개를 모으세요."},progress={{33,1317828881},"제 샘플을 받으셨나요?"},completion={{152,138803877},"어머, 정말 흥미롭군요. 독성 물질이 가득 들어있네요.$B$B언더시티에 계신 은인들께서 기뻐하실 겁니다. 약속대로 이 동전들을 가져가세요."}}
rows[40775]={title={{18,1647132919},"아무런 질문도 하지 않겠습니다."},description={{415,731265652},"매우 민감한 사안에 대한 도움이 필요합니다.$B$B 다행히도 당신은 말을 할 수 없거나 답변을 간결하게 하는 것을 선호하는 것 같군요. 제가 딱 필요한$B$B 조건입니다. 당신에게 맡길 일은 간단합니다. 블러드베놈 폭포로 가서 주변의 점액질 괴물들을 처치하고, 그 점액을 모아 저에게 가져오십시오. 이 일을 아무런 논의나 질문 없이 수행할 수 있다면 그에 상응하는 보상을 받겠습니다."},objectives={{119,1384117024},"펠우드 탈론브랜치 글레이드에 있는 바나 그레이스폴을 위해 블러드베놈 폭포 근처의 점액 생물로부터 오염된 점액 슬러지 15개를 모으세요."},progress={{70,1609797487},"더 이상 시간을 낭비하지 마세요. 일을 끝내고, 제대로 끝내도록 하세요."},completion={{57,1845810070},"잘했어요.$B$B이제 가셔도 돼요. 더 이상 필요 없어요."}}
rows[40776]={title={{29,417528594},"그들은 스스로를 일리다리라고 부른다"},description={{871,932584680},"정찰병들이 산산조각난 흉터 골짜기 동쪽, 우리 부족이 '배신자의 신전'이라고 부르는 곳 근처에서 수상한 움직임을 포착했다고 보고했습니다. 그곳에는 우리 역사에 큰 영향을 미친 일리단 스톰레이지의 차가운 동상이 서 있습니다. 감히 그에 대해 공개적으로 말하는 자는 많지 않지만, 저는 더 이상 이 땅에 살지 않는 존재의 이름을 거론하는 데 두려움을 느끼지$B$B 않습니다. 하지만, 이건 역사 수업이 아닙니다. 그 동상 아래에는 신도레이 무리가 자리를 잡고 있습니다. 아마도 아즈샤라를 피해 도망쳐 왔거나, 아니면 오랫동안 숨어 지냈을지도 모릅니다. 저는 대사제가 아즈샤라의 통치 시대를 떠올리게 하는 이 잡종들을 도왔던 것을 기억합니다. 하지만 그녀는 분명히 $B$B착각했습니다. 그들은 스스로를 일리다리라고 부르지만, 제 생각에 그들은 배신자와의 연관성을 어리석게 인정함으로써 스스로의 운명을 결정지은 것 같습니다. 우리는 그들의 수를 줄여야 합니다. 이 숲은 이미 감염되었고, 더 이상의 역병은 감당할 수 없습니다."},objectives={{112,808304602},"펠우드 탈론브랜치 숲에 있는 살로란 나이트웰의 배신자 신전에서 블러드 엘프 충성파 10명을 처치하세요."},progress={{25,550591319},"그들은 동정받을 자격이 없다."},completion={{182,1221817927},"배신자에 대한 믿음을 자랑하던 자들의 몰락을 목격하는 것은 꽤나 통쾌한 일이다. 그들은 돈 받고 고용된 용병의 손에 죽음을 맞이함으로써 자신들의 명성을 조롱거리로 만들었다."}}
rows[40777]={title={{15,1852169619},"빅 그린 불리"},description={{504,1735655498},"린테아는 두 손으로 얼굴을 가리고 흐느껴 울고 있습니다. 눈물을 닦으며 그녀는 새로운 희망이 담긴 눈빛으로 당신을 바라봅니다.$B$B \"어른이시죠? 사감 선생님은 무슨 일이 생기면 어른들에게 도움을 요청해야 한다고 항상 말씀하셨어요. 그리고 지금 정말 심각한 문제가 $B$B생겼어요! 오늘 아침에 다른 아이들을 데리러 학교에 갔다가 돌아오면서 우리한테 선물을 놓고 가셨는데, 돌아오실 때까지 열어보지 말라고 하셨어요. 그런데 $B$B지금 선물이 없어졌어요! 모두가 슬퍼하고 있어요. 다 그 초록색 못된 녀석 때문이에요!\""},objectives={{44,859572994},"조키에게 절도 혐의에 대해 따져 물으세요!"},progress={{6,691853874},"안녕하세요."},completion={{38,1073030060},"조키는 호드에서 가장 강한 전사입니다!"}}
rows[40778]={title={{17,1032339202},"조키는 도둑이 아니야!"},description={{616,668627868},"뭐라고? 조키는 도둑이 아니야! 조키는 명예로운 오크라고. 물론 조키가 가끔 약한 아이들에게 누가 제일 강한지 알려주긴 하지만, 그저 진실만을 말할 뿐이야! 린테아와 다니엘은 너무 말랐고, 브레카는 그냥 정령들과 이야기하는 따분한 할머니가 되고 싶어 할 뿐이라고. 조키는 사우르팡이나 그의 형처럼 훌륭한 전사가 될 거야! 아니면 그롬마쉬처럼 될지도 몰라. 마트론 선생님이 그롬마쉬는 호드의 영웅이었다고$B$B 했잖아. 왜 자꾸 조키에게 훔친 선물로 괴롭히는 거야? 난 아무것도 훔치지 않았어, 내 명예를 걸고 맹세해! 마트론 선생님이 눈사람 하나가 장갑을 잃어버렸는데 나중에 알고 보니 도둑맞은 거였다고 했던 게 기억나는데, 가서 한번 물어보는 게 어때?"},objectives={{76,1881736826},"윈터 베일 베일에서 사라진 도난당한 선물에 대해 미스터 미슬토에게 이야기해 보세요!"},progress={{18,1553047025},"즐거운 겨울 축제 보내세요!"},completion={{144,1888875891},"조키는 아직 말썽꾸러기 명단에 오르지 않았어요. 가끔 말이 좀 거칠긴 하지만, 아무것도 훔치지는 않았거든요. 아이들을 잘 대해줘서 고마워요! 선물이에요!"}}
rows[40779]={title={{20,779296226},"무시무시한 크람푸스"},description={{841,1004400328},"틴셀은 얼마 전에 장갑을 잃어버렸는데, 친절한 축제 참가자들이 도와줘서 되찾았지! 그런데 장갑이 돌아오면서 내 의심이 확신으로 바뀌었어. 이 세상에서 그렐을 소환할 수 있는 존재는 단 하나뿐인데, 바로 그 녀석이 다시 아제로스를 괴롭힐 때가 온 것 같아.$B$B 겨울의 대부, 크람푸스! 매년 겨울 아제로스의 모든 선물을 훔치러 나타나는 분노에 찬 영혼이지! 다행히도 그는 베일에는 모습을 드러낼 수 없고, 겨울의 대부가 내게 그의 위치를 ​​알 수 있는 방법을 알려줬어. 그 위치는$B$B 꽤 정확하지. 선물을 돌려줘! 축제는 끝나서는 안 돼! 하지만 명심해, 크람푸스는 영혼이야. 완전히 죽는 법이 없어. 내년에 반드시 돌아올 거야. 겨울봄 어딘가, 아마도 어둡고 동족 악마들이 우글거리는 곳에 있을 거야."},objectives={{99,619368988},"사악한 크람푸스를 물리치고, 윈터 베일 베일에서 미스터 미슬 토를 위해 도난당한 선물 자루를 되찾으세요!"},progress={{21,628755376},"이미 가지고 계신가요?"},completion={{134,1678731400},"정말 고마워요! 이제 축하 행사를 계획대로 진행할 수 있겠네요. 여기에서 제가 드리는 특별한 선물로 하나를 고르세요!"}}
rows[40780]={title={{22,499152585},"전설에 대하여 문의하기"},description={"Greetings $r, enjoying the celebration? You may have heard the short abridged version of why this celebration was held when it was limited to Ironforge and Orgrimmar. But as you can see, there's much more than dwarves here. Many races seem to have a version of Greatfather Winter in their culture.$B$BI suspect there is more to this tale. Seek out the storytellers. Let's start with the Night elf, Tauren, and Furbolg version of the tale so that you do not get it all mixed up. Pay attention cause their stories likely contain important clues that we will utilize.","안녕하세요,$r 님. 축제를 즐기고 계신가요? 예전에 아이언포지와 오그리마에서만 이 축제가 열렸을 때는 간략하게 요약된 이야기를 들으셨을지도 모르겠습니다. 하지만 보시다시피, 이 축제에는 드워프만 관련된 것이 아닙니다. 많은 종족들이 각자의 문화 속에 위대한 겨울의 아버지(겨울 할아버지)와 같은 존재를 모시고$B$B 있는 것 같습니다. I는 이 이야기에 더 많은 내용이 숨겨져 있을 거라고 생각합니다. 이야기꾼들을 찾아보세요. 혼동을 피하기 위해 나이트엘프, 타우렌, 퍼볼그의 이야기부터 시작해 보겠습니다. 그들의 이야기에는 우리가 활용할 중요한 단서들이 숨겨져 있을 가능성이 높으니 주의 깊게 들어주세요."},objectives={{157,1338340763},"겨울의 장막 골짜기에 있는 물린 스노우비어드를 찾아가 나이트 엘프 이야기꾼, 타우렌 이야기꾼, 퍼볼그 이야기꾼에게 위대한 겨울의 아버지에 대해 문의하세요."},progress={{26,472468828},"돌아오셨군요, 어떻게 되셨나요?"},completion={{189,1348798646},"아주 잘했어요! 좋은 시작입니다. 전설 속 인물들은 모두 겨울에 나타나 추위로부터 구원과 보호를 가져다주는 공통된 특징을 보이는 것 같네요. 계속해서 이야기를 이어가 봅시다..."}}
rows[40781]={title={{30,1049812812},"레전드에 대한 추가 문의"},description={{269,218783708},"다음으로는 드워프, 고블린, 그리고 얼음 트롤 이야기꾼들과 이야기를 나눠보세요. 네, 알아요. 얼음 트롤들이 그다지 친절한 종족은 아니지만, 그들의 이야기도 들어보고 싶어요. 전처럼 집중하세요. 이 전설을 제대로 파헤치려면 모든 세부 사항이 중요할 수 있습니다!"},objectives={{155,619077622},"겨울의 장막 골짜기에 있는 멀린 스노우비어드를 만나려면 드워프 이야기꾼, 고블린 이야기꾼, 얼음 트롤 이야기꾼에게 위대한 겨울의 아버지에 대해 문의하십시오."},progress={{28,1959882920},"그들과 이야기해 보셨나요?"},completion={{300,835321798},"아, 정말 흥미롭네요! 얼음 트롤들은 그걸 겨울의 정령이라고 부르는데, 어쩌면 일종의 정령일지도 모르겠어요. 고블린의 건 너무 뻔해서 전설이라고 할 수도 없을 것 같고, 드워프의 건... 뭐, 저도 잘 알죠. 하지만 그건 그렇고, 이제 재밌는 이야기가 시작될 거예요, 오호호!"}}
rows[40782]={title={{25,1676687177},"전설이 현실이 되다!"},description={{412,2133840100},"좋아! 이제 이야기를 들었으니, 직접 찾아볼 시간이야. 전설에는 어느 정도 진실이 담겨 있을 가능성이 높지. 맥주도 넉넉하고, 펜도 있고, 시간도 충분하니까. 칼림도르의 황야로 나가서 무엇을 찾을 수 있는지 확인해 봐! 너희는 타우렌의 겨울 족장, 나이트 엘프의 겨울의 고대신, 그리고 마지막으로 퍼볼그의 아버지 곰을 찾아야 할 거야."},objectives={{178,1573823826},"타우렌의 겨울 족장, 나이트 엘프의 겨울의 고대신, 그리고 퍼볼그의 아버지 곰을 모두 찾아 완료한 후, 겨울의 장막 골짜기에 있는 물린 스노우비어드에게 돌아가십시오."},progress={{3,2091085},"에야디야?"},completion={{152,1001124132},"목격 제보가 몇 건 있었다고요? 음... 예상치 못한 일이네요. 기록해 두겠습니다. 모든 제보를 조사한 후, 상황을 더 자세히 알아볼 수도 있겠습니다."}}
rows[40783]={title={{25,213366503},"전설에게 삶이 찾아왔다!"},description={{427,2028365723},"좋아! 이제 이야기도 들었으니, 본격적으로 사냥에 나서 보자. 전설 속에는 분명 어느 정도 진실이 담겨 있을 거야. 자, 이제 네 보고를 기다릴게. 주변 땅을 파헤쳐서 뭘 찾을 수 있는지 보자! 공짜로 하나 줄게! 고블린이 고용한 위대한 겨울의 신을 찾아줘... 헤헤! 그리고 위대한 겨울의 신의 근원과 위대한 겨울 정령인가 뭐시기 하는 것도 찾아봐."},objectives={{162,982673840},"겨울의 장막 골짜기에서 멀린 스노우비어드를 위해 고블린의 위대한 아버지, 드워프의 위대한 겨울 아버지, 그리고 얼음 트롤의 위대한 겨울 정령을 찾아보세요."},progress={{12,1881765766},"돌아왔어?"},completion={{164,595981844},"목격담이 있으시다고요? 네, 정말요? 음... 잠시만 기다려 주세요. 기록해 두겠습니다. 여섯 마리 모두 확보되면 다음 단계로 넘어가도록 하죠."}}
rows[40784]={title={{24,2108966237},"평생 쓸 수 있는 상품권!"},description={{668,1754383673},"정말 그 동물들을 찾았다고? 오크만 아니라 전부 진짜였다고? 그런데 증거는 하나도 안 가져왔군… 있잖아, 네 말만 믿을 순 없어. 우리가 뭔가 조치를 취해야 할지도 몰라. 진정해! 화내지 마! 그렇게 간절히 원하시면 믿어야겠지만… 됐어! 자, $B$B그럼 이렇게 해보는 건 어때? 몇 년 전에 주사위 게임에서 딴 순록 상품권이 있어. 새 친구를 타고 즐거운 시간 보낼 수 있을 거야. 진정해! 이 상품권을 베일에 있는 쿼크에게 가져가면 그가 순록을 처리해 줄 거야. 네 발견 사항은 기록해 뒀어! 술에 취했지만 글은 쓸 줄 알아. 내가 일하는 기관에 전달될 테니 안심해."},objectives={{82,1042593584},"순록 상품권을 윈터 베일 베일의 쿼크에게 가져가서 정당한 보상을 받으세요!"},progress={{4,273767400},"예?"},completion={{545,266254614},"어? 순록 교환권 있어? 맙소사! 그런 거 본 지 정말 오래됐네, 꼬맹아! 몇 년 전에 특별 프로모션으로 나왔던 건데… 멀린한테 속았다고? 하하, 그 늙은이는 전설 연구하러 왔다고 하지만 사실은 술 마시고 잔치나 하고 싶어 하는 거지. 연구비를 잔치에 썼다는 걸 직원들이 알면 가만히 있지 않을 테니, 그래서 이런 꼼수를 부린 거야. 뭐, 내 알 바 아니지. 어쨌든 교환권은 유효기간이 없으니까, 약속은 약속이야. 새 순록 잘 타렴!"}}
rows[40785]={title={{24,888370965},"모로고 썬더풋 왕이시여!"},description={{286,1532593192},"원숭이 우두머리에게 현상금이 걸렸습니다! 텔아빔과 텔 컴퍼니의 안전을 위해 싸울 의지가 있는 모든 이들은 힘을 합쳐 하이베일 라이즈 정상에서 마지막으로 목격된 모로고 썬더풋 왕을 추적하십시오. (함께$B$B 움직이는 게 좋을 겁니다. 그 원숭이는 정말 크거든요.)"},objectives={{143,1892339333},"모로고 썬더풋을 처치하고 그의 '썬더풋'을 획득하세요. 완료 후 텔아빔의 텔 코 기지 캠프에 있는 스닐 피즈왁에게 보상을 받으세요."},progress={{21,1907799052},"그래서, 무슨 일이야?"},completion={{327,1326283940},"어머나, 저건 엄청나게 큰 원숭이 발이군. 설마 모로고 썬더풋의 뒷발은 아니겠지?$B$B<스닐 피즈왁이 멍하니 당신을 바라봅니다.>$B$B현상금 게시판을 올렸을 때 누가 실제로 보상을 신청할 거라고는 생각도 못 했어. 게다가 누가 그렇게 미친 짓을 할 거라고는 더더욱 생각 못 했지!$B$B저기, 뭔가 찾을 수 있어."}}
rows[40786]={title={{17,573258431},"외국인의 마음 속에서"},description={{838,864690720},"이 숲 자체가 뒤틀리고 타락했습니다. 어디를 보더라도 이 악의 곪아 터지고 남아있는 기운이 느껴집니다. 야생 동물들은 비참한 삶을 살도록 저주받았고, 끊임없이 광기와 분노의 벼랑 끝에 서 있으며, 그들의 마음을 독으로 물들이는 거대한 악에 사로잡혀 있습니다. 저는 오랫동안 $B$B이곳의 야생 동물들을 연구해 왔지만, 이 현상을 더 잘 이해하기 위해서는 더 많은 표본이 필요합니다. 최근 텔아빔에서 일어나는 자연 현상을 발견했습니다. 그곳 야생 동물들의 분노가 제 귀에까지 들려왔고, 이곳에서 벌어지고 있는 일과의 연관성을 밝히기 위해 더 자세한 정보를 알아야 합니다. $B$B그러므로 분노한 바실리스크의 심장 다섯 개가 필요합니다. 그것들을 가져다주시면, 당신이 제공하는 표본을 잘 활용하겠습니다. 이 저주를 이해하는 데 진전을 이루도록 합시다."},objectives={{124,2032505606},"텔아빔의 그래블하이드 바실리스크에게서 얻은 뒤틀린 바실리스크 심장 5개를 펠우드의 탤론브랜치 글레이드에 있는 골하인 더 후디드에게 가져가세요."},progress={{35,1568238393},"당신의 여정은 어느 정도 진전되었나요?"},completion={{389,1341641481},"이 샘플들은 외부의 간섭이나 사악한 마법에 의해 변형된 흔적이 전혀 없다는 점에서 특이합니다. 오히려 원시적인 분노로 인해 기형이 된 것으로 보입니다.$B$B제가 놓치고 있는 연관성이 있을지도 모르지만, 이 샘플들이 펠우드에서 벌어지고 있는 일과 관련이 있을 것 같지는 않습니다.$B$B어쨌든 그러한 가능성을 배제해 주셔서 감사합니다."}}
rows[40787]={title={{18,1411803610},"사냥꾼을 사냥하다"},description={{854,1847916446},"십 년 전, 같은 피를 나누고 함께 빵을 먹던 동료 악마 사냥꾼에게 배신당했습니다. 그의 이름은 팔라다르 스타스플린터입니다. 그는 타락한 기운을 몰고 펠우드로 돌아와 이미 황폐해진 이 땅을 더욱 더럽혔습니다. 이 배신자에게$B$B 원한을 품고 있는 자는 많지만, 그중에서도 가장 큰 원한은 제 이름을 딴 강력한 유물, 다크윈드 스타를 훔쳐간 것입니다. 이 유물은 우리 가문 대대로 전해 내려온 것으로, 엄청난 힘을 지니고 있습니다. 저는 이 비열한 자의 손에서 유물을 되찾아야 하며, 이를 위해 당신의 도움이 필요합니다. $B$B저를 도와주고 싶다면, 배신자의 신전에서 팔라다르 스타스플린터를 찾으십시오. 그곳은 블러드베놈 폭포 북서쪽, 아이언트리 숲 남쪽에 있습니다. 당신의 임무는 그를 추적하여 제 것이 된 유물을 되찾는 것입니다. 자, 사냥을 시작합시다."},objectives={{90,1251009723},"펠우드에서 팔라다르 스타스플린터를 처치하고 니레미우스 다크윈드를 위해 다크윈드 스타를 되찾으세요."},progress={{90,959391667},"시간이 흐를수록 배신자 팔라다르는 자신의 사악한 음모를 이루는 데 한 걸음 더 가까워지고 있다."},completion={{372,1473979276},"오랜 세월 동안 나는 별 없이 지내왔지만, 너의 노력 덕분에 이제 별은 제자리를 찾았다.$B$B<니레미우스 다크윈드는 다크윈드 별의 힘에 흠뻑 빠진 듯 눈빛이 깊은 에너지로 빛났다.>$B$B젊은이, 자네는 훌륭하게 임무를 수행했네. 그에 걸맞은 보상을 준비했네."}}
rows[40788]={title={{19,1020883237},"무거운 지구 핵"},description={{662,2006202169},"안녕하세요! 좀 도와주시겠어요? 저희 에버룩에서는 온갖 연구를 진행하고 있는데, 연구가 있으면 돈도 벌 수 있거든요. 텔아빔에서 오는 물품 배송 관련해서 부업을 하고 있었는데, 아무 소식도 없어서 기다리고 있는 고객이 있어요. 혹시 $B$B제3자로서 이 문제를 해결해 주실 수 있을까요? 음식이나 음료는 제가 대접할게요. 남쪽으로 멀리 떨어진 텔아빔으로 가서 화난 바위 정령들을 찾아주시면 돼요. 그 녀석들이 무거운 흙 핵을 가지고 있는데, 제가 필요한 건 바로 그 8개예요. $B$B빨리 부탁드려요."},objectives={{124,1918722463},"윈터스프링의 에버룩에 있는 여관 주인 비지에게 가져다주기 위해 텔아빔의 격노한 바위 정령에게서 무거운 흙 핵 8개를 모으세요."},progress={{55,838755041},"이봐, 아웃라이더! 텔아빔에 다녀왔어?"},completion={{196,248034294},"어머나! 정말 흠잡을 데 없이 깔끔하네요. 훌륭한 작업입니다. 제 고객이 제가 이 일을 마무리하지 못했으면 좀 화를 냈을 텐데, 당신 덕분에 위기를 모면했어요.$B$B여기, 약속대로 드립니다."}}
rows[40789]={title={{24,126226963},"다누비스 경의 업적"},description={{617,1888007166},"길고 고된 여정이었습니다. 수많은 전투를 치르고 많은 적을 물리쳤습니다. 고향을 떠나기 전,$B$B 저는 복원된 빛의 대성당을 직접 보고 싶었습니다. 하지만 스톰윈드의 대사관이 아닌 이곳으로 보내졌다는 통보를 받았습니다. 솔직히 말씀드리면 마음이 아팠습니다. 이 모든 여정의 끝에 대성당을 다시 볼 수 없을지도 모른다는 두려움 때문입니다. 하지만$B$B 저는 여전히 대성당에 경의를 표하고 싶습니다. 친구여, 부디 저를 위해 그렇게 해주시길 $B$B부탁드립니다. 제 모든 업적이 담긴 이 책을 스톰윈드 대성당에 가져다 주시면, 이 버려진 세상의 끝자락에서 제가 잊히지 않도록 기록해 주시길 바랍니다."},objectives={{70,1163123090},"스톰윈드의 빛의 대성당에 다누비스 경의 업적을 가져다 놓으십시오."},progress={"Light's blessings, $N. Have you come to join our service?","빛의 축복이 함께하길,$N. 저희 예배에 함께 하시겠습니까?"},completion={"A Kul Tiran paladin gave you this book?$B$BIn Kul Tiras, the Holy Light is not as widespread as it is in Stormwind and Lordaeron; places where the tradition of the faith has long been established.$B$BYet I am gladdened to see that our church has touched the heart of such a worthy man. I will make sure all its contents are kept safe in our archives.$B$BThank you, and may the Light ever be with you, $N.","쿨 티라스의 성기사가 이 책을 드렸습니까?$B$B쿨 티라스에서는 스톰윈드와 로데론처럼 성스러운 빛이 널리 퍼져 있지는 않습니다. 그곳들은 오랫동안 신앙의 전통이 확립된 곳이죠.$B$B하지만 우리 교회가 이처럼 훌륭한 분의 마음을 움직였다니 기쁩니다. 이 책의 모든 내용을 우리 기록 보관소에 안전하게 보관하겠습니다.$B$B감사합니다. 그리고 빛이 언제나 당신과 함께하길 바랍니다.$N"}}
rows[40790]={title={{26,87039265},"쿨 티란 제공품: 식품"},description={"You there, RECRUIT!$B$BI don't see you wearing your tabard, what in- wait a second. What are you doing here $r, do you not see that we Kul Tirans are at a war?$B$BBah, why don't you make yourself useful, we are going to be needing all the provisions we can account for, perhaps you can find some spare food to feed some bellies for a few extra nights.$B$BEach day we keep the Horde at bay, is another day you can sleep safe at night. How about some Kodo Meat from the beasts in the Barrens? The horde use the beasts as pack mules, fighting beasts, and breed them for food, their heavy flanks should serve well to feed a few squadrons.","거기, 신병!$B$B휘장이 안 보이는군. 대체 무슨... 잠깐. 여기서 뭐 하는 거지, $r? 우리 쿨 티란이 전쟁 중인 게 안 보이나?$B$B흥, 그럼 쓸모 있는 일이라도 해라. 보급품은 많을수록 좋으니 며칠 더 버틸 식량을 구해 와라.$B$B우리가 호드를 막아내는 하루하루가 자네가 밤에 안전히 잠들 수 있는 하루를 더 벌어주는 셈이지. 불모의 땅에 있는 코도 고기는 어떤가? 호드는 코도를 짐꾼과 전투용으로 쓰고 식량으로도 기른다. 두툼한 옆구리살이면 몇 개 소대를 먹이고도 남을 거다."},objectives={{110,1990431004},"불모의 땅에서 야생 코도를 사냥하여 코도 고기 5개를 모아 불모의 땅 앵커즈 엣지에 있는 갑판장 다크할로우에게 가져다 주세요."},progress={{30,274752414},"이 구더기야, 음식 좀 받았어?!"},completion={"Well, look at that, not even part of the Old Alliance, and still making yourself useful as a $r. Perhaps you do have it cut out to be part of the navy after all.","어머, 보세요. 구 동맹의 일원도 아닌데$r이라는 숫자로 꽤 유용하게 쓰이고 있잖아요. 어쩌면 당신은 해군에 정말 잘 어울릴지도 모르겠네요."}}
rows[40791]={title={{35,1960364270},"쿨 티란 공급품: 특수 상품"},description={{725,671266275},"신병, 식량 모으는 일 잘했어. 우리 해군 소속은 아니지만 정말 잘했어. 혹시 아직도 여기서 도울 일이 있다면, 마지막으로 부탁할$B$B 게 하나 있어. 갑판장으로서 내 임무는 배에 필요한 물자를 확보하고 보장하는 건데, 우리가 여기 정박하는 동안 몇 가지 부탁을 $B$B들어줘야 해. 톱니항에 화약 한 통 주문이 있는데, 거기 은행 왼쪽 구석에 있을 거야. 그리고 마지막으로 테라모어로 가. 거기 아직 충성스러운 동맹들이 많이 남아있어. 부두에 정박해 있는 배들을 살펴보고 녹색 닻이 찍힌 상자를 찾아서 나에게 가져다줘."},objectives={{147,1704022297},"불모의 땅 앵커스 엣지에 있는 갑판장 다크할로우에게 라쳇에게서 밀수된 화약을, 테라모어에서 밀수된 조달품을 가져다 주세요."},progress={{25,1543013496},"그래서, 혹시 좋은 소식이라도 있었나요?"},completion={{293,1803838372},"자네를 믿은 건 옳은 선택이었군. 어쩌면 이 '신동맹'이 생각만큼 나쁘지만은 않은 것 같아. 아니, 내가 보기엔 너희 모두 이 전쟁을 위해 일하기엔 너무 게을렀던 것 같아.$B$B자네는 훌륭하게 임무를 수행했고, 그 노고에 대한 보상으로 이 표창장을 수여한다. 자랑스럽게 착용하거라, 병사여."}}
rows[40792]={title={{17,18438611},"물의 힘"},description={{603,1806100916},"우리 모두에게 길고 험난한 여정이었습니다. 몇 달간의 고군분투 끝에 보랄루스에서 가져온 도구들로 버텨왔지만, 이제 물자가 위험할 정도로 부족해졌습니다. 함대의 귀환 여정을$B$B 신속하게 진행할 수 있을 만큼 오랫동안 물에 대한 지배권을 유지하려면 새로운 물자 공급원이 필요합니다. 북서쪽에는 $B$B신비롭고 마법에 걸린 잿빛 골짜기 숲이 있습니다. 저는 그 지역의 심장부, 미스트랄 호수에서 강력하지만 변덕스러운 정령들의 존재를 감지했습니다. 그곳으로 가서 그 정령들에게서$B$B 희귀한 정제된 아쿠아 코어를 획득하십시오. 그러면 쿨 티라스는 당신의 공적을 결코 잊지 않을 것입니다."},objectives={{125,849871661},"불모의 땅 앵커즈 엣지에 있는 수력술사 셰일본을 위해 애쉬엔베일의 물 정령에게서 정제된 아쿠아 코어를 모으세요."},progress={{127,1119833962},"아쿠아 코어가 회수되었습니까?$B$B찾으시는 데 시간이 좀 걸리실 수도 있겠지만, 반드시 제가 확보해야 합니다."},completion={"The Aqua Core, and even more potent than I had hoped!$B$BIn this arid land of beasts, mongrels and demi-humans, I dared not hold faith in assistance from anyone. But now, my control of the tidal elements is secured.$B$BYou have my thanks, $c.","아쿠아 코어, 기대했던 것보다 훨씬 강력하군!$B$B짐승과 잡종, 반인반수들이 우글거리는 이 메마른 땅에서, 나는 누구의 도움도 감히 기대할 수 없었지. 하지만 이제, 나는 조석 원소를 완전히 통제할 수 있게 되었어.$B$B고맙다,$c"}}
rows[40793]={title={{22,1178839423},"드래곤마우 분쟁"},description={{687,361430460},"제2차 전쟁 동안, 쿨 티라스는 오그림 둠해머의 허름한 함대를 자랑스럽게 격파했습니다. 하지만 일부는 우리의 손아귀에서 벗어났습니다. 날개 달린 노예 짐승들을 타고 우리에게 헤아릴 수 없는 파멸을 안겨준 비겁한 용아귀 클랜 오크들은 세상의 어두운 구석으로 도망쳤습니다. 쿨$B$B 티라스는 그들에게 복수를 갈망합니다. 그들의 불길에 우리 용감한 동지들이 바다에서 고통스러운 죽음을 맞았기 때문입니다. 제 아버지 $B$B또한 같은 운명을 맞았고, 저는 그 일을 잊지 않았습니다... 습지에서 $B$B이 용아귀 짐승들이 마침내 뻔뻔스럽게 숨어 있던 곳에서 기어 나왔습니다. 이 오만함에 대한 대가로 저는 그들의 목을 베어버릴 것입니다. 그렇게$B$B 한다면 당신은 쿨 티라스의 친구임을 증명하게 될 것입니다."},objectives={{116,109115598},"습지대에 있는 드래곤마우 오크에게서 드래곤마우 머리 20개를 얻어 불모의 땅 앵커즈 엣지에 있는 알버롤드 중위에게 가져다주세요."},progress={{155,858457416},"내게 그런 힘이 있다면, 저 민족 전체를 말뚝에 못 박아 불에 태워 죽이고 싶다. 내 민족이 불타 죽었던 것처럼. 내 아버지가 돌아가셨던 것처럼."},completion={"The souls of our honored dead sing of your name, $c.$B$BBut there shall be no peace for me, not until all of Lord Daelin's murderers are dead and their accursed nations gone with them.","우리의 영광스러운 죽은 자들의 영혼이 당신의 이름을 노래합니다,$c$B$B하지만 내게는 평화가 없을 것입니다. 다엘린 경을 죽인 자들이 모두 죽고 그들의 저주받은 나라가 그들과 함께 사라질 때까지는 말입니다."}}
rows[40794]={title={{17,2074238810},"전쟁의 저울"},description={{609,758306714},"다엘린 경께서 우리를 이 빛에 버려진 해안으로 데려온 지 벌써 삼 년이라는 힘든 시간이 흘렀습니다. 우리 원정 함대는 오크와 그들의 비참한 동맹군을 상대로 충분히 시험받았고, 저는 부재 중에 필요한 자원을 거의 구할 수 없었습니다. 이 $B$B전쟁에서 승리하거나, 적어도 우리가 가장 증오하는 적에 맞서 서쪽 방어선을 확보하려면 저 혼자서는 싸울 수 없습니다.$B$B 렌호프 부제독은 제 오랜 친구이며, 쿨 티라스에서 막강한 영향력을 행사하고 $B$B있습니다. 스톰윈드에서 그를 찾아 이 편지를 전하여 우리의 사정을 알리고, 우리의 모든 희생이 헛되지 않도록 해주시길 부탁드립니다."},objectives={{107,1554357581},"봉인된 쿨 티란 서한을 스톰윈드 항구에 있는 쿨 티란 대사관의 렌호프 부제독에게 가져가십시오."},progress={{27,1161756121},"무슨 일이죠? 도와드릴까요?"},completion={"Alverold lives?! Tides be thanked!$B$BWith the fall of Lord Daelin, we thought the western cause lost. Indeed, many in Kul Tiras have elected to divert our attention north.$B$BIt will not be easy to persuade them to support the Kalimdor Expedition again; it is far more likely that they will demand Alverold's return for his assistance in the northern realms instead.$B$BStill, I will do what I can and send word to Alverold once I have news.$B$BYou have Kul Tiras' gratitude, $N.","알베롤드가 살아있다니?! 정말 다행입니다!$B$B대엘린 경이 쓰러지면서 우리는 서부의 대의가 좌절되었다고 생각했습니다. 실제로 쿨 티라스의 많은 이들이 우리의 관심을 북쪽으로 돌렸습니다.$B$B그들이 다시 칼림도르 원정대를 지원하도록 설득하는 것은 쉽지 않을 것입니다. 오히려 그들은 북부 왕국에서의 알베롤드의 도움에 대한 대가로 그의 복귀를 요구할 가능성이 훨씬 더 큽니다.$B$B하지만 저는 할 수 있는 모든 것을 다 할 것이며, 소식이 들어오는 대로 알베롤드에게 전하겠습니다.$B$B쿨 티라스의 감사를 전합니다.$N"}}
rows[40795]={title={{28,1277836203},"태양에 대한 지식을 찾아서"},description={{492,128865690},"자네를 보니 훈련이 많이 필요해 보이군. 마법사인 내가 자네의 훈련이 어떻게 진행될지는 말할 수 없지만, 분명히 자네에게는 지도가$B$B 필요하겠네. 태양의 요새로 가거라. 인간 도시에서 자랐다면, 바다 위에 떠 있는 마법 요새를 떠올릴 수 있을 테니 찾기 $B$B어렵지 않을 거야. 어쨌든 요새에 올라가서 왼쪽으로 돌면 대사제를 만나게 될 테지. 대사제가 자네에게 더 자세한 설명과 필요한 지도를 해 줄 거야. 자, 이제 내 일로 돌아가 보겠네, 그렇지?"},objectives={{64,881141538},"태양의 요새에 있는 대사제 라에모란 아나르벨로레를 방문하세요."},completion={{463,1971288004},"알라탈라스의 입문자가 된 것을 환영합니다. 우리 교단의 다른 이들이 이곳에 온 것을 보니 정말 기쁩니다.$B$B물론 필요한 모든 훈련을 제공해 드리겠지만, 제가 전수할 수 없는 훈련도 있습니다. 제 옆에 있는 샤날라 선소로우에게 말을 걸어보세요. 그녀는 실버문 대사원의 성서 사본을 가지고 있습니다.$B$B그 성서는 우리 교단의 비밀 의식을 배우는 데 매우 중요하니 꼭 한 부 구해 두세요. 평안히 가시오, 친구여. 태양이 당신을 인도하길!"}}
rows[40796]={title={{19,789319724},"숨겨져 있지만 사라지지 않았습니다"},description={"There are many things that can hurt me. After seeing so many years pass by, believe me when I say, physical pain is among the least of them.$B$BI assume you are not unfamiliar with the problems we have in Ashenvale, $c? Between the Horde and the Sayaads, the tranquillity of the forest is fast becoming just a memory. But we have persisted - and will persist - through this challenge and countless more, mark my words.$B$BThe disgusting demons that have an uncanny resemblance to us are the worst affronts to nature. They hide away in their hovels, plotting corruption and torturing us all. I want you to head to each one of their nooks and crannies, and do your fair share in thinning them out. Bring me a collection of their gnarled and twisted horns, and the Kaldorei will know of your bravery.","저를 해칠 수 있는 것은 많습니다. 오랜 세월을 살아오면서, 육체적인 고통은 그중에서도 가장 작은 것에 불과하다는 것을 $B$B깨달았습니다. 잿빛 골짜기의 문제점을 모르시는 건 아니겠죠? 호드와 $c사야드 때문에 숲의 평온함은 이제 추억 속으로 ​​사라져 가고 있습니다. 하지만 우리는 이 시련과 앞으로 닥칠 수많은 시련을 헤쳐나왔고, 앞으로도 헤쳐나갈 것입니다. 제 말을 $B$B명심하십시오. 우리와 소름 끼치도록 닮은 역겨운 악마들은 자연에 대한 최악의 모독입니다. 그들은 오두막에 숨어들어 타락을 꾀하고 우리 모두를 고문하고 있습니다. 당신은 그들의 은신처 구석구석을 샅샅이 뒤져 악마들을 소탕하는 데 일조해야 합니다. 그들의 뒤틀리고 옹이진 뿔을 모아오면 칼도레이가 당신의 용맹함을 알게 될 것입니다."},objectives={{45,92851250},"사티로스 진영 각각에서 뿔 6개씩을 모으세요."},progress={{87,609050989},"땅에 생긴 병충해는 쉽게 감출 수 있지만, 고치기는 어렵습니다. 이 점을 명심하십시오."},completion={{162,668313322},"훌륭하군. 전투 중에 부상은 없으셨길 바라. 당신은 단 한 번의 전투에서 저 철없는 경비병들이 부임한 이후로 한 것보다 더 많은 도움을 주셨어."}}
rows[40797]={title={{13,2122770208},"끔찍한 형상"},description={{279,1609985790},"푸르볼그 조각상은 날카로운 가시와 금속 파편으로 뒤덮여 있다. 얼굴, 목, 몸통 곳곳에 박혀 있다. 그럼에도 불구하고, 이 조각상은 어쩐지 어린아이 같은 모습을 하고 있다. 이것은 누군가의 장난감이었을까? 사티로스는 이것으로 무엇을 하고 있었던 것일까?"},objectives={{31,1520282786},"인형을 주인에게 돌려주세요."},progress={{52,1178273440},"<푸르볼그는 당신이 다가오자 호기심 어린 눈으로 당신을 바라봅니다.>"},completion={{641,142561915},"<그는 귀를 쫑긋 세우고는 인형을 낚아채 간다. 몇 초간 침묵을 지키다가 조용히 야옹거린다.>$B$B이건 내가 아주 어렸을 때 부모님께서 주신 거야. 우리는 이 인형이 우리를 항상 지켜주길 기도하며 축복을 빌지. 이건 정말 소중한 거야. 평생 하나밖에 없거든. 내가 숲의 노래에 피난처를 찾으러 왔을 때, 뭔가가 이 인형을 낚아채 가는 걸 느꼈어. 제대로 보지도 못했는데 말이야! 그들이 왜 그랬는지, 무슨 짓을 했는지 전혀 모르겠어. 때로는 묻지 않는 게 나을 때도 있지.$B$B<가시를 뽑아내며 인형을 가슴에 꼭 안고 고개를 끄덕인다.>$B$B이게 내게 얼마나 소중한지 넌 모를 거야. 난 가진 게 별로 없지만, 이걸 위해서라면 모든 걸 다 줄 수도 있었어. 그러니 제발, 가져가... 가져가."}}
rows[40798]={title={{19,706502696},"훈련용 간식"},description={"Greetings, $c. Were you sent by my sister? My brother? No? Who might you be, then?$B$B$N, is it? Allow me to introduce myself: I am Alleana Moonfeather youngest of the Moonfeather family. My siblings already wear the mantle of Hippogryph Master, but I am finding it difficult to focus on my training since my mentor...$B$BNevertheless, I must press on, for my family's reputation and in my mentor's memory! Without proper guidance, however, it is quite difficult to gauge my methods. We raise fledgling hippogryphs from a young age, so they bond to us and rely wholly upon our guidance.$B$BMake no mistake, these children belong to nature first and foremost, but the Kaldorei share a bond with nature that allows us to commune with these younglings effectively. Yet these fledglings seem indifferent towards me. Perhaps it is their diet.$B$BIt would be of great help if you could gather some food from the creatures in Darkshore and Ashenvale for me.","안녕하세요,$c 님. 제 누나나 형이 보내셨나요? 아니라고요? 그럼 누구시죠?$B$B$N님, 맞으시죠? 제 소개를 하겠습니다. 저는 문페더 가문의 막내, 알레아나 문페더입니다. 제 형제자매들은 이미 히포그리프 마스터의 칭호를 받았지만, 스승님께서 돌아가신 후로 수련에 집중하기가 어렵습니다…하지만 가문의 명예와$B$B 스승님의 기억을 위해서라도 계속 나아가야 합니다! 그러나 제대로 된 지도가 없으니 제 방법을 가늠하기가 참 어렵습니다. 저희는 어린 히포그리프들을 어릴 때부터 키우기 때문에, 그들은 저희에게 애착을 갖고 저희의 지도에 전적으로 의지합니다.오해하지$B$B 마세요. 이 아이들은 무엇보다도 자연의 일부이지만, 칼도레이는 자연과 특별한 유대감을 가지고 있어 이 어린 히포그리프들과 효과적으로 소통할 수 있습니다. 그런데 이 어린 히포그리프들은 저에게 무관심한 것 같습니다. 아마 식단 때문일$B$B 거예요. 다크쇼어와 애쉬엔베일에 있는 생물들에게서 먹을 것을 좀 모아주시면 정말 큰 도움이 될 거예요."},objectives={{132,120028318},"숲의 노래에 있는 알레아나 문페더에게 크롤러 골수 5덩어리, 천국 복숭아 5개, 곰 내장 5개, 거대 방랑자 날개 5개를 가져다 주세요."},progress={{51,1911803414},"다시 오신 걸 환영합니다. 히포그리프 먹이는 가져오셨나요?"},completion={"Thank you kindly for your efforts, $N.$B$BDid you carry all of these in your backpack? The smell must be... Nevermind.","$N,$B,$B님, 수고해주셔서 정말 감사합니다. 이 모든 걸 배낭에 넣고 다니셨나요? 냄새가… 됐습니다."}}
rows[40799]={title={{15,1033303655},"지혜로운 말씀"},description={"They still aren't responding to me! How is it my siblings make it look so simple? How very infuriating!$B$B<Her ears prick and she bares her fangs when she fails to summon one of the fledglings to her side.>$B$BMy Shan'do would tell me to set aside my pride, I'm sure of it. His was always the way of patience. I implore you, $N, seek out Hippogryph Masters and request their counsel on these willful children. Spare no detail of my struggles, as much as it pains me to admit that I am in need of their aid.$B$BWait! Do not speak to Caylais or Fyldren! I cannot accept what could only be seen as preferential treatment.$B$BI would urge you to travel to Rut'theran Village and Astranaar, and I believe I received correspondence from Nijel's Point once, wherever that may be. Teloren on Stonetalon Peak I am certain would help me in this, but be mindful of his... tendency to ramble.","아직도 내 말에 응답이 없잖아! 내 형제자매들은 어떻게 그렇게 쉽게 해내는 거지? 정말 화가 나!$B$B (그녀는 새끼들을 불러들이는 데 실패하자 귀를 쫑긋 세우고 송곳니를 드러냈다.) 내 샨도는 $B$B분명 내게 자존심을 버리라고 했을 거야. 그의 방식은 언제나 인내였으니까. 부디, 히포그리프 마스터들을 찾아가 $N이 고집 센 아이들에 대한 조언을 구해주세요. 내가 겪는 모든 어려움을 숨김없이 전해주세요. 그들의 도움이 필요하다는 걸 인정하는 게 고통스럽지만 말입니다. 잠깐! $B$B케일라이스나 필드렌과는 이야기하지 마세요! 특혜로 비칠 수 있는 건 받아들일 수 없어요. 루트테란 마을과 $B$B아스트라나르에 가보시길 권합니다. 그리고 니젤 포인트에서 온 편지를 받은 적이 있는데, 어디인지는 잘 모르겠네요. 스톤탈론 봉우리에 있는 텔로렌이 분명 이 일에 도움을 줄 거라고 생각하지만, 그가 좀 장황하게 말하는 경향이 있으니 조심해야겠어."},objectives={{63,587374788},"칼도레이 히포그리프 마스터들을 찾아가 조언을 구하십시오."},progress={"I hope you come bearing word from the masters, $N.","$N님, 스승님들의 말씀을 가지고 오시기를 바랍니다."},completion={{175,1526446086},"<당신이 스승들의 조언을 전하는 동안 그녀는 조용히 생각에 잠겨 몇 분 동안 그 말씀을 곱씹습니다.>$B$B잠깐... 텔로렌이 뭐라고 했어??$B$B<그녀의 얼굴이 당황으로 붉어집니다.>"}}
rows[40800]={title={{15,2082961660},"가족 이름"},description={{805,1671501970},"맞아요, 저는 문페더 가문 사람이에요! 저에게는 특별한 재능이 있는데, 어떻게 활용해야 할지 배워야 할 뿐이죠. 샨도도 그렇게 말씀하셨고, 저는 $B$B그분의 유산을 기릴 거예요! 샤프탈론은 제가 해질녘 숲 속 공터를 거니는 모습을 본 적 있는 위풍당당한 히포그리프 족장이에요. 하지만 우리는 아직 만난 적이 없죠. 그렇게 위엄 있는 생물은 분명 엘룬의 총애를 받는 존재일 거예요. 부디, 갓 부화한 새끼 중 가장 어린 아이를 데리고 여기서 남서쪽으로 가세요. 최대한 호드를 피하고 목숨을$B$B 걸고 아이를 지켜주세요. 오크들의 흉물스러운 야영지 남쪽에는 우리 자매들이 나무 위에서 침략자들을 매복 공격하며 경계를 서고 있는 아름다운 숲 속 공터가 있을 거예요. 샤프탈론이 그 근처 잿빛 골짜기 방어를 돕고 있다는 소문이 $B$B있어요. 아이를 그에게 데려다주고 문페더 가문의 이름을 전해주세요. 부디 그의 호의적인 반응을 기대할게요."},objectives={{93,2092701681},"애쉬엔베일 숲에서 샤프탈론을 찾아 교감한 후, 알레아나 문페더에게 돌아가십시오."},progress={"Hello, $n. Did you find Sharptalon?","안녕하세요,$n님. 샤프탈론을 찾으셨나요?"},completion={"He bowed his head? By Elune, that is amazing news! I understand. I shall spend more time with the fledglings in Sharptalon's presence, and with hard work and some fortune, I will make my family proud. The Moonfeathers will have yet another Hippogryph Master in their lineage!$B$BIt seems this little one doesn't want to leave your side. I suppose if you promise to care for and look after this child, there should be no issue in allowing it to follow you, right?$B$BThis is the least I can offer after everything you have done on my behalf. Elune smiles upon us both this day, $N.","그가 고개를 숙였다고요? 엘룬이시여, 정말 놀라운 소식이군요! 알겠습니다. 샤프탈론 앞에서 어린 히포그리프들과 더 많은 시간을 보내겠습니다. 열심히 노력하고 약간의 운도 따라준다면, 우리 가문에 자랑스러운 히포그리프를 선사할 수 있을 겁니다. 달깃털 가문에 또 한 명의 히포그리프 마스터가 탄생할 것입니다!$B$B이 꼬맹이가 당신 곁을 떠나고 싶어하지 않는 것 같군요. 이 아이를 돌봐주겠다고 약속하신다면, 따라가는 데 아무 문제 없겠죠?$B$B당신이 저를 위해 해주신 모든 일에 대한 보답으로 이 정도는 해드릴 수 있습니다. 오늘 엘룬께서 우리 둘에게 미소 지어주시길 바랍니다.$N"}}
rows[40801]={title={{19,452973252},"인내가 핵심이다"},description={"You may see ruins around here, $c, but what I see is far different. I see a reminder of a lost civilization, a Kaldorei race that was strong, ordered, unified, unparalleled in might. And now, just across the hills, I see the horde invading our sacred lands.$B$BBut that is not what has happened. Instead we bicker with the sentinels while the horde spreads like a disease, ravaging parts of our ancient homelands. Sentinels throwing young lives away like they were meaningless. If Fandral was here, he would have those upstarts whipped into line in a moment.$B$BAnyway, what brings you to Forest Song? Are you here to help?","이 주변에 폐허가 보일지도 $c모르지만, 내가 보는 건 전혀 다릅니다. 잃어버린 문명, 강하고 질서정연하며 단결되어 비할 데 없는 위력을 자랑했던 칼도레이 종족의 흔적이 보입니다. 그런데 지금, 저 언덕 너머로 무리가 우리의 신성한 땅을 침략하고 $B$B있습니다. 하지만 현실은 그렇지 않습니다. 무리가 전염병처럼 퍼져나가 우리 고대 고향 곳곳을 파괴하는 동안 우리는 파수꾼들과 티격태격하고 있습니다. 파수꾼들은 어린 생명들을 하찮게 여기며 내팽개치고 있습니다. 판드랄이 여기 있었다면, 그 건방진 놈들을 순식간에 혼쭐냈을 텐데 말입니다. 그런데$B$B 무슨 일로 포레스트 송에 오셨습니까? 도와주러 오셨나요?"},objectives={{175,321110530},"아이언글레이드 형제와 스타윈드 사령관의 말을 들어보십시오. 최선의 행동 방침을 선택하십시오. 어느 한쪽 편을 들면 다른 쪽이 당신에게 등을 돌릴 가능성이 높습니다."},progress={{65,972225201},"그럼 당신도 경비병들처럼 도움이 안 될 거라는 말인가요?"},completion={"Impressive to see one with an ounce of sensibility around here. Thank you, $n.","이곳에서 조금이라도 분별력 있는 사람을 보니 정말 인상적이네요. 감사합니다,$n님."}}
rows[40802]={title={{12,1301681682},"아웃라이더"},description={"Very well $n, let us break this deadlock immediately. From this moment forwards, the Horde will be our prey! The first thing to do with a prey animal is to isolate it from the rest. Make it blind, deaf and dumb. We need to disrupt the communications of the invaders from the rest.$B$BThere is an outrider who diligently passes messages from the lumber camp to their outposts, and likely beyond into the dusty deserts they call home. Lay an ambush, $n. Lie in wait by the road just south of here, north of the lumber camp. And when she passes by, strike her down. Show no mercy, for none will be shown to you.","좋아, .$n 이 교착 상태를 당장 타파하자. 지금 이 순간부터 호드는 우리의 사냥감이 될 것이다! 사냥감을 잡을 때는 먼저 무리와 격리시키는 게 상책이다. 눈멀게 하고, 귀먹게 하고, 말 못하게 해야 한다. 침략자들의 통신망을 끊어야 한다.$B$B 벌목장에서 적의 전초기지, 그리고 아마도 그들의 은신처인 먼지투성이 사막까지 부지런히 전령을 보내는 기수가 있다. , 매복하라. 여기에서 $n남쪽으로, 벌목장 북쪽의 길가에 숨어 기다리다. 그녀가 지나갈 때, 바로 공격하라. 자비를 베풀지 마라. 너에게도 자비는 없을 테니까."},objectives={{92,1120041640},"브롤탄 철창의 숲 노래 남쪽 길을 순찰하는 전쟁노래 기병을 처치하십시오."},progress={{49,1181792360},"지금까지 사냥은 어떻게 진행되었나요? 보고할 만한 사항이 있나요?"},completion={{107,1834260770},"잘했어요. 당신은 이미 경비병들보다 훨씬 유용하다는 것을 증명했군요. 물론, 그 기준이 그리 높지는 않았지만요."}}
rows[40803]={title={{17,987332717},"필살의 일격"},description={{736,1993149594},"이 갈등을 결정적인 한 방으로 끝낼 때가 왔습니다. 아니, 사실 두 방이죠. 당신이 없는 동안, 그리고 파수꾼들이 영웅 행세를 하는 동안 제가 직접 조사를 좀 해봤습니다. 이 작전의 우두머리는 두 명인데, 이 숲에 다시 평화를 가져오려면 둘 다 쓰러뜨려 처형해야 합니다. 당신은 그들의 지휘관인 그루샤크라는 야만적인 오크를 캠프 남쪽 어딘가에서 찾아야 합니다. 그리고 요새 안에서는 그리메이라는 주술사가 음모를 꾸미고$B$B 있습니다. 이 목표물들을 암살하는 데 동료가 필요하다면, 저는 전혀 탓하지 않을 겁니다. 오히려 아주 현명한 선택이라고 생각합니다. 실패할 때마다 우리의 삶은 훨씬 더 힘들어질 테니까요."},objectives={{94,1689032128},"애쉬엔베일의 포레스트 송에서 브롤탄 아이언글레이드를 위해 사령관 그루샤크와 예언자 그리메이를 처치하십시오."},progress={"I pray you return with good news, $n?","$n님, 좋은 소식을 가지고 돌아오시길 바랍니다."},completion={"I knew I could count on you, from the moment we began to talk. Truly you have earned Elune's favor this day, and I will make sure the word is spread of your deeds. My thanks, $n.","처음 대화를 시작했을 때부터 당신을 믿을 수 있다는 걸 알았습니다. 오늘 당신은 진정으로 엘룬의 은총을 입으셨고, 당신의 훌륭한 업적을 널리 알리도록 하겠습니다. 감사합니다,$n."}}
rows[40804]={title={{22,1302487190},"승리, 그것이 바로 승리다"},description={"Your task for helping Forest Song and ending this stalemate is at an end. However, I cannot think of anyone more appropriate to send word to Fandral Staghelm than you, $n. You did a significant portion of the work, and you deserve that portion of the praise too.$B$BGo, now. The path to Teldrassil is a long, albeit beautiful, one. Take the time for some rest and relaxation, perhaps, enjoy the verdant canopies of our ancient oaks. Once you board the ship and make it to Teldrassil, you will find the Arch Druid in the Cenarion Enclave of our beautiful capital. Here, this report should explain what transpired. Give it to him, but be a bit wary of his temper.","포레스트 송을 돕고 이 교착 상태를 해결하는 당신의 임무는 끝났습니다. 하지만 판드랄 스태그헬름에게 소식을 전할 사람으로 당신보다 더 적합한 사람은 없다고$n 생각합니다, . 당신은 상당한 일을 해냈고, 그에 걸맞은 칭찬을 받을 자격이 있습니다.$B$B자, 이제 가십시오. 텔드라실로 가는 길은 길지만 아름답습니다. 잠시 쉬면서 고대 참나무의 푸른 잎사귀를 감상하는 것도 좋겠습니다. 배에 올라 텔드라실에 도착하면 아름다운 수도의 세나리온 자치령에서 대드루이드를 만날 수 있을 겁니다. 이 보고서가 무슨 일이 있었는지 설명해 줄 것입니다. 그에게 보고서를 전하십시오. 하지만 그의 성격을 조심하는 것이 좋습니다."},objectives={{79,884928222},"봉인된 숲의 노래 보고서를 다르나서스에 있는 대드루이드 판드랄 스태그헬름에게 가져가십시오."},progress={{143,1821638108},"빨리 말씀해 주십시오. 저는 이미 많은 짐을 지고 있습니다. 만약 당신이 거기에 더 보태려 한다면, 적어도 그렇게 하고 빨리 떠나 주십시오."},completion={{121,595098699},"아, 남부 애쉬엔베일의 골칫거리가 드디어 끝났군. 브롤탄 아이언글레이드가 뭘 이뤄냈는지 한번 볼까."}}
rows[40805]={title={{23,1480056662},"리더십의 대가"},description={"After reading this report, it is clear that the sentinel presence has been less than helpful in Forest Song. Not only have they refused to follow the tactical plans suggested by Brolthan, but the display of bravado has led to the death of many sisters and daughters. To lose the blood of kin is a pain I know all too well.$B$BI know not if this was a simple mistake on Commander Starwind's part, or if it was deliberate misconduct, but regardless, her actions demand consequences. One less supporter of this new way of living in a leadership position, spread by that fool Tyrande and her ilk, will only solidify the Kaldorei as a traditional and united force. I will make the changes to the records, while you bring my notice to the commander. Inform Ironglade to present you with a suitable reward, too.$B$BI do not care if you think me heavy-handed or cruel, $c. Hopefully, this situation will teach you something about viewing the greater picture.","이 보고서를 읽어보니, 포레스트 송에서 파수꾼들의 존재가 전혀 도움이 되지 않았다는 것이 분명해졌습니다. 그들은 브롤탄이 제안한 전술 계획을 따르기를 거부했을 뿐만 아니라, 허세를 부리다가 많은 자매와 딸들의 죽음을 초래했습니다. 혈육을 잃는 고통은 저 또한 너무나 잘 알고 있습니다.$B$B 스타윈드 사령관의 행동이 단순한 실수였는지, 아니면 고의적인 잘못이었는지는 모르겠지만, 어쨌든 그녀의 행동에는 대가가 따릅니다. 그 어리석은 티란데와 그 무리들이 퍼뜨린 새로운 삶의 방식을 지지하는 지도자가 한 명이라도 줄어든다면, 칼도레이는 더욱 전통적이고 단결된 세력으로 굳어질 것입니다. 제가 기록을 수정하는 동안, 당신은 제 보고를 사령관에게 전달하십시오. 아이언글레이드에도 적절한 보상을 준비하라고 전하십시오. $B$B제가 너무 과격하거나 잔인하다고 생각하든 말든 $c상관없습니다. 이번 일을 통해 더 큰 그림을 보는 법을 배우게 되기를 바랍니다."},objectives={{60,366291532},"포레스트 송에 있는 스타윈드 사령관에게 판드랄의 편지를 가져다 주세요."},progress={"Ah, $n! I hear we have you to thank for bringing this conflict to an end!","아,$n님! 이 분쟁을 종식시킨 건 당신 덕분이라고 들었습니다!"},completion={{124,230846390},"우리 둘 다 언젠가는 쉬면서 명상을 해야 할 거예요. 저는 정말… 이게 뭐죠? 대드루이드께서 보내신 편지인가요?"}}
rows[40806]={title={{15,592198079},"칼도레이 유물"},description={"<Her silver eyes grow wide, while her skin grows red. She grinds her teeth together and throws the letter to the floor.>$B$BSo that is the Elune-damned thanks I get after all this time? To take the fall for that belligerent, conniving druid? Oh, I will tell my sisters we will leave this place alright, don't expect to see us here again. And don't think I won't take this up with Lady Whisperwind either, she must smell foul play in the air. Now, get out of my sight, $n. You've done enough around here.","그녀의 은빛 눈이 커지고 얼굴은 붉어졌다. 그녀는 이를 악물고 편지를 바닥에 던졌다. \"이게 엘룬 신이 내린 보상인가?$B$B 이토록 오랜 시간 끝에 받는 고작 이 정도라니? 그 호전적이고 교활한 드루이드 때문에 내가 책임을 져야 하다니? 내 자매들에게 우리가 이곳을 떠날 거라고 전해둬. 다시는 여기서 우리를 볼 생각 하지 마. 그리고 위스퍼윈드 여신께도 이 일을 따져 물을 거야. 분명 뭔가 수상한 낌새를 눈치채셨을 테니까. 자, 이제 내 눈앞에서 사라져, .$n 여기서 할 짓은 이제 충분해.\""},objectives={{42,398550501},"보상을 받으려면 브롤탄 철창으로 돌아가십시오."},progress={{64,1443090129},"보상을 받으러 돌아오신 거죠? 네, 그럴 줄 알았습니다."},completion={{72,1257648136},"여기, 저희의 노고에 대한 감사의 표시로 이것 중 하나를 받아가세요."}}
rows[40807]={title={{19,394059047},"압력이 핵심이다"},description={{714,76246962},"이 지역에 낯선 얼굴이로군, 이쉬누-알라. 내 이름은 스타윈드 사령관이다. 평소 같으면 어딘가 순찰을 돌거나 자매 파수꾼들과 훈련을 하고 있었겠지만… 불행히도 지금은 고집불통에 비겁한 드루이드 아이언글레이드를 설득하느라 여기 갇혀 있다. 우리 코앞에서 벌어지고 있는 전쟁에 그를 도와달라고 애쓰고 있군. 그런 대화를 해야 한다는 게 믿기지 않을 정도야! 호드는 우리의 고대 나무들을 베어 엘룬의 아름다움을 더럽히고 있어. 당연히 우리 중 많은 이들이 이미 전투에 휘말려 있고, 누군가, 혹은 무언가가 이 교착 상태를 깨뜨려야 해. 안타깝게도 우리는 시간마다 목숨을 잃고 있어. 혹시 그를 $B$B설득해 줄 수 있을까? 아니면, 능력이 된다면 우리와 함께 전쟁에 참여해 줄 수 있을까? 그렇게 해준다면 분명 큰 보상을 받을 수 있을 거야."},objectives={{174,1737586554},"스타윈드 사령관과 브롤탄 형제의 말을 들어보십시오. 최선의 행동 방침을 선택하십시오. 어느 한쪽 편을 들면 다른 쪽이 당신에게 등을 돌릴 가능성이 높습니다."},progress={{35,1844096221},"그래서요? 흐름을 바꾸는 데 관심 있으세요?"},completion={"Now that's what I like to hear! Grab your weaponry, $n.","바로 그거야! 무기를 챙겨,$n."}}
rows[40808]={title={{24,883653592},"전장의 혼란"},description={"Listen closely, $n. You will not be fighting alone out there, so show some spirit when you do. And do not dare return until you are crimson with their blood. I do not care if they are common laborers or peons, guards or shamans. Kill them indiscriminately. Bring havoc to the battlefield. Each Kaldorei death will be repaid tenfold, mark my words.$B$BWe will remember your name if you return from this alive, and if you fight with honor, $n. If not, then may Elune cast her gaze upon your body. Tor ilisar'thera'nal!","잘 들어라, .$n 너는 저기서 혼자 싸우지 않을 것이다. 그러니 용기를 내어 싸워라. 그리고 그들의 피로 온몸이 붉게 물들기 전까지는 감히 돌아오지 마라. 그들이 평범한 노동자든, 하급 병사든, 경비병이든, 주술사든 상관없다. 무차별적으로 죽여라. 전장을 휩쓸어라. 칼도레이의 죽음 하나하나는 열 배로 갚아질 것이다. 내 말을 $B$B명심하라. , 네가 살아 돌아오고 명예롭게 싸운다면 우리는 네 이름을 기억할 것이다.$n 그렇지 않다면, 엘룬이 네 시신을 꿰뚫어 보기를. 토르 일리사르테라날!"},objectives={{115,1229816562},"애쉬엔베일의 포레스트 송에 있는 스타윈드 사령관을 위해 워송 벌목 캠프 주변의 침략자 무리와 전쟁을 벌이세요."},progress={{19,1259475000},"벌써 돌아오셨군요?"},completion={{72,689556521},"너한테서는 피, 땀, 흙 냄새가 진동하네. 걔네들을 쫓아냈어?"}}
rows[40809]={title={{16,229863365},"최후의 일격"},description={"The enemies are reeling, their compatriots' blood in their eyes and their death-rattles in their ears. Do not let up the pressure now, $c. Seek the brutish Commander Grushak south of the keep, possibly watching from one of their towers. He should be separated from the bulk of the forces. And find the venomous Farseer Grimeye in the keep, plotting away his next move.$B$BI will leave it to you, if you grant them a warrior's swift death, or a slow and painful one. As long as they are dead and gone, Elune will smile upon whichever choice you make.","적들은 동족의 피가 눈에 고이고 죽음의 신음 소리가 귓가에 맴도는 가운데 휘청거리고 있습니다. 지금 압박을 늦추지 마십시오, . 요새 남쪽에서$c 잔혹한 사령관 그루샤크를 찾으십시오. 아마도 망루 중 하나에서 지켜보고 있을 겁니다. 그는 주력 부대와 떨어져 있을 것입니다. 그리고 요새 안에서는 독기 어린 예언자 그리메이를 찾아내십시오. 그는 다음 계획을 꾸미고 있을 겁니다. I는 $B$B당신이 그들에게 전사의 빠른 죽음을 선사할지, 아니면 느리고 고통스러운 죽음을 선사할지 선택하도록 맡길 것입니다. 그들이 죽기만 한다면, 엘룬은 당신의 어떤 선택이든 기뻐할 것입니다."},objectives={{94,1247737590},"애쉬엔베일의 포레스트 송에서 사령관 스타윈드를 위해 사령관 그루샤크와 파시어 그리메이를 처치하십시오."},progress={{64,1916729065},"끝났습니까? 남쪽 숲은 드디어 호드로부터 해방되었습니까?"},completion={"<She bares her teeth and gives a wide grin.>$B$BFantastic. The sentinels shall be recalled, finally, and we shall celebrate tonight. Elun'adore, $n!","<그녀는 이를 드러내고 활짝 웃었다.>$B$B환상적이야. 드디어 파수꾼들을 소환할 수 있겠군. 오늘 밤 우리는 축하 파티를 열자. 엘루나도르,$n!"}}
rows[40810]={title={{21,1350425465},"승리 소식을 전"},description={{740,47268083},"우리가 한 일 덕분에 이곳에서는 문베리 코디얼과 술이 마음껏 흘러넘치고 있습니다. 적어도 우리 중에서는 겁쟁이 아이언글레이드는 얼굴조차 드러내지 않죠. 진정한 땅의 수호자들이 당당히 서 있는 동안 자기가 그저 방관만 했다는 걸 알고 있기 때문입니다. 감사 인사는 충분히 드렸지만, 이 이야기를 직접 듣고 싶어 하는 사람이 한 명 더 있는 것 같으니, 이 보고서를 다르나서스의 위스퍼윈드 여신께 전해 주십시오. 아마 달의 신전에서 다른 여사제들과 함께 계실 겁니다. 걱정 마세요. 당신에 대한 좋은 평가가 담겨 있으니, 여신께서 어떻게 하실지 잘 아실 겁니다. 아, $B$B그리고 이 보고서는 천천히 쓰셔도 괜찮습니다. 어차피 곧 갈 길이니까요. 오버딘에서 생선 요리도 드시고, 텔드라실까지 가는 배 여행도 즐기세요. 너무 취하지는 않도록 조심하시고요!"},objectives={{71,1121720664},"봉인된 숲의 노래 보고서를 다르나서스에 있는 티란데 위스퍼윈드에게 가져다 주세요."},progress={"Greetings, $c. What brings you to our Temple?","안녕하세요,$c님. 무슨 일로 저희 사원에 오셨나요?"},completion={{84,1660923866},"아, 그럼 우리 남쪽 숲이 드디어 호드로부터 해방된 건가? 정말 반가운 소식이군."}}
rows[40811]={title={{22,1683094657},"비겁함의 대가"},description={"You claim how many Horde kills to your name? Very impressive indeed, $n. There is one thing that concerns me, though, even during what should be a jubilant period. This Brolthan Ironglade, the one coordinating the druids in the area, the report states he refused to help at all? Cowardice it claims in here, but I worry there is something far worse than cowardice involved here.$B$BYou see, that druid is staunchly loyal to Arch Druid Fandral Staghelm. And we do not exactly see eye to eye. He would not have acted this way without some assurance or support from Darnassus, I imagine. Which means he knowingly endangered Kaldorei lives in order to, what, prove a political point?$B$BPlease, deliver this message to him. Frankly I think it is better than he deserves, but I will leave his fate to Elune to decide., And $n, do not forget to ask the commander for a reward afterwards!","당신이 호드 적을 몇 명이나 처치했다고 주장하는 겁니까? 정말 $n대단하군요, . 하지만 기뻐해야 할 이 시기에도 한 가지 걱정스러운 점이 있습니다. 이 지역 드루이드들을 지휘하는 브롤탄 아이언글레이드라는 자가 전혀 도움을 주지 않았다는 보고가 있더군요. 비겁함 때문이라고 하는데, 저는 그보다 훨씬 더 심각한 일이 관련되어 있을 거라고 생각합니다.아시다시피, 그 $B$B드루이드는 대드루이드 판드랄 스태그헬름에게 충성이 깊습니다. 그리고 우리는 사이가 좋지 않습니다. 다르나서스의 어떤 보장이나 지원 없이는 그가 이렇게 행동하지 않았을 거라고 생각합니다. 그렇다면 그는 정치적인 목적을 달성하기 위해 고의로 칼도레이의 목숨을 위험에 빠뜨린 겁니까?부디 이 $B$B전갈을 그에게 전해 주십시오. 솔직히 말해서 그가 받을 만한 벌은 아니라고 생각하지만, 그의 운명은 엘룬에게 맡기겠습니다. 그리고$n , 나중에 지휘관에게 보상을 요구하는 것도 잊지 마십시오!"},objectives={{74,1977598931},"잿빛 골짜기의 포레스트 송에 있는 브롤탄 아이언글레이드에게 티란데의 메시지를 전달하세요."},progress={"Ah, the hero of the hour. Speak quickly, $n, I rather wish to be left alone currently. The drunken singing of the sentinels is making it rather hard to meditate.","아, 오늘의 영웅이시군요.$n, 빨리 말씀해 주십시오. 지금은 혼자 있고 싶습니다. 경비병들의 술 취한 듯한 노래 소리 때문에 명상하기가 어렵네요."},completion={{48,2093072818},"티란데가 직접 나에게 보낸 메시지라고? 신기하네."}}
rows[40812]={title={{17,866822462},"칼도레이 무기"},description={{418,1912353371},"그래서, 그것이 대제사장의 판단이로군. 어이가 없군. 생명을 구하려는 내 마음은 비겁함으로, 사령관의 피에 대한 갈망은 영웅주의로 여겨지다니? 어쩌면 정말$B$B 내 젊은 시절의 산으로 돌아가야 할 때일지도 모르겠군. 매와 함께 날고, 물고기와 함께 헤엄치고, 늑대와 함께 사냥하겠지. 그러면 너희 경비병 친구들보다 훨씬 덜 위선적인 사람들을 만날 수 있을 테니까."},objectives={{42,282266185},"스타윈드 사령관에게 돌아가 보상을 받으세요."},progress={"$n! Drink?","$n! 마실래?"},completion={{199,1018251654},"그건... 좀 가혹하긴 하지만, 드루이드들에게 불공평한 건 아니죠. 어쨌든 그런 긴장감 때문에 그들이 결국엔 떠나게 됐을 거라고 생각해요. 그리고 수고에 대한 보상으로 새로 제작된 무기를 하나 고르셔도 좋습니다."}}
rows[40813]={title={{19,313242199},"조각 조화"},progress={{396,562534895},"돌아왔군, 그 파편들은 준비됐나?"},completion={{143,296844473},"훌륭한 작업입니다. 조화 과정은 특히 이렇게 연습을 많이 하면 오래 걸리지 않아요. 혹시 더 좋은 방법을 찾으시면 저에게 알려주세요."}}
rows[40814]={title={{28,433573223},"인챈티드 레더 컬렉션"},progress={{335,407812106},"$c님, 혹시 좋은 결과 있으셨나요?"},completion={{111,1078390207},"음, 모든 게 괜찮아 보이네요. 저희를 도와주셔서 정말 감사합니다. 자, 이거 받으세요."}}
rows[40815]={title={{28,1189079138},"인챈티드 토륨 컬렉션"},progress={{348,1655971978},"$c님, 혹시 좋은 결과 있으셨나요?"},completion={"I am sure our blacksmith will be eager to work with this new material, thanks again $c!","저희 대장장이가 이 새로운 재료로 작업하는 것을 매우 기대하고 있을 거라고 확신합니다.$c님, 다시 한번 감사드립니다!"}}
rows[40816]={title={{20,92950905},"문클로스 컬렉션"},progress={{344,1540098080},"$c님, 혹시 좋은 결과 있으셨나요?"},completion={"Mooncloth, so divine, and majestic. I can feel the grace of Elune radiating from it.$B$BThank you $c, take this as thanks for helping us.","달빛천, 너무나 신성하고 위엄 있네요. 엘룬의 은총이 느껴지는 것 같아요.$B$B감사합니다.$c도와주셔서 감사하는 마음으로 드리는 선물입니다."}}
rows[40817]={title={{21,619546517},"카라잔의 열쇠 I"},description={{856,1228383755},"산 자가? 여기에? 이런 날이 올 줄은 꿈에도 $B$B생각 못 했지. 저주받은 내 영혼은 영원히 이곳에 갇혀 진정한 죽음의 달콤한 해탈을 찾지 못하고 있다. 과거의 기억들이 여전히 나를 괴롭히고, 내 행동의 $B$B결과를 끊임없이 상기시킨다. 그런데 자네는 이 복도를 헤매고 다니며, 자네를 기다리는 공포를 알지 못하는군. 카라잔의 미스터리를 풀고 싶다면 잠시 머물며 내 이야기를 들어보게. 하지만 경고하건대, 이 벽 안에는 나조차 알지 못하는 더 어두운 비밀이$B$B 묻혀 있다. 메디브의 탑에 숨겨진 수수께끼를 파헤칠 의지가 있다면, 이 저주받은 장소의 진정한 목적이 드러날지도 모른다. 아니면 자네도 이전에 수많은 이들을 사로잡았던 광기에 휩쓸려 길을 잃게 될지도 모르지. 과거의 고통받는 유령처럼, 나처럼 이 벽 안에 영원히 갇힌 채…"},objectives={{38,590843203},"에본록 경의 이야기를 들어보세요."},progress={{77,96847781},"내 이야기가 자신의 이해력을 넘어선 권력을 추구하는 모든 이들에게 경각심을 일깨워주는 계기가 되기를 바랍니다."},completion={{831,316025943},"유령처럼 이 복도를 떠돌며 수년을 보낸 후, 저는 제 행동의 무게와 제게 닥친 결과들을 받아들이게 되었습니다. 저는 당신에게 용서나 사면을 구하지 않습니다. 그것은 당신이 줄 수 있는 것이 아니기 때문입니다.$B$B대신, 제가 당신에게 드러낸 것을 생각해 보시기 바랍니다. 제 이야기를 곱씹어 보고, 거기서 얻을 수 있는 교훈을 되새겨 보십시오. 어쩌면 당신 또한 과거에 권력이나 지식에 대한 갈망이 판단력을 흐리게 했을지도 모릅니다. 혹은 후회하고 만회하고 싶은 실수를 저질렀을지도 모릅니다.$B$B앞으로 어떻게 할지는 당신이 결정해야 합니다. 카라잔의 상층부로 가는 열쇠를 찾아 그 비밀을 밝혀낼 것입니까? 아니면 이 저주받은 곳을 떠나 다른 곳에서 새로운 운명을 개척할 것입니까? 당신 앞에 놓인 길은 오직 당신만이 결정할 수 있습니다."}}
rows[40818]={title={{22,1703698893},"카라잔의 열쇠 II"},description={{794,1153690823},"아, 카라잔의 금지된 지식을 추구하기로 결심했군. 그럴 만도 하지. 그런 힘과 비밀의 유혹은 아무리 고귀한 의도를 가진 사람이라도 거부할 수 없으니까. 아마도 이 지식을 세상의 더 큰 선을 위해 사용하고자 하는 바람에서일 테고, 그런 마음가짐이라면 칭찬받아 마땅하군.$B$B 하지만 진정으로 상층부의 비밀을 풀고 싶다면, 먼저 탑의 금지 구역 열쇠를 지키는 저주받은 불멸의 성주 모로에스를 찾아야 한다. 그는 교활하고 자신이 지키는 비밀을 맹렬하게 지키려 하니 쉬운 일은 아닐 것이다. 모로에스의 진짜 주인이 누구인지는 나 역시 모르니 조심해야 한다. 하지만$B$B 그의 방어를 뚫고 열쇠를 손에 넣을 수 있다면, 상층부에 들어가 그토록 갈망하던 지식을 발견할 수 있을 것이다."},objectives={{133,1287465449},"모로에스를 처치하고 상층부로 가는 열쇠를 되찾으세요. 모로에스는 하층 카라잔 홀에 있습니다. 열쇠를 에본록 경에게 가져다주세요."},progress={{34,298558205},"모로에스와 열쇠를 찾으셨나요?"},completion={{798,1233495131},"열쇠는 이제 부서져 쓸모없게 되었고, 그 마법의 정수는 시간 속에 사라져 현재 상태로는 더 이상 우리에게 아무런 도움이 되지 못한다. 메디브는 죽어서도 산 자들의 눈으로부터 자신의 비밀을 지키기 위한 마지막 계략을 숨기고 있는 듯하다.$B$B하지만 우리는 희망을 잃어서는 안 됩니다. 열쇠를 예전의 영광으로 되돌리고 상층부로 향하는 문을 열 방법이 분명히 있을 것입니다. 카라잔의 비밀이 영원히 사라지도록 내버려 둘 수는 없습니다. 분명히 열쇠를 되살리고 부서진 것을 고칠 지식과 능력을 가진 자가 있을 것입니다.$B$B더 많은 도움을 드릴 수 있었으면 좋겠지만, 이 임무에서 제가 할 수 있는 역할은 여기서 끝입니다. 부디 열쇠를 되찾는 여정이 성공적으로 마무리되어 카라잔의 비밀이 그것을 찾는 자들에게 밝혀지기를 바랍니다."}}
rows[40819]={title={{23,1993739447},"카라잔의 열쇠 III"},description={{501,2095197309},"당신이 메디브의 열쇠를 가지고 있다는 것을 감지했습니다. 어떻게 그 열쇠를 손에 넣었는지는 알 수 없지만, 경고하건대 모든 것이 겉보기와는 다르고, 상층부에 깃든 힘들은 당신이 이해할 $B$B수 있는 범위를 넘어섭니다. 메디브는 젊었을 때 키린 토의 마법사 반돌을 자주 탑에 머물게 했습니다. 만약 누군가 그 열쇠를 고칠 수 있다면,$B$B 바로 그일 것입니다. 서두르십시오. 상층부에서 불길한 소리가 들려오고 있으며, 그곳의 상황은 더욱 악화될까 두렵습니다."},objectives={{122,1977084707},"키린 토에 있는 사람 중에 반돌에 대해 아는 사람이 있는지 찾아보세요. 달라란이 검색을 시작하기에 좋은 장소일 수 있습니다."},progress={{4,273767400},"예?"},completion={{22,1416586116},"흠, 반돌이라고요?"}}
rows[40820]={title={{22,1703698906},"카라잔의 열쇠 IV"},description={{689,171179873},"네, 맞습니다. 대마법사 반돌은 키린 토에서 가장 뛰어난 지략가 중 한 분이셨죠. 믿기 어려우시겠지만, 그는 메디브의 절친한 친구였습니다. 물론 메디브에게는 진정한 친구가 없었다고 주장하는 사람들도$B$B 있겠지만요. 하지만 안타깝게도 제가 당신을 많이 도와드릴 수는 없을 것 같습니다. 아르키몬드가 달라란을 파괴한 후, 반돌은 큰 부상을 입으셨고, 그 후유증으로 오랜 기간 회복에 힘쓰시다가 결국 우리 시대 최고의 마법사 중 한 명으로 은퇴하셨습니다. 제가 기억하기로는$B$B 그가 테라모어 근처에 정착하고 싶어 했던 것 같습니다. 만약 아직 살아계시다면, 테라모어 시내에서 직접 찾아보시는 게 좋겠습니다. 우리 수습 마법사 할리스터가 그의 행방을 알고 있을지도 모릅니다."},objectives={{63,826967510},"테라모어에 있는 마구스 할리스터에게 반돌의 행방을 물어보세요."},progress={{62,1026830195},"테라모어에 오신 것을 환영합니다. 무엇을 도와드릴까요?"},completion={{33,1458802971},"반돌이요? 제가 기록을 확인해 보겠습니다."}}
rows[40821]={title={{21,619546530},"카라잔의 열쇠 V"},description={{738,1694018677},"마법사 할리스터는 두꺼운 책들을 꼼꼼히 훑어보며, 수십 년간의 연구와 경험이 묻어나는 강렬한 눈빛으로 모든 줄을 살폈다. 몇 분 동안 부지런히 책을 찾던 그는 마침내 씁쓸한 미소를 지으며 당신을 올려다보았다.$B$B \"아, 맞다. 반돌. 그는 약 4년 전에 테라모어에 왔었지. 제이나 부인을 뵈러 왔었거든. 하지만 오래 머물지는 않았어. 나이 든 자신에게는 너무 번잡하다고 $B$B생각했나 보군. 우리 기록에 따르면, 반돌은 방문 직후 작은 배를 샀대. 필수품과 식량, 심지어 씨앗까지 싣고 말이지. 남쪽으로 항해를 떠났어. 좀 더 조용한 삶을 찾아서 말이야. 그를 찾으려면 해안선을 따라가는 게 가장 좋을 거야.\""},objectives={{89,1024061393},"반돌을 찾아라. 그는 칼림도르 동쪽 해안, 테라모어 남쪽 어딘가에 살고 있다."},progress={{37,797867442},"무슨 일로 제 외딴 집에 오셨나요?"},completion={{623,1870843980},"당신이 저를 찾아왔고, 제 진짜 정체를 알고 있다는 것을 느낍니다. 제 과거가 마침내 저를 따라잡은 것 같군요. 솔직히 놀랍지는 않습니다.$B$B당신이 하려는 말의 심각성을 잠시 생각해 보십시오. 저는 승리와 비극으로 가득 찬 긴 인생을 살아왔습니다. 위대한 왕국의 몰락을 목격했고, 권력이라는 이름으로 사람들이 저지를 수 있는 잔혹 행위를 직접 보았습니다.$B$B만약 당신이 제 과거의 죄와 제가 저지른 수많은 실수에 대해 따지러 왔다면, 저는 저항하지 않겠습니다. 어떤 결과가 따르더라도 받아들이겠습니다."}}
rows[40822]={title={{23,1993739447},"카라잔의 열쇠 III"},description={{501,2095197309},"당신이 메디브의 열쇠를 가지고 있다는 것을 감지했습니다. 어떻게 그 열쇠를 손에 넣었는지는 알 수 없지만, 경고하건대 모든 것이 겉보기와는 다르고, 상층부에 깃든 힘들은 당신이 이해할 $B$B수 있는 범위를 넘어섭니다. 메디브는 젊었을 때 키린 토의 마법사 반돌을 자주 탑에 머물게 했습니다. 만약 누군가 그 열쇠를 고칠 수 있다면,$B$B 바로 그일 것입니다. 서두르십시오. 상층부에서 불길한 소리가 들려오고 있으며, 그곳의 상황은 더욱 악화될까 두렵습니다."},objectives={{120,262674067},"키린 토에서 반돌에 대해 아는 사람을 찾아보세요. 언더시티가 검색을 시작하기에 좋은 장소일 수 있습니다."},progress={{55,1170539186},"내 말을 끊는 데에는 아주 타당한 이유가 있어야 할 거야."},completion={{40,1922659872},"반돌을 찾으시는군요? 좋습니다."}}
rows[40823]={title={{22,1703698906},"카라잔의 열쇠 IV"},description={{733,1125665042},"반돌. $B$B그는 나보다 선배였고, 마지못해 인정하지만 나는 그에게서 마법과 그 규칙에 대해 많은 것을 배웠습니다. 사람들은 그가 메디브와 친했다고 하지만, 내 생각엔 그저 서로에게 이득이 되는 관계였을 뿐인 것 같습니다.$B$B 마지막으로 들은 소식으로는 반돌은 달라란 함락에서 간신히 살아남아 더스트왈로우의 외딴 늪지대로 은퇴했다고 합니다. 우리 오우거 \"동맹\"들이 그곳에 정착지를 세웠으니, 그를 찾으려면 그들과 상대해야 할 겁니다. <그는 몸을 더 가까이$B$B 기울이며 목소리를 낮고 위험한 속삭임으로 바꿉니다.> 하지만 $B$B반돌을 찾게 된다면, 그의 옛 동료가 안부를 전했다고 전해 주십시오. 그리고 실패한다면… 글쎄, 내 시간을 낭비하는 자들을 처리하는 방법은 내가 잘 알고 있다고만 해 두죠."},objectives={{67,830241759},"브래큰월 마을 사람에게 반돌이 어디 있는지 물어보세요."},progress={"Throm-ka. Is there anything I can help you with, $r?","트롬카.$r님, 제가 도와드릴 일이 있을까요?"},completion={{7,803250177},"반돌?"}}
rows[40824]={title={{21,619546530},"카라잔의 열쇠 V"},description={{813,387917555},"크로그는 낮고 우렁찬 웃음을 터뜨렸다. \"우리가 테라모어를 염탐하고 있다고 생각하는 건가? 하! 우리가 그런 약골들에게 시간을 낭비하겠어. 아니, 아니, 친구. 그저 우연히 그들의 장부를 손에 넣게 된 것뿐이야. 늪 어딘가에서 잃어버린 모양이지. 우리에겐 행운이지, 안 그래?\" 크로그는$B$B 장부를 펼쳐 들고 두껍고 초록색 손가락으로 페이지를 쓸어내렸다. $B$B\"어디 보자... 아, 그래. 반돌. 그는 약 4년 전에 배를 타고 왔다가 해안선을 따라 남쪽으로 향하는 작은 배를 타고 떠났어. 유감스럽게도 우리가 가진 정보는 이게 전부야.\" $B$B\"자, 만약 정말로 그를 찾고 싶다면 밀수업자에게서 배를 빌려 해안선을 따라 항해해 보는 것도 좋겠군. 하지만 조심해야 할 거야.\" 최근 복수심에 불타는 선원이 해안가를 공포에 떨게 하고 있다는 소문이 돌고 있습니다."},objectives={{89,1024061393},"반돌을 찾아라. 그는 칼림도르 동쪽 해안, 테라모어 남쪽 어딘가에 살고 있다."},progress={{37,797867442},"무슨 일로 제 외딴 집에 오셨나요?"},completion={{623,1870843980},"당신이 저를 찾아왔고, 제 진짜 정체를 알고 있다는 것을 느낍니다. 제 과거가 마침내 저를 따라잡은 것 같군요. 솔직히 놀랍지는 않습니다.$B$B당신이 하려는 말의 심각성을 잠시 생각해 보십시오. 저는 승리와 비극으로 가득 찬 긴 인생을 살아왔습니다. 위대한 왕국의 몰락을 목격했고, 권력이라는 이름으로 사람들이 저지를 수 있는 잔혹 행위를 직접 보았습니다.$B$B만약 당신이 제 과거의 죄와 제가 저지른 수많은 실수에 대해 따지러 온 것이라면, 저는 저항하지 않겠습니다. 어떤 결과가 따르더라도 받아들이겠습니다."}}
rows[40825]={title={{22,1703700596},"카라잔의 열쇠 VI"},description={{525,1127387269},"카라잔 상층부 열쇠를 수리해 달라고 제게 도움을 청하러 오셨군요. 메디브와의 과거 인연이 다시 한번 저를 괴롭히는 것 같지만, 어쩔 수 없는 대가겠죠. 메디브 자신도 자신이 하는 일의$B$B 위험성을 알고 있었지만, 지식과 권력에 대한 그의 끝없는 갈망이 그 결과를 간과하게 만들었습니다. 우리는 신중하게 진행해야 합니다. $B$B당신이 추구하는 힘이 감당하기엔 너무 클 수도 있다는 것을 알면서도, 앞으로 닥칠 위험에 맞설 준비가 되셨습니까? 잠시 머물면서 제 $B$B이야기를 들어보십시오."},objectives={{25,1169326837},"반돌의 이야기를 들어보세요."},progress={{59,844899901},"내가 경고했지만, 당신은 여전히 ​​결심을 굳힌 것 같군요."},completion={{879,1188618585},"생전에 메디브는 극도로 신중하고 편집증적인 인물로 알려져 있었으며, 자신의 방 열쇠는 오직 자신과 가장 신뢰하는 측근만이 접근할 수 있도록 철저히 관리했다. 심지어 그의 친구였던 나조차도 그의 방에 접근하는 것이 금지되어 있었다.$B$B하지만 아직 희망의 불씨가 남아 있을지도 모릅니다. 메디브의 흔적을 찾아낼 수 있다면, 그 흔적이 열쇠를 작동시킬 만큼 강력할 수도 있습니다. 뛰어난 마법 능력을 가진 자들은 종종 지맥에 흔적을 남겨, 그들이 사라진 후에도 오랫동안 영향을 미칠 수 있는 교란을 일으키곤 합니다.$B$B이러한 메아리는 그 인물의 이야기에 있어 매우 중요한 장소에 머무르는 경향이 있으므로, 우리는 메디브의 메아리로 이어질 만한 단서나 흔적을 찾기 위해 온 땅을 샅샅이 뒤져야 합니다. 쉬운 일은 아니겠지만, 카라잔의 방에 접근하고 우리 모두를 집어삼키려는 어둠의 세력을 막을 수 있는 유일한 희망입니다."}}
rows[40826]={title={{23,1993962540},"카라잔의 열쇠 VII"},description={{755,1097015036},"유감스럽게도 메디브의 메아리가 어디에 있는지에 대한 정보는 제한적입니다. 탐색을 시작하려면 메디브가 두 번째 삶에서 자주 방문했던 장소들을 찾아가 보세요. 그는 자신을 속죄하고 다가오는 제3차 전쟁을 준비하기 위해 돌아왔습니다. 이 사건들은 비교적 최근에 일어났기 때문에 메아리를 찾기가 더 쉽고 그 효능도$B$B 더 강할 것입니다. 메디브의 존재를 나타내는 메아리에는 그가 한때 소유했던 물건들이 함께 있을 가능성이 높습니다. 그의 망토에서 떨어진 깃털이나 그의 정수를 담고 있는 $B$B다른 기념품일 수도 있습니다. 하지만 시간이 촉박하니 서둘러야 합니다. 어서 메디브의 메아리를 네 개 이상 찾아보세요. 이 정도면 열쇠를 재충전하고 카라잔의 방을 열기에 충분할 것입니다."},objectives={{129,523327327},"메디브의 메아리 네 개를 찾으세요. 마법사에게 매우 중요한 장소에서 발견될 수도 있습니다. 그런 다음 열쇠를 가지고 반돌에게 돌아가세요."},progress={{356,37644879},"저는 메디브가 과거에 있었던 장소 중 하나를 알고 있습니다. 바로 로데론의 왕좌실입니다. 비록 지금은 3차 전쟁으로 폐허가 되었지만, 과거의 흔적이 아직 남아 있을 가능성이 있습니다. 어쩌면 잔류 에너지나 잊혀진 유물의 형태로 그의 존재를 나타내는 단서를 발견할 수 있을지도 모릅니다."},completion={{361,149745721},"메디브의 메아리를 찾으신 것을 축하드립니다. 임무를 성공적으로 완료하셨지만, 안타깝게도 열쇠는 여전히 부서져 사용할 수 없습니다. 메디브의 메아리를 주입하는 것만으로는 원래 상태로 복구하기에 충분하지 않았던 것 같습니다. 돌이켜보면, 제가 더 일찍 알아차렸어야 했습니다. 열쇠를 보여주시면 자세히 살펴보겠습니다."}}
rows[40827]={title={{24,1363571558},"카라잔의 열쇠 VIII"},description={{775,927874104},"돌반은 열쇠를 꼼꼼히 살펴보며 모든 각도에서 살펴보고, 잠재적인 문제점을 감지하기 위해 주문을 $B$B외웠다. \"열쇠를 통해 흐르는 마법 에너지에 문제가 있는 것 같습니다. 자세히 살펴보니 열쇠를 고정하는 수정들이 복구 불가능할 정도로 손상되었습니다. 안타깝게도 저는 그것들을 고칠 능력이 없어서 열쇠를 다시 작동시키려면 새로운 수정을 구해야 합니다. 저는 다이어 몰 던전 깊숙한$B$B 곳에 이몰타르라는 악마가 살고 있다는 소문을 들었습니다. 전설에 따르면 그의 피부에는 열쇠를 수리하는 데 사용할 수 있는 특이한 보석이 박혀 있다고 합니다. 하지만 이몰타르는 매우 강력한 적이며, 그에게 도달하는 여정은 결코 쉽지 않을 것입니다.\""},objectives={{80,1467529424},"다이어 몰에서 임몰타르를 처치하고 그의 가죽에서 보석을 회수하여 반돌에게 돌아가십시오."},progress={{57,1501604702},"다이어 몰은 서쪽, 페랄라스의 황량한 땅에 자리 잡고 있습니다."},completion={{340,90065700},"또 한 번, 당신은 다른 사람들이 실패한 일을 해냈습니다. 당신의 뛰어난 능력과 끈기에 깊은 감명을 받았습니다. 이 임무를 끝까지 완수하려는 당신의 확고한 의지는 정말 존경스럽습니다.$B$B이제, 악마 임몰타르에게서 회수한 보석을 넘겨주시면 열쇠를 다시 벼려내겠습니다."}}
rows[40828]={title={{22,1703698908},"카라잔의 열쇠 9"},description={{648,2114518062},"돌반은 열쇠를 고치느라 애썼고, 시간이 흐를수록 그의 표정은 실망감으로 $B$B일그러졌다. \"이해할 수가 없군. 이건 안 돼. 메디브의 마법에 정통하다고 생각했는데, 아아, 틀렸어. 이 남자는 엄청난 재능을 가졌는데… 하지만 $B$B이야기가 딴 데로 새는군. 열쇠를 고쳐야 해. 마지막으로 한 가지 가능성이 떠오른군.$B$B 오래전 에그윈이 쓴 '마법 자물쇠와 열쇠에 관한 논문'이라는 희귀한 책이 필요해. 달라란이 파괴된 이후로 사라졌지만, 소문에 따르면 빅터 네파리우스 경이 가지고 있다고 해… 이게 우리의 유일한 $B$B기회야. 그 책을 되찾아 와야 해.\""},objectives={{114,1072517954},"\"마법 자물쇠와 열쇠에 관한 논문\"을 찾아서 반돌에게 가져다 주세요. 블랙윙 소굴에 보관되어 있다는 소문이 있습니다."},progress={{188,383755144},"빅터 네파리우스 경은 검은바위 산에 거주하며 검은바위 오크 군대와 그 밖의 무시무시하고 혐오스러운 생물들을 다스리고 있다고 전해집니다."},completion={{436,642501285},"믿기지 않아. 존경받는 에그윈이 직접 쓴 \"마법 자물쇠와 열쇠에 관한 논문\"이라니. 이렇게 오랜 시간이 지난 후 내 손에 들어오다니.$B$B이 고대 서적을 좀 살펴봐야겠군. 닳고 풍화된 이 책에 담긴 지식은 메디브가 이 열쇠를 만들 때 사용했던 지식일 거라고 확신해. 이 책에 기술된 방법과 기법을 연구하면, 우리도 그 과정을 재현하고 열쇠를 수리할 수 있을 거야."}}
rows[40829]={title={{21,619546532},"카라잔의 열쇠 X"},description={{471,1589792070},"돌반은 깊은 경외심을 담아 고서의 페이지를 꼼꼼히 넘기며 마치 섬세한 보물을 다루듯 조심스럽게 한 장 한 장 넘겨본다. 그가 신비로운 마법 연구를 몹시 그리워했음이 분명하다. 그의 자세는 곧게 펴지고 학자다운 분위기를 풍기며, 이전에 일그러졌던 얼굴은 평온한 표정으로 바뀐다. 마치 영원처럼 느껴지는 시간이 흐른 후, 그는 새로운 목적의식을 품은 듯 당신을 올려다본다. \"준비됐습니다.$B$B 열쇠를 다시 만들어 봅시다.\""},objectives={{55,1531837952},"상원 열쇠의 재련 과정을 목격하십시오."},progress={{8,2043663839},"마지막으로."},completion={{494,324811522},"임무가 완료되었습니다. 이제 상층부의 열쇠가 당신의 손에 있습니다. 전설적인 카라잔의 비밀과 경이로움이 당신을 기다리고 있으며, 이 고대 장소의 미스터리가 다시 한번 밝혀질 것입니다.$B$B하지만 내 경고에 귀 기울여라. 불과 유황에 휩싸인 그림자가 기다리고 있다. 불길하고 불길한 기운을 내뿜는 불타는 그림자는 그 길에 있는 모든 것을 집어삼키려 한다.$B$B저의 역할은 여기서 끝납니다. 이제 아제로스의 운명을 당신과 당신의 동료들에게 맡기겠습니다. 아제로스의 운명은 당신들의 손에 달려 있습니다."}}
rows[40830]={title={{18,182908515},"그레이셔를 샅샅이 뒤지다"},description={{978,2005899888},"길니아는 음울해 보일지 모르지만, 이곳이 항상 우리의 현실이었던 것은 아니라는 것을 말씀드리고 싶습니다. 과거에 저는 스승님들의 가르침 아래 오랜 세월을 보내며 빛을 위한 위대한 원고들을 그렸습니다. 저는 신앙을 전파하고 많은 훌륭한 사람들과 함께 $B$B빵을 나누었습니다. 제3차 전쟁의 위험천만한 시기에 우리가 아무런 피해도 입지 않았다고 생각하는 어리석은 자들이 있습니다. 북쪽의 사촌들처럼 역병으로 직접적인 고통을 겪지는 않았지만, 우리도 스컬지와 싸워야 했습니다.$B$B 아시다시피, 2년 전 영원한 나제라는 강력한 리치가 올드록 고개 근처의 성벽을 무너뜨렸습니다. 결국 길니아의 용감한 병사들이 언데드를 물리쳤지만, 우리의 승리는 끔찍한 대가를 치렀습니다. 저는 운 좋게$B$B 그레이샤이어에서 목숨을 건졌지만, 다른 이들은 그렇지 못했습니다. 여러분께 부탁드립니다. 그 버려진 곳을 샅샅이 뒤져 제가 젊은 시절을 바쳐 그린 원고들을 되찾아 주십시오. 그곳에 계시는 동안, 여전히 남아 있는 쓸쓸한 영혼들에게 평화를 가져다주세요."},objectives={{110,1821710411},"길니아스의 섀드모어 선술집에 있는 오블렌 신부를 위해 그레이셔 유적에서 그레이셔 필사본을 회수하십시오."},progress={{130,290848579},"위험한 일처럼 보일지 모르지만, 기억하세요. 빛에 대한 믿음을 잃지 않는다면 반드시 올바른 길을 찾게 될 것입니다."},completion={"<Father Oblen seems pleased gazing upon his old work.>$B$BAhh, I never thought I would look upon these scripts again, lucky they are to have survived all of the misery that befell that place.$B$BI thank you greatly for your efforts, $c. Please, take this as a sign of my gratitude.","<오블렌 신부는 자신의 옛 작품을 바라보며 만족스러운 표정을 짓는다.>$B$B아, 이 원고들을 다시 볼 수 있을 거라고는 생각도 못 했었는데, 그곳에 닥친 온갖 참혹한 일들을 견뎌내고 살아남아서 정말 다행이다.$B$B수고해 주셔서 진심으로 감사드립니다.$c이것을 제 감사의 표시로 받아 주십시오."}}
rows[40841]={title={{15,2031775537},"벽 뒤에서"},description={{655,1693893344},"북쪽에서 들려오는 소식을 들었나? 그레이메인 성벽이 드디어 열렸다고 하더군.$B$B 내가 들은 그 끔찍한 일들을 생각하면 다시는 살아 돌아오지 못할 것 같아. 게다가 소문에 따르면 상황도 좋지 않아 보여. 하지만 길니아스 시티에는 내 소중한 친구 한 명이 '던스톤'이라는 희귀한 재료를 다루는 일을 했었는데, 이 재료는 길니아스에서만$B$B 구할 수 있는 거야. 분명 그의 작업실에 설계도가 있을 테니, 부디 그걸 찾아다 주면 좋겠군. 동료들을 몇 명 데리고 가는 게 좋을 거야. 소문에 따르면 늑대인간과 내전으로 인한 소요 사태가 벌어지고 있다고 하니, 혼자서는 절대 갈 수 없는 곳이거든."},objectives={{92,1344468902},"길네아스 시티로 가서 스톰윈드에 있는 테룸 심연 제련소의 새벽돌 설계도를 회수하세요."},progress={{162,1902185526},"계획은 좀 진전이 있었나요?$B$B제가 부탁드린 일이 쉽지 않다는 건 알지만, 그 계획들은 한 사람의 평생의 노력이 담긴 결과물이라, 만약 잃어버리게 된다면 정말 비극일 겁니다."},completion={"Are these it? I haven't had the opportunity to read these plans in quite some years.$B$BAdaman was an exceptionally talented blacksmith and I grieve deeply for his passing. I will make sure his findings are properly recorded here and in Ironforge, so that his name may earn the recognition he always deserved.$B$BThank you, $N. I have prepared something for you as well, as compensation for the immense trouble you put yourself through.","이게 다인가요? 몇 년 동안 이 도면들을 읽어볼 기회가 없었네요.$B$B아다만은 뛰어난 재능을 가진 대장장이였고, 그의 죽음을 진심으로 애도합니다. 그의 업적이 이곳과 아이언포지에 제대로 기록되어, 그가 마땅히 받아야 할 인정을 받을 수 있도록 하겠습니다.$B$B감사합니다,$N. 당신이 수고해 주신 것에 대한 보상으로 저도 무언가를 준비했습니다."}}
rows[40842]={title={{14,535766053},"진정한 적"},description={{546,172259138},"사악한 악마들이 감히 포레스트 송 남쪽, 비참한 데몬 폴 캐니언에 요새를 점령하고 우리에게 도전하고 있습니다.$B$B 슬프게도 파수꾼들은 완강히 저를 돕기를 거부하는 반면, 우리의 진정한 적은 더욱 강해져 또 다른 침략을 준비하고 $B$B있습니다. 이제 행동에 나서야 합니다. 부디 그들의 영역으로 들어가 수를 줄여주십시오. 마주치는 모든 종류의 악마를 최소 열 마리씩 처치한다면 강력한 경고를 보낼 수 있을 것입니다.$B$B 이 악귀들을 뒤틀린 황천으로 추방하여 다시는 우리의 신성한 숲을 더럽히지 못하게 해야 합니다."},objectives={{113,1531530874},"애쉬엔베일의 포레스트 송에서 타오르는 지옥불정령 10마리, 지옥수호병 10마리, 만노록 채찍질하는 자 10마리를 처치하여 델로스 탈론하트를 획득하세요."},progress={{169,2116928760},"우리는 수많은 전장을 거치며 수천 년에 걸쳐 군단과 전쟁을 벌여왔습니다.$B$B우리는 이 세계의 수호자이며, 그들이 이 세계를 더럽히는 것을 결코 용납하지 않을 것입니다."},completion={"The trees, the beasts, the wind; all of nature rejoices. In its song, it is you who are owed thanks, $N.$B$BYour bravery and tenacity in cleansing Demon Fall Canyon have bought us precious time to prepare for the final confrontation. Your actions have not gone unnoticed, and I am proud to call you a comrade in our holy war to protect these lands.","나무들, 짐승들, 바람, 모든 자연이 기뻐합니다. 그 노래 속에 담긴 감사는 바로 당신에게 돌아갑니다,$N,$B,$B. 악마의 폭포 협곡을 정화하는 데 보여주신 당신의 용기와 끈기는 우리에게 최후의 결전을 준비할 귀중한 시간을 벌어주었습니다. 당신의 행동은 결코 잊히지 않을 것이며, 저는 이 땅을 지키기 위한 성전에서 당신을 동지라고 부르는 것이 자랑스럽습니다."}}
rows[40843]={title={{24,547863950},"데몬 캐니언에서의 추락"},description={{671,574339059},"악마의 폭포 협곡이 왜 그런 이름을 갖게 되었는지 궁금해 본 $B$B적이 있습니까? 4년 전, 우리 종족의 오랜 적, 심연의 군주 만노로스가 우리 세계를 파괴하기 위해 돌아왔습니다. 그곳에서 그의 가장 잔혹한 오크 하수인 중 하나이자 세나리우스를 무자비하게 살해한 그롬마쉬 헬스크림이 자신의 주인을 배신하고 그를 죽이려$B$B 했습니다. 결국 만노로스와 그롬마쉬는 싸움 끝에 서로를 죽였고, 이는 우리 모두에게 큰 $B$B행운이었습니다. 하지만 만노로스가 휘두른 무기는 여전히 협곡에 산산조각 나 있으며, 바라시우스라는 강력한 사티로스가 그것을 다시 벼려내어 자신의 사악한 목적에 이용하려 한다는 소문이 있습니다.$B$B 이 사티로스의 음모를 당장 저지하십시오."},objectives={{108,888746362},"악마의 폭포 협곡에 산다는 소문이 있는 바라시우스를 처치하고 숲의 노래를 통해 델로스 탈론하트로 돌아오십시오."},progress={{93,3709833},"오크들이 협곡에 그롬마쉬를 기리는 기념비를 세웠다고 하더군요.$B$B당신이 그 기념비에 침을 뱉었기를 바랍니다."},completion={{572,895724066},"당신의 헌신과 용기에 항상 의지할 수 있다는 사실이 저에게 큰 위안이 됩니다. 사티로스 바락시우스는 강력하고 위험한 적이었지만, 당신은 뛰어난 전투 실력을 보여주셨습니다. 당신의 행동 덕분에 우리의 신성한 숲은 마노로스의 무기를 악용하려는 자들의 사악한 야망으로부터 지켜낼 수 있었습니다.$B$B사티로스를 처치하고 무기 수리 시도를 막아냄으로써, 당신은 우리 적에게 큰 타격을 입히고 칼도레이에게 중요한 승리를 안겨주었습니다. 당신의 헌신에 영원히 감사드리겠습니다."}}
rows[40844]={title={{22,1426501373},"루크 아가만드에게 보고"},description={{251,658881190},"루크 아가만드는 가족 사이에서 늘 따돌림을 당하는 존재였다. 가족에게서 버림받고 추방당한 그는 어찌어찌 내 눈에 띄어 우리 일행에 합류하게 되었다.$B$B 그의 옛집은 그가 처음으로 습격했던 곳 중 하나였다. 나는 그에게 특별한 임무를 맡겼으니, 당신은 그가 반드시 성공하도록 해야 한다."},objectives={{56,282889758},"길니어스에 있는 블랙쏜 캠프의 루크 아가만드와 이야기하세요."},progress={{18,127551055},"안녕하세요."},completion={"The boss wants you to help me? I hope you're a capable $c and not some diplomatic noodle.$B$BWhat you're about to do will take some guts.","사장님이 나 좀 도와달라고 하셨어? 네가 유능한$c이길 바라. 외교관 노릇이나 하는$B$B같은 사람은 아니길. 네가 하려는 일은 꽤 용기가 필요할 거야."}}
rows[40845]={title={{21,684160254},"드라이록 광산 강도 사건"},description={{376,518114578},"언덕 위에 드라이록 광산이라는 광산이 하나 있는데, 현지인들은 그곳을 길네아 군대에 미스릴 광석을 공급하는 곳이라고 알고 있습니다. 보스는 이 미스릴이 호드에게 공급하기에 훨씬 더 적합하다고 생각하는데, $B$B동의하시겠습니까? 광산으로 올라가서 방해하는 자는 모두 처치하고 미스릴 광석 16자루를 가져오십시오. 임무를 완료하면 저에게 돌아오십시오."},objectives={{87,77416677},"블랙쏜 캠프에 있는 루크 아가만드를 위해 드라이록 광산에서 미스릴 광석 16자루를 모으세요."},progress={{20,247907031},"광석을 얻으셨나요?"},completion={{176,2134471440},"세상에! 네가 정말로 해냈구나! 사장님께서 이 미스릴이 가장 필요한 곳에 쓰이도록 하실 거야. 자네가 제 역할을 톡톡히 해냈군, 꼬마야. 자, 네 몫을 줄게."}}
rows[40846]={title={{25,725371272},"리비아 스트롱암에게 보고"},description={{167,975524695},"리비아는 처음부터 이 조직의 일원이었습니다. 그녀가 당신을 가치 있다고 여긴다면 저도 마찬가지일 겁니다. $B$B제가 그녀에게 아주 중요한 임무를 맡겼습니다. 가서 그녀를 도와주세요."},objectives={{57,519018338},"길니어스에 있는 블랙쏜 캠프에서 리비아 스트롱암을 찾아보세요."},progress={{13,1711692534},"아, 당신이었군요."},completion={{248,1324408414},"잘 들어라, 꼬마야. 난 그 잘난 척하는 길네아 땅에 눈길조차 내밀고 싶지 않았어. 약탈할 생각도 전혀 없었고. 내 호감을 얻고 싶다면, 보스가 시킨 이 일을 끝내도록 도와줘. 그래야 여기서 일을 마무리 짓고 이 지긋지긋한 곳을 떠날 수 있으니까."}}
rows[40847]={title={{31,2072665813},"침투자와의 만남"},description={{549,1280953547},"이 지역에 대한 우리의 정보는 빈약합니다. 길니아스가 고립주의 국가라는 것은 알고 있었지만, 이토록 비참한 상태일 줄은 몰랐습니다.$B$B 우리는 살아있는 사람들 속에 섞여 들어가 첩보 활동을 하는 데 어려움이 없습니다. 우리 요원 중 한 명이 \"그레타 롱파이크\"라는 가명을 사용하고 있는데, 최근 보고에서 그레이셔라는 정착지에 $B$B잠입했다고 합니다. 그녀를 찾아가 \"밤의 여인, 새벽에 입에 금을 물고\"라고 전하십시오. 이것이 암호입니다. 그녀는 매우 중요한 보고서를 줄 것이고, 그 내용을 내게 가져오십시오."},objectives={{139,2000850734},"그레이샤이어 유적지로 가서 그레타 롱파이크를 찾고, 길니아스의 블랙쏜 캠프에서 리비아 스트롱암을 위한 봉인된 보고서를 획득하세요."},progress={{52,468201033},"돌아오면 그 보고서를 꼭 챙겨 와 있어야 할 거야."},completion={{347,228247085},"길네아에서 반란이 일어난 것 같습니다. 한쪽은 리암 그레이메인 왕자와 레이븐우드라는 인물이 이끌고 있고, 다른 한쪽은 부패한 길네아 귀족들이 주도하고 있습니다. 보스께서 이 상황에 대해 듣고 싶어 하실 겁니다. 훌륭하게 임무를 수행하셨습니다. 쉽지 않은 임무였겠지만, 호드의 일원으로서 완벽한 수행 능력을 보여주셨습니다."}}
rows[40848]={title={{28,1257993660},"블랙쏜과 함께하는 소중한 시간"},description={{583,2140985928},"왜 인간 무리가 호드와 손을 잡았는지 궁금하겠지. 그 답은 역병지대에서 벌어진 내전에 있어. 그때 우리 언데드가 처음으로 자유를 $B$B쟁취했지... 그래, 우리 언데드 말이야. 난 지금 블랙쏜에 빙의한 밴시인데, 그의 잔인한 무리를 설득해서 우리 편으로 만들었어. 안심해, $B$B나 혼자 하는 일은 아니야. 더 알고 싶다면 내 신뢰를 얻어야 할 거야. 나가들이 해변에서 캠프로 접근하고 있거든. 놈들을 처치하고 돌아오면 그때 다시 이야기를 나누자."},objectives={{73,1880259060},"길네아스의 블랙쏜 캠프에서 블랙쏜을 위해 스파이트레스트 네터 8명을 처치하세요."},progress={{27,1860061992},"이야기를 계속해 볼까요?"},completion={{390,68540006},"잘 해냈습니다.$B$B포세이큰의 승리 이후, 전쟁 중에 육체를 지녔던 자들은 암흑 여왕의 눈과 귀로 파견되었습니다. 우리 그룹은 인간들 사이에 섞여 들어가기에 적합하기 때문에 주로 얼라이언스를 염탐하는 임무를 맡습니다.$B$B저는 이 그룹의 동료들에게 정이 많이 들었습니다. 한때는 규율과 목적의식이 부족했지만, 이제는 숙련된 침투 요원이자 첩자가 되었습니다."}}
rows[40849]={title={{23,1109419309},"겐 그레이메인은 죽어야 한다!"},description={{463,1309047842},"이야기는 끝났습니다. 이제 행동할 시간입니다. 리비아에게서 가져온 보고서를 읽었고, 어떻게 처리하는 것이 최선인지 $B$B결정했습니다. 겐 그레이메인 왕은 옛 로데론 동맹에서 언제나 막강한 세력이었습니다. 그의 힘과 지략은 고집과 오만함에 비견될 만했습니다. 무너져가는 왕국을 그가 다시 장악하도록 내버려 둘 수는 없습니다. $B$B최대한 많은 동료들과 함께 그의 도시로 들어가 그의 목을 가져오십시오."},objectives={{109,359414201},"길네아스 시티에 들어가 겐 그레이메인을 처치한 다음, 그의 머리를 길네아스에 있는 블랙쏜의 캠프로 가져오십시오."},progress={{141,862920208},"길네아의 왕은 한때 막강한 권력을 휘두르했지만, 왕국에 대한 그의 권력과 지배력은 약해졌다. 그러나 그는 결코 만만한 상대가 아니다."},completion={{325,1719691587},"훌륭하군! 자네는 어둠의 여왕의 유능한 요원임을 증명했네.$B$B하지만 도시에서 일어난 일에 대한 자네의 이야기는 나를 불안하게 하는군… 만약 겐 그레이메인이 정말로 반란의 배후였다면, 우리는 의도치 않게 적을 도운 셈이군. 하지만 그건 자네의 잘못도 아니고 자네가 신경 쓸 일도 아니네.$B$B이제 우리가 처리하겠네. 자네는 가도 좋네."}}
rows[40850]={title={{10,210428726},"길니아스로"},description={"The Dark Lady has a task for a capable $c such as yourself that would benefit the interests of the Horde.$B$BOne of the Banshee Queen's agents has been sent to Gilneas in order to survey the situation, acquire assets for the Horde, and evaluate whether the area is suitable for exploitation by the Forsaken.$B$BThe Greymane Wall was recently breached and the nation it once protected is in chaos, granting us access and an opportunity. Follow the road south into Gilneas, circle around the city, and you will find a camp by the western shore occupied by Blackthorn.$B$BYou may be surprised by the nature of his followers, but rest assured that he and his minions are devoted in their service to the Horde and the Dark Lady. Report to him and he will make good use of you.","어둠의 여왕께서 당신처럼 유능한 $c자에게 호드의 이익에 도움이 될 임무를 맡기셨습니다. $B$B밴시 여왕의 첩자 중 한 명이 길니아에 파견되어 상황을 파악하고, 호드를 위한 자산을 확보하며, 포세이큰이 이 지역을 이용하기에 적합한지 평가할 예정입니다. 최근 그레이메인$B$B 장벽이 무너져 한때 그 장벽이 보호하던 나라가 혼란에 빠졌고, 이는 우리에게 기회를 제공했습니다. 남쪽 길을 따라 길니아로 들어가 도시를 돌아가면 서쪽 해안가에 블랙쏜이 주둔하고 있는 야영지를 발견할 수 있을 것입니다.$B$B 그의 추종자들의 모습에 놀랄 수도 있겠지만, 그와 그의 부하들은 호드와 어둠의 여왕께 충성을 다하고 있으니 안심하십시오. 그에게 보고하면 그는 당신을 잘 활용할 것입니다."},objectives={{52,1290268357},"길니어스에 있는 블랙쏜 캠프에서 블랙쏜을 찾아보세요."},progress={{12,201207537},"당신은 누구신가요?"},completion={{312,708720680},"어둠의 여왕께서 우리를 돕기 위해 자를 보내셨음을 알겠소. 나는 인간처럼 보일지 모르지만, 겉모습에 속지 마시오.$B$B나는 밴시 여왕께 충성을 다하기 때문에 호드에 전적으로 헌신하고 있소. 자네가 도우러 왔다면, 일을 맡기겠소.$B$B내 부하들을 도우시오. 그러면 더 자세한 지시를 내리겠소."}}
rows[40851]={title={{22,1678121309},"교회에서 버림받다"},description={{445,364273208},"우리 정찰병들이 이 지역을 조사하던 중 북동쪽에서 포세이큰 무리를 발견했습니다. 증원군이 도착할 예정이라는 소식이나 다른 포세이큰이 이곳에 있다는 정보는 아직 받지 못했습니다. 혹시 조사에$B$B 참여해 주시겠습니까? 이 포세이큰들은 북동쪽에 있는 스틸워드 교회라는 곳 근처에서 발견되었습니다. 만약 그들이 도움이 필요하다면, 포세이큰 형제자매들을 돕는 것은 우리의 의무입니다."},objectives={{53,1026809322},"길니어스에 있는 스틸워드 교회에서 버림받은 자들을 찾아보세요."},progress={{36,476433823},"방황하던 영혼이 우리 무리에 합류했습니다."},completion={{238,2020693159},"이 땅에 우리와 같은 존재들이 또 있다는 사실에 놀랐습니다. 우리가 자발적으로 이곳에 왔으니 그들이 우리의 존재를 몰랐던 것도 당연하겠죠.$B$B하지만 여기까지 오셨다면 분명 저희를 도와주실 의향이 있으시겠죠."}}
rows[40852]={title={{19,715207406},"브롤록 오우거 현상금"},description={{471,593994281},"이곳 주변이 온통 문제투성이여서, 어쩔 수 없이 검을 든 용병들에게 도움을 청해야 하는 상황이군. 솔직히 말해서, 결코 달갑지 않은 처지지.이봐,$B$B 난 네 말을 들어주려고 돈을 주는 게 아니고, 넌 내 말을 들으러 온 것도 아니잖아. 여기 북쪽, 저 언덕에는 내가 감당하기 힘들 정도로 많은 오우거들이 있어. 가서 그들의 목을 베어 와. 스무 개만 가져오면 보수를 주겠다.<그는 $B$B비웃는 듯한 미소를 지으며 시선을 돌렸다.>"},objectives={{75,1891438004},"길니어스에 있는 레이븐셔의 아빙턴 병장에게 브롤록 오우거 머리 20개를 가져다주세요."},progress={{112,1730382759},"당신은 죽은 용병이 아닌 것 같군요. 그렇다면 당신은 성공한 용병인가요, 아니면 그저 게으른 용병인가요?"},completion={{140,714362918},"열여덟, 열아홉, 둘… 흠. 저건 정말 심하게 손상됐네. 도대체 무슨 짓을 한 거야? 어쨌든 잘했어. 여기 보상이야."}}
rows[40853]={title={{20,1175167705},"신반의 직원들"},description={"Truthfully, $N, I don't really care how many dumb ogres are killed by gold-a-dozen mercenaries. Whether it's you or some other that brings me a bag of heads, it makes no difference.$B$BOh, don't look at me like that, you know I'm right. Anyway, if you want something meaningful to do, listen: our scouts overheard that two ogres are vying for power amongst the Brol'ok. One of which calls himself Shinban Four-Eyes. A two headed ogre with three actual eyes, claims the fourth is a hidden one that gives him the vision required to lead!$B$BI would be worried about that, $N. Either he is telling the truth and is a caster powerful enough to have magical sight, or he is smart enough to understand metaphors. Both are worrying. Regardless, he is your primary target.","솔직히 말해서,$N , 금화 12개 주는 용병들이 멍청한 오우거들을 몇 마리나 죽이든 난 상관없어. 네가 오우거들의 머리가 든 자루를 가져오든 다른 누가 가져오든 아무런 차이도 없어.$B$B, 그렇게 쳐다보지 마. 내 말이 맞는 거 알잖아. 어쨌든, 뭔가 의미 있는 일을 하고 싶다면 잘 들어봐. 우리 정찰병들이 브롤록 부족 내에서 오우거 두 마리가 권력 다툼을 벌이고 있다는 걸 엿들었어. 그중 한 마리는 자기를 신반 네 눈이라고 부르는데, 머리가 두 개인 오우거지만 실제 눈은 세 개뿐이고, 네 번째 눈은 숨겨진 눈이라서 지도자가$B$B 되기 위한 예지력을 준다고 $N주장해! 나 같으면 걱정될 거야, . 그 녀석이 진짜 마법을 쓸 줄 아는 마법사이거나, 아니면 은유를 이해할 만큼 똑똑한 거겠지. 둘 다 걱정스러워. 어쨌든, 그 녀석이 네 주요 목표물이야."},objectives={{91,1126682081},"신반 안경잡이를 처치하고 그의 지팡이를 길니아스 레이븐셔에 있는 아빙턴 하사에게 가져다주십시오."},progress={{52,1669891442},"더 이상 할 일은 없습니다. 현재 진행 중인 업무를 완료해야 합니다."},completion={{165,1962942478},"자네가 이렇게 빨리 전리품을 가져오는 걸 보니, 그가 그렇게 위협적인 존재는 아니었던 것 같군. 보수는 바꾸지 않겠지만, 어쨌든 보상은 보상이니 받도록 하지."}}
rows[40854]={title={{13,173061933},"버논의 임무"},description={"Greetings, $N.$B$BIt is rare that I admit my incorrect assumptions, but I must atone for this one. I previously thought the ogres of Brol'ok should be allowed to grow and fester, like a pustulant sore, right next to Ravenshire. Let the living there be the ones to suffer with it.$B$BBut alas, whatever still holds vigil over this godforsaken land has a sense of irony. It was just last night that I saw a group of ogres attack, and kill, one of our own Deathstalkers. Out of my own pocket, I now purchase vengeance. Bring me twenty of their heads, and be rewarded.","안녕하세요,$N $B$B.님. 제가 잘못된 생각을 인정하는 경우는 드물지만, 이번 일은 꼭 사과드려야겠습니다. 저는 이전에 브롤록의 오우거들이 레이븐샤이어 바로 옆에서 고름이 찬 상처처럼 번져나가도록 내버려 두어야 한다고 생각했습니다. 그곳에 사는 사람들이 그 고통을 고스란히 감내하게 해야$B$B 한다고 생각했죠.하지만, 이 저주받은 땅을 아직도 지키고 있는 존재가 아이러니를 안겨주었습니다. 바로 어젯밤, 오우거 무리가 우리 데스스토커 중 한 명을 공격하고 죽이는 것을 목격했습니다. 이제 제 사비를 들여 복수를 해야겠습니다. 그들의 머리 스무 개를 가져오면 보상해 드리겠습니다."},objectives={{82,1796596106},"길니아스에 있는 스틸워드 교회의 데스스토커 버논에게 브롤록 오우거 머리 20개를 가져다 주세요."},progress={{55,251918994},"서둘러라, 복수는 즉시 충족시켜야 제맛이다."},completion={{97,1452922272},"정말 영광스럽군요, 그저 영광스러울 뿐입니다. 아, 빚을 스무 배로 갚았다는 이 달콤한 맛이란!"}}
rows[40855]={title={{20,1608319407},"야만인들 중 우두머리"},description={"Recent events have made me reconsider my outlook on life. Or, lack thereof.$B$BWhat is it that demands the most respect in this world, $N? I would say that is power. Raw and unadulterated. Sheer strength of will, force of arm, power. And what causes any kingdom to fall into ruins, to crumble into ash? The loss of leadership, the lack of power!$B$B Ah, forget my musings and ramblings, I have much too much time and much too much contempt. To speak plainly: the Brol'ok have a champion vying for power in their little mounds, known as Maulfist. He is called a chief, even amongst the ogres, so he must be exceptionally powerful... bring me his crown, if you can. I will reward you handsomely if so.","최근 사건들 때문에 인생관, 혹은 인생관의 부재에 대해 다시 생각해 보게 $B$B되었습니다. 이 세상에서 가장 존경받아야 할 것은 $N무엇일까요, ? 제 생각에는 권력입니다. 순수하고 불순물이 섞이지 않은 권력 말입니다. 순수한 의지력, 무력, 그리고 권력. 그렇다면 어떤 왕국이 몰락하고 잿더미로 변하는 원인은 무엇일까요? 바로 지도력의 $B$B상실, 권력의 부재입니다!  아, 제 잡담은 잊어버리세요. 저는 시간도 많고 경멸감도 넘쳐납니다. 솔직히 말해 두죠. 브롤록족의 작은 언덕에서 권력을 잡으려는 마울피스트라는 자가 있습니다. 그는 오거들 사이에서도 족장으로 불리니, 분명히 엄청난 힘을 가진 자일 겁니다… 할 수 있다면 그의 왕관을 가져오시오. 성공한다면 후한 보상을 주겠소."},objectives={{82,1181426371},"길니어스에 있는 스틸워드 교회에 있는 데스스토커 버논에게 몰피스트의 왕관을 가져다 주세요."},progress={"Yes, $N? Have you brought death to their mounds?","네,$N번이요? 당신은 그들의 무덤에 죽음을 가져다주었습니까?"},completion={{146,204503949},"아, 정말 멋지군요. 이런 투박한 솜씨라니, 그들의 작품은 종종 꽤 한심해 보이지 않나요? 아, 신경 쓰지 마세요. 보상은 바로 드리는 겁니다."}}
rows[40856]={title={{24,1573843839},"백업 시스템 활성화"},description={{952,553911990},"그노메레건의 복잡한 덕트, 파이프, 채널, 환풍구, 그리고 통로 네트워크는 건강한 공기 흐름을 유지하는 데 필수적입니다. 하지만 이러한 네트워크는 우리 동족에게 치명적인 영향을 미친 유독 가스를 $B$B순환시키기도 했습니다. 예방 조치로, 우리는 비상시 공기 흐름을 전환하는 포괄적인 백업 시스템을 구축했습니다. 불행히도, 이러한 채널 중 상당수가 폐쇄되고 봉쇄되어 있어 레버와 밸브를 조작해야만 다시 활성화할 수 있습니다.$B$B 우리는 도시 내 두 개의 중요한 접근 지점에 접근하기 위해 당신의 기술적 전문 지식이 필요합니다. 첫 번째는 백업 전력 생산을 담당하는 알파 채널로, 엔지니어링 연구실에 위치해 있습니다. 두 번째는 예비 공기 펌프 작동에 필수적인 예비 펌프 채널로, 발사대 근처에 있습니다. 이 채널들을 반드시$B$B 활성화해야 합니다! 우리는 위대한 도시 그노메레건을 한때 누렸던 경이로운 기술의 도시로 되돌려야 합니다!"},objectives={{139,1734480768},"던 모로그에 있는 마스터 기술자 와이어스패너를 위해 그노메레간 깊숙한 곳에 있는 알파 채널 밸브와 예비 펌프 채널 레버를 작동시키십시오."},progress={{183,997426599},"우리의 성공은 이러한 백업 시스템의 활성화에 달려 있습니다. 그노메레간에는 온갖 위험한 것들이 도사리고 있으니, 이 작업에 투입할 백업 인력을 확보하는 것이 좋겠습니다."},completion={{610,2032602016},"모험가님! 알파 채널과 예비 펌프 채널이 약 87%의 효율로 매우 잘 작동하고 있다는 기쁜 소식을 전해드립니다. 아니, 잠깐, 88%입니다! 그노메레간이 처참하게 파괴된 상황을 고려하면, 이는 정말 반가운 소식입니다.$B$B이 시설 복구에 제공해주신 귀중한 도움에 진심으로 감사드립니다. 여러분의 노력이 없었다면 이만큼의 진전을 이루지 못했을 것입니다.$B$B감사의 표시로, 저희 복구 시설 직원 모두를 대표하여 이 작은 선물을 드립니다. 앞으로의 활동에 도움이 되기를 바랍니다."}}
rows[40857]={title={{25,150774754},"나병환자 출신 지도부 제거"},description={{753,455549605},"모험가여, 안녕하십니까. 저는 한때 놈리건에서 널리 알려졌던 티즐 듀얼플래시입니다. 우리의 대의에 큰 도움이 될 귀중한 정보를 가지고 돌아왔습니다. 지상에서 혼란을 일으키고 있는 나병 그놈들의 우두머리가 누구인지 알아냈습니다. 그의 이름은 니반 구블와이어입니다. 그는 나병 환자들을 규합하여 복구 시설에 끊임없이 문제를 일으키고, 우리의 노력을 방해하며, 우리의 미래 성공을 위협하고 있습니다. $B$B그러므로 용감한 모험가여, 니반 구블와이어를 정의의 심판대에 세우는 데 도움을 주시기를 간곡히 부탁드립니다. 쉬운 일은 아니겠지만, 반드시 해내야 합니다. 그는 이곳 놈리건 남쪽, 지상 어딘가에 있을 것입니다. 저를 도와주시겠습니까?"},objectives={{97,288349159},"던 모로그의 그노메레간 복구 시설에서 니반 구블와이어를 처치하고 티즐 듀얼플래시를 획득하세요."},progress={{54,167337685},"자칭 지도자라고 하는 그 불량배를 찾으셨나요?"},completion={"Impressive work, $c. You have slain Neevan Gubblewire and scattered his leper ruffians, making our work safer and more secure. Your bravery and determination are admirable, and you have served our cause well. I will be sure to pass along your name with everyone I am sure to run into.$B$BTake one of these as a token of my appreciation, and best of luck out there.","$c, 정말 훌륭한 활약이었습니다. 니반 구블와이어를 처치하고 그의 부하들을 흩어지게 하여 우리 작전을 더욱 안전하고 확실하게 만들어 주셨습니다. 당신의 용기와 결단력은 존경할 만하며, 우리 대의를 위해 큰 공헌을 하셨습니다. 앞으로 만나는 모든 사람에게 당신의 이름을 꼭 전하겠습니다.$B,$B, 감사의 표시로 이것들을 하나씩 드리겠습니다. 앞으로도 행운을 빕니다."}}
rows[40858]={title={{12,1513223003},"기한이 지난 작업"},description={{354,1449929540},"혹시 스톰라이트 기술자님 보신 적 있으세요? 키가 작고, 대머리에 갈색 염소수염을 기른 ​​분$B$B 말이에요. 제가 접근 단말기 수리를 거의 하루 종일 기다리고 있는데, 그분 작업이 끝나야 절차를 계속 진행할 수 있거든요. 혹시 그분을 찾아서 빨리 끝내달라고 전해주세요. 아마 아직 복구 시설 안에 있을 거예요."},objectives={{84,24536583},"던 모로그에 있는 그노메레간 복구 시설에서 기술자 스톰라이트를 찾으세요."},progress={{4,273767400},"예?"},completion={{248,1922503337},"제가 지금 얼마나 바쁜지 안 보이세요? 형편없는 도구와 부족한 재료로 이 접근 단말기를 작동시키려고 애쓰고 있단 말이에요! 저 같은 노움에게도 꽤 어려운 일이네요.$B$B혹시 저 좀 도와주시겠어요?"}}
rows[40859]={title={{24,1194875915},"수압축기 변조기"},description={{647,1771378172},"며칠 전부터 팅커 타운에서 배송될 물품을 기다리고 있었습니다. 아시다시피, 모든 게 안정되자마자 희귀 자재들을 이곳으로 많이 보냈거든요. 제가 작업 중인 이 점검 패널에는 수압 응축기 변조기가 필요한데, 운송 중에 나병 걸린 노움 무리에게 훔쳐갔습니다. 그들은 귀중품도 꽤 많이 약탈해 갔죠. $B$B자, 새 걸 구하는 건 쉬운 일이 아닙니다. 그 변조기는 놈리건에서만 제작할 수 있었거든요. 그러니 트로그가 우글거리는 그 폐허를 뒤지고 싶지 않다면, 도난당한 걸 찾아보는 게 좋겠습니다. 여기 남쪽에 있는 오래된 집들을 뒤져보세요. 분명 어딘가 안전한 곳에 숨겨뒀을 겁니다."},objectives={{113,894968011},"던 모로그에 있는 그노메레간 복구 시설에서 기술자 스톰라이트를 위한 수력 응축기 변조기를 찾으십시오."},progress={{49,632074517},"제 변조기를 찾는 데 성공하셨나요?"},completion={"<Technician Stormlight lets out an exhausted sigh of relief.>$B$BI was getting ready to start preparing the copper tubes and bronze frameworks as a backup! You have certainly saved a colossal headache by finding this blasted thing. Now I can get started on some real fixing. Thanks again, $c.","<기술자 스톰라이트는 안도의 한숨을 내쉬었다.>$B$B예비용으로 구리관과 청동 틀을 준비하려던 참이었는데! 이 망할 것을 찾아줘서 정말 큰 골칫거리를 해결해 주셨군요. 이제 제대로 수리를 시작할 수 있겠습니다. 다시 한번 감사드립니다,$c."}}
rows[40860]={title={{21,494427872},"던스톤 커플러"},description={{761,1310309328},"수년 전 놈리건을 건설했을 당시 우리는 전 세계에서 온갖 종류의 재료를 구할 수 있었습니다. 그중 하나인 던스톤은 에너지 결합에 탁월했습니다. 마법과 강력한 에너지 흐름 모두에 매우 강한 저항력을 가지고 있어 활용도가 매우 높았습니다. 하지만$B$B 고장 난 던스톤을 수리할 복제품을 만들지 못해 품질이 떨어지는 대체품으로 교체해야 했고, 그 대체품은 훨씬 더 자주 고장$B$B 났습니다. 그런데 운이 좋게도 길니아스가 다시 문을 열었습니다. 그곳에서 내전이 벌어지고 있다는 소문이 무성합니다. 북쪽$B$B 멀리 길니아스로 가서 던스톤 광석 네 개를 구해다 주십시오. 도시 근처에 있는 던스톤 광산에서 찾을 수 있을 겁니다."},objectives={{139,1248867984},"북쪽의 길네아로 가서 던 모로그에 있는 그노메레간 복구 시설의 기술자 볼트기어에게 새벽의 돌 조각 4개를 가져다 주세요."},progress={{189,1292321052},"구리 커플러 소모 속도가 상상을 초월할 정도입니다! 이 시설에서 필요한 모든 수리 작업을 감당하려면 내구성이 뛰어난 제품이 필요합니다."},completion={"<Master Technician Wirespanner gazes upon the ore, an expression of giddy joy washes across his face.>$B$BThese dull, repressed glints, I remember them fondly. Excellent work $c, with this ore we will be able to produce enough conductors to fix what is needed in the facility.","<수석 기술자 와이어스패너는 광석을 바라보며 얼굴에 들뜬 기쁨이 가득했다.>$B$B이 무미건조하고 억눌린 반짝임들, 나는 그것들을 애틋하게 기억한다. 훌륭한 작업이야$c. 이 광석으로 시설에 필요한 전선을 충분히 생산할 수 있을 거야."}}
rows[40861]={title={{21,1908551267},"고에너지 조절기"},description={{838,781233118},"놈리건의 파괴는 우리 기술 발전에 여러모로 큰 타격을 입혔습니다. 눈 깜짝할 사이에 우리의 많은 연구 성과가 $B$B사라졌습니다. 우리는 사실상 눈을 감고 작업하는 것과 마찬가지입니다. 이 시설에서 진정한 진전을 이루려면 매우 희귀하고 중요한 물건이 $B$B필요합니다. 고에너지 조절기는 엄청난 에너지의 급증을 제어하기 위해 만들어진 장치입니다. 이 장치가 없으면 필요한 곳에 과도한 에너지를 공급하는 것이 불가능하며, 바로 그것이 우리가 여기서 하려는 일입니다!$B$B 현재 이 시설은 시스템 과부하를 방지하기 위해 저전력으로 가동되고 있습니다. 하지만 우리는 훨씬 더 빠르게 작업할 수 있습니다. 놈리건에서 분실된 고에너지 조절기의 설계도를 찾아주세요. 이 설계도를 손에 넣을 수만 있다면 이 시설을 원래 설계된 대로 제대로 활용할 수 있을 것입니다."},objectives={{147,1828202450},"그노메레간에서 고에너지 조절기 설계도를 찾아 던 모로그에 있는 그노메레간 복구 시설의 위잔 리틀기어에게 가져가세요."},progress={{108,1895662583},"젠장, 스패너 때문에 항상…$B$B아, 깜짝 놀랐네요. 혹시 회로도를 찾으셨나요?"},completion={"Hmm, this is much more complicated than I remember, but with a little bit of elbow grease and some studious applications of gnomish engineering, it shouldn't be too hard to create a proper replica. It will take some time to test its efficiency before we put it into practice, but this has saved us a lot of time in designing a new prototype.$B$BThanks again $c. Here, take this, a Low Energy Regulator as thanks for your help.","음, 이건 내가 기억하는 것보다 훨씬 복잡하군. 하지만 약간의 노력과 그놈족 공학 기술을 조금만 활용하면 제대로 된 복제품을 만드는 건 그리 어렵지 않을 거야. 실전에 적용하기 전에 효율성을 테스트하는 데 시간이 좀 걸리겠지만, 덕분에 새로운 시제품을 설계하는 데 드는 시간을 많이 절약했어.$B$B다시 한번 고마워.$c. 자, 도움에 대한 감사의 표시로 저에너지 조절기(저에너지 조절기)를 줄게."}}
rows[40862]={title={{18,1574927369},"오작동 대혼란"},description={{617,816235451},"안녕하세요! 저는 노움 팅커인 캐시 코퍼라이트입니다. 얼마 전 팅커 타운에서 나온 불량 데이터 멤브레인 때문에 복구 시설 지하층에 있는 서비터들이 심각한 고장을 일으켜 곤란한 상황에 처했습니다. 당신의 도움이 필요할 것 같습니다. 당신의 임무는 지하층으로 $B$B내려가 고장 난 서비터들을 파괴하는 것입니다. 또한, 주변에 흩어져 있는 예비 부품들을 회수해 주시면 감사하겠습니다. 서비터들을 새로 만들 수 있도록 말이죠. 대략 7개 정도면 충분할 것 같습니다. 쉬운 일은 아니겠지만, 당신의 기술과 용기가 있다면 이 문제를 해결하고 더 이상의 피해를 막을 수 있을 겁니다."},objectives={{134,450163081},"던 모로그에 있는 그노메레간 복구 시설에서 고장난 서비터 10마리를 처치하고 캐시 코퍼라이트를 위해 예비 부품 7개를 모으세요."},progress={{129,2111353145},"저 서비터들을 다룰 때는 조심하는 게 좋을 거야. 주로 작업을 돕기 위해 만들어졌지만, 상당히 위험할 수도 있거든!"},completion={{244,1683198872},"<캐시 코퍼라이트가 안도의 한숨을 내쉬었다.>$B$B휴.$B$B자, 위기 하나는 모면했군. 나머지 고장 난 서비터들도 곧 모두 파괴될 거야. 네가 해준 일에 대한 보답으로 은화를 좀 줬어. 다음에 또 보자!"}}
rows[40863]={title={{21,429179249},"겸손의 자비"},description={{721,421764904},"모험가여, 안녕하십니까. 저는 아르젠트 던의 겸손한 사제, 개빈 신부입니다. 제 영혼을 무겁게 짓누르는 부탁을 드리러 왔습니다. 최근 던 모로그에서 매복 공격을 당해 제가 가장 소중히 여기는 고대 종교 서적인 '겸손의 자비'를 흉포한 록조 트로그들에게 빼앗겼습니다. 이 짐승 같은 괴물들은 쓸모없는 것은 무엇이든 파괴하는 것으로 악명이 높아, 저는 이 귀중한 유물을 $B$B되찾을 수 있도록 도와주시기를 간곡히 부탁드립니다. 남동쪽 아이언밴드 기지 근처에 있는 트로그들이 이 책을 가지고 있을 것이라고 확신합니다. 그들을 처치하고 책이 복구 불가능할 정도로 훼손되기 전에 되찾아$B$B 주십시오. 이 책을 되찾아 주신다면, 빛을 위한 당신의 봉사에 합당한 보상을 해 드리겠습니다."},objectives={{110,162348858},"던 모로그에 있는 아이언밴드 기지 근처의 록조 트로그에게서 개빈 신부를 위해 '겸손의 자비'를 되찾으세요."},progress={{78,1789791919},"너무 늦기 전에 겸손의 자비를 되찾는 것이 무엇보다 중요합니다."},completion={{244,1396042653},"신의 이름으로 맹세하건대, 그 책이 되찾아졌습니다...$B$B무거운 짐이 사라지고 제 영혼이 자유로워졌습니다. 이 책을 되찾아 주신 것은 저에게 큰 은혜이며, 진심으로 감사드립니다.$B$B부디 제 호의의 표시로 이 옷을 받아 주십시오."}}
rows[40864]={title={{16,196674667},"화학 물질 제거"},description={{582,1544385554},"보시다시피, 복구 시설의 하층부가 화학 물질 누출로 오염되어 부식성 물질이 역류하고 있습니다. 이 위험한 물질은 불안정한 마법 변환기에서 마법 에너지가 누출되면서 발생했습니다. 화학자인 저는 이러한 위험 $B$B물질을 제거하는 임무를 맡고 있습니다. 하지만 부식성 물질은 제거하기는커녕 억제하는 것조차 매우 어렵습니다! 이 문제에 도움을 주실 수 있을까요? 역류하는 물질의 양을 줄여주시면 제 일이 훨씬 수월해질 것입니다."},objectives={{121,413048578},"던 모로그에 있는 그노메레간 복구 시설에서 화학자 글로사이트를 얻으려면 하층에서 부식성 백업 8마리를 처치하세요."},progress={{120,1478101125},"당신의 훌륭한 해결책이 효과가 없을 경우를 대비해서, 좀 더 과학적인 해결책을 생각해 보고 있어요."},completion={{201,256087065},"메카토르크의 말에 따르면, 화학물질 유출 사고 수습을 정말 잘 해냈군요.$B$B아직 할 일이 조금 남아있지만, 곧 마무리될 겁니다.$B$B여기, 수고에 대한 보답으로 드리겠습니다."}}
rows[40865]={title={{18,1557817155},"화학적 배신!"},description={{485,2136223595},"고도의 기술력을 지닌 화학 정화 로봇 XV-81이 마법 간섭으로 폭주했습니다. 놈리건 탈환 시설의 하층부에서 난동을 부리며 지나가는 모든 이를 위협하고 있습니다.$B$B지하 깊숙한 곳으로 내려가 XV-81을 찾아 파괴해 주십시오. 더 큰 피해가 생기기 전에 막아야 합니다. 무엇보다 로봇의 두뇌 깊숙한 곳에 들어 있는 매우 희귀한 기술 부품인 화학 처리막을 반드시 회수해 주십시오!"},objectives={{129,2029188919},"XV-81을 처치하고 던 모로그에 있는 그노메레간 복구 시설의 화학자 글로사이트에게 화학 처리 멤브레인을 반환하십시오."},progress={"The chemists here at the Reclamation Facility are relying on you, $N!","여기 복구 시설의 화학자들은 당신,$N에게 의지하고 있습니다!"},completion={{468,1894454490},"해냈군요!$B$B화학 처리 멤브레인이 회수되었습니다. 얼마나 감사한지 말로 다 할 수 없습니다! 새 멤브레인을 만들려면 엄청난 작업이 필요할 거라 벌써부터 걱정했거든요.$B$B이제 팅커 함선과 함께 XV-82 작업을 시작하여 화학적 문제를 훨씬 더 잘 처리하고 신비로운 간섭에도 견딜 수 있도록 만들 수 있습니다.$B$B감사의 표시로 이걸 받으십시오. 당신이 아니었다면 저는 아직도 해결책을 찾느라 머리를 싸매고 있었을 겁니다!"}}
rows[40866]={title={{20,120886710},"검은무쇠 테크놀로지"},description={{540,287087630},"팅커 타운을 떠난 이후로 남동쪽 아이언밴드 기지 근처에서 습격이 있었다는 소식이 들려왔습니다. 트로그들이 그런 짓을 저질렀을 거라고 생각할 수도 있겠지만, 아닙니다. 어둠철족이 던$B$B 모로그에 나타났습니다.이건 우려스러운 일이지만, 어둠철족의 기술을 얻을 수 있는 기회가 될 수도 있습니다. 그들 중에는 뛰어난 기술자와 마법사들이 있다는 것을 알고 있고, 그들의 능력을 직접 확인하고 싶습니다.$B$B그곳으로 가서 찾을 수 있는 것을 가져오십시오. 제가 연구할 수 있도록 말입니다."},objectives={{125,1228824623},"던 모로그에 있는 그노메레간 복구 시설의 아이언밴드 기지에서 다크 아이언 기술을 수집하고 10너 파이프가지를 받으세요."},progress={{48,1484657425},"그래서, 아이언밴드의 기지에 도착하셨나요?"},completion={{281,979254749},"이게 다야? 솔직히 좀 더 기대했는데, 아마 고향에서 너무 멀리 떨어져 있어서 그런가 보군.$B$B뭐, 그래도 좀 더 자세히 연구해 봐야겠어. 적어도 그 흉포한 다크 아이언 몇 마리는 처치했잖아.$B$B자, 감사의 표시로 이 동전을 받아."}}
rows[40867]={title={{23,1674517748},"공식 마스터하기 I"},description={"Greetings $c, I am the Master Chemist here at the Reclamation Facility, working on a groundbreaking formula to purify the air in our once beloved city of Gnomeregan. However, I am in dire need of materials to test my theories.$B$BI require a Pure Aqua Sample, which can only be obtained from the unbalanced aqua found in Dun Morogh's Ice Flow Lake. These elementals are known for their unique and magical properties, making them a perfect specimen for my research.$B$BIf you could gather one Pure Aqua Sample for me, it would be of great assistance. Do approach cautiously, as the elementals can be quite dangerous.","안녕하세요,$c 님. 저는 복구 시설의 수석 화학자입니다. 한때 사랑받았던 도시 그노메레건의 공기를 정화할 획기적인 공식을 연구하고 있습니다. 하지만 제 이론을 검증하기 위해 재료가 절실히 필요합니다.$B$B  저는 순수한 물 샘플이 필요한데, 이는 던 모로그의 얼음 흐름 호수에서 발견되는 불균형한 물에서만 얻을 수 있습니다. 이 정령들은 독특하고 마법적인 속성으로 알려져 있어 제 연구에 완벽한 $B$B표본입니다. 순수한 물 샘플 하나를 구해 주시면 큰 도움이 될 것입니다. 정령들은 매우 위험할 수 있으니 조심스럽게 접근해 주십시오."},objectives={{125,2105756497},"던 모로그의 아이스 플로우 호수에 위치한 불균형한 물에서 순수 물 샘플을 채취하여 화학 전문가 볼터화이트에게 보내주십시오."},progress={{98,335711782},"제가 당신에게 수집을 의뢰한 샘플은 매우 중요합니다. 이 일을 절대 미루지 마십시오."},completion={{197,281448119},"<베테랑 화학자 볼터화이트는 시간을 들여 매우 신중하게 시료를 연구합니다.>$B$B음, 이것은 내가 연구 중인 복잡한 퍼즐의 중요한 조각이 될 수도 있겠군. 먼저 몇 가지를 테스트해 봐야겠어..."}}
rows[40868]={title={{24,318493099},"포뮬러 II 마스터하기"},description={{688,418825560},"당신이 제공한 샘플의 마법적인 변동은 매우 극심했습니다. 이 에너지를 활용하고 제어하기 위해서는 몇 가지 재료가 필요합니다. 제가 오랫동안 기다려온 재료들입니다. 골볼라르$B$B 채석장의 소동과 그곳에서 일하던 계약자의 갑작스러운 죽음으로 인해 저는 스노우베일 뿌리와 골볼라르 광석을 구할 수 없게 되었습니다. 혹시 이 재료들을 구해 주실 수 있을까요? 스노우베일 뿌리는 $B$B종종 산속 깊은 곳에 있는 은신처로 간 서리갈기 예언자들이 가지고 다닙니다. 그들에게서 스노우베일 뿌리 샘플 세 개를 받아야 합니다. 골볼라르 광석은 채석장의 탐사꾼 ​​게흔이 우리를 위해 구해줄 것이라고 확신합니다."},objectives={{223,853490304},"던 모로그에 있는 서리갈기 예언자의 집에서 눈베일 뿌리 3개를 모으고, 골볼라 채석장의 탐사꾼 ​​게흔에게서 골볼라 광석 한 상자를 받아 던 모로그의 그노메레간 복구 시설에 있는 화학 전문가 볼터화이트에게 가져다 주세요."},progress={{92,1647244104},"당신은 내 작업을 방해하고 있어요. 혹시 제가 구해달라고 부탁했던 재료들을 가지고 계신 건 아니겠죠?"},completion={{185,815587027},"골볼라 광석의 안정적인 성질과 스노우베일 뿌리의 제어된 에너지는 아까 가져오신 물 샘플의 극심한 변동을 잘 제어해 줄 것입니다."}}
rows[40869]={title={{25,920406781},"포뮬러 III 마스터하기"},description={{473,980024769},"당신이 도와주시는 동안 좋은 생각이 떠올랐어요! 이 요소들을 기반으로, 저는 공식에 더 휘발성이 강한 물이 필요하다는 것을 알게 됐습니다. 더 강력한 화학 반응을 통해 이론적으로 공기 중의 독소를 제거할 수 있을 거예요.$B$B 꽤 설득력 있지 않나요? $B$B계산해 보니, 필요한 건 휘발성 물 샘플 하나뿐입니다. 던 $B$B모로그 동쪽 헬름스 베드 호수 근처에 상당히 적대적인 물 정령이 있다는 소문을 들었거든요."},objectives={{114,752308523},"던 모로그에 있는 그노메레간 복구 시설의 수석 화학자 볼터화이트에게 휘발성 물 샘플을 채취해 주세요."},progress={{81,1098378418},"제 작업은 거의 완료되었고, 우리는 중대한 돌파구를 마련할 직전에 있습니다."},completion={{582,2126793700},"<화학의 대가 볼터화이트는 결연한 표정으로 휘발성 아쿠아를 바라보며 곧바로 합성 과정을 시작한다.>$B$B뒤로 물러서세요. 금방 끝날 겁니다.$B$B<노움의 얼굴에 비웃음이 번진다.>$B$B제 이론이 성공적이었던 것 같습니다. 설계도를 복제하고 샘플의 공기에서 방사능을 제거하는 데 성공했거든요!$B$B당신의 도움 덕분에 제 이론이 검증되었고, 당신이 없었다면 어떻게 됐을지 모르겠습니다. 이제 진짜 일이 시작될 겁니다.$B$B당신의 도움에 대한 보답으로 선물을 준비했습니다. 하나 고르세요. 당신에게 도움이 되기를 바랍니다."}}
rows[40870]={title={{18,1289830755},"꽃이 핀 히잘루트"},description={{508,29801489},"거기 당신! 그래, 바로 당신, 필멸자여! 도움이 필요합니다. 제 친구가 에메랄드 꿈의 광기에 사로잡혀 병들기 시작했는데, 영원히 잃기 전에 치료해 주셔야 $B$B합니다. 노르드라실의 수호자들에게서 이 지역에서만 자라는 하이잘루트라는 약초에 대한 이야기를 들었습니다. 구하기가 쉽지는 않지만, 파라누스의 고통을 덜어주려면 여덟 묶음이 필요합니다. 부디 서둘러 주십시오. 그렇지 않으면 제 친구를 영원히 잃게 될 것입니다. (<어린$B$B 새끼는 슬픔에 잠긴 듯 야옹거린다.>)"},objectives={{85,252490101},"하이잘 지역 주변에서 하이잘루트 8개를 모아 하이잘의 노르다나르에 있는 엔토스에게 가져가세요."},progress={{89,883038309},"파라누스는 의지가 강하지만, 그의 힘이 약해지는 것은 시간 문제일 뿐이다."},completion={"You have done it. With this Hyjalroot I will be able to bring Paranus back from the edge, and guide him away from the dream. I must thank you $c. Without you, I would have been lost in grief.$B$BTake this Small Dream Shard, as thanks for everything you've done.","해냈군요. 이 하이잘루트로 파라누스를 절망의 벼랑 끝에서 구해내고 꿈에서 벗어나게 할 수 있을 겁니다. 정말 고맙습니다,$c. 당신이 아니었다면 저는 슬픔에 잠겨 길을 잃었을 겁니다.$B$B, 모든 것에 대한 감사의 표시로 이 작은 꿈 조각을 받아가세요."}}
rows[40871]={title={{21,1833209833},"하이잘루트 비축"},description={{449,881502047},"파라누스를 구하기 위한 당신의 노력에 영원히 감사드립니다. 하지만 생각해 보니, 이 전쟁이 끝나고 에메랄드 드림이 복원되면, 많은 이들이 다시 세상으로 돌아오기 위해 하이잘루트가 필요할 것입니다. 저는$B$B 지금부터 하이잘루트를 비축해 두는 것이 중요하다고 생각합니다. 만약 당신이 하이잘루트 8개를 모으면 제게 돌아오십시오. 당신의 노고에 대한 보답으로 작은 꿈 조각을 드리겠습니다."},objectives={{85,252490101},"하이잘 지역 주변에서 하이잘루트 8개를 모아 하이잘의 노르다나르에 있는 엔토스에게 가져가세요."},progress={{37,41836219},"하이잘루트를 가지고 돌아오셨나요?"},completion={"More for my stockpile! Thank you again for your efforts $c. Please, once again, take this Small Dream Shard as a token of my thanks.","제 비축량에 또 하나 추가됐네요!$c님, 다시 한번 수고해주셔서 감사합니다. 감사의 표시로 이 작은 꿈 조각을 받아주세요."}}
rows[40872]={title={{23,1983721380},"동반자: 리틀 폰"},description={{270,1295266678},"노르드라실 주변을 순찰하던 중, 저는 특이한 손님을 만나게 되었습니다. 이 지역의 야생 동물 중 하나인 작은 새끼 사슴 한 마리가 제게 다가왔습니다. 하이잘에서 당신이 기울인 노력에 대한 보상으로, 이 새끼 사슴이 당신의 충실한 동반자가 되도록 해드리겠습니다."},objectives={{74,217871726},"하이잘의 노르다나르에서 에반딜 나이트윈드를 위해 밝은 꿈 조각 50개를 모으세요."},progress={{30,1436192723},"그래서, 선택하셨나요?"},completion={{91,977804650},"세계수 주변 야생 동물들의 신뢰를 얻은 것은 행운이라고 여겨진다."}}
rows[40873]={title={{31,849195885},"꿈의 파편 엘릭서의 제조법"},description={{332,507507536},"가장 중요하고 희귀한 영약에 대한 지식을 얻고자 한다면 제대로 찾아오셨습니다. 하이잘에서의 당신의 노고에 대한 보답으로, 저는 선조들의 지식을 당신에게 전수해 드릴 수 있습니다. 꿈의 파편 영약은 매우 강력한 연금술적 혼합물입니다. $B$B이 영약을 사용하면 전세를 역전시킬 수 있을 것입니다."},objectives={{74,217871726},"하이잘의 노르다나르에서 에반딜 나이트윈드를 위해 밝은 꿈 조각 50개를 모으세요."},progress={{30,1436192723},"그래서, 선택하셨나요?"},completion={{166,1816014692},"경고하지만, 이 레시피는 현명하게 사용해야 합니다. 재료를 잘못 사용하면 꿈의 파편 엘릭서의 정반대 효과를 가진 물질을 만들어낼 수 있습니다.$B$B이 레시피를 꼼꼼히 따라 하시길 바랍니다."}}
rows[40874]={title={{29,519670372},"명료함의 물약 제조법"},description={{327,954956953},"오래전 하이잘의 드루이드들은 마시는 사람을 깨어 있게 하고 에메랄드 꿈의 유혹에 저항하게 하는 명료함의 물약을 만드는 법을 터득했습니다. 하이잘에서 당신이 행한 공적에 대한 보답으로, 저는 당신에게 이 물약 제조법을 드리고자 합니다. 밝은 꿈의$B$B 조각을 모아 주십시오. 그러면 당신 또한 악몽의 유혹에서 벗어나 명료함을 유지할 수 있을 것입니다."},objectives={{74,217871726},"하이잘의 노르다나르에서 에반딜 나이트윈드를 위해 밝은 꿈 조각 50개를 모으세요."},progress={{30,1436192723},"그래서, 선택하셨나요?"},completion={{203,459997502},"한 모금만 마시면, 당신을 잠으로 이끄는 강력한 힘에도 굴복하지 않고 깨어 있을 수 있습니다.$B$B하지만 명료함의 물약을 과도하게 사용하지 않는 것이 좋습니다. 수면 부족으로 미쳐버린 사례가 몇 건 알려져 있습니다."}}
rows[40875]={title={{28,1941690246},"패턴: 마법 갑옷 키트"},description={{326,1954519539},"오래 전 하이잘의 드루이드들은 갑옷을 강화하기 위해 강력한 가죽세공 비법을 개발했습니다. $B$B이 갑옷 세트에는 드루이드 마법의 힘이 고스란히 담겨 $B$B있습니다. 원하신다면 노르다나르에서 저희를 도와주시는 대가로 이 비법을 드리겠습니다. 당신과 당신의 동료들에게 큰 도움이 될 것입니다."},objectives={{74,217871726},"하이잘의 노르다나르에서 에반딜 나이트윈드를 위해 밝은 꿈 조각 50개를 모으세요."},progress={{30,1436192723},"그래서, 선택하셨나요?"},completion={"A wise decision $c. I would recommend using these smelling salts with care. They are extremely strong and should not be used for any sort of practical joking.","현명한 결정입니다,$c님. 이 암모니아수는 조심해서 사용하시길 권합니다. 향이 매우 강하므로 장난으로 사용해서는 안 됩니다."}}
rows[40876]={title={{19,1021514859},"결속의 뿔"},description={{665,380195040},"저는 제3차 전쟁으로 땅이 상처 입기 훨씬 전, 하이잘의 드루이드 수련생이었습니다. 그곳에서 드루이드 마법의 심오한 가르침들을 배울 기회를 얻었고, '결속의 뿔'이라는 아이템을 만드는 법을 익혔습니다. 저는 윈터스프링의$B$B 자연 에너지와 결속할 새로운 뿔을 제작하려고 노력하고 있지만, 이 땅과 하이잘 곳곳에서 더 많은 재료가 필요합니다. 필요한 재료는 다음과 같습니다.$B$B 하이잘에 서식하는 큰뿔올빼미의 부리, 그곳에 사는 사티로스에게서 얻을 수 있는 사향뿔, 노르다나르에서 찾을 수 있는 '자연의 결속'이라는 책, 그리고 마지막으로 윈터스프링에 사는 올빼미 짐승에게서 얻을 수 있는 달빛의 부적입니다."},objectives={{156,680638423},"윈터스프링의 스타폴 마을에 있는 에버윌 문시커에게 그레이트혼 부리 6개, 바일머스크 뿔 1개, '자연의 힘' 책, 그리고 달빛의 부적을 모으세요."},progress={{101,616870749},"이러한 물질들을 구하는 것은 위험할 수 있으므로, 찾을 때 각별히 주의해 주시기 바랍니다."},completion={"The creation of the Horn of Binding shall finally begin, in no small part thanks to your courageous and selfless efforts, $N. It will no doubt take me many days, or even weeks, to read through this old book and remember the steps necessary to finish this ordeal.$B$BI must thank you for what you have done for me. Please, take these items. They are tokens of my time spent in Hyjal, many long years ago... May they serve you better than collecting dust here with me at Starfall Village.","결속의 뿔 제작이 마침내 시작될 것입니다.$N님, 당신의 용감하고 헌신적인 노력 덕분입니다. 이 낡은 책을 읽고 이 시련을 끝내는 데 필요한 단계를 기억해내는 데 며칠, 아니 몇 주가 걸릴지도 모르겠습니다.$B$B님, 저를 위해 해주신 일에 진심으로 감사드립니다. 이 물건들을 받아주십시오. 오래전 하이잘에서 보낸 제 시간을 기념하는 물건들입니다. 별똥별 마을에서 먼지만 쌓이게 두는 것보다 당신에게 더 도움이 되기를 바랍니다."}}
rows[40877]={title={{15,1922546197},"어둠이 올 때까지 죽은"},description={"Listen, $r. We face no shortage of troubles here, but I shan't waste your time with mindless errands. Dealing with the pests and beasts that torment our camp is a task I can handle myself.$B$BHowever, I do require your aid in a matter of greater importance. One of our own, Orvan Darkeye, came to Gilneas in search of the lost tomes of Archmage Ur. Yet, the irony of it all - he himself became lost. $B$B<Deathstalker Alynna's twisted smile conveys her amusement at the situation.>$B$BYour mission is clear: find him, or what little is left of him. Last we heard, he was headed towards Greyshire.","들어보세요,$r . 여기는 골칫거리가 끊이지 않지만, 쓸데없는 심부름으로 당신의 시간을 낭비하고 싶진 않습니다. 우리 진영을 괴롭히는 해충과 짐승들을 처리하는 건 제가 직접 할 수 있는 일입니다.하지만 $B$B더 중요한 일에 당신의 도움이 필요합니다. 우리 동료 중 한 명인 오르반 다크아이가 대마법사 우르의 잃어버린 고서를 찾으러 길니아에 왔습니다. 그런데 아이러니하게도 그 자신도 길을 잃었습니다. <데스스토커 알리나의 비뚤어진 $B$B미소가 상황을 재밌어하는 듯했다.>당신의 임무는 분명합니다. 그를, 아니면 그에게 $B$B남은 얼마 안 되는 흔적이라도 찾아내십시오. 마지막으로 들은 소식으로는 그가 그레이샤이어 쪽으로 향하고 있다고 합니다."},objectives={{106,1155069802},"데스스토커 알리나를 위해 오르반 다크아이를 찾아주세요. 그가 그레이샤이어 유적 근처에 있다는 소문이 있습니다."},progress={{5,921233587},"무엇?"},completion={{332,1462935305},"뭐라고? 저 멍청한 얼간이가 내가 길을 잃었다고 생각하는 건가?$B$B<오르반이 음침하게 웃는다>$B$B재밌군. 한심한 놈 하나가 줄었군. 보시다시피, 난 내 앞길을 충분히 돌볼 수 있지. 하지만 운명이 자네를 이곳으로 데려온 것 같군. 솔직히 말해서, 하인이 필요하긴 하지. 그리고 자네는, 내 사랑, 그 일에 딱 맞는 사람 같군."}}
rows[40878]={title={{20,329791667},"우리에게 필요한 건 피뿐"},description={{556,969600919},"저는 특정한 책을 찾아 이 땅에 왔습니다. 오랫동안 찾아 헤맨 바로 그 책, 대마법사 우르의 '피의 힘에 대하여'입니다. 아, 그토록 찾기 힘들었던 책이었죠! 하지만 이제 길니아스 어딘가에 숨겨져 $B$B있을지도 모른다는 단서를 얻었습니다. 그 책에 담긴 지식은 언데드와 호드 모두의 목표 달성에 매우 귀중한 자료가 될 것입니다. 거의 다 찾아왔지만, 그전에 당신의 도움이 필요합니다. 이 작은 병들을 받아 박쥐의 피를 모아 주십시오. 우리의 계획에 꼭 필요할 겁니다. 저를 실망시키지 마십시오."},objectives={{85,608409046},"길네아의 그레이샤이어 유적에 있는 오르반 다크아이에게 바일윙 피병 10개를 가져다 주세요."},progress={{60,1539818764},"혈액 채취는 이미 하셨나요? 혈액 샘플 10개가 필요해요."},completion={{191,1694336153},"아, 훌륭합니다. 제가 필요했던 것을 가져다주셨군요.$B$B오르반은 약병들을 받아 들고 섬뜩한 미소를 지으며 살펴보더니 갑자기 뒤로 던져버렸다.$B$B이것들은 정말 귀중할 것입니다."}}
rows[40879]={title={{23,1649351250},"살아있는 시체들의 마지막"},description={{520,476975088},"그레이메인은 이 성벽 뒤에 숨으면 ​​안전하다고 생각했을지 모르지만, 죽음으로부터 숨을 수 있다고 믿었던 건 어리석은 짓이었다. 이제 그의 무능함이 그에게, 그리고 더 나아가 나에게까지 되돌아오고 있다. 스컬지는 여전히 이 땅에 도사리고 있으며, 끊임없이 내 연구를 방해하고 진척을 늦추고 있다. 이제 우리가 직접 나서야 할 때다.$B$B 나는 네게 그레이샤이어에 남아있는 스컬지 세력을 소탕하라고 명한다.$B$B 나를 실망시키지 마라. 실패는 용납할 수$B$B 없다. <포세이큰의 눈이 차갑고 계산적인 기세로 가늘어졌다.>"},objectives={{103,394424107},"길네아의 그레이샤이어 폐허에서 오르반 다크아이를 위해 비틀거리는 망령 8마리와 남아있는 해골 8마리를 처치하세요."},progress={{144,1651277386},"뭘 기다리고 있는 겁니까? 당장 뿌리 뽑아 완전히 섬멸하십시오. 그들이 여기에 있는 것은 포세이큰에 대한 모욕이며 우리 작전에 대한 위협입니다."},completion={{546,951582256},"스컬지 세력이 완전히 소탕된 것은 아닌 것 같지만, 그럼에도 불구하고 여러분의 노고에 찬사를 보냅니다. 여러분의 노력 덕분에 이 땅에 대한 그들의 영향력이 약해졌고, 당분간은 그것으로 충분할 것입니다. 우리는 적, 특히 스컬지를 결코 과소평가해서는 안 됩니다. 그들은 끝까지 사악한 리치 왕을 섬기는 무자비한 세력입니다.$B$B그런데, 이곳을 침공한 스컬지 사령관은 어떻게 되었을까요? 패배한 것일까요, 아니면 숨어서 리치 왕의 명령을 기다리고 있는 것일까요?"}}
rows[40880]={title={{26,74301621},"우리는 살아있는 사람들로부터 그것을 얻는다"},description={{781,977466274},"솔직히 말해서, 자네는 유용한 하인임을 증명해냈고, 이 시대에 자네의 맹목적인 충성심은 참으로 보기 드문 것이네. 하지만 고백하건대, 처음에는 자네에게 완전히 솔직하지는 못했네. 내 개인적인 목표는 우르의 작품을 찾는 것이지만, 동시에 왕립 약제사 협회의 임무도 수행하러 온 것이네. 우리는 길니아스가 호드의 적들을 상대할 새로운 무기를 완성하기에 완벽한 장소라고 생각하지만, 그러기 위해서는$B$B 더 많은 피가 필요하네. 인간의 피와 늑대인간의 피 말이지. 아주 미묘한 균형이 필요해. 이 약병들을 가지고 스틸워드 교회 남쪽으로 가도록 해. 그곳에 그레이메인의 군대가 있을 거야. 그들에게서 필요한 피를 얻는 건 그리 어렵지 않을 테지. 늑대인간의 피는… 뭐, 어떻게든 자네에게 올 테니까. 그들이 나타날 때를 대비해 두도록 해."},objectives={{98,192086510},"그레이샤이어 폐허에 있는 오르반 다크아이에게 길네아 혈액병 15개와 늑대인간 혈액병 15개를 가져다주세요."},progress={{30,613520863},"내 종아, 어서 움직여라."},completion={{114,1173998287},"정말 인상적이군. 이 피가 내가 만든 혼합물과 어떻게 반응할지 한번 보자. 내 계산이 맞다면…"}}
rows[40881]={title={{22,60187703},"악이 나를 그렇게 만들었다"},description={{780,291504267},"제가… 계산을 좀 잘못한 것 같습니다. '피의 힘'에 담긴 지식 없이는 혼합물을 안정시킬 수 없는 것 같습니다. 그 책이 필요합니다. 이$B$B 땅 구석구석을 샅샅이 뒤져봤지만 찾지 못했습니다. 이는 단 한 가지를 의미합니다. 그 책은 길네아스 도시 안에 숨겨져 있다는 것입니다. 길네아스는 난공불락의 요새처럼 우뚝 솟아 있고, 그 성벽 안에서 책 한 권을 찾는다는 생각만 해도 벅찹니다.$B$B 도시는 철저하게 요새화되어 있고, 그곳에 주둔한 인간 군대는 만만치 않습니다. 그들은 남은 얼마 안 되는 것을 지키기 위해 필사적으로 싸울 것이며, 도시를 지키기 위해서라면 무슨 일이든 서슴지 않을 것입니다. 그들의 방어선을 뚫으려면 당신의 모든 지략과 은밀함이 필요할 것입니다. 하지만$B$B 만약 당신이 그 책을 찾아낸다면… 제가 헤아릴 수 없는 보상을 드리겠습니다."},objectives={{113,73547631},"길니아스 도시에서 '피의 힘에 대하여'를 찾은 다음, 길니아스에 있는 그레이샤이어 유적의 오르반 다크아이에게 돌아가십시오."},progress={{38,877783094},"내가 해온 모든 일이 헛된 것이었을까?"},completion={{739,265238470},"아, 드디어! 온갖 장애물과 좌절 끝에 우르의 걸작을 손에 넣었다! 혈마법의 비밀, 그리고 생명의 정수를 조종하는 힘! 이 책만 있으면 나는 무적의 존재가 될 것이고, 포세이큰의 적들은 내 앞에서 떨 것이다.$B$B<포세이큰은 흥분에 겨워 낄낄거리며 책장을 넘겼다.>$B$B우르는 분명 대가였지. 하지만 그조차도 혈마법의 진정한 잠재력을 완전히 이해하지는 못했어. 이 책에 담긴 지식으로 나는 그를 뛰어넘어 세상 역사상 가장 위대한 혈마법사가 될 것이다.$B$B<포세이큰은 사악한 미소를 지으며 올려다보았다.>$B$B충실한 부하여, 너는 나를 잘 섬겼다. 그 보답으로 우리가 곧 휘두르게 될 힘의 작은 맛을 보여주겠다."}}
rows[40882]={title={{15,1390241309},"피에는 피"},description={{838,79017480},"언데드의 새로운 시대가 도래했다! 이 책을 길잡이 삼아, 나는 피의 차원의 비밀을 밝히고 그 힘을 우리의 대의를 위해 $B$B이용하겠다. 오르반 다크아이는 책에 적힌 단계를 꼼꼼하게 따라가며 피와 끈적끈적한 녹색 혼합물을 섞었다. 잠시 후, 그는 사악한 미소를 지으며 당신을 바라보았다.$B$B 자, 이제 내 최신 발명품의 실험 대상을 찾아야 한다. 네게 억지로 먹이려 했지만, 넌 충실한 하인이었으니 이번에는 봐주겠다. 대신 더 좋은 생각이 있다. 근처에 우리 대의에 충성하는 인간 용병들의 캠프가 있다. 이 혼합물이 그들을 더욱 우리의 임무에 헌신하게 만들지 않을까? 진행하기$B$B 전에 마지막으로 한 가지 부탁을 들어주겠다. 언더시티에 있는 파라넬 주임 약제사에게 보고하여 임무가 성공적이었다고 전해라."},objectives={{50,1387759978},"언더시티에 있는 수석 약제사 파라넬에게 보고하십시오."},progress={{4,273767400},"예?"},completion={{465,1521660718},"결국 오르반이 성공했군. 훌륭하군. 자네는 오늘 언데드와 호드에게 큰 공을 세웠으니 보상을 주겠다. 이 약병을 받아라, 친구. 이 안에는 강력한 약이 들어 있는데, 그 증기를 들이마시기만 해도 자네의 힘이 강해진다. 물론 두통, 구토, 광기, 심지어 죽음과 같은 경미한 부작용이 있을 수 있지만, 자네는 괜찮을 거라고 확신한다. 결국 이 약이 가져다줄 힘에 비하면 작은 위험쯤이야 아무것도 아니지 않겠는가?"}}
rows[40883]={title={{29,1770334902},"마법 부여 부츠: 더 강력한 영혼"},description={{267,44331839},"우리가 알고 있는 마법은 매우 다양합니다. 모든 비밀을 다 알려드릴 수는 없지만, 하이잘에서 우리를 도와주신 데 대한 감사의 표시로 몇 가지 마법 공식을 전수해 드리겠습니다. 혹시 관심 있으시면 강력한 부츠 마법 공식도 하나 알려드리겠습니다."},objectives={{74,217871726},"하이잘의 노르다나르에서 에반딜 나이트윈드를 위해 밝은 꿈 조각 50개를 모으세요."},progress={{30,1436192723},"그래서, 선택하셨나요?"},completion={{112,982155823},"이 마법이 당신과 당신의 동맹들에게 축복이 되기를 바랍니다. 이 마법의 힘은 어려운 전투의 흐름을 바꿀 수도 있을 것입니다."}}
rows[40884]={title={{34,2119779735},"팔찌 마법 부여: 강화된 방어"},description={{269,429505152},"우리가 알고 있는 마법은 매우 다양합니다. 모든 비밀을 다 알려드릴 수는 없지만, 하이잘에서 우리를 도와주신 데 대한 감사의 표시로 몇 가지 마법 공식을 전수해 드리겠습니다. 관심 있으시면 강력한 팔찌 마법 공식도 하나 알려드리겠습니다."},objectives={{74,217871726},"하이잘의 노르다나르에서 에반딜 나이트윈드를 위해 밝은 꿈 조각 50개를 모으세요."},progress={{30,1436192723},"그래서, 선택하셨나요?"},completion={{95,845907202},"여기서는 처짐의 특성에 대해 잘 알고 있습니다. 당신도 이를 잘 활용하실 거라고 확신합니다."}}
rows[40885]={title={{10,1511758511},"드림토닉"},progress={{409,1827698689},"자, 당신은 작은 꿈 조각을 가지고 있나요?"},completion={{55,1018916554},"이 혼합물의 효과는 매우 강렬하니, 천천히 섭취하세요."}}
rows[40886]={title={{19,874217443},"드림스틸 제련"},description={{363,1912909629},"꿈강철을 제련하는 것은 그 자체로 하나의 예술입니다. 꿈강철 막대를 이용해 무늬를 만드는 과정은 복잡하지만, 제련 과정 자체의 가치를 떨어뜨리지는 않습니다.만약$B$B 다른 사람에게 의존하지 않고 직접 꿈강철 막대를 만드는 방법을 배우고 싶다면, 세계수에 대한 충성의 표시로 밝은 꿈 조각 15개를 모아 오십시오."},objectives={{75,1605176142},"하이잘의 노다나아르에 있는 탄토스 에버브리즈를 위해 밝은 꿈 조각 15개를 모아야 합니다."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{144,777367740},"자, 이제 여러분이 알아야 할 모든 것을 가르쳐 줄 책이 바로 이것입니다. 꼼꼼히 공부하고, 책에 나와 있는 기법들을 그대로 적용해 보십시오."}}
rows[40888]={title={{19,2124779682},"드림스틸 레깅스"},description={{379,862905422},"드림스틸을 다루는 것은 매우 복잡한 기술이며, 완벽에 도달하려면 극도의 인내심이 필요합니다.$B$B 이 도전에 응하고 싶다면 드림스틸 레깅스 제작 도면을 드리겠습니다. 단, 노르드라실의 이름으로 당신의 노고에 대한 증표가 필요합니다. 밝은 꿈의 조각 75개면 충분합니다. 그것들을 가져오면 보상을 드리겠습니다."},objectives={{75,578463688},"하이잘의 노르다나르에 있는 탄토스 에버브리즈를 위해 밝은 꿈 조각 75개를 모아야 합니다."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamsteel, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림스틸을 제작하는 법을 처음 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40889]={title={{18,863413607},"드림스틸 브레이서"},description={{378,1812193963},"꿈의 강철을 다루는 기술은 매우 복잡하고, 완벽에 도달하려면 엄청난 인내심이 필요합니다. $B$B이 도전에 응하고 싶다면 꿈의 강철 팔찌 제작 도면을 드리겠습니다. 단, 노르드라실의 이름으로 당신의 노고에 대한 증거가 필요합니다. 밝은 꿈의 조각 75개면 충분합니다. 그것들을 가져오면 보상을 드리겠습니다."},objectives={{75,578463688},"하이잘의 노르다나르에 있는 탄토스 에버브리즈를 위해 밝은 꿈 조각 75개를 모아야 합니다."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamsteel, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림스틸을 제작하는 법을 처음 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40890]={title={{16,1376066996},"드림스틸 부츠"},description={{376,1961364513},"드림스틸을 다루는 것은 매우 복잡한 기술이며, 완벽에 도달하려면 극도의 인내심이 필요합니다.$B$B 이 도전에 응하고 싶다면 드림스틸 부츠 제작 도면을 드리겠습니다. 단, 노르드라실의 이름으로 당신의 노고에 대한 증표가 필요합니다. 밝은 꿈의 조각 75개면 충분합니다. 그것들을 가져오면 보상을 드리겠습니다."},objectives={{75,578463688},"하이잘의 노르다나르에 있는 탄토스 에버브리즈를 위해 밝은 꿈 조각 75개를 모아야 합니다."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamsteel, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림스틸을 제작하는 법을 처음 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40891]={title={{36,1218827258},"나무껍질 부족의 타락"},description={{749,556961874},"바크스킨 부족은 두 명의 장로, 즉 저와 노련한 전사 그로울하트 장로가 다스리고 있었습니다. 그로울하트 장로는 공격적인 성격과 영향력 있는 연설로 명성을 얻은 인물입니다. 저는 $B$B바크스킨 부족의 타락을 그 어떤 전사나 정원사, 곰의 탓으로 돌리지 않습니다. 오로지 그로울하트 장로의 잘못입니다. 그의 통치 기간 동안 그는 점점 더 적대적으로 변했고, 제가 가장 아끼던 친구들을 많이 제거했습니다. 바크스킨 부족을 되살릴 수 $B$B있는 아주 작은 가능성이라도 있다면 그로울하트 장로는 반드시 제거되어야 합니다. 그의 변색된 털을 보면 그를 알아볼 수 있을 겁니다. 그는 자신과 가장 충성스러운 추종자들이 섭취하는 오염된 수액에 중독되어 이런 모습을 갖게 $B$B되었습니다. 바크스킨 마을은 하이잘 계곡 남서쪽, 계곡 바닥 근처에서 찾을 수 있습니다."},objectives={{106,2108288172},"하이잘의 노르다실 글레이드에 있는 바크스킨 마을 깊숙한 곳에서 엘더 그로울하트를 찾아 처치하면 엘더 바크마우를 처치할 수 있습니다."},progress={{88,1273760621},"조심하는 게 좋겠습니다. 바크스킨 마을은 적대감이 넘치고 숙련된 곰들이 우글거리는 곳입니다."},completion={{286,957750572},"그토록 끔찍한 일들이 있은 후 정의가 실현되었다는 사실에 마음의 짐이 덜어지는 것을 느낍니다. 그의 가장 충성스러운 동료들이 그와 함께 싸우다 전사했다는 것을 저는 조금도 의심하지 않습니다.$B$B어떤 말로도 감사를 다 표현할 수 없습니다. 부디 이 물건들을 감사의 표시로 받아주십시오."}}
rows[40892]={title={{13,924986967},"나무껍질 곰치"},description={{553,619345712},"바크스킨 우르사는 부족 내에서 가장 충성스럽고 무시무시한 전사 집단이었습니다. 그들은 그로울하트에게 이끌려 그의 명령에 복종했습니다. $B$B숙청으로 인해 수많은 죽음과 고통이 초래되었습니다. 이 모든 것은 주인의 욕망을 아무런 결과도 생각하지 않고 실행한 우르사들의 소행이었습니다. 나는 당신에게$B$B 바크스킨 마을로 가서 무분별한 살인을 자행한 자들을 처단해 달라고 부탁합니다. 바크스킨 마을은 남쪽 멀리 하이잘 산기슭 근처에 있습니다. 당신의 $B$B공적을 증명하기 위해 우르사 전투망치 네 개를 가져오면 보상을 드리겠습니다."},objectives={{93,1855211701},"하이잘의 놀드랏실 숲에 있는 장로 바크모를 위해 나무껍질 우르사에게서 우르사 전투망치 4개를 모으십시오."},progress={"The ursa should not be taken easily $c. Take your time, and prepare for the coming battle with diligence.","곰을 쉽게 잡아서는 안 됩니다.$c서두르지 말고, 다가올 전투를 부지런히 준비하십시오."},completion={{247,1425113410},"그런 살인자들이 최후를 맞이하고 그들의 행위에 대한 대가를 치렀다는 것을 알게 되니 늙은 마음이 편안해집니다. 저도 직접 볼 수 있었으면 좋았을 텐데요.$B$B당신의 노력에 대한 보답으로, 한때 우리 종족 사이에서 매우 귀중하게 여겨졌던 밝은 꿈의 조각 하나를 드립니다. 부디 잘 사용하시길 바랍니다."}}
rows[40893]={title={{18,989247342},"바크스킨 벤전스"},description={{295,2097756001},"나르그는 악행을 저지른 다른 바크스킨들에게 복수하려 합니다. 바크스킨들은 나르그의 아버지를 포함하여 많은 친구들을 죽였습니다. 부족은 더 $B$B이상 예전의 모습이 아니며, 분노에 차 있고 사악해졌습니다. 나르그는 자신이 할 수 없는 일을 당신에게 부탁합니다. 바크스킨들을 처치하고 바크스킨 펜던트를 되찾으세요. 바크스킨 펜던트는 모든 바크스킨 퍼볼그에게서 찾을 수 있습니다."},objectives={{66,1818717614},"하이잘의 노르다실 숲에서 나르그를 위해 나무껍질 펜던트 10개를 모으세요."},progress={{56,1746555194},"나르그가 부탁한 대로 악한 바크스킨에게 죽음을 가져다주겠소?"},completion={{115,388785778},"나르그는 기뻐하고, 나르그는 행복하다.$B$B마음속 깊은 곳에는 여전히 불꽃이 타오르고, 분노는 가라앉지 않았다. 나르그의 감사의 표시로 이것을 받아라."}}
rows[40894]={title={{28,1210776716},"계속되는 바크스킨 벤전스"},progress={{305,2041063934},"나르그가 부탁한 대로 악한 바크스킨에게 죽음을 가져다주겠소?"},completion={{115,388785778},"나르그는 기뻐하고, 나르그는 행복하다.$B$B마음속 깊은 곳에는 여전히 불꽃이 타오르고, 분노는 가라앉지 않았다. 나르그의 감사의 표시로 이것을 받아라."}}
rows[40895]={title={{18,769777866},"드림하이드 제작하기"},description={{320,239137209},"제 작품을 감상하러 오셨습니까? 이렇게 귀한 가죽을 보러 먼 길을 오신 것을 칭찬하지만… 뭐라고요? 제 비법을$B$B 배우러 오셨다고요? 흠… 그럴지도 모르죠. 우리 대의에 충성하는 자들에게 드림하이드를 다루는 법을 가르치는 책을 준비했지만, 그 책을 드리려면 당신에게서 브라이트 드림 샤드를 받아야 합니다."},objectives={{72,1751787967},"하이잘의 노르다나르에서 밝은 꿈 조각 15개를 모아 잔셀의 별가루를 구입하세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{144,777367740},"자, 이제 여러분이 알아야 할 모든 것을 가르쳐 줄 책이 바로 이것입니다. 꼼꼼히 공부하고, 책에 나와 있는 기법들을 그대로 적용해 보십시오."}}
rows[40897]={title={{17,370225862},"드림하이드 브레이서"},description={{300,1672838256},"나는 내 가장 소중한 패턴을 자칭 가죽공예가라는 자들에게 넘겨줄 생각이 없다. 내 훌륭한 작품을 만들 기회를 얻으려면 헌신과 의지를 보여줘야 한다. 드림하이드 $B$B브레이서 패턴을 배우고 싶다면 브라이트 드림 샤드 75개를 가져오라."},objectives={{72,2095639410},"하이잘의 노르다나르에서 밝은 꿈 조각 75개를 모아 잔셀의 별가루를 구입하세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamhide, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림하이드를 처음 만들고 제작하는 법을 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40898]={title={{18,1941694497},"드림하이드 레깅스"},description={{301,96351361},"나는 내 가장 소중한 패턴을 자칭 가죽공예가라는 자들에게 넘겨줄 생각이 없다. 내 훌륭한 작품을 만들 기회를 얻으려면 헌신과 의지를 보여주는 견습생을 원한다. 드림하이드$B$B 레깅스 패턴을 배우고 싶다면 브라이트 드림 샤드 75개를 가져오세요."},objectives={{72,2095639410},"하이잘의 노르다나르에서 밝은 꿈 조각 75개를 모아 잔셀의 별가루를 구입하세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamhide, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림하이드를 처음 만들고 제작하는 법을 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40899]={title={{14,1650180911},"드림하이드 벨트"},description={{297,1874924173},"나는 내 가장 소중한 패턴을 자칭 가죽공예가라는 자들에게 넘겨줄 생각이 없다. 내 훌륭한 작품을 만들 기회를 얻으려면 헌신과 의지를 보여주는 견습생을 원한다. 드림하이드$B$B 벨트 패턴을 배우고 싶다면 브라이트 드림 샤드 75개를 가져오라."},objectives={{72,2095639410},"하이잘의 노르다나르에서 밝은 꿈 조각 75개를 모아 잔셀의 별가루를 구입하세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamhide, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림하이드를 처음 만들고 제작하는 법을 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40900]={title={{20,1967923596},"꿈의 실타래 만들기"},description={{309,1423528919},"나는 오랜 세월 동안 세계수 아래에서 기술을 연마해 왔다. 맑은 정신이 손가락을 이끌고 상상력을 발휘하게 한다. 하이잘을 도운 $B$B당신의 노력에 대한 보답으로, 내 모든 지식이 담긴 책을 드리겠습니다. 밝은 꿈의 조각 15개를 가져오시면 제 기술을 배우실 수 있습니다."},objectives={{72,1751787967},"하이잘의 노르다나르에서 밝은 꿈 조각 15개를 모아 잔셀의 별가루를 구입하세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{144,777367740},"자, 이제 여러분이 알아야 할 모든 것을 가르쳐 줄 책이 바로 이것입니다. 꼼꼼히 공부하고, 책에 나와 있는 기법들을 그대로 적용해 보십시오."}}
rows[40902]={title={{16,1256905402},"드림스레드 킬트"},description={{315,1648310371},"고요함. 그것이 바로 드림스레드 작업을 위해 필요한 것입니다. 노르드라실 아래에서는 꿈결 같은 상태에 빠지기 쉽습니다. 드림스레드 킬트를 만들 수 있는 도안을 드릴 수 있습니다. 하지만 당신의 노고에 대한 증표가 $B$B필요합니다. 밝은 꿈 조각 75개를 가져오시면 보상을 드리겠습니다."},objectives={{72,2095639410},"하이잘의 노르다나르에서 밝은 꿈 조각 75개를 모아 잔셀의 별가루를 구입하세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamthread, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림스레드를 만드는 법을 처음 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40903]={title={{19,1189085001},"드림스레드 브레이서"},description={{318,1713509635},"고요함. 그것이 바로 드림스레드 작업을 위해 필요한 것입니다. 노르드라실 아래에서는 꿈결 같은 상태에 빠지기 쉽습니다. 드림스레드 팔찌 제작법을 알려드릴 수 있습니다. 하지만 당신의 노고에 대한 증표가 필요합니다.$B$B 밝은 꿈 조각 75개를 가져오시면 보상을 드리겠습니다."},objectives={{72,2095639410},"하이잘의 노르다나르에서 밝은 꿈 조각 75개를 모아 잔셀의 별가루를 구입하세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamthread, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림스레드를 만드는 법을 처음 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40904]={title={{18,1619008938},"드림스레드 장갑"},description={{317,455555193},"고요함. 그것이 바로 드림스레드 작업을 위해 필요한 것입니다. 노르드라실 아래에서는 꿈결 같은 상태에 빠지기 쉽습니다. 드림스레드 장갑 제작 도안을 드릴 수 있습니다. 하지만 당신의 노고에 대한 증표가 필요합니다.$B$B 밝은 꿈 조각 75개를 가져오시면 보상을 드리겠습니다."},objectives={{72,2095639410},"하이잘의 노르다나르에서 밝은 꿈 조각 75개를 모아 잔셀의 별가루를 구입하세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={"I remember the day I first learned to craft and create Dreamthread, it was a most rewarding experience.$B$BMay this recipe serve you well, $N.","드림스레드를 만드는 법을 처음 배웠던 날이 기억납니다. 정말 보람찬 경험이었죠.$B$B이 레시피가 당신에게 도움이 되기를 바랍니다.$N"}}
rows[40905]={title={{24,1848167434},"타오르는 꿈의 정수"},description={{264,1102084583},"타오르는 꿈의 정수를 만지는 순간, 강렬한 에너지가 온몸에 퍼져나갑니다. 손끝에서 에메랄드 꿈의 힘이 느껴지며, 행동을 촉구하는 듯합니다. 어쩌면 노르다나르 안에는 이러한 힘에 익숙한 누군가가 있을지도 모릅니다."},objectives={{81,1211335181},"하이잘의 노르다나르에 있는 대드루이드 드림윈드에게 타오르는 꿈의 정수를 가져다 주세요."},progress={{33,48083328},"당신이 내게 가져온 것은 무엇입니까?"},completion={{246,1711939888},"이렇게 온전한 꿈의 정수를 본 건 정말 오랜만입니다. 아제로스에서 그 흔적이 완전히 사라졌다고 생각했는데, 틀렸군요.$B$B이 샘플에는 타락이 깊숙이 스며들어 있지만, 점차 약해지고 있습니다. 정화하는 건 어렵지 않을 겁니다."}}
rows[40906]={title={{22,1011551081},"정화된 꿈의 정수"},description={{524,166796569},"솔직히 말해서, 다시 꿈의 정수를 다룰 수 있게 되어 꽤나 향수를 느낍니다. 정말 오랜만에 이 즐거움을 누리게 되었군요. 이 샘플을 복원하려면 아제로스 곳곳에서 구할 수 있는 다음 재료들이 필요합니다.$B$B 하이잘에서 밝은 꿈 조각 10개를 구해야 합니다. 마법 분해를 할 수 있는 자에게서 꿈의 가루 25개를 얻어야 하고요. 마지막으로 생명의 정수 15개가 필요한데, 구하기가 꽤 까다롭습니다. 이 재료들을 가져다주시면 에메랄드 축복을 드리겠습니다."},objectives={{116,1519966828},"하이잘의 노르다나르에 있는 대드루이드 드림윈드에게 밝은 꿈 조각 10개, 꿈의 가루 25개, 생명의 정수 15개를 모으세요."},progress={{47,2112267451},"재료는 다 모았습니까, 동료 드루이드?"},completion={{179,1403848696},"완성되었습니다. 꿈의 정수가 정화되어 당신의 품에 안기기를 기다리고 있습니다.$B$B모든 드루이드가 이런 마법을 사용할 기회를 얻는 것은 아닙니다. 젊은이여, 이 마법은 아껴 쓰고 매우 신중하게 사용해야 합니다."}}
rows[40907]={title={{33,1438601664},"알리아탄 앤더슨의 유령"},description={{735,31506008},"당신이 다가가자 남자의 눈이 휘둥그레지며 숨을 멈췄다. 그러더니 숨을 크게 내쉬며 몸을 떨기 시작했다. \"도와주세요. $B$B도와주세요. 그녀는... 어디에나 있어요. 그런데도 어디에도 없어요! 제발... 그녀가 사라지길 바라요! 제발... (그는$B$B 떨리는 손가락으로 숲 쪽을 가리켰다.) 저는... $B$B그들의 춤을 추고 싶지 않아요. 그들의... 그들의... 원에 합류하고 싶지도 않아요. 그들의 어두운 원, 죽음의 그림자에... 제발! 남서쪽, 제가 마지막으로 야영했던 그레이셔 마을 근처, 거기서 모든 게 시작됐어요! 저는... 제 일기를 거기 두고 왔어요. 제발 야영지를 살펴보고 제 일기를 찾아서 울프스우드의 펠러 가문에 가져다 주세요. 그들은... 뭔가 알고 있을 거예요... 도와주세요. 이렇게는 더 이상 살 수 없어요...\""},objectives={{104,1676068180},"숲속 야영지에서 알리아탄 앤더슨의 일기를 찾아 울프스우드의 펠러 가문에 가져다주세요."},progress={"I see discouragement and concern on your face, $N. What ails you so?","$N님, 얼굴에 실망과 걱정이 가득한 것 같네요. 무슨 일이 있으신가요?"},completion={{237,212012554},"과부들이 이처럼 젊은이에게 그토록 깊은 관심을 보이는 것을 들은 지 정말 오래되었군요. 부럽지 않은 운명입니다. 우리 펠러 가문은 이 땅의 선량한 백성들을 위해 충실히 봉사해 왔습니다. 제게 조언을 구할 테니 귀 기울여 주십시오."}}
rows[40908]={title={{15,1181120105},"블랙 왈츠"},description={"The Widows of the Wood are a fickle lot, $N. They hold a strong attachment to the woods. They are playful, yet spiteful. They rejoice in scaring children, luring young men away to rest beneath the canopies they haunt, appearing in their dreams.$B$BI fear we have not much time to save young Aliattan if his journal is anything to go by. They seek to break his will, and draw him into a maddening dance known as the black waltz. They say the soul itself is wrenched from the body with each twirl and spin, before being devoured by the hungry Widows.$B$BReturn to the campsite, $N. You must light that which caused so much grief to begin with. Draw them out of hiding, and dispose of them. May the Wolf Serpent guard you, for a fate worse than death awaits you if you anger the Widows and fail in your efforts.","숲의 과부들은 변덕스러운 무리입니다, $N. 그들은 숲에 강한 애착을 가지고 있습니다. 장난스럽지만 악의적입니다. 아이들을 겁주고, 젊은이들을 유인하여 그들이 출몰하는 숲의 그늘 아래에서 쉬게 하고, 꿈속에 나타나는 것을 $B$B즐깁니다.  알리아탄의 일기를 보니 그를 구할 시간이 얼마 남지 않은 것 같습니다. 그들은 알리아탄의 의지를 꺾고, 검은 왈츠라고 알려진 광기의 춤으로 끌어들이려 합니다. 그들은 춤을 출 때마다 영혼이 육체에서 뜯겨져 나가 굶주린 과부들에게 잡아먹힌다고 합니다. 야영지로 돌아가십시오,$B$B . 그토록 많은$N 고통을 초래한 것에 불을 붙여야 합니다. 그들을 숨어 있는 곳에서 끌어내어 처치하십시오. 늑대뱀이 당신을 지켜주기를 바랍니다. 과부들을 화나게 하고 실패한다면 죽음보다 더 끔찍한 운명이 당신을 기다릴 것입니다."},objectives={{130,1399642160},"알리아탄 앤더슨을 괴롭히는 과부들을 쫓아내려면 그레이셔 마을 근처 남서쪽 숲에서 모닥불을 피우세요."},progress={{26,867693877},"그... 당신은... 성공했나요?"},completion={{169,1248497323},"나… 나 한 시간 넘게 죽음의 한기를 못 느꼈어… 나… 나 효과가 있었던 것 같아. 맹세컨대, 정말 효과가 있었던 것 같아! 정말 고마워! 내 삶은 다시 내 것이 되었어."}}
rows[40909]={title={{14,1831260455},"적대적인 사절들"},description={{529,66217217},"하이잘의 적들은 날이 갈수록 늘어나고 있습니다. 저는 무기를 제작하는 법은 모르지만, 드루이드 무기를 만드는 데에는 마법의 토륨이 많이 필요하다는 것을 알고 있습니다. 따라서 우리가 만반의 준비를 갖추는 것이 제 임무입니다.$B$B 만약 노르다나르에서 저희를 도와주실 의향이 있으시다면, 언제든 밝은 꿈의 조각 두 개를 마법의 토륨 열 개로 교환해 드릴 수 있습니다."},objectives={{97,1230734519},"하이잘의 노르드라실 숲에서 프룰그 의장을 위해 겨울의 사자와 죽은 나무의 사자를 처치하십시오."},progress={{36,294331031},"내 부패한 형제들을 죽였느냐?"},completion={{167,1181853708},"감탄스럽군. 바크스킨 마을 깊은 곳에서 돌아와 내 부탁을 들어주다니.$B$B감사의 표시로 이 밝은 꿈의 조각과 갑옷을 주겠다."}}
rows[40910]={title={{22,1713770843},"신속의 인장"},description={{321,1173158877},"신속의 문장에는 속도의 힘이 깃들어 있습니다. 이 문장의 에너지를 사용하면 더욱 빠른 속도로 공격할 수 있게 됩니다. 이$B$B 문장을 원하신다면 밝은 꿈 조각 다섯 개와 희미해지는 꿈 조각 하나가 필요합니다. 하이잘에서 당신이 이룬 업적을 증명할 수 없이는 그냥 드릴 수 없습니다."},objectives={{100,931264436},"하이잘의 노르다나르에서 바에나르 할로우스타를 위해 밝은 꿈 조각 5개와 희미해지는 꿈 조각 1개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{152,646000109},"<바에나르는 잠시 생각에 잠긴 채 꿈의 조각들을 바라본다.>$B$B잘했구나. 나는 약속을 지켰다. 이 문장을 받아라. 그 힘이 너에게 도움이 되기를."}}
rows[40911]={title={{21,651366937},"흡혈의 인장"},description={{325,120557616},"흡혈의 문장에는 어둠의 힘이 깃들어 있습니다. 이 문장의 에너지를 사용하면 상대방의 정수를 빨아들일 수 있습니다. 이 문장을$B$B 원한다면 밝은 꿈의 조각 다섯 개와 희미해지는 꿈의 조각 하나가 필요합니다. 하이잘에서 당신이 이룬 업적을 증명할 수 없이는 그냥 드릴 수 없습니다."},objectives={{100,931264436},"하이잘의 노르다나르에서 바에나르 할로우스타를 위해 밝은 꿈 조각 5개와 희미해지는 꿈 조각 1개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{152,646000109},"<바에나르는 잠시 생각에 잠긴 채 꿈의 조각들을 바라본다.>$B$B잘했구나. 나는 약속을 지켰다. 이 문장을 받아라. 그 힘이 너에게 도움이 되기를."}}
rows[40912]={title={{24,1337977730},"관통의 인장"},description={{325,744040131},"관통의 문장에는 강력한 마법이 깃들어 있습니다. 이 문장의 에너지를 사용하면 단단한 갑옷도 더욱 깊숙이 꿰뚫을 수 있게 됩니다. $B$B이 문장을 원하신다면 밝은 꿈의 조각 다섯 개와 희미해지는 꿈의 조각 하나가 필요합니다. 하이잘에서 당신이 이룬 업적을 증명할 수 없이는 그냥 드릴 수 없습니다."},objectives={{100,931264436},"하이잘의 노르다나르에서 바에나르 할로우스타를 위해 밝은 꿈 조각 5개와 희미해지는 꿈 조각 1개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{152,646000109},"<바에나르는 잠시 생각에 잠긴 채 꿈의 조각들을 바라본다.>$B$B잘했구나. 나는 약속을 지켰다. 이 문장을 받아라. 그 힘이 너에게 도움이 되기를."}}
rows[40913]={title={{18,1187770226},"활의 숙달"},description={{314,1377027021},"제 목표는 엘룬의 인도하심을 따르며, 제가 쏘는 모든 화살은 진실입니다. 부정적인 말을 하는 사람들의 말에 속지 마세요. 헌신이야말로 $B$B최고의 스승입니다. 제가 모든 것을 가르쳐드릴 수는 없지만, 장기적으로 도움이 될 기술들을 기꺼이 공유해 드리겠습니다. 밝은 꿈의 조각 50개를 가져오시면, 그 대가로 제 지식을 드리겠습니다."},objectives={{74,220404999},"하이잘의 노르다나르에서 사냥꾼 엘다사나를 위해 밝은 꿈 조각 50개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{145,623609851},"약속드린 대로, 제가 수년간 쌓아온 전문 지식을 공유합니다.$B$B시간을 내어 공부하고 연습하세요. 결국 헌신에는 인내가 필요합니다."}}
rows[40914]={title={{20,1367835974},"수수께끼의 편지"},description={{300,362962702},"편지가 당신 앞에 나타납니다. 봉인은 되어 있지 않지만, 전혀 손대지 않은 상태입니다. 편지 안쪽에는 거칠고 조잡한 필체로 휘갈겨 쓴 글씨가 있는데, 단어 하나하나가 낯설게 $B$B느껴집니다. 뭔가 몹시 잘못된 것 같습니다. 낯익으면서도 섬뜩한 목소리가 머릿속에 떠오르고, 당신은 카라잔 근처에 있는 주인의 지하 저장고로 이끌립니다."},objectives={{76,1824493676},"데드윈드 패스에 있는 마스터스 셀러에서 이 신비로운 에너지를 찾아보세요."},progress={{10,1884752158},"<침묵.>"},completion={{135,1653722966},"<익숙한 목소리가 당신의 마음속으로 파고든다.>$B$B잘 왔군. 이 편지를 보낸 자는 이미 나를 실망시켰지만, 자네는 그러지 않겠지."}}
rows[40915]={title={{19,96262439},"수수께끼 같은 심부름"},description={"We meet again $N. I must say, I am impressed with your progress so far. You have proven far more… resilient... than most.$B$BYou know deep down why I have called you here. You still cheat death with every passing moment. You cling to this mortal coil, despite all adds. Yet, you still hunger for more. I can sate that hunger, assuming you manage to fulfil some... obligations. Only the most fierce souls are worthy of my second blessing, after all.$B$BIf I have divined your spirit accurately, then you will want to go to Gadgetzan and speak to Marin Noggenfogger. Tell him I need the... 52nd package.",", 다시 만났군.$N 지금까지 자네의 발전에 깊은 인상을 받았네. 자네는 다른 이들보다 훨씬 더… 강인한… 모습을 보여주었군.$B$B 자네는 내가 왜 자네를 불렀는지 마음속 깊이 알고 있겠지. 자네는 매 순간 죽음을 아슬아슬하게 피해가고 있고, 온갖 위협에도 불구하고 이 필멸의 육신에 매달려 있지. 그런데도 자네는 더 많은 것을 갈망하고 있군. 자네가 몇 가지… 의무를 이행한다면, 자네의 갈망을 채워줄 수 있지. 결국 가장 강인한 영혼만이 나의 두 번째 축복을$B$B 받을 자격이 있으니까. , 내 해석이 자네의 영혼을 정확하게 파악했다면, 가젯잔으로 가서 마린 노겐포거에게 가서… 52번째 패키지가 필요하다고 전해줘."},objectives={{41,18989900},"가젯잔에서 마린 노겐포거를 찾아보세요."},progress={{26,1436679074},"여보세요! 무슨 일로 오셨어요?"},completion={{116,1020859771},"52번째라고?!$B$B<마린은 잠시 유령이라도 본 듯한 표정을 지었다가 곧 평정을 되찾는다.>$B$B꼬마야, 문제가 생겼어."}}
rows[40916]={title={{16,586721307},"52번째 패키지"},description={{360,1312663128},"누가 그 얘기를 했어? 응? 대답이 없나?$B$B 알았어. 어쨌든 52번째 소포는 사라졌어. 금고에서 그냥 사라져 버렸지, 마치 누군가의 손아귀에서 쏙 빠져나간 $B$B것처럼. 내가 돈을 주고 찾으라고 했는데, 그 사람이 데솔라스에 있는 켄타우로스 무덤, 마라돈인가 어딘가에서 찾았대. 어떻게 거기에 갔는지는 나도 모르겠어.$B$B 어쨌든 네가 원한다면 직접 가서 가져와야겠어."},objectives={{60,407743964},"52번째 소포를 찾아서 미스터리 우체통에 가져다 주세요."},progress={{11,754981723},"당신은 돌아옵니다."},completion={{101,1071886664},"아주 잘했어. 영혼의 무게만큼 값진 것을 되찾았으니, 첫 번째 시험을 통과했군."}}
rows[40917]={title={{20,1452911143},"미스터리를 향한 눈"},description={"This package contains an incredibly important crystal, $N. This crystal once housed powers drawn from the Well of Eternity itself. And though its power has long since been depleted, there is ever the chance of it being restored, wouldn’t you agree?$B$BI require its power and you will help me restore it, if you wish for your hunger to be satiated, that is. Firstly, you must delve deep into Blackrock Mountain and grab the eye of Overlord Wyrmthalak, who stalks the lower halls of Blackrock Spire.","이 소포에는 엄청나게 중요한 수정, 이 들어 $N있습니다. 이 수정은 한때 영원의 샘에서 끌어낸 힘을 품고 있었습니다. 비록 그 힘은 오래전에 고갈되었지만, 언젠가는 되살아날 가능성이 있지 않겠습니까? I는 그 $B$B힘이 필요하고, 당신의 굶주림을 채우고 싶다면, 당신은 제가 그 힘을 되살리는 것을 도와야 합니다. 우선, 당신은 검은바위 산 깊숙이 들어가 검은바위 첨탑 하층부를 배회하는 오버로드 웜탈락의 눈을 가져와야 합니다."},objectives={{69,889562839},"웜탈락의 눈을 획득하여 수수께끼의 우체통에 가져가세요."},progress={{11,754981723},"당신은 돌아옵니다."},completion={{7,1814144743},"좋은..."}}
rows[40918]={title={{27,1631199590},"낯선 사람과 마법의 물약"},description={"You have done well so far, but you certainly took your time returning, didn’t you? The eye is already decomposing, and its powers are fading. Which adds yet another step to your growing list of tasks, $N.$B$BSome necromancy is now going to be required, and though traveling to Northrend is not an option, Scholomance still exists. I am sure they will have a potion that can preserve the eye.$B$BYou know what to do, do not disappoint me.","지금까지는 잘 해냈지만, 돌아오는 데 너무 오래 걸렸군. 눈은 이미 썩어가고 있고, 그 힘도 점점 약해지고 있어. 자네가 해야 할 일이 하나 더 늘었군, .이제 강령술이$N$B$B 필요할 것 같군. 노스렌드로 가는 건 불가능하지만, 스콜로맨스는 여전히 존재해. 분명 그곳에 눈을 보존할 수 있는 물약이 있을 거야.자네는 어떻게 해야$B$B 하는지 알겠지? 날 실망시키지 마."},objectives={{68,533925072},"강령술 물약을 구해서 수수께끼의 우편함에 가져다 놓으세요."},progress={{11,754981723},"당신은 돌아옵니다."},completion={{111,1742440458},"이 물약은 눈의 힘을 보존하고 되살려 줄 것입니다. 아무래도 이번 임무는 완전히 실패한 것은 아닌 것 같군요."}}
rows[40919]={title={{23,1294850014},"미스터리에 집중하기"},description={{425,1930009704},"눈의 힘을 수정에 제대로 불어넣으려면 마법 집중기가 필요합니다. 그런 집중기는 칼도레이 문명이 전성기를 누리던 시절에 흔했죠. 아아, 저도 잘 기억합니다… 이제 그 오만했던 권력의 자리는 어떻게 되었을까요? 폐허만 남았죠. 지식은 시간 속에 묻혀버렸습니다.그렇다면 마법 집중기를$B$B 찾는 건 불가능한 일이라고 생각하실지도 모르겠습니다. 하지만 다행히 제가 단서를 드리겠습니다. 아마도 다이어 몰의 하이본족 중에 하나가 남아있을지도 모릅니다."},objectives={{63,841810525},"마법 집중 도구를 획득하여 신비로운 우편함으로 가져가세요."},progress={{11,754981723},"당신은 돌아옵니다."},completion={{37,1094788706},"이건 정말 놀라운 일이군요. 잘됐습니다."}}
rows[40920]={title={{26,597159326},"미스터리 홈을 망치로 두드리다"},description={{499,1543660853},"오, 이게 무슨 한심한 흉물이야. 일부러 이렇게 아마추어 같은 표본을 가져온 건가?네가 스스로 만든 무능함으로$B$B 할 일 목록을 늘리는 걸 즐기는 모양이군. 잘 들어라. 이 수정의 흠집을 제거해야 한다. 쉬운 일이 아니니 아주 특수한 도구가 필요하다. 망치 두 개가 필요하다. 하나는 헤이트포지 채석장 깊은 곳에서 단조된 것이고, 다른 하나는 검은바위 심층부의 검은무쇠 부족이 사용하는 것이다. 그것들을 가져오면 네 실수를 용서해 주겠다."},objectives={{94,64417222},"'증오의 망치'와 '심연의 망치'를 획득하여 수수께끼의 우체통으로 가져가세요."},progress={{11,754981723},"당신은 돌아옵니다."},completion={{97,851990978},"이것들을 이용하면 초점을 조절할 수 있다. 머지않아 수정은 예전처럼 강력한 힘으로 가득 차게 될 것이다..."}}
rows[40921]={title={{24,1244615995},"마지막 불길한 미스터리"},description={{515,1128236912},"수정은 거의 완성되었습니다. 눈은 융합될 준비가 되었고, 초점은 에너지를 공급할 준비가 되었습니다. 이제 그것들을 결합할 액체 플럭스가 필요합니다. 구할 수 있는 가장 강력한 피, 바로 강력한 드래곤킨 필멸자의 피입니다. $B$B드라키사스 장군이라는 자가 있는데, 그는 다른 강력한 존재들 중에서도 가장 강력한 존재입니다. 당신의 임무를 완수하고 싶다면, 그를 물리치고 그의 심장을 가져오십시오. 그것으로 수정은 다시 태어날 것이고, 당신은 그토록 간절히, 그리고 오랫동안 갈망해 온 보상을 받게 될 것입니다."},objectives={{67,318255192},"용의 피의 심장을 획득하여 수수께끼의 우편함에 가져가세요."},progress={{34,1444115332},"마지막으로 돌아오신 거죠?"},completion={{60,572690941},"그렇다면 때가 온 것 같군요? 수정이 완성되었습니다..."}}
rows[40922]={title={{17,709611769},"영원한 죽음"},description={"And so, here we stand, $N. The end of your journey, immortality awaits. But is that truly what you want? To be like those haughty creatures of old, never fearing the cold grip of death? Never feeling the adrenaline rush of living on the edge? The risk that makes life worth living... gone. War, which I can see in your soul you live for, will become lackluster.$B$BYou will live forever. You will watch your family pass away. Your friends. Your loves. And then what? When all you value is gone?$B$BNo, I will spare you this torture, and instead grant you the true blessing: the blessing of mortality. This is the moment you have been waiting for. To face the greatest challenges and know your life may come to an end at any moment. That... that is what truly makes life worth fighting for. Am I not correct, $N?","자, 여기 당신이 있습니다.$N 당신의 여정의 끝, 불멸이 기다리고 있죠. 하지만 그게 당신이 진정으로 원하는 건가요? 옛날의 오만한 자들처럼 죽음의 차가운 손길을 두려워하지 않고, 아슬아슬한 삶의 스릴을 느끼지 않는 삶을 원하는 건가요? 삶을 가치 있게 만드는 위험이 사라지는 삶을 원하는 건가요? 당신의 영혼 속에 살아 숨 쉬는 전쟁은 이제 아무런 감흥도 주지 못할 겁니다. $B$B당신은 영원히 살게 될 겁니다. 가족이, 친구가, 사랑하는 사람이 세상을 떠나는 것을 지켜보게 되겠죠. 그리고 그 후에는 어떻게 될까요?$B$B 당신이 소중히 여기는 모든 것이 사라지고 나면요? 아니, 저는 당신에게 그런 고통을 주지 않고 진정한 축복을 주겠습니다. 바로 필멸의 축복이죠. 당신이 기다려온 순간입니다. 가장 큰 도전에 맞서고, 삶이 언제든 끝날 수 있음을 아는 것. 바로 그것이 삶을 진정으로 살아갈 가치가 있게 만드는 것입니다. 제 말이 맞습니까, $N?"},objectives={{122,647185260},"수수께끼의 우체통에 다시 말을 걸면 영원히 필멸의 존재가 되거나, 이 퀘스트를 포기하고 60레벨에 불멸을 얻을 수 있습니다."},progress={{62,329144807},"어떤 결정을 내리시겠습니까? 신중하게 생각하세요. 이 결정은 되돌릴 수 없습니다."},completion={"You actually impress me, $N. Very well. From this day forth, you will walk this land as a mortal.","$N, 자네는 정말 인상적이군. 좋아. 오늘부터 자네는 필멸자로서 이 땅을 걸어가게 될 것이다."}}
rows[40923]={title={{17,30125018},"신비로운 축복"},description={{177,1526546222},"가시기 전에... 당신에게 약간의 동정심이 느껴집니다. 어쨌든 당신은 스릴과 위험을 즐기기 위해 저에게 상당한 도움을 주셨으니까요. 어쩌면 보답으로$B$B 당신에게 작은 선물을 드릴지도 모르겠습니다."},objectives={{56,933725279},"수수께끼의 우체통에 다시 말을 걸면 보상을 받을 수 있습니다."},progress={{16,1887756932},"보기 드문 친절입니다."},completion={{268,1284233952},"<우편함이 열립니다. 꽤나 화려한 펜던트가 떨어지고, 우편함이 끔찍한 소리를 내며 닫힙니다.>$B$B이것이 당신의 운명적인 미래 여정에 도움이 되기를 바랍니다. 이제 떠나십시오. 저는 할 일도 있고 가야 할 곳도 있습니다.$B$B<우편함과의 연결이 영원히 끊어졌습니다.>"}}
rows[40924]={title={{21,499234876},"실버레인의 인장"},description={{557,1235067802},"레이븐셔 공성전 중에 도적떼와 산적들이 내 방에 침입하여 가문의 가장 귀중한 물건들을 훔쳐갔습니다. 그중 하나가 아버지께서 소유하셨고 내게 물려주신 실버레인의 문장이었습니다. 내 가문의 문장이 $B$B왕당파에서 존경받는 장교인 오스마크에게 명예의 표시로 주어졌다는 소식을 들었습니다. 그는 서쪽 멀리 드라이록 광산을 지배하고 있을 겁니다. 풀이 자라지 않는 곳을 찾아보면 산업 시설로 가득 찬 거대한 광산을 발견할 수 있을 겁니다. 내 가문의 $B$B정당한 권리를 되찾아 준다면 보상을 받으리라."},objectives={{133,2074804339},"길네아의 레이븐셔에 있는 드라이록 구덩이에서 고위 장교 오스마크에게서 실버레인의 인장을 되찾아 칼리반 실버레인 남작을 위해 돌려주세요."},progress={"Do not take your task lightly $c, Dryrock Pit is one of their most vital operations in the region and it will be under heavy guard.","$c번 임무를 가볍게 여기지 마십시오. 드라이록 피트는 이 지역에서 가장 중요한 작전 중 하나이며, 삼엄한 경비가 이루어질 것입니다."},completion={{311,610627640},"<칼리반 실버레인 남작은 미소를 지으며 인장을 바라보았다. 아무 말 없이 반지가 그의 손가락에 끼워졌다.>$B$B잘했군. 흠집 하나 없군. 이런 죄를 저지른 장교의 목숨을 앗아갔다니 속이 시원하군.$B$B자네에게 보상을 준비했네. 다시 한번 고맙네, 모험가여."}}
rows[40925]={title={{15,1070794998},"속이 빈 거미줄 실크"},description={{535,1935097464},"이 전쟁이 끝나면, 누가 이기든 상관없이, 나는 우리 가문이 빚지고 있는 귀족다운 모습을 갖춰야 한다. 그런 높은 지위를 유지하려면 이 땅에서 구할 수 있는 최고의 비단이 필요하다. $B$B속이 빈 거미줄 숲의 거미들이 만들어내는 비단은 귀하고 구하기 어렵다. 이 전쟁이 필연적으로 끝날 때를 대비해 새 옷을 주문 제작하려면 그 비단이 꼭 필요하다. 속이 빈 거미줄 $B$B숲은 바로 여기 서쪽에 있다. 속이 빈 거미줄 비단 10개를 구해다 주면, 평민이여, 그만한 값진 대가를 치르게 해 주겠다."},objectives={{110,558627555},"길니아스에 있는 레이븐셔의 판사 카슨을 위해 할로우 웹 숲의 거미에게서 할로우 웹 실크 10개를 모으십시오."},progress={{43,1858350154},"제가 당신에게 돈을 주는 건 시간 낭비를 하라고 주는 게 아니잖아요."},completion={{228,1505402673},"어머, 이것 좀 보세요. 이렇게 정교하고 복잡한 실크라니.$B$B이 실크로 새 옷을 다 만들면 그 값어치가 충분히 하겠군요.$B$B아, 맞다, 제가 돈을 드리기로 했었죠? 이 은화를 받으시고, 어서 가시죠."}}
rows[40926]={title={{18,1536438381},"길니아스 확보"},description={{428,82529097},"이 땅은 늑대인간들이 아무런 제재 없이 활보하며 남긴 추악한 흔적으로 더럽혀져 있습니다. 왕당파는 늑대인간들이 마치 전염병처럼 퍼지도록 방치함으로써 백성들을 벌하고 있습니다.$B$B 지금도 늑대인간들은 이곳 북서쪽에 있는 무성한 숲까지 남쪽으로 뻗어 있습니다. 그들이 이 위협을 끝내지 않는다면, 우리가 나서야 합니다. 길니아스에 숨어 있는 블러드클로 부족을 찾아 사냥하고, 그들의 가죽 열 장을 가져오십시오."},objectives={{98,477591785},"길니아스 레이븐샤이어에 있는 블러드클로 워겐에게서 블러드클로 펠 10개를 모아 란워스 상병에게 가져다 주세요."},progress={{28,1558662505},"워겐은 전멸했나요?"},completion={{129,1953885630},"여러분의 노력은 시간이 흐르면서 세상을 더 나은 곳으로 만들 것입니다. 숲을 배회하는 늑대인간이 적을수록 우리는 더 빨리 평화로운 상태로 돌아갈 수 있을 것입니다."}}
rows[40927]={title={{19,1557448845},"길니아스 확보"},description={{412,1366740143},"블러드클로를 막으려면 무리의 우두머리를 처치해야 합니다. 늑대인간 중에서도 가장 강한 자들을 '알파'라고 부르며, 이들이 나머지 늑대인간들을 지휘합니다. 블러드클로 알파는 $B$B북서쪽 동굴 안에 있습니다. 노스게이트 타워 서쪽에 있는 늑대인간 캠프를 찾아보세요. 동굴은 바로 근처에 있을 겁니다. 알파 $B$B13마리를 처치하고 임무를 완료하면 저에게 돌아오십시오."},objectives={{109,1638554538},"길니아스 레이븐샤이어의 란워스 상병을 위해 북쪽 동굴에 서식하는 블러드클로 알파 13마리를 처치하십시오."},progress={{113,157647196},"앞으로 닥칠 임무에 대비하십시오.$B$B도움을 요청하는 것이 좋겠습니다. 늑대인간 소굴을 공격하는 것은 쉬운 일이 아닙니다."},completion={"You have done well $N. It will only be a matter of time before the Bloodclaw tears itself apart as they struggle to establish new chains of command.$B$BYour duty to the people of Gilneas will not go unrewarded. Please, take one of these items as a thanks for everything you have done.","$N님, 정말 잘하셨습니다. 블러드클로가 새로운 지휘 체계를 확립하는 과정에서 스스로 분열되는 것은 시간 문제일 뿐입니다.$B님,$B님, 길니아 백성을 위해 헌신하신 당신의 노고는 결코 헛되지 않을 것입니다. 감사의 표시로 이 물건들 중 하나를 받아 가십시오."}}
rows[40928]={title={{14,1051092242},"파울하이드 페스트"},description={{540,892755159},"파울하이드 놀들이 이 지역에 큰 골칫거리로 떠오르고 있습니다. 최근 그들은 사우스마이어 과수원을 공격하고 점령했는데, 그곳에서 제 친구 어니스트가 목숨을 잃었습니다. 저는$B$B 아직도 그의 죽음을 슬퍼하지만, 가만히 있을 수는 없습니다. 파울하이드 놀들은 곧 다른 목표물을 찾아 나설 것이고, 섀드모어 선술집이 그들의 다음 목표물이 될 수도 있습니다. $B$B그러니 제 친구의 과수원(이곳 남동쪽에 있습니다)으로 가서 그곳에 사는 놀들을 처치해 주십시오. 증거로 그들의 팔찌 14개를 가져오십시오."},objectives={{106,1768509496},"길니아스의 섀드모어 선술집에서 파울하이드 놀을 처치하고 대로우 섀드모어를 위해 파울하이드 팔찌 14개를 획득하세요."},progress={"Have you completed your task $c?","과제$c을 완료하셨습니까?"},completion={"Fewer gnolls that prowl the countryside is better for any that call Gilneas home.$B$BThank you for your hard work $c.","시골을 배회하는 놀이 적을수록 길네아에 사는 모든 생명체에게 더 좋습니다.$B$B수고하셨습니다$c."}}
rows[40929]={title={{22,2011223960},"길니아스 등대"},description={{683,367338675},"저는 엘라로스 란워스입니다. 이 등대의 불을 밝게 타오르게 하는 것이 제 임무입니다.$B$B 전쟁 전에는 사우스쇼어에서 꾸준히 석유를 공급받았습니다. $B$B그레이메인 장벽이 봉쇄된 이후로는 제가 구할 수 있는 여분의 석유로 이 등대를 밝혀 왔습니다. $B$B이제 등대의 불이 꺼지는 것도 시간 문제일 뿐입니다. 저 또한 이 세상을 떠날 것입니다. $B$B아직 떠날 준비가 되지 않았기에 간절히 바라는 $B$B마음입니다. 로데론은 역병에 휩싸였지만, 서쪽 멀리 인간 세력의 새로운 요새가 있다는 소문이 들립니다. $B$B테라모어라는 도시에 가서 부두 관리인과 이야기해 보시고, 저에게 줄 수 있는 석유가 있는지 알아봐 주시길 부탁드립니다."},objectives={{104,1676549040},"더스트왈로우 습지의 테라모어 섬에 있는 선착장 로먼에게 말을 걸어 길네아로 보내질 예정이었던 기름을 회수하세요."},progress={{4,273767400},"예?"},completion={{65,1014862396},"길네아로 석유를 운송한다고요? 그곳은 이미 몇 년 전에 폐쇄되지 않았나요?"}}
rows[40930]={title={{25,1481898163},"길니아스 등대"},description={{498,1997142824},"아, 그러고 보니, 우리 동네에 몇 년 동안 남아있는 오래된 기름이 있었지. 말하기는 좀 그렇지만, 탈영병들이 도시를 떠나 늪지에 야영지를 차릴 때 가져가 버렸어. 그들이 그 인화성 $B$B액체를 노린 목적이 뭔가 꿍꿍이가 있을 거라고 확신해. 아니면 그 값비싼 기름으로 돈을 벌려는 걸지도 모르지. 요즘 제대로 가동되는 석유 생산지가 많지 않거든. 그 $B$B기름이 필요하면 그들에게서 되찾아 와."},objectives={{119,1336313451},"더스트왈로우 습지의 테라모어 섬에 있는 탈영병 은신처에서 훔친 석유 화물을 부두 관리인 로먼에게 가져다주세요."},progress={{27,1210508000},"기름은 회수되었습니까?"},completion={{87,878211052},"음, 이 드럼을 제대로 본 지 꽤 됐지만, 아마 이게 맞을 거예요."}}
rows[40931]={title={{26,855131228},"길니아스 등대"},description={{268,609968454},"이제 이 기름을 회수했으니, 길네아스로 돌려보낼 수 있습니다. 물론 그곳에 들어갈 방법이 있다면 말이죠. 그곳에서$B$B 내전이 일어날 조짐이 보인다는 소문을 들었으니 조심하는 게 좋겠습니다."},objectives={{82,95276566},"도난당한 석유 화물을 길니아스의 그레이메인 감시탑에 있는 엘라로스 란워스에게 돌려주십시오."},progress={{35,469500852},"그럼, 이게 테라모어에서 나온 기름인가요?"},completion={{502,1443469762},"안도감이 드네요. 드디어 두려움 외에 다른 감정을 느낄 수 있다니.$B$B오래전 저주를 받아 영원히 이 불을 돌봐야 합니다. 불꽃이 꺼지면 저도 죽게 되죠. 불꽃이 꺼졌을 때 무슨 일이 일어날지 너무나 두렵습니다. 이 영적인 형체에 묶여 있는 동안, 그 이후에 무엇이 오는지 알 수 없다는 것이 제가 진정으로 두려워하는 부분입니다.$B$B지금처럼 고통받는 한이 있더라도, 영원히 잊혀져 사라지는 것이라면 무엇이든 다 줄 수 있습니다."}}
rows[40932]={title={{10,843828542},"마차의 문제점"},description={{447,283125164},"당신, 저를 이렇게 우연히 만나주셔서 정말 다행입니다. 저는 지금 너무나 힘든 시간을 보내고 있어요. 가족의 집을 떠나야만 $B$B했는데, 이제 이런 일까지! 제 마차 바퀴가 부러져서 교체해야 하는데, 예비 바퀴를 농장에 두고 왔거든요. 부탁 하나만 들어주시겠어요? 늑대인간들이 마을을 점령해서 저는 돌아갈 수 없지만, 당신은 가능할지도 몰라요.$B$B 여기에서 북서쪽으로 조금만 가면 있는 로즈윅 농장으로 가서 제 집에 있는 예비 바퀴를 좀 가져다주세요."},objectives={{82,1184571388},"길니어스 노스게이트 타워 근처에서 도널드 로즈윅을 위해 예비 마차 바퀴를 찾아주세요."},progress={{31,1449279110},"내 예비 타이어 가져왔어?"},completion={{74,994346661},"오, 정말 멋지네요! 이제 셰이드모어 선술집까지 빠르게 갈 수 있겠어요!"}}
rows[40933]={title={{16,853341945},"로즈윅의 걱정"},description={{432,413736510},"마지막으로 한 가지만 더 부탁드리겠습니다. 다시 출발하기까지는 시간이 좀 걸릴 것 같지만, 그동안 제 아내의 걱정을 덜어주셨으면 합니다. 제가 가장 $B$B귀중한 소지품들을 가지고 떠나기 전에 아내를 셰이드모어 여관으로 보냈습니다. 제가 가는 중이고 안전하다고 아내에게 전해주세요. 이 길을 따라오시다가 레이븐샤이어로 가는 갈림길에서 서쪽으로 향하면 셰이드모어 여관을 찾을 수 있습니다."},objectives={{60,1226664417},"길니어스에 있는 셰이드모어 선술집에서 프렐 로즈윅을 만나세요."},progress={{4,273767400},"예?"},completion={{318,100438615},"도널드가 보냈나요?$B$B<안도의 물결이 여자를 휩싸며 깊은 한숨을 내쉬었다.>$B$B이 말을 듣고 정말 안심이 됐어요. 최악의 상황을 예상하고 있었거든요. 그에게 같이 가자고 했지만, 상황이 더 악화될 때까지 농장을 계속 돌보겠다고 고집을 부렸어요.$B$B소식을 전해주셔서 감사합니다, 낯선 분. 이것 좀 받아주세요."}}
rows[40934]={title={{22,999472619},"언데드에 맞서는 동맹"},description={{442,258297265},"불멸의 악취는 가장 사악하고 끔찍한 것입니다. 수년 전, 길네아 땅은 사악한 마법으로 땅을 황폐하게 만든 리치의 침략을 받았습니다. 이는 제 고향 땅에서 일어났던 일과$B$B 유사합니다. 아시다시피, 붉은십자군는 적이 아닙니다. 우리는 모두 같은 목적을 위해 싸우고 있습니다. 저는 당신이 강령술에 맞서는$B$B 요원임을 증명해 주기를 바랍니다. 그레이샤이어로 가십시오. 혹은 그곳의 남은 잔해로 가십시오. 그곳에서 여전히 걸어 다니는 죽은 자들을 처치하십시오."},objectives={{97,714743399},"길니아스의 섀드모어 선술집에서 엘리아스 형제를 위해 남아있는 해골 7마리와 비틀거리는 시체 7마리를 처치하세요."},progress={{32,831183916},"당신은 신성한 응징을 행했습니까?"},completion={{68,179941697},"그러니 당신은 어둠의 세력에 물들지 않은 것 같군요."}}
rows[40935]={title={{18,433588392},"붉은십자군의 타락"},description={{605,378892150},"이제 당신이 언데드의 하수인이 아니라는 것을 확신하게 되었으니, 제가 중립 지대를 찾아 헤맨 진정한 이유를 밝히겠습니다. 십자군은 한때 고결한 도덕성을 지닌 조직이었지만, 가장 신뢰받는 지도자들의 기둥에 균열이 생기기 시작했습니다.$B$B 대성당 깊숙한 곳에서는 페어뱅크스 대심문관의 진짜 운명에 대한 소문이 퍼지고 있습니다. 그의 죽음이… 비정상적인 방법으로 저지되었다는 믿을 만한 소식통이 있습니다. 만약 십자군 엘리트들 사이에서 강령술이 만연해졌다는 것이 사실이라면, 증거를 $B$B요구합니다. 붉은 대성당에서 페어뱅크스 대심문관을 찾아 진실을 밝혀내십시오."},objectives={{112,56869666},"길니아스의 섀드모어 선술집에서 엘리아스 형제를 위해 대심문관 페어뱅크스의 운명에 대한 진실을 밝혀내세요."},progress={{53,1042658006},"그렇다면 당신은 내 고향에서 무엇을 발견했습니까?"},completion={{327,2119559485},"제가 듣고 있는 말을 믿을 수가 없습니다. 우리 민족 지도자들 사이에서 그런 일이 벌어지다니요? 저를 비롯한 많은 사람들이 오랫동안 그런 의혹을 경계해 왔지만, 그것이 사실이라는 것을 알게 되다니…$B$B저는 다른 사람들과 모여 우리의 미래를 결정해야 할 것 같습니다. 진심으로 감사드립니다. 부디 이것을 저와 제가 대표하는 모든 사람들의 감사의 표시로 받아주십시오."}}
rows[40936]={title={{16,1389977237},"방랑자 용품"},description={{499,626045183},"우리는 분쟁에서 벗어나 자유로워지기를 바라며 길네아에 도착했습니다. 하지만 적대감만 가득할 뿐입니다. $B$B사흘 전, 늑대인간 습격대가 우리 야영지를 공격하여 가장 중요한 물자를 약탈해 갔습니다. 그런데 그 물자는 창백한 나이트하울이 아니라 블러드클로의 소행입니다. 블러드클로는 나이트하울과 적대 관계에 있는 또 다른 부족으로, 우리 야영지 남쪽에 자리 잡고 있습니다. 저는 그들이 우리 물자를 움막 속에 숨겨놓았을 거라고 확신합니다.$B$B 물자를 되찾아 우리에게 돌려주십시오."},objectives={{141,497500376},"남쪽 블러드클로 캠프에서 방랑자 보급품을 회수하여 길니아 북부의 방랑자 캠프에 있는 캠프 지도자 게테노르에게 돌아가십시오."},progress={{113,1909074133},"머지않아 우리의 물자는 그것을 훔쳐 달아난 늑대인간들의 사악한 손길에 의해 상하게 될 것이다."},completion={{340,209556526},"<게테노르는 시간을 들여 없어진 물품들을 꼼꼼히 살펴본다.>$B$B다행입니다. 모두 다 있네요. 귀한 의약품과 약재들이 수용소로 오는 험난한 운송 과정에서 손상될까 봐 걱정했습니다.$B$B수고해 주셔서 정말 감사합니다. 저희는 그동안 이 물품들에 크게 의존해 왔습니다. 부디 이것을 저희의 감사 인사로 받아주십시오."}}
rows[40937]={title={{18,1628974290},"나이트하울 성가신"},description={{410,1309902114},"밤낮으로 우리는 적대적인 나이트하울의 습격을 받고 있습니다. 그들은 흉포하고 무자비한 적으로, 우리의 방어선을 시험해 왔습니다. 그들이 우리를$B$B 완전히 압도하기 전에 이 위협을 제거하는 데 여러분의 도움이 필요합니다. 나이트하울은 올드록 패스에서 노스게이트 타워에 이르기까지 길니아 북부 전역에 숨어 있습니다.$B$B 그들을 처치하고 그들의 손목에 채워진 족쇄 11개를 가져오십시오."},objectives={{131,742230969},"길네아 북부의 방랑자 야영지에서 야영지 지도자 게테노르에게 나이트하울 워겐을 처치하고 나이트하울 족쇄 11개를 모으세요."},progress={{71,884340467},"낭비되는 매 순간은 나이트하울이 힘을 비축하는 또 다른 순간이다."},completion={{158,1869938871},"이 족쇄에는 늑대인간만이 다룰 수 있는 어떤 힘이 담겨 있습니다.$B$B적의 수를 줄이는 데는 성공했지만, 아직 우리가 감당할 수 있는 것보다 훨씬 많습니다."}}
rows[40938]={title={{22,2131988759},"나이트하울 중화"},description={{518,698535015},"나이트하울의 위협을 끝내려면 그들의 지도부를 제거해야 합니다. 늑대인간 부족은 강력한 알파가 이끄는데, 그는 매우 효율적으로 무리를 지휘합니다. 알파가 없다면 나이트하울은 혼란에 빠질 것입니다. 저는 $B$B당신에게 늑대 소굴로 잠입해 달라고 부탁합니다.$B$B 이곳 서쪽에는 은빛소나무 숲과 길니아스를 잇는 길인 골드록 패스가 있습니다. 이 길은 얼마 전 침입을 당했습니다. 나이트하울 늑대인간들이 우글거리는 이곳에 그들의 알파가 있습니다. 그들을 처치하고 이 $B$B위협에서 우리를 해방시켜 주십시오."},objectives={{95,2101539611},"길네아 북부의 방랑자 야영지에서 야영지 지도자 게테노르를 위해 나이트하울 알파 3마리를 처치하세요."},progress={{73,1135561234},"알파는 교활한 적입니다. 전략을 잘 세우고 도전에 대비하세요."},completion={"You have scattered the Nighthowl with this move. I suspect their attacks on us will cease as infighting begins to establish new leaders for their tribe.$B$BYou have done us a good favor $c, and for that you shall be rewarded.","당신의 이번 조치로 나이트하울 일당이 흩어졌습니다. 부족 내분으로 새로운 지도자가 선출되면서 우리에 대한 공격도 중단될 것으로 예상됩니다.$B$B당신은 우리에게 큰 호의를 베풀었으니, 그에 대한 보상을 받겠습니다.$c"}}
rows[40939]={title={{21,150384909},"식량 보충"},description={{443,974635819},"이곳 수용소와 그레이메인 성벽에 있는 많은 난민들이 굶주리고 있습니다. 늑대인간의 위협 때문에 대부분의 사람들이 식량을 구하거나 사냥을 나가지 못하고 있습니다. 저희 상황을 도와주시면 모두에게 제대로 된 식사를 제공할 수 있을 것 같습니다.$B$B 황혼털 늑대는 적대적이지만, 현재 식량을 보충하는 데 도움이 될 것입니다. 길니아 곳곳에서 황혼털 늑대를 찾을 수 있습니다. 고기 여섯 덩어리를 가져다주시면 당분간은 먹을 수 있을 겁니다."},objectives={{115,2026310731},"길네아스 북쪽의 방랑자 야영지에 있는 요리사 벨덴을 위해 황혼털 늑대에게서 황혼털 고기 6개를 모으세요."},progress={{53,2071652020},"모험가 여러분, 저희를 위해 먹을 것을 좀 찾으셨나요?"},completion={{261,1707242627},"정말 감동입니다. 이렇게 신선한 고기는 배고픔을 달래는 데 큰 도움이 될 겁니다. 가장 절박한 사람들에게 먼저 전달하도록 하겠습니다.$B$B다시 한번 감사드립니다. 저희를 조금 더 살려주신 것에 대한 감사의 표시로 받아주세요."}}
rows[40940]={title={{14,1031683859},"아르카나의 샘"},description={{646,1628630567},"길니아스에는 기묘하고 불길한 마법의 기운이 감돌고 있습니다. 뭔가 숨겨진 일이 벌어지고 있는 것 같습니다. 프레스토 $B$B경은 그레이메인 왕의 총애를 받는 인물로, 그의 많은 결정에 영향력을 행사했습니다. 오래전 그를 만났을 때, 저는 그에게서 뿜어져 나오는 엄청난 마법의 기운에 압도당했습니다. 길니아스에서도 그와 같은 마법의 기운이 느껴지지만, 어디에서 오는 것인지는 확신할 $B$B수 없습니다. 그 근원을 알아내려면 희귀한 아이템, 즉 푸른 용족이 사용하는 마법의 샘이 필요합니다. 그들의 무리 중 가장 가까운 곳은 불모의 땅의 수정 오아시스라는 곳에 살고 있습니다."},objectives={{136,137176665},"불모의 땅로 가서 푸른 용군단의 일원들을 처치하고 길네아의 레이븐샤이어에 있는 마법사 오렐리우스를 위해 마법의 샘을 되찾으세요."},progress={{28,463398464},"글꼴이 복구되었습니까?"},completion={{163,716592527},"용의 마법과 접촉할 때마다, 나는 그 마법이 지닌 엄청난 힘에 경외감을 느낀다.$B$B진정으로, 우리 필멸의 존재들은 용과 같은 경쟁자들의 힘에 비할 수 없습니다."}}
rows[40941]={title={{16,421295085},"마법의 존재"},description={{382,1760749705},"마법의 샘을 손에 넣으신 것을 축하드립니다. 하지만 작업을 진행하기 전에 마법적인 재료가 필요합니다. 마법의 샘은 용의 마법 없이는 자연스럽게 사용할 수 없으므로, 제 마법으로 마법 부여 재료를 활성화시켜야 합니다. 흔한 $B$B마법 부여 재료인 커다란 빛나는 조각을 가져다주시면 작업을 계속할 수 있습니다."},objectives={{96,1403770173},"길네아의 레이븐샤이어에 있는 마법사 오렐리우스를 위해 마법의 샘에 사용할 커다란 빛나는 조각을 획득하세요."},progress={{75,1927723714},"신비의 샘은 마법만으로는 다룰 수 없는 엄청난 힘을 지니고 있다."},completion={{65,2053802026},"자, 그럼 이제 신비의 샘이 어떤 진실을 드러낼 수 있는지 살펴보겠습니다."}}
rows[40942]={title={{18,456830867},"용의 존재?"},description={{683,987453827},"저는 시간을 들여 그 샘에 대해 자세히 살펴보았습니다. 남아있는 마법의 기운이 길니아스 시에서 비롯된 것임을 깨달았습니다. 어떤 종류의 마법인지 알아내기 위해서는 샘을 완전히 가동하는 데 필요한 마지막 재료 하나가 더 필요합니다. 저는 그 샘 자체를 통해 이것이 용의 마법일지도 모른다는 추측을 하고 있으며, 만약 그렇다면 프레스토 경은 인간의 모습을 한 용이었을지도 모릅니다.$B$B 이것이 사실인지 확실히 확인하려면 검은 용군단의 본거지인 더스트왈로우 습지로 가야 합니다. 더스트왈로우 습지 남쪽 드래곤머크에 서식하는 불꽃갈기 용들에게서 '강력한 용의 보석'을 회수해 오십시오. 그들은 종종 이 보석을 지니고 다닙니다."},objectives={{124,1368058306},"먼지 늪지대에서 화염 어둠 용족을 처치하고, 길니아의 레이븐샤이어에 있는 마법사 오렐리우스에게 강력한 용의 보석을 가져다주세요."},progress={{70,702134608},"이 용의 보석을 되찾으면 진정한 마법의 정체를 밝혀낼 수 있을 것이다."},completion={{821,102508545},"<마법사 오렐리우스는 잠시 멈춰 서서 마법의 샘을 통해 강력한 용의 보석의 에너지를 집중시켰다. 잠시 후, 그는 크고 무거운 한숨을 내쉬었다.>$B$B내 예상대로였군. 내 이론이 맞았어. 프레스토 경은 어쩌면 처음부터 변장한 용이었을지도 몰라. 그를 대신해 온 자들 역시 마찬가지일 거라고 확신해.$B$B할로우 가문은 프레스토가 길니아스에 도착할 무렵 명성을 얻은 귀족 가문이며, 바로 그 가문이 도시를 지배하고 있지. 셀리아 부인과 모티머 경은 그레이메인 왕의 섭정으로서 그의 대리인 역할을 하고 있어.$B$B검은 용군단의 영향력은 길니아스 깊숙이 자리 잡고 있으며, 그들은 오랫동안 이 분쟁을 조장해 온 것 같아. 무고한 사람들의 죽음과 이 땅의 부패는 모두 그들의 책임이다. 반드시 그들을 막아야 한다."}}
rows[40943]={title={{25,2041551312},"용의 존재 해제"},description={{428,720321254},"길니아스를 구할 길은 오직 하나뿐입니다. 할로우 가문이 이 내전에서 무사히 빠져나가도록 내버려 둘 수는 없습니다. 섭정 여왕 셀리아 할로우와 섭정 군주 모티머 할로우는 검은 용군단의 용족입니다. 그들은 오랫동안 길니아스를 타락시켜 쇠락과 분쟁의 땅으로 만들었습니다.$B$B 우리는 이 땅의 고통을 끝내고, 그들을 처단하여 그들의 사악한 음모를 뿌리 뽑아야 합니다."},objectives={{152,395017198},"길네아의 레이븐셔에서 마법사 오렐리우스를 위해 섭정 부인 셀리아 할로우와 섭정 영주 모티머 할로우를 처치하여 길네아에 대한 용의 영향력을 종식시키십시오."},progress={{27,192685073},"그들의 노력이 물거품이 된 걸까요?"},completion={{474,147511770},"오늘 당신의 노고는 백성들에게 알려지지 않겠지만, 그들의 고통은 끝날 것입니다. 길네아스를 지배하던 용의 영향력은 이제 사라졌습니다.$B$B이 땅이 몇 년 전의 모습으로 복원되는 것은 시간 문제일 뿐이며, 이는 부분적으로 오늘 당신의 노력 덕분입니다. 저는 키린 토의 다른 구성원들과 회의를 열었고, 사악한 용의 마법을 몰아낸 당신의 노고는 결코 헛되지 않을 것입니다.$B$B감사의 표시로 이 물건들 중 하나를 받아 주십시오."}}
rows[40944]={title={{20,1386832812},"레이븐셔로 향"},description={"Hail $c. I am Councilor Ravencrest, a noble in service to the rebellion of Lord Ravenwood.$B$BYou have come to Gilneas in a time of strife and civil conflict. Even now the Greymane royalists are no doubt preparing for the coming conflict within the walls of the city itself.$B$BIf you desire to learn more, or help us break free from the shackles of tyranny, I would guide your attention to Ravenshire to the southeast. Simply follow the road and take a left at the fork. Keep following it southward until you reach the town. When you have arrived, speak with Clerk Ebonmere.","$c안녕하십니까, 저는 레이븐크레스트 의원입니다. 레이븐우드 경의 반란을 $B$B돕는 귀족입니다. 당신은 지금 혼란과 내전이 끊이지 않는 길니아에 오셨습니다. 그레이메인 왕당파는 지금도 성벽 안에서 다가올 전투를 준비하고 있을 $B$B것입니다. 더 자세한 정보를 원하시거나 폭정의 굴레에서 벗어나는 데 도움을 주시려면 남동쪽의 레이븐셔로 가시면 됩니다. 길을 따라가다가 갈림길에서 좌회전하세요. 계속 남쪽으로 가면 마을에 도착합니다. 도착하시면 에본미어 서기관과 이야기하십시오."},objectives={{50,1739169145},"길니어스에 있는 레이븐셔에서 에본미어 서기관을 만나십시오."},progress={{4,273767400},"예?"},completion={{101,1598933123},"외부인이 나타났다? 그레이메인 성벽이 열리면서 새로운 동맹이 나타난 것 같다."}}
rows[40945]={title={{9,353971340},"스나르클로"},description={{580,1482685881},"저는 한때 길네아의 기사였습니다. 복무하는 동안 제 충성심을 흔드는 많은 일들을 목격했습니다. 하지만 아내가 죽고 나서야 비로소 진실을 영원히 깨달았습니다. 충성파들은$B$B 도시 외곽의 무고한 사람들을 괴롭히기 위해 늑대인간들이 침입하는 것을 방관했습니다. 제 아내는 스나클로라는 괴물에게 최후를 맞았고, 저는 복수를 하지 못하도록 금지당했습니다. 이제 저는 이곳에 남아 슬픔을 술로 달래고 있습니다.$B$B 스나클로라는 괴물을 처치하고, 그 왕당파들이 결코 용납할 수 없었던 일을 하십시오. 이 괴물은 북동쪽, 블러드클로 늑대인간들이 사는 동굴 속에 숨어 있습니다."},objectives={{87,1304662208},"길니아의 섀드모어 선술집에서 맥스웰 기빙스를 위해 스나클로라는 이름의 늑대인간을 처치하세요."},progress={{29,1045698146},"<맥스웰은 생각에 잠겨 있다.>"},completion={{271,358782207},"어떤 안도감을 느낄 줄 알았는데, 사실 별다른 감정은 느껴지지 않네요. 정말 큰 도움을 주셔서 감사합니다.$B$B어쩌면 곧 앞으로 닥칠 암울한 날들 속에서 위안을 찾을 수 있을지도 모르겠습니다. 부디 이것을 받아주세요. 이제 더 이상 필요하지 않을 겁니다."}}
rows[40946]={title={{21,550352982},"스파이트레스트 침입"},description={{470,276589100},"뭐, 우리를 도와주겠다는$B$B 거야?<보렌의 얼굴에 비웃는$B$B 표정이 스쳐 지나갔다.>레이븐샤이어에서 뭔가 제대로 하고 싶다면 남쪽 해변에 모여드는 나가 떼를 없애버리는 게 좋을 거야. 작년부터 떼로 몰려들기 시작했는데, 어부들을 많이 죽였거든!증거로$B$B 나가 비늘 16개를 가져와. 길니아 남쪽 해안선을 따라 널려 있을 거야. 그렇게 하면 이 망할 세상에 평화를 가져다줄 수 있을 거야."},objectives={{137,869975153},"길니아스 남쪽 해안을 따라 스파이트레스트 나가에게서 스파이트레스트 비늘 16개를 모아 길니아스 레이븐셔에 있는 부두 감시자 보렌에게 가져다 주세요."},progress={{31,1774301190},"날 귀찮게 하지 마."},completion={{99,782942948},"그러니까, 당신은 강단 있는 사람이군요? 적의 수를 줄이는 데는 성공했을지 모르지만, 아직 할 일이 더 많습니다."}}
rows[40947]={title={{21,1570222463},"스파이트레스트 데쿠르션스"},description={{416,449968944},"그렇게 쉬울 거라고 생각하진 않았겠지? 스파이트크레스트의 나가족은 고집스럽고 사악한 종족이야. 그들은 군주와 여군주가 이끌고 있는데, 각각 갈라진 삼지창의 두 갈래를 휘두르며 길네아스를 공격하고 있지. $B$B나가족의 군주와 여군주를 찾아 처치하면 우리 해안을 위협하는 이 폭정을 끝낼 수 있을 거야. 분명 남쪽 해변의 미끄러운 동족들 사이에서 그들을 찾을 수 있을 거라고 확신해."},objectives={{131,1378967224},"길니아스 남부 해안에서 자르산 경과 헤스자 부인을 찾아 처치하십시오. 길니아스 레이븐셔에 있는 부두 감시자 보렌의 의뢰를 받으십시오."},progress={{31,1774301190},"날 귀찮게 하지 마."},completion={"Huh, you've done it? Well why didn't you say that $c! You've done and gone real heroes work out here, and in Gilneas that is a rarity.$B$BHere, as a token of my thanks and from all of us that work down here, take this. It might serve you better than it would myself.","어라, 해냈군?$c, 왜 진작 말하지 않았어! 넌 정말 영웅적인 일을 해냈어. 길니아스에서는 그런 일이 드물거든.$B$B, 자, 여기 우리 모두를 대표해서 감사의 표시로 이걸 가져가. 내 것보다 자네에게 더 유용할지도 모르겠군."}}
rows[40948]={title={{18,1151211101},"양떼 속의 늑대"},description={{830,103250092},"말해 보시오. 한 나라의 본질, 한 나라의 심장, 한 민족의 의지란 무엇인가? 땅 그 자체인가? 법치인가? 경제인가? 아니, 틀림없이 이 모든 것은 아니다. 한 나라의 본질은 전통, 역사, 유산, 결단력, 그리고 의지력에 있다. 우리 모두는 최악의 상황에 $B$B대비해야 한다. 우리 국민 전체가 왕을 구출하여 다시 왕좌에 앉히기를 간절히 바라고 있기 때문이다. 하지만 만약 그가 그렇게 할 수 없다면 어떻게 될까? 왕비가 죽은 후, 겐은 자식들을 멀리 보내는 것이 최선이라고 생각했다. 몇 달이 지나서야 우리는 그 소식을 들었지만, 리암과 테스는 지금 할로우 가문의 포로가 된 것 같다. 우리는$B$B 리암이 길니아스 시 서쪽 지하 깊숙한 드라이록 광산에 갇혀 있다고 믿는다. 그는 이 나라의 후계자이므로, 조국을 해방하기 위해 백성과 함께 피를 흘려야 한다."},objectives={{19,1299161431},"리암 그레이메인을 찾으세요."},progress={{4,273767400},"예?"},completion={{207,998069718},"잊히지 않았나 보군요.$B$B당신에게 말합니다. \"반갑습니다, 벽 너머에서 온 분이시여.\" 이 만남을 머릿속으로 수없이 상상해 봤지만, 지금은 말문이 막힙니다. 당신은 저를 해방시켜 주려고 온 거죠?"}}
rows[40949]={title={{19,135939766},"한 번에 한 사슬씩"},description={{726,1043482499},"아이러니하군. 오랫동안 햇빛을 보지 못했다고 말하려던 참이었는데, 길니아스의 안개와 비 때문에 제대로 된 일출을 본 적이 없다는 걸 깨닫고는 피식 웃었다. 나는$B$B 이 사슬에서 벗어나야 해. 그 창녀 셀리아가 아버지를 설득해서 우리를 쿨 티라스로 보내 테스와 나를 묶어 세상과 단절시켰어! 나는 테스가 탈출하는 걸 도왔지만, 그들은 나를 여기에$B$B 가둬버렸지. 제발 나를 도와줘. 내 백성을 찾아 내 도시를 점령하고 아버지의 마음을 독살한 악당들로부터 그들을 도울 수 있도록$B$B 말이야. 경비대장 마슨, 그 놈이 내 자유의 열쇠를 쥐고 있어. 아마 이 근처에서 찾을 수 있을 거야. 바깥 신선한 공기를 쐬고 있을지도 몰라."},objectives={{80,1912592240},"경비대장 마슨을 처치하고 녹슨 열쇠를 모아 리암 그레이메인을 구출하세요."},progress={{74,1669142337},"시간이 좀 더 있었으면 좋았겠지만, 정말 서둘러야 해요."},completion={{200,971143060},"그는 편안한 죽음이라는 자비를 받을 자격이 없었다.$B$B<리암이 낄낄거린다.>$B$B어쩌면 이 구덩이에서 보낸 몇 주가 내가 빛의 추종자로서의 진실성을 의심하게 만드는 것일지도 모른다. 나는 스승에게 수치를 안겨주었다."}}
rows[40950]={title={{17,2059413940},"전설의 발자취를 따라서"},description={{686,911785966},"고맙습니다. 레이븐셔로 돌아가 다리우스에게 보고하는 것이 최선이지만, 당신에게 다른 일을 부탁해야겠습니다. 제 여동생의 발자취를 따라가야 합니다. 여동생은$B$B 탈출하기 전에 어머니의 이야기를 했는데, 사실 그 이야기들은 그저 동화에 불과했습니다. 하지만 테스는 늑대뱀과 그 추종자들인 펠라르의 존재를 굳게 믿었던 것 같습니다. 그녀는 전설을 찾아 땅의 한가운데로 떠났고, 당신도 그 길을 따라가야 합니다. 제 여동생을 찾아 레이븐셔로 안전하게 데려다주십시오. 우리는 그곳에서 다시$B$B 만날 것입니다. 이곳에 머무르는 것은 제 생각에 전혀 없습니다. 빛과 $B$B함께 가십시오, 친구여. 가장 필요할 때 빛이 가장 밝게 빛나기를."},objectives={{67,615820251},"길네아스 중심부에 있는 큰 나무 아래에서 테스 그레이메인을 찾으세요."},progress={{4,273767400},"예?"},completion={{124,1254856438},"외국인이 하필 여기라니? 리암이 보낸 건가? 아, 그럼 내 동생은 안전하겠군. 우리가 직접 구출하려던 참이었어."}}
rows[40951]={title={{18,881835762},"레이븐셔로 돌아가기"},description={"I will remain here with the Pellars. Demetreus has acknowledged my will to learn, and I am prepared to learn their ways before the final battle. As much as possible, that is. There will be a final battle $N, you know. Mark my words, it has been foreseen. With them at our side, we are sure to hold an advantage, even though Demetreus is sure I will play little part in taking down the evil that has corrupted this land.$B$BIf anything he believes that YOU, $N, will play a deciding role in this. They speak in riddles and are very vague, but they are dependable. Find my brother in the town of Ravenshire to the southeast and let him be worry-free.$B$BTell him this: the mane grows grey with wisdom when the long dark sets. He will know what it means.","저는 펠라르 가문과 함께 이곳에 남겠습니다. 데메트레우스께서 제가 배우고자 하는 의지를 인정해 주셨고, 저는 최후의 전투 전에 그들의 방식을 배울 준비가 되어 있습니다. 가능한 한 최대한 많이 말이죠. 최후의 전투는$N 반드시 있을 겁니다, . 명심하세요, 이미 예견된 일입니다. 그들이 우리 편에 있다면, 데메트레우스께서는 제가 이 땅을 타락시킨 악을 물리치는 데 큰 역할을 하지 못할 거라고 생각하시지만, 우리는 분명 유리한 입장에 서게$B$B 될 겁니다. 오히려 그는 당신, 이$N 결정적인 역할을 할 거라고 믿고 있습니다. 그들은 수수께끼 같은 말을 하고 매우 모호하지만, 믿을 만한 사람들입니다. 남동쪽 레이븐셔 마을에 있는 제 동생을 찾아 걱정 없이 지내게 해 주십시오. $B$B그에게 이렇게 전해 주세요. 긴 어둠이 내리면 갈기는 지혜로 하얗게 변한다고. 그는 그 뜻을 알 겁니다."},objectives={{49,794442496},"길니어스에 있는 레이븐셔의 리암 그레이메인에게 보고하십시오."},progress={{4,273767400},"예?"},completion={{112,910692565},"내 여동생... 빛이 준 선물.$B$B<리암은 씩 웃으며 고개를 끄덕인다.>$B$B그렇다면 우리는 우리 자신의 행동에서 지혜를 찾을 수 있을까?"}}
rows[40952]={title={{25,1171482045},"어둠 속의 희미한 빛"},description={{713,1938433533},"당신이 테스를 찾는 동안, 저는 레이븐셔로 돌아가는 길을 찾고 있었습니다. 먼저 할로우 가문에 나라를 팔아넘긴 배신자들을 처리해야 했죠. 빛의 인도하심을 따라, 저는 죽은 자들 사이에서 편히 쉬며 어머니의 묘에 참배하고 싶었습니다. 지하 묘지에 도착했을 때, 저는 거칠고 $B$B낯선 얼굴을 보았습니다. 그 얼굴은 저에게 적대감만 드러냈습니다. 짐승처럼 으르렁거렸죠. 솔직히 말해서, 저는 환영받지 못했지만, 그들은 저에게 피난처를 제공해 주었습니다. 그들은 냉정하고 폭력적인 여자가 이끄는 이상한 무리입니다. 그녀의 이름은 모란나이고, 네 명으로 이루어진 무리를 이끌고 있는데, 그들은 불멸을 연구하는 사이비 종교 집단이라고 주장합니다. 저는 그녀가 우리에게 도움이 될 수 있을 거라고 생각합니다. 서쪽에 있는 할로우 웹 묘지에서 그녀를 찾아보세요."},objectives={{61,1635713744},"길니어스에 있는 할로우 웹 묘지에서 모란나 로젠버그를 찾아보세요."},progress={{4,273767400},"예?"},completion={{94,2044599139},"그럼, 레이븐셔로 가는 길에 우리를 방문한 분이 왕자님이었군요? 저는 그분이 왕족일 거라고는 생각 못 했어요."}}
rows[40953]={title={{13,1860901564},"가장 비열한 인간"},description={{832,1468367767},"그레이메인 왕자가 우리 연구단에 도움을 요청하는 건 분명해 보입니다. 하지만 왕자님께서 우리를 오해하신 것 같습니다. 우리는 불멸을 추구하는 것이 아니라, 인간의 육체가 감당할 수 있는 한계를 뛰어넘는 힘과 건강을 추구합니다. 당신은 이미 우리의 비밀을 눈치챘겠지만, 만약 그렇지 않다면 솔직하게 말씀드리겠습니다. 우리는 늑대인간의 저주를 $B$B받아들였습니다. 우리는 리암이 도시와 영토를 되찾도록 기꺼이 도울 의향이 있습니다. 우리의 연금술 지식, 이빨, 그리고 잠재된 힘 모두 그의 $B$B손에 달려 있습니다. 아직 우리의 능력을 완전히 제어하지는 못했지만, 그 문제를 해결할 방법을 찾은 것 같습니다. 북서쪽 드라이록 계곡으로 가서 배신자들을 최대한 많이 처치하십시오. 그들의 피를 뽑아 저에게 가져오십시오. 우리의 연구에 중요한 역할을 할 것입니다."},objectives={{136,642232317},"길니아스의 할로우 웹 묘지에 있는 모란나 로젠버그를 위해 드라이록 밸리 주변의 그레이메인 충성파들로부터 혈액 샘플 20개를 모으십시오."},progress={{72,374197285},"당신은 혈통에 얼마나 큰 힘이 깃들어 있는지 상상조차 할 수 없을 겁니다."},completion={{88,731226106},"당신의 도움에 회의적이었지만, 괜한 의심이었군요. 정말 잘하셨습니다."}}
rows[40954]={title={{17,821827001},"갈림길 거래"},description={{367,540395836},"아마도 왕자께서는 예상했던 것보다 더 많은 것을 얻었다고 느끼실 겁니다. 저는 왕자님의 눈에서 불꽃을 보았습니다. 그 불꽃을 다시금 $B$B왕자님께 상기시켜 주십시오. 어려운 시기에는 행동에 있어 어중간해서는 안 됩니다. 자신이 아끼는 사람들을 해치는 것보다 더 큰 $B$B악은 없습니다. 왕자님께 보고드리고, 제 충성심은 이 땅의 평민들에게 있음을 확신시켜 주십시오."},objectives={{49,848665447},"길니아의 레이븐셔에 있는 리암 그레이메인에게 돌아가십시오."},progress={{4,273767400},"예?"},completion={{80,1872679226},"다리우스는 고집이 센 사람이다. 그는 이 동맹의 필요성을 이해할 것이다."}}
rows[40955]={title={{25,679581776},"프레이셰어 요새 공격"},description={{533,1988278182},"프레이시어 요새의 위협은 레이븐셔에 끊임없는 압박을 가하고 있습니다. 전략적으로 매우 중요한 위치에 자리 잡고 있으며, 마을로 들어오는 모든 물자 수송을 $B$B차단할 수 있습니다. 우리가 도시에 최후의 일격을 가하려면 이곳을 파괴해야 합니다! 북쪽으로 다리를 건너면 프레이시어 요새가 있는 섬이 나옵니다. 그곳으로 가서 요새 수비대와 대포를 지휘하는 포병 라일슨을 처치하십시오. 이 임무를$B$B 완료하면 레이븐우드 영주에게 보고하십시오. 그가 우리의 최종 작전을 지휘할 것입니다."},objectives={{133,1175135149},"프레이셰어 요새에서 그레이메인 수호자 8명과 포병 라일슨을 처치한 후, 길니아스의 레이븐셔에 있는 다리우스 레이븐우드 경에게 보고하십시오."},progress={{32,2024182899},"작업이 완료되었습니까?"},completion={{192,153423461},"당신의 행동 덕분에 이 지역 동부에서 그레이메인의 능력이 크게 약화되었습니다. 당신의 노고에 감사드립니다.$B$B이제 우리는 마지막 단계에 집중할 수 있습니다."}}
rows[40956]={title={{29,1484872226},"그레이메인의 몰락과 부활"},description={"The entirety of Gilneas stands at our side! The tyranny of the royalists can no longer be allowed to stand! If this nation is to ever recover from the darkness, then we must hold fast, and strike even faster still!$B$BThe Greymane Crown must be recovered if our dream is ever to be realized. Enter Gilneas City. Fight your way through his most loyal soldiers. End the Harlows, and reclaim the Greymane birthright. A new king and a new beginning awaits us, $N.","길니아의 모든 백성이 우리 편이다! 왕당파의 폭정을 더 이상 용납할 수 없다! 이 나라가 어둠에서 벗어나려면 우리는 굳건히 버텨야 하며, 더욱 빠르게 공격해야 한다! 우리의 꿈을 이루려면$B$B 그레이메인 왕관을 되찾아야 한다. 길니아 시티로 진격하여 그의 가장 충성스러운 병사들을 물리치고, 할로우 가문을 처단하여 그레이메인의 계승권을 되찾아라. 새로운 왕과 새로운 시작이 우리를 기다린다, .$N"},objectives={{95,501626622},"길니아의 레이븐셔에서 겐을 구출하고, 다리우스 레이븐우드 경을 위해 그레이메인 왕관을 되찾으세요."},progress={{83,1046828659},"모험가여, 용기를 내십시오. 이 도시 역시 우리처럼 내란을 겪어왔습니다."},completion={{337,1116207344},"한 시대의 끝이 다가왔습니다. 오늘, 어둠이 걷히고 구름 사이로 새로운 희망이 솟아오릅니다. 모두가 볼 수 있는 한 줄기 빛입니다. 리암 그레이메인이 왕으로 즉위하고, 그의 통치는 오랫동안 고통받아온 백성들에게 번영을 가져다줄 것입니다!$B$B그의 눈에는 희망이 빛났다. 아마도 한 세대 만에 처음일 것이다."}}
rows[40957]={title={{16,1693114708},"꿈속으로 I"},description={{840,370899485},"저는 녹색 용군단의 종복, 랄라티우스입니다. 제가 꿈의 세계 밖에서 저를 만나는 것은 드문 일이지만, 이곳에 온 데에는 절박한 이유가 $B$B있습니다. 저희의 신성한 영역이 정체불명의 어둠에 오염되었습니다. 이 타락은 갑작스럽고 예고 없이 나타나 꿈의 세계 곳곳에 악영향을 미치고 있습니다. 드루이드와 용, 그리고 꿈의 모든 거주자들이 이 간악한 세력에 맞서 용감하게 싸우고 있지만, 막대한 손실을 입고 있습니다.$B$B 그중에는 고귀한 영혼이자 이세라의 가장 소중한 자식 중 하나인 각성자 솔니우스도 있습니다. 솔니우스는 각성이라는 가장 신성한 의식을 수호하는 책임을 맡았습니다. 그러나 그는 악몽의 유혹적인 속삭임에 굴복했고, 이제 이 신성한 힘은 어둠의 손에 넘어갔습니다. 부디 제 이야기를 $B$B들어주십시오. 무슨 수를 써서라도 그를 막아야 합니다."},objectives={{33,786316495},"랄라티우스의 이야기를 들어보세요."},progress={{31,475284036},"에메랄드 드림이 위험에 처해 있습니다."},completion={{41,615409288},"이제 아시겠죠. 솔니우스는 반드시 막아야 합니다."}}
rows[40958]={title={{17,607211212},"꿈속으로 II"},description={{902,402298474},"악몽은 도처에 존재할 수 있습니다.$B$B 고귀한 영웅처럼 보이는 자조차도 이 사악한 세력에 숨겨진 충성을 품고 있을지도 모릅니다. 저는 맹목적으로 신뢰할 여유가 없습니다. 그러므로 당신의 $B$B충성을 증명할 확실한 증거가 필요합니다. 이 마법에 걸린 숲 깊은 곳에는 어둠을 받아들인 사악한 사티로스들이 살고 있습니다. 이 악마들은 타락의 힘이 깃든 악몽의 형상, 즉 유물을 소유하고 있습니다. 이 형상들은 우리 세계에 악몽의 모든 힘을 풀어놓을 만큼 강력하지는 않지만, 적이 휘두를 경우 상당한 위협이 됩니다.$B$B 하지만 그 중요성은 당면한 위험을 넘어섭니다. 이 사악한 형상들은 꿈의 세계와 필멸의 세계를 연결하는 통로 역할을 합니다. 이 악마의 유물을 제게 가져오면, 우리는 그 독특한 힘을 이용하여 악몽의 하수인 중 감히 그것을 휘두르는 자를 드러낼 수 있습니다. 세 개면 충분합니다."},objectives={{57,424346843},"노다나르에 있는 랄라시우스에게 악몽 조각상 3개를 가져가야 합니다."},progress={{174,38937196},"무거운 마음으로 경계와 불신의 짐을 지고 있지만, 적의 위협은 모든 그림자 속에 도사리고 있으며, 어떤 약점이나 취약점이라도 이용하려 들고 있습니다."},completion={{283,738550284},"당신은 손에 이 형상들을 들고 있지만, 당신에게서 부패의 기색은 찾아볼 수 없소.$B$B<랄라티우스는 안도의 한숨을 내쉰다.>$B$B나는 모든 그림자 속에서 적을 보고 있으며, 그것이 나를 짓누르고 있소. 처음 당신을 불신했던 것에 대해 유감스럽게 생각하지만, 이 조치를 취해야만 하네. 자, 이제 이 형상들을 내게 넘겨주시오."}}
rows[40959]={title={{18,87773938},"꿈속으로 III"},description={{995,20648967},"꿈의 세계에 적응하려면 더 많은 재료가 필요합니다. 당신의 육체가 그곳에 갇히게 되면 악몽의 먹잇감이 될 것입니다. 꿈의 길을 안전하게 통과하려면 다음 아이템들이 필요합니다. 첫째, 절벽 파괴 거인의 결속 조각입니다. 이 강력한 유물은 당신의 영혼을 아제로스에 결속시켜 도중에 발생할 수 있는 모든 실패로부터 당신을 보호해 줄 것입니다. 둘째, 다이어 몰에서 얻을 수 있는$B$B 과부하된 비전 프리즘은 꿈의 세계를 가득 채우는 마법의 폭풍으로부터 당신을 지켜줄 방패가 될 것입니다. 셋째, 가라앉은$B$B 사원 깊은 곳에서 쓰러진 동족에게서 얻은 잠자는 자의 조각을 구하십시오. 이 조각은 꿈의 수호자들로부터 당신의 존재를 숨기는 능력을 가지고 있습니다. 마지막으로, 아르카나이트 지팡이를 $B$B제작할 수 있는 숙련된 대장장이를 찾으십시오. 이 아이템들을 모두 $B$B모으면 슬픔의 늪에서 에라니쿠스의 형제인 이타리우스를 찾아가십시오. 당신이 꿈에 접근할 수 있도록 허락하려면 그의 승인이 필요합니다. 이 결정은 제가 내릴 수 있는 것이 아닙니다."},objectives={{277,1100284233},"아즈샤라의 절벽 파괴자에게서 결속의 조각을, 다이어 몰 서쪽 구역의 마법 급류에서 과부하된 마법 프리즘을, 가라앉은 사원의 직조공에게서 잠자는 자의 파편을, 그리고 아르카나이트 지팡이를 모으세요. 모은 아이템을 가지고 슬픔의 늪에 있는 이타리우스에게 가세요."},progress={{11,819267740},"그게 뭐죠?"},completion={{113,150523373},"필멸자여, 무엇을 원하는가? 어찌하여 이 버려진 곳에 왔는가?$B$B잠깐... 네게서 꿈의 기운이 느껴지는군."}}
rows[40960]={title={{17,607211225},"꿈속으로 IV"},description={{814,1172227527},"이타리우스는 지혜와 연민이 가득한 눈으로 당신의 이야기를 주의 깊게 듣습니다. $B$B\"이해합니다. 랄라티우스가 충동적으로 행동했을지 모르지만, 그의 의도는 고귀했습니다. 그는 전개되는 사건들과 그 안에서 자신이 맡게 될 운명을 완전히 이해하지 $B$B못하고 있습니다. 저는 이곳에서 동족들이 사악한 악몽에 의해 타락하는 것을 목격하며 경계를 늦추지 않았습니다. 솔니우스의 불행한 운명에 마음이 아픕니다. 이런 비극은 우리 $B$B모두에게 닥칩니다. 저는 악몽을 둘러싼 수수께끼를 풀고 그것을 영원히 물리칠 방법을 찾기 직전에 있습니다. 당신의 용감한 여정에서 우리가 승리할 수 있도록 해 줄 중요한 단서를 발견할지도 모릅니다. 제 축복을 담아 이 명령을 랄라티우스에게 전하십시오. 그는 제 권위에 따라 당신이 꿈의 세계로 들어갈 수 있도록 허락할 것입니다.\""},objectives={{59,688156016},"하이잘의 노르다나르에 있는 랄라시우스에게 이타리우스의 명령을 가져가야 합니다."},progress={{4,273767400},"예?"},completion={{230,505881218},"제가 부탁드린 자료들을 모아주셔서 진심으로 감사드립니다. 이렇게 모은 자료들과 이타리우스의 자비로운 축복으로 이제 우리는 꿈의 세계를 들여다보고 당신이 그 강력한 에너지에 연결될 수 있도록 준비했습니다."}}
rows[40961]={title={{16,1693114721},"꿈속으로 V"},description={{651,1213101325},"제가 손에 넣은 물건들과 제게 전해진 심오한 지식을 바탕으로, 이제 에메랄드 드림의 신비로운 에너지로 통하는 통로가 될 신성한 의식을 시작하겠습니다. 이 고대 의식을 통해 우리는 조화로운 연결을 맺고, 당신이 존경받는 영역으로 안전하게 들어올 수 있도록 하겠습니다.$B$B 제가 고대 주문을 외우고 꿈의 정수를 불러일으키면, 우리 세계를 가르는 장막이 걷히고 고요와 지혜의 길이 드러날 것입니다. 꿈의 신비로운 안개가 당신을 감싸 안아 해악으로부터 보호하고 푸르른 풍경 속으로 인도할 것입니다. $B$B에메랄드 드림의 장엄함을 받아들이세요!"},objectives={{34,477353182},"의식이 끝날 때까지 기다리세요."},progress={{31,475284036},"에메랄드 드림이 위험에 처해 있습니다."},completion={{71,938532852},"이세라 여신님... 저희는 당신을 실망시키지 않겠습니다. 에메랄드 드림을 저버리지 않겠습니다."}}
rows[40962]={title={{17,607212915},"꿈속으로 VI"},description={{464,1084362649},"라타리우스가 꿈의 길을 끊으려 시도하는 동안 꿈의 세계로 안전하게 들어가는 것은 불가능합니다. 만약 계속 진행한다면, 당신은 갇히게 되어 악몽의 손아귀에 넘어갈 위험이 있습니다. 라라니쿠스를 찾아$B$B 그의 고통을 끝내주십시오. 이를 증명하기 위해 이세라가 그에게 준 보석을 되찾아 오십시오. 그는 아마도 아직 그 보석을 가지고 있을 것이며, 이는 악몽이 우리의 유산을 조롱하는 행위일 것입니다. 라라니쿠스는$B$B 하이잘 어딘가에 있을 것입니다. 그를 처치하십시오."},objectives={{85,283908376},"하이잘의 노르다나르에 있는 라라니쿠스를 처치하고 랄라시우스를 위해 이세라의 돌진을 회수하세요."},progress={{19,1667884298},"라라니쿠스는 죽었나요?"},completion={{264,1897082572},"라라니쿠스는 최후를 맞이했고, 당신은 이세라의 전령을 성공적으로 되찾았습니다. 이 중대한 업적을 통해 당신은 이제 에메랄드 꿈에 대한 조율 과정을 거칠 준비가 되었습니다. 필멸자여, 가만히 있으십시오. 제가 당신에게 이세라의 선물을 수여하겠습니다."}}
rows[40963]={title={{15,1370359324},"솔니우스의 수장"},description={{626,1462793867},"당신은 한때 고귀하고 존경받던 용이었지만, 이제는 사악한 악몽에 물들어 타락한 솔니우스의 잘린 머리를 손에 쥐고 있습니다. 그의 비늘에 새겨진 뒤틀린 무늬와 상징들은 섬뜩한 어둠을 내뿜어 경외감과 불안감을 동시에 자아냅니다. 강력한 용조차도 이토록 철저하게 타락할 수 있다는 것은 악몽의 힘과 악의를 $B$B보여주는 증거입니다. 솔니우스의 죽음 소식은 노르다나르의 랄라티우스에게 안도감과 만족감을 안겨줄 것입니다. 녹색 용족은 강력한 위협이 제거되었다는 사실에 기뻐할 것이며, 에메랄드 드림은 한결 편안해질 것입니다."},objectives={{61,515339490},"솔니우스의 머리를 하이얄의 노르다나르에 있는 랄라티우스에게 가져다 주십시오."},progress={{46,867065627},"필멸자여, 무슨 일이냐? 꿈에서 돌아온 것이냐?"},completion={{166,333845978},"해냈군요. 각성이 저지되었습니다.$B$B지금 이세라에게 연락하겠습니다. 그녀도 알아야 합니다.$B$B녹색 용군단의 감사의 표시로 이 물건을 받아주십시오."}}
rows[40964]={title={{26,340220469},"여단이 귀환"},description={{639,1449784979},"소식 들었나? 한때 난공불락의 장벽이었던 그레이메인 성벽이 드디어 열렸어! 오랫동안 잃어버렸던 우리 고향으로$B$B 돌아갈 길이 열렸다고! 소집 명령이 내려졌고, 용감한 병사들을 가득 태운 배가 길니아를 향해 출항했다. 지금쯤이면 억압적인 정권에 맞선 반란의 중심지, 레이븐셔 항구에 도착했을 것이다. 레이븐우드 반란의 깃발 아래, 우리는 함께 불의한 통치의 굴레에서 길니아를 해방시킬 $B$B것이다! 이 중대한 기로에 선 우리는 여러분의 도움을 간절히 바란다. 지체 없이 레이븐셔로 향하라. 도착하면 아빙턴 하사를 찾아라."},objectives={{61,104696614},"길네아로 가서 레이븐셔에서 아빙턴 경사를 찾으십시오."},progress={{31,1654372646},"새로운 얼굴입니다. 길네아스에 오신 것을 환영합니다."},completion={{770,5839251},"아, 단미어가 당신을 우리 쪽으로 보냈군요. 보시다시피 이곳 상황은 결코 좋지 않습니다. 우리는 절실히 도움이 필요하며, 당신의 어떤 도움이라도 매우 감사히 받겠습니다. 최전선에 오신 것을 환영합니다.$B$B우리 작전에 대해 제대로 파악하려면 우리 부대의 핵심 인물 두 명에게 인사를 드리는 것이 좋겠습니다. 다리우스 레이븐우드와 칼리반 실버레인은 할로우 세력에 맞서 우리 저항군을 지휘하는 굳건한 지도자들입니다. 그들은 보통 시청에서 다음 작전을 구상하고 전략을 짜느라 분주할 것입니다. 지체 없이 그들을 찾아가 도착을 알리십시오. 그들은 당신의 방문을 반길 것이며, 당신에게 특정한 임무나 지시를 내릴 수도 있습니다."}}
rows[40965]={title={{21,1364348608},"반란군에게 식량을 공급하다"},description={{912,864933135},"저는 이 지역에서 험난한 삶을 살아왔습니다. 이곳 생활이 항상 순탄했던 건 아니지만, 대체로 단순하고 평범했습니다. 제 임무는 친척들과 마을 사람들을 먹여 살리고, 이 숲을 배회하는 흉포한 짐승들을 사냥하는 것이었습니다. 하지만$B$B 반란 이후로 많은 것이 변했습니다. 이제 제 지친 어깨에는 가족을 먹여 살리는 것뿐만 아니라 군대 전체에 물자를 공급해야 하는 책임이 지워졌습니다! 저 같은 보통 사람에게는 감당하기 힘든 짐입니다. 낯선 이여, 이 곤경에서 저를 $B$B도와주시겠습니까? 숲 속 깊은 곳으로 들어가 바일윙이라고 불리는 박쥐 같은 생물들을 찾아보세요. 어린 녀석들은 살이 질기고 혈관이 많아서 손댈 필요가 없습니다. 우리가 노리는 건 더 큰 녀석들입니다. 그 녀석들을 사냥해서 큼직한 고기 아홉 덩어리를 가져오십시오. 그게 바로 이 어려운 시기에 배를 든든히 채우고 기운을 북돋아 주는 비결이 될 겁니다."},objectives={{76,1950875067},"길니아스 레이븐셔에 있는 나르윅에게 큰사악날개고기 9덩어리를 가져다 주세요."},progress={{27,1974426178},"아, 사냥의 스릴이란!"},completion={{142,1968661353},"어머, 낯선 분이시여, 정말 반가운 얼굴로 뵙게 되었군요! 우리 대의를 위해 훌륭한 일을 많이 해 주셨으니, 우리는 당신에게 큰 은혜를 입었다고 생각합니다."}}
rows[40966]={title={{22,86775768},"레이븐셔에 대한 증서"},description={{697,1557509342},"그레이메인, 아니 할로우는 레이븐셔를 끊임없이 공격해 왔지만, 번번이 실패했습니다. 우리의 용감한 병사들은 흔들림 없는 용기를 보여주며 그들의 공격을 여러 차례 격퇴했습니다. 그러나 어느 대담한 야간 공격에서 적군은 시청의 방어선을 뚫고 레이븐셔의 소유권 증서를 탈취해 갔습니다. 이 증서는$B$B 저에게 개인적으로는 큰 가치가 없지만, 백성들에게는 제가 정당하게 통치하고 있음을 상징하는 매우 중요한 의미를 지닙니다. 길니아에 질서를 회복하기 위해서는 이 증서를 하루빨리$B$B 되찾아야 합니다. 적군은 증서를 길니아 시로 가져갔을 것이 분명합니다. 하지만 현재 그 행방은 알 수 없습니다."},objectives={{85,82981713},"길네아 시티에서 레이븐샤이어 영지 증서를 찾아 칼리반 실버레인에게 가져다 주세요."},progress={{41,794380547},"레이븐셔 영지의 소유권 증서는 반드시 되찾아야 한다."},completion={{585,1821996262},"훌륭한 업적을 칭찬합니다. 이제 문서가 안전하게 제 손에 다시 들어왔으니, 감히 제 통치에 도전하는 자들은 그들의 행동을 재고할 수밖에 없을 것입니다. 이 문서의 반환은 강력한 억지력이 되어, 우리의 권위에 의문을 제기하는 자들의 오만함을 꺾어놓을 것입니다.$B$B앞으로 나아갈 길이 험난할지라도, 우리는 길네아 재건에 대한 우리의 의지를 결코 굽히지 않을 것입니다. 길고 험난한 여정이 우리 앞에 놓여 있지만, 하루하루 지칠 줄 모르고 노력하여 사랑하는 조국을 본래의 영광과 위엄의 자리로 되돌려 놓겠습니다."}}
rows[40967]={title={{14,1611356370},"레이븐우드 요새"},description={{984,997882733},"반란이 시작된 후, 나의 고향인 레이븐우드 요새는 할로우 가문의 지휘 아래 있는 군대의 공격을 받았습니다. 우리 수비대는 흔들림 없는 용기로 싸웠지만, 결국 열세에 몰렸습니다. 할로우 가문은 어둠의 마법을 사용하여 군대를 강화한 듯했습니다. 비록 우리 병사들 중 일부는 간신히 $B$B공격을 피해 탈출했지만, 대부분은 적의 칼날에 희생되었습니다. 심지어 나의 충성스러운 신하들조차 학살을 피할 수 없었습니다. 그중에는 나의 가장 소중한 두 친구, 게이틀리와 마티아스도 있었습니다. 이제 전쟁의 여운이 가라앉으면서,$B$B 한때 위안과 보호를 제공했던 바로 그 성벽 안에 섬뜩한 기운이 감돌고 있습니다. 게이틀리와 마티아스의 불안한 영혼은 목적 없이 떠돌아다니며, 한때 고귀했던 그들의 마음은 쓰라린 원한에 사로잡혀 있습니다. 아군과 적군을 구분하지 못하게 된 그들은 감히 그들의 길을 가로막는 자들에게 무자비한 만행을$B$B 저지릅니다. 고통받는 이 영혼들이 영원한 잠의 품에서 평화를 찾을 수 있도록 안식을 주소서."},objectives={{151,874291776},"길니아스에 있는 레이븐셔에서 다리우스 레이븐우드 경을 위해 레이븐우드 유령 8마리, 레이븐우드 망령 8마리, 게이틀리 병장, 그리고 관리인 마티아스에게 안식을 가져다주세요."},progress={{26,661443974},"레이븐우드 요새... 나의 고향."},completion={{300,350937588},"<다리우스 레이븐우드는 안도의 한숨을 내쉬었다.>$B$B나의 병사들과 하인들이 더 이상 할로우 가문의 어둠의 마법에 시달리며 이 세상을 떠돌지 않는다는 사실에 큰 평화를 얻었다. 그들의 이름으로 깊은 감사를 표한다. 부디 이 선물을 나와 그들의 감사의 표시로 받아주시오."}}
rows[40968]={title={{28,2127974588},"벽이 무너져 내린다"},description={{991,397946633},"참으로 중대한 사건입니다. 그레이메인 성벽이 마침내 무너졌습니다.$B$B 오랜 고립 기간 동안 길니아의 왕좌는 알테라시 귀족인 할로우 가문의 손에 넘어갔습니다. 그들은 얼라이언스에 대해 노골적인 적대감을 품고 있기에, 길니아 내부에 뿌리내린 반란군을 지원하는 것이 우리에게 매우 중요합니다. 그들은 스스로를 레이븐우드 반란군이라고 부르며, 그들의 노력 덕분에 길니아의 성문이 다시 열렸습니다. 그들의 지도자가 얼라이언스에 도움을 요청했습니다.$B$B 저는 포드라곤 경으로부터 길니아 해방을 위한 레이븐우드 반란군의 투쟁을 지원하기 위해 모든 건장한 병력을 파견하라는 명령을 받았습니다. 서쪽으로 실버파인을 지나 그레이메인 성벽까지 이동하십시오. 성벽 너머 해안선을 따라 레이븐샤이어 마을이 자리 잡고 있습니다. $B$B도착하면 레이븐우드 경을 찾아가 얼라이언스가 동맹에 대한 변함없는 헌신을 보여줄 것을 당부하십시오."},objectives={{68,1837848614},"길네아로 가서 다리우스 레이븐우드 경에게 지지를 표명하십시오."},progress={{31,549305730},"여기서 당신을 본 적이 없는 것 같은데요."},completion={{727,1343480299},"약속했던 지원군이 드디어 도착했군.$B$B겐 그레이메인이 동맹을 깊이 불신했던 것은 그의 가장 큰 오판 중 하나였음에 틀림없다. 그의 그런 결정에 대한 이유는 이해할 수 있지만, 나는 결코 전적으로 동의할 수는 없었다. 하지만 이제 모든 것은 과거의 일이고, 곱씹어봤자 소용없지.$B$B너와 막강한 동맹의 힘을 진심으로 환영한다. 레이븐샤이어는 작은 마을이지만, 우리 사랑하는 길니아를 다시 불태울 회복력과 희망의 불꽃을 품고 있다. 때가 되면 우리는 너와 함께 길니아 성벽 안에서 성대한 연회를 베풀도록 초대하겠다. 하지만 그런 축제를 즐기기 전에 해야 할 일이 많다."}}
rows[40969]={title={{15,1364627114},"크리스탈베인 광석"},description={{967,1622654566},"길네안의 단단한 광석을 다루는 건 결코 쉬운 일이 아니죠. 특히 그레이메인 성벽이 닫혔을 때는 좀 더 이국적인 광석을 갈망했던 적도 있었어요. 아, 얼마나 간절했는지! 하지만 이제 운명이 $B$B제게 미소 지었습니다. 드디어 다시 한번 그 희귀한 광석들을 다룰 기회를 얻었죠. 특히 제 마음속에 특별한 자리를 차지하는 광석이 하나 있는데, 바로 크리스탈베인입니다. 수습 시절에 그 광석을 다룰 수 있었던 영광을 누렸죠. 정말 아름다운 광석이었어요. 강하고 내구성이 뛰어나며, 제련하는 재미도 쏠쏠했죠. 그 광석을 다시 갖게 된다면 반란군에게는 진정한 축복이 될 겁니다. 하지만 안타깝게도 $B$B크리스탈베인은 머나먼 가시덤불 골짜기 땅에서만 발견되는 보물입니다. 혹시 운 좋게 무법항에 발을 들여놓게 된다면, 크랭크라는 이름의 고블린을 찾아보세요. 그는 예전에 제가 그 귀한 광석을 구할 때 늘 의지하던 사람이었거든요. 내가 보냈다고 전해줘. 그럼 어쩌면, 정말 어쩌면, 그가 다시 한번 크리스탈베인을 구해줄 수 있을지도 몰라."},objectives={{24,597323302},"무법항에서 크랭크를 찾으세요."},progress={{17,2037304073},"무엇을 원하세요?"},completion={{64,2131797310},"소문이 사실이었군요. 길네아스가 다시 영업을 시작했습니다."}}
rows[40970]={title={{24,1081778212},"크리스탈베인 광산 정화 작업"},description={{947,1945029602},"아, 토드, 참 좋은 대장장이였지. 금속 다루는 솜씨는 정말 대단했어. 그건 인정해 줄게. 그런데 말이야, 토드가 원하는 광석은 내가 좀 도와줄 수가 없거든. 좀 곤란한 상황이야. 토드가 말하는 그 수정광산이$B$B 그 성가신 바실리스크들로 가득 차 버렸거든. 정말 끔찍한 생물들이지. 그놈들이 쳐다보기만 해도 뿅 하고 수정으로 변해버린다고! ​​그래서 우리 고블린들은 당연히 그곳에 가까이 가지 않고 있어. 하지만 $B$B자네가 무모하든 용감하든 간에, 그 동굴에서 바실리스크들을 소탕해 줄 수 있다면, 거래를 하나 할게. 자네가 그 힘든 일을 하고, 거기서 찾은 광석은 자네 거로 줄게. 공평한 거래지. 단, 자네 배낭에 들어갈 만큼만 가져가야 해. 그 무거운 광석을 산더미처럼 들고 다니게 할 순 없지. 자, 모험가님,$B$B 어떠십니까? 도전해 보시겠습니까? 그렇다면 여기서 북동쪽으로 향하세요. 그러면 수정맥 광산이 있을 겁니다."},objectives={{114,1321247869},"무법항에서 크리스탈베인 광석 10개를 모으고, 트래쉬테일 바실리스크 6마리와 아이언조 바실리스크 6마리를 처치하여 크랭크 피즐버브를 획득하세요."},progress={{53,547799151},"음, 제가 이미 말씀드렸잖아요. 당신은 광산을 정리해야 해요."},completion={{503,851424042},"이봐, 친구! 솔직히 네가 거기서 무사히 나올 줄은 몰랐어. 정말 대단한 생존자야! 그래서, 그 끔찍한 바실리스크들이 광산에서 완전히 사라졌다는 거야? 정말 다행이군! 채굴팀을 당장 보낼게!$B$B자, 네가 캐낸 그 광석은 내놔. 걱정 마, 내가 예쁘게 포장해서 토드에게 멋진 편지도 붙여줄게. 오랜만이지? 토드가 내 소포를 받으면 정말 좋아할 거야."}}
rows[40971]={title={{20,764773781},"크리스탈베인 배송"},description={{476,1164552204},"좋아, 친구, 기다리던 소포 여기 있어. 크리스탈베인, 깔끔하게 포장해서 배송 준비 완료됐어. 잘 보관해 줘, 알겠지?$B$B 자, 토드를 만나면 내 말 좀 전해 줘. 반란 관련 일들 다 끝나면 꼭 들르라고. 오랜만에 만나서 이런저런 얘기도 나누고 근황도 얘기하자. 토드한테 행운을 빌어 줘, $B$B알겠지? 난 이제 볼일이 있어서. 돈도 벌어야 하고 거래도 성사시켜야 하거든."},objectives={{73,246735886},"크리스탈베인 화물을 길니어스의 레이븐셔에 있는 토드 볼더에게 전달하세요."},progress={{4,273767400},"예?"},completion={{711,734717377},"내 눈을 믿을 수가 없군! 내가 기억하던 그대로의 수정맥 광석이잖아. 이건 정말 보물이야. 이 귀한 광석으로 어떤 멋진 무기를 만들어낼지 벌써부터 눈앞에 선하군.$B$B래리! 대장간에 불을 붙여라! 이 귀한 광석으로 얼마나 뛰어난 예술성을 발휘할 수 있는지 보여줄 시간이다. 모두가 감탄하고 부러워할 만한 걸작을 만들어내자.$B$B아, 제가 예의가 없었군요. 죄송합니다. 당신의 노고에 진심으로 감사드립니다. 감사의 표시로 이 작품을 받아주십시오. 제가 최고의 정성과 기술을 다해 만든 작품 중 하나입니다. 친구여, 우리의 협업을 기념하는 소중한 기념품이 되기를 바랍니다.$B$B자, 이제 작업에 들어가 볼까요?"}}
rows[40972]={title={{13,1258800504},"반란"},description={{373,676584536},"길네아의 잔해에 오신 것을 환영합니다.$B$B 눈앞에 펼쳐진 광경은 당신이 상상했던 웅장함과 화려함과는 거리가 멀지도 모릅니다. 한때 인간 권력의 강력한 요새였던 이곳은 이제 시간의 흐름과 전쟁의 참화를 보여주는 증거로 남아 있습니다. 우리 또한 세상의 많은 곳을 덮친 운명에 굴복하고 말았습니다. 잠시$B$B 시간을 내어 한 노기사의 이야기에 귀 기울여 보십시오."},objectives={{39,828411043},"다리우스 레이븐우드의 이야기를 들어보세요."},progress={{33,834377450},"길네아스의 상황은 심각합니다."},completion={{134,1206046840},"이제 아시겠죠. 많은 세부 사항을 생략했지만, 지금은 잡담할 시간이 없습니다. 새롭게 얻은 동맹의 힘을 바탕으로 지금 당장 행동해야 합니다."}}
rows[40973]={title={{18,1818891809},"대중 조화"},progress={{353,255751691},"돌아왔군, 그 파편들은 준비됐나?"},completion={{143,296844473},"훌륭한 작업입니다. 조화 과정은 특히 이렇게 연습을 많이 하면 오래 걸리지 않아요. 혹시 더 좋은 방법을 찾으시면 저에게 알려주세요."}}
rows[40974]={title={{19,1537755744},"죽음 이후의 복수"},description={{576,1706120974},"살아생전 저는 그레이메인 가문에 충성하는 군인이었습니다. 그레이샤이어 전투에 참전하여 스컬지에 대한 위대한 승리를 만끽했죠. 하지만 위대한 전사라고$B$B 자부하던 저는 동료들과 함께 거대한 짐승의 매복 공격을 받았습니다. 그 거대한 워겐은 우리를 갈기갈기 찢어놓았고, 저도 필사적으로 저항했지만 결국 쓰러지고 말았습니다. 이제$B$B 저는 이곳에서 끝없는 실패의 기억 속에서 고통받고 있습니다. 저는 그 워겐에게 복수하고 싶습니다. 그 워겐의 이름은 스나클로입니다. 그는 이곳 서쪽, 블러드클로 진영 근처 깊은 동굴에 숨어 있는 것으로 알려져 $B$B있습니다. 그의 발을 가져오면 보상을 받겠습니다."},objectives={{76,940625797},"스나르클로의 발을 길니어스에 있는 스틸워드 교회의 도미닉 라슨에게 가져다 주세요."},progress={"Has the deed been done $c?","$c번 거래가 완료되었습니까?"},completion={{213,975941467},"<도미닉 라슨의 얼굴에 비웃음이 걸려 있다.>$B$B잘했군. 자네의 노고에 찬사를 보내네. 나에게 영원한 불멸의 저주를 내린 괴물을 물리쳤으니, 감사의 표시로 이것 하나를 주네."}}
rows[40975]={title={{25,1250986585},"판사와 유령"},description={{638,93700553},"<유령이 서서히 현실로 모습을 드러내기 시작한다. 바람 소리가 울려 퍼지는 가운데 유령이 $B$B말을 시작한다.>생전 내 이름은 칼 글레이모어였고, 우리 가문은 길니어스에서 명망 있는 가문이었다. 하지만 이제 우리는 아무것도 아니다. 모두 산 자의 $B$B세계에서 사라졌다.우리는 모두 음모 혐의로 재판을 받았다. 아무런 근거도 없는 주장으로. 내 자식들은 잔혹한 서덜랜드 판사에게 하나씩 살해당했다. 그의 망치질 한 번 한 번에 판결이 내려졌다.우리는$B$B 본보기가 되도록 정해졌고, 이제 나는 이 세상을 떠돌며 분노에 휩싸여 있다…내게 평화를 $B$B가져다주시오. 길니어스 시에서 서덜랜드 판사를 찾아 그의 목숨을 끊어주시오. 일이 끝나면 나는 알게 될 것이오."},objectives={{99,1138522770},"길니어스 시내의 글레이모어 농장에서 분노한 유령을 처치하기 위해 서덜랜드 판사를 살해하십시오."},progress={{39,1837060581},"<고요함이 몽환적인 바람에 실려 감돈다.>"},completion={{249,234470623},"당신은 잘 해냈습니다. 이제 저는 완전히 평화를 찾았습니다.$B$B저승이 제 영혼의 잔재를 삼켜가는 것을 느낍니다. 이제 떠나서 쉴 시간입니다.$B$B당신이 베풀어주신 모든 것에 감사하는 마음으로 물건 하나를 남겨두었습니다.$B$B<유령이 서서히 사라진다.>"}}
rows[40976]={title={{13,1903070390},"워겐과의 전쟁"},description={{413,624675925},"길네아의 늑대인간들은 짐승 무리치고는 놀라울 정도로 조직적입니다. 그들의 무리는 우리의 영향력 확장에 상당한 골칫거리였죠. I, 저는 그들의 지휘 체계를$B$B 끊어낼 수 있는 누군가가 필요합니다. 목적 없는 늑대인간 무리가 결국 우리에게 훨씬 더 도움이 될 겁니다. 서쪽으로 가서 블러드클로 알파가 사는 동굴을 찾아 처치하십시오. 그러면 그들의 무리가 우리에게 대항하여 조직적으로 움직이지 못할 겁니다."},objectives={{78,815836770},"길니아스에 있는 스틸워드 교회에서 블러드클로 알파 9마리를 처치하면 데스스토커 버논을 얻을 수 있습니다."},progress={{86,874421925},"조심해서 행동하시길 바랍니다.$B$B당신의 적은 당신이 생각하는 것만큼 약하지 않습니다."},completion={{285,1709630009},"잘 해냈습니다. 알파들이 흩어졌으니 지배권을 둘러싼 다툼이 벌어지겠죠. 하지만 그 결과가 어떻든 우리는 상관할 바가 아닙니다. 우리는 이미 짐승의 머리를 제거했으니까요.$B$B어둠의 여왕을 섬긴 당신의 노력은 결코 헛되지 않을 겁니다. 당신의 노고에 대한 찬사로 받아들이세요."}}
rows[40977]={title={{24,72556913},"에본미어 박쥐떼 출몰"},description={{381,1979160146},"이봐, 너. $B$B박쥐 박멸에 대해 아는 거 있어? 지난 몇 주 동안 정말 지옥 같았어. 박쥐들을 쫓아내려고 온갖 노력을 다했지만 번번이 실패했지. 혹시 부탁 하나만 들어줄 수 있을까? 이 성가신 $B$B박쥐들을 좀 없애주면 좋겠어. 에본미어 농장을 복구하려면 박쥐들을 없애야 해. 개체 수를 줄여서 열두 마리 정도 잡아서 내게 와 줘."},objectives={{74,1912296860},"길니어스에 있는 에본미어 농장에서 조슈아 에본미어를 위해 사악한 날개를 가진 새끼 박쥐 12마리를 처치하세요."},progress={{27,2127541848},"그래서 일이 끝난 건가요?"},completion={{124,1712395910},"이제야 숨을 쉴 수 있을 것 같아. 이 지긋지긋한 벌레들이 숲을 떼 지어 돌아다니는데, 적어도 이제는 그 수가 줄어든 것 같아 다행이야."}}
rows[40978]={title={{27,1312043662},"에본미어 워겐 침입"},description={{462,624898152},"길니아의 늑대인간들은 올드록 고개의 그레이메인 성벽이 파괴된 직후에 나타났습니다. 아시다시피, 강력한 리치가 이 땅을 침략하여 그레이샤이어를 파괴했거든요. 이제 숲은 늑대인간들로 가득 차서 언제라도 제 농장을 덮칠 기세입니다. 늑대인간들의 가죽을$B$B 모아서 앞으로의 공격을 막아주세요. 블러드클로와 나이트하울 늑대인간 무리에게서 가죽 6개를 모으면 됩니다. 이 무리들은 서쪽과 남서쪽에서 찾을 수 있습니다."},objectives={{97,998367658},"길니아스에 있는 에본미어 농장의 조슈아 에본미어에게 블러드클로 가죽 6개와 나이트하울 가죽 6개를 모아 주세요."},progress={{66,829324102},"밤에는 조심하세요. 어둠의 기운은 언제나 도사리고 있습니다."},completion={{88,425793570},"워겐이 패배했다고?$B$B<그의 얼굴에 비열한 미소가 번진다.>$B$B잘했군, 외부인."}}
rows[40979]={title={{16,996627527},"에본미어 사건"},description={{526,32524766},"자네가 내게 귀중한 동맹임을 증명했으니, 이제 내가 처리해야 할 더 급한 일이 있네. 3주 전에 내 $B$B농장이 도둑맞았지. 더스티반 블랙카울이라는 사기꾼이 고용되어 에본미어 농장의 소유권을 가로챘어! 그는 그레이메인의 하수인으로, $B$B충성스러운 개처럼 그를 섬기고 있지. 이 배신에 대한 대가를 치르게 하고, 우리 가문의 소유권을 되찾아야 해. 자네가 이 일을 해낸다면, 그에 합당한 보상을 해주겠네. $B$B자네가 길니아스 시 깊숙한 곳에서 그 사기꾼을 찾아낼 수 있을 거라고 확신하네."},objectives={{102,941890318},"길니아스의 에본미어 농장에서 더스티반 블랙카울을 처치하고 조슈아 에본미어를 위해 에본미어 소유권 증서를 되찾으십시오."},progress={{26,737692536},"그래서, 무슨 소식이 있나요?"},completion={{185,253767496},"당신 덕분에 그토록 바라던 평화를 얻었습니다.$B$B이 덕분에 저는 늘 해왔던 대로 살아갈 수 있게 되었습니다. 제 물건을 돌려주신 것에 대한 감사의 표시로 몇 가지 보상을 준비했습니다."}}
rows[40980]={title={{15,2035180142},"그레이메인 증오"},description={{685,1913981039},"내 동생 프랭클린 블랙하트는 살아있었지만, 그는 여전히 내 동생이었다. 그는 레이븐우드 반란에 가담하여 싸웠다. 바로 그곳에서 그레이메인의 매복 공격을 받아 최후를 맞았다. 단 한 사람도 살아남지 못했고, 진영은 완전히 불타 없어졌다. 그의 처참하게 $B$B훼손된 시신을 보는 순간, 그 어떤 것보다도 가슴이 아팠다. 그의 죽음에 대한 슬픔은 아직도 내 마음속 깊은 곳에 남아 있다. 나는 이 끔찍한 짓을 저지른 자들에게 복수하고 싶다. 길니아에 숨어 있는 그레이메인들을 처단해야 한다. 그들은 동쪽, 레이븐샤이어 북쪽이나 이곳 서쪽의 드라이록 계곡에 숨어 있다. 그들의$B$B 대의에 충성을 맹세하는 자는 누구든 그레이메인 문장 40개를 가져오도록 하라."},objectives={{116,2138488651},"그레이메인 가문에 충성하는 자들을 처치하고, 그들에게서 길니아스의 해리슨 블랙하트를 위해 그레이메인 문장 40개를 모으십시오."},progress={{78,138107873},"돌아오셨군요, 제 형을 살해한 자들에게 정의를 구현하셨습니까?"},completion={{132,1227639142},"아, 복수의 기분이 이런 건가?$B$B솔직히 말해서, 나는 공허함만 느낄 뿐이야. 진범은 아직 잡히지 않았고, 반드시 찾아내야 해."}}
rows[40981]={title={{21,768230847},"블랙하트 킬러"},description={{498,2099908274},"데스스토커들로부터 프레이시어 요새에 주둔한 벨러 대위가 매복 공격을 사주했다는 소문을 들었습니다. 만약 이 소문이 사실이라면, 바로 그 남자가 제 동생을 죽인 $B$B범인입니다. 프랭클린의 시신에서 매우 귀중한 보석, 블랙하트 목걸이가 사라졌습니다. 저는 그 오만한 남자가 목걸이를 가져갔다는 것을 확신합니다.$B$B 프레이시어 요새는 서쪽 멀리, 레이븐셔를 내려다보는 외딴 섬에 있습니다. 그를 처치하고 목걸이를 되찾으십시오."},objectives={{117,2006454972},"길니아에 있는 해리슨 블랙하트를 위해 블랙하트 목걸이를 되찾으려면 프레이시어 요새를 공격하고 벨러 대장을 처치하십시오."},progress={{28,1813417036},"목걸이를 찾으셨나요?"},completion={{168,591541789},"<해리슨 블랙하트는 부드러운 손길로 보석을 받아들고 잠시 그 ​​아름다움을 감상했다.>$B$B이것을 되찾아주셔서 정말 감사합니다. 제게는 정말 소중한 물건입니다."}}
rows[40982]={title={{21,1119840715},"프랭클린을 추모하며"},description={{194,1951151489},"마지막으로 부탁 하나만 드리겠습니다. 어쨌든 이 목걸이를 되찾으셨으니, 당연히 해주셔야 할 일이라고 생각합니다. 프랭클린의$B$B 무덤에 이 목걸이를 놓아주십시오. 이렇게라도 그를 기릴 수 있을 겁니다."},objectives={{55,1648398807},"블랙하트 목걸이를 프랭클린의 무덤에 놓으십시오."},progress={{9,1854390496},"음, 네?"},completion={{209,1811712360},"<해리슨은 고개를 끄덕이며 만족스러운 표정을 지었다.>$B$B당신은 저를 위해 많은 일을 해주셨고, 저는 진심으로 감사드립니다. 프랭클린도 마찬가지일 겁니다.$B$B<해리슨에게서 껄껄 웃음이 새어 나왔다.>$B$B이것 중 하나를 저희가 드리는 감사의 표시로 받아가십시오."}}
rows[40983]={title={{19,1059588082},"노르다나르에게 보고"},description={{373,1051272645},"저는 악마들을 막아내야 할 의무가 있으며, 그 의무 때문에 이곳에 머물러야만 합니다. 노르다나르에게서 소식이 없는 것이 걱정스럽지만, 점점 커지는 악마의 세력 때문에 지연되고 있는 것 $B$B같습니다. 부디 제 보고서를 정상 꼭대기에 있는 노르다나르에게 전해주시기 바랍니다. 길을 따라 마을까지 가십시오. 대드루이드 드림윈드를 찾아 이 편지를 전해주세요."},objectives={{76,1459567383},"엔다라스에게서 받은 보고서를 하이잘의 노르다나르에 있는 대드루이드 드림윈드에게 가져다 주십시오."},progress={{30,614053714},"어떻게 도와드릴까요, 외부인이시여?"},completion={{144,1006616289},"음, 다크위스퍼 협곡에 악마의 기운이 감도는 건 내 예상이 맞았군. 그들이 우리 방어벽을 뚫고 들어올 방법을 찾아내는 건 시간 문제일지도 몰라."}}
rows[40984]={title={{25,667918690},"세나리우스의 룬스톤"},description={{568,1816786078},"우리는 세나리우스 룬스톤을 재활성화하는 임무를 맡았습니다. 한때 이 돌을 통해 흐르던 마법 에너지는 노르드라실 룬스톤과 연결되어 이곳과 노르다나르 사이를 이동할 수 있게 해주었습니다. 하지만 $B$B외계의 마법이 이 과정을 방해하고 있습니다. 정확히 무슨 일이 벌어지고 있는지 알아내기 위해 재료가 필요합니다.$B$B 나무껍질 퍼볼그에게서 나무껍질 영혼 구슬 다섯 개를, 미스투프에게서 뿔 세 개를, 그리고 마지막으로 이 지역에 서식하는 진흙 같은 생물에게서 반짝이는 점액 하나를 모아 주십시오."},objectives={{118,261697671},"하이잘 산기슭 근처에서 부톡 구름뿔을 얻으려면 나무껍질 정령 구슬 5개, 미스투프 뿔 3개, 반짝이는 점액 1개를 모으세요."},progress={"Have the materials been acquired $c?","$c번 자재를 확보하셨습니까?"},completion={{67,2115217811},"잘하셨습니다. 저는 이미 의식을 위한 준비를 시작했습니다."}}
rows[40985]={title={{20,1035746566},"룬스톤 의식"},description={{193,136496502},"의식을 준비했습니다. 당신이 모아주신 재료들을 이용하면 룬스톤에 깃든 마법을 밝혀낼 수 있을 겁니다. 잠시 시간을$B$B 주시면, 준비가 되면 말씀해 주세요."},objectives={{47,706047654},"부톡 클라우드혼이 의식을 마칠 때까지 기다리세요."},progress={{44,1785328475},"<부톡 클라우드혼은 의식에 완전히 몰두한 듯 보인다.>"},completion={{188,13438870},"이 마법의 근원을 밝혀냈습니다. 사티로스가 룬스톤을 더럽히고 저주를 걸었습니다.$B$B<부톡 클라우드혼이 한숨을 내쉰다.>$B$B이 문제를 해결하려면 상당한 노력이 필요할 겁니다."}}
rows[40986]={title={{23,331238346},"아테렐렉스의 클러치"},description={{583,1386053892},"강력한 사티로스 저주를 푸는 것은 결코 쉬운 일이 아니며, 특히 우리가 가진 마법으로는 더욱 그렇습니다. 우리는 '아테렐렉스의 손아귀'라는 사티로스 유물을 만들어야 합니다. 각 사티로스 부족은 특정한 지팡이를 가지고 있습니다. 특정 저주를 풀기 위해서는 모든 지팡이를 하나로 연결하여 특정한 마법을 발동시켜야 합니다. 아테렐렉스의 손아귀를 만들기 위해서는 하이잘의 $B$B바일머스크 사티로스 부족이 가진 '아스의 지팡이', 아즈샤라의 레가시 사티로스 부족이 가진 '에레의 지팡이', 그리고 마지막으로 제이드파이어 사티로스 부족이 가진 '렉스의 지팡이가 필요합니다."},objectives={{105,1860137087},"하이잘 산기슭 근처에서 부톡 클라우드혼을 위해 '아스의 지팡이', '에레의 지팡이', '렉스의 지팡이'를 모으십시오."},progress={{40,495626825},"그래서 필요한 것을 모두 확보하셨나요?"},completion={{123,55372508},"<부톡 클라우드혼은 안도의 한숨을 내쉬었다.>$B$B당신이 돌아오지 않을까 봐 걱정했습니다. 제 걱정이 현실이 되지 않아서 다행입니다."}}
rows[40987]={title={{12,1136368817},"주입된 돌"},description={{382,1046322960},"아테렐렉스의 클러치는 강력한 자연 에너지에서 힘을 끌어내는 원소 마법에 의존합니다. 우리가 그토록 원하는 마법을 사용하려면 마법이 부여된 돌을 얻어야 $B$B합니다. 강력하고 격노한 돌 정령들이 그러한 돌을 지니고 있는 것으로$B$B 알려져 있습니다. 타나리스 동쪽에 있는 텔아빔 섬에서 격노한 바위 정령들을 찾아 그곳으로 가서 마법이 부여된 돌을 얻으십시오."},objectives={{101,1970487496},"하이잘 산기슭 근처에 있는 부톡 클라우드혼을 얻으려면 텔아빔의 바위 정령에게서 마법이 부여된 돌을 획득하세요."},progress={"Has the work been completed $c?","$c번 작업이 완료되었습니까?"},completion={{82,540579334},"겉보기엔 평범한 돌처럼 보이지만, 이 신비로운 돌은 상당한 힘을 지니고 있습니다."}}
rows[40988]={title={{19,1928657060},"룬스톤의 저주"},description={{421,412418990},"필요한 아이템들을 사용해 저주를 풀려고 시도해 봤지만, 아직 뭔가 잘못된 것 같습니다. 룬스톤을 자세히$B$B 조사해 보니, 룬스톤의 일부가 떨어져 나간 것을 알게 되었습니다. 추측컨대, 잘틱스라는 사티로스가 이 조각을 조종하고 있는 것 같습니다. 그는 이 조각을 이용해 저주를 무기한으로 유지할 수 있습니다. 잘틱스를$B$B 찾아 그에게서 룬스톤 조각을 되찾아 오십시오."},objectives={{122,1392713320},"하이잘에서 사티로스 잘틱스를 찾아 처치하고, 하이잘 기슭 근처에서 부톡 클라우드혼을 위한 룬스톤 조각을 회수하세요."},progress={{25,1432128638},"잘틱스를 추적해 보셨나요?"},completion={{116,139428891},"<부톡 클라우드혼이 룬스톤 조각을 제자리에 다시 끼워 넣습니다.>$B$B잘했어, 내가 예상했던 것보다 훨씬 잘했어."}}
rows[40989]={title={{22,1633611077},"룬스톤 재활성화"},description={{289,1549316430},"모든 준비가 완료되면 룬스톤의 힘이 곧 다시 발휘될 것입니다. 노르다나르에 있는 고대의 글란타스와 이야기해 주십시오. 그가 바로 하이잘에 있는 룬스톤의 힘을 관장하는 자입니다. 그의 마법을 이용하면 두 룬스톤 사이를 순간 이동할 수 있을 것입니다."},objectives={{54,437584431},"하이잘의 노르다나르에 있는 고대의 글란타스와 대화하세요."},progress={{4,273767400},"예?"},completion={{70,1968640926},"<고대 글란타스는 길고 말없이 응시한다.>$B$B룬스톤?"}}
rows[40990]={title={{21,1593302525},"룬스톤 홀"},description={{594,1995180749},"<삐걱거리는 고대의 존재가 투덜거린다.$B$B>부톡이 세나리우스의 룬스톤을 다시 활성화하는 데 성공한 것 같군. 하지만 아직 해결해야 할 마지막 문제가 하나 남아 있다.$B$B몇 년 전, 나는 엔텔라르 베일브랜치라는 드루이드에게 룬스톤 관리를 맡겼었지. 마법을 활성화하는 룬스톤 홀은 그가 타락의 유혹에 넘어갔을 때 그의 손에 있었다.최근 소식에 따르면, $B$B엔텔라르 베일브랜치는 정신이 혼미해진 채 윈터스프링 주변을 헤매고 있다고 한다. 룬스톤 홀을 되찾아오면 하이잘의 룬스톤에 접근할 수 있도록 허락하겠다."},objectives={{136,181963413},"하이잘의 노르다나르에 있는 고대의 글란타스를 찾아 겨울봄을 배회하는 엔텔라르 베일브랜치에게서 룬스톤 홀을 되찾으세요."},progress={{4,273767400},"예?"},completion={"<Glanthas the Ancient lets out a creaking exhale of approval.>$B$BYou have done well in finding this. It eases my mind to know you have brought peace to Enthelar. He suffered great hardships, and I am sure he was relieved by your actions.$B$BAs I promised, you can now access the Runestones of Hyjal, offering transport between them. Use this power wisely, $c.$B$BFor your considerable efforts in restoring the Runestones I have prepared a suitable commendation.","<고대 글란타스가 만족스러운 듯 삐걱거리는 숨을 내쉬었다.>$B$B이것을 찾아낸 것은 훌륭한 일이다. 네가 엔텔라르에게 평화를 가져다주었다니 마음이 놓인다. 그는 큰 고통을 겪었는데, 네 행동으로 안도했을 것이다.$B$B약속대로 이제 하이잘의 룬스톤에 접근할 수 있고, 룬스톤 사이를 이동할 수 있게 되었다. 이 힘을 현명하게 사용하거라.$c$B$B룬스톤을 복원하는 데 기울인 상당한 노력에 대한 보상으로 적절한 표창장을 준비했다."}}
rows[40991]={title={{18,564657657},"컬렉션을 위해"},description={{784,1138490686},"전생에 살아있는 인간이었던 저는 아주 먼 옛날 우리 조상인 아조타족의 이야기에 매료되었습니다. 그들의 고대 지식과 유물은 저를 사로잡았죠. 하지만 길니아스의 혼란스러운$B$B 상황 때문에 아조타족에 대한 연구는 중단되었고, 저는 이 좁은 성벽 안에 갇혀버렸습니다. 이제 마침내 성문이 열렸지만, 버려진 자로서 인간의 땅으로 발을 딛는 것은 제게 파멸을 의미할 것입니다. 그러나$B$B 저는 위험한 불모의 땅에 자리 잡은 코르탄이라는 외딴 도시에 대한 소문을 들었습니다. 전설에 따르면 버려진 성벽 안에는 강력하고 불가사의한 아조타족 유물, 코르탄의 손이 숨겨져 있다고 합니다. 이 유물의 진정한 정체는 아직 밝혀지지 않았지만, 분명 큰 의미를 지니고 있으며 제 수집품에 귀중한 가치를 더할 것이라고 확신합니다."},objectives={{80,2084755986},"코르탄의 손을 길네아스에 있는 스틸워드 교회의 어둠의 주교 모르드렌에게 가져다 주십시오."},progress={{39,734776292},"배드랜드로 가는 여정은 험난하다. 어서 출발하라."},completion={{297,914700648},"헤아릴 수 없군. 아조탄 유물이 이제 내 손아귀에 들어왔다.$B$B<어둠의 주교가 불길하게 웃는다>$B$B우리 조상들이 나처럼 혐오스러운 존재가 자신들의 소중한 유물을 손에 쥐고 있는 모습을 목격했을 때 어떤 반응을 보였을지 상상해 보는 건 얼마나 재밌는 일인가. 분명 그들은 영원한 잠 속에서 이 광경에 경악하며 몸을 뒤척이고 있을 것이다."}}
rows[40992]={title={{17,1116085362},"파울하이드 잡종견"},description={{772,364243676},"끔찍한 가죽을 뒤집어쓴 놀들은 아마도 당신이 이곳으로 오는 여정에서 마주쳤을 겁니다. 여느 놀들처럼 지능이 낮고 야만성과 무력에만 의존하는 자들이죠. 그들과 소통하거나 협력하는 것은 헛수고일 뿐입니다. 섭정들은 이를 외면하고$B$B 있고, 소위 반란군은 자기들 일에만 정신이 팔려 있습니다. 그러니 우리가 이 문제를 해결해야 할 차례입니다. 물론 우리의 동기는$B$B 순수한 것이 아닙니다. 이 놀들은 언더시티에서 보내지는 중요한 물자를 가로채는, 넘을 수 없는 장애물이 되어버렸습니다. 이런 방해는 용납할 수 없습니다. 남쪽으로 진격하여 이 끔찍한 괴물들을 최대한 많이 처치하십시오. $B$B성공의 확실한 증거로 가죽 발 16개를 가져와 제게 돌아오십시오."},objectives={{60,77842223},"스틸워드 교회에 있는 할란 밸로우에게 파울하이드 파우 16개를 가져다 주세요."},progress={{153,1680001584},"사우스마이어 과수원에서 엄청난 수의 파울하이드 놀 무리를 발견할 수 있습니다. 실버파인에서도 이미 그들의 습격대가 목격되었습니다. 반드시 막아야 합니다."},completion={{380,264346232},"하! 당신의 변함없는 노력 덕분에 수도와의 통신망이 강화되어 길니아스에서의 작전 안전이 확보되었습니다. 포세이큰을 향한 당신의 헌신은 실로 숭고합니다.$B$B감사의 표시로 이것을 드리겠습니다. 비록 사치스러운 것은 아니지만, 앞으로 우리 앞에 놓인 험난한 땅을 헤쳐나가는 데 분명 도움이 될 것입니다."}}
rows[40993]={title={{21,156035155},"더 큰 마법을 통해"},description={{991,343812491},"비열한 그레이메인 세력, 나를 죽음으로 몰아넣고 내 교회를 모독한 자들. 왜 하필 나를 노렸을까?$B$B 그 답은 여전히 ​​수수께끼로 남아 있지만, 이 장소의 중요성과 깊은 관련이 있음을 직감한다. 수 세기 전, 바로 이 언덕에서 길네아 군대가 모든 역경을 딛고 아라토르를 물리치는 전투가 벌어졌다. 나는 그들의 승리의 열쇠가 이 땅속에 묻혀 있다고 확신하며, 섭정의 피에 대한 갈망이 이 잠재된 힘을 악용하려 한다고 믿는다. 우리는$B$B 이 미스터리를 깊이 파헤쳐야 한다. 그러한 힘을 발견한다면 우리에게 엄청난 이점을 가져다줄 것이다. 나는 이 낡은 고서들을 샅샅이 뒤져 우리의 목표물에 대한 해답을 찾을 $B$B것이다. 그동안, 자네는 잊혀진 땅로 향하는 위험한 여정에 나서야 한다. 그곳, 악마들 사이에서 크시토스의 눈을 찾아 되찾아야 합니다. 이 유물은 잊혀진 그림자의 에너지를 다룰 수만 있다면 과거의 비밀을 밝혀낼 수 있는 능력을 지녔다고 전해집니다."},objectives={{102,36075891},"데솔레이스에서 크시토스의 눈을 찾은 다음, 길니아스의 스틸워드 교회에 있는 어둠의 주교 모르드렌에게 돌아가십시오."},progress={{155,1177378797},"크시토스의 눈이 데솔레이스의 섀도우 카운슬의 손에 들어갔다는 소문이 돌고 있다. 나는 어둠의 속삭임에서 ‘섀도우브레이크’라는 이름을 들었다."},completion={{471,1763586423},"눈… 아, 그렇습니다. 당신이 가까이 다가오자 그 사악한 기운이 분명하게 느껴졌습니다.$B$B더 가까이 오십시오. 끊임없는 연구와 수많은 고서를 통해 저는 매우 흥미로운 사실을 밝혀냈습니다. 전설적인 스틸워드 전투에서 초대 그레이메인은 헤아릴 수 없는 어둠을 휘둘렀던 것으로 보입니다.$B$B이제 크시토스의 눈을 손에 넣었으니, 저는 시간의 심연 속으로 뛰어들 것입니다. 우리가 지금 맞서 싸우고 있는 이 강력한 힘의 진정한 본질을 밝혀내려 합니다."}}
rows[40994]={title={{21,907593332},"레이븐우드 홀"},description={{1002,306014233},"나는 진실을 목격했다. 마치 내가 직접 그곳에 있었던 것처럼 스틸워드 제1차 전투의 실상을 엿보았다. 가라론 그레이메인의 전술적 기량을 기록한 고대 서적들은 이제 기만의 산물임이 드러났다. 그는 불길한 힘을 휘둘렀다. 내 이성조차 이해하기 어려운 존재들로부터 비롯된 힘이었다. 그의 손에는 어둠의 정수를 다스리는 통로인 홀이 쥐어져 있었다. 그 위력은 공포 그 자체였다. 우리는 $B$B이 힘이 적의 손아귀에 넘어가는 것을 용납할 수 없다. 만약 그들이 진실을 알게 된다면, 우리의 대의는 파멸할 것이다. 잘 들어라. 내 환영 속에서 나는 그 홀의 모습을 알아보았다. 그것은 한때 레이븐우드 요새에 $B$B있었다. 아아, 이제 요새는 그레이메인 군대의 맹공격으로 폐허가 되었다. 그들이 홀을 차지하지 않기를 기도할 수밖에 $B$B없겠소. 레이븐우드 요새로 가서 흑요석으로 만들어진 홀을 찾아 내게 가져오시오."},objectives={{94,1788646552},"스틸워드 교회에 있는 어둠의 주교 모르드렌을 위해 레이븐우드 요새에서 레이븐우드 홀을 되찾으세요."},progress={{30,1992402334},"이런 힘은... 틀림없이 우리 것이어야 해."},completion={{245,783251568},"아, 결국 찾아냈군.$B$B세월의 흐름은 홀에 큰 타격을 주어 예전의 위력을 약화시켰지만, 약해진 와중에도 그 기운은 부인할 수 없는 어둠으로 가득 차 있으며, 금지된 마법의 잔재가 남아 있다."}}
rows[40995]={title={{17,1171510657},"초월의 힘"},description={{756,1736769454},"이 부서진 무기의 진정한 잠재력을 활용하려면, 그것이 지닌 힘을 주저하지 말고 받아들여야 합니다. 하지만 신중을 기해야 합니다. 현재와 같이 심하게 손상된 상태로는 휘두르는 것은 매우 위험한 일이기 때문입니다. 표면의 균열을 메우고 그 막강한 힘을 되찾기 위해서는 어둠의 흑요석으로 만들어진 강력한 유물이 필요합니다.$B$B 다행히 저는 그러한 유물을 구할 만한 곳을 알고 있습니다. 서쪽으로 향하여 칼림도르의 불모의 땅로 가십시오. 그곳에는 어둠의 요새처럼 자리 잡은 레이저펜 다운스가 있습니다. 그 깊은 곳에는 사악한 리치가 언데드 하수인들을 거느리고 사악한 마법에 휩싸여 은신처를 $B$B마련했습니다. 그의 불멸의 정수가 담긴 부적은 바로 우리가 찾는 흑요석으로 만들어졌다고 전해집니다."},objectives={{142,973664194},"레이저펜 다운즈로 들어가 냉기를 불러오는 자 암넨나르를 처치하고, 길니아스의 스틸워드 교회에 있는 어둠의 주교 모르드렌을 위해 그의 영혼함을 되찾아 오십시오."},progress={"Act quickly, $c. For with each passing moment, his dark powers surge and his influence expands.","서둘러야 해,$c. 시간이 흐를수록 그의 어둠의 힘은 더욱 강해지고 영향력은 더욱 커지고 있어."},completion={"Your unwavering dedication continues to impress me, $c.$B$BYet, during your absence, I delved once more into the past, and it became clear that there is yet another task I must entrust to you.$B$BThe Scepter is still incomplete, lacking a crucial component I have missed earlier.","$c,$B,$B, 당신의 변함없는 헌신에 늘 감탄하고 있습니다. 하지만 당신이 없는 동안 저는 다시 한번 과거를 되짚어보았고, 당신에게 맡겨야 할 또 다른 임무가 있다는 것을 알게 되었습니다.$B,$B홀은 아직 완성되지 않았습니다. 제가 이전에 놓쳤던 중요한 구성 요소가 빠져 있습니다."}}
rows[40996]={title={{18,224434102},"그레이메인 스톤"},description={{776,2098271706},"유감스럽게도, 한때 홀의 꼭대기를 장식했던 수정은 세월의 흐름 속에 사라져 버렸습니다. 그 행방은 여전히 ​​알 수 없으며, 찾아내는 것은 넘을 수 없는 난관이 될지도 모릅니다. 하지만 절망하지 마십시오. 제가 다른 해결책을$B$B 생각해냈습니다.알터랙 계승 위기 당시, 프레스토 경이라는 인물이 길니아스 시티를 자주 드나들며 왕과 깊은 유대감을 형성했습니다. 그는 겐에게 선물로 '자정의 조각'이라는 강력한 유물을 $B$B하사했습니다.그 조각의 타락시키는 영향력에 대한 전설이 무성하며, 그레이메인 탑 안에 단단히 봉인되어 있다고 전해집니다.$B$B당신의 임무는 분명합니다. 자정의 조각을 찾아 홀의 제자리에 되돌려 놓으십시오. 그래야만 홀의 힘이 완전히 되살아날 것입니다."},objectives={{74,3813953},"스틸워드 교회에서 어둠의 주교 모르드렌을 위해 한밤의 조각을 되찾으세요."},progress={{47,330404604},"모험을 떠나기 전에 실력 있는 일행을 모으십시오."},completion={{468,1139502791},"그래, 바로 그거야! 보라, 마침내 내 손에 들어온 한밤의 조각이다.$B$B<다크 비숍은 홀을 ​​세심하게 다듬으며, 수정 조각을 홀 꼭대기에 조심스럽게 고정시켰다.>$B$B임무는 완료되었다. 한때 가라론 그레이메인이 휘둘렀던 불경스러운 힘을 다시 사용할 수 있게 되었지만, 그 악의에 맞설 용기를 가진 자만이 가능하리라.$B$B이 일은 너와 내가 감당할 수 있는 수준을 훨씬 뛰어넘는 것이다. 우리는 임무를 완수했고, 이제 이 홀을 상관에게 바쳐야 한다."}}
rows[40997]={title={{23,1759098693},"어둠의 주교의 선물"},description={{418,500832700},"당신의 노고는 더할 나위 없이 귀중했습니다. 당신이 없었다면 우리의 승리는 그저 아득한 꿈에 불과했을 것입니다. 이 홀을 바리마트라스에게 전달하는 임무는 당신이 맡는 것이 마땅합니다. 그는 이미 이 홀의 중요성을 충분히 알고 있으며 당신의 도착을 간절히 기다리고 있습니다. I는 그를 $B$B기다리게 하지 말라고 강력히 권고합니다. 명심하십시오, 그는 드레드로드이며, 그들의 인내심은 결코 가볍게 여겨서는 안 됩니다."},objectives={{63,1993316599},"가랄론의 홀을 지하 도시에 있는 바리마트라스에게 전달하십시오."},progress={{26,1137810941},"나는 어둠의 여왕을 대변한다."},completion={{743,1183867388},"아, 보십시오, 예상대로 당신의 손에 홀이 들려 있군요.$B$B<바리마트라스가 날카롭고 악마적인 눈으로 당신을 응시합니다>$B$B진정으로, 그 안에 잠재된 어둠은 우리의 위대한 대의에 없어서는 안 될 것이 될 것입니다. 우리의 숙련된 마법사들이 그 잠재력을 완전히 활용하는 데는 시간이 걸리겠지만, 그 보상은 무궁무진할 것입니다.$B$B한때 길네아의 기반을 형성했던 바로 그 힘들이 이제 나약한 인간들에게 경멸과 멸시를 받는다는 아이러니를 목격하는 것이 매우 흥미롭습니다. 시간이 흐르면서 그들의 신생 종족에게서 지혜가 퇴색한 것 같군요.$B$B하지만 그들에 대한 이야기는 이쯤 하고. 저는 당신의 공헌을 잊지 않았습니다. 우리의 꼼꼼한 약제사들이 당신의 노고에 대한 보상을 준비했습니다. 다양한 상품 중에서 마음에 드는 것을 고르시고, 마땅히 받을 자격이 있는 상품을 받아가세요."}}
rows[40998]={title={{23,1730974750},"휘갈겨 쓴 요리 메모"},description={{229,2097781601},"레시피로 보이는 반쯤 찢어진 조각을 발견했습니다. 글씨가 알아보기 힘들 정도로 조잡하게 쓰여 있습니다. 이 조각에 대해 더 잘 아는 사람을 찾아보는 것이 좋겠습니다."},objectives={{74,1846412041},"휘갈겨 쓴 요리 메모에 대해 아는 사람을 찾아보세요."},progress={{15,159386007},"도와드릴까요?"},completion={{183,892610675},"요리 노트. 음, 솔직히 말해서 저는 카라잔에서 꽤 많은 식사를 해봤습니다. 젊은 시절에는 요리를 배우는 데 많은 시간을 쏟기도 했죠.$B$B당신은 정말 제대로 찾아오셨습니다."}}
rows[40999]={title={{14,477036793},"분실물 센터"},description={{462,315158037},"더 알고 싶으시다면, 이 양피지에서 얻은 지식을 전해드리기 전에 몇 가지 부탁을 드려야겠습니다. 오래전 카라잔에 처음 도착했을 때, 저는 최고급 금으로 만든 새겨진 팔찌를 차고 있었습니다. 그것은 제 신분을 상징하는 것이었는데, 이 복도를 배회하며 떠돌아다니는 동안 사라져 버렸습니다. 제$B$B 생각에는 이 아래층 어딘가에 팔찌를 두고 온 것 같습니다. 부디 찾아주시면 정말 감사하겠습니다."},objectives={{66,1690208294},"카라잔에서 로틀렌 공작을 위한 새겨진 금팔찌를 되찾으세요."},progress={{59,1290229443},"제 팔찌를 찾으셨나요? 아내가 선물해 준 거예요."},completion={{83,1039809121},"아, 정말 훌륭한 작품이군요... 얼마나 호화로운 작품인지 잊고 있었어요."}}
rows[41000]={title={{21,1596815259},"로틀렌 가문 브로치"},description={{500,1919511654},"제게 새겨진 금팔찌를 되찾아주셔서 감사합니다. 하지만 저는 제 마음속에 더 소중한 것을 원합니다. 오래전 가족을 뒤로하고 이곳에 왔지만, 영원히 갇혀버린 기분입니다. 과거의 추억이 담긴 $B$B물건, 가장 아름다운 기억을 떠올릴 수 있는 무언가를 갖고 싶습니다. 그것을 통해 마음의 평화를 찾을 수 있기를 $B$B바랍니다. 저는 한때 로데론 땅의 스트라솔름 출신이었고, 저희 가문의 저택은 무역 지구 안에 있습니다. 로슬렌 가문의 집을 찾아 가문의 브로치를 되찾아주세요."},objectives={{79,1185976014},"카라잔에서 로틀렌 공작을 위해 스트라솔름에서 로틀렌 가문의 브로치를 되찾아오세요."},progress={{45,1783706162},"로슬렌 가문의 브로치가 회수되었습니까?"},completion={{224,1108100026},"스트라솔름이 파괴되었다고? 우리 집이 불타버렸다고?$B$B<로슬렌 공작은 믿을 수 없다는 듯 한숨을 내쉬었다.>$B$B이런 소식은 제 마음을 아프게 합니다. 이것을 되찾아 주셔서 진심으로 감사드립니다. 이것은 정말 우리 가족의 마지막 유품입니다."}}
rows[41001]={title={{17,2084839773},"비밀 레시피"},description={{319,137151844},"저는 시간을 내어 양피지를 살펴보았고, 그것이 '초콜릿 생선' 요리법의 미완성본이라는 것을 알게 되었습니다. 메디브가 가장 좋아했던 요리 중 하나이며, 완성하는 데 상당한 기술이 필요합니다. 이 레시피의 비법을 알고 싶으시다면, 카라잔에 있는 '요리사'에게 문의해 보시기 바랍니다."},objectives={{34,23776261},"카라잔에 있는 '요리사'와 이야기해 보세요."},progress={{4,273767400},"예?"},completion={{26,806315438},"르 피쉬 오 쇼콜라, 그렇죠?"}}
rows[41002]={title={{23,403266814},"카라잔의 문지기"},description={{390,51019652},"네, 이 조리법을 고안한 건 바로 저입니다. 카라잔에서 일하던 요리사들 중 극소수에게만 이 조리법을 가르쳐 주었죠. 널리 알려지지는 않았지만 메디브는 이 $B$B조리법을 무척 좋아했습니다. 제가 이런 정보를 함부로 알려드릴 수는 없지만, 문지기 몽티그의 '카라잔의 명령서'를 구할 수 있다면 조리법을 쉽게 알려드릴 수 있습니다. 몽티그에게 문의해서 한 부 받아오세요."},objectives={{40,2110740954},"카라잔의 문지기 몽티그에게 말을 걸어보세요."},progress={{4,273767400},"예?"},completion={{59,1992446898},"카라잔에 오신 것을 환영합니다. 무엇을 도와드릴까요?"}}
rows[41003]={title={{18,735334556},"카라잔의 책임"},description={{483,1885035084},"카라잔의 충전물이 필요하신가요? 글쎄요, 일반인이나 탑의 손님에게 그냥 주어지는 건 아닙니다. 메디브에게 충분한 기부를 하고 그가 제공하는 마법 서비스에 대한 대가를 지불해야만 얻을 수 있는 것이죠. 충전물을 원하신다면, 저희 주인님이 돌아오실 때를 대비해 기부금을 대신 받아두겠습니다.$B$B 현재 필요한 건 죽음의 정수 10개, 생명의 정수 10개, 그리고 금화 25개입니다. 메디브를 대신하여 이 기부금을 가져오시면, 정당한 보상을 받으실 수 있도록 해드리겠습니다."},objectives={{91,83648326},"카라잔의 문지기 몽티크에게 죽음의 정수 10개, 생명의 정수 10개, 금화 25개를 가져다주세요."},progress={{64,148776310},"탑 건립에 기증하실 자재는 모두 확보되었습니까?"},completion={{184,1802897238},"여러분의 기여는 제 수첩에 기록되어 있습니다. 지속적인 지원에 감사드립니다. 약속드린 대로 여러분을 대신하여 카라잔 기도문을 준비했습니다."}}
rows[41004]={title={{20,186772326},"르 피쉬 오 쇼콜라"},description={{133,1431921762},"약속드린 대로, 여기 카라잔의 책임자가 있습니다. $B$B여러분의 성원에 감사드립니다. 카라잔에서 편안하게 지내시기 바랍니다."},objectives={{53,1679756085},"카라잔의 책임자를 카라잔에 있는 요리사에게 데려가십시오."},progress={{41,259429462},"돌아왔군요, 뭔가 좋은 일이 있었나요?"},completion={{201,544007125},"좋습니다. 이 위임장은 제가 요청하신 정보를 제공할 권한을 부여합니다. 레시피를 준비하고 조리법도 적어 두었습니다. 이 귀한 진미를 잘 활용하시길 바랍니다."}}
rows[41005]={title={{20,308083732},"노르다나르 허브차"},progress={{253,743437315},"자, 당신은 작은 꿈 조각을 가지고 있나요?"},completion={{69,2087817669},"이 차는 마음을 진정시키는 효과가 있으니 몇 모금 마시면서 편안하게 휴식을 취해보세요."}}
rows[41006]={title={{25,1308813665},"환상: 녹색 용족"},description={{348,1692481667},"나, 슬럼브나즈는 기만 마법의 달인이다.$B$B 내 용의 힘은 나와 내 주변 사람들의 모습을 변형시키고, 아제로스의 시각적 현실 자체를 왜곡할 수 있도록 조율될 수 있다. 만약 당신이 이러한 마법을 맛보고 싶다면, 내 동족을 도운 당신의 노력에 대한 $B$B보상을 주겠다. 밝은 꿈의 조각 25개를 가져오면 이 환영을 선사하겠다."},objectives={{65,980738754},"하이잘의 노르다나르에서 슬럼브나즈를 위해 밝은 꿈 조각 25개를 모으세요."},progress={{37,894527800},"마법의 조각들을 모두 얻으셨나요?"},completion={{108,1123612658},"용의 마법을 맛보는 것은 그것에 익숙하지 않은 자에게는 강렬한 경험이 될 수 있습니다. 이 환영을 사용할 때는 조심하십시오."}}
rows[41007]={title={{33,354609601},"사라져가는 꿈의 조각들을 모으다"},progress={{313,477001407},"희미해져 가는 조각을 찾는 것은 꽤 어려울 수 있지만, 희망을 잃지 마세요."},completion={{87,503735247},"약속드린 대로, 이 작은 꿈 조각들에는 강력한 마법이 담겨 있으니 현명하게 사용하세요."}}
rows[41008]={title={{15,1298252828},"놀드랏실 수사슴"},description={{352,345878003},"노르다나르의 드루이드들은 노르드라실의 위풍당당한 사슴을 가장 숭배합니다.$B$B 우리 대의를 위해 가장 큰 공을 세운 당신에게 이 멋진 탈것을 선물할 수 있습니다. 이 보상은 오직 남다른 헌신을 보여준 자에게만 주어지는 것입니다. 밝은 꿈의 조각 500개를 가져오시면 당신의 헌신에 걸맞은 탈것을 보상으로 드리겠습니다."},objectives={{75,877305551},"하이잘의 노르다나르에서 에반딜 나이트윈드를 위해 밝은 꿈 조각 500개를 모으세요."},progress={{30,1436192723},"그래서, 선택하셨나요?"},completion={{174,2079810523},"당신은 하이잘에게 당신의 능력을 증명했으니, 그에 걸맞은 큰 보상이 기다리고 있습니다. 노르드라실의 사슴을 가장 충성스러운 반려자처럼 대하십시오. 그러면 사슴은 당신에게 자연의 강인함을 보여줄 것입니다."}}
rows[41009]={title={{26,96516542},"꿈 표범의 상형문자"},description={{555,369434393},"하이잘은 에메랄드의 꿈의 힘이 가장 강하게 느껴지는 곳입니다. 최근 들어 그 힘을 끌어오는 흐름에 이상이 생겼고, 예전처럼 하이잘을 찾는 순례자도 많지 않습니다.$B$B저는 달숲의 정령들을 대신해 하이잘을 도울 유능한 드루이드를 찾으러 왔습니다. 그대의 노력을 증명하고 싶다면 달숲의 정령들이 그 고귀한 행동에 보답할 것입니다. 달숲의 위대한 고양이 정령을 찾아 밝은 꿈의 조각 20개와 비전 정수 8개를 가져가십시오."},objectives={{90,1014070169},"달빛숲에 있는 위대한 고양이 정령에게 밝은 꿈 조각 20개와 ​​신비의 정수 8개를 모으세요."},progress={{105,1774306667},"<거대한 고양이 정령의 날카로운 눈빛이 위압적이다.>$B$B두려워하지 마세요, 우리는 같은 편입니다."},completion={{326,1266494768},"단타르 오크맨틀은 달의 숲의 충실한 친구이며, 당신을 우리에게 인도하는 임무를 맡은 자입니다. 에메랄드 드림 안에서 무언가가 꿈틀거리고 있으며, 이제 우리는 힘을 합쳐 그것을 물리쳐야 합니다.$B$B당신은 훌륭하게 임무를 수행해 왔습니다. 앞으로도 계속 그렇게 한다면, 마침내 평화를 찾을 수 있을지도 모릅니다. 이 문양을 받아들이고, 나의 힘이 당신을 통해 흐르도록 하십시오."}}
rows[41010]={title={{25,149056026},"에메랄드 곰의 상형문자"},description={{556,727125887},"하이잘은 에메랄드 드림의 힘이 가장 강하게 느껴지는 곳입니다. 최근 들어 이러한 에너지를 전달하는 데 차질이 생겼습니다. 예전처럼 하이잘로 순례를 오는 사람도 많지 않습니다.$B$B I는 문글레이드의 정령들로부터 하이잘을 도울 유능한 드루이드를 요청하는 사절로 파견되었습니다. 당신의 노력을 증명하고 싶다면, 문글레이드의 정령들이 그 고귀한 행동에 보상해 줄 것입니다. 문글레이드에서 위대한 곰 정령을 찾아 밝은 꿈 조각 20개와 ​​마법 정수 8개를 가져오십시오."},objectives={{91,1695501602},"달빛숲에 있는 큰곰 정령에게 밝은 꿈 조각 20개와 ​​신비의 정수 8개를 모으세요."},progress={{146,1039887321},"단타르 오크맨틀은 노르다나르의 드루이드들을 내게 인도하는 임무를 맡았습니다. 당신도 그중 한 명임을 느낄 수 있습니다. 하이잘에서 당신이 이룬 업적을 증명할 만한 것이 있습니까?"},completion={{415,612884967},"당신은 하이잘의 정상까지 여정을 완수했고, 그 여정을 성공적으로 마쳤습니다.$B$B그 길은 위험으로 가득 차 있었고, 당신의 용기는 칭찬받아 마땅합니다. 에메랄드 드림에는 어둠의 기운이 감돌고 있으며, 저조차도 그것이 제 의지를 조종하고 있음을 느낄 수 있습니다. 우리는 모두 하이잘을 지키기 위해 힘을 합치고 있으며, 그에 대한 보답으로 당신의 헌신에 보답하고자 합니다.$B$B이 문양을 받아들이고, 에메랄드 드림에 충성하는 자로 변모하십시오."}}
rows[41011]={title={{19,135841048},"상단 바인딩 I"},description={{611,1340075119},"아주 오래전, 저는 아제로스 전역의 지맥에서 엄청난 힘을 끌어내는 강력한 유물을 우연히 접하게 되었습니다. 저는 이 유물을 연구하려 했지만, 세월이 흐르면서 그 힘은 서서히 사라져 갔습니다. 제가 할 수 있었던 연구는 다소 실망스러웠고, 이제 제게 남은 것은 그저 아름다운 문진일 뿐입니다.이 $B$B오래된 유물을 원래의 힘으로 되돌리는 데 도움을 주신다면, 아마 저보다 더 좋은 결과를 얻으실 수 있을지도 모릅니다. 제가 가장 먼저 필요한 것은 강력한 용족 마법을 지닌 용족의 돌입니다. 검은바위 첨탑의 용족들이 그런 아이템을 가지고 있다는 이야기를 들었습니다."},objectives={{98,1071927481},"길네아의 파르나부스를 위해 검은바위 첨탑 안의 검은 용족에게서 용족 돌진을 모으세요."},progress={{90,1151620256},"오랜만에 이렇게 신나는 기분을 느껴보네요. 드래곤킨 차지 스킬을 되찾으셨나요?"},completion={{87,419945790},"이 작은 토큰에 담긴 엄청난 힘, 용의 마법은 정말 매혹적입니다!"}}
rows[41012]={title={{20,615308217},"상단 바인딩 II"},description={{577,511906223},"저는 드래곤킨 차지를 사용하여 유물을 재충전하려고 시도했지만, 잠재된 힘을 활성화하는 데 실패했습니다. 더 적극적인 지맥 에너지원이 필요할 것 같습니다.$B$B 이 의식을 시작하기 전에 몇 가지 재료가 필요합니다. 먼저, 다음 재료들을 모아주세요. 구하기는 비교적 쉬울 겁니다. 불의 정수 5개와 흙의 조각 1개면 시작할 수 있을 것입니다. 이 재료들을 찾는 것이 까다로울 수도 있지만, 흙의 조각은 실리투스에서 볼 수 있는 흙 정령에게서 얻을 수 있습니다. 그곳에서부터 시작해 보세요."},objectives={{74,919978975},"길네아스의 파르나보스를 위해 불의 정수 5개와 흙의 조각 1개를 모으세요."},progress={{32,1472229036},"필요한 요소들을 모두 확보했습니까?"},completion={{44,701904049},"이제 막 시작했을 뿐이니 너무 들뜨지 마세요."}}
rows[41013]={title={{21,1148481593},"상단 바인딩 III"},description={{710,909076669},"정령의 불과 대지의 조각을 이용하면 유물을 접지하여 진정한 에너지화를 준비할 수 있습니다. 이 결속에는 유물이 한때 지녔던 힘에 필적할 만한 극도의 마법 에너지 충전이 필요합니다. 아제로스에서 이처럼 순수한 마법 에너지를 모으는 $B$B것은 매우 드뭅니다. 저는 칼림도르 대륙에서 극심한 마법 에너지 방출을 감지한 지 꽤 되었습니다. 제가 들은 소문에 따르면, 한때 엘프의 도시였지만 지금은 다이어 몰이라고 불리는 곳에서 엄청난$B$B 에너지가 방출되고 있는 것 같습니다. 저는 그곳에 나타난 마법 원소들에서 얻을 수 있는 초강력 마법 공명이 필요합니다. 그것을 모아주시면, 예전의 유물을 되찾아 드리겠습니다."},objectives={{104,1055376451},"길니아스의 다이어 몰에 있는 마법 정령들에게서 초강력 마법 공명을 모아 파르나부스에게 전달하세요."},progress={{69,2087885722},"다이어 몰 주변에서 뿜어져 나오는 힘이 얼마나 엄청날지 상상조차 할 수 없습니다."},completion={{66,558705575},"<파르나바는 눈앞의 힘에 충격을 받은 듯 보인다.>$B$B그래서, 그것은 사실이었다."}}
rows[41014]={title={{20,615308230},"상단 바인딩 IV"},description={"You have done well in acquiring these materials $c. As I have promised, I will perform the ritual to recharge this relic as it once was. Speak to me when I am finished.","이 재료들을 구해낸 것은 훌륭한 일입니다, .$c 제가 약속드린 대로 이 유물을 예전의 모습으로 되돌리는 의식을 거행하겠습니다. 의식이 끝나면 말씀해 주십시오."},objectives={{48,25197641},"의식이 완료되면 파르나보스와 이야기하십시오."},progress={{4,273767400},"예?"},completion={"It is done, the ritual is complete. This binding once came from near the tower of Karazhan. I have no doubt it once served a more grand cause, or was apart of an object with considerable power.$B$BI have no purpose for this binding any longer, and I offer it to you for whatever purpose you see fit. I wish you the best of luck in your cause $c.","다 끝났습니다. 의식이 완료되었습니다. 이 묶음은 한때 카라잔 탑 근처에서 나왔습니다. 틀림없이 더 큰 목적을 위해 쓰였거나 상당한 힘을 지닌 물건의 일부였을 것입니다.$B$B저는 더 이상 이 묶음을 사용할 필요가 없으므로, 당신이 원하는 용도로 사용하시기 바랍니다. 당신의 뜻에 행운을 빕니다.$c"}}
rows[41015]={title={{22,1443888974},"크산타르의 속박"},description={{699,1262117278},"몇 년 전, 희귀하고 강력한 물건이 이 교회 안에 보관되어 있었습니다. 그 물건이 사라진 이후로 저는 저주를 받아 이곳에 계속 머물고 있습니다. 만약 당신이 그 물건을 되찾아 카라잔으로 돌려준다면, 저는 더할 나위 없이 $B$B감사할 것입니다. 그 결속은 도난당하기 전에 이미 찢어졌고, 두 조각은 이제 각각 다른 주인에게 있습니다. 첫 번째 조각은 소속이 없는 은둔 마법사가 가져갔는데, 그의 말투는 분명 북쪽 출신인 듯했습니다. $B$B결속의 두 번째 조각은 붉은 천을 두르고 빛의 상징을 지닌, 신앙심 깊고 경계심이 강한 남자가 가져갔습니다. 그의 광기는 거의 미친 소리 같았습니다! 결속의 $B$B위쪽과 아래쪽 조각을 모두 모아주시면, 제가 그것을 하나로 만들 수 있습니다."},objectives={{134,1307628329},"카라잔 외곽의 작은 교회에서 의로운 한바르를 위해 크산타르의 윗단추와 아랫단추를 모으십시오."},progress={{93,1550065636},"결합이 복원되면 나는 평화를 얻을 것이다.$B$B두 조각 모두를 되찾는 것은 당신에게 달려 있다."},completion={{391,918931223},"윗부분과 아랫부분 모두. 이렇게 함께 있을 줄은 상상도 못 했습니다.$B$B<한바르는 잠시 마음을 가다듬는다.>$B$B묶인 것들이 다시 하나로 합쳐졌습니다. 저는 이 물건들을 영원히 지켜야 하는 저주를 받았지만, 당신이라면 제 임무를 더 잘 수행할 수 있을 것 같습니다.$B$B이 묶인 것을 잘 지켜보고 악의 손에 넘어가지 않도록 하십시오."}}
rows[41016]={title={{14,765157486},"야생의 형상자"},description={{484,895663606},"야생의 형상을 만드는 자, 하이잘의 드루이드들이 그에게 붙여준 칭호. 지금은 알진이라고 불린다. 한때 그들이 지녔던 모습과는 완전히 다른, 뒤틀리고 타락한 존재. 타락하기 전의 모든 신념에 반하는 존재가 되었다.$B$B '알진'은 한때 나의 친구였지만, 이제는 페랄라스 전체를 타락시키려는 욕망에 사로잡혀 있다. 나는 그의 사악한 계획을 영원히 끝내는 것이 내 의무라고 생각한다. 그는 $B$B사티로스 동족과 함께 다이어 몰 깊숙한 곳에 숨어 있다. 그를 처치하고 그의 머리를 가져오라. 그래야만 나는 안식을 찾을 수 있을 것이다."},objectives={{87,1273117741},"하이잘의 노르다나르에게 대드루이드 드림윈드를 위해 야생변형술사 알진의 머리를 가져다주세요."},progress={{44,2044696933},"저 흉악한 짐승은 정의의 심판을 받았습니까?"},completion={{276,76923226},"저는 그런 배신을 상상조차 할 수 없었습니다. 너무나 큰 충격이어서 그 기억을 떠올리고 싶지도 않습니다.$B$B이 배신자를 처형해 주셔서 감사합니다. 당신의 개입이 없었다면 알진이 무슨 짓을 저질렀을지 두려웠습니다. 부디 이것을 제 깊은 감사의 표시로 받아주십시오."}}
rows[41017]={title={{21,68153471},"바일머스크 침투"},description={{425,2094451637},"노르드라실 숲은 오랜 세월 동안 평화로운 곳이었지만, 벌써부터 군단의 하수인들이 독을 퍼뜨리기 시작했습니다. 가장 역겨운 배신자인 사티로스들이 우리 국경을 노리고 있습니다. 그들은 스스로를$B$B '사악한 사향'이라 부르는데, 이는 그들의 불길한 혈통에 걸맞은 이름입니다. 나는 그들을 하이잘에서 몰아내라고 명령한다. 그들을 사냥하여 발굽을 증거로 가져오너라. 그렇게 한다면 보상을 주겠다."},objectives={{77,1977713246},"하이잘의 노르다나르에 있는 대드루이드 드림윈드에게 바칠 사악한 사향발굽 30개를 모으세요."},progress={{96,1794804791},"사티로스는 한때 우리와 매우 비슷했지만, 이제는 그림자 속에서 우리를 배회하며 우리의 노력을 방해합니다."},completion={{248,692036956},"훌륭히 해냈습니다. 당신의 공적은 결코 잊히지 않을 것입니다. 쓰러진 사티로스 한 명당, 진정한 최후의 심판의 날에는 그 수가 하나씩 줄어들 것입니다.$B$B하이잘을 위한 이 전투는 당신의 영웅적인 행동에 달려 있습니다. 감사의 표시로 이 밝은 꿈의 조각을 받으십시오."}}
rows[41018]={title={{22,458235603},"타락한 꿈의 조각들"},progress={{419,1112537649},"이 타락한 파편들을 찾으셨나요?"},completion={{217,1668418201},"이 파편들에는 어둠의 마법이 깊숙이 깃들어 있었소. 너무 늦기 전에 당신이 이것들을 회수해낸 것은 정말 다행이오.$B$B파괴 직전에서 이것들을 구해낸 것에 대한 감사의 표시로 이것을 받아주시오. 혹시 더 발견하면 내게 가져다주시오."}}
rows[41019]={title={{28,920148984},"셰이드플레어 부족 팔찌"},progress={{453,1052599693},"우리 적들의 의지를 의심하지 마십시오. 그들은 우리를 파멸시키기 위해 뭉쳤습니다."},completion={{222,1533429890},"훌륭히 해냈습니다. 당신의 행동 덕분에 노르다나르의 안전이 보장됩니다. 노르드라실 숲은 미쳐버린 트롤들의 사악한 변덕에 위협받지 않고 안전한 피난처로 유지되어야 합니다.$B$B감사의 표시로 이 작은 꿈의 조각을 받아주십시오."}}
rows[41020]={title={{13,1959482180},"잔바락 경"},description={{665,1088513335},"제3차 전쟁 동안, 불타는 군단은 우리 군대에 맞서 자신들의 힘을 시험했고, 노르드라실 앞에 집결한 우리 군대에 패배했습니다. 그들이 다시 돌아와 사악한 계획을 꾸미고 있습니다. 이번에는 우리를$B$B 지켜줄 강력한 군대도, 우리를 이끌어줄 말퓨리온의 지혜도 없습니다. 하이잘의 방어는 우리, 남은 소수의 용감한 자들에게 달려 있으며, 우리는 악에 맞서 경계해야 $B$B합니다. 나는 당신에게 하이잘에 있는 불타는 군단의 지도자 잔바락 군주에게 도전해 달라고 부탁합니다. 그는 서쪽 노르드라실 숲 바로 외곽에 있는 블리크할로우 분화구에 강력한 악마 군대를 집결시키기 시작했습니다. 그의 심장을 가져와 우리의 걱정을 끝내주십시오."},objectives={{65,1603978824},"잔바락의 심장을 노르다나르에 있는 대드루이드 드림윈드에게 가져다 주세요."},progress={{154,229922149},"불타는 군단의 힘은 결코 얕볼 수 없습니다. 잔바락의 강력함에 도전할 모험가나 용병들을 직접 데려오십시오."},completion={{342,827286952},"잔바락의 심장에서 뿜어져 나오는 사악한 기운이 느껴집니다. 하이잘을 지켜낸 당신의 노고는 실로 엄청났습니다. 잔바락이 쓰러졌으니, 악마들이 새로운 지도자를 중심으로 뭉치기까지는 상당한 시간이 걸릴 것입니다.$B$B당신은 우리에게 평화를 가져다주었습니다. 그 평화가 얼마나 오래갈지는 모르지만 말입니다. 이러한 업적은 더할 나위 없이 신성한 보상을 받을 만합니다."}}
rows[41021]={title={{16,748087498},"야생동물 도태"},progress={{573,494549673},"진전이 있었습니까?"},completion={{238,218644671},"하이잘의 자연을 개선하기 위해서는 이처럼 혹독한 임무가 필요합니다. 우리가 행동하지 않으면 하이잘의 동물들은 공격적이고 적대적인 짐승으로 전락하거나, 어쩌면 군단의 노예가 될지도 모릅니다.$B$B감사의 표시로 이 꿈의 조각을 받아주십시오."}}
rows[41022]={title={{27,1859897988},"악몽의 발현"},description={{352,435383825},"하이잘 곳곳에서 에메랄드 드림에서 벌어지고 있는 타락의 징후들이 나타나고 있습니다. 녹색 진흙이 땅을 오염시키고 우리의 삶을 위협하고 있습니다. 우리는 불타는 군단의 악마들을 상대하듯 이 위험에 맞서 싸워야 합니다. I는 당신의 $B$B공적을 증명하기 위해 마법에 걸린 진흙 40개를 모으라고 요구했습니다. 이 임무를 완수하면 충분한 보상을 드리겠습니다."},objectives={{81,1217568280},"하이잘의 노르다나르에서 오물에게서 마법에 걸린 진흙 40개를 모아 파라나 잎칼날을 제작하세요."},progress={{55,327530029},"조심하세요, 이 괴물들은 생명을 조금도 소중히 여기지 않습니다."},completion={{142,656122834},"당신은 훌륭한 일을 해냈습니다. 당신의 노력 덕분에 이 땅은 더욱 안전해졌습니다. 하지만 이 생물들이 어디에서 왔는지에 대해서는 여전히 많은 의문점이 남습니다."}}
rows[41023]={title={{19,1372573838},"글란타스 샘플"},description={{304,1148382828},"당신이 모아준 마법의 진흙 샘플을 준비했습니다. 이 샘플을 노르다나르에 있는 고대의 글란타스에게 가져다 주십시오. 제가 마지막으로 $B$B들은 바로는 글란타스와 한 드루이드가 비슷한 현상의 근본 원인을 찾기 위해 협력하고 있다고 합니다. 이 진흙 샘플이 그들에게 도움이 될 수 있을지도 모릅니다."},objectives={{61,1799163408},"슬러지 샘플을 노르다나르에 있는 고대의 글란타스에게 가져가세요."},progress={{20,1292366299},"네, 도와드릴까요?"},completion={{203,1193657596},"파라나 리프블레이드가 보낸 건가? 훌륭한 전사로군. 그녀는 나만큼이나 이 땅에 헌신적이야.$B$B<글란타스는 샘플을 받아들고 꼼꼼히 살펴본다.>$B$B마법의 기운으로 오염된 역겨운 물질로군."}}
rows[41024]={title={{23,825207515},"현상 연구"},description={{417,1641411181},"카노스 클리어우드라는 드루이드는 몇 년 전 아즈샤라에서 나타나는 괴물들에 대한 조사를 맡았습니다. 하지만 그의 연구는 한때 인간의 영역이었던 동부 역병지대로 그를 이끌었습니다. 제가 듣기로는 $B$B그가 현재 그곳에서 진흙 같은 괴물들과의 연관성을 찾기 위해 조사 중이라고 합니다. 그에게 이 $B$B샘플을 가져다주면, 하이잘에서 벌어지고 있는 이 새로운 현상의 원인을 밝혀낼 수 있을지도 모릅니다."},objectives={{66,1440092879},"슬러지 샘플을 동부 역병지대의 카노스 클리어우드에게 가져가세요."},progress={{17,68824445},"도와드릴까요?"},completion={{214,77426228},"글란타스가 당신을 보내서 저를 찾으라고 했습니까?$B$B<카노스는 잠시 멈춰서 진흙을 살펴본다.>$B$B이 진흙에는 어떤 마법적인 속성이 남아 있는 것 같지만, 글란타스는 이미 이 정보를 알아냈겠죠."}}
rows[41025]={title={{26,1561384972},"발현 양상의 유사점"},description={{571,286964973},"아즈샤라에서의 연구는 흥미로운 정보를 제공했지만, 동부 역병지대에서도 추가 연구가 필요합니다. 저는 마법과 오즈(수액괴물) 사이의 연관성을 찾으려 노력해 왔지만, 아직까지는 별다른 성과를 거두지 못했습니다. 이 괴물들이 이곳에 오랫동안 서식해 왔기 때문에 마법적인 힘이 약해졌다는 결론에 도달했습니다. 저는 당신에게 마법의 $B$B기운이 미량이라도 담긴 '마법이 주입된 오물'을 찾아달라고 부탁합니다. 이 괴물은 역병지대의 빛의 희망 예배당과 코린의 교차로 근처에서 발견할 수 있습니다."},objectives={{101,1572648003},"메렐다르 호수 근처의 카노스 클리어우드를 위해 동부 역병지대의 점액 괴물에게서 마법이 부여된 진흙을 모으세요."},progress={{108,177928981},"저는 마법 같은 연결고리를 찾으려고 꽤 오랫동안 노력해 왔습니다. 어쩌면 당신은 저보다 더 운이 좋을지도 모르겠네요."},completion={{74,674008407},"마법의 흔적.$B$B<카노스에게서 한숨이 새어 나왔다.>$B$B나는 스스로를 의심하기 시작했다."}}
rows[41026]={title={{19,1189363833},"드림윈드에 보고"},description={{519,1458103001},"점액질 생물들은 강렬하고 어두운 마법 에너지의 급증과 연관되어 있는 것으로 보입니다. 엄청난 마법 에너지 자체의 후유증으로 남아있는 것이죠. 어쩌면 자연적인 현상일 수도 있고, 훨씬 더 심오한 무언가가 있을지도 모릅니다.$B$B 솔직히 제 증거가 정확한지, 제가 제대로 된 곳을 조사하고 있는 건지는 확신할 수 없습니다. 하지만 어쨌든 하이잘의 대드루이드 드림윈드에게 보고서를 제출했습니다. 제가 발견한 모든 것을 설명해 드릴 것입니다. 도움을 $B$B주셔서 정말 감사합니다. 당신이 없었다면 저는 아직도 점액질 생물들을 파헤치고 있었을 겁니다."},objectives={{55,1236852987},"카노스의 보고서를 하이잘의 노르다나르에 있는 드림윈드로 가져오세요."},progress={{15,159386007},"도와드릴까요?"},completion={{411,1192018965},"카노스는 정말 놀라운 연구에 매진했군요. 아직 결론은 나지 않았지만, 그의 연구 방향이 옳다고 확신합니다. 마법적인 피드백, 혹은 잔여물이라는 이론은 분명 흥미롭고, 더 깊이 연구해 볼 필요가 있습니다.$B$B이 문제에 대한 당신의 도움은 제가 깊은 존경을 표하는 글란타스 신께서도 강조하셨습니다. 하이잘에서 드리는 감사의 표시로 이것을 받아주십시오."}}
rows[41027]={title={{15,1996977633},"도난당한 맹렬함"},description={{616,1012117689},"고양이 정령이 점점 호기심 어린 눈으로 당신을 바라봅니다.$B$B 당신에게서 목적의식을 느낍니다. 당신의 본질에서 뿜어져 나오는 강인함이 느껴집니다. 당신에게 임무를 맡기겠습니다. 당신의 교활함과$B$B 회복력을 시험할 임무입니다. 지옥숲 깊숙한 곳에 그림자 요새라는 곳이 있습니다. 한때 드루이드들의 무덤 소굴이었던 이곳은 이제 불타는 군단에게 점령당했습니다. 이 요새에는 제게 매우 중요한 유물, 로레쉬의 송곳니가 있습니다. 그림자 요새 깊숙이 스며든 타락이 로레쉬의 영혼을 광기로 몰아넣었고, 저는 그에게 가해진 고통을 끝내고자 합니다. 당신의 $B$B맹렬함을 ​​보여주고, 이 유물을 가져오십시오."},objectives={{94,1878619641},"달빛숲의 위대한 고양이 정령을 위해 그림자 요새 깊숙한 곳에서 로레쉬의 송곳니를 되찾아 오세요."},progress={"Fabricate a plan, and put it in motion. Use cunning and skill to achieve your goals $c.","계획을 세우고 실행에 옮기세요. 교활함과 기술을 활용하여 목표를 달성하세요.$c."},completion={{182,325239591},"로레쉬의 송곳니가 내게 돌아왔지만, 예상했던 것보다 훨씬 더 끔찍하군. 어둠의 마법이 이미 유물 깊숙이 스며들어 있어. 로레쉬의 영혼이 미쳐버린 것도 당연한 일이군."}}
rows[41028]={title={{18,628813586},"로레쉬의 송곳니"},description={{435,234329646},"타락이 한때 로레쉬의 송곳니에 담겨 있던 모든 정수를 완전히 잠식해 버렸습니다. 그 안에 아직 남아있는 영혼을 보존하기 위해서는 제 의식을 시작하기 위한 많은 재료를 모아야 합니다. 하이잘에서 $B$B찾을 수 있는 밝은 꿈의 조각 10개, 생명의 정수 10개, 그리고 거대한 찬란한 조각 1개를 가져오십시오. 마지막 재료들은 찾기가 다소 어려울 수 있습니다. 이 $B$B모든 재료를 모으면 저에게 돌아오십시오."},objectives={{116,1112734148},"달빛숲에 있는 위대한 고양이 정령에게 밝은 꿈 조각 10개, 생명의 정수 10개, 그리고 커다란 찬란한 조각 1개를 모으세요."},progress={{45,1646558599},"<위대한 고양이 정령이 강렬한 눈빛으로 응시한다.>"},completion={{107,365604629},"당신은 수완이 뛰어나군요.$B$B로레쉬의 영혼을 정화하기 전에 마지막으로 해야 할 일이 하나 있습니다."}}
rows[41029]={title={{20,499449056},"로레쉬의 정신"},description={{307,2085377036},"로레쉬의 어둡고 뒤틀린 그림자가 그의 송곳니에 깃든 강력한 마법으로 형체를 드러냈다. 그의 영혼을 정화하려면 이 어둠의 존재를 파괴해야 한다. 네 능력을 증명하고 이 그림자를 처치하라. 텔아빔 섬에서$B$B 추적 장치를 사용해라. 그곳에서 네 사냥감을 찾을 수 있을 것이다."},objectives={{74,1926196690},"로레쉬의 정령을 처치하고 달의 숲에 있는 위대한 고양이 정령에게 돌아가십시오."},progress={{94,1954396435},"경계를 늦추지 말고, 단호하게 접근하십시오. 어둠의 마법에 굴복하지 마십시오."},completion={{119,422199537},"로레쉬의 영혼이 자유에 한 걸음 더 가까워졌습니다. 그를 가두었던 사악한 마법은 당신의 속도와 기술에 비하면 아무것도 아니었습니다."}}
rows[41030]={title={{13,1718469042},"로레쉬 구하기"},description={{238,1352172985},"저를 도와주신 노력은 결코 헛되지 않을 것입니다. 하지만 먼저 제게 가장 중요한 일을 처리해야 합니다. 로레쉬의 영혼을 정화하고 어둠의 마법으로 인한 고통에서 그를 해방시켜야 합니다.$B$B뒤로 물러서서 제가 일을 마치면 말씀하십시오."},objectives={{64,1856222715},"위대한 고양이 정령이 로레쉬를 고통에서 해방시켜 줄 때까지 기다리세요."},progress={{4,273767400},"예?"},completion={{200,1851089417},"완료되었습니다. 로레쉬는 어둠의 마법에서 해방되었습니다. 당신은 요청받은 일을 성공적으로 완수했으니, 그에 대한 보상을 받겠습니다.$B$B이 맹렬함의 선물을 받아 모든 자연의 더 큰 선을 위해 사용하십시오."}}
rows[41031]={title={{20,176811648},"맹렬함의 선물"},description={{322,1151309264},"저는 영원한 고통에서 해방되었고, 이제 제 영혼은 달빛숲에서 평화롭게 쉴 수 있게 되었습니다. 감사의$B$B 표시로, 당신에게 아주 강력한 마법을 선물할 수 있습니다. 이 선물은 우리 종족 사이에서 신성한 물건으로, 가장 신뢰하는 자에게만 주어집니다. 밝은 꿈 조각 세 개를 가져오시면, 당신도 이 축복을 받을 수 있도록 해 드리겠습니다."},objectives={{67,1840420863},"달빛숲에서 로레쉬의 정령을 위해 밝은 꿈 조각 3개를 모으세요."},progress={{30,217780863},"파편들을 획득하셨나요?"},completion={{105,372263083},"약속드린 대로, 맹렬함의 선물($B,$B)을 드립니다. 현명하게 사용하세요. 그러면 당신의 적들은 당신의 위력 앞에 떨게 될 것입니다!"}}
rows[41032]={title={{16,185969889},"고통을 무디게 하기 위해"},description={{575,954092068},"들어오거라, 얘야. 이곳은 편히 잠들지 못하는 죽은 자들 사이에서 너를 환영한다. 우리가 추종자들에게 베푸는 선물에 대해서는 네가 이미 알고 있을 테니, $B$B더 이상 자세히 설명하지는 않겠다. 나는 늑대인간이 되기로 선택했고, 저주 속에서 내가 떠나온 삶보다 훨씬 더 큰 힘과 지식을 얻었다. 지금은 모란나 부인의 연구를 돕고 있는데, 안타깝게도 연구가 교착 상태에 빠졌다. 내가 필요한 독은 이 묘지 바로 동쪽에 있는 할로우 웹 거미에게서 얻을 수 있다. 우리 신병들이 변신의 고통을 극복하는 데 매우 중요할 것이다. 열 병을 가져오너라. 그 정도면 충분할 것이다."},objectives={{78,927225833},"길니어스에 있는 할로우 웹 묘지에서 타냐 어머니를 위해 할로우 웹 독 10개를 모으세요."},progress={{272,549924962},"변신 과정은 누구에게나 힘든 여정일 수 있습니다. 낡은 껍질이 찢어지고 늑대인간의 본모습이 드러나는 순간, 극심한 고통이 따릅니다. 그 고통이 얼마나 큰지, 그리고 변신을 끝까지 해낼 내면의 힘이 부족한 사람들도 있다는 것을 이해해야 합니다."},completion={{142,1564711831},"돌아왔군! 독을 손에 쥐고! 늙은 여자의 으르렁거림—물론 미소지만—을 맞이하며.$B$B수고에 대한 감사의 표시로 이 동전을 받아라."}}
rows[41033]={title={{17,1388024443},"피의 해결책"},description={{507,1881946664},"반갑습니다, 친구. 우리와 함께 하러 오셨습니까? 호기심에 이끌리셨으니, 그 호기심을 충족시켜 주시길 바랍니다. 레이븐샤이어 사람들은 우리를 광신도 집단으로 여기고 있습니다. 우리의 힘을 죄악으로 보는 그들이 얼마나 $B$B어리석은지 아십니까? 저는 피 자체를 연구하는 임무를 맡았는데, 다른 종족의 피도 우리와 비슷한 성질을 가지고 있는지 궁금합니다. 동쪽에는 한때 시든 나무껍질 트롤의 고향이었던 오지(동부 내륙지)가 있습니다. 그곳에서 시든 나무껍질 피 다섯 병을 모아 제게 가져다주십시오."},objectives={{123,681391342},"할로우 웹 묘지에 있는 이선 레이븐크로프트를 위해 힌터랜드의 위더바크 트롤에게서 위더바크 피 5병을 모으세요."},progress={{175,1519878642},"피는 참 흥미로운 존재입니다. 엄청난 힘을 지니고 있죠. 우르의 연구에 따르면 악마는 죽은 사람의 피로 독살될 수 있다고 합니다. 정말 매혹적이지 않나요?"},completion={{151,794420945},"충분한 연구를 통해 우리는 혈액 자체의 특성을 밝혀낼 수 있을지도 모릅니다. 우리의 추측이 맞다면, 이는 모란나에게 매우 중요할 수 있습니다."}}
rows[41034]={title={{13,1193353146},"사악한 망토"},description={"I don't know your face, $r, I don't like new faces. There's enough trouble in these forests without outlanders dragging theirs along.$B$BBut you're here now, curse it all. The Master says it is all part of the Wolf Serpent's will and who is foolish wee me to disagree? Thus, I say you should help with your part.$B$BIt gets pretty cold up here in Gilneas and we pellars need clothes as much as anyone. Track down the Vilewing Bats and the Duskpelt Wolves, then bring me their furs. You'll find them almost anywhere in this country, but the closest are to the southwest.","당신 얼굴은 낯설어요,$r . 낯선 얼굴은 좋아하지 않아요. 이 숲에는 외지인이 괜히 덤벼들 필요도 없거든요.$B$B하지만 당신이 여기 왔으니, 젠장. 스승님께서는 이 모든 게 늑대뱀의 뜻이라고 하셨는데, 내가 어찌 감히 반대하겠어요? 그러니 당신도 제 몫을 $B$B해야죠.길니아스는 꽤 추워서 우리 펠러들도 다른 사람들처럼 옷이 필요해요. 바일윙 박쥐와 더스크펠트 늑대를 찾아내서 가죽을 가져오세요. 이 지역 어디에서나 찾을 수 있겠지만, 가장 가까운 곳은 남서쪽이에요."},objectives={{101,1225728937},"길니아스에 있는 모스그로브 농장 위쪽 동굴에서 베어베인을 위해 바일윙 가죽 5개와 더스크펠트 모피 5개를 모으세요."},progress={{139,1120214553},"사냥이라는 성례는 자연의 질서에서 매우 중요하다. 죽음은 생명을 키우고, 생명은 죽음을 키우고, 죽음은 다시 생명을 키운다.$B$B그 원은 끊어지지 않았다."},completion={{204,394017833},"저것 좀 봐, 꽤 용감한 이방인이군. 우리는 첫 사냥에서 승리해야 진정한 사나이가 된다고 하지만, 이건 네 첫 사냥이 아닌 것 같군.$B$B네 이국 얼굴은 그 정도는 참을 수 있지. 자, 어서 가거라."}}
rows[41035]={title={{24,562646965},"사냥개와 사냥꾼"},description={{405,1731950689},"길을 잃고 헤매던 너는, 의미를 쫓고 경이로움을 찾아 헤매다 늑대뱀의 품으로 향했구나. 내 말이 맞지? 나도 한때 $B$B너처럼 겁에 질린 암탉이었어. 맞고 물리고 우리에서 쫓겨나 피 흘리고 쓰러졌지! 북쪽 에본미어 $B$B농장 근처에서 나무꾼이 나무 사이를 배회하고 있어. 내 목숨을 앗아갈 놈이지. 네가 그의 마지막 먹잇감이 되어 늑대뱀의 축복을 너와 함께 나누리라."},objectives={{99,483218579},"매튜 베켓을 찾아 처치한 후, 길니어스에 있는 모스그로브 농장 위쪽 동굴에 있는 레반드라에게 돌아가십시오."},progress={{45,2013373010},"끝난 건가요? 악몽은 사라진 건가요?"},completion={{168,1027841853},"당신께 천 번 만 번 감사드립니다.$B$B내 가족, 내 혈육은 내가 역병에 걸렸다고 생각했고, 내가 그 멍에를 메울 가치가 없다고 생각했습니다. 이제 나는 더 이상 베케트가 아닌 자유로워졌습니다."}}
rows[41036]={title={{15,155766213},"죽음의 족쇄"},description={"My father, Demetreus, has seen your likeness in a dream, $N. He knew you would come to us one day.$B$BThe Wolf Serpent, our eternal guardian, will soon return to this world. We must make ready for his rebirth, for the cleansing of these lands.$B$BIn the west lie the Ruins of Greyshire. There are items there, mementos of significance, that hold a spiritual bond with the dead that possessed them in life.$B$BGather them for me, that I may summon the souls of the departed and relieve them of their suffering.","내 아버지 데메트레우스는 꿈에서 당신의 모습을 보셨습니다,$N . 언젠가 당신이 우리에게 올 $B$B것을 아셨죠.우리의 영원한 수호자, 늑대뱀이 곧 이 세상으로 돌아올 것입니다. 우리는 그의 재림, 이 땅을 정화할 준비를 해야 합니다.$B$B서쪽에는 그레이샤이어의 폐허가 있습니다. 그곳에는 생전에 그것들을 소유했던 죽은 자들과 영적인 연결고리를 가진, 의미 있는 기념품들이 있습니다.그것들을 $B$B모아 주십시오. 그러면 제가 죽은 자들의 영혼을 불러내어 그들의 고통을 덜어줄 수 있을 것입니다."},objectives={{64,300208445},"늑대숲에서 러른 파이브펠트를 위해 유령 기념품 10개를 모으세요."},progress={{202,1392420815},"이 토큰에는 이 망령들이 한때 누구였는지, 무엇을 소중히 여겼는지에 대한 흔적이 담겨 있습니다.$B$B결혼반지, 가문의 검, 잃어버린 손수건 등은 모두 저승과 현생을 잇는 연결고리가 될 수 있다."},completion={{231,548623148},"준비가 되면 이 물건들을 소금으로 원을 만들어 놓고, 검은 장미 향을 피워 영혼들을 불러내겠습니다.$B$B비록 그날이 아직 오지 않았고, 한동안은 오지 않겠지만, 당신은 잘 해냈습니다. 당신이라면 당연히 그렇게 했을 거라는 걸 알고 있습니다."}}
rows[41037]={title={{20,1520933754},"펠러용 막대"},description={"For what do you linger there, $c? Idle of hand, idle of spirit?$B$BIf you are looking for good work, then I have a task for you. From the soot on me you can see the markings of a blacksmith, and indeed, I have forged many a fine thing for us here.$B$BCopper and silver we do need, to craft the rods we wield to bridle lightning and shackle thunder. Find the talismans worn by the invading Foulhide gnolls south of here and bring them to me. They contain the metals that I need.","거기서 뭘 하고 있는 거냐, $c? 손도 안 쓰고, 마음도 $B$B빈둥거리는 거냐?만약 괜찮은 일을 찾고 있다면, 내가 자네에게 맡길 일이 있네. 내 몸에 묻은 그을음을 보면 대장장이의 솜씨가 드러난다. 나는 여기서 우리를 위해 훌륭한 물건들을 $B$B많이 만들어 왔지.우리는 번개를 제어하고 천둥을 묶는 막대를 만들기 위해 구리와 은이 필요하네. 여기 남쪽에서 침략해 온 파울하이드 놀들이 착용하고 있는 부적을 찾아 내게 가져오게. 그 안에 내가 필요한 금속이 들어있네."},objectives={{85,102944822},"길니어스에 있는 모스그로브 농장 위쪽 동굴에서 머스탱을 위해 파울하이드 부적 15개를 모으세요."},progress={{94,714534156},"놀들이 사용하는 장신구에는 은이 별로 없겠지만, 구리는 꽤 많이 사용하는 것 같군요."},completion={{171,2135701816},"못생기고, 조잡하고, 싸구려군. 놀이 만든 물건에 뭘 더 기대하겠나?$B$B하지만 금속은 금속이지. 내 손에 있는 게 쟤네들 손에 있는 것보다 낫군. 고맙습니다. 이 구리로 제대로 된 막대기를 만들 수 있겠군요."}}
rows[41038]={title={{20,1479015288},"에레니우스의 발톱"},description={{162,1572596771},"<에레니우스의 발톱에는 부패의 기운이 감돌고 있다. 어쩌면 누군가는 이 물건을 필요로 할지도 모르고, 누군가는 에레니우스의 운명을 알고 싶어할지도 모른다.>"},objectives={{58,1083181531},"에레니우스의 발톱을 필요로 할 만한 사람에게 가져다 주세요."},progress={{15,159386007},"도와드릴까요?"},completion={{409,1908477080},"에레니우스의 발톱.$B$B한때 우리 대의를 위해 헌신했던 고귀한 영웅이 몰락하는 모습을 보니 마음이 아픕니다. 위대한 에레니우스조차 각성의 유혹에서 벗어나지 못했던 것 같습니다. 타락이 그의 마음속 깊이 스며들어 그를 악의 하수인으로 만들었다고 생각합니다.$B$B이제 에레니우스는 고통에서 벗어나 편히 쉬고 있습니다. 당신의 공적에 감사드립니다. 영웅적인 행위에 대한 보답으로 이 유물 중 하나를 가져가십시오."}}
rows[41039]={title={{24,1816360892},"탈라나르를 위한 조항"},description={{625,1378829293},"탈라나르 주민들은 우리 군대를 유지하기 위해 부지런히 일해 왔지만, 안타깝게도 그들의 노력만으로는 우리 분대의 필요를 충족시키기에 역부족입니다. 우리 파수꾼들은 이미 우리를 위해 많은 희생을 치른 그들에게 더 이상의 부담을 주어서는 안 $B$B됩니다. 숙련된 사냥꾼들이 식량을 구하러 나섰지만, 이 임무의 규모를 고려할 때 모든 사람의 도움이 필요합니다. 인근에 늑대들이 어슬렁거리는 것을 목격했는데, 그들의 굶주림 또한 우리와 마찬가지입니다. 어서 사냥에 나서서 맛있는 늑대 고기 열 조각을 구해 오십시오. 우리의 전력을 강화할 수 있도록 말입니다."},objectives={{73,1899448823},"페랄라스 탈라나르에 있는 센티넬 글렌샤에게 늑대 고기 10덩어리를 가져다 주세요."},progress={{19,721585928},"한 발로 한 명을 사살한다."},completion={"These meats will be crucial for our survival in this wilderness. Thank you, $c.","이 고기들은 이 황무지에서 우리의 생존에 매우 중요할 것입니다. 감사합니다,$c."}}
rows[41040]={title={{16,505164563},"우드포우 디스어레이"},description={{526,323814601},"우드포우 놀들이 우리의 신성한 땅을 위협하며, 우리의 대상과 정찰병들을 공격하고 있습니다. 그들이 세력을 키워 탈라나르를 공격하는 것을 용납할 수 없습니다. 지금이 바로 공격할 때입니다. 당신의 $B$B임무는 명확합니다. 우드포우의 위협이 더 커지기 전에 제거하십시오. 악취로 쉽게 추적할 수 있는 위험한 우드포우 언덕에 있는 그들의 야영지를 찾아내십시오. 사냥꾼과 잡종 열 $B$B명을 처치하고, 약탈자 여덟 명을 쓰러뜨리고, 우두머리 여섯 명을 쓰러뜨리십시오. 이 결정적인 타격은 그들을 혼란에 빠뜨려 우리에게 귀중한 시간을 벌어줄 것입니다."},objectives={{141,105970531},"페랄라스의 탈라나르에 있는 사령관 아나샤 스타폴을 위해 우드포 사냥꾼 10명, 우드포 잡종 10명, 우드포 약탈자 8마리, 우두머리 6마리를 처치해야 합니다."},progress={{58,794332712},"그러고 보니 궁금해지네요... 놀들은 항상 거기 있었던 걸까요?"},completion={{422,628761214},"신속하고 단호하게, 당신은 놀라운 효율성으로 임무를 완수했습니다. 외부인임에도 불구하고 당신의 뛰어난 행동력은 많은 것을 말해줍니다.$B$B신속한 조치의 중요성을 인식하고 쓸데없는 잡담을 싫어하는 당신의 통찰력은 당신을 남다르게 합니다. 이는 우리 조직에서 매우 높이 평가하는 자질입니다. 샨드리스처럼 마지막 순간까지 망설이다가 결국… 하지만 지금은 그런 이야기는 하지 맙시다."}}
rows[41041]={title={{18,1760530687},"그림토템 음모"},description={{792,411150852},"모든 타우렌 부족이 호드에 합류하기를 열망했던 것은 아닙니다. 그중에서도 그림토템 부족은 예외적입니다. 대부분의 부족이 원시적인 본능을 억제하고 길들이려 애쓰는 반면, 그림토템 부족은 야만적인 본성을 그대로 받아들입니다. 세나리우스를 살해한 자들과 연대감을 느낄 법도 하지만, 그들에게도 자존심은 $B$B있습니다. 그림토템 부족은 충성과 독립 사이에서 아슬아슬한 줄타기를 하고 있습니다. 최근 우리 정찰병들이 북서쪽 모자체 야영지의 타우렌과 그림토템 부족 사이에 소규모 교전이 있었다고 보고했습니다. 이 분쟁의 원인이 $B$B무엇인지 궁금합니다. 그림토템 거주지로 가서 상황을 밝혀줄 단서를 찾아주십시오. 저는 이 갈등의 배후에 숨겨진 동기를 알고 싶습니다."},objectives={{145,1389895075},"그림토템 타우렌의 상황을 밝혀줄 단서를 찾아 페랄라스의 탈라나르에 있는 아나샤 스타폴 사령관에게 돌아오십시오."},progress={{515,1193305933},"과거 나이트 엘프와 타우렌이 굳건한 동맹을 맺었던 시절, 그림토템 부족은 끊임없이 문제를 일으키려 드는 것으로 악명이 높았습니다. 그들은 칼도레이로부터 독립을 추구했고, 그 과정에서 종종 자신들의 번영을 희생시키기도 했습니다.$B$B그럼에도 불구하고, 저는 그들의 전투 능력에 감탄하지 않을 수 없습니다. 타우렌 종족 내에서 그들은 켄타우로스의 맹공격에 맞서 굳건히 버텼고, 외딴 산악 전초기지에서 불리한 상황 속에서도 굳건히 자리를 지켰습니다. 역경 속에서도 굴하지 않는 그들의 회복력과 끈기는 칭찬받아 마땅합니다."},completion={{252,872193830},"흥미롭군. 그러니까, 그들의 지도자가 이 유물을 소유하고 있었다는 말이군. 이 유물에서 풍기는 기운은 틀림없이 스컬지의 기운을 풍긴다. 더 높은 지혜와 권위를 가진 분께 이 사실을 알려 적절한 조치를 결정해야겠어."}}
rows[41042]={title={{25,1624938076},"대드루이드의 말씀"},description={{490,1509501774},"이 유물의 의미를 해독할 수 있는 사람은 오직 한 명뿐입니다. 바로 대드루이드 판드랄입니다. 칼도레이족 중 많은 이들이 대사제와의 의견 차이 때문에 그에게 원한을 품고 있지만, 저는 그가 더 큰 그림을 보고 있다고 믿습니다.$B$B 티란데는 더 이상 우리 백성의 이익을 위해 $B$B행동하지 않습니다. 어쨌든 이 망치를 반드시 그에게 가져다주어야 합니다. 그는 적절한 해결책을 결정할 지혜와 지식을 갖추고 있습니다."},objectives={{59,1828870425},"조사 결과를 다르나소스에 있는 판드랄 스타그헬름에게 보고하십시오."},progress={{58,1122010494},"무슨 일이야? 내 말을 끊으려면 그럴듯한 이유라도 있어야 할 거야."},completion={{591,443831874},"아, 스컬지의 오염된 무기가 그림토템 무리에게서 발견되었다고? 전혀 놀랍지 않다. 그들은 언데드에 대한 기묘한 집착을 키워왔고, 심지어 포세이큰과 손을 잡는 비열한 짓까지 저질렀으니 말이다. 하지만 그 유물이 왜 그 한심한 그림토템 놈들의 손에 들어갔는지는 신경 쓸 필요 없다. 그것은 호드의 진정한 가치, 즉 죽음과 파괴를 보여주는 또 하나의 증거일 뿐이다.$B$B세상은 더욱 분열되고, 제2차 대격변이 임박했다. 이 일에 대한 당신의 관여는 비록 미미할지라도 기록되어 있다.$B$B이제 해산을 선언한다. 자, 당신의 보잘것없는 노력에 대한 감사의 표시로 이것만 받으리라."}}
rows[41043]={title={{21,1220443805},"이실디엔의 폐허"},description={{852,1309035931},"오래전 아즈샤라 여왕의 통치 시절, 이곳은 칼도레이 문명의 중심지로서 번성했습니다. 이제 남은 것은 오우거들이 점령했거나 언데드에 의해 오염된 폐허뿐입니다. $B$B이곳의 몰락은 신비로운 마법 때문이었고, 이곳에서 최후를 맞이한 자들에게 연민을 느끼기는 어렵습니다. 하지만 이 모든 마법의 타락 속에서도 한때 순수와 빛의 장소, 엘룬의 신전이 존재했습니다. 그 이름은 이제 시간의 기록 속에 잊혀졌지만$B$B 말입니다. 신전 안에서 여사제들은 우리 민족과 우리가 사는 세상의 뿌리와 깊이 연결된 신성한 유물을 지켰습니다. 저는 그 유물이 필요하지만, 지금은 임무 때문에 진영을 떠날 수 없습니다. 만약 운명이 당신을 이실디엔 폐허로 이끈다면, 상상할 수 없을 만큼 중요한 푸른 보석인 잘모스의 눈물을 찾아주십시오. 당신의 도움은 매우 귀중할 것입니다."},objectives={{125,1441468007},"이실디엔 유적의 엘룬 신전에서 잘모스의 눈물을 찾아 페랄라스의 탈라나르에 있는 라로다르에게 가져다주세요."},progress={"Have you found it, $c?","$c님, 찾으셨나요?"},completion={{196,1357320107},"좋습니다, 잘모스의 눈물을 되찾는 데 도움을 주셔서 진심으로 감사드립니다. 하지만 눈물을 얻는 것은 더 큰 목표를 향한 첫걸음에 불과합니다. 다시 한번 도움을 주시겠습니까?"}}
rows[41044]={title={{18,577200174},"타락한 고대인"},description={{890,1762707802},"한때 칼도레이 제국의 막대한 영향력은 전 세계에 미쳤지만, 대격변이라는 대재앙으로 우리의 영토는 산산이 조각났습니다. 그 결과, 우리의 성스러운 유물들은 지구 곳곳으로 흩어졌습니다. $B$B최근 길니아스를 외부 세계와 가르던 그레이메인 장벽이 무너졌다는 소문이 돌고 있습니다. 저는 인간 왕국들의 내분에는 별 관심이 없지만, 길니아스가 한때 고대 야생의 신 잘모스의 고향이었다는 사실은 주목할 만합니다. 슬프게도 잘모스는 고대 전쟁 중에 그곳에서 목숨을 잃었습니다. 당신의 임무는 $B$B길니아스로 가서 마녀숲의 펠라르라는 수수께끼의 집단이 소유하고 있다고 전해지는 잘모스의 송곳니를 되찾는 것입니다. 안타깝게도 자세한 정보는 부족하지만, 당신의 기지가 진실을 밝혀내는 데 도움이 될 것입니다."},objectives={{50,1051455418},"길네아로 가서 마녀의 숲 종을 찾으세요."},progress={{31,445733570},"얘야, 무슨 일로 여기에 왔니?"},completion={{635,622743524},"아, 그렇다면 자모스의 송곳니라고 알려진 신성한 유물을 찾고 있소? 그렇다, 우리 펠라르 가문은 그러한 유물을 손에 넣을 수 있다. 우리는 이 고대 유물의 수호자로 임명되었기 때문이다. 늑대뱀의 입은 수없이 많았고, 한 번 물 때마다 천 마리 늑대의 힘이 깃들어 있었다.$B$B서쪽 땅의 드루이드가 이런 유물을 왜 원하는지 궁금증이 드는 것은 어쩔 수 없소. 하지만 나는 고대의 방식을 따르는 보잘것없는 하인에 불과하며, 수천 년의 역사를 가진 분의 권위에 감히 이의를 제기할 수 있겠소? 자네가 내 부탁을 들어준다면, 잘모스의 송곳니 중 하나를 주겠소."}}
rows[41045]={title={{15,307995545},"뱀뿌리"},description={{674,946427616},"제게 매우 중요한 일에 당신의 도움이 필요합니다.$B$B 길네아 내전으로 혼란스러운 이 시기에 우리의 치유 능력에 대한 수요는 전례 없이 높아졌습니다. 하지만 우리는 이 동굴의 안전한 곳에 갇혀 위험한 야생으로 나가 필수 물자를 구할 수 없는 처지입니다. 야생에 도사리고 있는 위험은 날이 갈수록 더욱 거세지고 있습니다. 용감한 영혼이여, $B$B제가 당신에게 부탁할 것은 뱀뿌리라는 희귀한 치유 약초입니다. 이 약초는 길네아 땅에서만 자라며, 혼란 속에서도 무성하게 자랍니다. 이 귀한 약초 열 개를 구해다 주시면, 당신의 노고에 대한 보상으로 잘모스의 송곳니 하나를 드리겠습니다."},objectives={{42,89519139},"러른 파이브 펠트를 만들려면 서펜트루트 10개를 모으세요."},progress={{28,2091869521},"늑대뱀이 당신을 지켜볼 것입니다."},completion={{69,540089656},"훌륭합니다. 이 물품들로 우리는 도움이 필요한 사람들을 도울 수 있을 것입니다."}}
rows[41046]={title={{17,1396732700},"탈라나르로 돌아가기"},description={{861,357474355},"용감한 모험가여, 여기$B$B 있습니다.<늙은 펠라르가 거친 손을 뻗어 잘모스의 송곳니를 조심스럽게 당신의 손에 $B$B쥐어줍니다.>이 신성한 유물을 손에 쥐십시오. 여기에는 우리의 고대 야생 신 잘모스의 정수가 담겨 있습니다. 결코 가볍게 여겨서는 안 될 힘입니다. 잘못된 손에 들어가면 헤아릴 수 없는 파괴를 초래할 수 있습니다. 섭정들은 우리에게 직접 도전할 만큼 어리석지는 않았지만, 적은 그림자 속에 숨어 기회를$B$B 엿보고 있습니다.이 송곳니를 최대한 경계하며 지키십시오. 이제 이것을 안전하게 지키는 것은 당신의 책임입니다. 적이 이것을 보게 된다면, 그들의 권력과 지배욕은 결코 사그라지지 않을 것입니다. 늑대뱀의 축복이 당신의 여정을 인도하고 보호하길 바라며, 다시 번영하는 길네아에서 다시 만나기를 바랍니다. 그리고 이 임무를 맡긴 드루이드에게 제 안부를 전해 주십시오."},objectives={{45,1914473530},"탈라나아르에 있는 라로다르에게 잘모스의 송곳니를 가져가야 합니다."},progress={{68,688814411},"드디어 돌아오셨군요. 잘모스의 송곳니를 되찾는 데 성공하셨나요?"},completion={{303,1433067718},"정말 흥미롭군요. 인간들이 한때 그들의 땅에 깃들었던 고대의 힘을 잊지 않았다는 사실이 고무적입니다. 잘모스의 송곳니를 되찾아 오신 것을 진심으로 축하드립니다. 하지만 우리의 임무는 아직 끝나지 않았습니다.$B$B아직 한 조각, 우리가 획득해야 할 유물이 하나 더 남아 있습니다."}}
rows[41047]={title={{19,2062264826},"페랄라스의 페랄킨"},description={{1001,1333789819},"당신은 소중한 동맹임을 증명해 보였고, 그에 대한 보답으로 진실을 밝히겠습니다. 우리가 모은 유물들은 세상의 균형을 되찾기 위한 더 큰 계획의 일부에 불과합니다. 잘모스는 $B$B비할 데 없는 재생 능력을 지녔습니다. 그의 정수를 활용하면 펠우드의 타락한 땅을 치유하고 죽어가는 세계수를 되살릴 수 있는 치유의 힘을 불러일으킬 수 있습니다. 하지만 유물만으로는 이 임무를 $B$B완수할 수 없습니다. 세네론의 도움이 필요합니다. 그는 한때 잘모스 밑에서 수련했던 드루이드였습니다. 세월이 흐르면서 세네론은 많이 변했지만, 우리는 그가 여전히 페랄라스의 고대 숲을 배회하고 있다고 믿습니다. 야생의 신과의 연결고리가 그를 이 유물들의 잠재력을 발휘하는 열쇠로 삼고 있습니다. 페랄라스의 황야에서 세네론을 $B$B찾으십시오. 조심하십시오. 그는 이제 원시적인 본능을 잃어버린 야성적인 존재가 되었습니다. 당신이 그의 신뢰를 얻을 수 있다면, 그는 이 유물들의 힘을 증폭시킬 수 있는 지식을 갖게 될 것입니다."},objectives={{29,2076111879},"페랄라스에서 야생 동물을 찾아보세요."},progress={{200,558731537},"야생의 사나이 세네론은 고대의 눈으로 당신을 응시합니다. 그의 야성적인 모습은 주변의 황야와 완벽하게 어우러져 있습니다. 그가 당신의 존재를 신중하게 살피는 동안 무거운 침묵이 공기를 감쌉니다."},completion={{579,1596689754},"내 지혜를 구하는 것이로군. 감히 내 영역에 발을 들여놓는 자는 드물고, 하물며 나를 만나려 하는 자는 더욱 드물다. 목적을 말하되, 말에 신중을 기해야 할 것이다. 나는 쓸데없는 잡담을 참을성이 없기 때문이다.$B$B<세네론의 시선이 더욱 강렬해지고, 그의 원초적인 본능은 조금이라도 속임수나 무례함이 보이면 당장이라도 달려들 준비를 하고 있다. 그림자 속에 숨어 있던 그의 무리는 불안하게 움직이며, 야성적인 기운이 공기 중에 감돌고 있다.>$B$B필멸자여, 명심하라. 인간과 자연의 관계는 매우 섬세하다. 한 번의 실수로 내 무리는 주저 없이 네게 분노를 쏟아낼 것이다. 자, 이제 네 의도를 밝혀라."}}
rows[41048]={title={{17,1195751103},"잘모스의 정수"},description={{992,1818972097},"당신은 그림자에 가려지고 기만에 가려진 답을 찾고 있군요. 당신을 보낸 자들은 나름의 속셈이 있을지 모르지만, 이제 와서는 중요하지 않습니다. 당신은 저를 찾아냈고, 쓸데없는 $B$B이야기를 나눌 시간은 지났습니다. 세라데인이 번성하는 머나먼 땅에서, 부엉이족은 잘모스의 정수를 지키는 막중한 임무를 맡았습니다. 오랜 세월이 흘러 그들이 맡았던 고대의 임무에 대한 기억은 희미해졌을지도 모릅니다. 하지만 그들이 아직 잘모스의 존재 조각을 담고 있는 영혼의 보석을 가지고 있을 가능성이 있습니다.$B$B 제가 드릴 수 있는 정보는 여기까지입니다. 이제 이곳을 떠나십시오. 저는 고독과 동족과의 교제를 원합니다. 영혼들이 당신의 길을 인도하길, 그리고 우리의 길이 다시는$B$B 겹치지 않기를 바랍니다. 세네론의 날카로운 시선이 잠시 당신에게 머물다가, 그는 시선을 돌려 주변의 원시 세계로 향합니다. 메시지는 분명합니다. 당신의 시간은 끝났고, 그는 자신의 고독한 삶에 더 이상의 간섭을 원하지 않습니다."},objectives={{102,2073889303},"오지로 모험을 떠나 그곳의 올빼미족이 잘모스의 영혼 보석을 어디에 숨겨두고 있는지 알아내세요."},progress={{28,1424993276},"야생 동물을 찾으셨나요?"},completion={"The essence of the Wolf-Serpent before my eyes... Remarkable.$B$BI have tarried here long enough. The time has come to make my way back to Teldrassil, bearing the treasures you have procured. Fandral will be eager to learn of these developments, and I can already anticipate the satisfaction in his eyes.$B$BThank you, $N. You have played a part in something bigger than you can imagine.","내 눈앞에 펼쳐진 늑대뱀의 본질이라니... 놀랍군.$B$B이제 이곳에 너무 오래 머물렀어. 네가 구해준 보물들을 가지고 텔드라실로 돌아갈 때가 되었어. 판드랄은 이 소식을 듣고 무척 기뻐할 테고, 그의 만족스러운 눈빛을 벌써부터 기대하게 돼.$B$B고마워,$N. 넌 상상 이상으로 큰 일에 일조했어."}}
rows[41049]={title={{14,324996727},"키메라 임무"},description={{575,1916632838},"길들여지지 않은 아름다움을 지닌 장엄한 생명체, 키메라는 과거 우리의 충실한 동맹이자 강력한 전투 짐승이었습니다. 그러나 3차 전쟁 중 불타는 군단의 파괴적인 공격으로 그들의 서식지는 파괴되었고, 우리는 그들의 동반과 힘을 잃었습니다. 하지만 희망이 다시 $B$B피어오르고 있습니다. 노련한 키메라 조련사 벨로스 샤프스트라이크가 놀라운 발견을 했습니다. 바로 우리 위치에서 남서쪽에 오랫동안 잊혀진 키메라 서식지가 있다는 것입니다. 그는 이 신성한 안식처를 되살리고 복원하는 데 도움을 요청하고$B$B 있다고 합니다. 벨로스를 도와주세요."},objectives={{62,1212056053},"페랄라스의 키메라 루스트 베일에 있는 벨로스 샤프스트라이크에게 보고하십시오."},progress={{33,1838383321},"손님이 오실 줄은 몰랐네요. 환영합니다."},completion={{63,922279321},"이곳 상태가 좋지 않아 죄송합니다. 저희 일은 이제 막 시작됐습니다."}}
rows[41050]={title={{19,1548153305},"둥지를 정리하다"},description={{530,920324856},"새로운 키메라를 훈련시키는 길을 시작하려면 먼저 이 둥지를 현재 살고 있는 키메라들을 제거해야 합니다. 저 하늘을 나는 생명체들이 아무리 웅장할지라도, 이미 훈련 단계를 넘어섰고 우리의 목적에 부합하지 않습니다. 진정으로 $B$B순종적이고 충성스러운 동반자를 만들기 위해서는 아주 어릴 때부터 시작해야 합니다. 그러므로 여러분께 무기를 들고 이 하늘을 배회하는 듄바운드 키메라 여덟 마리와 베놈래쉬 키메라 여덟 마리를 처치해 주시길 부탁드립니다. 길이 열리면 비로소 우리의 진정한 임무가 시작될 수 있을 것입니다."},objectives={{107,453759945},"페랄라스의 키메라 둥지 계곡에서 듄바운드 키메라 8마리와 베놈래쉬 키메라 8마리를 처치하여 벨로스 샤프스트라이크를 획득하세요."},progress={{55,2118735560},"독성이 강한 숨결을 조심하세요. 한 번의 실수로 치명적일 수 있습니다."},completion={{619,1546891739},"아, 어린아이여, 정말 고맙구나. 이 지친 내 몸은 오랜 세월을 견뎌왔고, 늙어가는 눈은 예전처럼 예리하지 못하구나. 자네가 여기 와준 것은 정말 다행스러운 일이네. 이제 곧 기대의 순간이 다가오기 때문이지.$B$B우리 앞에 있는 저 소중한 알들을 보아라. 둥지의 포근한 품 안에 자리 잡고 있구나. 새 생명의 약속으로 반짝이는 알껍질은 곧 부화할 것을 기대하며 떨리고 있네. 참으로 장엄한 광경이로군.$B$B깨어 있거라. 이제 곧 연약한 알껍질이 안에 있는 힘에 굴복하고, 새로운 키메라 새끼들이 이 세상에 모습을 드러낼 테니까."}}
rows[41051]={title={{22,1741072155},"어린 동물들에게 먹이 주기"},description={{661,180313959},"아, 어린 키메라들의 왕성한 식욕이란! 정말이지, 그 어떤 것과도 비교할 수 없죠. 이 작은 녀석들은 하루에 자기 몸무게의 두 배나 되는 양을 먹어치울 수 있지만, 먹이에 대해서는 아주 까다롭습니다. 과거에는 버릇없는 조련사들이 유혹적인 선택이었을지 모르지만, 이제는 더 적절한 먹이로 그들의 허기를 달래줘야 $B$B합니다.이번 경우에는 키메라들이 가장 좋아하는 별미가 바로 히포그리프입니다. 광활한 야생 지대 깊숙한 곳에서 상당한 수의 히포그리프 무리가 발견되었습니다. 자네는 이 히포그리프들을 사냥해서 고기 스무 조각을 가져와야 합니다. 이것은 곧 부화할 키메라들에게 풍성한 영양을 공급하고 점점 커지는 식욕을 만족시켜 줄 것입니다."},objectives={{90,1598262545},"페랄라스의 키메라 둥지 계곡에 있는 벨로스 샤프스트라이크에게 히포그리프 고기 20덩어리를 가져다 주세요."},progress={{141,1892617196},"나이트 엘프인 우리가 히포그리프를 죽이는 것을 가볍게 여기는 것은 아니지만, 키메라가 건강하게 자라기 위해서는 어쩔 수 없이 필요한 일입니다."},completion={{313,1050226480},"아, 드디어 돌아오셨군요! 정말 적절한 시기에 오셨습니다. 기대감이 점점 커지고 있는데, 키메라들이 곧 부화할 것 같은 예감이 듭니다. 며칠 후면 이 장엄한 생명체들이 알에서 깨어나 우리 보금자리를 찾아올 겁니다. 당신이 제때 와주셔서 정말 감사하고, 덕분에 그들의 도착을 완벽하게 준비할 수 있게 되었습니다."}}
rows[41052]={title={{20,1777259810},"키메란의 하네스"},description={{912,949692761},"고대의 이야기를 하나 들려드리겠습니다. 수천 년 전, 칼도레이와 키메라 사이에 중대한 계약이 맺어졌습니다. 그 고대에는 키메라란이라는 놀라운 인물이 있었습니다. 그는 이 고귀한 생명체들을 훈련시킬 뿐만 아니라, 비할 데 없는 우아함으로 그들의 등에 올라탈 수 있는 희귀한 능력을 지녔습니다. 하지만 마라우딘 $B$B켄타우로스와의 잔혹한 전쟁 중에 비극이 닥쳤습니다. 그들은 키메라란의 전설적인 마구를 약탈해 갔습니다. 비록 켄타우로스가 더 이상 그것을 가지고 있지는 않지만, 전해지는 바에 따르면 그것은 여전히 ​​마라우돈의 미로 깊숙한 곳에 있다고 합니다. 그러나 조심하십시오. 사악한 사티로스와 같은 다른 악의 세력이 이제 이 귀중한 유물의 수호자가 되었을지도 모릅니다. 부디$B$B 마라우돈으로 모험을 떠나 잃어버린 마구를 되찾아 주십시오. 그것을 되찾는 것은 키메라 조련사들의 유산에 심오한 의미를 지니고, 한때 우리 종족을 하나로 묶었던 고대의 유대를 기리는 일이 될 것입니다."},objectives={{121,1046502249},"마라우돈에게서 키메라의 하네스를 되찾아 페랄라스의 키메라 둥지 계곡에 있는 벨로스 샤프스트라이크에게 가져다주세요."},progress={{26,292670474},"복구하셨나요?"},completion={{694,1392028734},"<벨로스는 되찾은 하네스를 꼭 움켜쥐었고, 그의 주름진 얼굴은 감정에 젖어 부드러워졌다. 당신의 손에서 유물을 건네받는 그의 눈에는 눈물이 고였고, 감사함에 그의 목소리는 떨렸다.>$B$B친구여, 당신은 숭고한 일을 행하셨습니다. 당신의 행동은 제 마음속에 희망의 불꽃을 다시 지펴주었습니다. 오랫동안 잃어버렸던 이 유물을 되찾음으로써, 저는 이제 새로운 세대의 키메라를 훈련시키고 양육할 수 있는 미래를 감히 꿈꿀 수 있게 되었습니다. 당신의 헌신적인 행동은 제게 마음의 안정을 주고 새로운 삶의 목적을 주었습니다. 저는 당신에게 영원히 은혜를 갚겠습니다.$B$B당신의 변함없는 헌신과 지지에 대한 감사의 표시로 이 작은 선물을 드립니다. 앞으로 당신의 여정에 도움이 되기를 바랍니다."}}
rows[41053]={title={{19,562981444},"갈락 전령"},description={{715,2041545840},"우리의 경계는 끝나지 $B$B않을 것이다. 버섯구름 봉우리을 점령한 켄타우로스 부족은 날이 갈수록 더욱 뻔뻔해지고 있으며, 그들의 정찰병들은 대담하게 우리의 신성한 땅을 침범하고 있다. 지금은 다른 이들을 괴롭히는 데 만족하고 있지만, 이 끔찍한 괴물들이 우리 마을을 노리는 것은 시간 문제일 뿐이다. 내 정찰병들은$B$B 이 땅의 군벌들 사이에서 소식을 전하는 켄타우로스 전령의 존재를 보고했다. 우리는 그들이 계속해서 우리를 상대로 음모를 꾸미도록 내버려 둘 수 없다. 우리는 그들의 계획을 알아내야 하며, 그것도 신속하게 해야 한다. 나는 $B$B당신이 이 전령을 제거하고 그들이 전하는 모든 메시지를 확보할 수 있는 능력을 갖추고 있다고 믿는다. 나는 실패를 용납하지 않을 것이다."},objectives={{103,1269210914},"탈라나르에 있는 아나샤 스타폴 사령관을 위해 갈락 메신저로부터 센타우르 서신을 찾아 회수하십시오."},progress={{21,1335376226},"날 실망시키지 마."},completion={{236,350092625},"메시지를 회수했군. 잘했어. 이제 보여줘.$B$B<아나샤 사령관이 당신에게서 메시지를 받아 미간을 찌푸리며 꼼꼼히 읽는다.>$B$B흥미롭군... 그들이 타우렌을 공격할 준비를 하고 있어."}}
rows[41054]={title={{17,2088984382},"부끄러운 줄 알아라, 다시는 안 돼"},description={{671,1837664366},"나는 우리의 신성한 땅을 더럽히는 악마의 손아귀에 빠진 자들과 동맹을 맺은 배신자 타우렌을 조금도 좋아하지 않는다. 하지만 의무가 우리를 부르고 있으니, 우리는 어쩔 수 없이 그들을 도와야 한다. 호드와 얼라이언스의 정치적 입장은 지금 이 순간 중요하지 않다. 칼도레이의 명예가 다시 더럽혀지는 것을 용납할 수 없으며, 무고한 피가 흘려지는 것을$B$B 가만히 지켜볼 수도 없다. I는 외교관을 타우렌에게 보내 그들의 위태로운 상황을 알리도록 할 것이다. 그동안, 자네는 용감하게 나아가 켄타우로스의 수를 줄여 프리윈드의 타우렌들이 방어 태세를 갖출 시간을 벌어주도록 부탁한다. 자네의 공로를 증명하기 위해 그들의 팔찌 20개를 가지고 돌아오게 하라. 엘룬의 빛이 자네의 길을 인도하길."},objectives={{66,2000789674},"탈라나르에 있는 사령관 아나샤 스타폴에게 갈라크 팔보호구 20개를 가져가야 합니다."},progress={{86,364496182},"켄타우로스는 주로 사우전드 니들스 북부 지역에서 발견됩니다. 시간을 낭비하지 마세요."},completion={{257,760656737},"당신의 노력 덕분에 타우렌족에게 매우 중요한 시간을 벌어주었고, 우리 외교관은 회담에서 무사히 돌아왔습니다. 타우렌족은 제공해주신 정보에 깊은 감사를 표했으며, 그들의 감사는 우리 마음속에도 깊이 새겨져 있습니다.$B$B다시는 우리에게 수치가 닥치지 않겠습니다."}}
rows[41055]={title={{21,227499532},"드림스케일 컬렉션"},progress={{278,1930724812},"$c님, 혹시 좋은 결과 있으셨나요?"},completion={{111,1078390207},"음, 모든 게 괜찮아 보이네요. 저희를 도와주셔서 정말 감사합니다. 자, 이거 받으세요."}}
rows[41056]={title={{19,487973889},"놀드랏실의 망토"},description={{371,202930401},"무기고에는 수많은 무기, 갑옷, 그리고 고대의 위대한 유물들이 보관되어 있습니다. 이 물건들은 매우 강력하며, 강력한 마법이 깃들어 있습니다. 저는 하이잘에서 가치 있는 동맹임을 증명한 자들에게 이러한 물건들을 제공할 권한을 부여받았습니다.$B$B 노르드라실의 휘장을 원하신다면, 밝은 꿈의 조각 150개를 가져오십시오. 그러면 당신의 것이 되겠습니다."},objectives={{75,970986653},"하이잘의 노르다나르에서 엘바노르의 심장 노래를 위해 밝은 꿈 조각 150개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{95,1827772576},"저희 무기고에 있는 이 유물이 당신에게 큰 도움이 되어 앞으로 닥칠 모든 전투에서 당신을 지원하길 바랍니다."}}
rows[41057]={title={{13,1143860405},"딥우드 파이프"},description={{365,1378586313},"무기고 안에는 수많은 무기, 갑옷, 그리고 고대의 위대한 유물들이 보관되어 있습니다. 이 물건들은 매우 강력하며, 강력한 마법이 깃들어 있습니다. 저는 하이잘에서 가치 있는 동맹임을 증명한 자들에게 이러한 물건들을 제공할 권한을 부여받았습니다.$B$B 심층목 파이프를 원하신다면, 밝은 꿈 조각 150개를 가져오십시오. 그러면 당신의 것이 되겠습니다."},objectives={{75,970986653},"하이잘의 노르다나르에서 엘바노르의 심장 노래를 위해 밝은 꿈 조각 150개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{95,1827772576},"저희 무기고에 있는 이 유물이 당신에게 큰 도움이 되어 앞으로 닥칠 모든 전투에서 당신을 지원하길 바랍니다."}}
rows[41058]={title={{14,446419135},"스태그우드 그라스프"},description={{366,77081274},"무기고에는 수많은 무기, 갑옷, 그리고 고대의 위대한 유물들이 보관되어 있습니다. 이 물건들은 매우 강력하며, 강력한 마법이 깃들어 있습니다. 저는 하이잘에서 가치 있는 동맹임을 증명한 자들에게 이러한 물건들을 제공할 권한을 부여받았습니다.$B$B 사슴나무 손아귀를 원하신다면, 밝은 꿈 조각 150개를 가져오십시오. 그러면 당신의 것이 되겠습니다."},objectives={{75,970986653},"하이잘의 노르다나르에서 엘바노르의 심장 노래를 위해 밝은 꿈 조각 150개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{95,1827772576},"저희 무기고에 있는 이 유물이 당신에게 큰 도움이 되어 앞으로 닥칠 모든 전투에서 당신을 지원하길 바랍니다."}}
rows[41059]={title={{28,1594272690},"노르다나르 수호자 스폴더"},description={{380,286266456},"무기고에는 수많은 무기, 갑옷, 그리고 고대의 위대한 유물들이 보관되어 있습니다. 이 물건들은 매우 강력하며, 강력한 마법이 깃들어 있습니다. 저는 하이잘에서 가치 있는 동맹임을 증명한 자들에게 이러한 물건들을 제공할 권한을 부여받았습니다. $B$B노르다나르 수호자 어깨 보호구를 원하신다면, 밝은 꿈 조각 150개를 가져오십시오. 그러면 당신의 것이 되겠습니다."},objectives={{75,970986653},"하이잘의 노르다나르에서 엘바노르의 심장 노래를 위해 밝은 꿈 조각 150개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{95,1827772576},"저희 무기고에 있는 이 유물이 당신에게 큰 도움이 되어 앞으로 닥칠 모든 전투에서 당신을 지원하길 바랍니다."}}
rows[41060]={title={{16,954202798},"드림브리즈 카울"},description={{368,1289007752},"무기고에는 수많은 무기, 갑옷, 그리고 고대의 위대한 유물들이 보관되어 있습니다. 이 물건들은 매우 강력하며, 강력한 마법이 깃들어 있습니다. 저는 하이잘에서 가치 있는 동맹임을 증명한 자들에게 이러한 물건들을 제공할 권한을 부여받았습니다.$B$B 드림브리즈 카울을 원하신다면, 밝은 꿈의 조각 150개를 가져오십시오. 그러면 당신의 것이 되겠습니다."},objectives={{75,970986653},"하이잘의 노르다나르에서 엘바노르의 심장 노래를 위해 밝은 꿈 조각 150개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{95,1827772576},"저희 무기고에 있는 이 유물이 당신에게 큰 도움이 되어 앞으로 닥칠 모든 전투에서 당신을 지원하길 바랍니다."}}
rows[41061]={title={{15,228096896},"클로버링크 벨트"},description={{367,1922848425},"무기고에는 수많은 무기, 갑옷, 그리고 고대의 위대한 유물들이 보관되어 있습니다. 이 물건들은 매우 강력하며, 강력한 마법이 깃들어 있습니다. 저는 하이잘에서 가치 있는 동맹임을 증명한 자들에게 이러한 물건들을 제공할 권한을 부여받았습니다. $B$B클로버링크 벨트를 원하신다면, 밝은 꿈의 조각 150개를 가져오십시오. 그러면 당신의 것이 되겠습니다."},objectives={{75,970986653},"하이잘의 노르다나르에서 엘바노르의 심장 노래를 위해 밝은 꿈 조각 150개를 모으세요."},progress={{45,2062388738},"꿈의 조각 모험가를 데려오셨나요?"},completion={{95,1827772576},"저희 무기고에 있는 이 유물이 당신에게 큰 도움이 되어 앞으로 닥칠 모든 전투에서 당신을 지원하길 바랍니다."}}
rows[41062]={title={{21,781510573},"여신의 낫"},description={{578,1809332730},"당신의 손에는 불가사의한 엘룬의 낫이 쥐어져 있습니다. 고대 유물인 이 낫은 신비에 싸여 있으며 상상할 수 없는 힘을 발산합니다. 낫이 여기까지 오게 된 과정은 여전히 ​​수수께끼로 남아 있습니다. 어떻게, 그리고 왜 여기에 왔는지는 답을 찾아야 할 질문들입니다. 하지만 지금 당장 가장 중요한 것은 이 특별한 유물이 초래한$B$B 파괴를 막는 것입니다. 카라잔의 늑대인간 지도자 클로로드 하울팽을 처치하십시오. 그의 폭정에서 벗어나야만 혼돈 속에서 질서를 되찾을 수 있습니다. $B$B임무를 완수한 후에는 에본록 경에게 이 불가사의한 낫에 대한 답을 구하십시오."},objectives={{52,679901751},"클로로드 하울팽을 처치하고 에본록 경에게 보고하십시오."},progress={{34,1751749170},"네, 필멸자시여? 무엇을 도와드릴까요?"},completion={{726,1138388524},"엘룬의 낫… 심오한 힘을 지닌 저주받은 유물인 이 낫은 시간과 그림자에 묶인 존재, 어둠의 기사 중 한 자에 의해 카라잔의 성지로 옮겨졌습니다. 그들의 도착에 대한 기억은 최근의 일처럼 느껴지면서도 아주 오래전 일처럼 느껴지기도 하지만, 시간은 제 마음을 혼란스럽게 하는 태피스트리를 짜는 듯 흐릿합니다.$B$B그 비열한 존재, 블랙왈드는 낫을 손에 넣는 데 쾌감을 느꼈습니다. 그의 악의는 끝이 없었고, 그토록 강력한 유물을 소유하는 데서 기쁨을 찾았습니다. 카라잔의 전당은 그의 뒤틀린 만족감으로 가득 찼습니다.$B$B지금은 감히 그것을 사용하려는 생각조차 하지 마십시오. 너무 오랫동안 어둠의 세력의 손에 있었던 이 낫은, 당신의 의도가 아무리 정당하다 하더라도 더 큰 파괴만을 가져올까 두렵습니다."}}
rows[41063]={title={{21,781510573},"여신의 낫"},description={{971,202909394},"더 자세히 말씀드리고 싶지만, 안타깝게도 제 처지로는 의미 있는 정보를 얻을 수 없었습니다. 블랙월드 경은 그것을 이용해 카라잔으로 늑대인간들을 소환했고, 그들은 대체로 그의 명령에 $B$B복종했습니다. 어둠의 기사들은 메디브가 정의로운 기사들의 뒤틀린 형상으로 만든, 유물 사냥꾼의 저주를 받았습니다. 그의 존재는 오래전에 사라졌지만, 이 무자비한 사냥꾼들은 알려지지 않은 주인을 위해 끊임없이 보물을 찾아 헤매고 있습니다. 아, 이 $B$B신비로운 유물에 숨겨진 목적을 밝혀낼 수 있다면 얼마나 좋을까요. 하지만 당신의 여정에 한 줄기 희망을 드리겠습니다. 어쩌면 자신도 모르게 어둠의 기사들을 도왔던 자들을 찾아보세요. 한때 위대한 마을로 알려졌던, 비밀과 속삭임이 뒤얽힌 제 옛 영토를 바라보십시오. 그곳에서 당신의 탐색이 결실을 맺을지도 모릅니다. 소문에 따르면 늑대인간들이 왕국 곳곳을 배회하고 있으며, 그들의 존재는 낫과의 연관성을 증명하는 것이라고 합니다."},objectives={{71,206762565},"황혼의 숲에서 엘룬의 낫에 대해 더 잘 아는 사람을 찾아보세요."},progress={{6,130161156},"네?"},completion={{316,234292094},"제발, 엘룬의 낫에 손대지 마세요! 제가 마지막으로 그 낫을 만졌을 때, 황혼의 숲에 파멸이 닥쳤습니다. 그 저주받은 유물의 결과가 저를 괴롭히고 있습니다. 제발, 그 낫을 찾으려는 생각은 버리세요. 그 힘은 운명을 뒤틀고 비극을 가져오는 독과 같습니다. 그 낫은 잊혀지고, 그 어두운 유산은 그림자 속에 묻히게 하세요."}}
rows[41064]={title={{21,781510573},"여신의 낫"},description={{759,1260244507},"당신이 그걸 가지고 있다고요? 안 돼, 안 돼, 안 돼! 끔찍해, 절대 발견되어서는 안 될 물건이야! 무시무시한 어둠의 기사들이 돌아오고 있어. 그들은 내 목숨을 앗아가고 황혼의 숲 전체에 파멸을 불러일으키려 하고 있지! 하지만, $B$B아무리 끔찍한 일이라도, 낫이 그들의 손에 들어가는 것보다는 당신 손에 있는 게 나을 것 같소. 하지만 솔직히 말해서, 이 유물에 대해 아는 것이 거의 없소. 아주 잠깐 동안 내 손에 쥐어보긴 했지만, 내 연약한 존재를 걸고 맹세하건대, 나는 그 진정한 정체를 알지 못하오. 난 아무것도 몰라! 운명이 내 떨리는$B$B 손에 낫을 쥐여준 곳은 롤랜드의 파멸이라 불리는 황량한 옛 광산의 깊은 곳이었소. 꼭 가야 한다면 그곳으로 가시오. 하지만 조심하오. 그곳은 늑대인간, 아니, 그보다 더 어두운 존재들로 가득 차 있소."},objectives={{69,463439786},"롤랜드의 파멸로 가서 엘룬의 낫에 대한 단서를 찾아보세요."},progress={{48,1863092578},"내 여신의 낫이 느껴진다... 당신은 누구인가?"},completion={{295,985212925},"나는 당신 앞에 서서, 낯선 손에 들려 있는 낫이 내게 돌아오는 것을 지켜보고 있습니다. 안도감과 걱정이 동시에 밀려옵니다. 이 신성한 유물이 세월 속에 사라진 채로 있는 한, 내 영혼은 결코 안식을 찾을 수 없었기 때문입니다.$B$B용감한 이들이여, 어떻게 낫을 손에 넣게 되었습니까?"}}
rows[41065]={title={{21,781510573},"여신의 낫"},description={{866,1631256735},"어둠의 기사들... 그들의 끈질긴 추격은 내가 황혼의 숲에 발을 들여놓는 순간부터 내 존재를 감지하고 빠르게 달려들었다. 도망치는 것은 소용없었다. 그들은 낫의 힘에 굶주려 있었고, 만족할 줄 모르는 욕망이 그들을 쉴 새 없이 앞으로 몰아냈다. 나는 충성스러운 늑대인간 동료들을 불러 모아 내 위치를 굳건히 했지만, 그들의 힘은 압도적이었고, 결국 나는 그들의 어둠의 영향력 아래 쓰러졌다. 마지막 저항으로, 나는 창으로 그들의 심장을 꿰뚫었다. 나의 $B$B희생이 헛되지 않을 것을 알았기에. 아아, 결국 낫은 그 사악한 존재들의 손에 들어간 것 같군. 그들이 낫의 힘으로 세상에 어떤 끔찍한 짓을 저지를지 생각만 해도 몸서리가 쳐진다. 이제 그 유물이 네 손에 있다는 사실이 다행이다. 네가 낫의 본래 목적을 위해 그것을 휘두를 수 있기를 바라기 때문이다. $B$B잠깐. 저 소리 들리나?"},objectives={{22,1811649664},"다크 라이더를 물리치세요."},progress={{21,1152747866},"뭔가 이상해..."},completion={{176,1581043130},"당신도 봤잖아요. 그들은 낫을 되찾을 때까지 멈추지 않을 겁니다. 도망치고 숨어도 소용없어요. 그들은 당신을 찾아낼 겁니다.$B$B하지만 아직 기회는 있습니다."}}
rows[41066]={title={{21,781510573},"여신의 낫"},description={{918,1088900254},"멜탄드리스의 신전에서 낫을 선물 받았습니다. 늑대인간을 소환하는 능력 덕분에 펠우드의 타락과 싸우는 데 큰 도움을 받았죠. 하지만 늑대인간들을 통제할 수 없게 되었습니다. $B$B도움이 필요했습니다. 저는 늑대인간을 소환하는 마법사 아루갈에게 조언을 구하기 위해 애쉬엔베일 숲을 떠났습니다. 엘룬이 그들에게 내린 은총과 이 생명체들 사이의 연관성을 알고 싶었습니다. 하지만… 아루갈이… $B$B죽었다니? 엘룬의 눈물이여, 그 소식은 저를 슬픔에 잠기게 합니다. 지금 이 순간, 우리를 인도할 지혜와 지식을 가진 단 한 사람에게 의지해야 합니다. 저승 세계의 학자인 대드루이드 드림윈드가 우리 세계와 그 너머의 미스터리를 풀 열쇠를 쥐고 있을지도 모릅니다. 그를 찾아가 제게 닥친 일을 이야기해 주십시오. 내가 칼림도르를 떠날 때, 그는 노르드라실을 복구하기 위한 노력의 최전선에 서 있었다."},objectives={{39,1231207918},"노르다나르에서 대드루이드 드림윈드를 찾으세요."},progress={{43,1696853789},"노르다나르에 오신 것을 환영합니다. 무엇을 도와드릴까요?"},completion={{60,178598849},"이것이 바로 벨린데 수녀의 운명입니다. 참으로 비극적인 이야기입니다."}}
rows[41067]={title={{21,781510573},"여신의 낫"},description={{936,711033530},"워겐이라는 이름은 역사의 메아리를 통해 울려 퍼지며 고대의 기억을 불러일으킵니다. 수억 년 전, 아즈샤라 여왕의 통치 시대에 그녀의 마법사들은 금지된 마법을 탐구하여 필멸자의 이해를 초월하는 영역으로 통하는 $B$B차원문을 열었습니다. 불타는 군단의 세계, 에메랄드 불꽃에 휩싸인 세계, 절대적인 추위의 세계, 상상할 $B$B수 없는 어둠의 세계. 그중 하나가 바로 피의 세계, 보르겐도르였습니다. 그곳에 얽힌 지식은 오래전에 사라져 잊혀진 전설 속에 묻혀버렸습니다. 그럴 만한$B$B 이유가 있었겠죠. 하지만 저의 깊은 고대 지혜 속에서 저는 여러분을 지식의 등불로 인도할 수 있습니다. 우르라는 이름의 인간 마법사는 이 불가사의한 영역을 연구하는 데 헌신했습니다. 그는 보르겐도르에 대한 이해와 탐구를 담은 고서를 남겼다고 전해집니다. 달라란의 마법사들이 더 이상 이 귀중한 책을 소유하고 있지 않다면, 네파리우스 경의 방대한 서재에서 찾을 수 있을 거라고 생각합니다."},objectives={{89,1439223082},"빅터 네파리우스 경에게서 \"보르겐도르: 피의 차원 신화\" 사본을 받아오십시오."},progress={{4,273767400},"예?"},completion={{228,328701331},"몇 페이지밖에 온전하게 남아있지 않은 것 같습니다. 안타깝네요. 이 상태로는 책을 쓸 수 없을 테니까요.$B$B이런 책이 보관되어 있을 만한 다른 장소가 하나 더 있는데, 수년 동안 아무도 발을 들여놓지 않았습니다. 카라잔 도서관…"}}
rows[41068]={title={{23,1915232683},"보라 연꽃 수집"},progress={{316,1700024279},"$c님, 혹시 좋은 결과 있으셨나요?"},completion={{111,1078390207},"음, 모든 게 괜찮아 보이네요. 저희를 도와주셔서 정말 감사합니다. 자, 이거 받으세요."}}
rows[41069]={title={{22,1351520294},"검은 연꽃 수집"},progress={{294,2116314133},"$c님, 혹시 좋은 결과 있으셨나요?"},completion={{111,1078390207},"음, 모든 게 괜찮아 보이네요. 저희를 도와주셔서 정말 감사합니다. 자, 이거 받으세요."}}
rows[41070]={title={{19,1847855458},"신성하지 않은 가지"},description={{809,261459161},"자연의 타락이 가져올 수 있는 파괴를 저는 목격했습니다. 펠우드는 그 진실을 여실히 보여주는 곳입니다. 하지만 이곳 숲속 공터는 여전히 순수하며, 이는 모두 에트위르 덕분입니다. $B$B(드루이드는 잠시 고개를 숙이고 경건한 표정으로 말을 멈췄다가 다시 말을 이어갔다.$B$B) 하지만 그의 희생은 그와 가장 가까운 이들만을 감동시켰습니다. 우리는 펠우드의 타락을 정화하는 일을 계속함으로써 그의 유산을 기려야$B$B 합니다. 이 숲의 남서쪽 끝자락에는 아름다움과 어둠이 공존하는 고대의 공터가 있습니다. 그곳에서 당신은 미쳐 날뛰는 트렌트들의 가슴 아픈 광경을 마주하게 될 것입니다. 쓰러진 트렌트들의 시체에서$B$B 그들의 고통으로 더럽혀진 나뭇가지 여섯 개를 가져오십시오. 비록 더럽혀졌을지 모르지만, 이 나뭇가지들은 잠재된 힘을 지니고 있습니다. 그것들을 제게 가져오십시오. 그러면 우리는 그들의 타락한 본질에 새로운 생명을 불어넣을 것입니다."},objectives={{71,19839817},"펠우드에 있는 탈론브랜치 글레이드의 탈로라스에게 불경스러운 나뭇가지 6개를 가져다 주세요."},progress={{365,462958730},"철목 숲의 험준한 깊은 곳으로 들어가는 것을 금지한 요한의 엄격한 명령에도 불구하고, 운명은 뜻밖에도 외부인인 당신을 우리의 조력자로 불러들였습니다. 우리 땅의 법에 얽매인 요한의 힘은 우리의 전통에 얽매이지 않은 자 앞에서는 약해집니다. 하지만 조심하십시오. 그의 예리한 눈길이 여전히 우리의 행동을 주시하고 있을지도 모릅니다."},completion={{122,1890472529},"당신의 자비로운 행동은 아이언트리 숲에서 고통받는 트렌트 영혼들에게 위안을 주었습니다. 그 점에 대해 저는 영원히 감사할 것입니다."}}
rows[41071]={title={{22,1308820061},"부패를 감내하다"},description={{663,1496152289},"곰이라니! 야생에서 어떤 생물이 그 위엄과 위용에 견줄 수 있겠는가? 우리 드루이드들이 오랫동안 이 모습을 숭배해 왔고, 우르속과 우르솔의 축복을 직접 받아 온 것은 결코 우연이 $B$B아니다. 하지만 이 고귀한 생물들이 숲을 휩쓰는 악마의 타락에 굴복하는 것을 보는 것은 내 마음을 몹시 아프게 한다. 에트위르의 숭고한 희생에도 불구하고, 우리가 그들을 치료하려는 시도는 오히려 이 불쌍한 짐승들에게 더 큰 고통만을$B$B 안겨준 것 같다. 그러므로 간청하노니, 숲으로 들어가 이 땅을 삶의 터전으로 삼는 스무 마리 곰들의 고통을 끝내주시오. 쉬운 일은 아니겠지만, 자연을 위해 반드시 해내시오."},objectives={{66,1114114285},"펠우드에서 후드 쓴 골하인을 위해 앵거클로 회색곰 20마리를 처치하세요."},progress={{40,1858454605},"당신은 이 숲에 평화를 가져왔습니까?"},completion={{483,681826398},"저는 이 암흑기에 잃어버린 생명체들의 영혼이 에메랄드 드림으로 돌아갔다는 믿음에서 위안을 얻습니다. 그곳에서 그들은 우리 세계의 자연적 균형을 지켜보는 위대한 곰 정령 우르속과 우르솔과 함께 자유롭고 평화롭게 거닐고 있을 것입니다.$B$B이 땅의 현재 상태와 발생한 고통에도 불구하고, 저는 시간이 흐르면 ​​상처가 아물고 숲이 다시 조화롭고 평온한 곳이 될 것이라는 희망을 놓지 않습니다."}}
rows[41072]={title={{29,1162887865},"파수꾼의 갑작스러운 의심"},description={"Ishnu-alah, $c. What a favorable event meeting you here. I was sent to Felwood to guard the Talonbranch Glade. However, druid Wildwalker sent me away. I suspect he believes me to be a spy. Ironically, he has now made me into one.$B$BI would like to know why he would object to being guarded, and sending another sentinel would give my concealed intentions away. Would you speak to Wildwalker and find out what is going on? Return to me once you have identified the intentions of his superiors.","이슈누알라, $c. 여기서 당신을 만나게 되어 정말 기쁩니다. 저는 펠우드의 탈론브랜치 숲을 지키라는 명령을 받고 파견되었는데, 드루이드 와일드워커가 저를 돌려보냈습니다. 제가 스파이라고 생각하는 것 같습니다. 아이러니하게도, 이제 그는 저를$B$B 스파이로 만들어 버렸습니다. I는 와일드워커가 왜 경호를 거부하는지 알고 싶어 합니다. 또 다른 경비병을 보내면 제 숨겨진 의도가 탄로 날 테니까요. 와일드워커와 이야기해서 무슨 일이 벌어지고 있는지 알아봐 주시겠습니까? 그의 상관의 의도를 파악하면 저에게 돌아오십시오."},objectives={{82,332724419},"펠우드의 탈론브랜치 글레이드에 있는 드루이드 요한 와일드워커에게 당신의 능력을 제공하세요."},progress={"Yes, $r?","예,$r?"},completion={{40,1365807020},"당신을 활용할 수 있는 방법이 있을 것 같네요."}}
rows[41073]={title={{14,1625448272},"특별 임무"},description={{766,174077277},"자연의 신비를 탐구하고 숲의 균형을 지키는 것은 제 임무입니다. 하지만 이번 임무는 지금까지 실패로 돌아갔고, 이는 저를 분노와 좌절로 가득 채웠습니다. 남서쪽에 있는 고대의 숲은$B$B 한때 생명으로 가득 차 있었지만, 이제는 죽어 생명력을 잃었습니다. 에트위르의 희생과는 달리, 그들의 희생은 헛되었습니다. 에트위르는 이 정착지의 부패를 정화할 수 있었습니다. 저는 그 이유를 알아야 $B$B합니다. 우리 편인 말로니아스 섀드문이 그 숲을 조사하기 위해 파견되었습니다. 하지만 그는 아직 돌아오지 않았고, 그의 게으른 성격을 아는 이상, 아마도 임무를 회피할 새로운 방법을 찾고 있을 것입니다. $B$B그를 찾아내어 그의 책임을 상기시켜 주십시오. 그는 완수해야 할 임무가 있으며, 저는 그의 태만을 용납하지 않을 것입니다."},objectives={{100,868089045},"말로니아스 섀드문을 찾아라. 그는 아이언트리 숲에 있는 고대의 숲을 조사하기 위해 파견되었다."},progress={{30,1694824434},"이 고통은… 견딜 수가 없어…"},completion={{86,186497201},"제발, 저를 도와주세요... 퍼볼그 무리의 습격을 받았어요. 요한을 실망시킬 순 없어요..."}}
rows[41074]={title={{16,263131193},"도난당한 노트"},description={{924,1237940669},"잠시 마음을 추스르겠습니다. $B$B(드루이드는 잠시 말을 멈추고 집중하려 애썼다. 부상이 그에게 영향을 미치고$B$B 있는 것이 분명했다.) \"내 상처는 신경 쓰지 마라. 시간이 지나면 나을 것이다. 잘 들어라. 나를 공격한 퍼볼그들은 나에게 상처를 입혔을 뿐만 아니라 내 소중한 노트까지 훔쳐갔다. 나는 그것들을 되찾아야 하지만, 지금은 내 상태가 좋지 않아 그럴 수 없다. 요한이 여기서 일어난 일을 알게 되는 것은 절대 안 된다. 알겠나? 내가 노트를 $B$B잃어버렸다는 사실은 절대 요한에게 말하지 마라. \"이 공격을 감행한 퍼볼그들을 찾아라. 나는 그들이 동쪽으로 도망치는 것을 보았고, 아직 그 지역에 진을 치고 있을지도 모른다. 내 노트를 되찾는 대로 지체 없이 요한에게 전해다오. 절대로 읽지 말아라. 우리 기사단만이 알 수 있는$B$B 지식이 담겨 있다. \"요한이 내 안부를 물으면 곧 돌아오겠지만, 아직 연구가 좀 남았다고 전해다오. 네 판단력을 믿노라.\""},objectives={{44,2085236328},"말로니아스의 메모를 요한 와일드워커에게 돌려주어야 합니다."},progress={{18,1184033356},"말로니아스는 어디 있죠?"},completion={{408,1741460202},"그가 그 메모들을 당신에게 맡겼다고요?$B$B<요한이 당신 손에서 메모를 낚아채 급히 읽는다>$B$B세나리온 의회을 위해 진행한 귀중한 연구 자료를 이렇게 부주의하게 다룰 줄은 정말 놀랍군요. 숲속을 헤매던 낯선 사람에게 맡기다니… 우리 단체의 일원이 되기에 필요한 분별력과 전문성이 전혀 없는 게 분명합니다.$B$B가도 좋다. 도와줘서 고맙다."}}
rows[41075]={title={{22,582625752},"펠우드 음모"},description={{936,1802062731},"당신은 페이지들을 꼼꼼히 살펴보며, 특이한 점이나 악의적인 의도가 있는지 각 줄을 살핍니다. 처음에는 대부분의$B$B 메모가 트렌트의 마법적 속성에 대한 상세하고 광범위한 연구처럼 보입니다. 고대 숲이 굴단의 해골에 의해 어떻게 더럽혀졌는지, 그리고 그 타락시키는 힘이 고대인들이 숲을 구하기 위해 필사적으로 노력했던 것과는 비교할 수 없을 정도로 강력했는지에 대한 내용이$B$B 담겨 있습니다. 하지만 메모의 마지막 몇 페이지에 다다르자, 내용이 특히 불안해집니다. 에트위르의 희생이 비극이 아니라 오히려 자신들의 이익을 위해 이용될 수 있다는 내용이 적혀 $B$B있습니다. 메모 작성자는 트렌트의 죽음으로 주변 식물이 전례 없이 성장했으며, 이 성장을 이용하면 아무런 의심도 사지 않고 엄청난 양의 모로우그레인을 얻을 수 있다고 주장합니다. 파수꾼 브리아리엘이 이 이야기를$B$B 듣고 싶어 할 겁니다. 당신은 조심스럽게 그 페이지를 찢어냅니다."},objectives={{45,2020141469},"찢어낸 페이지를 센티넬 브리아리엘에게 가져오세요."},progress={{68,583605483},"돌아왔군요! 탈론브랜치 숲에서 뭐 찾은 게 있나요?"},completion={{547,2123537731},"모로우그레인? 네, 들어본 적이 있습니다.$B$B하지만 그저 소문에 불과하다고 생각했죠. 그러나 이 신비로운 식물에는 뭔가 숨겨진 비밀이 있는 것 같습니다.$B$B대드루이드 스태그헬름이 수년 동안 엄청난 양의 모로우그레인을 모아왔다는 소문이 들립니다. 어떤 이들은 그 식물에 불길한 기운이 있으며, 그가 무슨 어두운 계획을 꾸미고 있다고 말합니다.$B$B이 일을 무시할 수는 없습니다. 너무 늦기 전에 진상을 밝혀내야 합니다. 스태그헬름에게 사악한 계획이 있다면, 세나리온 의회 전체가 위험에 처할 수 있습니다."}}
rows[41076]={title={{17,1786507893},"펠우드의 모로우"},description={{957,1433940753},"와일드워커에게 쪽지를 보여주는 건 소용없습니다. 쪽지에는 펠우드에서 모로우그레인이 실제로 사용되었다는 구체적인 증거가 전혀 없으니까요. 지금으로서는 전부 추측일 뿐입니다. 만약 $B$B드루이드들이 펠우드에 모로우그레인 씨앗을 가져왔다면 분명 잘 숨겨뒀을 겁니다. 하지만 저는 이 지역의 새들이 이 미스터리의 열쇠를 쥐고 있을지도 모른다고 생각합니다. 이$B$B 땅의 올빼미들은 살아남기 위해 온갖 수단을 동원해야 했습니다. 드루이드들이 펠우드에 모로우그레인 씨앗을 가져왔다면, 올빼미들이 먹이로 일부를 훔쳐 먹었을 수도 $B$B있습니다. 썩 유쾌한 생각은 아니지만, 어쩌면 이것이 유일한 희망일지도 모릅니다. 우리는 지역 새들의 내장을 뒤져 모로우그레인 씨앗의 흔적을 찾아야 합니다. 쪽지에 따르면 씨앗은 붉은색을 띤다고 합니다. 만약 씨앗을 발견하면 즉시 제게 가져오십시오. 쉽지는 않겠지만, 이 불가사의한 식물과 대드루이드 스태그헬름이 그 식물에 집착하는 이유에 숨겨진 진실을 밝히려면 감수해야 할 위험입니다."},objectives={{58,1498999124},"펠우드 올빼미의 장에서 모로우그레인 씨앗을 찾아보세요."},progress={{59,982743030},"불쌍한 올빼미들. 혹시 모로우그레인 씨앗은 찾으셨나요?"},completion={{10,547311302},"그럴 줄 알았어."}}
rows[41077]={title={{31,828623392},"파수꾼의 정당한 의심"},description={{218,336295848},"쪽지와 씨앗을 샨드리스 페더문에게 가져다 주세요. 그녀는 파수꾼 군대의 총사령관이며, 앞으로 어떻게 해야 할지 알고 있을 겁니다. 아, 그리고 제가 도와줬다는 사실도 꼭 말씀해 주세요."},objectives={{71,1177171055},"씨앗과 쪽지를 페더문 요새에 있는 샨드리스에게 가져다 주세요."},progress={{4,273767400},"예?"},completion={{882,115500708},"<샨드리스는 메모를 훑어보고 모로우그레인 씨앗을 살펴보았다.>$B$B당신의 우려는 충분히 이해하지만, 이 문제는 신중하게 접근해야 합니다. 세나리온 의회은 오랫동안 우리의 동맹이었으며, 그들의 임무는 우리 세계의 자연적 균형을 보호하고 보존하는 것입니다. 그들의 방식이 우리 외부인에게는 불가사의하게 보일지 모르지만, 우리는 그들이 최선의 의도를 가지고 있다고 믿어야 합니다. 저는 파수꾼 브리아리엘이 조금… 지나치게 열성적인 것 같다는 생각이 듭니다.$B$B게다가, 우리에게는 더 큰 위협이 다가오고 있다는 사실을 잊어서는 안 됩니다. 호드가 우리 땅을 침범하고 있고, 파수꾼의 반란까지 일어났으며, 우리는 더 이상의 내부 분쟁에 휘둘릴 여유가 없습니다. 우리의 자원과 관심은 우리의 고향과 백성을 지키는 데 집중되어야 합니다.$B$B죄송하지만, 이것만으로는 충분하지 않습니다. 현재로서는 탈론브랜치의 드루이드들은 평화롭게 연구를 진행할 수 있습니다."}}
rows[41078]={title={{26,1237321405},"교회에 대한 기부"},description={{518,734096068},"당신이 원하는 것이 무엇입니까? 신성함입니까, 아니면 위대한 지식입니까? 여기서는 그런 것들을 찾을 수 없을 겁니다. 마법사 메디브의 강력한 마법 때문에 저와 제 무리는 영원히 떠도는 고통의 $B$B삶을 살게 되었으니까요. 우리는 갇혀서 생을 마감한 곳을 영원히 방황해야 합니다. 하지만 저승으로 넘어갈 가능성은 있습니다. 그러려면 엄청난 양의 마법 에너지가 필요하죠. $B$B만약 당신이 마법 재료를 모아준다면, 예전에 제가 유명했던 소환술을 당신에게 보여드릴 수 있습니다. 괜찮은 제안 같습니까?"},objectives={{129,652469264},"카라잔 외곽의 교회에서 대사제 네르세우스에게 마법 정수 15개, 환영 가루 20개, 상급 영원 정수 10개를 모으십시오."},progress={{51,728230},"내 기운이 남아있는데, 재료는 가져왔나요?"},completion={{143,1299321270},"저는 이런 물품들을 받을 거라고는 전혀 예상하지 못했습니다. 카라잔 주변에서는 아무도 도움을 주겠다고 나서지 않았거든요. 당신의 너그러움은 결코 헛되지 않을 것입니다."}}
rows[41079]={title={{24,705628115},"파괴의 기원"},description={{677,298067507},"과거에 수많은 위대한 사제들이 빛을 소환하고 강력한 마법을 부여하는 능력으로 '대주교'라는 칭호를 얻었습니다. 이 기술은 극히 어렵고, 오직 한 명의 스승에서 뛰어난 제자에게만 전수됩니다. 시간이 흐르면서 대주교의 수는 줄어들었고, 그와 함께 과거의 소환술도 역사의 한 페이지로 사라져 버렸습니다. 당신의 숭고한 희생에 보답하기 위해 저는 $B$B당신에게 그러한 소환술을 제공할 수 있지만, 희귀한 재료가 필요합니다. 제 힘이 약해져서 과충전된 레이 에너지 하나가 필요합니다. 이 에너지는 카라잔의 탑에서 찾을 수 있습니다. 하나를 가져다주시면 당신이 원하는 소환술을 제공해 드리겠습니다."},objectives={{108,1336802070},"카라잔 외곽의 교회에서 대사제 네르세우스에게 과충전된 레이 에너지와 마법 정수 6개를 모으세요."},progress={{33,1041854780},"지맥 에너지를 모으셨나요?"},completion={{65,707788982},"이 기도가 당신에게 악을 물리칠 힘을 주기를 바랍니다."}}
rows[41080]={title={{32,890195316},"더욱 강력한 보호를 위한 기원"},description={{677,298067507},"과거에 수많은 위대한 사제들이 빛을 소환하고 강력한 마법을 부여하는 능력으로 '대주교'라는 칭호를 얻었습니다. 이 기술은 극히 어렵고, 오직 한 명의 스승에서 뛰어난 제자에게만 전수됩니다. 시간이 흐르면서 대주교의 수는 줄어들었고, 그와 함께 과거의 소환술도 역사의 한 페이지로 사라져 버렸습니다. 당신의 숭고한 희생에 보답하기 위해 저는 $B$B당신에게 그러한 소환술을 제공할 수 있지만, 희귀한 재료가 필요합니다. 제 힘이 약해져서 과충전된 레이 에너지 하나가 필요합니다. 이 에너지는 카라잔의 탑에서 찾을 수 있습니다. 하나를 가져다주시면 당신이 원하는 소환술을 제공해 드리겠습니다."},objectives={{108,1336802070},"카라잔 외곽의 교회에서 대사제 네르세우스에게 과충전된 레이 에너지와 마법 정수 6개를 모으세요."},progress={{33,1041854780},"지맥 에너지를 모으셨나요?"},completion={{65,707788982},"이 기도가 당신에게 악을 물리칠 힘을 주기를 바랍니다."}}
rows[41081]={title={{28,2074783172},"확장된 마음의 기원"},description={{677,298067507},"과거에 수많은 위대한 사제들이 빛을 소환하고 강력한 마법을 부여하는 능력으로 '대주교'라는 칭호를 얻었습니다. 이 기술은 극히 어렵고, 오직 한 명의 스승에서 뛰어난 제자에게만 전수됩니다. 시간이 흐르면서 대주교의 수는 줄어들었고, 그와 함께 과거의 소환술도 역사의 한 페이지로 사라져 버렸습니다. 당신의 숭고한 희생에 보답하기 위해 저는 $B$B당신에게 그러한 소환술을 제공할 수 있지만, 희귀한 재료가 필요합니다. 제 힘이 약해져서 과충전된 레이 에너지 하나가 필요합니다. 이 에너지는 카라잔의 탑에서 찾을 수 있습니다. 하나를 가져다주시면 당신이 원하는 소환술을 제공해 드리겠습니다."},objectives={{108,1336802070},"카라잔 외곽의 교회에서 대사제 네르세우스에게 과충전된 레이 에너지와 마법 정수 6개를 모으세요."},progress={{33,1041854780},"지맥 에너지를 모으셨나요?"},completion={{65,707788982},"이 기도가 당신에게 악을 물리칠 힘을 주기를 바랍니다."}}
rows[41082]={title={{38,951414810},"상급 마법적 강인함의 소환"},description={{677,298067507},"과거에 수많은 위대한 사제들이 빛을 소환하고 강력한 마법을 부여하는 능력으로 '대주교'라는 칭호를 얻었습니다. 이 기술은 극히 어렵고, 오직 한 명의 스승에서 뛰어난 제자에게만 전수됩니다. 시간이 흐르면서 대주교의 수는 줄어들었고, 그와 함께 과거의 소환술도 역사의 한 페이지로 사라져 버렸습니다. 당신의 숭고한 희생에 보답하기 위해 저는 $B$B당신에게 그러한 소환술을 제공할 수 있지만, 희귀한 재료가 필요합니다. 제 힘이 약해져서 과충전된 레이 에너지 하나가 필요합니다. 이 에너지는 카라잔의 탑에서 찾을 수 있습니다. 하나를 가져다주시면 당신이 원하는 소환술을 제공해 드리겠습니다."},objectives={{108,1336802070},"카라잔 외곽의 교회에서 대사제 네르세우스에게 과충전된 레이 에너지와 마법 정수 6개를 모으세요."},progress={{33,1041854780},"지맥 에너지를 모으셨나요?"},completion={{65,707788982},"이 기도가 당신에게 악을 물리칠 힘을 주기를 바랍니다."}}
rows[41083]={title={{22,1759291402},"적합한 숙소"},description={{403,1045421014},"저기, 이봐요!$B$B 여기 룸서비스는 정말 끔찍하네요. 마치 몇 년째 누군가 와서 제 문제를 해결해 주기를 기다리는 $B$B기분이에요. 배정받은 방도 마음에 안 들고, 잠도 제대로 못 자겠어요. 좀 더 편안한 베개라도 주세요. 그래야 여기서 편히 쉴 수 있을 것 같아요."},objectives={{61,2039265358},"카라잔에서 카일슨 시의원을 위한 편안한 베개를 찾아주세요."},progress={{163,1896096488},"이게 얼마나 심각한 문제인지 모르겠어? 빨리 안 하면 네 상사한테 네가 얼마나 일을 엉망으로 하는지 다 일러바칠 거야.$B$B어서 시작해!"},completion={{181,1871205009},"아, 드디어. 밤에 머리를 댈 곳이 생겼네. 푹 잔 게 언제였는지 기억도 안 나네... 이상하게도 잠든 게 언제였는지조차 기억이 안 나."}}
rows[41084]={title={{16,1724267468},"잠들기 위한 한 잔"},description={{281,1068670892},"이걸 구하는 데 정말 큰 도움을 주셨지만, 이제 좀 쉬기 전에 마지막으로 한 가지만 더 부탁드려도 될까요? 가지고 계신 와인 중에서 제일 좋은 걸로 한 잔 가져다 주시겠어요? 무슨 말인지 정확히 아시겠죠? 자, 어서 제가 찾는 걸 가져다 주시면 편히 잠들 수 있을 것 같습니다."},objectives={{75,1740658966},"카일슨 시의원을 위해 와인을 구할 수 있는 방법을 아는 사람과 이야기해 보세요."},progress={{15,159386007},"도와드릴까요?"},completion={{261,1218298555},"와인을 찾으시나요?$B$B<요리사가 작게 웃음을 터뜨린다.>$B$B어떤 영혼들은 자신들이 처한 곤경을 깨닫지 못하고 있습니다. 사실, 많은 영혼들은 여전히 ​​자신이 살아 있다고 믿으며, 운명이 닥치기 전날 밤처럼 이 복도를 걷고 있습니다."}}
rows[41085]={title={{13,1427270049},"스펙트럴 와인"},description={{446,606623648},"믿기 ​​어렵겠지만, 저는 유령 와인 제조법을 가지고 있습니다. 영혼이 마실 수 있는 와인이라는 개념을 연구하고 다듬어 왔죠. 제조 과정이 다소 복잡하고 카라잔에서는 구하기 어려운 재료들이 필요합니다. 죽음의 정수$B$B 세 개, 포도주 다섯 병, 그리고 유령 버섯 하나를 구해다 주시면 카일슨 의원을 위해 유령 와인을 만들어 드릴 수 있습니다. 하지만 이렇게까지 수고를 하시는 걸 보니 제정신이신지 의심스럽군요."},objectives={{90,1394884888},"카라잔에 있는 요리사를 위해 죽음의 정수 3개, 포도주 5병, 유령버섯 1개를 모으세요."},progress={{15,150644083},"다 챙겼어?"},completion={{66,1357187338},"저는 이 공식을 사용하게 될 거라고는 상상도 못 했는데, 이렇게 사용하게 됐네요."}}
rows[41086]={title={{16,1194517283},"카일슨을 위한 와인"},description={{301,1256697139},"당신을 위해 스펙트럴 와인을 준비했습니다. 여기 있습니다. 카일슨 의원이 당신의 노고에 대한 보답으로 무언가를 제안하길 바랍니다. 어서 그에게 가져다 주십시오. 시간을 낭비하지 마십시오. 몇 년 후에는 스펙트럴 와인의 마법적인 효능이 사라지고 평범한 와인이 될지도 모릅니다."},objectives={{60,1905859608},"스펙트럴 와인을 카라잔에 있는 카일슨 시의원에게 전달하세요."},progress={{48,2038112694},"그래서, 내가 부탁한 와인 가져왔어?"},completion={{606,787832410},"<카일슨 의원은 스펙트럴 와인을 한 모금 마시고는 잠시 음미하며 멍한 표정을 짓는다.>$B$B정말 훌륭한 와인이로군. 몇 년 만에 이렇게 갈증을 해소해 주는 와인은 처음이야. 정말이지, 아주 오랫만에 맛보는 최고의 와인이로다. 카라잔에서 나를 극진히 대접해 주셔서 정말 고맙네.$B$B이렇게 훌륭한 하인이시니 카라잔에서 크게 성공하실 거야. 그러니 팁은 아낌없이 드려야지.$B$B<카일슨은 당신의 주머니에 동전 하나를 넣어준다.>$B$B이렇게 귀한 돈을 한 번에 다 쓰지 마시오. 필요한 게 있으면 언제든 말해 주시오."}}
rows[41087]={title={{21,781510573},"여신의 낫"},description={{757,1626961775},"고대 전설의 속삭임 속에는 수호자들의 심오한 지혜가 한때 안전하게 보관되었던 성스러운 안식처, 메디브의 탑 꼭대기에 대한 이야기가 펼쳐집니다. 하지만 세월의 흐름 속에 이 성소로 향하는 통로는 사라졌고, 탑은 이제 폐허로 남아 있습니다. 탑 꼭대기에 자리 잡은 도서관은 인간의 손이 닿지 않도록 $B$B봉인되었습니다. 그러나 운명의 흐름 속에서도 어둠 속에는 희망이 빛나고 있습니다. 만약 당신이 상층 카라잔을 둘러싼 장벽을 뚫을 수 있다면, 그 깊숙한 곳에 손대지 않은 귀중한 책이 있을지도 모릅니다. 당신이 찾는 비밀은 시간의 흐름 속에 감춰진 채, 당신처럼 굳은 의지를 가진 탐구자를 기다리고 있을지도 모릅니다."},objectives={{83,1295288891},"어퍼 카라잔에서 \"보르겐도르: 피의 차원 신화\" 사본을 가져오세요."},progress={{51,194190276},"카라잔 탑은 데드윈드 패스 위로 우뚝 솟아 있다."},completion={{470,1029282589},"우르의 일생이 우리 눈앞에 펼쳐지는 것을 목격하는 것은 참으로 특별한 선물입니다. 세월의 흔적이 묻어나는 이 책에는 그 본질이 대부분 온전히 남아 있어, 잊혀진 지식의 귀중한 보물과도 같습니다.$B$B이제 이 고대의 페이지 속으로 들어가, 세월의 흔적이 묻어나는 지혜를 품어봅시다. 보르겐도르의 비밀, 워겐의 신비, 그리고 우리 세계 너머의 진실이 우리 앞에 드러날지도 모릅니다. 그리고 무엇보다 중요한 것은, 낫의 비밀이 밝혀질 것입니다."}}
rows[41088]={title={{16,785072704},"수상한 식물"},description={{436,598454932},"안녕하세요, 여행자님! 정상으로 올라가시는 중이신가요? 악마들을 몰래 지나치시다니 정말 용감하시겠어요. 죄송하지만, 잠깐 도와주실 수 있을까요? 부탁드려요.$B$B 식물들이 고통스럽게 울부짖는 소리가 들려요. 뭔가 문제가 있는 것 같아요. 제가 나무들과 이야기하는 동안 살펴볼 수 있도록 이 근처에서 몇 개 $B$B따주시겠어요? 뿌리째 조심스럽게 땅에서 뽑아주세요. 나중에 다시 제자리에 돌려놓겠습니다!"},objectives={{67,741847965},"하이잘 식물 표본 8개를 모아서 파엘린델라로 가져오세요."},progress={{47,391545723},"자, 성공하셨나요? 제발 알려주세요! 정말 중요해요."},completion={{207,570884648},"고마워요! 어디 보자… 어머나! 이 식물들 중 일부는 오염된 것 같은데, 오염은 뿌리에서 시작된 것 같아요!$B$B이건 심각한데, 당신의 도움이 절실히 필요해요! 자, 이 반짝이는 것들을 가져가세요. 도와주시면 더 많이 구해드릴게요!"}}
rows[41090]={title={{17,967894240},"악마의 서신"},description={"The foul demons are mustering their strength, performing obscene rituals for some dark purpose I shudder to imagine. I am certain these Succubi are receiving some form of direction from their commanders, so it stands to reason that documented orders must be among them.$B$BIt is imperative that we acquire whatever plans we can find, and so I rely upon you, $N. Slay those vile temptresses until you find their orders, then return them to me promptly!","사악한 악마들이 힘을 모아 음란한 의식을 행하고 있는데, 그 목적은 상상하기도 끔찍합니다. 이 서큐버스들이 지휘관으로부터 어떤 지시를 받고 있는 것이 분명하니, 그들 사이에 문서로 된 명령서가 있을 겁니다. 우리가 찾을 수 있는 $B$B모든 계획서를 확보하는 것이 무엇보다 중요하니, 자네에게 부탁하네, N.$N 저 사악한 유혹자들을 처치하고 명령서를 찾아내어 신속히 내게 가져오게 하네!"},objectives={{64,1292501839},"악마의 서신을 모아서 하이잘에 있는 멜라나스트라자에게 돌아가십시오."},progress={{16,1240083400},"찾으셨나요?"},completion={{162,432911919},"정말 잘했어요! 뭔가 이상하다고 생각했죠. 이걸 어떻게 받았죠? 악마 언어로 되어 있어서 번역하려면 도움이 필요할 거예요. 하지만 지금까지는 아주 잘했어요!"}}
rows[41091]={title={{22,52628186},"악마 사냥꾼 찾기"},description={{543,215818793},"이 서신을 번역하는 것은 적의 음모를 파악하는 데 중요할 뿐만 아니라, 그들이 이 서신을 어떻게 접하고 있는지 알아내는 데에도 필수적입니다. I는 우리를 $B$B도울 수 있는 가장 적합한 자는 악마 사냥꾼이라고 생각합니다. 그들은 악마의 힘을 받아들이고 악마와 싸우겠다고 맹세한 나이트 엘프입니다. 이곳에서는 환영받지 못하지만, 그럼에도 불구하고 그들은 어떤 비난을 받더라도 악마의 대의에 헌신하고 있습니다.$B$B  최근 니레미우스 다크윈드라는 자가 펠우드 북부에서 목격되었다는 소식을 들었습니다. 그를 찾아 이 서신을 보여주십시오."},objectives={{60,1192885500},"니레미우스 다크윈드를 찾아가 악마의 서신을 보여주십시오."},progress={{25,817381712},"당신은 나에게 무엇을 원하는 겁니까?"},completion={{144,847228328},"하이잘에 악마가 있다고? 그 서신을 보여줘 봐!$B$B<그는 내용을 잠깐 훑어보고 고개를 흔든다>$B$B암호화되어 있어. 암호가 필요해."}}
rows[41092]={title={{17,742726926},"찾기 힘든 자판"},description={{477,26826506},"산을 오를 만큼 민첩하고 순찰대의 눈을 피해 숨을 만큼 은밀한 악마는 오직 임프뿐입니다. 이 임프는 자판이라는 이름으로 $B$B불리며, 암호를 가지고 있습니다. 이 잡기 힘든 생물은 여러 번 제 손아귀에서 벗어났습니다. 혹시 당신이라면 펠우드에서 이 생물을 찾아낼 수 있을지도 모릅니다. 저는 펠우드 폭포 $B$B근처에서 이 임프를 자주 목격했습니다. 그곳부터 확인해 보시는 게 좋겠습니다.$B$B 자판에게서 암호를 되찾아 제게 가져오십시오."},objectives={{54,869966889},"펠우드에 있는 임프 자판에게서 암호 룬을 되찾으세요."},progress={{59,1392195973},"암호를 찾았나요? 암호를 찾지 못하면 돌아오지 마세요."},completion={"Well done, now I will use this cipher with the letter and we will know more. <Niremius takes his time inspecting the letter.>$B$BThis is troubling news indeed. I have a task for you $c.","잘했어. 이제 이 암호를 편지에 적용하면 더 많은 것을 알 수 있겠지. <니레미우스는 편지를 꼼꼼히 살펴본다.>$B$B정말 걱정스러운 소식이군. 자네에게 임무가 하나 있네.$c"}}
rows[41093]={title={{10,1594624126},"교도소장"},description={{594,913663668},"분화구 안의 악마들은 주의를 분산시키기 위한 미끼입니다. 그들은 하이잘의 군대를 교란시키기 위한 공격을 준비하고 있습니다. 그들은 선봉대일 뿐이고, 주력 악마들은 아르키몬드의 집결지인 다크위스퍼 협곡에 있습니다. 비록$B$B 사이가 좋지는 않지만, 저는 그곳에서 악마들을 소탕하고 있는 사람을 알고 있습니다. 감시자 키리 스타스토커를 찾아 무슨 일이 있었는지 알리고 그녀와 협력하여 이 일을 막으십시오. 저는 악마들의 진짜 목적이 무엇인지 조사하겠습니다. 그녀에게 이 서신 사본을$B$B 전해주세요. 또한, 그곳의 악마들을 상대하려면 도움이 필요할 겁니다. 그들은 만만치 않습니다."},objectives={{43,1962057988},"다크위스퍼 협곡에서 키리 스타스토커를 찾으세요."},progress={{17,2037304073},"무엇을 원하세요?"},completion={{227,1206760156},"니레미우스가 당신을 보냈습니까? 저는 그와 같은 부류를 좋아하지 않지만, 그가 악마들을 처치하는 한, 그의 잘못에도 불구하고 그의 존재를 용인하겠습니다. 그가 당신을 제게 보냈다면 분명 타당한 이유가 있었겠죠. 저 쪽지는 무엇입니까?"}}
rows[41094]={title={{19,1404842056},"다크위스퍼 소탕"},description={{460,2140368829},"<키리는 편지를 잠깐 읽고 고개를 끄덕였다> $B$B\"알겠습니다.$B$B 당신의 이야기가 상황을 파악하는 데 도움이 되는군요. 이제 이 악마들을 소탕할 때입니다. 그들은 이미 처형일을 훨씬 $B$B넘겼습니다. 주력 부대를 제거해 주시길 바랍니다. 혼자 감당하기 힘들다면 동료들을 데려오세요. 트락날과도 이야기를 나눠보세요. 그도 당신에게 맡길 일이 있을지도 모릅니다.$B$B 우리의 혈통과 신념은 다를지 몰라도, 하이잘을 지키겠다는 우리의 의지는 같습니다.\""},objectives={{67,1625828107},"다크위스퍼 협곡에서 헤데린 슬레이어 12마리를 처치하여 키리 스타스토커를 획득하세요."},progress={{11,56490833},"다 됐나요?"},completion={{77,1623702245},"잘했어. 여기서 우리가 물리치는 악마 하나하나는 적의 공격에 맞서는 악마의 수를 줄이는 것을 의미해."}}
rows[41095]={title={{22,2035897041},"섀도투스를 구하다"},description={{658,1200036212},"월요일, 악마와는 상관없는 문제가 생겼습니다. 우리 부족에 관한 일인데요… 부족원 대부분이 미쳐버렸습니다. 부족의 의장이 꿈에서 로아의 계시를 받아 에메랄드 성소 차원문 근처의 물을 이용해 꿈의 부적을 만들라는 명령을 받은 이후로 이런 일이 벌어졌습니다. 당시 저는 악마들과 싸우고 있었는데, 돌아오니 부족원들이 저를 공격하며 스스로를 그림자 사냥꾼이라고 칭했습니다. 광기가 그들을 덮쳤지만, 타락의 근원을 제거하면 우리 부족을 구할 수 있을 거라고 믿습니다. 이 악의 근원을 파헤친 전쟁군주 한젠토를 처치하고, 꿈의 부적을 가지고 있는 의장 간호타를 찾아주십시오. 둘 다 하이잘 서부 줄하타에 있습니다."},objectives={{110,318312574},"줄하타에서 전쟁군주 한젠토를 처치하고, 어둠속삭임 협곡에 있는 그림자사냥꾼 트락날에게 꿈의 마법을 가져다주세요."},progress={{15,587923360},"찾았어?"},completion={{240,720099331},"<트락날이 당신에게서 모조를 빼앗아 칼로 부숴버립니다.>$B$B저는 제 백성을 포기하지 않겠습니다. 이 물건의 타락시키는 영향력이 사라지면, 시간이 흐르면서 그들의 정신이 다시 제자리를 찾을 수 있기를 바랍니다. 친구여, 당신에게 큰 빚을 졌습니다. 감사합니다."}}
rows[41096]={title={{15,2036583839},"레즈에게 알려주세요"},description={{377,1033354823},"이로써 그들의 속도는 당분간 느려졌을 겁니다. 트라크날과 저는 이 악당들에게 계속해서 정의를 구현할 $B$B것입니다. 당신은 산 위로 올라가 당신을 보낸 용에게 경고해야 합니다. 전령에는 또 다른 세력에 대한 언급이 있었는데, 저는 그 세력이 지하에 있을 거라고$B$B 생각합니다. 최근 동굴 하나가 안쪽에서 무너졌지만, 악마 군대는 쉽게 잔해를 치우고 밖으로 쏟아져 나올 수 있을 겁니다."},objectives={{45,1481683599},"멜라나스트라자를 찾아 그녀에게 소식을 전하세요."},progress={{13,630182922},"돌아오셨군요?"},completion={{187,38257332},"정말 끔찍한 소식이네요! 어떤 동굴인지 알겠습니다. 하이잘 아래쪽의 무덤 심연과 연결되어 있죠. 제가 마법을 걸어 그들이 당분간 침입하지 못하도록 막을 수 있을 것 같습니다."}}
rows[41097]={title={{21,466213111},"침공 지연"},description={"Travel to the summit of Mount Hyjal and find my superior, Annesastrasza. She needs to know every pertinent detail about what happened.$B$BLeaving those demons lurking in the Barrow Deeps would have endangered us all. I will make sure to seal the cave while you deliver the news.$B$BYou have done us a great service, $N.","하이잘 산 정상으로 가서 내 상관인 안네사스트라자를 찾아와. 그녀는 무슨 일이 일어났는지 모든 중요한 세부 사항을 알아야 해. 무덤 $B$B깊은 곳에 숨어 있는 악마들을 그대로 놔두는 건 우리 모두를 위험에 빠뜨렸을 거야. 네가 소식을 전하는 동안 나는 동굴을 봉쇄해 둘게. 자네는$B$B 우리에게 큰 공을 세웠네, $NN."},objectives={{56,1427516235},"하이얄의 노르다나르에 있는 안네사스트라자에게 소식을 전하세요."},progress={{26,922174967},"네, 얘야, 내가 도와줄까?"},completion={{461,54668497},"이건 좋지 않은 소식이군요. 딸아이를 도와주신 데 감사드립니다. 그린 가족은 현재 이곳에서 비상사태를 처리 중이라 지금 당장 배로우즈의 악당들을 진압할 병력을 투입할 수 없습니다.$B$B하지만 안심하십시오. 저희가 반드시 그들을 막아낼 것입니다.$B$B수고에 대한 보답으로 이것을 선물로 받겠습니다. 노르다나르에서 유용하게 쓰일 겁니다. 그럼 실례하겠습니다. 악마의 위협을 진압하기 위해 할 일이 많거든요."}}
rows[41098]={title={{24,1956196004},"가젯잔에서 온 편지"},description={"Greetings $c, it has come to my attention that I have received a letter asking specifically for you. It is from a Gnome in Gadgetzan.$B$BThey are called Reas. Seek her out and find out what she wants.","안녕하세요,$c 님. 제가 특별히 당신을 찾는 편지를 받았다는 사실을 알게 되었습니다. 가젯잔에 사는 그놈족인 레아스가 $B$B보낸 편지입니다. 그녀를 찾아가서 무슨 용건인지 알아보세요."},objectives={{27,1452916024},"가젯잔에서 레아스를 찾아보세요."},progress={{12,1838663260},"안녕하세요?"},completion={{28,1046730988},"어머! 당신 낯이 익네요."}}
rows[41099]={title={{23,601403463},"가젯잔에서 온 편지"},description={"Hail $c, I have news for you.$B$BWe got a letter from someone asking specifically for you. It is from a Gnome in Gadgetzan.$B$BThey are known as Reas. We have been asked to inform you that if you are available, you should go there.","안녕$c , 너에게 전할 $B$B소식이 있어.누군가 너를 특별히 찾는 편지를 받았어. 가젯잔에 사는 노움이 $B$B보낸 편지야.그들은 레아라고 불리지. 네가 시간이 된다면 그곳으로 가달라는 부탁을 받았어."},objectives={{27,1452916024},"가젯잔에서 레아스를 찾아보세요."},progress={{12,1838663260},"안녕하세요?"},completion={{28,1046730988},"어머! 당신 낯이 익네요."}}
rows[41100]={title={{19,1407123038},"레이네가 보낸 편지"},description={"Greetings $c, here we are again. We received a notice asking us to send you down to the Eastern Plaguelands. The letter comes from one of the druids stationed there at Light's Hope Chapel.","안녕하세요,$c 님. 다시 뵙게 되었습니다. 동부 역병지대로 당신을 보내달라는 통지를 받았습니다. 그 편지는 빛의 희망 예배당에 주둔하고 있는 드루이드 중 한 명이 보낸 것입니다."},objectives={{69,844242515},"동부 역병지대에 있는 빛의 희망 예배당에서 레인을 찾아보세요."},progress={{26,1921742131},"안녕하세요, 무엇을 도와드릴까요?"},completion={{51,680917040},"아, 당신이었군요. 참 이상한 상황이네요."}}
rows[41101]={title={{20,1692761290},"레이네의 편지"},description={"Hello $c. We received a letter asking us to send you down to the Eastern Plaguelands. The letter comes from one of the druids stationed there. They go by the name 'Rayne', find them at Light's Hope Chapel.","$c안녕하세요, 님. 동부 역병지대로 당신을 보내달라는 편지를 받았습니다. 편지는 그곳에 주둔 중인 드루이드 '레인'이 보낸 것이며, 빛의 희망 예배당에서 찾을 수 있습니다."},objectives={{69,844242515},"동부 역병지대에 있는 빛의 희망 예배당에서 레인을 찾아보세요."},progress={{26,1921742131},"안녕하세요, 무엇을 도와드릴까요?"},completion={{51,680917040},"아, 당신이었군요. 참 이상한 상황이네요."}}
rows[41102]={title={{22,1685247163},"블로마스터의 호출"},description={"Greetings $c. It looks like it is time for you to get into business again.$B$BA certain Kex Blowmaster in the Barrens, around Bael'modan, I believe is looking for ‘his trusted partner'. He promises there will be an opportunity to make quite a fortune.","안녕하세요,$c 님. 다시 사업을 시작할 때가 된 것 같네요.$B$BA라는 사람이 벨모단 근처 불모의 땅에 있는 '믿을 만한 파트너'를 찾고 있는 것 같습니다. 큰돈을 벌 수 있는 기회가 될 거라고 하네요."},objectives={{55,205861017},"불모의 땅 지역의 벨모단 근처에서 켁스 블로우마스터를 찾아보세요."},progress={{3,1746948},"뭐라고?"},completion={{20,450818329},"파트너, 해냈군요!"}}
rows[41103]={title={{18,887401465},"토블레에게서 온 전화"},description={"Hello $c, I hope you're having a fine day. I have news for you. A certain Torble Sparksprocket is asking for your assistance. He mentioned that your invaluable aid in his scientific endeavor is needed once more. Seek him out in Bael'modan.","$c안녕하세요, 님. 좋은 하루 보내고 계시길 바랍니다. 전해드릴 소식이 있습니다. 토르블 스파크스프로켓이라는 분이 당신의 도움을 요청하고 있습니다. 그의 과학 연구에 당신의 귀중한 도움이 다시 한번 필요하다고 하더군요. 벨모단에서 그를 찾아보세요."},objectives={{61,1828459078},"불모의 땅 지역의 벨모단 근처에서 토르블 스파크스프로켓을 찾아보세요."},progress={{4,273767400},"예?"},completion={{25,1308721861},"어머, 여기 계셨군요! 반가워요!"}}
rows[41104]={title={{27,1124621909},"블로우마스터의 귀빈"},description={"Hello $c, it looks like your partner Kex Blowmaster is calling for you again. He said all the pieces are prepared and he wants you to be there for his great moment. Find him in the Barrens in Bael'modan. You are the guest of honor after all.","$c안녕하세요, 님. 파트너인 켁스 블로마스터가 다시 연락을 드린 것 같습니다. 모든 준비가 끝났고, 그의 특별한 순간에 당신이 함께해 주길 바란다고 하네요. 벨모단 불모의 땅에서 그를 찾아보세요. 당신이 바로 그날의 귀빈이니까요."},objectives={{40,293742366},"벨모단 근처에서 켁스 블로우마스터를 찾아보세요."},progress={{3,1799086},"흠?"},completion={{38,474794646},"여기 있었군요! 잘 들어보세요, 이거 정말 중요한 소식이에요!"}}
rows[41105]={title={{30,2067284779},"스파크스프로켓의 특별 손님"},description={"Ah, yes hello $c. We have got another letter for you. Apparently, you have been instrumental in the conclusion of some research in the Barrens. Your pal Torble Sparksprocket is requesting your presence as the guest of honor in the culmination of his research! Better not keep him waiting, eh? You will find him near Bael'modan.","아, 안녕하세요,$c 님. 또 다른 편지가 왔습니다. 당신이 불모의 땅에서 진행된 연구의 마무리 단계에 중요한 역할을 하셨다고 들었습니다. 당신의 친구인 토블 스파크스프로켓이 연구의 결실을 맺는 자리에 당신을 귀빈으로 초대하고 싶어합니다! 오래 기다리게 하지는 않는 게 좋겠죠? 벨모단 근처에서 그를 만날 수 있을 겁니다."},objectives={{61,1828459078},"불모의 땅 지역의 벨모단 근처에서 토르블 스파크스프로켓을 찾아보세요."},progress={{7,179296994},"네, 그렇죠?"},completion={{15,933809218},"아, 여기 계시군요!"}}
rows[41106]={title={{18,657051356},"멜라나스트라자를 찾으세요"},description={{429,1970403214},"땅에 펠(지옥)이 있다면 악마들이 무슨 짓을 꾸미고 있다는 뜻입니다. 길을 따라 올라가다 보면 불에 탄 땅 근처에 도착하게 될 겁니다. 그곳은 하이잘 산 전투가 벌어졌던 $B$B장소 중 하나입니다. 사악하고 흉측한 악마 군주 아르키몬드가 직접 나타나 모든 것을 파괴했죠! 악마들은 아직도 하이잘에 남아 있습니다.$B$B 제가 이곳에 오는 길에 악마들을 조사하고 있던 젊고 아름다운 붉은 용을 만났습니다. 그녀를 찾아보세요!"},objectives={{51,1623909194},"멜라나스트라자를 찾아 그녀에게 상황을 보고하세요."},progress={{4,273767400},"예?"},completion={{129,1612695376},"땅속에 묻혔다고?! 저 짐승들이 뭔가 꾸미고 있다는 걸 알고 있었어. 요즘 너무 조직적으로 움직이더라. 네 도움이 필요해!"}}
rows[41107]={title={{19,132276449},"블러드 링의 명예"},description={{253,885250021},"블러드 링 안에는 영광이 도사리고 있다. 얼라이언스의 용사들에게 도전하여 승리한다면 호드에게 영광을 안겨줄 것이다. 아제로스의 진정한 영웅들은 바로 그곳에 있다. 네 $B$B역할을 다하여 너 자신과 호드에 영광을 가져다주어라."},objectives={{78,586669985},"전장 밖에서 호드 전쟁선봉대원에게 투기장 명예의 징표 15개를 가져다주세요."},progress={"How has the arena treated you, $n?","$n님, 경기장은 어떠셨나요?"},completion={{92,779229449},"우리 조상들이 당신의 이름을 부르짖을 것입니다! 당신의 영광의 소식이 온 백성에게 퍼지게 하소서."}}
rows[41108]={title={{19,132276449},"블러드 링의 명예"},description={{277,704534971},"거기 있느냐, 환호하는 군중이 네 이름을 부르는 소리가 들리느냐? 블러드 링 안에서 누릴 영광은 그 무엇과도 비교할 수 없다. 얼라이언스의 용사들이 호드의 용사들과 맞서 싸우고, 바로 그곳에서 우리는 우월함을 증명할 수 있다. $B$B얼라이언스의 이름으로 네 역할을 다하라!"},objectives={{88,456567412},"전장 밖의 연합군 준장에게 투기장 명예의 징표 15개를 가져다주세요."},progress={"How has the arena treated you, $n?","$n님, 경기장은 어떠셨나요?"},completion={{44,949916785},"오늘 동맹의 막강한 힘이 드러났습니다!"}}
rows[41109]={title={{19,132276449},"블러드 링의 명예"},progress={{248,314417806},"당신의 가슴은 전투에 대한 갈망으로 불타오르는가? 최정상급 전사들이 피의 고리에서 격돌한다. 부름에 응하여 아제로스 최강의 적들과 맞서 싸워라! 승리의 증거를 가져오면, 풍성한 전리품을 거머쥐리라."},completion={{53,531508365},"승리의 영광을 만끽하고, 승리의 기쁨에 흠뻑 젖어보세요!"}}
rows[41110]={title={{21,1450983780},"블러드 링에서의 승리"},description={{232,71067412},"당신은 적을 정복하고, 당신의 막강한 힘 앞에 그들이 짓밟히는 모습을 볼 수 있는 능력을 갖고 있습니까? 만약 그렇다고 생각한다면, 블러드 링에서 영광을 쟁취하고 승리를 거머쥐십시오. 그때 비로소 당신은 이름을 떨치기 시작할 것입니다."},objectives={{95,1177166704},"블러드 링에서 전투에서 승리하고 스트랭글쏜 밸리의 구루바시 투기장에 있는 그렌토르에게 보고하십시오."},progress={"How has the arena treated you, $n? ","$n님, 경기장은 어떠셨나요?"},completion={{71,1776788066},"승리의 기쁨을 느끼셨나요? 피땀 흘려 얻어낸 승리입니다."}}
rows[41111]={title={{29,918252936},"설계도: 드림스틸 벨트 버클"},description={{357,1595469215},"하이잘의 마지막 대규모 전투 중에 꿈의 강철 버클 제작법이 고안되었습니다. 이 버클은 드루이드와 파수꾼들에게 에메랄드 꿈의 마법적 속성을 부여하는 데 사용되었습니다. 만약 이 $B$B제작법이 마음에 드신다면, 꿈의 조각과 교환해 드릴 수 있습니다. 저희는 하이잘을 위해 도움을 주신 분들께 언제나 보상을 드리고자 합니다."},objectives={{74,217871726},"하이잘의 노르다나르에서 에반딜 나이트윈드를 위해 밝은 꿈 조각 50개를 모으세요."},progress={{30,1436192723},"그래서, 선택하셨나요?"},completion={{86,1221341068},"이 계획들이 악과의 싸움에서 당신과 당신의 동맹들에게 강력한 자산이 되기를 바랍니다."}}
rows[41112]={title={{21,673525525},"레이븐크로프트의 야망"},description={{712,1580560598},"이 지긋지긋한 연구에 너무 오랫동안 매달려 있었어요. 모란나도 저를 더 힘들게 하고 있고요. 우르의 책 없이 어떻게든 그의 비밀을 밝혀내야 한다는 건 알지만, 도대체 어떻게 해야 할지 모르겠어요. 마지막으로$B$B 들은 소식으로는 호드의 언데드들이 실버레인 요새에서 그 책을 가져갔다고 하더군요. 영영 찾을 수 없게 된 것 같아요. 하지만 아직 희망은 있어요. 섀드모어 여관에 있던 한 소녀가 길니아스 성벽을 뛰어넘어 탈출했다고 주장했거든요. 의심스럽긴 하지만, 그 소녀에게서 유용한 정보를 얻었어요. 길니아스 도시 도서관에 우르의 책이 있을지도 $B$B몰라요. 부디 그 책을 찾아주시면 정말 감사하겠습니다."},objectives={{100,2119717955},"길니어스 시티 도서관에서 우르의 책 2권을 되찾아 에단 레이븐크로프트에게 돌려주세요."},progress={{25,880492744},"이게 진짜였으면 좋겠네요."},completion={{215,1505716970},"2권이라고요? 이게 어떻게 길네아에 오게 됐는지는 모르겠지만, 신경도 안 써요. 최대한 빨리 모란나에게 가져다줘야 해요. 제 탁자에 있는 보상을 가져가세요. 많지는 않지만, 이게 제가 가진 전부예요."}}
rows[41113]={title={{13,189567976},"왕실의 강탈"},description={{429,155678692},"보스에게 질문하는 건 좋아하지 않지만, 그가 제정신이 아닌 것 같아. 우린 도둑인데, 돈도, 보물도, 훔치고 약탈하는 데서 오는 짜릿함도 어디 있지? 블랙쏜을 설득해서 $B$B나와 다른 산적들이 도시를 습격하는 건 불가능하지만, 자네는 좀 더 재량권을 줄게. 자네가 해야 할 일은 길네아스 시 도서관에 가서 미아 그레이메인의 초상화를 훔쳐오는 것뿐이야. 전리품은 나눠 갖자."},objectives={{111,547114660},"길니어스 시티의 도서관에서 그림을 훔쳐 길니어스에 있는 블랙쏜 캠프의 루크 아가만드에게 가져다주세요."},progress={{29,329581909},"이번이 첫 강도 행각인가요?"},completion={{158,83922321},"그럼 그건 그녀의 어린 시절 초상화였군요? 뭐, 가치는 별로 없을지도 모르지만, 그건 중요하지 않아요. 잘한 일에는 대가가 따르는 법이니까요. 도둑들 사이에도 의리가 있다는 말이 있잖아요."}}
rows[41114]={title={{27,4710628},"물점술에 관한 원고 II"},description={{481,627618211},"마법사여, 자네는 테라모어에 자신의 능력을 증명해 보였네. 이제 내가 부탁할 중대한 일이 $B$B있네. 오래 전, 쿨 티란의 한 수력술사가 길니아스에 상당한 시간을 머물며 수력술에 관한 두 번째 원고를 도시에 남겨두었네. 그 원고는 지금까지 길니아스 도서관에 보관되어 잠들어 있지. 그곳에서는 반란과 폭동에 대한 이야기가 끊이지 않았네. 자네가 이 도시를 용감하게 헤쳐나가 우리 적들이 가장 강력한 마법의 비밀을 알아내기 전에 그 원고를 되찾아 와야 하네."},objectives={{98,1818411643},"먼지진흙 습지대의 테라모어 섬에 있는 마법학자 할리스터를 위해 '물의 마법에 관한 논문 II'를 되찾으십시오."},progress={{62,597246559},"이건 정말 심각한 문제입니다. 원고를 되찾으셨습니까?"},completion={{289,1479156158},"드디어 되찾았군.$B$B<마법사 할리스터가 안도의 한숨을 내쉰다.>$B$B우리의 비밀이 안전한 손에 돌아왔어. 자네는 귀중한 자산임을 증명했고, 같은 마법사로서 마법의 힘이 얼마나 강력한지 잘 알고 있을 거라고 확신하지.$B$B이 선물을 우리 도시의 감사 인사로 받아주게."}}
rows[41115]={title={{21,213161047},"카르텔 금 기부"},description={{542,525626546},"잘 들어, 꼬마야. 네가 누구든, 얼마나 환상적이고 마법 같은 여행을 많이 했든 상관없어. 칭찬받고 싶으면 술집에 가서 여자애들한테나 떠벌려. 난 여기 시스템을 돌아가게 하는 윤활유에 관심 있어. 무슨 말인지 알겠어? 카르텔은$B$B 매일매일의 활동을 조직하고 운영하려면 금이 필요해. 해야 할 일은 항상 있지, 그게 인생의 진리잖아? 그러니까... 네가 우리에게 자금을 대주면, 우린 관심을 가질 거야. 어쩌면 가끔 무릎뼈를 부러뜨려도 눈감아 줄지도 몰라. 어쩌면 말이야."},objectives={{51,495122899},"무법항에 있는 카운터 직원 클레멘스에게 금화 10개를 가져다 주세요."},progress={{169,2109693092},"그는 금화를 하나씩 깨물어 준 다음 카운터 뒤에 보관했다. 그는 더 이상 한마디도 하지 않고 짧게 고개를 끄덕이며 장부에 무언가를 적었다."},completion={{22,1814577066},"그래서, 그 동전 얻었어?"}}
rows[41117]={title={{20,833373806},"제페크의 석판"},description={{643,1823980471},"마법사여, 자네는$B$B 내게 큰 도움을 주었네. 우리 마법사들은 서로를 도와야 하니까. 자네에게 부탁할 게 하나 더 있네. 이번에는 좀 더 개인적인 부탁이네. 나는 한동안 아탈하카르 사원을 연구해 왔는데, 제페크의 석판에 얽힌 수수께끼를 들었네. 전설에 따르면, 그 석판에는 이곳 늪지에 있는 사원을 세운 위대한 트롤 군주에 대한 이야기가 담겨 $B$B있다고 하네. 뭐, 대략 그런 내용이지만. 더 중요한 건 그 돌에 깃든 마법이지. 자네가 그 석판을 되찾아 주었으면 좋겠네. 사원 안 피의 방 근처, 주문을 외우는 불경한 카즈카즈가 있는 곳에 있네. 찾아서 내게 가져다주게."},objectives={{53,1178462144},"스토나드에서 툴타조르를 위해 제페크의 석판을 모으세요."},progress={{42,787338685},"당신은 이 신비로운 카즈카즈를 찾았나요?"},completion={{262,1156803899},"이 석판에서 뿜어져 나오는 마법의 힘은 엄청나군! 트롤들에게서 이런 에너지가 나올 줄은 상상도 못 했어.$B$B자네는 내게 큰 은혜를 베풀었네. 그 보답으로 이 책을 주겠네. 이 책을 통해 스토나드로 순간이동하는 방법을 알게 될 걸세. 내 마법이 자네에게 도움이 되기를!"}}
rows[41118]={title={{15,788828755},"피의 증표"},progress={{273,632269623},"거기! 혹시 아레나 명예의 징표를 현금으로 바꾸고 싶으신가요? 저희 금고에서 보상을 받고 싶으시다면, 명예의 징표를 피의 토큰으로 교환해 드릴 수 있습니다. 이곳의 화폐 같은 거라고 생각하시면 됩니다."},completion={{43,1114254191},"챔피언님, 거래하게 되어 기쁩니다."}}
rows[41119]={title={{31,2120672332},"설계도: 화려한 혈석 단검"},description={{281,131621563},"투기장의 영광에 걸맞은 위엄 있는 무기를 만들고 싶으신가요? 그렇다면 제가 딱 맞는 무기를 하나 추천해$B$B 드리겠습니다. 화려한 혈석 단검은 고대에 피를 제물로 바친 단검, 구루바시에서 유래했다고 전해집니다. 관심 있으시면 연락 주십시오."},objectives={{87,421682167},"스트랭글쏜 밸리의 구루바시 투기장에 있는 브래들리 스틸에게 피의 토큰 50개를 가져다 주세요."},progress={{22,1920851038},"그래서, 마음을 정하셨어요?"},completion={{105,1425017783},"이제 그 힘은 당신의 손에 있습니다. 투기장에서 당신이 흘린 피에 걸맞은 당연한 결과입니다."}}
rows[41120]={title={{19,898418207},"레전드 오브 던스톤"},description={{930,1257267773},"이봐, 꼬마야! 전설적인 던스톤 광석에 대해 들어봤나? 정말 대단한 이야기지! 2차 전쟁 때 우리 용감한 성기사들의 갑옷을 만드는 데 쓰였던 광석 말이야. 참 $B$B영광스러운 시절이었지! 하지만 말이야, 정말 귀한 광석이란다! 이 넓은 세상에서 단 한 곳, 길니아스 시 지하에 숨겨진 광산에서만 채굴할 수 있어. 그래, 그곳에는 저주 같은 게 걸려 있어서 이 귀한 광석이 지표면으로 올라온 것 같아. 우리 아버지 수염을 걸고 맹세하는데, 그 진짜 정체를$B$B 알고 싶지는 않군. 그레이메인 문이 다시 열렸고, 길니아스의 정치적 혼란 때문에 그 광산은 아마 버려졌을 거야. 그래서 언더마인에 있는 내 의뢰인들을 위해 그 광석을 캐내려고 생각 중이지. 던스톤 광석 덩어리 12개를 구해다 주시면, 수익의 일부를 기꺼이 나눠드리겠습니다. 어때요? 거래할까요?"},objectives={{122,186388040},"무법항에 있는 커넨 오스브레이스에게 새벽석 광석 12덩이를 가져다 주세요. 이 광석은 길니아스의 새벽석 광산에서만 채굴할 수 있습니다."},progress={{39,1953128403},"그 광산이 아직 온전하게 남아있을지 궁금하네요..."},completion={{282,414714455},"그래, 광석이 내 예상대로로 왔군! 정말 자랑스럽구나, 얘야! 자, 이제 이 귀한 돌들을 모아서 언더마인으로 운반할 준비를 해야겠다. 아, 생각만 해도 벅차오르는 수익이여!$B$B약속대로 보상을 받을 자격이 충분하구나. 자, 필요하다면 이것을 가져가거라."}}
rows[41121]={title={{19,1867426116},"페레놀드의 유산"},description={{908,1132726148},"저는 길네아의 영주 파이어우드입니다. 이미 들으셨겠지만, 반란군이 그레이메인 성벽을 장악하여 성벽이 개방되었고, 이는 우리 왕국에 새로운 장을 열어젖히고 있습니다. 저는 바로 이 반란군의 명령을 받고 스톰윈드에 저희의 대의를 지지해 줄 것을 간청하기$B$B 위해 이곳에 왔습니다. 하지만, 이 긴급한 사안들 외에도 겸손하게 도움을 청해야 할 부탁이 하나 있습니다. 그레이메인 궁정이 많은 손님들을 맞이하던 중, 이시덴 페레놀드라는 분이 저희 궁정을 방문하셨습니다. 많은 이들이 그를 알터랙 왕좌의 정당한 계승자로 여기고 있으며, 그가 동맹에 도움을 준다면 그 가치는$B$B 헤아릴 수 없을 것입니다. 그런데 할로우 가문이 그를 악명 높은 드라이록 구덩이에 가두고 있다는 소문이 제 귀에 들어왔습니다. 그곳에서부터 수색을 시작해 주시고, 이 존경받는 손님에 관한 정보를 발견하시면 주저 없이 저에게 알려주시기 바랍니다."},objectives={{108,724653667},"이시덴 페레놀데에 대한 정보를 찾아보세요. 그는 길네아스의 드라이록 구덩이에 감금되어 있다는 소문이 있습니다."},progress={{629,1963704733},"에이든 페레놀드 왕의 조카인 이시덴 페레놀드는 알테라크의 배신으로 동맹이 위태로운 상황에 처하게 되었습니다. 이 절박한 상황에 맞서 이시덴은 길니아로 피신했습니다.$B$B알테라크의 후계자 문제가 점점 더 중요해지면서, 이시덴 페레놀드는 지원을 얻기 위해 노력했고, 그 과정에서 겐 그레이메인의 눈에 띄게 되었습니다. 이 문제의 중요성을 인식한 그레이메인 왕은 이시덴을 지지하기로 결정했고, 이는 사건 전개에 또 다른 복잡성을 더했습니다.$B$B결국 알테라크는 스트롬과 로데론에 합병되었지만, 이시덴은 그레이메인 장벽이 무너진 후에도 길니아에 남아 있었습니다."},completion={{327,162551258},"이바르가 서류를 훑어보는 동안 그의 눈에는 뚜렷한 실망감이 가득했다.$B$B이시덴이 길네아스를 떠난 것 같군. 만약 그가 톨 바라드에 피신했다면, 우리는 그의 비극적인 죽음을 받아들여야 할 것이다. 그 섬의 혹독하고 무자비한 환경을 견뎌낼 수 있는 것은 아무것도 없으니까."}}
rows[41122]={title={{15,1181525023},"길네아의 총"},description={"Listen here, $c! I got a real urgent and serious matter that needs your help, right now!$B$BThose Gilneans have gone and opened up their gates once again, causing a load of trouble for us. Blast it! Now their coastal batteries are taking potshots at our transport ships, making trade with the Undercity a real pain in the gut!$B$BI need ya to take care of Cannoneer Rileson. He's the scoundrel calling the shots at Freyshear Keep, and he's the one commanding those blasted cannons. And don't you dare forget about his henchmen too – deal with them all!$B$BGet back to me once you've sent him to the great beyond. We ain't got time to waste.","이봐, ! $c지금 당장 네 도움이 필요한 아주 긴급하고 심각한 일이 $B$B있어!저 길네아 놈들이 또 성문을 열어서 우리한테 큰 골칫거리를 안겨줬어. 젠장! 이제는 해안 포대가 우리 수송선에 포격을 가하고 있어서 언더시티와의 교역이 완전히 엉망이 됐어!$네가 $B$B포수 라일슨을 처리해 줘야 해. 그 악당이 프레이시어 요새에서 지휘를 맡고 있고, 그 망할 대포들을 지휘하는 놈이야. 그리고 그 부하들도 절대 잊지 마. 전부 처리해 버려!그놈을$B$B 저승으로 보내고 나면 바로 연락 줘. 시간을 낭비할 여유가 없어."},objectives={{92,321486887},"글리네아스 동쪽 프레이셰어 요새에서 포병 라일슨과 그레이메인 수호자 10명을 처치하십시오."},progress={{60,2063913447},"당신이 머뭇거리는 매 순간이 이 미치광이에게 또 다른 배를 잃는 것과 같습니다!"},completion={{98,277321544},"좋습니다, 좋습니다.$B$B당신의 도움 덕분에 언더시티와 타렌 밀로의 배송이 훨씬 안전해졌습니다."}}
rows[41123]={title={{19,1131161699},"비즐로에게 기부"},progress={{275,1792101288},"챔피언님!$B$B저희와 함께 이름을 떨치고 싶으신가요? 저희는 현재 기부금을 받고 있습니다. 피의 토큰이 필요해요. 만약 사용하지 않으실 것 같으면 저희에게 반납해 주세요. 제가 사장님들께 부탁드려서 부탁드리겠습니다."},completion={{43,1114254191},"챔피언님, 거래하게 되어 기쁩니다."}}
rows[41126]={title={{44,1141393335},"형제단의 호의, 검은무쇠 바"},objectives={{67,32964178},"그림 거즐러에 있는 로크토스 다크바게이너에게 다크 아이언 바를 가져다 주세요."},progress={{330,1604574818},"심연에는 흑철이 풍부하지만, 암살단에게는 여전히 귀중한 자원입니다. 라그나로스의 신성한 무기는 흑철을 선호합니다. 광석 외에도, 제련 기술을 가지고 있다면 흑철 주괴 형태도 받습니다.$B$B흑철 주괴를 하나 바칠 때마다 암살단의 호감도가 증가합니다."},completion={{119,1862505354},"당신의 제안이 받아들여졌습니다. 당신은 호의를 얻었습니다. 계속 노력하시면 고대 무역에 접근할 수 있게 될 것입니다."}}
rows[41127]={title={{22,1506893420},"바엘 하르둘의 드워프들"},description={{478,2007301086},"우리의 굳건한 드워프 동맹이 최근 돌발톱 산맥에 있는 옛 3차 전쟁 전초기지에 정착했습니다. 그들의 지도자는 제 오랜 친구인 화이트피크입니다. 얼라이언스를 위해 스톤탈론을 재건하는 데 도움을 주시면 $B$B화이트피크가 매우 기뻐할 것입니다.기억이 맞다면 그 전초기지는 바엘 하르둘입니다. 그곳을 찾으려면 탈론딥 고개를 지나 남쪽 산맥으로 들어가세요. 전초기지로 이어지는 비밀 길이 $B$B있습니다.화이트피크를 만나시면 제 안부를 꼭 전해주세요."},objectives={{144,1288573163},"벨 하르둘 산기슭에 있는 화이트피크 탐험대장에게 보고하십시오. 화이트피크 탐험대장은 브램블쏜 고개 근처, 윈드셰어 크래그 남쪽에 위치해 있습니다."},progress={{38,578184263},"그래요? 오늘 손님이 올 줄은 몰랐는데요."},completion={{308,127829988},"그래, 델그렌이 널 보냈군? 하하, 그 녀석 참 좋은 녀석이지. 3차 전쟁 때 내 옆에서 싸웠어. 제이나 여왕님 지휘 아래서 말이야. 여왕님은 정말 훌륭한 분이셨지.$B$B하지만 이제 늙은 난쟁이처럼 과거 이야기를 늘어놓는 건 그만하고, 할 일이 산더미 같으니 어서 서둘러 시작하자! 시간을 낭비할 순 없어, 얘야!"}}
rows[41128]={title={{22,1147356377},"샤드 탈조화"},progress={{223,230986949},"돌아왔군, 그 파편들은 준비됐나?"},completion={{143,1078531042},"훌륭한 작업입니다. 조화 과정은 특히 이렇게 연습을 많이 하면 오래 걸리지 않습니다. 더 좋은 방법을 찾으시면 저에게 알려주세요."}}
rows[41129]={title={{25,2036234151},"계획: 피 묻은 벨트 버클"},description={{244,272273814},"남들보다 돋보이고 싶으시다면, 제가 딱 맞는 아이템을 하나 추천해 드릴 수 있습니다. 얼마 전, 저는 강렬한 힘이 깃든 화려한 버클 패턴을 디자인했습니다. 이$B$B 버클은 경기장에서 싸우는 이들에게 유용할지도 모릅니다."},objectives={{87,1955794127},"스트랭글쏜 밸리의 구루바시 투기장에 있는 브래들리 스틸에게 피의 토큰 25개를 가져다 주세요."},progress={{22,1920851038},"그래서, 마음을 정하셨어요?"},completion={{104,2053631268},"이 벨트 버클이 당신에게 오래도록 유용하게 쓰이길 바랍니다. 현명하게 사용한다면, 생사를 가르는 중요한 역할을 할 수도 있습니다."}}
rows[41130]={title={{14,334368900},"가죽 편지"},description={{341,2083730668},"방금 당신 앞으로 온 편지를 받았습니다. 마을 사람 중 한 명이 당신을 잘 알고 있어서 만나자고 하더군요. 다시 한번 당신의 뛰어난 사격 솜씨와 용맹함에 축하를 전합니다. 당신은 분명 동맹에 큰 공헌을 할 겁니다. 나이 드신 요나 ​​할아버지가 참을성이 없어지셨는데, 그 얘기는 절대 들키지 않도록 조심해 주세요."},objectives={{71,1290012680},"가죽 편지를 읽고 노스셔 수도원 뒤편에 있는 늙은 요나와 대화하세요."},progress={{85,366049407},"하! 어른에 대한 존경심이라고는 눈곱만큼도 없군. 이 녀석아, 날 얼마나 오래 기다리게 했냐."},completion={{294,1857893305},"그건 단지 첫 번째 교훈일 뿐이란다, 꼬마야. 네가 생존에 있어서 그토록 타고난 재능을 보일 줄은 몰랐지만, 어쨌든 넌 가서 쓸모 있는 일을 해야 한다. 시간이 흐르고 네가 이 땅과 네 능력에 대해 더 잘 알게 되면 다시 내게 돌아오렴. 그러면 내가 더 많은 것을 가르쳐주겠다."}}
rows[41131]={title={{16,967004350},"야수를 길들이기"},description={{647,1020066610},"할아버지께서는 제게 사냥꾼의 의미에 대한 이야기를 자주 들려주셨습니다. 다른 민족들에게는 그 의미가 상당히 다른 것 같습니다. 우리 인간에게 사냥꾼이란 자연에 적응하고, 자연을 존중하는 도구로 사용하는 것입니다. 우리 조상들은 야생마, 소, 심지어 가장 사나운 포식자까지 길들여 믿음직한 동반자로 만들었습니다. 인간의 손길은 땅을 다양한 형태로 변화시킬 수 있으며, 바로 이러한 적응력이 우리의 생존을 가능하게 했습니다. 저는 여러분이 스톤필드 농장에 방문하여$B$B 멧돼지 한 마리를 길들여 주시기를 바랍니다. 멧돼지는 강하고 튼튼하며, 무시무시한 적이 될 수도 있고 훌륭한 동반자가 될 수도 있습니다."},objectives={{125,82559243},"길들이기 막대를 사용하여 돌상아멧돼지를 길들이세요. 길들이기 기술을 연습한 후, 골드샤이어에 있는 데이지 윈드헬름에게 길들이기 막대를 돌려주세요."},progress={{121,1404106427},"할머니 스톤필드께 인사드리는 것도 잊지 마세요. 물론 당신이 오거처럼 예의범절을 잃어버리지 않았다면 말이죠."},completion={{96,352750959},"축하합니다! 첫 번째 우정을 쌓는 데 성공하셨군요! 친구, 당신의 끈기가 정말 대단합니다."}}
rows[41132]={title={{16,967004350},"야수를 길들이기"},description={{699,493316041},"스톤 케언 호수에서 물놀이를 즐기던 때가 종종 그립지만, 요즘은 온갖 야생 동물들, 끔찍한 놀, 미끈미끈한 멀록, 그리고 어리석은 데피아즈 도적들로 가득 차 버렸지. 뭐, 평화로운 시절을 아쉬워할 이유는 없겠지. 평화로운 시절은 머지않아$B$B 다시 돌아올 테니까. 동쪽으로 벌목 캠프 쪽으로 이동하면, 캠프 외곽에서 프롤러를 만날 수 있을 거야. 길들인 멧돼지와는 달리, 이 야생 숲의 생물은 길들이기가 좀 더 어려울지도 몰라. 무섭긴 하지만, 일단 두려움을 극복하고 나면 이보다 더 좋은 동반자는 없을 거야. 늑대 종족인 프롤러는 주인과 평생 동안 지속될 유대감을 형성할 가능성이 매우 높거든."},objectives={{118,1800952410},"길들이기 막대를 사용하여 프롤러를 길들이세요. 실력을 갈고닦은 후, 골드샤이어에 있는 데이지 윈드헬름에게 길들이기 막대를 돌려주세요."},progress={{182,966171755},"때로는 프롤러를 상대할 때 단호하게 행동하는 것이 유일한 해결책입니다. 다른 방법이 없다고 생각되면, 그냥 달려들어 귀를 물어뜯고 누가 우두머리인지 보여주세요!"},completion={{54,1319533173},"정말 잘했어요! 이제 다음이자 마지막 과제를 수행할 준비가 되었습니다."}}
rows[41133]={title={{16,967004350},"야수를 길들이기"},description={{695,774527297},"어린 숲곰을 마주했을 때, 그 순수함과 귀여움에 그냥 무관심할 수는 없습니다. 어린 나이에도 불구하고 이들은 만만치 않은 생물이며, 위협을 감지하면 공격적으로 변할 가능성이 높습니다. 이 짐승을 길들이는 것은 쉬운 일이 아닙니다. 하지만 길들이는 데 성공하면 영원히 당신 곁을 지켜줄 든든한 동반자를 얻게 될 것입니다. 이 곰들은 쉽게 겁을 먹지만, 일단 당신에게 익숙해지면 매우 애교가 많습니다. 숲곰을 $B$B찾으려면 벌목 캠프 근처로 다시 한번 가보세요. 아, 그리고 아조라의 탑을 조심하세요. 그곳에 사는 자는 제정신이 아닌 것 같고, 노움 조수들을 몹시 좋아합니다. 정신 건강을 소중히 여긴다면 가까이 가지 마세요."},objectives={{128,1291927476},"길들이기 막대를 사용하여 어린 숲곰을 길들이세요. 길들이기 기술을 연습한 후, 골드샤이어에 있는 데이지 윈드헬름에게 길들이기 막대를 돌려주세요."},progress={{150,1372769696},"곰이 꿀을 아주 좋아한다는 말을 들었어요. 심지어 꿀을 너무 많이 먹으면 곰의 피부가 노랗게 변한다는 얘기도 있는데, 할아버지는 그건 그냥 허황된 미신이라고 하시더라고요."},completion={{144,1490872011},"자, 드디어 마지막 과제를 완료했습니다. 정말 훌륭하게 해냈군요. 엘윈에서 동물을 관리하는 방법을 완벽하게 익혔습니다."}}
rows[41134]={title={{18,534037912},"야수를 훈련시키다"},description={{469,307087121},"이제 원하는 모든 종류의 짐승을 길들일 수 있지만, 그건 짐승과 유대감을 형성하는 시작일 뿐입니다. 그러려면 새로운 동료를 훈련시키는 방법을 배워야 하죠. 걱정 마세요, 제가 딱 맞는 사람을 알고 있습니다. 바로 마븐입니다. 그는 스톰윈드 공원에 살고 있는데, 아마도 엄청난 돈을 요구할 겁니다. 이 마븐이라는$B$B 사람은 짐승 조련에 아주 능숙한데, 심지어 네싱와리까지 감탄시켰다고 하더군요. 물론 네싱와리가 누군지는 저도 잘 모르겠지만요."},objectives={{58,1517932194},"스톰윈드 시 공원에 있는 조련사 마벤과 대화하세요."},completion={{256,1596235982},"아, 새로운 퀴버 회원이시군요. AJ가 조만간 오실 거라고 말씀드렸었죠. 최근 성과를 보니 데이지가 기초를 정말 잘 가르쳐주신 것 같네요. 자, 그럼 두 번째 수업을 시작해 볼까요? 얼마나 잘 해내실지 기대되네요."}}
rows[41135]={title={{14,2672871},"오염된 태블릿"},description={{503,1424776917},"저는 이 석판을 당신에게 전달하는 임무를 맡았습니다. 골칫거리 흑마법사 나르토크도 모자라, 또 다른 트롤이 시련의 계곡에 나타났습니다. 그는 지역 부족 출신의 흑마법사 지망생들을 가르치러 왔다며, 자신의 방법이 정통이라고 주장합니다. 하지만 저는 호기심이나$B$B 불필요한 위험을 즐기는 사람이 아닙니다. 그저 문제를 일으키거나 갈등에 휘말리고 싶지 않을 뿐입니다. 특히 악마의 힘처럼 위험한 것과 관련된 일이라면 더더욱 그렇습니다. 그러니 항상 경계하고 안전에 유의하십시오."},objectives={{86,925365814},"오염된 석판을 읽고 시련의 계곡에 있는 굴 안에서 진자시와 대화하십시오."},progress={{230,1830725098},"안녕, 친구. 난 진자시야. 자네를 환영하네.$B$B난 레반투스크 부족 출신이고, 어린 트롤들에게 뒤틀린 황천의 길을 가르치러 왔네. 악마들은 강력한 존재지만, 아주 교활하기도 하니 조심해야 하네!"},completion={{552,268951605},"굳이 오크 코븐에 가입할 필요는 없지만, 그들을 잘 활용하는 게 좋을 거야. 이 오크, 나르토크는 말이 너무 많아. 악마들을 어떻게 다뤄야 하는지 제대로 아는 것도 아니고, 마치 선택받은 자라도 된 것처럼 허풍만 떨고 있지. 절대 그렇게 생각하지 마. 뒤틀린 황천에서 악마들을 소환하는 순간, 넌 로아의 손길이 닿지 않는 삶을 선택하게 되는 거야. 언젠가는 그 대가를 치르게 될 테니까.$B$B어쨌든, 내게 제물을 바친다면 기꺼이 가르쳐주겠다. 언젠가는 너도 잔달라리 데모니악처럼 강해질 수 있을 테니까!"}}
rows[41136]={title={{22,1703698906},"카라잔의 열쇠 IV"},description={{689,171179873},"네, 맞습니다. 대마법사 반돌은 키린 토에서 가장 뛰어난 지략가 중 한 분이셨죠. 믿기 어려우시겠지만, 그는 메디브의 절친한 친구였습니다. 물론 메디브에게는 진정한 친구가 없었다고 주장하는 사람들도$B$B 있겠지만요. 하지만 안타깝게도 제가 당신을 많이 도와드릴 수는 없을 것 같습니다. 아르키몬드가 달라란을 파괴한 후, 반돌은 큰 부상을 입으셨고, 그 후유증으로 오랜 기간 회복에 힘쓰시다가 결국 우리 시대 최고의 마법사 중 한 명으로 은퇴하셨습니다. 제가 기억하기로는$B$B 그가 테라모어 근처에 정착하고 싶어 했던 것 같습니다. 만약 아직 살아계시다면, 테라모어 시내에서 직접 찾아보시는 게 좋겠습니다. 우리 수습 마법사 할리스터가 그의 행방을 알고 있을지도 모릅니다."},objectives={{63,826967510},"테라모어에 있는 마구스 할리스터에게 반돌의 행방을 물어보세요."},progress={{62,1026830195},"테라모어에 오신 것을 환영합니다. 무엇을 도와드릴까요?"},completion={{33,1458802971},"반돌이요? 제가 기록을 확인해 보겠습니다."}}
rows[41137]={title={{21,619546530},"카라잔의 열쇠 V"},description={{738,1694018677},"마법사 할리스터는 두꺼운 책들을 꼼꼼히 훑어보며, 수십 년간의 연구와 경험이 묻어나는 강렬한 눈빛으로 모든 줄을 살폈다. 몇 분 동안 부지런히 책을 찾던 그는 마침내 씁쓸한 미소를 지으며 당신을 올려다보았다.$B$B \"아, 맞다. 반돌. 그는 약 4년 전에 테라모어에 왔었지. 제이나 부인을 뵈러 왔었거든. 하지만 오래 머물지는 않았어. 나이 든 자신에게는 너무 번잡하다고 $B$B생각했나 보군. 우리 기록에 따르면, 반돌은 방문 직후 작은 배를 샀대. 필수품과 식량, 심지어 씨앗까지 싣고 말이지. 남쪽으로 항해를 떠났어. 좀 더 조용한 삶을 찾아서 말이야. 그를 찾으려면 해안선을 따라가는 게 가장 좋을 거야.\""},objectives={{89,1024061393},"반돌을 찾아라. 그는 칼림도르 동쪽 해안, 테라모어 남쪽 어딘가에 살고 있다."},progress={{37,797867442},"무슨 일로 제 외딴 집에 오셨나요?"},completion={{623,1870843980},"당신이 저를 찾아왔고, 제 진짜 정체를 알고 있다는 것을 느낍니다. 제 과거가 마침내 저를 따라잡은 것 같군요. 솔직히 놀랍지는 않습니다.$B$B당신이 하려는 말의 심각성을 잠시 생각해 보십시오. 저는 승리와 비극으로 가득 찬 긴 인생을 살아왔습니다. 위대한 왕국의 몰락을 목격했고, 권력이라는 이름으로 사람들이 저지를 수 있는 잔혹 행위를 직접 보았습니다.$B$B만약 당신이 제 과거의 죄와 제가 저지른 수많은 실수에 대해 따지러 왔다면, 저는 저항하지 않겠습니다. 어떤 결과가 따르더라도 받아들이겠습니다."}}
rows[41138]={title={{25,1396410993},"금고 족쇄 복구"},description={{581,611750601},"처음 금고가 열렸을 당시, 이곳은 가장 위험한 죄수들을 가두는 곳이었습니다. 마법적인 존재들과 정신 나간 자들을 가두기 위해 룬 구조물을 사용했죠! 하지만 이 룬 $B$B구조물들은 금고 안의 강렬한 마법 때문에 타락했고, 파괴되어야 합니다. 강력한 팔찌가 이 구조물들을 온전하게 유지시켜 주고 있는데, 이 팔찌를 되찾아야 합니다! 저는 이 팔찌에 정확히 무엇이 잘못되었는지 알아낼 계획입니다.$B$B 스톰윈드 금고 안에서 이 구조물들을 찾아 처치하고, 제게 족쇄 한 쌍을 가져오세요. 그러면 반드시 보상을 드리겠습니다."},objectives={{103,1885726565},"스톰윈드 금고 안에서 룬 구조물을 처치하여 룬 족쇄 2개를 획득하고, 이를 콜리 스팀하트에게 가져다주세요."},progress={{97,668637425},"조심하세요, 룬 구조물은 상당히 강력합니다. 마법 에너지가 폭주한 결과물이에요!"},completion={{89,1532638768},"아, 여기 있군요! 이분들이시네요. 다시 한번 감사드립니다. 정말 큰 의미가 있어요. 약속대로 왔습니다."}}
rows[41139]={title={{16,1248788029},"아크티라스 엔딩"},description={{583,1983694663},"수년 전, 스톰윈드의 마법사들은 엄청난 양의 마법 에너지를 품은 거대한 수정 하나를 발견했습니다. 우리는 이 수정에 아크티라스라는 이름을 붙이고, 그것이 내뿜는 불안정한 마법 때문에 여러 차례 사고를 겪은 후 스톰윈드 금고 깊숙한 곳에 보관했습니다.$B$B 하지만 우리는 이 수정이 아크티라스라는 사실을 전혀 몰랐습니다.$B$B 아크티라스는 스스로 생각하는 능력을 가지고 있었습니다. 이 수정은 경비병들을 미치게 만들었고, 스톰윈드 금고를 광기의 복도로 바꿔놓았습니다. 지금은 우리의 마법으로 수정을 억제할 수 있지만, 완전히 $B$B파괴해야 합니다. 스톰윈드 금고로 가서 이 광기를 끝내주세요."},objectives={{108,119204012},"스톰윈드 금고 깊숙이 들어가 아크티라스를 찾아 처치하십시오. 완료되면 페핀 아인스워스에게 돌아가십시오."},progress={{133,317122352},"아크티라스가 활성화된 상태로 오래 지속될수록 스톰윈드는 더 큰 위험에 처하게 됩니다. 소문이 퍼지는 것을 용납할 수 없습니다. 반드시 해결해야 합니다."},completion={"It is done, truly?$B$BWhy, thank you $N, you've saved us a massive headache, and countless lives of this city. We have requisitioned a reward worthy of such feats from the treasury itself.$B$BPlease, take one, it is the least we can do.","정말 끝났습니까?$B$B정말 고맙습니다.$N덕분에 큰 골칫거리와 이 도시의 수많은 생명을 구할 수 있었습니다. 국고에서 그에 걸맞은 포상을 발부받았습니다.$B$B부디 하나만 받아 가십시오. 이 정도는 해드릴 수 있습니다."}}
rows[41140]={title={{15,2092244553},"요점을 증명하다"},description={{842,76985043},"저기 있는 내 쓸모없는 동생 신드리가 어머니께 허풍을 떨면서 나를 이길 수 있다고 생각하는 모양인데, 그건 그냥 그 늙은 여왕님한테 덤벼들기 위해서지! 내가 여기서 대장장이 일을 더 잘한다는 걸 그 자식은 뻔히 알고 있어. 두고 봐, 동생아, 내가 네 그리핀 둥지에 꽂을 무기를 만들어 줄 테니까! 자, $B$B이봐요, 당신도 좀 도와주세요. 스컬크 록에 있는 동굴 알지? 그 광산에는 아직 미스릴이 많이 남아있지만, 그냥 냄새나는 미스릴은 필요 없어. 난 에칭된 미스릴이 필요하다고! 거기 돌아다니는 진흙 괴물들이 주변에 있는 광석 조각들을 다 흡수해 버리지만, 그 산성으로는 완전히 파괴할 수는 없거든. 녹이면 $B$B엄청나게 단단해져요! 신드리는 낡고 먼지 쌓인 책에서 그렇게 하면 안 된다고 읽었다고 할지도 모르지만, 우리 조상들이 망치질하기 전에 책을 읽었을 거라고 생각하세요? 절대 아니었을 거예요!"},objectives={{89,627665528},"에어리 피크에 있는 브록 썬더포지에게 새 제작물을 위해 에칭된 미스릴 조각 15개를 모으세요."},progress={{98,567862159},"어머니가 그의 작품을 비웃을 때 그가 짓는 멍한 표정을 보면 다른 어떤 것과도 비교할 수 없는 감정이 내 마음속에 와닿는다."},completion={{265,622800577},"오호! 이 조각들 정말 멋지군. 어서, 내게 줘!$B$B<브록이 네 손에서 미스릴 조각을 거의 뺏어 대장간에 던져버린다.>$B$B아하하! 이거 정말 끝내줄 거야, 친구! 두고 봐, 신드리, 넌 언제나처럼 눈물을 펑펑 쏟게 될 거야!"}}
rows[41141]={title={{27,1337695347},"나는 그것을 책에서 읽은 적이 있다."},description={{988,1733668911},"브록과 나눈 대화 들었어요. 그 녀석이 얼마나 시끄럽게 떠드는지, 제 생각조차 제대로 들을 수 없을 정도였죠! 아마 제가 아마추어 대장장이 같다고 했을지도 모르지만, 그건 완전히 사실과 다릅니다! 우리 와일드해머 드워프 중에서 저보다 나은 대장장이는 없을 거예요. 물론 우리 어머니를 $B$B제외하고는요. 하지만 사실이에요. 어머니께 무기를 선물해서 그 얼간이에게 시간 낭비하지 않도록 확실히 해드리고 싶어요. 그 얼간이는 감정에 휘둘려 무기를 만들고 전통과 기술, 그리고 무엇보다 품격을 무시하잖아요! 제 생각엔 그 얼간이는 변두리 청동수염 마을에나 처박혀 있어야 할 $B$B거예요. 당신이 그 얼간이를 도왔으니 저도 도와주셔야죠. 최근 떠돌이 상인들에게서 산 책들에는 자연 마법으로 만들어진 돌 거인들에 대한 이야기가 나와 있어요. 그들의 몸은 제 무기에 딱 맞는 에너지 광물로 가득 차 있죠! 그들은 페랄라스 북부의 울창한 숲에 살고 있답니다. 그들의 시신에서 충분한 양의 샘플을 채취해 주세요."},objectives={{124,1496373711},"신드리 썬더포지는 자신의 창조물을 위해 산악 거인의 표본이 필요합니다. 그는 특히 페랄라스에 사는 거인들을 언급했습니다."},progress={{98,605807140},"브록은 정말 자만심이 가득해. 틀렸다는 게 밝혀졌을 때 짓는 그 뾰루퉁한 표정은 정말이지, 말로 다 할 수 없어!"},completion={{184,335872407},"정말 멋지네요! 뿜어져 나오는 에너지 좀 보세요! 하하, 이걸 손에 넣으면 절대 질 리 없지!$B$B<신드리는 돌덩이들을 바라보며 당신을 금세 잊어버립니다.>"}}
rows[41142]={title={{13,1743134255},"둘 다 하면 안 될 이유가 뭐 있죠?"},description={{874,659025846},"내 아들들을 사랑하지만, 저렇게 싸우는 모습을 보면 망치로 머리를 후려치고 싶어 죽겠어. 걔네들이 싸움만 그만하면 훨씬 더 많은 걸 이룰 수 있을 텐데 말이야. 난 걔네들을 좋게 $B$B포장하는 사람이 아니야. 아버지라면 그랬을지도 모르지만, 그 실망스러운 남자는 오래전에 세상을 떠났지. 우린 걔네 둘에게 진짜 드워프 대장장이의 기술이 뭔지 다시 일깨워주기 위해 우리만의 무기를 만들 거야. 걔네들은 좋은 방향으로 가고 있었지만, 안타깝게도 비전이 부족해. 우린 걔네 둘의 아이디어를 $B$B합쳐볼 거야. 네 모험가 친구들은 상상도 못 할 기괴한 생물들에 대한 이야기를 많이 해 주지. 잊혀진 땅의 마라우돈의 하얀 협곡에는 순수한 대리석으로 이루어진 거대한 랜드슬라이드가 살고 있어. 소문에 따르면 불타는 초원의 증오 대장간 채석장 깊숙한 곳에 있는 산성 웅덩이가 너무나 강력해서 그곳에서 어떤 존재가 나타났다고 한다!$B$B 내가 정말 강력한 무기를 만들 테니, 그 둘의 시신 조각들을 가져오너라."},objectives={{144,737189796},"마라우돈 깊은 곳에서 산사태의 심장을, 증오의 대장간 채석장에서 부식의 정수를 얻어 에어리 봉우리의 프리그 썬더포지에게 전달하세요."},progress={{39,1385392983},"자, 얘들아, 현실로 돌아와 보자."},completion={{624,343173177},"둘 다 정말 훌륭한 자료들이야. 정말 잘했어. 자, 수고비로 돈 좀 줄게.$B$B브록과 신드리는 전문가이지. 어쨌든 내 아들들이잖아! 언젠가는 서로의 차이점을 극복하고 서로가 하는 일과 자신이 하지 않는 일을 비교해 봐야 할 거야.$B$B브록은 일에 있어서 너무 감정적이야. 갑자기 아이디어가 떠오르면 바로 실행에 옮기지만, 애초에 제대로 될 리 없었다는 걸 깨닫곤 하지. 신드리는 자기 자신에게 너무 엄격해. 자기 능력을 믿지 않아서 뭐든지 원칙대로만 해. 그러다 보니 시야가 좁아지는 거야.$B$B이제 감상적인 얘기는 그만하고, 둘을 제대로 된 자리에 앉혀 놓자!"}}
rows[41143]={title={{20,178287744},"썬더포지 숙련"},description={{252,1538069076},"좋아, 무기는 준비됐어. 저 녀석들 얼굴에 띤 비웃음 좀 봐, 쳇! 대장장이는 자만할 수도 있지만, 겸손함도 똑같이 중요하지. 이제 그 교훈을 제대로 배우게 될 거야. 자,$B$B 여기 남아서 강의를 지켜봐. 정말 재밌을 거야."},objectives={{33,895310852},"썬더포지 강연을 직접 목격하세요."},progress={{18,1944206129},"말만 하세요."},completion={{559,451861320},"생각했던 것만큼 나쁘진 않았군. 이제 드디어 둘 다 어른이 되어 진짜 대장장이가 될 때가 된 것 같군. 오해는 마, 아직 갈 길이 멀지만, 대장장이의 길을 혼자 걸을 필요는 없지. 나도 있고, 자기들도 있으니까. 난 내 아들들을 진심으로 사랑하니까, 이 일을 혼자 내버려 둘 생각은 없나? 게다가, 내가 걔네들을 혼자 두면 내 대장간도 오래 못 버틸 거야!$B$B<프릭의 호탕한 웃음소리가 대장간을 가득 채운다.>$B$B네가 대부분의 작업을 했으니, 내가 만든 이 무기는 네가 가져도 좋아. 진정한 썬더포지 걸작이지!"}}
rows[41144]={title={{15,375434089},"통과의례"},description={{853,1907281269},"알다시피, 우리 와일드해머족은 항상 이 황량한 땅에 살았던 건 아니야. 우리도 예전에는 우리 형제들인 브론즈비어드족처럼 지하에 살았지. 난 우리 위대한 도시 그림 바톨을 본 적은 없지만, 할아버지 베모스가 벽난로 앞에서 그곳에 대한 이야기를 $B$B들려주셨단다. 과거의 와일드해머족과 지금의 와일드해머족이 같다고는 할 수 없어. 그냥 다를 뿐이지. 물론 몇몇 전통은 계승되었지만, 우리 그리핀 기수들에게 더 어울리는 새로운 관습도 만들었단다. $B$B<도란은 당신을 위아래로 훑어보더니 잠시 망설인다.$B$B> <그것들에 대해 알고 싶어? 자, 내가 보여줄게.>$B$B 어린 와일드해머족은 성인이 되기 전에 깃털로 머리 장식을 직접 만들어야 해. 일종의 통과의례라고 할 수 있지. 직접 만들고 싶다면, 오지에서 돌아다니는 올빼미 짐승들에게서 깃털을 좀 얻어오렴. 친구, 여러 가지 색깔의 깃털을 모으는 것도 잊지 마."},objectives={{164,168690824},"에어리 피크에 있는 도란 스틸윙을 위해 힌터랜드의 자야수에게서 붉은 올빼미수수 깃털 10개, 검은 자야수 깃털 10개, 갈색 자야수 깃털 10개를 모으세요."},progress={{107,1136868284},"둥지를 떠나려는 어린 새에게 깃털을 붙여주는 것보다 더 좋은 비행 보조 방법이 있을까요?"},completion={{244,594920740},"도란의 목소리가 약간 떨리는 듯했고, 늙은 드워프는 깃털을 아주 조심스럽게 받아 들었다.$B$B정말 훌륭하군요, 친구분. 저희 전통에 관심을 가져주셔서 진심으로 감사드립니다. 이제 깃털은 확보했으니, 그것들을 넣을 액자를 만들어야겠네요."}}
rows[41145]={title={{16,1644629922},"적절한 틀"},description={{373,1242115114},"보통 어린 녀석들은 직접 가죽을 구하러 사냥을 나가곤 하는데, 자네가 가죽 벗기는 기술에 대해 잘 아는지 모르겠군.$B$B 아래층에 있는 내 친구 드랙 스톤핸드에게 물어보게. 그는 우리 가죽 세공의 달인인데, 그의 솜씨만큼 훌륭한 솜씨는 없을 걸세. 도란이 보냈다고 전해$B$B 줘. 그 오랜 친구가 아직 나한테 신세를 졌거든. 자네 같은 모험가라면 언제든 기꺼이 도와줄 거야."},objectives={{69,2050754308},"에어리 피크에 있는 드락 스톤핸드에게 머리 장식 틀에 대해 물어보세요."},progress={{24,1106595841},"날씨 참 좋네요, 그렇죠?"},completion={{56,1225026823},"네, 에어리 피크에 오신 것을 환영합니다! 제가 도와드릴 일이 있으신가요?"}}
rows[41146]={title={{21,1850322782},"모든 단계"},description={{913,245291431},"도란이 보냈다고? 글쎄, 그는 내 절친한 친구지. 그리고 우리 어린 새들처럼 깃털 장식 머리띠 만드는 걸 도와달라고 했어? $B$B(드락은 잠시 침묵했다.) $B$B와일드해머 방식대로 하려면 가죽을 직접 구해야 해. 그렇지 않으면 정통이 아니잖아? 자, 이렇게 하자. 실버메인 가죽 15장을 구해다 주면 내가 가진 최고급 가죽으로 틀을 만들어 줄게. 뭐라고? 도란이 시켰다고? 내가 그에게$B$B 신세를 졌나? 걱정 마, 도란을 위해서 하는 거지만, 너도 이 모든 과정을 경험해야 하잖아? 우린 널 속이려는 게 아니야, 그렇지?자, 이 가죽 벗기는 칼을$B$B 가져가. 사람들이 말하는 것만큼 어렵지 않아. 그냥 살과 조직에서 가죽을 조심스럽게 잘라내기만 하면 돼. 너희 모험가들이 하는 온갖 베는 짓들을 생각하면 금방 익숙해질 거야. 다만 손은 베지 않도록 조심해, 친구!<드랙은 $B$B낄낄거리며 너에게 가죽 벗기는 칼을 건네준다.>"},objectives={{64,1532177685},"에어리 피크에 있는 드락 스톤핸드에게 실버메인 가죽 15장을 가져다 주세요."},progress={{50,1144237091},"사냥은 잘 되고 있나? 도란 영감님이 너무 오래 기다리게 하지 마!"},completion={{169,1416595541},"나쁘지 않네요, 나쁘지 않아요. 아마추어 치고는 꽤 괜찮네요. 도와주셔서 감사하고, 도란을 위해 이렇게 해주셔서 정말 고맙습니다. 이게 도란에게 얼마나 중요한지 모르실 수도 있어요."}}
rows[41147]={title={{13,147414620},"날개가 잘린"},description={{517,1260102080},"자, 이 액자는 제가 만든 것 중에서도 꽤 훌륭한 작품입니다. $B$B장담하겠어요. 제가 도란을 거의 십 년 동안 알고 지냈는데, 정말 좋은 사람이에요. 마음씨는 착하지만, 아내가 세상을 떠난 후로 예전 같지 않아요. 지금은 멍하니 옛날이야기만 하고 있는데, 분명 당신에게도 얘기했을 거예요. 그런 모습을 보면 정말 마음이 아파요. 액자를 $B$B가져가세요. 도란이 머리 장식을 완성하는 법을 알려줄 겁니다. $B$B<드락은 액자를 건네주고 깊은 한숨을 쉬며 당신을 보낸다.>"},objectives={{55,29921676},"머리 장식 틀을 위층에 있는 도란 스틸윙에게 가져가세요."},progress={{38,271199021},"돌아왔구나, 드락이 내 부탁을 기억하고 있을까?"},completion={{144,490276525},"도란은 떨리는 손으로 천천히 액자를 받아듭니다. 그는 또다시 말을 찾기 어려워합니다.$B$B고마워요, 친절한 친구. 거의 다 끝났어요."}}
rows[41148]={title={{7,1661654039},"그녀를 위해"},description={{996,1770756335},"자, 잘 봐. 우리 와일드해머족은 깃털을 머리 장식에 꿰매는 특별한 기술이 있지. 다른 데서는 배울 수 없어. 대대로 전해 내려오는 기술이거든... (도란이 깃털을 머리 장식에$B$B 꿰매는 모습을 지켜본다. 전보다 더 초조해 보이지만, 틀을 잡고 깃털을 꿰매는 솜씨는 여전히 꼼꼼하고 우아하다.) 좋아, 이게 바로 진짜$B$B 와일드해머족 머리 장식을 만드는 방법이야. 어린 와일드해머족이라면 첫 그리핀 타기 수업에 이걸 쓰고 가야지. 그리핀과 교감하는 동안 이걸 쓰는 건 어린 와일드해머족에게 마법 같은 순간이야. 난 아직도 어제 일처럼 생생하게 기억해. 그래, 어제 일처럼... (도란은 잠시$B$B 말을 멈추고 심호흡을 한다.) 미안해, 친구.$B$B 이건 자네를 위한 거라고 말했지만, 에어리 피크 묘지에 있는 무덤에 그 머리 장식을 놓아주겠나? 입구에서 오른쪽에 있는, 룬 문자가 새겨진 나무들 사이에 있는 묘비야. 만약 자네가 $B$B이것만 해 준다면, 이 늙은 드워프는 자네에게 평생 은혜를 갚겠네."},objectives={{98,411956375},"에어리 피크 묘지에 있는 도란이 묘사한 묘비에 와일드해머 깃털 머리 장식을 놓으세요."},progress={{49,1470204275},"이것이 바로 도란이 당신에게 말했던 묘비임이 틀림없습니다."},completion={{169,1248013695},"당신은 머리 장식을 묘비 위에 올려놓습니다. 묘비에는 \"둘린 스틸윙 - 도란과 시그룬의 사랑하는 아들. 당신의 그리핀이 당신을 가장 높은 곳으로 인도하길.\"이라는 글귀가 새겨져 있습니다."}}
rows[41149]={title={{22,1489296994},"높이 날아오르렴, 꼬마 둘린아"},description={{128,373074516},"묘비를 자세히 살펴보니 도란의 아들 둘린의 묘비였습니다. 당신은 그에게 돌아가 이 일에 대해 이야기하기로 결심합니다."},objectives={{66,1770965803},"도란 스틸윙에게 머리 장식과 묘비에 대해 이야기해 보세요."},progress={{4,220154602},"찬성?"},completion={{830,1495913817},"진실을 전부 말하지 못해서 미안합니다. 오늘이 제 아들 둘린의 열여섯 번째 생일이었거든요. 와일드해머 가문 사람들이 하늘을 나는 존재가 되는 나이랍니다.$B$B도란의 목소리가 떨리고 목이 메는 소리가 들린다.$B$B그는 안타깝게도 세상을 떠났습니다...$B$B사랑하는 시그룬은 그날 이후로 결코 마음의 상처에서 회복하지 못했습니다. 너무나 큰 슬픔에 잠겨 있었죠… 병이 들어서 건강이 급격히 악화되었습니다. 저희는 할 수 있는 모든 것을 다 해봤지만, 결국… 임종을 앞둔 그녀에게 둘린에게 머리 장식을 만들어 주겠다고 약속했지만, 차마 그렇게 할 수 없었습니다…$B$B<도란은 잠시 생각하더니 가방에서 그리핀 조각품을 꺼냈다.>$B$B친구여, 정말 고맙습니다. 당신 덕분에 이 늙은 난쟁이는 마음의 안정을 찾았습니다...이거 받아라, 둘린이 어렸을 때 만들어준 거야...$B$B부디, 집이 필요하다고 느끼실 때가 있다면, 에어리 피크는 언제나 당신을 위해 탁 트인 하늘을 열어드릴 것입니다."}}
rows[41150]={title={{18,867250124},"고장난 메인프레임"},description={{570,776842256},"큰 문제가 생겼습니다. 불량 메인프레임 때문에 휠링 위즈봇들이 오작동을 일으키고 있어요! 지금은 제$B$B 역할을 못 하고 목적 없이 돌아다니기만 합니다. 더 심각한 건 생산에 계속 방해가 된다는 겁니다. 키즈크랙이 이 문제를 해결하라고 저를 독촉하고 있어요.$B$B 혹시 휠링 위즈봇에서 고장 난 메인프레임들을 좀 모아주실 수 있을까요? 그걸 살펴보면 제가 만든 모든 메인프레임을 파괴하지 않고도 해결책을 찾을 수 있을지도 모르겠습니다. 여섯 개면 충분할 것 같습니다."},objectives={{111,1567574783},"발낙 코퍼라이트를 위해 블랙 애쉬 탄광 주변의 회전하는 휘즈봇으로부터 고장난 메인프레임 6대를 회수하세요."},progress={{51,1142584706},"메인프레임이 없으시다면, 저는 바쁘다고 생각해주세요!"},completion={{299,926016586},"<발낙은 잠시 메인프레임을 살펴보며 짜증스럽게 한숨을 크게 내쉬었다.>$B$B구리 배선 불량, 송신기 고장...$B$B이렇게 형편없는 솜씨라니, 최저가 입찰자를 고르지 말았어야 했나 보군. 다시 한번 수고해 주셔서 감사합니다. 이 문제를 해결하려면 꽤 시간이 걸리겠군요."}}
rows[41151]={title={{13,1774538537},"헤이와이어 하복"},description={{551,1552173455},"제 창작물들이 전부 통제 불능 상태가 된 것 같습니다. 처음에는 윙링 위즈봇들이 목적 없이 돌아다니더니, 이제는 배틀치킨들이 문제입니다. 며칠 전부터 날뛰기 시작했는데, 처음에는 명령을 무시하더니 이제는 작업 환경에 큰 피해를 주고 있습니다. 원래 야생 동물을 쫓아내려고 만들었는데, 이제는 득보다 실이 $B$B더 큽니다. 혹시 부탁 하나만 들어주실 수 있을까요? 배틀치킨들을 좀 치워주시면, 수가 줄어들면 새 로봇을 생각해 볼 수 있을 것 같습니다."},objectives={{84,534031680},"발낙 코퍼라이트를 얻으려면 블랙 애쉬 탄광 주변에서 헤이와이어 전투닭 8마리를 처치하세요."},progress={{49,1229184449},"고장난 모델들 정리 다 끝냈어?"},completion={{267,1671245329},"음, 새 구리 변조기를 사용하면 공격력과 제어 기능이 훨씬 뛰어난 배틀치킨을 새로 만들 수 있을 것 같군.$B$B아, 돌아왔군. 그 말썽꾸러기 닭들은 다 처리했나 보군? 자, 도와준 보답으로 동전 좀 줄게."}}
rows[41152]={title={{6,1561667378},"디비-500"},description={{555,275466460},"이제 고장난 메인프레임들을 복구했으니, 더 중요한 임무를 맡기겠습니다. 제가 만든 최고의 걸작, DV-500이 미쳐버렸습니다. 제가 뭘 만들어도 DV-500은 제게 등을 돌리는 것 같습니다. DV-500을$B$B 정말 아끼지만, 그보다 더 소중한 게 있습니다. 바로$B$B 금입니다. 그 고급 처리 장치는 엄청난 돈을 들여 만든 건데, 아무나 가져가서 쓸모없게 써먹을 수 있도록 여기저기 떠돌아다니는 걸 보니 미칠 것 같습니다! DV-500에서 그 처리 장치를 가져와 주십시오. 마지막으로 봤을 땐 여기 북쪽 어딘가였습니다."},objectives={{133,49204490},"DV-500에게서 고급 처리 장치를 회수해 검은바위 섬의 검은재 탄광에 있는 발낙 코퍼라이트에게 가져가십시오."},progress={{26,549648410},"그래서, DV-500을 찾으셨나요?"},completion={{173,1107672149},"아, 드디어 찾았네요. 이거 엄청 비쌌는데, 다시 살 돈이 없었거든요. 정말 고맙습니다.$B$B자, 이거 하나 받아가세요. 도움이 될지도 몰라요."}}
rows[41153]={title={{17,1619274283},"포먼 파이프래치"},description={{381,382769760},"이봐, 꼬맹이! 여기 작업 지시서랑 마감 기한이 있는데, 저 망할 애쉬페더들이 자꾸 방해만 하잖아. 빨리 결과를 내야 해. 이 주변 독수리들을 없애버려야 우리 부하들이 제대로, 방해받지 않고 작업할 수 있어. 네가 빨리 조치를 취해줄수록 내가 이 엉뚱한 일정들을 더 빨리 끝낼 수 있을 거야."},objectives={{99,370352805},"블랙스톤 섬의 블랙 애쉬 탄광에서 포어맨 파이플래치를 위해 애쉬페더 스캐빈저 10마리를 처치하세요."},progress={{5,921233587},"무엇?"},completion={{80,130272590},"드디어 좋은 소식이 나왔네요! 자, 이것 중 하나를 가져가시고, 제 길에서 좀 비켜주시겠어요?"}}
rows[41154]={title={{13,238969780},"비참한 일"},description={{465,1017924103},"너! 머리 없는 멀록처럼 어슬렁거리고 있는 거냐? 우리 할당량이 부족한데 너 같은 게으른 고블린들이 귀중한 금을 탕진한다고 상황이 나아질 리 없어! 듀로타르 노동조합은 본연의 수익성 좋은 일로 돌아가지 않으면 망할 거라고! $B$B어서 나가서 석탄 광산 주변에서 석탄을 캐내 와! 본보기를 보여줘야 할 거야. 너무 오래 머뭇거리면 깡패를 보내서 확인해 보겠다!"},objectives={{112,1092040316},"블랙애쉬 탄광 주변의 석탄 더미에서 석탄 열 개를 모아 키즈크랙 감독관에게 가져다 주십시오."},progress={{62,992270289},"손이 여전히 초록색이라면, 충분히 열심히 일하지 않는 겁니다!"},completion={{102,1066147959},"당신 참 빠르시군요! 제 앞에 완전히 쓸모없는 바보가 없어서 얼마나 다행인지 몰라요."}}
rows[41155]={title={{19,604000612},"로봇 전문가"},description={{550,1605900181},"우리 고블린들은 온갖 기계와 도구를 사용해서 노동을 최대한 쉽고 편안하게 만드는 것으로 유명하죠. 파쇄기라는 기발한 발명품을 생각해 보세요! 사람이 조작하는 다른 어떤 장비도 파쇄기만큼 빠른 속도로 나무를 베어낼 수는 없을 $B$B겁니다. 발낙 코퍼라이트는 우리 작업 기계 정비 담당이에요. 제가 이 엉망진창인 작업장을 정리하느라 정신이 없었는데, 밖에서 그 녀석이 끊임없이 욕하고 고함치는 바람에 머리가 아팠어요. 그 녀석한테 가서 무슨 문제든 해결해 주세요. 어떻게 하든 상관없으니, 그냥 입 좀 다물게 하고 빨리 끝내세요!"},objectives={{36,1408902018},"발낙 코퍼라이트에게 밖에서 말을 걸어보세요."},progress={{9,555438445},"흠? 뭐라고요?"},completion={{122,456304071},"당연히 내가 목청껏 소리 지르는 이유는 내 주변에 평생 자이로스패너 한 번 잡아본 적 없는 바보들뿐이기 때문이지!"}}
rows[41156]={title={{15,1648104365},"포먼스 블루스"},description={{516,1345139056},"너무 앞서가지 마세요. 당신과 홉고블린을 구분하는 유일한 차이점은 작업 속도뿐인데, 그것조차도 개선할 여지가 많습니다. 더 많은 일을 끝내는 것보다 더 좋은 방법이 있을까요? 그렇죠?근처 독수리들이$B$B 우리를 괴롭히고 작업 일정을 방해하고 있습니다. 아래 갱도의 파이플래치 반장이 이 문제를 처리하도록 지시받았지만, 다른 사람들을 어느 정도 통제할 수 있는 고블린조차도 처음 마주치는 문제에 당황하는 것 같습니다. 그곳에 가서 뭔가 조치를 취할 수 있는지 확인해 보세요."},objectives={{50,1171852015},"바로 바깥 갱도에 있는 포먼 파이프래치에게 말을 걸어보세요."},progress={{17,2037304073},"무엇을 원하세요?"},completion={{179,1270465311},"나는 이 쓸모없는 일꾼들과 깃털 달린 성가신 존재들 때문에 정신이 없어. 만약 당신이 이 두 가지 문제 중 하나라도 해결하러 온 게 아니라면, 당장 꺼져버려!"}}
rows[41157]={title={{17,971035425},"배송 지연"},description={{550,393021497},"물자가 부족해지기 시작했습니다. 듀로타르의 스파크워터 항구에서 오는 물자 수송을 기다리고 있었는데, 배가 남쪽 해안에서 원인 모를 공격으로 좌초되었습니다. 선원 대부분은 물고기 밥이 되었지만, 선장과 일등 항해사는 살아남아 현재 난파선을 조사하고 있습니다. 저는 언제쯤 $B$B물자가 도착할지 알고 싶습니다. 저는 결과와 재정적 성장을 위해 여기 있는 거지, 말장난이나 동정을 원하는 게 아닙니다. 여기 바로 남쪽 해안 절벽에 있는 다즐론 브래스디거에게 침몰한 물자를 인양하는 데 어떻게 할 수 있는지 물어보세요."},objectives={{95,761948251},"블랙애쉬 탄광 남쪽에 사는 다즐론 브래스디거에게 물어보면 그의 배 잔해에 대해 더 자세히 알 수 있을 겁니다."},progress={{26,1658468881},"아, 이건 정말 끔찍하네요!"},completion={{176,978656110},"키즈크랙은 지금 내 걱정거리 중 가장 사소한 문제야. 이 난파선에서 최대한 빨리 가져와야 할 물건들이 있는데, 이 거대한 바닷가재들 때문에 그걸 가져올 수가 없어!"}}
rows[41158]={title={{19,926193742},"심연의 복수"},description={"We've encountered many ghastly creatures on our voyages. From murlocs to naga, sharks to hydras. But personally, nothing from the depths gives me more shivers than these shelled horrors with their giant, snappy claws! Just look at them: the long, beady eyes, the razorsharp legs and their barnacle covered shell - UGH!$B$B$n, go down there and show them what they get for sinking my ship and making a feast out of my crew!","우리는 항해 중에 수많은 끔찍한 생물들을 만났지. 멀록부터 나가, 상어부터 히드라까지 말이야. 하지만 솔직히 말해서, 심해에서 나를 가장 오싹하게 하는 건 거대하고 날카로운 발톱을 가진 이 껍데기 괴물들이야! 저것들을 봐봐: 길고 동그란 눈, 면도날처럼 날카로운 다리, 따개비로 뒤덮인 껍데기까지 – 으악!$B$B$n 저놈들을 저 아래로 보내서 내 배를 침몰시키고 선원들을 잡아먹은 대가를 치르게 해 줘야겠어!"},objectives={{115,2055017138},"블랙스톤 섬 남서쪽 해안에서 마크루라에게 복수하고 다즐론 브래스디거에게 보고하십시오."},progress={{152,163367904},"스파크워터 항구의 누구도 이 해역에 마크루라와 멀록이 우글거린다고 말해주지 않았어요. 솔직히 말해서, 이런 일이 벌어질 거라고 예상하지 못할 이유는 없었죠."},completion={{94,1978776495},"잘 됐군. 교수형 집행인의 약탈자 조직원을 건드리지 말라는 교훈을 얻게 될 거야."}}
rows[41159]={title={{30,1207602293},"더러운 행위들이 깊은 바닷속에 가라앉았다"},description={"Do you even have the slightest idea what kind of disaster this is? First, my ship got wrecked on this backwater island. Secondly, my entire crew besides Ranala either drowned or got devoured by these lobster things down there. And thirdly - most importantly! - I lost my log book when we jumped ship!$B$BYou may think a soggy, old log book might not be worth it, but there are things inside this book that CANNOT make it to any of the higher ups here on this island. And I mean it! I swear it on the life of my rich grandmother back in Undermine!$B$B$n, while you're down there, look for any signs of the Hangmans Plunder's log book. Should you find it, I will pay you with good and honest coin!","이게 얼마나 심각한 재앙인지 조금이라도 아시나요? 첫째, 제 배가 이 외딴 섬에 좌초됐습니다. 둘째, 라날라를 제외한 선원들은 모두 익사하거나 저 아래 바닷가재 같은 것에 잡아먹혔습니다. 그리고 셋째, 가장 중요한 건! 배에서 뛰어내릴 때 항해일지를 잃어버렸다는 겁니다!$B$B 눅눅하고 낡은 항해일지가 별것 아니라고 생각할지도 모르지만, 이 책 안에는 이 섬의 높은 사람들에게 절대 알려져서는 안 될 중요한 내용이 들어 있습니다. 정말이에요! 언더마인에 계신 제 부유한 할머니 목숨을 걸고 $B$B$n맹세합니다! 그러니, 저 아래에 내려가서 교수형 집행인의 약탈호 항해일지를 찾아보세요. 만약 찾으면, 제가 값진 돈을 드리겠습니다!"},objectives={{124,1506372253},"블랙애쉬 탄광 남쪽의 난파선에서 교수형 집행인의 약탈자 항해일지를 회수하여 다즐론 브래스디거에게 가져다주십시오."},progress={{116,1247087595},"만약 그 안에 담긴 정보가 키즈크랙이나 러스트게이트에까지 전해진다면, 난 스파크워터 항구의 구덩이 중 하나에 처박히게 될 거야!"},completion={{285,148034080},"오! 내 사랑하는 항해일지! 정말 천국 같은 소식이군! 이제 항해일지를 되찾았으니, 이 일은 비밀로 해 줄 수 있을까? 걱정 마, 키즈크랙에 대한 그럴듯한 변명거리를 준비해 뒀어. 자, 이거 받아가서… 비밀로 해 줘, 알았지? 굳이… 음… 복잡하게 생각할 필요 없어, 알겠지? 제발?"}}
rows[41160]={title={{13,1285158128},"바닷속"},description={{676,1277215961},"저것 좀 봐. 부서진 껍데기일 뿐이야. 다즐론과 내가 우리만의 배를 마련하고, 더 나아가 이런 호화로운 생활을 누리기 위해 얼마나 오랫동안 일했는지 알아? 아마 모를걸. 절대 모를 거야.$B$B있잖아, 난 저 배에서 꽤 큰돈을 벌었어. 여러 번의 거래와 그 외 좀 더… 비정상적인 일들을 통해 배를 구해냈지. 바다의 여인들에게는 흔한 일이긴 하지만. 난 이 배를 위해 몇 달, 거의 일 년을 일했는데, 이제 모든 게 사라지고, 심해에 $B$B가라앉았어.$네가 다즐론을 찾으러 난파선에 간다고 들었어. 찾을 수 있을 거라는 희망은 없지만, 혹시라도 그곳 어디에서든 금화가 가득 든 녹색 뭉치를 발견하게 된다면, 제발 내게 가져다 줘."},objectives={{146,681332455},"라날라의 침몰한 보물을 찾으세요. 난파선 잔해에 없다면 마크루라가 가져갔을지도 모릅니다. 보물을 찾은 후 블랙 애쉬 탄광 남쪽에서 라날라에게 가져다 주세요."},progress={{78,350632071},"배는 부서지고 선원들은 모두 떠났으니, 이 금괴만이 내게 남은 전부다."},completion={"<Wide eyes and an extreme expression of bewilderment can be seen on Ranala's face.>$B$BI can't believe my eyes! My gold pouch, it's... it's here! But... it seems to have lost some coins through this hole here. Regardless, most of it is still here. $n, thank you so much. Here, this is for your troubles. When we get back, we'll tell the superiors of what you did here.","<라날라의 얼굴에는 눈이 휘둥그레지고 극도로 당황한 표정이 드러났다.>$B$B믿을 수가 없어! 내 금화 주머니가… 여기 있잖아! 그런데… 이 구멍으로 동전이 좀 빠져나간 것 같아. 그래도 대부분은 남아있어.$n정말 고마워. 자, 이건 수고비야. 돌아가면 상관에게 네가 한 일을 보고할게."}}
rows[41161]={title={{20,2146340069},"슈퍼커터 1500"},description={{852,48036196},"블랙 애쉬 탄광에서 여기까지 오셨으니 아마 그 크고 육중한 기계를 보셨을 겁니다. 가치크는 그걸 자신의 걸작이라고 생각하죠. 바로 슈퍼커터 1500입니다! 그걸로 우리는 어떤 파쇄기보다도 훨씬 빠르게 이 섬의 자원을 수확했습니다. 정말 대단한 기계였죠. 그런데 어떤 멍청이가 그 기계를 진흙탕에 처박아 버리는 게 참 안타깝습니다. 정말 획기적인 일이었는데, 그 자식을 잡아서 목 졸라 죽여버리고 싶을 정도입니다. 우리 작업 효율을 $B$B그렇게 망쳐놓다니. (판조는 한숨을$B$B 쉬며 관자놀이를 문지른다.) 그렇게 오래전 일은 아니지만, 그날 누가 조종했는지 기억이 안 나네요. 게다가 이 과도한 작업 일정 때문에 아직 피해 규모를 파악하지 못했습니다. 추락 현장에 가서 얼마나 심하게 파손됐는지 확인해 보세요. 그리고 슈퍼커터의 리모컨도 가져와서 고장 여부를 점검해 봅시다."},objectives={{137,1965705549},"블랙 애쉬 탄광 북쪽에 있는 슈퍼커터 1500에서 슈퍼커터 1500의 리모컨을 가져와 가치크의 작업장에서 판조 에지라인에게 전달하세요."},progress={{82,1967744919},"진짜, 이거 진짜 느리게 움직이네. 이걸 어떻게 진흙탕에 처박을 수 있지?!"},completion={{305,1391982841},"뭐라고요? 동료들이 당신을 공격했다고요? 미쳤어요? 당장 러스트게이트에 신고해야 해요!$B$B어쨌든 리모컨을 되찾아줘서 고맙습니다. 가치크에게 내부를 살펴보라고 할게요. 결국엔 제가 직접 해야겠지만요.$B$B<판조는 다시 한번 깊은 한숨을 내쉰다.>"}}
rows[41162]={title={{18,450289365},"골칫거리 제거"},description={{572,1012719069},"조수라면 상사 일의 절반만 할 줄 알았는데, 전혀 아니군! 모두가 일에 파묻혀 허덕이는 동안, 나를 포함해서 말이야! 가치크는 세상 걱정 하나 없이 매일같이 이것저것 만지작거리고 있어. 러스트게이트랑 무슨 꼼수를 부렸는지는 모르겠지만, 효과는 확실한$B$B 것 같군! 게다가 보급로는 침 질질 흘리는 놀들이나 야생 동물들 때문에 끊임없이 차단당해서 작업이 더 지연되고 있어. $B$B그래도 뭐, 넌 능력은 있어 보이니. 다리 건너가서 고블린 빼고는 다 처리해 와!"},objectives={{91,1159728944},"가치크의 작업장에서 판조 에지라인을 얻으려면 애쉬페더 스캐빈저와 블랙베놈 스콜피드를 처치하세요."},progress={{98,753693723},"다 끝났어요? 빨리 끝내실수록 제가 다른 문제들을 처리할 수 있거든요."},completion={{95,2100512756},"감사합니다. 일이 너무 많아서 머리가 아프네요. 드디어 믿을 만한 인력을 확보하게 되어 기쁩니다."}}
rows[41163]={title={{19,922557461},"배틀트론 재앙"},description={{703,1700982530},"저는 투자개발회사가 섬에 나타나기 시작하면서 벌어진 전투에 투입할 전투 로봇 몇 대를 제작하라는 의뢰를 받았습니다. 하지만 제가 만들던 전투 로봇들의 재료가 바로 우리가 싸우고 있는 적들이 만든 것이라는 사실을 미처 몰랐습니다. 결과적으로 새로 투입된 로봇들은 모두 골칫거리가 되어버렸습니다. 택슬로는 $B$B금을 아끼려다 섬 전체를 위험에 빠뜨렸고, 다행히 그들이 우리를 배신하지는 않았습니다. 어쨌든 이 난장판을 수습해야 하는데, 목적 없이 돌아다니는 로봇들이 여전히 문제를 일으킬 $B$B수 있습니다. 대부분의 로봇들은 이곳 서쪽 러스트게이트 능선 남쪽에서 돌아다니고 있으니, 적의 손에 넘어가지 않도록 파괴해 주십시오."},objectives={{88,876811845},"블랙스톤 섬에 있는 가치크의 작업장에서 가치크를 위해 고장난 배틀트론 1000 10대를 파괴하세요."},progress={{32,2007149516},"그럼, 그런 결함 있는 봇들을 부숴버리는 건가요?"},completion={{145,1247076267},"잘했어, 꼬마야. 오랜만에 믿을 만한 사람을 만나서 좋네. 택슬로랑은 원하는 걸 실제로 받을 수 있을지 확신할 수 없거든."}}
rows[41164]={title={{17,1913748585},"호송대 구조"},description={{784,528486375},"당신이 탄광에서 온갖 난장판을 치우던 그 유망한 일꾼이십니까? 뭔가 대단한 일을 하고 계신 게 분명합니다. 제 형은 탄광에서 몰래 탑에 들어오는 사람은 누구든 쫓아내거든요. 솔직히 말씀드리면, 당신의 능력이$B$B 절실히 필요합니다. 지난 몇 주 동안 반란을 일으킨 놀들의 매복 공격이 점점 더 심해지고 있습니다. 그놈들의 작은 뇌는 폭력과 혼란만을 추구하는데, 보급 담당자인 저로서는 도저히 이해할 수 없습니다. 그들은 우리 보급 수송대를 습격해서 주로 식량과 무기를 훔쳐갔지만, 도구는 대부분 그대로 남겨두었습니다. 아마도 그들에게는 너무 어려운$B$B 기술이었겠죠. 그 도구들을 최대한 빨리 되찾아야 합니다. 독수리와 하이에나가 부서진 수레 주변을 배회하며 여기로 돌아오지 못한 사람들을 뜯어먹고 있습니다. 섬 곳곳에 흩어져 있으니 찾기 어렵지 않을 겁니다."},objectives={{127,1349997209},"블랙스톤 섬 곳곳에 흩어져 있는 파괴된 수송대에서 러스트게이트 도구를 회수하세요. 회수한 도구를 러스트게이트 능선에 있는 보급 책임자 맥슬로에게 가져다 주세요."},progress={{110,1609815345},"스파크워터로부터 원하는 만큼 새로운 물자를 공급받지 못하고 있어서 최대한 많은 물자를 회수해야 합니다."},completion={{168,344134154},"음, 날씨가 좋지 않았네요. 하지만 작업자들이 복구하지 못할 일은 없을 겁니다. 모두 수고하셨습니다. 이대로 계속 노력하면 이 섬에 곧 정상적인 모습이 돌아올 수 있을 거예요."}}
rows[41165]={title={{15,2076696311},"사막처럼 메말랐다"},description={{460,687114099},"이 섬에서 가장 중요한 게 뭐라고 생각하세요? 당연히 물이죠! 택슬로의 대답도 좋았지만, 그조차도 노동자들이 튀긴 플랜틴처럼 쪼그라들면 일을 계속할 수 없다는 건 인정해야 할 겁니다. 북쪽으로 $B$B광산을 지나면 블랙스톤의 물웅덩이가 있습니다. 펌프 책임자 갈박스에게 러스트게이트 리지에 물을 보내라는 명령이 내려졌는데, 생각보다 시간이 오래 걸리고 있습니다. 왜 이렇게 오래 걸리는지 물어보세요!"},objectives={{87,452351679},"워터홀의 펌프마스터인 갈박스에게 문의하시면 누락된 물 공급에 대해 자세히 알아볼 수 있습니다."},progress={{30,2047968890},"러스트게이트에서 아직 한참 멀었네요, 친구."},completion={{115,136372324},"물 수송 말인가요? 네, 저도 알고 있습니다. 뒤쪽 절벽 위를 보시면 물이 어디로 갔는지 보실 수 있을 겁니다."}}
rows[41166]={title={{14,1068633182},"복구"},description={{576,1994775735},"혹시 코퍼라이트가 탄광에서 벌인 기계 난동을 도와주셨나요? 그가 자기 기계에 추가 개조를 위해 부품 몇 개를 요청하고 있거든요. 그가 원하는 부품은$B$B 안타깝게도 제 창고에는 없지만, 가직의 작업장에서 러스트게이트 리지로 새 물품을 보낼 예정입니다. 가직은 좀 게으른 편이긴 하지만, 이 섬에는 그와 같은 사람이 없어서 택슬로는 그의 꼼수를 눈감아주고 있습니다. 그의 작업장은 남동쪽, $B$B임시 다리를 건너면 있습니다. 가직에게 물어보면 물품이 어디 있는지 알 수 있을 겁니다. 물품을 받으면 저에게 가져다주세요."},objectives={{101,780109098},"가직의 작업장에서 재조정된 프레임워크 상자를 러스트게이트 리지의 보급 책임자 맥슬로에게 가져다 주세요."},progress={{52,22254507},"시간이 오래 걸릴수록 해야 할 일이 더 많이 쌓입니다."},completion={"Ah, there they are. I will have them be delivered to Copperlight once another worker shows his mug around here. Thank you, $n, I will mention this on your monthly resume.","아, 여기 있네요. 다른 직원이 나타나면 코퍼라이트로 배송하도록 하겠습니다.$n님, 감사합니다. 이 내용을 월간 이력서에 기재해 드리겠습니다."}}
rows[41167]={title={{17,1660288009},"멀록의 위협"},description={{565,1365321072},"좋아, 잘 들어. 너 멀록 싫어하지? 좋아. 멀록을 싫어하는 사람은 누구나 있지. 멀록의 먹이가 되지 않는 사람들은 예외지만 말이야. 그리고 난 우리 일꾼 중에 멀록의 한밤중 간식이 되는 꼴은 절대 보고 싶지 않아. 그러니$B$B 해안가로 가서 그 끈적끈적한 물고기 떼를 최대한 많이 처치해 와. 난 그 미끈미끈한 생물들을 상대하느니 차라리 게으름뱅이들을 때려눕히는 게 낫겠어. 그리고 죽인 척만 하지 마. 그런 짓을 하면 내가 직접 널 최고 감독관에게 끌고 갈 거야. 멀록 비늘을 가져와서 네가 믿을 만한 사람이라는 걸 증명해 봐."},objectives={{102,1400187594},"블랙스톤 섬 해안에서 멀록을 사냥하여 그 비늘 20개를 브루저 라클란에게 바치십시오."},progress={{95,618348109},"라클란은 초조하게 몽둥이를 손에 들었다 놓았다 하며 당신을 위협하고 있습니다."},completion={{122,1942354847},"나쁘지 않군, 꼬맹아. 덕분에 네 게으른 동료들을 다시 엉망으로 만들 시간이 좀 더 생겼어. 정말 고맙다."}}
rows[41168]={title={{14,1672004888},"해양 검보"},description={{761,260129010},"안녕, 친구! 러스트게이트 덕분에 우리는 여기서 호화롭게 살고 있지. 저 아래 구덩이에 사는 불쌍한 사람들과는 달리 말이야. 하지만 여기선 원래 그런 거야. 이게$B$B 바로 인생의 복권 당첨이지!<샤즐란이$B$B 이상하고 코맹맹이 소리를 내며 웃는다.>어, 이왕 여기까지 온 김에, 사실 좀 도와줄까? 러스트게이트가 요리에 있어서는 좀… 별난 취향을 가지고 있거든. 할머니가 케잔에서 만들어 주시던 해산물 검보를 다시 만들어 달라고 하더라. 보통은 문제없지만, 여기는 재료가 별로 없거든. 아, 그런 눈으로 보지 마. 정말이야!$B$B네가 크롤러 고기랑 마크루라 다리를 가져다주면 내가 만드는 법을 가르쳐 줄게. 사장님을 만족시켜야 할 때 유용할지도 몰라."},objectives={{75,240758289},"필요한 재료들을 모아서 러스트게이트 리지에 있는 샤즐란에게 가져다 주세요."},progress={{102,683085026},"이곳 동쪽 해변에서는 크롤러들이 재빨리 기어 다니고, 서쪽 난파선에서는 마크루라가 목격되었습니다."},completion={{248,1787513297},"개인적으로는 고기를 더 좋아하지만, 해산물 요리가 가진 매력도 인정합니다. 이 재료들로 든든한 검보를 만드는 건 어렵지 않을 거예요. 필기구를 준비하고 집중해서 보세요! 러스트게이트를 더 이상 기다릴 순 없잖아요."}}
rows[41169]={title={{18,457386182},"나쁜 소식을 전하는 사람"},description={{854,131741067},"이 섬을 잘 봐. 뭐가 보이지? 바로 그거야. 우리가 돈을 잃고 있는 게 보이지! 우리가 왜 돈을 잃는지 이유를 말해준다면, 우린 여기서 밤새도록 있어야 할 거야. 난 그럴 여유가 없고, 너도 마찬가지야. 블래스텐톰이 이 섬을 돈벌이 수단으로 만들자고 했을 때 난 귀를 기울였지만, 이건 내가 원했던 $B$B게 절대 아니야! 블래스텐톰은 여기 상황에 대한 보고서를 내게 요구하고 있어. 난 절대 그의 분노를 사고 싶지 않아. 다행히도 네가 나 대신 가주겠군. 이걸 가져가서$B$B 듀로타의 스파크워터 항구에 있는 네르트 블래스텐톰에게 가져다 줘. 헤엄쳐서 돌아오고 싶진 않을 테니, 가치크의 작업장에서 차를 얻어 타. 돈은 각오해야 해. 여긴 자선 가게가 아니야. 내일까지 돌아오지 않으면 체포 영장을 발부하고 탈영죄로 처형할 거야!"},objectives={{111,179199607},"가치크의 작업장에서 탑승료를 지불하고 러스트게이트 사업 보고서를 스파크워터 항구에 있는 네르트 블래스텐톰에게 가져다 주세요."},progress={{61,1411902198},"어머, 온몸에 재와 석탄이 묻었네. 잘 지내, 동족 고블린?"},completion={{148,551337305},"<블라스텐톰은 보고서를 읽으며 점점 더 붉어지는 얼굴에 땀이 줄줄 흘렀다.>$B$B도대체 그 섬에서 무슨 일이 벌어지고 있는 거야?!"}}
rows[41170]={title={{22,743000778},"해결책이 곧 나올 것입니다"},description={"This is a complete disaster! How could this happen in such a short span of time? Not only is this a monetary failure, but also a potential threat to our alliance with the Horde! I promised our benefactors in Orgrimmar new resources at a steady rate, but with what's happening on Blackstone Island, this will just be wishful thinking.$B$B$n, take the next trip back to Blackstone Island and assist Rustgate in salvaging this mess of an operation. Now go, I want to see results!","이건 완전 재앙이야! 어떻게 이렇게 짧은 시간 안에 이런 일이 벌어질 수 있지? 금전적인 실패일 뿐만 아니라 호드와의 동맹에도 잠재적인 위협이 될 수 있어! 오그리마의 은인들에게 꾸준한 자원 공급을 약속했는데, 블랙스톤 섬에서 벌어지고 있는 일들을 보면 그건 그저 헛된 희망일 뿐이야. , 다음번에$B$B$n 블랙스톤 섬으로 돌아가서 러스트게이트가 이 엉망진창인 상황을 수습할 수 있도록 도와줘. 자, 어서 가! 결과를 보여줘!"},objectives={{47,2070442378},"블랙스톤 섬의 택슬로 러스트게이트로 돌아가십시오."},progress={{27,1642782145},"잠깐, 네 못생긴 얼굴 알아."},completion={{147,2017536180},"블래스텐톰이 지금 상황이 마음에 안 든다고? 놀랍군. 우리 둘 다를 위해서라도, 내 탑에서 나가서 이 난장판을 치우는 것부터 시작해!"}}
rows[41171]={title={{18,534175366},"잔해 수색"},description={{736,1077427176},"자네 난파선 잠수에 익숙하다고 들었네? 오, 놀랐나 보군? 이 자식아, 내 귀에는 아무것도 안 들려. 그러니까 여기서 수상한 짓 할 생각 하지 마. 금화라고 말하기도 전에 덩치 큰 놈을 네 뒤에 붙여줄 $B$B테니까.동쪽 해안에 또 다른 배가 난파됐군. 해적선은 아니고, 스파크워터 항구에서 온 배야. 상자도 많고 새 일꾼들도 타고 있었지. 쓸만한 물품은 대부분 건졌지만, 항해일지는 못 찾았네. 뭐라고? 응, 배에 타고 있던 고블린 몇 마리도 죽었어. 하지만 내 생각엔 단순한 난파도 못 견뎌 하는 놈들이라면 블랙스톤은 놈들이 있을 곳이 아니야.항해일지를$B$B 가져와. 그리고 그 주변에 멀록들이 많으니 조심해. 이 망할 항해일지 건지느라 더 이상 일꾼들을 잃고 싶지 않아."},objectives={{64,649462362},"벤처 회사 항해일지를 회수하여 택슬로 러스트게이트로 가져오십시오."},progress={{20,1731667589},"시간이 얼마 남지 않았어요."},completion={{114,1414610485},"바로 이런 모습이 제가 원하던 겁니다. 단 열두 번의 시도 만에 성공했네요. 이 목록들을 보면 맥슬로는 정말 기뻐할 거예요."}}
rows[41172]={title={{18,1025078148},"투자개발회사에 대한 전쟁"},description={"Potential is what I see in you, $n. Not many here show it. But you might be the goblin I'm looking for.$B$BMaybe you've witnessed it already or you're just ignorant to the issue, but we're having problems with the... willingness of some workers out here. Call it a strike, sabotage, revolt - I don't care. They're costing me money instead of making it and I'm not having it. If that wasn't enough, their overly aggressive behaviour is a threat to the obedient workers we still have.$B$BOur bruisers got their hands full with keeping order around here, so you will be my instrument of justice. Go out and quell their uprising, immediately. Their medallions will do nicely as proof. According to reports, most of the hostile activity originates from the slum up north.",", 자네에게서 잠재력을 보네.$n 여기선 그런 모습을 보이는 사람이 많지 않지만, 자네가 바로$B$B 내가 찾던 고블린일지도 모르겠군.이미 목격했거나 아니면 모르고 있는 걸지도 모르지만, 여기 일부 노동자들의… 태도에 문제가 생겼어. 파업이든, 사보타주든, 반란이든 상관없어. 그들은 돈을 벌어들이기는커녕 손해만 끼치고 있고, 난 그걸 용납할 수 없어. 게다가 그들의 지나치게 공격적인 행동은 아직 남아있는 순종적인 노동자들에게도$B$B 위협이 되고 있어.우리 깡패들은 지금 질서 유지에 정신이 없으니, 자네가 내 정의의 도구가 되어주겠네. 당장 나가서 그들의 반란을 진압해. 그들의 메달이 증거로 충분할 거야. 보고에 따르면, 대부분의 적대 행위는 북쪽 슬럼가에서 비롯된다고 하네."},objectives={{72,1736882674},"벤처 컴퍼니의 배신자들을 처단하고 그들의 메달을 택슬로 러스트게이트로 가져오세요."},progress={{197,65233926},"나는 들판에서 꽃을 꺾고 노래를 흥얼거려서 최고 감독관이 된 것이 아니다. 질서를 유지하는 데 있어 나의 확고한 의지가 나를 이 자리에 올려놓은 것이다. 그리고 나는 내 권위가 훼손되는 것을 용납하지 않을 것이다."},completion={{137,1230991870},"훌륭해. 신속하고, 냉혹하고, 효율적이야. 이대로 계속하면 크게 성공할 거야, 장담해. 그리고 가기 전에, 아직 끝난 게 아니야."}}
rows[41173]={title={{33,778315678},"벤처 기업 리더십 파괴"},description={{719,517933955},"우리가 파악한 바로는, 이 저항은 단순한 노동자들의 불만 표출이라고 하기엔 너무나 조직적입니다. 누군가 사주했을 겁니다. 우리가 아무리 철저해도, 배후에 누가 있는지 짐작 가는 바가 있습니다. 겔벡스 골드핑거스와 $B$B덱스 로드스파크. 은혜를 모르는 놈들입니다. 둘 다 말썽꾼으로 악명이 높았지만, 깡패들이 처리할 수 없는 정도는 아니었습니다. 하지만 그들은 단순히 일을 게을리하는 것 이상의 사악한 계획을 꾸미고 있었던 것 같습니다. 그들이 무슨 계획을 꾸미든, 당신은 반드시 막아내야 합니다. 본보기를 보여주고 이 섬의 모든 사람들에게 그들의 행동에 대한 유일한 처벌은 사형이라는 것을 보여주십시오. $B$B그들은 아마도 슬럼가에 있는 공모자들 중 하나일 겁니다. 이 일을 처리하기 전까지는 돌아오지 마십시오."},objectives={{80,1233447268},"저항군 지도부를 제거하고 그들의 머리를 택슬로 러스트게이트로 가져오십시오."},progress={{36,661721125},"<택슬로는 엄격한 눈빛으로 당신을 바라봅니다.>"},completion={"<Taxxlo grabs the heads by the ears and lets out a laugh audible in all of Rustgate Ridge.>$B$BLook at this, $n. This is what awaits those who betray not only the Durotar Labor Union, but also ME. Nobody on this island will question my authority and proficiency ever again! Your future is promising, young worker. Goblins like you will be the key to get this machine back on track.$B$BTo reward you for your hard work, take one of these and tell everyone what those in my favor can expect.","<택슬로는 머리들을 귀를 잡고 러스트게이트 리지 전체에 울려 퍼지는 웃음소리를 냈다.>$B$B이것 좀 봐라,$n. 듀로타르 노동조합뿐 아니라 나까지 배신하는 자들에게는 이런 일이 기다리고 있다. 이 섬에서 다시는 내 권위와 능력을 의심할 자가 없을 것이다! 젊은 노동자여, 너희의 미래는 밝다. 너희 같은 고블린들이 이 시스템을 다시 정상 궤도에 올려놓을 열쇠가 될 것이다.$B$B너희의 노고에 대한 보상으로 이것 중 하나를 받아라. 그리고 내게 호의적인 자들이 무엇을 기대해야 하는지 모두에게 알려라."}}
rows[41174]={title={{16,1093190820},"직장 위험"},description={{844,1547984487},"블랙스톤의 상황은 예상했던 것보다 훨씬 심각합니다. 처음 이 섬에 와서 채굴 로봇을 만들어 달라는 요청을 받았을 때는 순조롭게 진행되는 것 같아 기뻤습니다. 하지만 현실은 적대적인 작업$B$B 환경과 계약에 걸맞은 작업을 제대로 수행할 만큼의 자재조차 부족한 상황이었습니다. 이제 저는 이 문제를 해결할 때까지 인질로 잡힌 채 이곳에 갇혀 있습니다. 제가 받은 자재가 너무 형편없어서 구리선이 부식되면서 채굴 로봇들도 고장 나기 시작했습니다. 지금은 로봇들이 섬 곳곳을 목적 없이 돌아다니고 $B$B있습니다. 혹시 큰 부탁 하나만 들어주시겠습니까? 고장 난 채굴 로봇들을 찾아서 파괴해 주시겠어요? 작업 현장에 위험을 초래하고 있는 것 같습니다. 섬 곳곳에서 찾을 수 있을 텐데, 대부분은 이곳 북쪽에 있는 블랙 애쉬 광산으로 보내졌습니다."},objectives={{92,1598810275},"블랙스톤 섬의 러스트게이트 능선에서 기술자 레이보를 위해 고장난 광산 로봇 8대를 처치하세요."},progress={{105,730837893},"택슬로와 그의 부하들이 내게 제대로 된 재료를 줬더라면, 애초에 이런 문제는 발생하지도 않았을 거야!"},completion={{197,1214950789},"드디어 좋은 소식이군! 이제 이 황금 없는 바위섬에서 벗어나 내 본래의 길로 돌아갈 수 있어.$B$B정말 고마워. 이것들을 가져가. 이 끔찍한 곳을 헤쳐나가는 데 도움이 될 거야."}}
rows[41175]={title={{20,822902364},"머드포우 광산 사고"},description={{546,880735643},"정말 큰 재앙이 닥쳤어. 택슬로가 알게 되면 내 목을 칠 거야. 며칠 전 밤, 여기 북쪽에 있는 블랙 애쉬 광산에서 공격을 받았어. 머드포우 놀들이 와서 우리를 쫓아내고, 그 과정에서 내 일꾼들을 많이 죽였지. 그런데 이제는 그놈들이 직접 광물을 캐고 있어! 그 얼간이들! 더 심각한 건 $B$B광산 근처에 있던 보급품들을 전부 잃어버렸다는 거야. 이제 그 망할 놀들이 그걸 다 써버리고 있어. 블랙 애쉬 광산으로 가서 보급품 상자 여덟 개만이라도 가져와 줘. 그래야만 이 재앙에서 내 목숨이라도 건질 수 있을 테니까."},objectives={{136,1903938714},"블랙스톤 섬 러스트게이트 능선에 있는 블랙 애쉬 광산에서 머드포 광부들로부터 채광 자재 8개를 회수하여 광산 감독 비즐로에게 전달하십시오."},progress={{94,753161114},"그래서, 뭔가 성과를 거두셨나요? 아니면 제가 이 일을 맡길 더 용감한 사람을 찾아야 할까요?"},completion={{224,424510969},"<비즐로는 안도의 한숨을 내쉬며 크게 웃었다.>$B$B어머, 이게 다 뭐야. 자네 덕분에 내 커리어가 구원받았군, 꼬마야. 이 장비들을 다 잃었더라면 광부로 강등되거나 더 심한 일을 당했을지도 몰라. 고마움의 표시로 이 동전을 받아라."}}
rows[41176]={title={{20,1442437510},"그녀는 조개껍데기를 판다"},description={{820,199698776},"이봐, 친구, 셸코인 들어봤어? 돈을 크게 벌고 싶어 하는 사람들 사이에서 완전 대박이야. 무역왕이 되는 지름길이라고는 이것밖에 없지! 단 한 가지 조건이 있어. 셸코인 거래를 시작하려면 예산이 필요하다는 거지! 러스트게이트 탑에 있는 자들 말고는 그만한 금을 가진 사람이 아무도 없어. 하지만 천재적인 $B$B전략가인 나는 이미 기발한 해결책을 생각해냈지! 이 섬 해안으로 밀려오는 조개껍데기들이 셸코인이랑 똑같이 생겼거든! 좋아, 내 제안은 이렇지.$B$B 그 조개껍데기를 충분히 가져오면 반반씩 나누는 거야. 여기 북쪽 해변에서 찾을 수 있고, 해안가를 돌아다니면서 조개껍데기를 모으는 놀들에게서도 얻을 수 있어. 20개 모으면 나한테 와. 그럼 우리 부자가 되는 거야!"},objectives={{119,2027789236},"블랙스톤 섬의 가치크 작업장에서 셰라 프레임스냅을 제작하려면 동쪽 해변을 따라 블랙스톤 조개껍데기 20개를 모으세요."},progress={{62,511527336},"벌써부터 아름다운 금화의 맛이 느껴지는 것 같아요! 하하!"},completion={{203,683941311},"아, 바다에서 밀려온 보물이여, 포도나무에서 포도를 따듯 주워 담을 수 있겠군! 이 황금빛 섬에서 탈출하기만 한다면 우린 부자가 될 거야! 부자가 될 거라고!$B$B<셰라는 하이에나처럼 낄낄거리기 시작한다.>"}}
rows[41177]={title={{16,967004350},"야수를 길들이기"},description={{544,435723625},"이제 자연을 길들이는 기술에 몰두할 시간이 왔습니다. 우리 레인저들은 자연과의 변함없는 유대감을 항상 간직해 왔으며, 많은 이들이 여정에서 동물 친구들과 특별한 인연을 맺어왔습니다. 이 연결고리, $B$B야생과의 조화를 이해하려면 먼저 당신의 준비 상태를 증명해야 합니다. 이 길들이기 지팡이를 잡으십시오. 이 도구는 당신에게 장로 진홍색 스라소니를 길들일 힘을 줄 것입니다. 이 위엄 넘치는 생물을 제압하고 레인저로서의 당신의 기량을 보여주십시오. 야생의 길로 들어서는 당신의 첫걸음은 바로 이 임무입니다."},objectives={{136,586838442},"길들이기 지팡이를 사용하여 장로 진홍살쾡이를 길들이세요. 기술을 연습한 후, 알라탈라스에 있는 다밀라라 선소로우에게 길들이기 지팡이를 돌려주세요."},progress={"You will learn, $N, and one day you will be a great $c.","$N님, 당신은 배우게 될 것이고, 언젠가는 훌륭한$c님이 될 것입니다."},completion={{57,1319700862},"훌륭한 임무 수행이었습니다. 당신은 유능한 레인저임을 증명해냈습니다."}}
rows[41178]={title={{16,967004350},"야수를 길들이기"},description={{533,416178305},"모든 짐승이 이 땅을 누비는 스라소니처럼 사납지는 않습니다. 야생의 위엄 있고 장엄한 면모를 알아보는 것이 중요합니다. 한때 왕족의 곁을 지키며 태양의 군마를 모시던 상아매사냥꾼도 있습니다. 이 길들이기 $B$B지팡이를 가지고 상아매사냥꾼을 길들이는 데 도전해 보세요. 이 임무는 특별한 접근 방식을 요구하며, 이를 통해 이 생명체의 다면적인 본성을 이해하게 될 것입니다. 이 만남을 통해 당신은 우리와 함께 살아가는 짐승들의 진정한 본질을 깨닫게 될 것입니다."},objectives={{135,1998882168},"길들이기 지팡이를 사용하여 상아매사냥꾼을 길들이세요. 실력을 갈고닦은 후, 길들이기 지팡이를 알라탈라스에 있는 다밀라라 선소로우에게 돌려주세요."},progress={"I am proud of your accomplishments, $N. Have you finished the last task I gave you?","$N, 당신의 성과가 자랑스럽습니다. 제가 마지막으로 맡긴 임무는 완료했습니까?"},completion={"Your commitment is unwavering, $c.","$c님, 당신의 헌신은 변함이 없습니다."}}
rows[41179]={title={{16,967004350},"야수를 길들이기"},description={{582,2092226916},"퀘르도레이로서, 우리는 마법과의 본질적인 연결고리로 인해 다른 종족과 구별됩니다. 하지만 야수들의 영역에는 태양샘의 순수한 마나에서 태어난 생명체, 마나 와이번이 존재합니다. 당신의 궁극적인 도전은 남쪽 언덕에 서식하는 라벤더 마나 와이번을 길들이는 것입니다. 이 $B$B생명체를 길들이는 데 성공한다면, 당신은 야수를 완전히 제압할 뿐만 아니라 마법에 대한 당신의 뛰어난 능력을 보여줄 수 있을 것입니다. 라벤더 마나 와이번은 우리 엘프의 유산과 아제로스를 흐르는 마법 에너지의 융합을 상징합니다. 당신의 노력이 이 두 가지를 모두 완벽하게 마스터하는 진정한 달인이 되기를 바랍니다."},objectives={{136,425648832},"길들이기 지팡이를 사용하여 라벤더 마나 와이번을 길들이세요. 실력을 갈고닦은 후, 길들이기 지팡이를 알라탈라스에 있는 다밀라라 선소로우에게 돌려주세요."},progress={{85,1074800725},"자연과 마법 사이의 균형을 이해하는 것은 모든 <종족>의 삶의 방식입니다."},completion={{579,1162701085},"축하합니다. 당신은 짐승 조련의 기술을 터득할 자격을 증명해냈고, 저는 당신의 성취를 자랑스럽게 생각합니다. 당신이 자신뿐 아니라 우리 모두에게 영광을 가져다줄 것이라고 확신합니다.$B$B조언 하나 드리겠습니다. 첫 번째 동반자를 선택할 때는 신중을 기하십시오. 육지 동물일까요, 물속 동물일까요, 아니면 하늘을 나는 생물일까요? 무엇을 선택하든, 선택한 동반자는 긴 여정 동안 당신 곁을 지킬 것이라는 점을 기억하십시오. 현명하게 선택하고, 당신과 당신의 반려동물 사이의 유대가 오래도록 지속되고 풍성하기를 바랍니다."}}
rows[41180]={title={{16,967004350},"야수를 길들이기"},description={{523,1053205706},"이제 동료를 길들일 수 있는 힘을 얻었지만, 여정은 이제 막 시작되었을 뿐입니다. 새로운 동료의 잠재력을 진정으로 활용하려면 우리 부족 최고의 사냥꾼인 레인저 장군 할두론 브라이트윙의 지도를 $B$B받으십시오. 그는 우리 부족의 최고 권위자이며, 남쪽 끝자락, 마지막 룬스톤 옆에 주둔하고 있습니다. 그곳에서 그는 스컬지에 맞서 불굴의 전투를 벌이고 있습니다. 그에게$B$B 다가가 그의 가르침 아래, 새로운 동료를 훈련하고 지휘하는 데 필요한 기술을 연마하십시오."},objectives={{78,2083164018},"마지막 룬스톤 옆 요새화된 지역에 있는 할두론 브라이트윙에게 말을 걸세요."},progress={{11,819267740},"그게 뭐죠?"},completion={{724,1039910969},"아, 이제 막 레인저의 길을 걷기 시작한 젊은이가 내 앞에 서 있군. 이리 오너라, 친구.$B$B레인저의 길을 걷기 시작했던 때가 이제는 아득한 옛날 기억처럼 느껴지네. 조국이 함락되기 전 시대의 삶이었기에, 그 시절은 희미하게나마 기억나지 않는구나. 하지만 너와 같은 젊은 사냥꾼들의 활력과 정신이야말로 우리 조상의 땅을 되찾고자 하는 희망의 불씨를 지피는 것이로다.$B$B이제 네 새로운 동반자를 훈련시키고 이끄는 법을 가르쳐주겠다. 앞으로 너는 네 동반자에게 새로운 능력을 가르치는 것은 물론, 전투의 위험에 처했을 때 보살피고 소생시켜야 할 것이다. 이것은 레인저로서 네 여정의 중요한 장이 시작되는 순간이다. 이 지식을 능숙하고 목적 있게 활용하거라.$B$B곧 다시 이야기 나눌 수 있기를 바라네."}}
rows[41181]={title={{16,1468253306},"마법의 질병"},description={{750,2075507461},"안녕하세요, 슈퍼히어로가 아니신가요? 오랜 친구 위제트를 만나러 오셨군요! 어디를 가든 고블린들이 당신에게 시선을 고정하더라고요. 우리만의 스타라니, 정말 멋지군요. 하지만 그건 $B$B그렇고, 할 일이 있어서 당신의 도움이 필요할 것 같습니다. 워터홀에 $B$B있는 갈박스가 우리 식수원을 위협하는 반란군 정령들과 마주쳤는데, 혼자서는 감당할 수 없다고 합니다. 이 물덩어리들이 우리가 물을 다 가져가는 걸 못마땅해하는 것 같더군요. 갈박스의$B$B 보고를 듣고 해결 방법을 짐작했는데, 어떤 매개체가 필요합니다. 북동쪽에 있는 머드포우 미스틱들이 마법 구슬을 가지고 다닌다고 하니, 세 개만 가져오면 계획을 계속 진행할 수 있을 겁니다."},objectives={{74,1009226920},"러스트게이트 능선에서 위제트 아이스휘슬을 위해 머드포 오라클 오브 3개를 획득하세요."},progress={{100,1538306014},"그들이 대단한 마법의 힘을 갖고 있을 것 같지는 않으니, 만일을 대비해 평소보다 더 많이 모아두자."},completion={{167,2123162315},"으, 쟤네들 이름 그대로 너무 심각하게 받아들이는 것 같네. 일단 쟤네들 잘 간직해 둬. 네가 손 더럽히는 동안 내가 갈박스의 수중 변칙 현상을 해결하는 방법을 알아냈거든."}}
rows[41182]={title={{16,543172118},"거품이 이는 악당들"},description={{661,669001771},"사실 아주 간단합니다. 이 구슬 안에 담긴 에너지와 당신의 마법을 이용하면, 그 공격에 맞설 수 있는 충분한 마법 방어막을 만들 수 있을 겁니다. 믿기 $B$B어렵겠지만, 강력한 마법사들은 자신만의 물의 정령을 소환하고 조종할 수 있습니다. 우리가 원소를 다루는 지식과 능력이 주술사만큼 깊고 영적인 것은 아닐지라도, 그렇다고 해서 우리가 원소로 놀라운 일을 해낼 수 없다는 뜻은 아닙니다. 그러니 누가 알겠습니까? 언젠가 당신도 그 정령 중 하나를 타고 이곳에 오게 될지도 모릅니다! 구슬을 가지고 $B$B북쪽의 물웅덩이로 가십시오. 그곳에 도착하면, 마음의 준비를 단단히 하고 듀로타르 노동조합 소유지에서 그 정령을 몰아내십시오!"},objectives={{117,2024331437},"물 펌프를 위협하는 물의 정령을 진압하고, 그 정령의 족쇄를 러스트게이트 능선에 있는 위제트 아이스휘슬에게 가져오십시오."},progress={{29,1155374253},"마음만은 함께할게요!"},completion={"You did it? Oh, and what are these? I'd reckon proof of your deeds. Did you know elemental shackles fetch for a good price on the black market? Ofcourse you didn't, why else would you give them to me? Nuh-uh, too late, you can't take back a gift, no? Brings bad fortune after all!$B$BBut don't be mad, because of your help we won't die of thirst, and we're grateful for that! Take one of these as appreciation, I will probably not use them anytime soon.$B$B$n, I have to say: It has been a joy to work with you! Whether we will see eachother again or not, best of fortune to you, my friend!","당신이 해냈다고요? 오, 그리고 이건 뭐죠? 당신의 공적을 증명하는 증거로 보이네요. 원소의 족쇄가 암시장에서 꽤 비싸게 팔린다는 거 아세요? 물론 몰랐겠죠, 안 그랬으면 왜 저한테 줬겠어요? 안 돼요, 이미 늦었어요. 선물은 돌려받을 수 없잖아요? 어쨌든 불길한 징조를 가져오니까요!$B$B하지만 화내지 마세요. 당신 덕분에 목말라 죽지 않게 됐으니 정말 감사해요! 감사의 표시로 하나 받아가세요. 당분간은 쓸 일이 없을 테니까요.$B$B$n, 정말이지, 당신과 함께 일할 수 있어서 기뻤습니다! 다시 만날 수 있을지는 모르겠지만, 행운을 빌어요, 친구!"}}
rows[41183]={title={{11,1212421700},"회색 가죽"},description={{593,950173988},"저는 여기 펌프를 하루도 빠짐없이 지켜보고 있습니다. 24시간 내내 여기 서서 이 낡고 고약한 펌프가 어떻게든 버텨내려고 안간힘을 쓰는 모습을 지켜보고 있죠. 만약 이 녀석이 멈춰버리면, 저는 정말 큰 곤경에 처하게 될 겁니다. 그런 곤경은 피하고 싶어요.$B$B 밤은 점점 더 추워지고 있는데, 펌프가 타버릴까 봐 모닥불을 피울 수도 없어요. 다행히 저는 가죽 세공에 능숙해서 추위를 막을 멋진 코트를 만들 수 있죠. 이 근처 $B$B하이에나 가죽을 가져다주시면, 당신에게도 뭔가 만들어 드릴게요. 어때요?"},objectives={{60,1337798283},"워터홀에 있는 펌프공 피즐로에게 애쉬포 가죽 6장을 가져다 주세요."},progress={{137,2025432062},"러스트게이트 측에서 조금 더 많은 보상을 해줬다면 이렇게까지 불평하지는 않았을 겁니다. 하지만 지금 상황으로 봐서는 분명히 불평할 수밖에 없네요."},completion={{148,789436829},"이것들은 쓸만하긴 한데 완벽하진 않아. 그래도 괜찮아. 정말 고맙다, 친구. 자, 수고에 대한 보답으로 이걸 받아. 넌 훌륭한 고블린이야, 몇 안 되는 훌륭한 고블린 중 하나지."}}
rows[41184]={title={{30,1677747282},"내 초록 코 바로 아래에서"},description={{807,1141137645},"알아요, 알아요. 탑에 계신 각하께서 목이 마르시다는데, 이제 그 형님이 불쌍하고 순진한 개미를 보내서 약속된 물을 가져오라고 시켰다는 거요. 오늘만 해도 그 얘기 세 번은 들은 것 같네요. 사실 저도 러스트게이트 각하께 물을 보내드리고 싶은데, 문제는 각하의 지도 방식이 이 섬에 있는 몇몇… 이상주의적이고 순진한 바보들과는$B$B 맞지 않는다는 겁니다. 러스트게이트 각하께 시원한 물을 가져다주기로 했던 대상 행렬이 저 위 빈민가 주민들의 습격을 받아 약탈당했어요. 자기네 물만 원하는 게 아니라, 최고 감독관이 타나리스의 멀록처럼 목마르게 내버려 두려는 $B$B거겠죠. 만약 도와주고 싶으시다면 – 부디 그러시길 바라지만 – 저 위로 올라가서 보급관 맥슬로에게 물을 가져다주세요. 성공하면 여기서 무슨 일이 벌어지고 있는지 알려주세요."},objectives={{87,458884515},"러스트게이트의 물 수송품을 회수하여 러스트게이트 리지에 있는 보급 책임자 맥슬로에게 가져다 주십시오."},progress={{32,1876413568},"어이, 너! 왜 이렇게 늦었어?"},completion={{300,94301550},"그러니까 슬럼가의 멍청이들이 매복 공격의 배후였군요. 놀들이 보통 그런 식으로 행동하잖아요, 그래서 놀들이 배후에 있을 거라고 의심은 했지만, 솔직히 너무 조직적인 것 같았어요. 어쨌든, 물자 회수 잘했습니다. 택슬로에게 보고하겠습니다. 이 반란군들을 어떻게든 처리해야 해요."}}
rows[41185]={title={{13,95943232},"머드포우와의 전쟁"},description={{515,355588645},"저 위 투자개발회사 놈들만으로도 충분히 짜증 나는데, 이 보잘것없는 연못 너머에는 놀들이 더러운 발을 질질 끌며 우리를 향해 낄낄거리고 으르렁거리고 있어. 하루 종일 말이야. 내가 이 얼간이들을 지키느라 바쁘지만 않았더라면 몽둥이를 들고 직접 가서 한바탕 혼내줬을 텐데. 하지만 그럴$B$B 수가 없지. 정말 화가 나. 돈 좀 벌고 싶어? 저놈들 대가리를 몇 대 후려치면 보상해 주지. 증거로 팔찌를 가져와. 난 누구의 말도 믿지 않아. 너도 자기 앞가림을 생각한다면 나처럼 할 거잖아."},objectives={{78,57730965},"워터홀에 있는 브루저 예보를 위해 머드포우 놀에게서 머드포우 팔찌를 모으세요."},progress={{139,315908718},"여기 담당 업무를 맡은 이후로 계속 그들을 지켜보고 있었어요. 그중 일부는 삐걱거리는 난쟁이들보다 훨씬 더 엉뚱하게 행동하고 있더군요."},completion={{190,1676269733},"이게 무슨 용도로 쓰이는지 궁금하네요. 부족의 색깔 같은 건가요? 아니면 다른 의미가 있는 걸까요? 어쨌든 저한테는 별로 중요하지 않아요. 고마워요, 친구. 이거 화장실에서 아주 유용하게 쓰일 거예요."}}
rows[41186]={title={{13,1501194330},"그랩 머드하이드"},description={{565,437243029},"저기서 시끄럽게 구는 무리를 이끄는 자가 있는 한, 내 문제는 쉽게 해결되지 않을 거야. 내가 알아본 바로는 놀 무리는 보통 적어도 한 명의 우두머리가 부하들을 꽤 폭력적으로 지휘하는 방식으로 움직이더라고. 훗, 아이러니하지 않나? I는 네가 저 우두머리 $B$B짐승을 없애주길 바라. 몇 번이나 우리를 조롱하는 걸 봤거든. 망할 짐승, 이름은 그랩 머드하이드야. 보통 이 연못 바로 너머에 있는 동굴에 나타나. 발을 잘라버려. 스파크워터에 있는 내 아내에게 내가 이 황량한 섬에서 빈둥거리고 있는 게 아니라는 걸 보여줄 트로피가 필요하거든."},objectives={{62,467658760},"브루저 예보를 워터홀로 데려와 그랩 머하이드의 발을 가져오세요."},progress={{163,849135559},"멀록, 놀, 마크루라. 솔직히 어떤 놈들이 더 짜증나는지 모르겠지만, 내 마음대로 할 수 있다면 듀로타르 노동조합 부지에서 전부 쫓아내 버릴 거야."},completion={"Haha! Wonderful, this will be a perfect gift for my darling Zanny. You are in my favour, $n, I'll tell the other bruisers to not hit you as hard from now on.","하하! 멋지다, 이건 내 사랑하는 재니에게 완벽한 선물이 되겠어.$n, 넌 내 총애를 받고 있어. 다른 깡패들에게 앞으로 널 그렇게 세게 때리지 말라고 할게."}}
rows[41187]={title={{16,1487785498},"난민은 더 이상 없습니다"},description={{777,1383949538},"오, 태양샘 근처에 또 다른 대상 행렬이 있군요? 지친 여행자들의 무게에 발밑의 땅이 신음하는 것 같습니다. 숨 돌릴 틈조차 없을 정도로 좁고, 쉴 곳을 찾는 건 더더욱 어렵습니다. 제발,$B$B 작은 땅이라도 찾아서, 어디든 좋습니다. 적어도 지금은 그곳을 당신의 공간으로 만들어 보세요. 비록 보잘것없더라도 소지품을 풀어놓으세요. 우리 모두 산산조각 난 삶의 무게를 손에 짊어진 것 같습니다. 이 $B$B혼란 속에서 잠시 마음을 추스르세요. 저기 아나릴레스 사령관이 남아 있는 얼마 안 되는 질서를 유지하고 있습니다. 그녀는 유능한 영혼을 필요로 하는 것 같은데, 당신을 보니 강인한 정신력을 가진 것 같군요. 시간이 되면$B$B 그녀에게 다가가 도움을 청하세요. 빛이 이 암흑기를 헤쳐나가도록 인도해 주기를."},objectives={{45,269942557},"브린틸리엔에 있는 아나릴레트 사령관에게 보고하십시오."},progress={{244,747962142},"아, 우리 동족들이 이 새로운 안식처를 찾아오는 모습을 보니 마음이 따뜻해지군요. 정말 아름다운 광경이 아닙니까? 실버문 시티 외곽을 떠올리게 하는 친숙한 분위기가 감돌아요."},completion={"Aerthand's judgment has proven sound in sending you my way. You bear the mark of capability, unmistakable in your presence, $c. There's no doubt we could use your skills in this tumultuous time.$B$BThere's much to be done, and with every caravan that arrives, our needs grow. Are you ready to lend your hand to our cause?","아에르탄드가 당신을 제게 보낸 것은 탁월한 판단이었습니다. 당신은 뛰어난 능력을 지녔으며, 그 존재감만으로도 당신은 틀림없습니다,$c. 이 혼란스러운 시기에 당신의 능력이 절실히 필요할 것입니다.$B$B해야 할 일이 많고, 새로운 캐러밴이 도착할 때마다 필요한 것이 늘어납니다. 우리를 위해 기꺼이 도움의 손길을 내밀어 주시겠습니까?"}}
rows[41188]={title={{23,1937233931},"난민을 위한 조항"},description={{676,1054695055},"섭정 위원회는 이 땅에 피난처를 찾는 모든 이들에게 식량과 거처를 제공하는 책임을 제게 맡겼습니다. 고귀한 의도를 가진 임무이지만, 자원이 턱없이 부족합니다. 이 지역에는 멧돼지가 $B$B많아 우리 사람들에게 잠재적인 식량원이 될 수 있습니다. 하지만 현실은 냉혹합니다. 많은 사람들이 멧돼지 사냥에 필요한 장비나 기술이 부족합니다. 이 격차를 해소하는 것은 기꺼이 나서서 도와줄 사람의 몫입니다. $B$B만약 당신에게 수단과 기술이 있다면, 우리를 위해 어린 멧돼지 옆구리살 열 개 정도를 모아주실 수 있을까요? 이곳에 피난처를 찾아온 사람들의 굶주림을 덜어주는 데 큰 도움이 될 것입니다."},objectives={{77,163637506},"브린틸리엔에 있는 아나릴레트 사령관에게 어린 탈라시안 멧돼지 옆구리 10개를 가져다주세요."},progress={{40,2096735080},"이 계곡 어디에서나 멧돼지를 찾아볼 수 있습니다."},completion={"Thank you, $c. Your willingness to contribute is like a small beacon of hope in the vast sea of our needs. It may seem like a mere drop amidst the ocean of challenges we face, but with each kind gesture, we inch closer to the restoration of our former glory.","$c님, 진심으로 감사드립니다. 당신의 따뜻한 도움은 우리가 직면한 수많은 어려움 속에서 한 줄기 작은 희망과 같습니다. 비록 거대한 바다 한가운데 작은 물방울처럼 보일지 모르지만, 당신의 작은 도움 하나하나가 우리가 예전의 영광을 되찾는 데 한 걸음씩 더 나아가게 해 줍니다."}}
rows[41189]={title={{19,1331049894},"난민의 안전"},description={{481,1320875771},"야생으로 탐험을 나갔을 때, 이 숲을 괴롭히는 스라소니들이 점점 더 큰 위협이 되고 있음을 목격하셨을 겁니다. 현재로서는 그저 성가신 존재일지 모르지만, 개체 수가 통제 불능 상태로 급증하는 것을 방치할 수는 없습니다. I는 $B$B당신에게 엄숙한 임무를 맡깁니다. 다시 한번 숲으로 들어가 스라소니 새끼들을 도태시켜 주십시오. 스라소니의 개체 수가 늘어나는 것을 용납할 수 없습니다. 우리 주민들의 안전과 안녕은 이 새로운 서식지에서 균형을 유지하는 데 달려 있습니다."},objectives={{53,936832570},"아나릴레스 사령관을 위해 어린 진홍색 살쾡이 12마리를 처치하십시오."},progress={{44,1059456134},"명심하세요, 여러분이 노리는 대상은 어린아이들입니다."},completion={"Ah, a welcome relief to know that the burgeoning threat of the lynx population has been curbed. Your actions bring a sense of solace, and I can rest easier knowing that you've shouldered this responsibility for our community, young $c.","아, 스라소니 개체 수 증가로 인한 위협이 억제되었다니 정말 다행입니다. 당신의 행동 덕분에 마음이 놓이고,$c님, 우리 공동체를 위해 이 책임을 다해 주셔서 정말 감사합니다."}}
rows[41190]={title={{18,1189602954},"탈라시안 굴라시"},description={{738,2070553638},"안녕하세요! 처음 오신 분이죠? 반갑습니다. 저는 달리시아인데, 그냥 달이라고 불러주세요! 알라탈라스가 처음 세워졌을 때부터 함께해 왔고, 제 요리 솜씨를 뽐내며 이곳에서 열심히 일해 왔습니다. 제가 바로 이곳의 요리사인데요, 솔직히 말해서 난민들에게 지급되는 식량은 정말 형편없습니다. 퍽퍽한 고기에 엘윈의 썩은 곡물이라니? 퀘르도레이의 입맛에는 전혀 $B$B맞지 않죠. 자, 이제 중요한 게 있습니다. 제가 자랑하는 굴라시를 만들고 싶은데, 재료를 구할 수가 없네요. 숲매사냥꾼 다리와 스라소니 스테이크를 좀 구해다 주시면, 우리 백성들을 위한 훌륭한 잔치를 금방 시작할 수 있을 거예요! 이 칙칙한 메뉴를 맛있는 음식으로 바꿔봅시다!"},objectives={{91,634413230},"브린틸리엔에 있는 달리시아 스위트실버를 위해 숲매사냥꾼 다리 6개와 스라소니 스테이크 8개를 모으세요."},progress={{23,1982222577},"잘 지내시나요, 친구?"},completion={{164,1974848373},"아, 드디어! 신선하고 좋은 재료들이 풍성하게 준비되었군요. 정말 감사합니다! 이제 이곳에 풍미를 더할 때가 된 것 같지 않나요?"}}
rows[41191]={title={{18,317774289},"꽃으로 만든 왕관"},description={{744,329020972},"저기요! $B$B(아베난트는 목소리를 낮추고 다급한 어조로 말했다.) 저기$B$B 저 아가씨를 한동안 눈여겨보고 있었거든요. 굳이 돌아서서 빤히 쳐다볼 필요는 없어요. 은근슬쩍 접근하는 게 중요하니까요. 문제는 저 아가씨가 제게 호감을 보이지 않는다는 겁니다. 자, 이제 당신의 도움이 필요한데, 아름다운 꽃으로 만든 화관이 효과가$B$B 있을 것 같지 않나요? (아베난트는 조심스럽게 $B$B주위를 둘러본 후 말을 이었다.) 솔직히 말하면, 저는 혼자 숲에 들어가는 걸 그다지 좋아하지 않아요. 스라소니, 거미 등등 온갖 동물들을 봤는데, 생각만 해도 소름이 돋거든요. 그래서 말인데, 당신이 저를 위해 꽃을 좀 따다 준다면, 저 아가씨의 마음을 얻을 수 있을지도 몰라요. 어떻게 생각하세요?"},objectives={{73,1820410790},"아베낭에게 꽃 열 송이를 가져다주세요. 그가 졸리를 위해 꽃으로 화관을 만들어 줄 겁니다."},progress={{19,836836492},"졸리는 내 것이 될 거야."},completion={{464,453738829},"농담하시는 거죠?$B$B이 꽃으로 누군가의 마음을 움직일 수 있다니, 더군다나 그녀처럼 아름다운 사람의 호감을 얻을 수 있을 리가 있겠어요. 헛된 노력일 뿐이에요. 정말 아무 가치도 없어요. 그녀의 마음을 얻는 건 불가능한 일 같아요. 고향에서 멀리 떨어진 이곳에서, 한때 인연을 약속했던 그곳에서, 저는 외롭게 시들어 죽어갈 것 같아요.$B$B그냥 내버려 두세요. 그래야 제가 마음껏 제 감정에 빠져들 수 있으니까요.$B$B<아베낭은 경멸하는 듯한 표정으로 꽃을 내던진다.>"}}
rows[41192]={title={{19,1606631005},"마법 골렘 반란"},description={{848,196391939},"이… 시들어버린 껍데기들이 $B$B보이십니까?<필라스는 한숨을 쉬며 영양실조에 걸린, 한때 엘프였던 자들을$B$B 바라보았다.>은빛 태양 광산이 복구되지 않으면 우리도 이렇게 될지도 모릅니다. 한때 충성스러운 일꾼이었던 마법 골렘들이 어떤 마법의 폭발에 휘말렸는데, 틀림없이 그 소위 블러드 엘프들의 소행일 겁니다. 미쳐버렸어요! 광산은 이제 접근할 수 없게 되었고, 우리는 그 귀중한 마법 수정의 공급원과 단절되었습니다.$B$B<필라스는 체념과 좌절이 뒤섞인 표정으로 어깨를 $B$B으쓱했다.>하지만 안타깝게도 섭정 위원회는 실질적인 도움을 주기보다는 궁정 내 배신에 더 관심이 있는 것 같습니다. 그러니, 용기가 있다면 이 미쳐버린 마법 골렘들을 광산에서 치워주실 수 있겠습니까? 물론 보상은 순은으로 지급하겠습니다. 위험한 업무에 대한 정당한 보상."},objectives={{126,1638774227},"실버 선 광산에서 고장난 마법 골렘 8마리, 결함 있는 마법 골렘 6마리, 마법 파운더 4마리를 처치하여 광산을 정리하세요."},progress={{69,265680080},"당신이 머뭇거리는 매 순간은 필요한 사람들을 위한 신비로운 수정의 양을 줄입니다."},completion={"The common folk yet again take matters into their own hands, endeavoring to mend the fallout left by those who consider themselves above such concerns. Thank you, $c. You have saved many.","평범한 사람들이 또다시 직접 나서서, 자신들은 이런 문제들과는 상관없다고 생각하는 자들이 남긴 폐해를 수습하려 애쓰고 있습니다.$c님, 감사합니다. 당신 덕분에 많은 사람들이 목숨을 건졌습니다."}}
rows[41193]={title={{20,276657499},"불안감을 주는 존재"},description={"$N, may I borrow a moment of your time? Your past assistance has not gone unnoticed, and there's a delicate matter that requires your attention.$B$BIt appears we are not alone in this new refuge. Our scouts have reported the presence of a significant force atop a nearby hill—our former brethren, the so-called blood elves. They are loyal to the traitorous prince, Kael'thas, and their dependence on dark magic clouds their judgment. They pose a threat to our cause, and their proximity to Brinthilien raises concerns.$B$BI must task you with a challenging mission: seek out and eliminate this group of blood elves. They are led by a man named Veloren Brightstar, a figure whose removal will sow chaos among their ranks. The safety of our community hinges on the success of this mission.","$NN, 잠시 시간 좀 내주시겠습니까? 당신의 이전 도움은 결코 잊지 않겠습니다. 그리고 당신의 관심을 필요로 하는 중요한 사안이 있습니다. $B$B우리 새로운 은신처에 우리만 있는 것이 아닌 것 같습니다. 정찰병들이 인근 언덕 위에 상당한 병력이 있다고 보고했습니다. 바로 우리의 옛 동족, 이른바 블러드 엘프들입니다. 그들은 배신자 켈타스 왕자에게 충성하며, 어둠의 마법에 의존하여 판단력이 흐려져 있습니다. 그들은 우리의 대의에 위협이 되며, 브린틸리엔과 가까운 곳에 있다는 점이 우려스럽습니다. 당신에게$B$B 어려운 임무를 맡겨야 합니다. 바로 이 블러드 엘프 무리를 찾아내 제거하는 것입니다. 그들은 벨로렌 브라이트스타라는 인물의 지휘를 받고 있는데, 그를 제거하면 그들 사이에 혼란이 일어날 것입니다. 우리 공동체의 안전은 이 임무의 성공 여부에 달려 있습니다."},objectives={{117,1506895507},"블러드 엘프 야영지를 찾아 브린틸리엔을 위협하는 존재를 제거하십시오. 임무를 완료하면 아나릴레스 사령관에게 돌아가십시오."},progress={{34,1278561309},"블러드 엘프 야영지를 찾으셨나요?"},completion={{337,400784922},"옛 동족의 죽음 소식은 내게 기쁨을 주지 않습니다. 이는 한때 하나였던 이들 사이에 갈등이 생겨났음을 상기시키는 슬픈 현실입니다. 그들의 침략으로 우리는 새로 찾은 고향을 지키는 것 외에는 다른 선택의 여지가 없었습니다.$B$B그들의 마음을 가렸던 어둠 속에서도 영원한 태양의 품 안에서 그들의 영혼이 평안을 찾기를 바랍니다."}}
rows[41194]={title={{25,446928802},"왕족의 편지"},description={{808,2040056714},"이 편지가 귀하께서 건강하게 잘 지내고 계시기를 바랍니다. 매우 중대한 사안을 알려드리게 되어 마음이 무겁습니다. 알라탈라스의 반군들이 우리를 상대로 한 움직임을 준비하고 있다는 첩보가 입수되었습니다. 우리 요원들이 도시 내에서$B$B 경계를 강화하고 있는 가운데, 귀하께서는 브린틸리엔에 있는 난민들을 예의주시해 주셔야 합니다. 최대한 신중하고 조심스럽게 행동하시고, 관련 인물들과의 어떠한 도발이나 직접적인 대립도 삼가해 주십시오. 또한, 관찰 시에는 $B$B눈에 띄지 않도록 주의하고 신중하고 사려 깊게 행동해 주시기 바랍니다. 이 임무에 대한 귀하의 헌신은 우리 국민의 안녕과 우리의 대의를 지키는 데 매우 중요합니다. 귀하의$B$B 능력을 전적으로 신뢰하며, 엘딘 $B$B선스트라이더 부왕 드림."},objectives={{51,2040524358},"펠트터치드 편지를 아나릴레트 사령관에게 가져다 주세요."},progress={{4,273767400},"예?"},completion={{276,1384876197},"그렇다면 이 서신은 사령관의 유해에서 발견된 것인가?$B$B내용이 우려스러운 만큼, 이 서신을 알라탈라스의 섭정위원회에 지체 없이 전달해야 한다. 도시 내에 우리 진영에 첩자가 침투했다는 언급은 심각한 우려를 불러일으킨다."}}
rows[41195]={title={{26,591228856},"윈드러너에게 보내는 메시지"},description={{495,249341467},"서둘러야 해. 시간이 촉박해. 상황이 악화되기 전에 이 서신을 바람처럼 빠르게 섭정위원회에 전달해야 해. 아나릴레스$B$B 사령관은 몸을 앞으로 기울이며 목소리를 낮췄다.$B$B 하지만 이 말에는 조심해야 할 점이 있다. 위원회 구성원 모두를 무조건 신뢰할 수는 없어. 최대한 신중하게 이 서신이 베레사 윈드러너에게만 전달되도록 해. 그녀만이 이 서신의 내용을 다룰 수 있어."},objectives={{70,1420148235},"펠트터치드 편지를 알라탈라스에 있는 베레사 윈드러너 부인에게 가져다 주세요."},progress={{61,1848236505},"우리 동족 중 또 한 명이 알라탈라스에 합류하게 되었군요. 환영합니다."},completion={"<Vereesa gracefully accepts the letter from your hand, her keen eyes perusing its contents with a measured intensity.>$B$BThank you, $c, for your diligence in bringing this matter to my attention. The urgency of the situation is apparent, further corroborating my apprehensions. It appears that the once understandable discontent has evolved into blatant mutiny.$B$B<She pauses, her demeanor reflecting a mix of concern and determination.>$B$BNot all within our midst remain loyal to our shared cause. We must swiftly identify these agents still aligned with Kael'thas and promptly expel them from our city.","<베리사는 당신의 손에서 편지를 우아하게 받아들였고, 날카로운 눈으로 내용을 꼼꼼히 살폈습니다.>$B$B감사합니다,$c이 문제를 제게 알려주셔서요. 상황의 긴급성이 분명하며, 이는 제 우려를 더욱 확증시켜 줍니다. 한때 이해할 만했던 불만이 노골적인 반란으로 변질된 것 같습니다.$B$B<그녀는 잠시 말을 멈추고, 걱정과 결의가 뒤섞인 표정을 지었습니다.>$B$B우리 가운데 모두가 공동의 대의에 충성하는 것은 아닙니다. 우리는 여전히 켈타스와 결탁한 자들을 신속히 색출하여 도시에서 추방해야 합니다."}}
rows[41196]={title={{16,320092543},"미친 듯한 굶주림"},description={{595,393470510},"더 이상 못 참겠어! 너! 너! 이 꼬맹이-<라나티르는 $B$B몸을 떨며 고개를 저었고, 목소리가 낮아졌다.>아니,$B$B 아니, 내가 아니야. 미안해. 정말 미안해, 제발… 용서해 줘, 내가 아니었어, 일부러 그런 게 아니었어. 하지만… 있잖아… 내가 $B$B마나를… 얼마나… … 얼마나 됐지? 요즘 시간이 멈춰서 날 비웃는 것 같아. 제발, 광산에서 마법 수정 좀 가져다줘. 골렘들이 그걸 얻기가 너무 힘들고, 항상 부족해. 항상 부족해… 제발. 제발 $B$B빨리. 더 이상… 견딜 수가 없어."},objectives={{76,1298368452},"광산에서 충전된 마법 수정을 가져와 라나티르에게 가져다주세요."},progress={{90,32852483},"어떤 날은 내가 죽을까 봐 너무 걱정되지만, 어떤 날은 내가 죽지 않을까 봐 너무 두려워요."},completion={{377,1107207709},"오! 오, 맞췄군요! 오, 축복받았어요-$B$B<라나티르는 재빨리 목소리를 낮추고 수정구를 가슴에 꼭 끌어안은 채 다른 시든 자들을 둘러보았다.>$B$B고마워요. 고마워요. 오늘은 괜찮을 거예요. 오늘은 멋진 날이 될 거예요. 정말 멋져요. 이건…$B$B<수정구를 쥔 손에 힘이 들어가고 손이 떨리기 시작했다. 그의 목소리는 갑자기 떨리는 속삭임으로 변했다.>$B$B아무리 많아도 부족해…"}}
rows[41197]={title={{23,1425540829},"알라탈라스로 배송"},description={{489,1136334727},"알라탈라스 시로 향하고 계신가요? 그렇다면 당신의 도움이 필요한 임무가 있습니다. 제 동료 티리엘이 도시로 몰려드는 난민들을 위해 여관을 열었는데, 예상하시다시피 손님들로 북적입니다. 와일드해머 부대에서 새로운 보급품이 도착했는데, 티리엘에게 전달해 주시면 정말 큰 도움이 될 겁니다. 티리엘의 여관은 도시 입구 바로 옆, 아나스테리안 공원을 가로지르며 들어가면 왼쪽에 있는 첫 번째 건물입니다."},objectives={{75,1428184455},"알라탈라스에 있는 티리엘 브라이트워터에게 와일드해머 보급품을 전달하세요."},progress={{102,1615936720},"여행자님, 저희 여관에 오신 것을 환영합니다. 지금은 침대가 없지만, 바닥에서 주무셔도 괜찮습니다."},completion={{277,405176641},"아, 솔레니아에게서 온 거군요? 우리 딸아이는 정말 착해요. 이렇게 전해 주셔서 정말 감사합니다, 낯선 분. 혹시 솔레니아를 다시 만나게 되면 제 감사 인사를 전해 주시고, 꼭 저를 찾아오라고 전해주세요. 우리가 꼭… 논의해야 할 중요한 일이 있거든요."}}
rows[41198]={title={{9,98335830},"찢어진 영혼"},description={{502,261465190},"누구세요? 여보세요?! 당신이 보이지는 않지만, 당신이 거기 있다는 걸 알아요. 제발, 누구시든 저를 도와주세요! 너무 고통스러워서 견딜 수가 없어요. 마치 제 존재가 매 순간 갈기갈기 찢어지는 것 같아요. 수많은 검은 그림자들이 집 주변을 서성이며 저를 잡아당기고 찢어발겨요. 마치 제가 동시에 여러 곳에 있는 것 같고, 제 존재 자체가 압박감에 무너져 내리는 것 같아요. 낯선 $B$B분이시여, 제발 제 몸에서 없어진 조각들을 찾아주세요! 그것들이 움직이고 있어요... 다른 곳에서요! 제발, 신이시여, 제 고통을 끝내주세요!"},objectives={{82,1387661774},"미리엄 렌하임의 시신 조각들을 찾아 포를론 서밋에 있는 그녀에게 가져다주세요."},progress={{50,901795200},"제발, 저 목소리들...! 너무 많아요!"},completion={{216,38903982},"이 고요함. 이토록 짜릿할 줄은 상상도 못 했습니다. 마침내, 이 모든 공포와 고통의 세월 끝에, 죽음의 짐이 벗겨지는 듯한 기분이 듭니다. 친절한 낯선 분들께 영원한 감사를 드립니다!"}}
rows[41199]={title={{22,804243012},"경계하는 마지막 수호자"},description={{792,331644128},"헤어지기 전에, 제 마음을 괴롭히는 한 가지가 있습니다. 제 몸을 되찾으니 마지막 순간의 기억들이 밀려옵니다. 어둠이 우리 가운데 숨어 있다가 빛의 수호자들이 떠나자 모습을 드러냈습니다. 우서 라이트브링어의 부하들 $B$B대부분은 그를 따라 다른 곳에서 스컬지와 싸우러 갔지만, 한 용감한 성기사이 무고한 자들을 지키기 위해 남았습니다. 우리가 광산으로 후퇴할 수밖에 없었을 때, 그는 할 수 있는 한 끝까지 버텼지만, 안타깝게도 빛에 대한 그의 흔들림 없는 헌신도 그에게 쏟아진 언데드 무리를 막아내기에는 역부족이었습니다. 그의 이름은$B$B 기억나지 않지만, 비록 결국 헛된 희생이었을지라도 그의 희생에 깊은 감사를 드립니다. 만약 광산 안에서 그의 흔적을 발견한다면, 부디 이 저주받은 곳에서 꺼내 주십시오. 제가 바라는 것은 그것뿐입니다."},objectives={{132,51393569},"황량한 정상에 있는 과부의 둥지에서 미리엄을 지켜준 사람과 관련된 단서를 찾아보세요. 그의 정체에 대한 힌트를 찾을 수 있을지도 모릅니다."},progress={"What is it, $r? What can the Argent Dawn do for a traveler like you?","이게 뭐죠,$r인가요? 아르젠트 던은 당신 같은 여행자에게 무엇을 해줄 수 있을까요?"},completion={{851,853845944},"<레오니드는 버려진 철퇴를 집어 들고 거의 감상에 잠긴 듯 바라본다.>$B$B그날을 기억한다… 그리고 그날 겪었던 공포를. 은빛 손의 감시가 사라지자, 산 정상은 서서히 불길의 소굴로 변했고 곧 어둠의 손아귀에 빠졌다. 저주받은 자들의 교단은 산으로 피난처를 찾아온 스트라솔름 난민들 사이로 침투하여 우서가 떠난 후 아서스의 옛 요새를 함락시켰다.$B$B빛의 독실한 신도로서 나는 무고한 사람들을 보호하기 위해 할 수 있는 모든 것을 다했다. 어리석은 짓이었을지도 모르지만, 그 외의 다른 선택은 내게 부끄러운 일이었을 것이다. 생명이 꺼져가는 내 몸에서 마지막으로 들은 소리는 내가 구하지 못한 사람들의 공포와 고통에 찬 비명 소리였다.$B$B여행자여, 이것을 가져다줘서 고맙다. 그것은 재앙이 세상에 가하는 공포를 다시금 일깨워주는 섬뜩한 사건이었고, 당신도 나도 쉽게 잊어서는 안 될 일이었다."}}
rows[41200]={title={{37,860740901},"빛의 분노가 너에게 임하리라"},description={{815,2093331630},"아제로스의 쓰레기들이 어둠의 심연에 숨어 지내기를 바랄 뿐이오. 그러나 도덕에 대한 무시와 권력욕에 눈이 멀어 그들은 혼돈을 퍼뜨리고 있소. 저주받은 자들의 교단 역시 예외는 아니오. 리치 왕의 집사, 대리치 켈투자드가 창설한 이 교단은 이 땅을 지금과 같은 모습으로 만든 장본인들이오. 제3차 전쟁의 서막에 언데드의 역병을 퍼뜨림으로써, 그들은 자신들의 영혼이 칠흑같이 어둡고 빛이 없다는 것을 분명히 보여주었소. 생명의 신성함을 조롱하는 것은 가장 빠르고 가혹한 처벌을 받아야 마땅한 죄악이오. 당신이 $B$B정의를 구현할 자인가? 그렇다면, 저들을 상대로 당신의 힘을 보태주시오.$B$B 서쪽 역병숲 너머 높은 산꼭대기에는 황량한 봉우리가 있소. 동료들을 찾아 그들의 지도자들을 처치하고, 아제로스에서 그들을 완전히 없애버리시오."},objectives={{117,1244990671},"테러데일 근처에서 포를론 서밋의 지도자들을 물리치십시오. 정의가 실현되면 맥스웰 티로수스 경에게 보고하십시오."},progress={{117,75461094},"빛의 형제단은 악이 활개를 치는 것을 좌시하지 않을 것입니다. 정의가 승리할 것입니다."},completion={{244,1868608827},"오늘 빛은 더욱 밝게 빛납니다. 당신의 확고한 신념 덕분에 악은 당분간 저지될 수 있었습니다. 하지만 이것이 끝이라고 어리석게 생각하지 마십시오. 어둠은 결코 완전히 사라지지 않습니다. 모험가여, 경계를 늦추지 마십시오. 빛이 당신을 비추기를 바랍니다."}}
rows[41201]={title={{20,274080484},"어둠 속으로 손을 담그다"},description={"Oh, oho! $n, perfect timing, I was just thinking about you, my all-so beloved warlock partner! I heard you've been turning Blackstone upside down with all the issues you solved for the hothead up on his tower. Not that I mind, keeps my back free to pursue more interesting… ventures. $B$BSpeaking of interesting - I believe you are more than ready for your second summoning spell. A dangerous invocation, one that many young warlocks fell victim too. The required materials I'd need to teach it to you are sadly not here on Blackstone, but Gan'rul Bloodeye in Orgrimmar can provide the necessary components for your training.$B$BSend my regards to him, he still owes me a sack of reagents. He usually spends his time in the Cleft of Shadow in the center of the capital.","오, 오호!$n 완벽한 타이밍이군, 바로 그때 자네 생각을 하고 있었네, 사랑하는 흑마법사 파트너! 자네가 블랙스톤 탑 꼭대기에 있는 그 성급한 놈 문제를 해결하느라 마을을 뒤집어 놓았다는 소식을 들었네. 뭐, 상관없지. 덕분에 내 뒷마당이 자유로워져서 더 흥미로운… 모험을$B$B 할 수 있으니까. 흥미로운 이야기 나온 김에 말인데, 자네가 두 번째 소환 마법을 배울 준비가 된 것 같군. 위험한 소환 마법이지. 많은 젊은 흑마법사들이 그 마법에 희생되었네. 자네에게 그 마법을 가르치는 데 필요한 재료는 안타깝게도 블랙스톤에 없지만, 오그리마에 있는 간룰 블러드아이가 자네 훈련에 필요한 재료를 구해줄$B$B 수 있을 거야. 그에게 안부 전해줘. 아직 재료 한 자루를 갚아야 하거든. 그는 보통 수도 중앙에 있는 그림자 틈에서 시간을 보내네."},objectives={{38,1798034170},"오그리마에 있는 간룰 블러드아이와 대화하세요."},progress={{39,704130856},"당신은 무슨 일로 그림자의 틈새에 오셨습니까?"},completion={{162,7724713},"고블린인가? 너희 같은 놈들이 요즘 도시를 어슬렁거리는 게 눈에 띄군. 하지만 상관없다. 권력을 추구하며 시야를 넓히려는 놈들은 누구든 환영이지."}}
rows[41202]={title={{20,179960414},"멍드는 법에 대한 교훈"},description={{882,1377666699},"이봐 꼬마, 네 소문이 좋더라. 러스트게이트 거리에는 네가 꽤 잘 싸운다는 얘기가 돌고 있어. 잘 싸운다는 건, 네 앞길을 막는 건 뭐든지 후려칠 줄 안다는 뜻이지. 마음에 드는군. 그건 용기라고 하는 거야. 넌 그런 용기가 넘쳐 보이는데. 자네에게 일거리가 하나 있는데, 고블린 노동력의 진짜 싸움꾼인 우리 일에 대해 가르쳐 줄$B$B 일이지. 알겠나? 북동쪽에서 머드포 그놀들이 우리 작업에 심하게 반발해서 우리를 작업장에서 쫓아냈어. 자네를 그중에서도 가장 사납고 흉포한 녀석들과 싸우게 할 좋은 기회인 것 같군. 머드포 브루트는 동족 중에서도 가장 강하고, 고블린들을 죽여 온 그 무시무시한 망치를 휘두르는 것으로 유명하지. 전세를 역전시켜서 녀석들을 제대로 혼내줘 ​​봐. 머드포 망치 여섯 개를 가져오면 보상을 주겠다. 나쁘지 않지, 그렇지?"},objectives={{138,2048176696},"북동쪽에 있는 머드포 브루트에게서 머드포 망치 6개를 모아 블랙스톤 섬의 러스트게이트 능선에 있는 집행관 그리지에게 돌아가십시오."},progress={{52,1896412865},"자, 대단한 사람아, 이제 고블린의 패권을 확립했나?"},completion={{420,1186988911},"이런, 돌아왔군. 망치까지 들고, 게다가 살아있었잖아! 네 소문이 다 사실이었군.$B$B내가 말하진 않았지만, 정말 고마워. 원래 내가 머드포우들을 처리하기로 되어 있었는데, 네가 대신 해줬잖아!$B$B<그리지는 크게 웃음을 터뜨린다.>$B$B이렇게 잘해줬으니 보상해줘야겠군. 자, 내 낡은 망치 하나 줄게."}}
rows[41203]={title={{17,1747421981},"재로 덮인 편지"},description={{400,1573179341},"당신이 열심히 일하는 동안, 러스트게이트 리지에서 편지가 하나 왔어요. 메이튼 붐라이플이라는 사람이 보낸 건데, 이 근처에서 총 쏘는 걸 좋아하는 녀석들을 훈련시키고 있대요. 러스트게이트 리지는 여기서 동쪽으로 언덕 위로 올라가면 있어요. 길을 따라가면 바로 보일 거예요. 편지를 받아두고 시간 날 때 메이튼과 얘기 좀 해 보세요. 하하, 내가 무슨 소리를 하는 거야. 당신한테 시간이 있을 리가 없잖아. 자, 이제 다시 일하러 가!"},objectives={{99,626979891},"재로 뒤덮인 편지를 동쪽 언덕 위 러스트게이트 능선에 있는 집행관 그리지에게 가져다 주세요."},progress={{49,957964851},"이봐, 친구! 아직도 탄광에서 고생하고 있어?"},completion={{302,667565684},"여기 오셔서 반갑습니다. 솔직히 말씀드리면, 처음 오셨을 때 체격이 정말 좋으셨더군요. 작업장에서 일하시는 모습을 보니 얼마나 강인하신지 알 수 있었습니다. 여기 생활이 좀 더 편해지실 수 있도록 몇 가지 팁이나 요령이 필요하시면 말씀하세요. 분명 돈값을 하실 겁니다."}}
rows[41204]={title={{19,719260481},"상형문자로 덮인 편지"},description={{400,1573179341},"당신이 열심히 일하는 동안, 러스트게이트 리지에서 편지가 하나 왔어요. 메이튼 붐라이플이라는 사람이 보낸 건데, 이 근처에서 총 쏘는 걸 좋아하는 녀석들을 훈련시키고 있대요. 러스트게이트 리지는 여기서 동쪽으로 언덕 위로 올라가면 있어요. 길을 따라가면 바로 보일 거예요. 편지를 받아두고 시간 날 때 메이튼과 얘기 좀 해 보세요. 하하, 내가 무슨 소리를 하는 거야. 당신한테 시간이 있을 리가 없잖아. 자, 이제 다시 일하러 가!"},objectives={{102,86786860},"상형문자가 새겨진 편지를 러스트게이트 능선 동쪽 언덕 위에 있는 위제트 아이스휘슬에게 가져다 주세요."},progress={{35,725930034},"안녕하세요! 여기서 뵙게 되어 반갑네요."},completion={{275,1598687118},"어떤 이들은 신비로운 마법을 익히려면 수년간의 꾸준한 노력이 필요하다고 말합니다. 하지만 저는 단호히 반대합니다! 가장 간단한 비법이야말로 가장 많은 돈을 벌어다 주는 비법입니다. 은화 몇 닢만 있으면 마법으로 만들어낸 물을 필요한 불쌍한 사람들에게 팔아 안정적인 수입을 올릴 수 있을 겁니다!"}}
rows[41205]={title={{17,917939085},"진흙투성이 편지"},description={{400,1573179341},"당신이 열심히 일하는 동안, 러스트게이트 리지에서 편지가 하나 왔어요. 메이튼 붐라이플이라는 사람이 보낸 건데, 이 근처에서 총 쏘는 걸 좋아하는 녀석들을 훈련시키고 있대요. 러스트게이트 리지는 여기서 동쪽으로 언덕 위로 올라가면 있어요. 길을 따라가면 바로 보일 거예요. 편지를 받아두고 시간 날 때 메이튼과 얘기 좀 해 보세요. 하하, 내가 무슨 소리를 하는 거야. 당신한테 시간이 있을 리가 없잖아. 자, 이제 다시 일하러 가!"},objectives={{66,337901902},"진흙 묻은 편지를 러스트게이트 능선에 있는 메이튼 붐라이플에게 가져다 주세요."},progress={{42,1948889091},"오! 멋진 붐스틱을 갖고 계시네요."},completion={{290,577160771},"당신도 저처럼 총을 좋아하시는군요. 총은 정말 아름답지 않나요? 적에게 구멍을 뚫는 것 외에도 온갖 재밌는 일에 쓸 수 있는 놀라운 도구죠. 당신이 돈을 좀 나눠주신다면 저도 멋진 사격 기술 같은 걸 몇 가지 알려드릴 수 있습니다. 여기서는 주고받는 게 중요하잖아요?"}}
rows[41206]={title={{12,1001073815},"블랙 레터"},description={{400,1573179341},"당신이 열심히 일하는 동안, 러스트게이트 리지에서 편지가 하나 왔어요. 메이튼 붐라이플이라는 사람이 보낸 건데, 이 근처에서 총 쏘는 걸 좋아하는 녀석들을 훈련시키고 있대요. 러스트게이트 리지는 여기서 동쪽으로 언덕 위로 올라가면 있어요. 길을 따라가면 바로 보일 거예요. 편지를 받아두고 시간 날 때 메이튼과 얘기 좀 해 보세요. 하하, 내가 무슨 소리를 하는 거야. 당신한테 시간이 있을 리가 없잖아. 자, 이제 다시 일하러 가!"},objectives={{62,312586465},"블랙 레터를 러스트게이트 리지에 있는 레일리 퀵텅에게 가져다 주세요."},progress={{40,536869313},"쉿, 쓸데없는 소리 낼 필요 없어."},completion={{252,634424798},"인생의 가장 중요한 목표는 무엇일까요? 무고한 사람들을 돕는 것? 평화를 이루고 비극을 끝내는 것? 쳇, 말도 안 돼! 인생의 목표는 번영이어야 합니다! 부! 값진 황금! 그 돈 좀 나눠주면 부자들을 어떻게 괴롭히는지 금방 알게 될 겁니다."}}
rows[41207]={title={{13,1918239942},"서명된 편지"},description={{277,786658113},"당신이 열심히 일하는 동안, 러스트게이트 리지에서 편지가 하나 왔어요. 메이튼 붐라이플이라는 사람이 보낸 건데, 이 근처에서 총 쏘는 걸 좋아하는 녀석들을 훈련시키고 있대요. 러스트게이트 리지는 여기서 동쪽으로 언덕 위로 올라가면 있어요. 길을 따라가면 바로 보일 거예요. 편지를 받아두고 시간 날 때 메이튼과 얘기 좀 해 보세요. 하하, 내가 무슨 소리를 하는 거야. 당신한테 시간이 있을 리가 없잖아. 자, 이제 다시 일하러 가!"},objectives={{60,1957525996},"서명된 편지를 러스트게이트 리지에 있는 암리 데몬딜에게 가져다 주세요."},progress={{31,615411369},"헤헤, 안녕하세요, 동료 신입 회원님!"},completion={{275,805545121},"더 강력한 마법을 갈망하는 눈빛이 보이는군, 그렇지? 당연하지, 이 세상에서는 강한 자들이 자연스럽게 부자가 되니까. 러스트게이트와 그의 탑을 봐라. 살아있는 증거지! 내게 동전을 좀 던져주면 네가 원하는 무엇이든 될 수 있도록 도와줄게."}}
rows[41208]={title={{25,479930401},"마음에 새겨둘 교훈"},description={{562,285193551},"어이, 다시 돌아왔군? 더 배우고 싶은가? 네 실력이 놀라워. 첫 번째 소환 마법을 시전할 수 있을 것 같군. 하지만 가르쳐주기 전에 부탁 하나만 들어줄래? 네가 날 도와주면 나도 널 도와줄 수 있지. 간단한 개념이지. 남쪽 $B$B해안을 따라 마크루라들이 살고 있는데, 어떤 마크루라는 다른 마크루라보다 더 적대적이야. 많은 사람들이 모르지만, 그들의 심장은 단순해 보이지만 엄청난 힘을 가지고 있지. 마크루라가 공격적일수록 심장의 힘도 더$B$B 강해. 그들의 뛰는 심장 여섯 개를 가져오면 곧 너만의 하수인을 소환할 수 있게 될 거야."},objectives={{73,845254694},"러스트게이트 리지에서 아므리 데몬딜에게 마크루라 하트 6개를 가지고 돌아오세요."},progress={{35,1662638475},"서두르세요, 오래 뛰지 않을 거예요!"},completion={"Oho! You can literally feel and hear their energy. $n, I am keeping my promise. Listen well, and execute properly. Even summoning an imp can be difficult at first. You'll get the hang of it in no time, I am sure.","오호! 그들의 에너지를 실제로 느끼고 들을 수 있어요.$n, 약속을 지키고 있습니다. 잘 듣고 제대로 실행하세요. 악마를 소환하는 것도 처음에는 어려울 수 있지만, 금방 익숙해질 거예요."}}
rows[41209]={title={{23,395559142},"부서진 절벽 점검"},description={{689,1118416602},"투자개발회사는 스톤탈론에서 매우 활발하게 활동해 왔습니다. 자연의 아름다움을 훼손하고, 가는 곳마다 산업의 흔적을 남기고 있죠. 그들이 착취하는 곳 중 하나가 바로 이곳 남동쪽, 스톤탈론 봉우리로 올라가는 길 바로 서쪽에 자리 잡은 브로큰 클리프 광산입니다. 제 정보에 따르면, 그곳은 딥모스$B$B 거미떼에게 점령당했고, 거미들은 도망치면서 광산에서 일하던 대부분의 사람들을 잡아먹었다고 합니다. 자연은 결코 얕볼 수 없는 존재인데, 탐욕스러운 고블린들은 계속해서 자연을 얕보고 있습니다. 당신이 브로큰 $B$B클리프 광산으로 가서 그곳의 야영지를 샅샅이 뒤져 그들의 계획에 대한 문서를 찾아주셨으면 합니다. 다음번에는 우리가 한 발 앞서 나갈 수 있을지도 모릅니다."},objectives={{121,1561466707},"부서진 절벽 광산을 샅샅이 뒤져 스톤탈론 산맥의 스톤탈론 봉우리에서 달라나스 스위프트페더에 관한 문서를 모두 찾아내십시오."},progress={{37,604517693},"그래서, 뭔가 가치 있는 걸 찾으셨나요?"},completion={{324,1054519282},"음...$B$B<달라나스는 문서를 꼼꼼히 살펴본다>$B$B그들의 노력은 대부분 블랙샌드 유전에 집중된 것으로 보이지만, 향후 개발 계획도 있는 것 같습니다. 작업 현장에서 이것을 회수해낸 것은 정말 잘한 일입니다. 스톤탈론 피크에서 보내는 우리의 감사의 표시로 이 동전들을 받으십시오."}}
rows[41210]={title={{24,868085716},"듀로타르 노동의 시작"},description={{844,690966525},"이봐 꼬마야, 듀로타르 노동조합이 돌발톱 산맥에서 시작됐다는 거 알고 있었니? 네르트 블래스텐톰도 한때 투자개발회사에서 일하다가 갑자기 떠났지. 그건 흥미로운$B$B 이야기지만, 스톤탈론 자체가 투자개발회사의 활동 거점이 되어버렸다는 사실은 변함이 없어. 그들은 모든 게 시작된 그 작은 계곡에서 정확히 무슨 일이 일어났는지 조사하기 시작했어. 듀로타르 노동조합은 우리의 흔적을 최대한 감춰야 하는데, 그러려면 용병 일을 좀 해야 해. 그래야 그들이 아무것도 알아채지 못할 테니까. 파우더 타운 북동쪽에 있는 벤처 캠프로 가. 파우더 타운에서 동쪽으로 나가서 북쪽으로 계속 가면 산으로 이어지는 길이 나올 거야. 거기에 도착하면, 그들을 처치하고 투자개발회사의 증거를 회수해 와. 그리고 내게 돌아오면 돼. 간단하지."},objectives={{146,1643566318},"파우더 타운 북동쪽에 있는 벤처 캠프에서 벤처 회사 관련 증거를 회수하여 스톤탈론 산맥에 있는 갈모 타즈렌치에게 돌아가십시오."},progress={{39,1117334966},"그래서, 뭐라도 찾는 데 성공했어?"},completion={{261,1216063897},"이것 좀 봐. 결국 뭔가를 찾아냈군. 우리가 재빨리 뺏어낸 게 정말 다행이야.$B$B임무 잘 수행했네, 용병. 수고비로 돈 좀 받아가. 우리 듀로타르 노동조합원들은 훌륭한 일에는 돈을 지불하지."}}
rows[41211]={title={{12,649298935},"해충 방제"},description={"We have received notice from Orgrimmar. The Warchief wishes to use the abandoned mine just before Stonetalon Peak for additional resources that the Horde is in dire need of. Ever since its desolation after the Third War it was used by the Venture Company to mine from, but now the aggressive Deepmoss spiders have taken residence in the mine's old tunnels. The Horde cannot reliably gather resources with the mine suffering from infestation.$B$B$n, do your part for the Horde's prosperity and cleanse the Broken Cliff Mine of the eight-legged pests. You can find the mine by turning west on the ascension to Stonetalon Peak.","오그리마에서 통보가 들어왔습니다. 대족장께서 호드에 절실히 필요한 자원을 확보하기 위해 스톤탈론 봉우리 바로 전에 있는 버려진 광산을 이용하려 하십니다. 3차 전쟁 이후 황폐해진 이 광산은 용병단이 자원을 채굴하던 곳이었지만, 지금은 공격적인 심해거미들이 옛 갱도에 서식하고 있습니다. 심해거미 때문에 호드는 안정적으로 자원을 채취할 수 없습니다. , 호드의 번영을$B$B$n 위해 부서진 절벽 광산을 여덟 발 달린 해충들로부터 정화해 주십시오. 광산은 스톤탈론 봉우리로 올라가는 길에서 서쪽으로 향하면 찾을 수 있습니다."},objectives={{123,1119279127},"부서진 절벽 광산 내부와 주변의 딥모스 개체수를 줄이고, 선 록 은신처에 있는 매그란 어스바인더에게 돌아가십시오."},progress={{161,1495010488},"딥모스 거미는 돌발톱 산맥에 골칫거리입니다. 이 거미들은 험준한 절벽을 지나가는 무고한 여행자들을 너무나 자주 매복 공격해 왔습니다."},completion={{306,305451534},"돌아왔군. 이번 모험으로 몰라보게 강해진 것 같아. 광산은 정리됐나 보군. 오늘 호드를 위해 훌륭한 공을 세웠어. 네 공적을 오그리마에 알리도록 하지. 자원이 점점 고갈되어 가는 상황에서 대족장께서도 네 야심찬 뜻을 인정하실 거야. 분명 그럴 거라고 확신해."}}
rows[41212]={title={{14,1422009857},"더 깊이 파헤쳐보기"},description={"If what Faldan said is true - and I trust his words - then this whole ordeal goes further than my initial assumption. While I am sure the Venture Co.'s violations against nature might not have been the catalyst for the spider's change in behaviour, they surely played a vital role in accelerating it. However, to verify this presumption, we need to gather more samples and ultimately, more evidence.$B$BMy brethren on top of Stonetalon Peak report of increasing hostility by the local spiders calling the Broken Cliff Mine their home. From what I can deduct, this is all too similar to what can be observed in the Windshear Crag.$B$B$n, please aid me again by bringing me the spiders' brains, more this time, eight samples shall be enough. I dare not think of the true reason behind it all - and frankly, I wish to be proven wrong. You can find the mine by turning westwards just before you reach Stonetalon Peak.","팔단이 한 말이 사실이라면(저는 그의 말을 믿습니다), 이 모든 일은 제 처음 예상보다 훨씬 더 복잡한 문제입니다. 투자개발회사의 자연 파괴 행위가 거미의 행동 변화를 직접적으로 촉발한 것은 아닐지라도, 그 변화를 가속화하는 데 중요한 역할을 했을 것은 분명합니다. 하지만 이 추측을 검증하려면 더 많은 샘플과 증거를 수집해야 합니다. 스톤탈론 봉우리 $B$B꼭대기에 있는 제 동료들은 브로큰 클리프 광산을 서식지로 삼는 지역 거미들의 적대감이 점점 심해지고 있다고 보고했습니다. 제가 보기에는 윈드셰어 크래그에서 관찰되는 현상과 매우 유사합니다. 자, 다시$B$B$n 한번 거미의 뇌를 가져다 주십시오. 이번에는 더 많이, 여덟 개면 충분합니다. 이 모든 일의 진짜 원인을 감히 짐작할 수 없으며, 솔직히 제 생각이 틀렸으면 좋겠습니다. 스톤탈론 봉우리에 도착하기 직전 서쪽으로 향하면 광산을 찾을 수 있습니다."},objectives={{93,317090839},"스톤탈론 산맥의 바엘 하르둘에서 말로란 오크브랜치를 위해 딥모스 러커 뇌 8개를 모으세요."},progress={"$n, how does your search for samples fare?","$n님, 샘플 검색은 어떻게 진행되고 있나요?"},completion={{515,2079802970},"내 예상대로군. 똑같이 희미한 불길한 마법의 기운이 이 거미들의 뇌리에 스며들어 있어. 하지만 부서진 절벽 광산의 거미들에게서는 그 기운이 훨씬 더 강하게 느껴지는 것 같아. 도대체 이유가 뭘까? 어쩌면 그들이 지하에서 사는 것이 중요한 요인일지도 몰라. 이 문제와 내 연구 결과에 대해 팔단과 상의해야겠어. 할 얘기가 많군.$B$B그럼에도 불구하고, 자네는 내 연구에 큰 도움을 주었네. 하지만 이 수수께끼를 풀기 위해서는 아직 할 일이 많고, 칼림도르를 위해서라도 최대한 빨리 해결해야 하네."}}
rows[41213]={title={{21,1611657641},"벤처 기업 확장"},description={{796,827103828},"이봐, 돈 좀 찾고 있냐? 내가$B$B 아주 중요한 일을 빨리 처리해야 해. 투자개발회사가 스톤탈론에서 계속 확장하면서 자원 전쟁에 더 많은 부하들을 끌어모으고 있어. 그들이 한 발 한 발 땅에 발을 디딜 때마다 우리 영향력이 줄어들고 있다고! 여기서 $B$B북동쪽으로 조금만 가면 벤처 캠프라는 작은 곳이 있는데, 지금 그곳이 새로운 벌목 작업의 중심지야. 악명 높고 잔혹한 감독관인 파즈윅 롱퓨즈가 그곳을 이끌고 있는데, 케잔 출신이라면 그의 이름이 낯설지 않을 거야. $B$B파우더 타운이 살아남으려면 그들을 돌발톱 산맥에서 완전히 몰아내고 다시는 돌아오지 말라는 경고를 보내야 해! 벤처 캠프를 찾아서 파즈윅 롱퓨즈와 네 앞길을 막는 부하들을 모두 처치해, 알겠지?"},objectives={{168,1564485339},"스톤탈론 산맥의 파우더 타운에 있는 벤처 캠프 근처에서 감독관 파즈윅 롱퓨즈를 처치하고 벤처 중대 완장 15개를 모아 보안관 모트 토즐퓨메에게 보상하십시오."},progress={{48,2055647877},"우리의 안전은 여러분의 행동에 달려 있습니다. 어서 행동에 나서세요!"},completion={{138,550937607},"벤처 컴퍼니와의 전쟁에서 우리는 승리에 한 걸음 더 다가섰습니다. 물론 당신의 행동 덕분은 아니지만요. 자, 감사의 표시로 이걸 받으십시오."}}
rows[41214]={title={{16,434320281},"특이한 나무꾼들"},description={{600,609091941},"이 땅은 쿠엘탈라스의 아름다움을 닮아 있지만, 그 유사점 속에는 흥미로운 차이점이 숨어 있습니다. 현재 저는 이 영역을 장식하는 트렌트들을 연구하는 데 몰두하고 있습니다. 그들은 어딘가 낯익은 모습을 하고 있지만, 제가 이해하기 어려운 기묘한 면모를 지니고 있습니다. $B$B혹시라도 이 존재들 중 하나에게서 원시의 심장을 얻을 수 있다면 제 연구에 큰 도움이 될 것입니다. 저는 전투에 능숙하지 않고, 경비병들이 제가 너무 가까이 다가가는 것을 막아왔습니다. 하지만 당신에게는 그런 문제가 없을 거라고 생각합니다. 어떻게 생각하십니까?"},objectives={{98,885447510},"아나스테리안 공원에 있는 탈라시안 트렌트에게서 칼히르 던체이서를 위한 탈라시안 원시 심장을 획득하세요."},progress={{374,1796548370},"우리 앞에 있는 이 조각상을 보십시오. 춤추는 한 쌍이라는 소중한 이상을 증명하는 유물입니다. 우리 민족의 오랜 전설에는 달과 태양의 신비로운 춤이 전해 내려오는데, 그들은 영원히 가까이 있지만 결코 서로 닿지 않습니다. 이러한 개념은 퀘르도레이의 춤에도 적용되어, 두 파트너가 서로에게 우아하게 다가가지만 물리적인 접촉 없이도 매혹적인 친밀감을 유지합니다."},completion={"I hope these pesky guards weren't much of an issue. Thank you, $C. This will be invaluable in my research.","이 성가신 경비원들이 큰 문제가 되지 않았기를 바랍니다.$C님, 감사합니다. 이 정보는 제 연구에 매우 유용할 것입니다."}}
rows[41215]={title={{18,449155895},"가을의 속삭임"},description={{630,942415090},"서쪽에는 영원한 가을의 섬이 있습니다. 우리 민족 사이에서 거의 잊혀진 전설이죠. 수천 년 전, 우리가 이 땅에 처음 발을 디뎠을 무렵, 우리 중 일부는 새로운 세계수를 심으려 애썼습니다. 하지만 그 시도는 실패했고, 저주받은 나무는 땅 전체에 변혁적인 마법을 걸어 영원한 가을에 빠뜨렸습니다. 섬은 사라질 수도, 진정으로 번성할 수도 없게 되었고, 과거의 야망이 잘못된 결과를 낳았음을 보여주는 증거가 되었습니다. 저는 당신에게 이 $B$B신비로운 섬으로 여행을 떠나 그곳에 살고 있는 나무 정령들로부터 원시의 심장을 얻어오라고 부탁합니다. 당신의 노력은 결코 헛되지 않을 것입니다."},objectives={{96,2090128558},"아나스테리안 공원의 가을 나무 정령에게서 칼히르 새벽추적자를 위한 탈라시안 원시 심장을 획득하세요."},progress={{243,960015290},"전설에 따르면 섬에 너무 오래 머무르는 사람들은 시간의 흐름을 잊어버린다고 합니다. 영원한 가을에서 위안을 찾는 동안, 본토에서는 계절은 물론이고 몇 년이라는 시간이 훌쩍 지나가 버린다는 사실을 깨닫지 못한다고 하죠. 그러니 여행자여, 조심하십시오."},completion={{137,2116260432},"정말 아름답군! 이제 이 두 심장을 손에 넣었으니, 이 땅의 감춰진 비밀들이 섬세한 태피스트리처럼 내 앞에 펼쳐지리라."}}
rows[41216]={title={{19,734066688},"하이랜드의 위협"},description={{757,453328140},"타우마리움에 오신 것을 환영합니다. 이곳에서 저의 매혹적인 아내는 탈라시안 고원을 빛낼 최고급 와인을 양조하고 있습니다. 저희는 퀘르탈라스에 있던 옛 와이너리와 같은 이름을 이 안식처에 붙여, 저희 사업의 번영을 간절히 $B$B기대하고 있습니다. 하지만 저희에게는 난처한 일이 생겼습니다. 저희는 이 성역의 남동쪽 언덕에 포도밭을 조성하고자 합니다. 그곳의 미기후는 포도 재배에 매우 적합합니다. 그러나 안타깝게도 이 언덕에는 사나운 스라소니들이 들끓어 저희 일꾼들이 평화롭게 밭을 갈 수 없습니다. 부디 가능한 한 많은 스라소니를 처치하고 그 가죽을 가져와 주시면 감사하겠습니다. 당신의 도움은 결코 헛되지 않을 것입니다."},objectives={{65,1495618046},"마법의 세계에 있는 마엘로르 스틸가드에게 밝은 살쾡이 털 10개를 가져다 주세요."},progress={{59,1469255956},"조심하세요, 이 생물들은 생각보다 훨씬 사납습니다."},completion={{158,1735822511},"하나, 둘, 셋... 그리고 스물열 개! 정말 놀라운 일입니다. 이렇게 부지런히 노력한다면 곧 산들이 안전해져서 우리 노동자들이 두려움 없이 다시 일을 시작할 수 있을 겁니다."}}
rows[41217]={title={{17,1036798091},"복수할 원한"},description={"I must burden you with one more request, $N. A few weeks past, as I scoured the hills in search of ideal spots for grape cultivation, I fell victim to a lynx of unparalleled ferocity. In the ensuing struggle, the creature overpowered me, leaving me grievously wounded, my eye forever lost.$B$BA personal vendetta now brews within me against this formidable adversary. Vanquish the beast and retrieve its fang as evidence. I will easily recognize it; the fangs were larger than any I have ever seen.",", 부탁 하나만 더 드려야겠소. 몇 $N주 전, 포도 재배에 적합한 장소를 찾아 언덕을 샅샅이 뒤지던 중, 나는 엄청난 사나움을 지닌 스라소니의 공격을 받았소. 그 싸움에서 나는 제압당했고, 심각한 부상을 입어 한쪽 눈을 영영 잃어버렸소. 이제 나는 이 $B$B무시무시한 적에게 복수심을 불태우고 있소. 그 짐승을 처치하고 증거로 송곳니를 가져와 주시오. 나는 쉽게 알아볼 수 있을 것이오. 그 송곳니는 내가 지금까지 본 어떤 송곳니보다도 컸소."},objectives={{70,381887980},"당신의 공적을 증명하기 위해 샤를란의 송곳니 1개를 마엘로르 강철수호자에게 가져오십시오."},progress={{20,1034473968},"물리면 위험하니 조심하세요."},completion={{311,1470306523},"확실히 이 송곳니는 나를 괴롭혔던 흉포한 짐승의 것이었다. 이제 그 짐승을 물리쳤으니, 내 일꾼들은 서둘러 산으로 돌아갈 수 있겠군. 내게 평생 잊을 수 없는 상처를 남긴 그 짐승이 더 이상 살아 있지 않다는 사실에 깊은 만족감을 느낀다."}}
rows[41218]={title={{19,1697283422},"언덕 위의 포도"},description={{566,570395026},"안녕하세요, 친구분. 저희의 유명한 와인을 맛보러 오셨나요? 안타깝게도 끊임없는 스라소니의 공격 때문에 언덕 지역의 포도 재배가 중단되어 포도를 한 방울도 얻지 못했습니다. 하지만 $B$B저는 이 혼란 속에서도 저희 일꾼들이 이곳 남동쪽 언덕에 포도가 가득 담긴 양동이를 남겨두었을지도 모른다는 희망을 품고 있습니다. 포도가 약간 발효되었을 수도 있지만, 와인 양조의 본질은 바로 그런 미묘한 차이를 받아들이는 데 있지 않을까요? 만약 당신이 포도 양동이 열 개라도 찾아주신다면, 손님들을 위해 와인을 만들어낼 수 있을 겁니다! 당신의 도움은 정말 큰 힘이 될 것입니다."},objectives={{68,938854741},"마법의 방에 있는 파인리엘 실버하프에게 포도 10통을 가져다 주세요."},progress={{82,1868415129},"스라소니를 조심하세요! 제 사랑하는 마엘로르가 스라소니와 싸우다가 한쪽 눈을 잃었어요."},completion={{261,1088596008},"태양샘의 이름으로 맹세코, 정말 감사합니다! 거창한 건 아닐지 몰라도, 이 어려운 시기에 조금이라도 도움을 주시면 진심으로 감사드리겠습니다. 감사의 표시로 이 물약들을 받아주세요. 제가 드릴 수 있는 어떤 와인보다도 지금 당신에게 더 도움이 될지도 모르겠습니다. 부디 안전한 여행 되소서, 친구."}}
rows[41219]={title={{22,1409570292},"하이랜드의 용들"},description={{619,596370389},"실버 코버넌트의 일원으로서 우리의 임무는 명확합니다. 피난처를 찾는 난민들을 위협하는 모든 위험으로부터 이 땅을 정화하는 것입니다. 이러한 위협 중에서도 특히 마나 와이번의 급증은 심각한 문제입니다. 마나 와이번들은 주변의 마나를 흡수하며 그 수가 기하급수적으로 늘어나 우리가 추구하는 균형을 깨뜨리고 있습니다.$B$B I는 당신에게 마나 와이번을 처치하고 그 증거로 마나 와이번의 눈 10개를 가져오라는 임무를 맡깁니다. 이 임무는 이 땅에 평화를 가져올 뿐만 아니라, 수집된 눈은 마나 크리스탈을 충전하는 촉매제 역할을 하여 두 가지 문제를 동시에 해결할 수 있습니다."},objectives={{69,1860387820},"실버 코버넌트 캠프에 있는 브레이든 사령관에게 마나 와이번 아이즈 10장을 가져다 주세요."},progress={"Yes, $c?","네,$c번이요?"},completion={"Thank you, $c. The roads are safer, and I'll make sure the charged mana crystals are distributed among the poorest of our kin.","고마워요,$c. 도로가 더 안전해졌고, 충전된 마나 수정은 우리 동족 중 가장 가난한 사람들에게 나눠주도록 하겠습니다."}}
rows[41220]={title={{20,2009298993},"가난한 자들을 위한 잔치"},description={{727,1980100345},"발라도르 예배당에 오신 것을 환영합니다. 이곳은 어려운 시기에 빛 속에서 위안을 찾는 이들을 위한 안식처입니다. 태양샘이 사라졌지만, 그 빛은 여전히 ​​하늘에서$B$B 우리를 비추고 있습니다. 친애하는 친구여, 작은 부탁 하나 드려도 될까요? 쿠엘탈라스의 가난한 사람들을 위한 잔치를 준비하는 과정에서 식량이 부족합니다. 귀족 가문들이 아낌없이 기부해 주셨지만, 여전히 식량이 $B$B부족합니다. 순찰대원들에게서 스톨혼 사슴 고기가 특히 맛있다는 이야기를 들었고, 저는 개인적으로 크림슨 호크스트라이더 날개를 좋아합니다. 각각 12개씩 구해 주실 수 있다면, 오랫동안 기억될 잔치를 열 수 있을 것입니다."},objectives={{99,1684373522},"발라도르 예배당에 있는 탈리렌에게 사슴뿔 고기 덩어리 12개와 진홍빛 매타조 날개 12개를 가져가야 합니다."},progress={{61,165254799},"이 두 생물은 모두 파스트라이드 전역에서 찾아볼 수 있습니다."},completion={{479,1764343041},"모험가님, 감사의 말씀을 드립니다. 하지만 예상치 못한 상황 변화로 인해 저희 계획이 변경되었습니다.$B$B아스탈로르 선스원 경께서는 당신이 모은 자원을 그의 귀족 후원자들을 위한 호화로운 연회에 사용하라고 지시하셨습니다. 비록 이 풍요로움을 불우한 이들에게 나누어 줄 수 없다는 사실을 전하게 되어 마음이 아프지만, 그의 결정에 이의를 제기하는 것은 제 권한 밖입니다. 그럼에도 불구하고, 친구여, 당신의 노력과 관대함에 진심으로 감사드립니다."}}
rows[41221]={title={{14,1079491892},"리아드린의 간청"},description={"No! I cannot allow such injustice to persist!$B$B$C, we must not silently endure this affront to our people. The nobles indulge in opulent feasts, savoring lavish meats and exotic fruits, while the common folk languish, starving and withering away on the streets.$B$BI am confined within the chapel, unable to confront Lord Astalor myself, but I implore you. Take this letter to that despot Astalor. I harbor doubts that it will sway his heart, but he must be made aware of the sentiments burning within me.","안 돼! 이런 불의가 계속되는 것을 두고 볼$B$B$C 수 없어! 우리 백성들이 당하는 이 모욕을 침묵 속에 참아낼 수는 없어. 귀족들은 호화로운 연회를 즐기며 값진 고기와 이국적인 과일을 맛보는 동안, 평민들은 거리에서 굶주림에 시달리며 죽어가고 있어. $B$B나는 지금 예배당에 갇혀 아스탈로르 영주를 직접 대면할 수 없지만, 부디 이 편지를 그 폭군 아스탈로르에게 전해 주시길 간곡히 부탁한다. 그의 마음을 바꿀 수 있을지는 의문이지만, 내 마음속에 타오르는 분노를 그에게 꼭 전해야 해."},objectives={{104,506342920},"리아드린의 편지를 아스탈로르 선스원에게 가져다 주세요. 그는 알라탈라스 북쪽에 있는 저택에 있습니다."},progress={{34,1251030227},"내 경비원들은 왜 당신을 여기로 들여보냈죠?"},completion={{372,1977870052},"<아스탈로르 선스원(아스탈로르 선스원)은 편지를 열어 내용을 훑어본 후 비웃듯이 웃었다.>$B$B감히 내 저택에 들어와 나를 모욕하려 하다니, 네놈을 경비병들에게 시켜 산 채로 가죽을 벗겨 죽여야 마땅하다. 하지만 지금 심부름꾼이 필요하다. 이… 리아드린이라는 놈에게 내 답장을 전해 주어라. 이 일은 내 경비병들의 체면을 깎아내리는 일이다."}}
rows[41222]={title={{17,1126909208},"선스원의 답신"},description={{811,253696934},"내가 한 말을 모두 그녀에게 다시 전해 줘. 내$B$B 자원은 내가 원하는 대로 쓸 수 있고, 지금 이 순간 그 자원은 진정으로 중요한 사람들의 의견에 영향을 미치는 데 쓰일 거야. 왕좌는 내 것이 될 거고, 내 통치 아래 우리 백성은 번영할$B$B 거야. 물론 이 자원을 가난한 사람들에게 나눠줄 수도 있겠지. 하지만 무슨 소용이 있겠어? 바로 다음 날이면 그들은 또다시 궁핍해질 텐데. 우리는 그들을 부양할 수 있는 탄탄한 기반 시설, 즉 농장, 포도원, 제대로 된 사냥터를 구축해야 해. 단순히 하루 식량만 제공하는 것으로는 아무것도 이룰 수 없어. 안심해. 왕관을 내가 차지하면 퀘르도레이 백성의 복지를 최우선 과제로 삼을 거야. 하지만 그 비전이 실현되기 전에 누군가가 희생되어야 한다면… 그건 유감스러운 일이지. 자, $B$B이제 가거라. 그리고 리아드린에게 이 모든 말을 꼭 전해 줘."},objectives={{69,1842255473},"발라도르 예배당에서 아스탈로르 선스워른이 리아드린에게 한 말을 되풀이하세요."},progress={{21,27987655},"아스탈로르를 찾으셨나요?"},completion={{487,1637348250},"<당신은 아스탈로르의 말을 여사제에게 빠짐없이 전합니다. 그의 메시지를 전달하는 동안, 당신은 여사제의 눈에서 끓어오르는 분노를 목격합니다. 희미한 초록빛이 그녀의 눈에서 뿜어져 나오며, 그녀의 얼굴은 완전히 다른 사람처럼 변합니다.>$B$B좋아. 그럴 줄 알았지. 얼마나 오만한가. 어떤 대의도 단 한 명의 퀘르도레이라도 계속 고통받게 할 가치는 없어. 우리는 이미 충분히 고통받았고, 나는 아스탈로르가 이 사실을 깨닫도록 할 거야. 곧…"}}
rows[41223]={title={{30,846525201},"내일이 없는 것처럼 신나게 놀아봐"},description={{438,2110158811},"아, 이런 끔찍한 일이 벌어졌네요! 아나스테리안 공원에서 와인, 간식 등 모든 것을 갖춘 멋진 파티를 준비하고 있었는데, 갑자기 무시무시한 괴물 떼가 나타나서 저는 목숨을 걸고 도망쳐야 $B$B했어요! 저는 간신히 살아남았지만, 파티 용품들이 모두 사라져 버렸답니다. 이제 공원 깊숙이 다시 들어갈 엄두가 안 나요. 부디 제 파티 용품들을 찾아주시겠어요? 여기서 다시 파티를 열고 싶은데 말이죠."},objectives={{46,1470797736},"렐라이나 화이트쇼어의 파티 용품을 찾아주세요."},progress={{45,387561046},"그 즐거웠던 일들이 자꾸만 생각나요."},completion={{242,597550943},"오! 찾으셨군요! 정말 감사합니다!$B$B파티에 초대하고 싶지만, 아쉽게도 비공개 행사입니다. 하지만 걱정 마세요. 분명 다음에 함께 즐거운 시간을 보낼 기회가 있을 거예요, 그렇죠?"}}
rows[41224]={title={{20,1450338984},"어떤 상황에서도 사랑은 변치 않는다"},description={{594,694881278},"아서스가 나타났을 때 저는 모든 것을 잃었습니다. 재산도, 영향력도, 집도요. 하지만 폐허 속에서 저는 새로운 것을 발견했습니다. 바로 사랑입니다. 린의 변함없는 지지가 없었다면 이 재앙을 어떻게 견뎌냈을지 $B$B모르겠습니다. 그녀에게 감사를 표하고 싶지만 어떻게 해야 할지 모르겠습니다. 저는 감정 표현에는 영 소질이 없거든요. 좀 이상하게 들릴지 모르지만, 여우털이 그녀의 아름다운 머리카락과 잘 어울릴 것 같습니다. 서쪽의 가을 섬에 여우가 산다고 들었습니다. 여우털을 구해서 바누달 금세공인에게 가져다주면 멋진 스톨을 만들어 줄 수 있을 겁니다…"},objectives={{52,1208105184},"알라탈라스에 있는 바누달 골드웨버에게 여우털을 가져다 주세요."},progress={{36,345864214},"안녕하세요. 무엇을 도와드릴까요?"},completion={{45,1273658254},"케일린이 린에게 선물을 주고 싶어한다고? 더 이상 설명이 필요 없겠지."}}
rows[41225]={title={{13,80123399},"케일린의 선물"},description={{543,108949073},"그가 이렇게 감성적이 될 줄은 몰랐어! 실버문에서는 거리에서 제일 거친 녀석이었는데. 하지만 기분 좋은 놀라움이군. 그가 그녀를 찾아서 $B$B진심으로 기뻐.<바누달은 여우 가죽을 능숙하게 다루며, 뛰어난 솜씨로 $B$B재단하고 바느질했다.>자, 여기. 지금 있는 재료로 만들 수 있는 최선이야. 금실을 좀 넣으면 더 고급스러워질 수도 있겠지만, 실버문 유적지로 여행을 떠날 준비는 아직 안 됐겠지? 케일린에게 달라란 레드 와인 한 병을 빚졌다고 전해줘!"},objectives={{38,156183459},"카엘린 블레이드송에게 스톨을 선물하십시오."},progress={{12,603155285},"성공 사례라도 있나요?"},completion={{142,2026768034},"<카엘린이 스톨을 바라본다>$B$B그래, 완벽해. 내 생각엔… 내 사랑하는 사람에게 정말 잘 어울릴 거야. 그녀의 놀란 표정을 보는 게 너무 기대돼."}}
rows[41226]={title={{23,2102631438},"마법으로 봉인된 편지"},description={{326,2068100303},"마법사님, 당신의 열정과 재능은 정말 훌륭합니다. 하지만 한 가지 경고할 것이 있습니다. 태양샘이 사라진 지금, 당신의 마법이 오히려 당신에게 불리하게 작용할$B$B 수도 있습니다. 다행히도, 이 문제를 해결해 줄 수 있는 사람이 있습니다. 강력한 마법사 알라쇼르가 도움을 주겠다는 편지를 보냈습니다. 꼭 그를 찾아가 보시는 것이 좋겠습니다."},objectives={{44,1861979827},"브린틸리엔에 있는 알라쇼르 프로스트파이어에게 말을 걸어보세요."},progress={{11,2119832196},"발라 대시."},completion={{46,193257697},"오셔서 정말 다행입니다. 자, 이제 시작하겠습니다."}}
rows[41227]={title={{14,2095004620},"우아한 편지"},description={{431,207015140},"자네도 우리 동맹군에 합류하여 무기를 들었나 보군. 자네는 이제 빛의 충실한 병사가 되었군. 새로 얻은 $B$B믿음 안에서 자네가 우리 동족들을 그토록 쉽게 억눌렀던 제약들을 극복할 수 있기를 바라네. 영원한 태양 앞에서도 우리는 빛의 인도를 받았지. 자네와 같은 병사 한 명이 자네의 관심을 요청했네. 로르타스가 내게 자네에게 이 편지를 전해달라고 부탁했네."},objectives={{34,386892064},"브린틸리엔에 있는 로르타스와 대화하세요."},progress={{20,237328198},"빛과 함께 걸으세요."},completion={{68,2032371444},"부름에 응해주셔서 기쁩니다. 이제 교육을 시작하겠습니다."}}
rows[41228]={title={{22,1805923282},"축복받은 우아한 편지"},description={{524,2054921768},"당신의 머리 주위에는 은혜와 자비의 가장 밝은 빛이 비추고 있습니다. 당신은 우리 백성을 치유하고 보살피는 길을 걸어온 다른 이들과 다를 바 없습니다. 신부님, $B$B저는 당신을 진심으로 존경하고 감탄합니다. 비록 젊은 나이에 시작하셨지만, 저는 당신의 존재를 영광스럽게 생각합니다. 마치 경험이 풍부한 실버선 사제님을 대할 때처럼 말입니다. 실버선 사제님께서는 저에게 이 편지를 신부님께 전하는 임무를 맡기셨습니다. 사제님의 은혜와 지혜는 우리가 직면한 어려운 시기에 분명 큰 도움이 될 것입니다."},objectives={{42,856728341},"브린틸리엔에 있는 마엘라 실버선에게 말을 걸어보세요."},progress={{16,624098027},"빛이 당신을 축복하길."},completion={{46,1357929561},"우리의 임무는 우리가 지닌 유산만큼이나 고귀합니다."}}
rows[41229]={title={{12,749023884},"수상한 편지"},description={{429,1169019463},"당신의 민첩성과 기술은 인상적입니다. 감탄해야 할지 경계해야 할지 모르겠네요. 기분 나쁘게 생각하지 마세요. 당신의$B$B 직업은 우리 조국을 되찾으려는 목표와는 무관합니다. 중요한 건 어떤 상황에서도 최선을 다하는 당신의 능력입니다. 이제 제 말은 그만하고, 누군가 당신을 찾고 있습니다. 어린아이가 전해준 이 편지에는 발신인 이름이 없습니다. 저는 사생활을 존중하고 우편물을 몰래 들여다보지 않기 때문에 이 편지를 당신에게 전달하겠습니다."},objectives={{42,1052146624},"브린틸리엔에 있는 그림자 릴라에게 말을 걸어보세요."},progress={{33,1672832019},"그림자 속에 숨어있는 것을 조심하세요."},completion={{59,1424806394},"이건 결코 싸지 않을 겁니다. 당신은 제게 큰 은혜를 갚아야 할 거예요."}}
rows[41230]={title={{12,1432613431},"일반 편지"},description={{511,316200058},"당신 안에서 분노가 타오르는 것을 느낍니다. 당신의 팔은 떨리고 있지만, 두려움 때문이 아니라 억누르려는 분노 때문입니다. 바로 이런 순간에 우리는 당신처럼 역경에도 굴하지 않는 전사에게 희망을 걸어야 합니다. 당신은 $B$B마법의 혜택을 받지 못했고, 쿠엘탈라스가 함락되기 전에는 무기를 휘두르는 꿈조차 꾸지 못했습니다. 아무것도 가진 것이 없었지만 모든 것을 잃었습니다. 당신의 눈빛에 타오르는 불꽃은 제게 이 편지를 당신에게 전하라고 지시한 발라노스를 떠올리게 합니다."},objectives={{42,626678809},"브린틸리엔에 있는 발라노스 돈파이어와 대화하세요."},progress={{29,90765926},"태양을 향해 무기를 들어라."},completion={{17,252414009},"한 명도 살아남지 못하게 하라."}}
rows[41231]={title={{16,599751794},"깃털 달린 편지"},description={{478,1556200529},"존경받고 명예로운 레인저가 되기를 꿈꾸십니까? 활을 다루는 솜씨는 정말 놀랍습니다. 솔직히 말해서, 명망 높은 마법사가 되는 영광에 버금갈 정도입니다. 안타깝게도$B$B 많은 레인저들이 조국과 함께 목숨을 잃었습니다. 하지만 당신처럼 그들의 발자취를 따르고자 하는 또 다른 이들이 여기 있습니다. 그녀의 경험에서 지혜를 얻으십시오. 그러면 당신과 그녀 모두 미래 세대를 위한 디딤돌이 될 수 있을 것입니다."},objectives={{45,326050832},"브린틸리엔에 있는 루비나 롱스트라이더에게 말을 걸어보세요."},progress={{28,105825823},"당신의 화살이 빠르게 날아가길 바랍니다."},completion={{35,1630626688},"파스트라이더의 유산은 반드시 이어져야 합니다."}}
rows[41232]={title={{17,1070141538},"마음을 찾기 위해"},description={{594,158995015},"우리는 이 불쌍한 영혼이 잠자는 나무 뿌리에서 쉴 수 있도록 허락했습니다. 이것이 그들을 치유하지는 못하겠지만, 적어도 지금은 시들어가는 것을 막아줄 것입니다. 이 땅의 수호자로서, 이곳의 모든 생명은 소중하며 우리가 보살펴야 합니다. 하지만$B$B 당신은 우리의 가치관을 배우기 위해 이곳에 온 것이 아닙니다. 저는 하이본족이 무엇을 원하는지 알고 있으며, 이것이 효과가 있을지는 확신할 수 없지만, 저와 제 자매들은 최선을 다해 도울 것입니다. 덤불에서 잎 몇 장과 매사냥꾼의 심장을 가져오십시오. 당신이 이렇게 하도록 하는 것이 마음 아프지만, 때로는 무언가를 얻으려면 무언가를 내어줘야 합니다."},objectives={{42,414420294},"리네를 만드는 데 필요한 재료들을 모으세요."},progress={{27,754984403},"모두 모으셨나요?"},completion={{83,1980632045},"이 의식을 거행하기 위해 잠시 우리의 손을 맞잡도록 허락해 주십시오."}}
rows[41233]={title={{20,319440708},"당신의 마음은 어디에 있나요?"},description={{501,129710550},"네가 찾는 것은 물속, 여기서 멀지 않은 폐허 속에서 발견될 거야. 그곳에 심장이 잠들어 있지. 네가 그것을 찾기를, 그리고 그것이 네 목표를 이루는 데 도움이 되기를 바라. (라인이 네$B$B 머리를 쓰다듬으며 고개를 갸우뚱거린다.$B$B) 오랫동안 고군분투해 온 것이 네 눈에서 보이구나. 아이야, 쉬는 것도 잊지 마렴. 조금이라도 위안을 얻고 싶다면 우리에게 돌아오렴. 잠자는 나무의 뿌리보다 더 좋은 곳은 없을 거야. 네 $B$B임무를 마치면 비즈네야에게 돌아가렴. 그녀는 무엇을 해야 할지 알고 있을 거야."},objectives={{23,1557732179},"마나 코어를 회수하세요."},progress={{16,2050373469},"제발, 말씀해 주세요."},completion={{50,1002386757},"핵심 부품을 가지고 돌아오셨군요. 이제 시작해도 되겠습니다."}}
rows[41234]={title={{19,461661529},"고대를 일으키다"},description={{470,1335464643},"이제 핵심을 손에 넣었으니 오르데날에게 돌아가기만 하면 됩니다. 그는 앞으로 무엇을 해야 할지 정확히 알 겁니다. 이것은 오랫동안 모습을 드러내지 않았던 고대인의 핵심입니다. 오르데날조차도 당신이 이 핵심을 건네주면 경외감을 느낄$B$B 겁니다. 고대인이 되살아나 알라탈라스 도시 주변에 있게 되면 퀘르도레이의 명상에 도움이 될 것입니다. 하지만 이것 역시 영구적인 해결책은 아닙니다. 그럼에도 불구하고 현재로서는 최선의 방법입니다."},objectives={{29,1564460319},"고대의 신비를 깨워라."},progress={{12,1112843183},"그럼 계속하세요."},completion={{49,1881430264},"고대의 신비로운 존재라니, 어떻게 그럴 수 있지?"}}
rows[41235]={title={{11,2123728622},"스태그헬름으로"},description={{433,882309613},"정말 놀라운 일이군요. 기대 이상입니다. 저 하이본이 무슨 꿍꿍이를 꾸미고 있었는지 전혀 몰랐지만, 엘룬이시여, 수천 년 만에 모습을 드러내지 않았던 고대 존재 앞에 서다니… 이 소식을 $B$B대드루이드께 꼭 전해야 합니다! 부디 이해해 주십시오. 고대 존재들은 칼도레이 문화에서 매우 존경받는 존재이며, 이는 제가 퀘르도레이를 돕는 데 큰 도움이 될 것입니다. 다르나서스에 무사히 도착하시기를 바랍니다. 대드루이드께서 당신에게 마땅한 보상을 내려주실 것을 믿습니다."},objectives={{35,750499024},"다르나서스에서 판드랄 스태그헬름을 찾아야 합니다."},progress={{5,921233587},"무엇?"},completion={{357,817117322},"나는 오르데날이 이렇게 어리석을 줄은 몰랐다. 조금의 생각도 없이 고대의 마법 생물을 소환하다니, 우리 문화와 유산을 노골적으로 조롱하는 짓이로군.$B$B하지만 네 정보는 소중하군. 이미 벌어진 일은 되돌릴 수 없으니, 그런 고대의 마법 생물의 존재 자체가 혐오스럽지만, 어찌 활용될 수 있을지 생각해 보게 되군.$B$B이제 사라져라."}}
rows[41236]={title={{19,1958752393},"은빛 서약단"},description={{751,771019218},"퀘르도레이 정치의 복잡한 사정은 생략하겠습니다. 하지만 반드시 알려드려야 할 중요한 사실입니다. 한때 하나였던 우리 나라는 이제 여러 파벌로 분열되어 영향력과 권력을 놓고 안타까운 다툼을 벌이고 있습니다. 우리 내부의 이러한 불화를 목격하는 것은 제 마음을 아프게 하지만, 이 폭풍을 헤쳐나가야만$B$B 합니다. (그녀는 잠시 말을 멈추고 체념한 $B$B듯한 눈빛을 보였다.) 그러나 이러한 혼란 속에서도 더 큰 비전을 지지하는 이들이 있습니다. 그들은 은빛 언약의 깃발 아래 집결하여 도시 서쪽 너머에 진을 치고 있습니다. 부디 그곳으로 가서 저의 존경하는 오른팔인 브레이든 사령관을 찾아주시길 바랍니다. 그는 이 문제를 부지런히 조사해 왔으며, 당신의 도움에 깊이 감사드리겠습니다."},objectives={{51,2103181141},"실버 코버넌트 진영에서 브레이든 사령관을 찾으세요."},progress={{41,104645935},"윈드러너 여사께서 우리를 승리로 이끌어 주실 것이다!"},completion={{227,961960930},"알겠습니다. 저는 이 지역에 블러드 엘프가 출몰하는지 오랫동안 조사해 왔지만, 이는 정말 심각한 소식입니다. 만약 그들이 정말로 도시까지 침투했다면, 신속하고 단호한 조치가 필수적입니다."}}
rows[41237]={title={{18,1139180857},"펠스트라이더 후퇴"},description={{587,1159951809},"우리... 옛 동지들이 펠스트라이더 은신처 산악 요새에 은신해 있습니다. 우리가 이 땅에 정착하기 전부터 이곳에 있었던 것으로 보아, 노스렌드로 가지 않은 켈의 군대 잔당일 가능성이 높습니다. 지금까지는 별다른 문제를 일으키지 않았고, 부끄럽게도 우리는 그들의 존재를 간과해 왔습니다. 하지만 당신의 말이 사실이라면, 그들은 분명 무언가를 꾸미고 있을 겁니다. 저는 당신이 그들의 음모에 대한 증거를$B$B 찾아주길 바랍니다. 어쩌면 그들의 병사 중 누군가가 사건의 실마리가 될 만한 명령서를 가지고 있을지도 모릅니다. 부디 빛이 당신을 인도하길, 친구여."},objectives={{55,1469446481},"펠스트라이더 은신처에서 블러드 엘프의 음모에 대한 증거를 찾아보세요."},progress={{24,1640579900},"뭔가 찾으셨나요?"},completion={{219,1314498163},"롬마스?$B$B저 쥐새끼, 저 해충 같은 놈! 베레사를 배신하고 아스탈로르 편에 섰던 놈이 이제 또 이러는 건가? 저 배신자는 교수형에 처해질 것이다.$B$B하지만 먼저 이 소식을 베레사 님께 전해 드려야겠소. 뭔가 더 숨겨진 사정이 있는 것 같소…"}}
rows[41238]={title={{23,969379428},"여군주 윈드러너에게 돌아가기"},description={"Make haste, $c. You may still have time to stop Rommath's scheme. Go with the wind, and let no one know about this, but Lady Vereesa! Fate of our kin is in your hands.","서둘러라, . $c로마스의 음모를 막을 시간이 아직 남아 있을지도 모른다. 바람을 타고 떠나라. 그리고 베레사 부인 외에는 아무에게도 이 사실을 알리지 마라! 우리 혈족의 운명이 네 손에 달려 있다."},objectives={{43,1259923691},"조사 결과를 베레사 윈드러너에게 보고하십시오."},progress={{27,1612204099},"조사는 어떻게 진행되었나요?"},completion={"<Vereesa's countenance pales as you explain the situation to her.>$B$BI... I didn't anticipate that it would be someone from the Regency Council, even in my darkest dreams. Who else is conspiring against us? Voren'thal? Astalor? This is profoundly grave news, $n.","당신이 상황을 설명하자 베레사의 얼굴이 창백해집니다.$B$B저는… 저는 꿈에도 상상 못 했습니다. 섭정 위원회 사람이 그럴 줄은요. 또 누가 우리를 음모하고 있는 겁니까? 보렌탈? 아스탈로르? 이건 정말 심각한 소식입니다,$n."}}
rows[41239]={title={{20,1557059775},"배신자 로마트"},description={{645,1141135558},"섭정위원회의 현 상황으로 볼 때, 저는 어쩔 수 없습니다. 우리가 편지를 가지고 있다 해도 로르테마르 외에는 아무도 저를 믿어주지 않을 겁니다. 그들은 제 행동을 틀림없이 왕위를 찬탈하려는 시도로 여길 것입니다. 하지만 모든 것이 끝난 것은$B$B 아닙니다. 롬마스에게 당신이 펠스트라이더 은신처에서 온 사절단이라는 것을 납득시킬 수 있다면, 그는 무심코 자신의 계획에 대해 더 많은 것을 드러낼지도 모릅니다. 편지는 매우 모호하기 때문에, 이 방법을 사용하면 추가적인 세부 정보를 얻을 수 있을 것입니다. 가십시오. 하지만 당신의 진짜 정체를 드러내지 않도록 조심하십시오. 롬마스는 예측할 수 없는 인물이며, 눈 깜짝할 사이에 당신을 제거할 수도 있습니다.$B$B 그는 탑 꼭대기에 있습니다."},objectives={{82,1172819229},"대마법사 로마스에게 보고하십시오. 그는 리젠시 타워 꼭대기에 있습니다."},progress={{34,1666146147},"누가 감히 내 명상을 방해하는가?"},completion={{508,795224247},"아, 펠스트라이더 출신이시죠? 안전합니다. 아무도 우리 대화를 들을 수 없어요.$B$B<롬마스는 당신의 얼굴을 한참 동안 살피며 유심히 살펴봅니다.>$B$B좋습니다. 필요한 준비는 모두 마쳤습니다. 제 계산이 맞다면—확실히 맞습니다—켈타스 왕자와 연락할 수 있을 겁니다.$B$B그런데 엘딘은 잘 지내고 있습니까? 그 바보 아스탈로르가 펠스트라이더를 공격하려고 병력을 모으려 했지만, 늘 그렇듯 실패했습니다.$B$B좋습니다. 준비가 되면 알려주세요."}}
rows[41240]={title={{27,651077796},"왕자와의 알현"},description={{104,2089846358},"이제 아웃랜드로 통하는 차원문을 열겠습니다. 마음의 준비를 하세요. 약간 끌리는 느낌이 들 수도 있는데, 떨어지지 않도록 조심하세요."},objectives={{72,1285877721},"대마법사 롬마스와 켈타스의 대화를 들어보세요."},progress={{12,607827910},"나의 왕자님..."},completion={{260,1968207680},"이제 아시겠죠. 매일 우리 국민들이 그를 배신자, 겁쟁이라고 부르는 소리를 듣습니다. 하지만 저는 그의 뜻을 따라야만 합니다. 그의 의도는 이해할 수 없지만, 그에 대한 믿음은 변함없습니다. 더 많은 우리 국민들이 저와 같은 마음으로 그를 바라볼 수 있기를 바랍니다."}}
rows[41241]={title={{22,96337905},"알라탈라스 주변 모든 곳"},description={{600,828282707},"당신은 혹시 부인할 수 없는 미래를 보기 위해 여기에 온 겁니까, 아니면 단순한 호기심 때문입니까? 어쩌면 우리를 진흙탕과 폐허 속에 버린 자들에게 침을 뱉으러 온 것일지도 모르죠. 태양이여, 부디 우리의 비참한 영혼을 불쌍히 여기러 온 건 아니겠죠? 당신의 동정은$B$B 필요 없습니다. 하지만 당신은 유용할지도 모릅니다. 당신에게는 임무가 하나 필요한데, 당신처럼 열정적인 동맹에게 딱 맞는 임무입니다. 흩어진 마법 수정 몇 개를 재활용해 주시겠습니까? 도시의 우리 귀족들은 오만함 때문에 알라탈라스 곳곳에 마법 수정을 버려두고 갑니다. 몇 개 없어진 것도 눈치채지 못할 겁니다."},objectives={{112,1412054757},"알라탈라스 주변에서 마법 수정 7개를 찾아 비참한 빈민가에 있는 카즈미르 솜버윈드에게 가져다주세요."},progress={{16,1360892200},"나는 불안한 기분이야."},completion={{104,1032642978},"당신이 카즈미르에게 수정들을 건네자 그의 손이 떨립니다.$B$B꽤 많은 걸 얻었군. 이것들은 우리에게 큰 도움이 될 거야. 고마워."}}
rows[41242]={title={{23,337888987},"그들은 서쪽에서 왔다"},description={{775,1206074197},"우리 종족은 남쪽으로 피난처를 찾았습니다. 드워프족은 우리 대상들을 보호해 주었고, 인간들은 새롭게 결성한 동맹에 우리를 받아들였습니다. 그와 함께, 우리는 소위 칼도레이라는 종족의 충성도 얻게 되었습니다. 서로 다른 점이 많지만, 우리 종족에게는 공통점도 있는 것 같습니다. 비록 $B$B모두가 우리의 마법 사용과 그로 인한 중독, 그리고 그로 인해 발생하는 희생자들(이미 고통받는 우리 종족에게서 볼 수 있듯이)을 환영한 것은 아니지만, 우리를 돕고자 하는 이들도 있었습니다. 그중에는 우리 거주지 너머에 사는 드루이드, 오르데날 아울메인이 있습니다. 그는 두 마리의 거대한 짐승의 윤곽을 닮은 나무 아래에 살고 있습니다. 그는 꿈과 달의 힘을 통해 우리가 구원받을 수 있다고 말합니다. 우리 종족에게 생존의 가능성이 있다고 진심으로 믿는다면, 그를 찾아가 보십시오."},objectives={{61,1924099440},"비참한 빈민가 바로 바깥에 있는 오르데날 아울메인에게 말을 걸세요."},progress={{11,819267740},"그게 뭐죠?"},completion={{99,1538052834},"당신은 빈민가에서 돌아오셨죠? 그들의 행동 계획을 돕기 위해 여기에 오신 겁니까?"}}
rows[41243]={title={{16,208235786},"희망에 대한 갈증"},description={{691,63405400},"태양의 아이여, 안녕하십니까. 저는 꿈에 맹세한 드루이드, 오르데날입니다. 퀘르도레이에게 끔찍한 운명이 닥쳤습니다. 이는 영원의 샘에 의존했던 고대 칼도레이 왕국과 하이본을 떠올리게 합니다. 영원의 샘을 잃었을 때, 우리 백성은 세계수로 피신했습니다.$B$B 하이본은 아직 살아남았지만 그 수는 매우 적고, 대부분은 굶주림을 채우기 위해 다른 타락에 빠졌습니다. 저는 이곳 백성들이 그런 운명을 겪지 않기를 바랍니다. 제 이론을 검증하는 데 도움을 주시면 대단히 감사하겠습니다. 저는 달샘물 몇 병을 가지고 있습니다. 이 물을 불쌍한 자들에게 주어, 혹시라도 그들의 고통을 잠시나마 덜어줄 수 있는지 확인해 주시겠습니까?"},objectives={{61,1188776791},"문웰 워터를 비참한 빈민가 주민들에게 제공하세요."},progress={{33,561833781},"제 이론이 맞기를 바랍니다."},completion={{32,937825861},"그러니까 아무런 효과도 없었다는 말인가요?"}}
rows[41244]={title={{32,795611475},"하이 엘프 중 한 명인 고귀한 혈통"},description={{356,1650677673},"친구여, 두려워하지 마시오. 비록 제 희망은 좌절되었지만, 자네에게 맡길 $B$B다른 임무가 있네. 이전에 하이본에 대해 언급한 적이 있는데, 놀랍게도 그들 중 한 명이 이곳 북서쪽에 있는 영원한 가을의 섬의 작은 탑에 살고 있는 것 같소. 그녀의 조언을 구하는 것이 현명할지도 모르니, 그녀는 모든 퀘르도레이의 구원에 필수적인 지식을 가지고 있을지도 모르네."},objectives={{52,174564513},"영원한 가을의 섬에서 비즈네야 반딧불이를 찾아보세요."},progress={{8,1903176468},"자세히 말해줘."},completion={{50,1962382199},"다스레마르의 자식이여, 내 현재 거처에 온 것을 환영한다."}}
rows[41245]={title={{23,845914153},"원정순찰로를 따라"},description={{407,299903983},"모든 땅과 해안이 이 우스꽝스러운 괴물들로 가득 차야만 하는가? 그들의 더러움을 마주하지 않고는 할 수 있는 임무가 하나도 없었다. 이 무시무시한 멀록들은 결코 좋은 징조가 아니다. 멀록이 있는 곳에는 곧 나가가 뒤따르기 때문이다.$B$B 저 더러움에서 벗어나 내게 돌아오너라. 네게 더 적합한 임무가 있다. 엘룬 신이시여, 찬양받으소서. 더 이상 저들을 볼 수 없다."},objectives={{51,710951361},"먼 걸음을 따라 먼 걸음 멀록을 처치하세요."},progress={{11,1398970741},"하나도 아끼지 마라."},completion={{133,777768599},"오랫동안 안 보이셔서 잘 지내시는지 확인하러 왔는데, 당신이 아주 쉽게 그것들을 해체하고 있는 모습만 봤어요. 정말 능숙하시더군요."}}
rows[41246]={title={{15,815983659},"불안한 가을"},description={{450,1364376895},"무언가가 쓰러진 자들의 영혼이 이 숲에서 안식을 누리지 못하게 막고 있습니다. 저는 걱정이 많고, 그 걱정이 사실이 아니길 진심으로 바랍니다. 하지만 저는 이곳을 떠날 수 없으니, 그 전에 이 불안한 영혼들에게 평화를 가져다주시길 부탁드립니다. $B$B두려워하지 마십시오. 그들은 죽일 수 있습니다. 혹시라도 아는 사람과 닮았다면 눈을 돌리십시오. 그들이 이곳에 있는 것은 옳지 않으며, 그들은 반드시 저승의 요람으로 돌아가야 합니다."},objectives={{56,720087471},"영원한 가을의 섬에 깃든 불안한 영혼들을 처치하라."},progress={{34,212538977},"생각만큼 쉽지는 않죠, 그렇죠?"},completion={{43,1911807214},"혹시 흥미로운 점이나 말씀하고 싶은 것이 있으신가요?"}}
rows[41247]={title={{19,17798000},"테론의 집"},description={{437,1111080033},"영혼 중 한 명의 재 속에서 이니셜이 새겨진 인장을 발견했다고요? 흥미롭군요. 테론, 테론... 어디선가 들어본 이름 같은데 확실하지는 않네요. <시라는 잠시 생각에 잠겼다.> 그는$B$B 의회 의원 중 한 명이었던 것 $B$B같은데, 이름은 로르테마르 테론이었던 것 같습니다. 어쩌면 이 인장이 어떤 감정적인 의미나 가문의 역사를 담고 있을지도 모르죠. 우리가 판단할 문제는 아니지만, 그를 찾아가 인장을 돌려주면 보상을 받을 수도 있을 겁니다."},objectives={{39,1585678082},"보고서를 로르테마르 테론에게 가져오세요."},progress={{11,1613218370},"자, 시작해 볼까요."},completion={{277,860906163},"이것은 제 삼촌의 것이었습니다. 그는 저의 보호자이자 스승이셨죠. 저는 그분이 이 땅에서 쓰러지셨다는 것을 알고 있었지만, 그분이 편히 쉬지 못하실 줄은 상상도 못했습니다. 어쩌면 그분은 쿠엘탈라스가 함락되었다는 것을 아셨기에, 저승으로 돌아오신 것일지도 모릅니다.$B$B당신은 제게 큰 도움을 주셨으니, 그에 대한 보상을 드려야 마땅합니다."}}
rows[41248]={title={{14,1796958762},"나가 올 얼로"},description={{748,940195432},"당신이 없는 동안 제 의심이 사실로 드러났습니다. 근처에 나가족이 의식을 행하는 듯한 파괴된 유적이 있습니다. 이는 이 땅의 평화를 깨뜨릴 뿐만 아니라 훨씬 더 심각한 결과를 초래할 수도 있습니다.$B$B 유적에 들어가 그들의 지도자들과 맞서기 전에 준비를 단단히 해야 합니다. 나가족은 수중에서 매우 강력한 적이며, 당신은 물속에서 살아남을 수단이 필요할 것입니다. 저는 수중 호흡 물약을 가지고 있지만, 이 섬의 특이한 기운 때문에 효능이 떨어졌습니다. $B$B저는 연금술에 대한 지식이 있어 이 문제를 해결할 수 있지만, 그러기 위해서는 나가족의 비늘이 필요합니다. 비늘을 가져다주시면 물약을 만들어 드리겠습니다. 하지만 조심하시고 물속 깊이 들어가지는 마십시오."},objectives={{49,234747387},"시라 문워든에게 암초비늘 나가 비늘 9개를 가져가야 합니다."},progress={{9,156505680},"혹시 좋은 소식 있으셨나요?"},completion={{205,908662606},"좋아.$B$B<시라는 비늘을 부수어 물약에 넣는다. 혼합물이 지글지글 소리를 내며 빛나기 시작한다.>$B$B자, 여기 있다. 물약 세 병이면 충분할 것이다. 현명하게 사용하거라. 더 이상은 주지 않겠다."}}
rows[41249]={title={{24,1973033226},"리프스케일의 리더들"},description={{572,697849966},"일부 나가족은 조수를 조종하여 지역 전체를 물에 잠기게 하는 능력을 가지고 있습니다. 만약 그들이 그런 의식을 행하고 있다면, 우리의 운명은 이미 결정되었을지도 모릅니다. 부디 결의를 굳건히 하고 뱃멀미에 대비하십시오. 당신이야말로 그들의 계획을 저지할 운명을$B$B 타고난 자입니다. 나가족은 엄격한 위계질서로 움직입니다. 그들의 지도자를 제거할 수 있다면, 그들의 군대는 흩어져 나즈자타르 심해로 후퇴할 것입니다. 지휘관들을 처치하는 것이 중요하지만, 그들의 하수인 몇 명도 처치하는 것도 나쁘지 않을 겁니다. 그저 스릴을 위해서 말이죠. $B$B<시라는 투구 아래에서 킥킥거렸다.>"},objectives={{80,180046386},"시라 문워든을 위해 리프스케일의 지도자와 리프스케일 분리자 8명을 처치하세요."},progress={{26,1747894462},"그 문제들은 해결되었나요?"},completion={{150,1505467377},"나가족이 퀘르도레이를 공격함으로써 얻고자 하는 것은 무엇일까? 분명 누군가 이미 고통받는 이들에게 더 큰 고통을 안겨주려 하고 있을 것이다."}}
rows[41250]={title={{15,448614469},"드리아드를 찾아라"},description={{648,1257183581},"도움을 주시겠다고 하니 정말 기쁩니다. 사실 저는 퀘르도레이들이 고통을 덜어낼 방법을 찾도록 돕기 위해 왔습니다. 많은 퀘르도레이들에게 명상을 가르치고 마법 사용을 자제하도록 도와왔지만, 이것이 영구적인 해결책은 아닙니다. 어떤 이들은 다른 $B$B이들보다 더 빨리 시들어 버립니다. 제 수호자, 혹은 간수가 저를 가두어 두지 않아 거처를 떠날 수 없으니, 섬 한가운데 있는 잠자는 나무로 가주시길 부탁드립니다. 그곳에 제가 우연히 만났던 가을의 자매, 린이 있습니다. 지난번에 그곳에 갔을 때는 서서히 시들어가는 한 명을 나무 안에 남겨두고 쉬게 해 주었습니다."},objectives={{31,528060931},"잠자는 나무에서 린을 찾으세요."},progress={{4,273767400},"예?"},completion={{75,629852409},"안녕하세요, 저는 라인입니다. 여기 계신 분들은 가을의 자매들이신 여러분과 함께하고 계십니다."}}
rows[41251]={title={{20,1693571181},"롬마트, 구세주"},description={{209,678426125},"지금 펠스트라이더 은신처로 가거라. 엘딘에게만 이 사실을 알리도록 $B$B하라. 우리 대화 내용을 절대로 누구에게도 누설하지 $B$B마라. 행운을 빌노타. 영원한 태양이 다시 한번 우리를 비추기를."},objectives={{43,323804447},"베레사 윈드러너에게 당신이 본 것을 이야기해 주세요."},progress={{22,1686705931},"무엇을 배웠나요?"},completion={"Kael, alive and well in Outland, still concerned about our people? Are you absolutely certain?$B$B<Vereesa's expression shifts as she delves into deep thought, her brows furrowing and her eyes gazing into the distance.>$B$BThere is much to weigh and consider in the wake of this information. The implications are far-reaching, and I must carefully deliberate on the best course of action for our people. Your delivery of this news has been invaluable, $N, and I am profoundly grateful for the service you have rendered to both me and the entirety of Quel'dorei.","아웃랜드에서 살아있고 건강한 카엘이 아직도 우리 백성을 걱정하고 있다고? 정말 확실한가?$B$B<베레사의 표정이 깊은 생각에 잠기며 변했다. 그녀의 눈썹이 찌푸려지고 눈은 먼 곳을 응시했다.>$B$B이 소식을 접하고 심사숙고해야 할 것이 많습니다. 그 영향은 광범위하며, 우리 백성을 위한 최선의 방안을 신중하게 고려해야 합니다. 이 소식을 전해주신 것은 매우 귀중했습니다,$N그리고 저와 퀘르도레이 전체를 위해 베풀어주신 도움에 깊이 감사드립니다."}}
rows[41252]={title={{9,1029088750},"킹스베인"},description={{734,502982983},"아, 모험가로군..$B$B. 아스탈로르의 얼굴이 경멸로 $B$B일그러졌다. \"중요한 일이 생겼는데, 내게로 이어지는 흔적을 남기지 않고 도움을 청해야겠소. 최근에 배신자 켈타스 왕자의 먼 사촌 중 한 명이 아직 살아있고, 펠스트라이더 후퇴 부대를 지휘하고 있다는 사실을 알게 됐소. $B$B짐작하시겠지만, 선스트라이더가 살아있다는 건 심각한 문제이지. 많은 이들이 그의 왕위 계승권을 정당하다고 여길 수도 있으니까. 그를 제거해야 하겠소. 강력한 무리를 꾸려 그를 처치하고, 시체를 호수에 버리시오. 그 끔찍한$B$B 임무를 완수하면, 그의 인장을 증거로 멜라테 섀도송에게 제출하시오. 아무도 내가 이 일을 제안했다는 사실을 알아채지 못하게 하시오.\""},objectives={{112,629410179},"엘딘 선스트라이더를 처치하고 그의 인장을 멜란테 셰이드송에게 가져다주세요. 그녀는 보통 경매장 근처에서 찾을 수 있습니다."},progress={{58,1455401609},"내가 웃길 바란다면, 웃을 만한 더 나은 이유를 대세요."},completion={{205,1295432688},"뭐라고?$B$B<멜란테는 브리엘라에게서 등을 돌리고 한숨을 쉬었다.>$B$B아. 너는… 그래, 알았어, 고마워. 잘했어, A+, 금별 줄게. 여기 월급 줄게. 가서 오렌지나 뭐든 사거나 개성을 좀 키워. 안녕."}}
rows[41253]={title={{14,1222528226},"펠의 길"},description={{512,495890443},"안녕하세요. 저는 레샨드라 핀트리입니다. 저는 마법 중독을 해소하는 좀 더… 독특한 방법들을 연구하고 있습니다. 남서쪽에는$B$B 블러드 엘프 요새가 있습니다. 블러드 엘프는 우리와는 다른 방식으로 중독을 해소하는 것으로 악명이 높으며, 독특한 마법을 사용합니다. 저는 그들의 비밀을 더 파헤치고 싶지만, 안타깝게도 섭정 위원회가 제 연구를 반대하고 있습니다. 만약 당신이 그곳으로 가서 지옥의 수정(펠 크리스탈)을 가져다주신다면, 그 노력에 대한 보답으로 후한 보상을 드리겠습니다."},objectives={{85,83669110},"알라탈라스에 있는 펠스트라이더 은신처에서 레샨드라 핀트리를 위해 펠 수정 10개를 가져오세요."},progress={{70,1972918373},"괜찮을 거예요. 경비병들에게 수정만 보여주지 마세요."},completion={{161,1374719873},"아, 정말 아름답고 달콤한 결정들을 많이 얻으셨군요. 제 연구에 정말 귀중한 자료가 될 겁니다. 오늘 우리 민족에게 큰 도움을 주셨습니다."}}
rows[41254]={title={{17,157865679},"딥머크의 어둠"},description={{535,1789818383},"최근에 파스트라이드에 가보셨나요? 그곳은$B$B 아름다운 해변이지만, 멀록과 다른 사악한 생물들 때문에 흠집이 나 있습니다. 그중에서도 딥머크는 가장 골칫거리입니다. 바다 가장 깊은 곳에서 온 이 멀록들은 알 수 없는 이유로 자신들의 수중 서식지를 떠나 파스트라이드의 동굴에 자리를 잡았습니다. 그들은 우리 레인저와 어부들을 끊임없이 공격하여 이 아름다운 땅을 완전히 사람이 살 수 없는 곳으로 만들어 버렸습니다. 만약 당신이 그들의 $B$B개체 수를 줄여준다면, 그에 합당한 보상을 받을 것입니다."},objectives={{61,1950652388},"니레니아 스위프트선 지역을 위해 딥머크 멀록의 개체수를 줄이세요."},progress={{4,273767400},"예?"},completion={{121,838394945},"훌륭해! 이 생물들이 사라지니 해변이 모두에게 더 안전해졌어! 그리고 이제 드디어 생선을 적당한 가격에 살 수 있겠네..."}}
rows[41255]={title={{17,2038678210},"딥머크 배송"},description={{615,525625206},"잠시 시간 좀 $B$B내주시겠습니까? 제가 여기 부두 관리인입니다. 아마 짐작하시겠지만, 새로 찾은 이곳에는 사람들이 많이 오가고 있고, 든든한 동맹국들로부터 많은 물자를 받고 있습니다. 그런데 $B$B며칠 전에 도착하기로 되어 있던 배 한 척이 사라졌습니다. 특히 해안가에 나가가 나타났다는 소문 때문에 최악의 상황이 걱정됩니다. $B$B그 물자는 매우 중요한 것이었으니, 파스트라이드로 가서 찾아주시면 후한 보수를 드리겠습니다. 혹시 남은 물자가 딥머크 멀록들에게 도난당했을 가능성도 있습니다. 만약 그렇다면, 그들은 물자를 자신들의 소굴로 가져갔을 겁니다."},objectives={{102,1110770257},"세일린 시스트라이더를 위한 화물을 회수하세요. 딥머크 동굴이 수색을 시작하기에 좋은 장소일 겁니다."},progress={{4,273767400},"예?"},completion={"Here it is, the shipment in question. I thought it was lost for good, but once again, the resilience of our people is remarkable. Thank you, $c. You have done a great service to me.","자, 여기 문제의 화물이 있습니다. 영영 분실된 줄 알았는데, 우리 직원들의 회복력이 정말 놀랍습니다.$c번, 정말 고맙습니다. 큰 도움을 주셨습니다."}}
rows[41256]={title={{10,146654818},"새로운 성장"},description={{906,82478059},"얼마 전, 저와 제 자매들은 바다 건너에서 어떤 이상한 기운을 느꼈고, 그래서 우리 중 몇몇은 별빛 가득한 집을 떠나 조사하러 나섰습니다. 우리의 수색은 이곳, 우리가 '잠자는 나무'라고 부르는 곳으로 이어졌습니다. 퀘르도레이가 바라던 모습과는 조금 다르지만, 그래도 꽤 $B$B아름답지 않나요?나무를 지키기 위해 우리는 나무의 씨앗을 이용해 고대 수호자들을 키웠습니다. 하지만 아아! 나무의 탄생이 결함이 있었던 것처럼, 그 자손들 또한 그러했습니다. 고대 수호자들은 변함없이 진실한 동반자로서 우리와 함께 영원토록 함께 걸어왔지만, 이 가을의 고대 수호자들은 그렇지 못했습니다. 그들은 고작 몇 천 년밖에 살지 못하고$B$B 시들어 흙으로 돌아갔습니다.하지만 최근에 저는 이 고대 수호자들이 잠들어 있던 곳에서 어린 묘목들이 돋아나는 것을 발견했습니다. 이것은 제게 희망을 줍니다! 부디 이 묘목들을 찾아 도토리 몇 개를 가져다주시겠습니까? 어쩌면 $B$B그때는…<마론드라는 말을 흐리며 생각에 잠겼다.>"},objectives={{98,1296489369},"마론드라를 위해 고대인의 시체에서 자라는 어린 나무에서 가을 고대 도토리 3개를 모으세요."},progress={{177,2136097523},"아, 가을이로구나! 가끔 칼림도르의 황혼녘 해안이 그리워지기도 하지만, 저주받은 역사에도 불구하고 이곳은 정말 아늑한 매력이 있어. 도토리 있어?"},completion={{317,1558453533},"오, 찾으셨군요! 정말 다행이에요, 고마워요. 머지않아 이 아이들이 아름다운 새싹으로 자라날 거라고 확신해요.$B$B<잠시 생각에 잠긴다.>$B$B아, 그러지 않으셔도 괜찮아요. 인간들은 우리와 시간 개념이 다르다는 걸 깜빡했네요. 몇 년이 걸릴지도 몰라요."}}
rows[41257]={title={{15,514749258},"피의 유산"},description={{962,1641014946},"우리 백성 중 마법사의 길을 택하는 자는 누구든 그 길에 따르는 험난한 함정에 잘 대비해야 한다. 이 길을 계속 걸어가고자 한다면, 여정에 필요한 충분한 교육을 받는 것이 좋을 것이다. 우리$B$B 백성을 괴롭히는 마법 중독과 태양샘의 상실은 우리에게 더욱 심각하다! 너의 소명은 너의 갈증에 끊임없이 불을 지필 것이다. 네가 그것을 지배하기 전에 네가 먼저 그것을 다스려야 한다. $B$B실버문에는… 내 친구였던 한 남자가 있었다. 비극적이게도 그는 갈증을 해소하려 왕자의 블러드 엘프에게 넘어갔을 뿐만 아니라, 많은 젊은 마법사들을 파멸로 이끌었다. 나는 또 다른 제자가 그의 함정에 빠지는 것을 보고만 있을 수 없다. 그가 펠스트라이더 은신처에서 목격되었다는 소식이 들려온다. 길라라스 선퓨리를 찾아내어, 욕망 때문에 이성과 도덕을 버린 자의 최후를 보게 하고, 그를 처단하여 우리의 고통을 끝내주도록 해라.$B$B 그리고 메리사가 그의 짓을 잊지 않았다는 것도 꼭 전해 줘라."},objectives={{46,294053601},"펠스트라이더 은신처에서 길라라스 선퓨리를 처치하세요."},progress={{112,943171243},"나는 그를 절대 믿지 말았어야 했다. 학생들을 맡길 때도, 그리고 내가 아끼는 '에그윈의 노래' 초판본을 맡길 때도 말이다."},completion={{464,1835761546},"그는 살해당한 건가? 난 이미 오래전에 그를 애도하는 걸 끝냈다고 생각했는데. 너희 둘 다 이번 일을 통해 귀중한 교훈을 얻었기를 바라지만, 그는 앞으로 어떤 실수에서도 교훈을 얻지 못할 것 같군. 힘내라, 어쩔 수 없는 일이었고, 이제 너희도 고통을 잊기 위해 더 사악한 것에 의지하는 자의 최후를 알게 되었으니.$B$B자, 여기 네가 받을 자격이 있는 것이다. 앞으로의 여정에 이것을 간직하고, 도구로서도, 그리고 기억을 되새기는 도구로서도 너에게 도움이 되기를 바란다."}}
rows[41258]={title={{16,1062801853},"빛의 전형"},description={{305,1737903376},"안녕, 성기사여.$B$B너는 상당한 지식을 쌓았지만, 아직 발견해야 할 것이 많이 남아 있다. 우리 기사단의 존경받는 성기사인 두토리안 랄을 찾아가라. 그는 남쪽 멀리 스톰윈드 시티에 거주하고 있다. 그의 지도 아래, 너는 내가 가르칠 수 있는 것보다 더 심오한 가르침을 받게 될 것이다."},objectives={{38,363220750},"스톰윈드 시티에서 두토리안 랄을 찾으세요."},progress={{4,273767400},"예?"},completion={{165,747937707},"위대한 엘프시여, 당신께 경의를 표합니다. 역경 속에서도 당신 종족이 보여준 회복력은 이 어려운 시기에 우리 모두에게 큰 영감을 줍니다."}}
rows[41259]={title={{20,1258580776},"오베르딘으로 가는 여정"},description={{436,1584488609},"우리의 새로운 동맹들이 머나먼 칼림도르 땅으로 당신을 요청했습니다. 베레사는 당신을 매우 높이 평가하고 있으며, 당신이 우리 새로운 고향의 많은 주민들에게 귀중한 동맹이 되어주었다는 소문도$B$B 들었습니다. 우리 도시와 나이트 엘프 마을 오버딘 사이에는 정해진 배길이 있습니다. 서둘러 그곳으로 가서 파수꾼 글린다 날셰아에게 보고하십시오. 그녀는 우리 종족의 동맹이며, 분명 당신에게 더 많은 임무를 줄 것입니다."},objectives={{59,254505043},"오버딘으로 이동하여 감시병 글린다 날셰아에게 보고하십시오."},progress={{4,273767400},"예?"},completion={{92,136363978},"드디어 약속했던 동맹들이 도착했군. 고향으로 돌아온 걸 환영한다, 동지들아. 앞으로 할 일이 많다."}}
rows[41260]={title={{20,596602464},"심연의 재앙"},description={{283,1591281585},"우리 전사들은 약자를 지키겠다는 맹세를 했습니다. 무시무시한 적, 머크블러드가 파스트라이드의 동굴 속에 숨어 있습니다. 그는 수많은 목숨을 앗아갔고, 우리가 개입하지 않으면 더 많은 이들이 그의 위협에 굴복할 것입니다. 그를 처치해 주시면, 저희가 가진 최고의 검 중 하나를 하사드리겠습니다."},objectives={{15,254607575},"머크블러드를 죽여라."},progress={{33,276657311},"그 끔찍한 괴물을 찾았습니까?"},completion={{56,673800117},"정말 잘하셨습니다. 여러분의 행동 덕분에 해안가가 훨씬 더 안전해졌습니다."}}
rows[41261]={title={{20,607102004},"보호에 관한 수업"},description={{289,1807982257},"전사여, 안녕하십니까.$B$B 당신의 배움의 여정은 훌륭했지만, 아직 습득해야 할 지식은 무궁무진합니다. 다르나서스의 수호자들은 특히 무적의 방어술에 능통한 것으로 명성이 자자합니다. 다르나서스로 가서 $B$B엘레나리아를 찾으십시오. 그녀가 당신을 더욱 인도해 줄 것입니다."},objectives={{33,1636692518},"다르나소스에 있는 엘라나리아와 이야기해 보세요."},progress={{4,273767400},"예?"},completion={{75,642645955},"다트레마르의 또 다른 자식이 우리 도시에 발을 들였군. 어서 와라."}}
rows[41262]={title={{15,297530854},"외교의 종말"},description={{406,1239579165},"첩보에 따르면 펠스트라이더 은신처에 새로운 적이 나타났습니다. 실바나스 윈드러너와 그녀의 언데드에게 복종하는, 정신 나간 하수인 언데드 엘프입니다. 블러드 엘프와 호드 간의 어떤 협력도 용납할 수 없습니다. 이 위협을 신속하고 은밀하게 제거하는 것이 무엇보다 중요합니다. 당신의 능력을 고려할 때, 이 임무에 적합하다고 생각합니다. 어떻게 생각하십니까?"},objectives={{25,1005092569},"이티릴렌 셰이드윈드를 처치하세요."},progress={{64,1241782144},"당신이 이곳에서 시간을 허비하며 보내는 매 순간마다 당신의 생명은 점점 더 짧아집니다."},completion={"Consider me thoroughly impressed. Outstanding job, $c. Naturally, ensure that the details of this event remain confidential. Let it fade into oblivion.","정말 감명받았습니다.$c, 훌륭한 일을 해냈군요. 물론, 이 사건의 세부 사항은 기밀로 유지되어야 합니다. 이 일은 잊혀지도록 내버려 두세요."}}
rows[41263]={title={{11,285736217},"신성한 의무"},description={{705,1617937518},"성스러운 빛의 헌신적인 종으로서, 불우한 이들을 돌보는 것은 우리의 의무이자 특권입니다. 몰락한 왕국 이후 쿠엘탈라스의 아이들이 겪는 고통의 무게를 우리는 종종 간과합니다. 수많은 어린아이들이 고아가 $B$B되었고, 우리는 그들에게 위로와 도움을 주어야 할 책임이 있습니다. 비록 당신의 운명이 다른 길로 인도할지라도, 당신의 도움은 여전히 ​​큰 영향을 미칠 수 있습니다. 상아 매사냥꾼의 뼈를 가져다주십시오. 그것으로 우리는 섬세한 인형 장난감을 만들 것입니다. 이 작은 장난감은 아이들에게 위안이 되어, 그들이 겪은 트라우마적인 기억을 극복하는 데 도움이 될 것입니다."},objectives={{73,1871633286},"발라도르 예배당에 있는 탈리렌 라이트본에게 상아 매사냥꾼 뼈를 가져다 주세요."},progress={{4,273767400},"예?"},completion={{96,314856482},"고맙다, 얘야. 네게는 별것 아닌 것처럼 보일지 모르지만, 그들에게는 정말 큰 의미가 있을 거야."}}
rows[41264]={title={{28,621829838},"블랙애쉬 광산에서 발생한 작업 중단"},description={{472,1976978407},"블랙 애쉬 광산의 작업이 완전히 중단되었습니다. 머드포우 놀들을 조심해야 하는 것도 모자라, 투자개발회사까지 주변에 잠복하고 있습니다. $B$B광부들로부터 고블린이 블랙 애쉬 광산에서 놀들을 지휘하는 것을 목격했다는 보고를 받았습니다. 여기 바로 북쪽으로 가서 광산 안으로 들어가 보십시오. 투자개발회사와 관련된 자를 발견하면 처치하고 저에게 돌아오십시오."},objectives={{146,1784620361},"러스트게이트 능선 북쪽에 있는 블랙 애쉬 광산의 깊은 곳을 탐험하고 머드포 그놀과 벤처 컴퍼니 사이에 어떤 연관성이 있는지 찾아보세요."},progress={{37,1083200861},"그런 소문이 사실이 아니길 바랍니다."},completion={{211,92134497},"광산 깊숙한 곳에 고블린이 있다고?$B$B이건 중대한 소식이고, 다소 우려스러운 일이군. 상관과 상의해 보겠지만, 자네 정보 덕분에 우리가 필요로 하는 정보를 정확히 얻었네. 오늘 아주 잘했군, 신참."}}
rows[41265]={title={{34,792408707},"러스트게이트 벌목장 교란"},description={{626,127679677},"우리가 처음 이 섬에 도착했을 때는 나무와 야생 동물로 가득한 울창한 녹색 오아시스였습니다. 바로 북동쪽에 있는 러스트게이트 제재소에서 큰 수익을 올렸는데, 그 수익이 순식간에 사라져 버렸습니다. 믿기 $B$B어렵겠지만, 아직 벌목할 나무가 꽤 많은데도 투자개발회사가 우리의 가장 수익성 높은 사업 중 하나를 가로챘습니다! 심지어 그들이 직접 그곳에서 일하고 있다는 소문까지 들었습니다. 정말 뻔뻔스럽군요!$B$B 러스트게이트 제재소로 가서 녀석들을 혼내줘야 합니다. 투자개발회사가 듀로타르 노동조합을 다시 건드리기 전에 두 번 생각하게 만들어야 합니다."},objectives={{110,1598113101},"블랙스톤 섬 러스트게이트 리지에 있는 러스트게이트 제재소 주변에서 슬레이 벤처 컴퍼니가 오지크 감독관의 지시를 받아 일했습니다."},progress={{64,1916433925},"머지않아 우리는 목재소를 되찾을 것입니다."},completion={{160,2084185848},"잘했어, 꼬마야. 네 파괴적인 손길을 이끌어줄 내 직감을 믿었어. 머지않아 다시 나무를 베고 수확하는 날을 맞이하게 될 거야."}}
rows[41266]={title={{11,1651624590},"빅맨"},description={{452,398913164},"자, 솔직히 말하는데, 상황이 좋지 않아. 그리고 그 높은 분이 이 사실을 알아야 할 거야. 이미 우리가 잘하고 있지 않다는 건 알고 계시겠지만, 이 보고서를 들으면 완전히 화를 내실$B$B 걸. 그러니 부탁 하나만 들어줘. 이 보고서를 시내 탑 꼭대기에 있는 택슬로 러스트게이트에게 가져다 줘. 빨리 가져다 줘야 해. 그분은 기다리는 걸 싫어하시거든."},objectives={{80,1978209112},"블랙스톤 섬 러스트게이트 리지에 있는 택슬로 러스트게이트에게 오지크의 보고서를 가져오세요."},progress={{47,440397377},"나를 귀찮게 할 만한 타당한 이유가 있어야 할 거야."},completion={{299,1877748497},"<택슬로는 보고서를 읽기 시작했고, 시간이 흐를수록 그의 얼굴은 점점 더 분노로 가득 찼다.>$B$B벤처 회사가 머드포 그놀과 손을 잡았다고?! 엉덩이에서 금이 쏟아져 나오더니 이제는 이것까지!$B$B<택슬로는 한참 동안 생각에 잠겼다>$B$B당장 여기서 나가! 안 그러면 이 탑에서 던져버릴 거야."}}
rows[41267]={title={{25,1396217018},"구원에 이르는 지름길은 없다"},description={{787,2124330994},"울창한 초목과 푸르른 풍경의 매혹적인 아름다움 속에, 탈라시안 고원에는 어둠의 기운이 은밀하게 드리워져 우리의 존재를 위협하고 있습니다. 우리는 타고난 운명에 스며든 마나 중독을 억제하기 위해 끊임없이 지식을 추구하지만, 적들은 위험한 악마 마법의 유혹으로 우리를 유혹합니다. 이미 몇몇 동족들이 그들의 사악한 손아귀에 넘어갔습니다. 최근에$B$B 우리는 서쪽 영원한 가을의 섬에서 악마 마법의 근원을 발견했습니다. 틀림없이 블러드 엘프들이 이 일에 연루되어 있을 것입니다. 그들은 절박한 자들을 어둠의 마법으로 유혹하려 하고 있습니다. 이 오염된 에너지를 찾아내어 내게 가져오십시오. 내가 제대로 파괴할 수 있도록 말입니다."},objectives={{179,1623802907},"영원한 가을의 섬에 남아 있는 악마 마법의 근원을 찾아내어 알라탈라스의 태양의 요새에 있는 시노다스 아주르스카이에게 가져다주면, 그 마법을 파괴할 수 있을 것입니다."},progress={{95,1976346046},"시간이 흐를수록 이 땅은 악마 마법의 어두운 기운으로 더욱 심하게 훼손될 것입니다."},completion={"You have done well, $N. The Citadel thanks you for the aid in retrieving this crystal. We shall see it purified or, barring that, destroyed soon enough. Stand proud, as your actions have helped to save many pure souls from the temptation of the fel.$B$BTake this, as a token of the Citadel's gratitude.","오늘 당신은 훌륭한 일을 해냈습니다. 우리의 마법으로 이 수정은 문제없이 파괴하고 정화할 수 있습니다. 당신의 행동 덕분에 많은 진실하고 순수한 영혼들이 어둠의 에너지에 유혹당하는 것을 막을 수 있었습니다.$B$B시타델에서 감사의 표시로 이것을 받으십시오."}}
rows[41268]={title={{24,1708034448},"스타킹 재입고"},description={{616,425012649},"어머나, 메종 세렌디피티의 겨울 베일 의상도 찾으러 오셨군요? 정말 죄송하지만… 지금 완전히 품절됐어요! 루즈 매거진에 저희에 대한 기사가 실렸는데… 이렇게 주문이 폭주할 줄은 몰랐거든요!$B$B I가 매장에 재고를 보충해달라고 연락해야 하는데, 저는 자리를 비울 수 없어요. 그런데 당신 옷차림을 보니 여행을 많이 다니신 것 같은데, 스톰윈드로 돌아가서 재고를 좀 보내달라고 부탁해 주시겠어요? 공방은 공원 입구 근처에 있어요. 그레 부인을 찾아 상황을 설명하시면 될 거예요!"},objectives={{121,1907801894},"스톰윈드 공원에 있는 아틀리에 세렌디피티 상점으로 가서 알릭스 그레스에게 베라 로렌에게 새 옷을 보내달라고 요청하세요."},progress={{44,1445135610},"네? 저는 그레 부인입니다. 무엇을 도와드릴까요?"},completion={{276,1927462824},"베라 제품이 벌써 매진됐나요? 뭐, 그런 가능성을 예상했어야 했지만, 오뜨 꾸뛰르는 서두를 수 있는 게 아니잖아요. 연말연시 의상이 언더마인 아웃피터스에서 산 기성복처럼 보이면 안 되죠, 안 그래요? 그런데 딱 한 가지 문제가 있어요…"}}
rows[41269]={title={{46,851535090},"아제로스에서는 '공정 무역'에 대한 법적 정의가 없다."},description={{749,1663341173},"베라에게 더 보내드리고 싶지만… 글쎄, 자기야, 우리가 장식용으로 얼마나 많은 모피를 쓰는지 알아? 그것도 그냥 모피가 아니라 진짜 100% 방목 알터랙 예티 모피라고! 제일 따뜻하거든. 그런데 불행히도 지금 모피가 다 떨어졌고, 공급업체들도 까다롭게 굴고 있어. 무슨 부족 사태랑 눈사람 얘기인가? 아무튼, 아, 오해는 하지 마, 자기야, 네 옷차림이 정말 눈길을 사로잡아. 그 의미는… 뭐라고 할까… '전투 기술에 정통한' $B$B사람 같다는 거지. 혹시 알터랙에 가서 신선한 예티 가죽 좀 구해다 줄 수 있을까? 예티들이 가죽을 내놓기를 좀 꺼려할지도 모르지만, 네가 할 수 있을 거야. 가장 부드럽고, 폭신하고, 깨끗한 가죽 열 장 정도면 될 것 같아."},objectives={{59,1632404436},"스톰윈드 공원에 있는 아틀리에 세렌디피티 상점으로 가서 알릭스 그레스에게 베라 로렌에게 새 옷을 보내달라고 요청하세요."},progress={{100,1947469759},"있잖아요, 이번 시즌엔 오렌지색이 새로운 보라색이에요. 옷장을 새롭게 단장해 볼 생각 없으세요, 자기?"},completion={{231,1322378852},"돌아온 걸 환영해, 자기! 가죽도 가져왔구나! 정말 고마워. 이 가죽들은 금방 세척하고, 무두질하고, 표백하고, 붙일 수 있어! 물론 상대적으로 그렇다는 얘기지. 맞춤 제작은 서두를 수 없는 법이니까."}}
rows[41270]={title={{29,1102093087},"겨울 축제를 위한 새 옷!"},description={{257,189450941},"자기야, 필요한 거 다 챙겨줘서 정말 고마워. 네가 없는 동안 윈터베일에 우리 가게에서 제일 좋은 실을 새로 보내줬어. 모두가 최대한 멋지게 차려입지 않으면 아쉬울 테니까. 베라한테 가 봐. 분명 고마워할 거야."},objectives={{52,336604454},"윈터베일 베일로 돌아가서 베라 로렌과 대화하세요."},progress={{4,273767400},"예?"},completion={{176,615394542},"안녕하세요, 알릭스에게서 가죽을 받았다는 소식을 들었습니다. 이미 일부는 미리 보내 놓았더군요. 여기 있는 프리즈 씨와 이야기해 보세요. 그분이 우리 물품 재고를 관리하고 계십니다."}}
rows[41271]={title={{24,1708034448},"스타킹 재입고"},description={{630,834800504},"어머, 메종 세렌디피티 윈터 베일 의상 찾으러 오셨군요? 죄송하지만 좀 늦으셨네요. 지금 완전히 품절됐어요. 루즈 매거진에 저희 가게에 대한 기사가 실렸는데… 이렇게 주문이 폭주할 줄은 몰랐거든요.$B$B 가게에 재고를 보충해달라고 연락해야 하는데, 자리를 비울 수가 없네요. 그런데 옷차림을 보니 여행을 많이 다니신 것 같은데, 언더시티로 돌아가서 재고를 좀 보내달라고 부탁해 주시겠어요? 아틀리에는 아포테카리움, 인챈팅 숍 근처에 있어요. 코코를 찾아서 상황을 설명해 주시면 해결해 줄 거예요!"},objectives={{143,453430733},"언더시티 아포테카리움 쇼핑 구역에 있는 아틀리에 세렌디피티 매장으로 가서 코코에게 랄프 제이콥스에게 새 옷을 보내달라고 요청하세요."},progress={{67,18502399},"코코를 찾으시나요? 저예요, 자기. 무슨 일로 오셨어요?"},completion={{276,2097610146},"랄프가 벌써 다 팔아버렸나 보군요? 뭐, 그런 가능성에 대비했어야 했지만, 오뜨 꾸뛰르는 서두를 수 있는 게 아니죠. 연말연시 의상이 언더마인 아웃피터스에서 산 기성복처럼 보이면 안 되잖아요? 그런데 딱 한 가지 문제가 있어요…"}}
rows[41272]={title={{46,851535090},"아제로스에서는 '공정 무역'에 대한 법적 정의가 없다."},description={{746,92075969},"랄프에게 더 보내드리고 싶지만… 글쎄, 자기야, 우리가 장식용으로 얼마나 많은 모피를 쓰는지 알아? 그것도 그냥 모피가 아니라 진짜 100% 방목 알터랙 예티 모피라고! 제일 따뜻하거든. 그런데 불행히도 지금 모피가 다 떨어졌고, 공급업체들도 까다롭게 굴고 있어. 무슨 물자 부족이랑 눈사람 얘기인가? 아무튼, 아, 오해는 하지 마, 자기야, 네 옷차림이 정말 눈길을 사로잡아. 그 의미는… 뭐라고 할까… '전투 기술에 능숙한' $B$B이미지라고 할까. 혹시 알터랙에 가서 신선한 예티 가죽 좀 구해다 줄 수 있을까? 예티들이 가죽을 내놓기를 좀 꺼려할지도 모르지만, 당신이라면 할 수 있을 거야. 가장 부드럽고, 폭신하고, 깨끗한 가죽 열 장 정도면 될 것 같아."},objectives={{60,1605345793},"언더시티 아포테카리움 쇼핑 구역에 있는 아틀리에 세렌디피티 매장으로 가서 코코에게 랄프 제이콥스에게 새 옷을 보내달라고 요청하세요."},progress={{100,1947469759},"있잖아요, 이번 시즌엔 오렌지색이 새로운 보라색이에요. 옷장을 새롭게 단장해 볼 생각 없으세요, 자기?"},completion={{437,813677762},"돌아온 걸 환영해, 자기! 가죽도 가져왔구나! 정말 고마워. 이 가죽들은 금방 세척하고, 무두질하고, 표백하고, 붙일 수 있어! 물론 상대적으로 그렇다는 얘기지. 맞춤 제작은 서두를 수 없으니까.$B$B네 공급업체 수수료를 줘야겠군. 그리고 랄프를 만나면 곧 배송될 거라고 전해줘. 랄프에게 빨리 연락하는 게 좋을 거야. 일찍 일어나는 새가 유행을 선도하잖아."}}
rows[41273]={title={{29,1102093087},"겨울 축제를 위한 새 옷!"},description={{257,189450941},"자기야, 필요한 거 다 챙겨줘서 정말 고마워. 네가 없는 동안 윈터베일에 우리 가게에서 제일 좋은 실을 새로 보내줬어. 모두가 최대한 멋지게 차려입지 않으면 아쉬울 테니까. 베라한테 가 봐. 분명 고마워할 거야."},objectives={{52,336604454},"윈터베일 베일로 돌아가서 베라 로렌과 대화하세요."},progress={{100,1947469759},"있잖아요, 이번 시즌엔 오렌지색이 새로운 보라색이에요. 옷장을 새롭게 단장해 볼 생각 없으세요, 자기?"},completion={{176,775990423},"안녕하세요, 코코에게서 가죽을 받았다는 소식을 들었어요. 코코는 이미 일부를 미리 보내줬고요. 여기 있는 프리즈 씨와 이야기해 보세요. 그분이 우리 물품 재고를 관리하고 계세요."}}
rows[41274]={title={{23,2009969194},"진정한 사랑의 성약"},description={"Can you feel it, $C? The sweet fragrance of love and admiration that permeates the air? The joy and fascination those eager lovebirds share with one another? There's nothing that makes my heart beat faster than witnessing the miracle of love spread throughout Azeroth!$B$BYour eyes betray your heart, and I can read you like an open book. I can see your eagerness to learn more, perhaps even to experience this sentiment yourself. Love takes many forms, and is not always as clear cut as one might think. Even I, love's herald, am often surprised at those chosen by my arrows to receive the blessings of love! Truly an enigma, love is!$B$BNo further proof of this needs be seen than those whom my arrows have pierced in the past. Bring me a token of their unique form of love and admiration, and return these keepsakes to me in any capital city.","느껴지시나요, $C? 공기에 스며드는 사랑과 감탄의 달콤한 향기? 열성적인 잉꼬들이 서로 공유하는 기쁨과 매력은 무엇일까요? 아제로스 전역에 퍼진 사랑의 기적을 목격하는 것보다 내 가슴을 뛰게 하는 것은 없습니다!$B$BYour 눈은 당신의 마음을 배반하고, 나는 펼쳐진 책처럼 당신을 읽을 수 있습니다. 나는 당신이 더 많은 것을 배우고 싶어하고, 아마도 이 감정을 직접 경험하고 싶어 하는 것을 볼 수 있습니다. 사랑은 다양한 형태를 취하며 생각만큼 항상 명확하지는 않습니다. 사랑의 전령자인 나조차도 사랑의 축복을 받기 위해 내 화살로 선택된 이들을 보고 종종 놀라곤 한다! 정말 수수께끼입니다. 사랑은 바로 그것입니다! $B$BNo 이것에 대한 더 많은 증거는 과거에 내 화살이 찔렸던 사람들보다 더 많이 보여야 합니다. 그들의 특별한 형태의 사랑과 존경의 증표를 나에게 가져오고, 이 유품을 수도에 있는 나에게 돌려주십시오."},objectives={{87,1316060786},"아제로스 전역에서 사랑의 기념품을 찾아 Kwee Q. Peddlefeet에게 가져가세요."},progress={{82,379312372},"환희 가득한 표정으로 돌아오셨습니다! 말해 보세요, 무엇을 보셨나요?"},completion={{642,780657883},"아, 우정 - 예술성에 대한 사랑 - 더 높은 존재에 대한 헌신 - 그리고 영원한 헌신과 충실함에 대한 약속입니다. 놀라운 예입니다. 정말 훌륭하게 해냈습니다! 솔직히 말해서 나는 그 모든 것을 거의 잊어버렸습니다. 예의가 부족한 점을 용서해 주십시오. 이 활은 스스로 생각을 갖고 있어서 때로는 스스로 화살을 쏘는 것조차 눈치 채지 못할 때도 있습니다! 아마도 당신이 나가는 길에 다음 표적이 될지 누가 알겠는가!$B$B<Kwee Q. chuckles at the thought.>$B$BHere, 당신의 노력에 대해 보상해 드리겠습니다. 이 상자를 가져가세요. 그 안에는 아제로스 전체에서 가장 좋은 옷이 들어 있습니다. 그들의 매혹적인 매력을 활용하고 마음 속에 소중한 사람들을 유혹해보세요!"}}
rows[41275]={title={{22,2074882893},"금세공 마스터하기"},description={"$N! Do you have a moment? Your skills in jewelcrafting are exceptional, rarely any of my pupils achieved such levels of craftsmanship by my teachings alone. It doesn't take a master to see - you are born to hone this craft to its fullest potential.$B$BWhile you've exceeded my expectations immensely, I sadly cannot teach you more than I already have. This doesn't mean the end of your journey, however. There are mentors more capable of teaching you, one of them being a good friend of mine. Perhaps you've become acquainted with him already, he may be a bit paranoid and disgruntled, but he will share what he knows with a bit of assistance.$B$BShould you wish to specialize your craft and become a master jewelcrafter, talk to Talvash del Kissel in the Mystic Ward. His instructions will pave the way for your future in this trade.","$N! 잠시 시간 있으세요? 보석 세공에 대한 당신의 기술은 탁월합니다. 내 학생 중 누구도 내 가르침만으로 그러한 수준의 장인 정신을 달성한 경우는 거의 없습니다. 보려면 마스터가 필요하지 않습니다. 당신은 이 기술을 최대한 활용하기 위해 태어났습니다. $B$BWhile 당신은 내 기대를 엄청나게 초과했습니다. 슬프게도 나는 이미 당신에게 가르칠 수 없습니다. 그러나 이것이 여행의 끝을 의미하는 것은 아닙니다. 당신을 가르칠 수 있는 더 많은 멘토가 있는데, 그 중 한 명은 나의 좋은 친구입니다. 어쩌면 당신은 이미 그와 친해졌을 수도 있고, 그는 약간 편집증적이고 불만스러울 수도 있지만, 그는 약간의 도움으로 그가 알고 있는 것을 공유할 것입니다. $B$BShould 당신의 기술을 전문화하고 보석 세공의 대가가 되고 싶다면 신비주의 병동에 있는 Talvash del Kissel과 대화하세요. 그의 지시는 이 거래에서 귀하의 미래를 위한 길을 열어줄 것입니다."},objectives={{62,1160095382},"아이언포지의 신비한 수호물에 있는 탈바쉬 델 키셀과 대화하세요."},completion={{264,1934257164},"아, 그래서 메이바가 당신을 보냈나요? 그 늠름한 여자는 AGES에서 여기 근처에 얼굴을 보여주지 않았어요! 그리고 내가 당신에게 금세공에 대해 가르쳐 주길 원한다고요? 그녀를 비난할 수는 없다고 가정해 봅시다. 사실 나는 아제로스 전체에서 가장 위대한 보석 세공인입니다. $B$BLet 그렇다면 더 이상 기다리지 마세요, 그렇죠?"}}
rows[41276]={title={{22,2074882893},"금세공 마스터하기"},description={"$N, what a splendid sight to have you here with me once more. I have noticed - and you surely too - that your progress in the craft has grown astronomically! Really, it has been too long since I've witnessed such prodigal skills at hand. This sadly means that my means of teaching are at an end. Your eagerness to learn more is apparent however; good thing I can assist you one last time.$B$BShould you wish to strengthen your understanding in the field of jewelcrafting, seek my good friend Jarkal in Kargath. The perilous Badlands are no place for a corpse like myself, but a sturdy troll like himself can withstand such harsh environments with ease. Take care on your journey to him, for I wish you the safest of travels.$B$B<Gulmire does a short, cordial bow.>","$N, 당신이 나와 다시 한 번 여기에 함께하게 되어 정말 멋진 광경입니다. 나는 당신의 기술 발전이 천문학적으로 증가했다는 것을 알아차렸습니다. 당신도 마찬가지입니다! 사실, 이런 엄청난 기술을 직접 목격한 것은 너무 오랜만이었습니다. 이것은 슬프게도 나의 가르치는 수단이 끝났다는 것을 의미합니다. 그러나 더 많은 것을 배우려는 귀하의 열망은 분명합니다. 다행이군요. 마지막으로 제가 도와드릴 수 있습니다. $B$BShould 보석세공 분야에 대한 이해를 강화하고 싶으시면 카르가스에 있는 제 좋은 친구 자르칼을 찾으세요. 위험한 황무지에는 나 같은 시체가 있을 곳이 아니지만, 그처럼 튼튼한 트롤이라면 그런 가혹한 환경도 쉽게 견딜 수 있습니다. 가장 안전한 여행이 되시길 바랍니다. $B$B<Gulmire does a short, cordial bow.>"},objectives={{54,1933855579},"황야의 땅 카르가스에 있는 자칼 모스멜드와 대화하세요."},completion={{444,462508414},"장거리 여행, 내가 가져갈까? 이 땅은 가장 환영받는 곳은 아니지만, 사람의 손길이 닿지 않은 원시적인 아름다움을 제공하며 다른 곳에서는 거의 볼 수 없습니다. 그래도 당신이 여기 있는 이유는 이게 아니죠? 누가 당신을 옛 자르칼로 보냈나요?$B$BGoldsmithing? 요즘에는 자주 운동하지 않는 오래된 기술입니다. 호드는 내 연금술 능력을 더 많이 활용합니다. 그러나 당신이 나에게서 배우고 내가 공유할 수 있는 것을 듣고 싶다면 나의 손님이 되어 주십시오."}}
rows[41277]={title={{18,1644081333},"보석학 마스터하기"},description={"$N! Do you have a moment? Your skills in jewelcrafting are exceptional, rarely any of my pupils achieved such levels of craftsmanship by my teachings alone. It doesn't take a master to see this - you are born to hone this craft to its fullest potential.$B$BWhile you've exceeded my expectations immensely, I sadly cannot teach you more than I already have. Don't fret, however, as my own master, Thegren, may aid where I fail to.$B$BShould you wish to specialize your craft and become a master in gemcutting, the art of manipulating gems to augment your abilities, search for Thegren. As a member of an ancient order, preceding any of our current civilizations, he chose a hermit's life, living secluded in the barren wastes of the Badlands. Seek him out near the ruins of the ancient city of Corthan. He does not speak to anyone, but should you show him this crystal, I assure you - he will listen to your cause. Be careful out there, it is a perilous journey to that dreary place!","$N! 잠시 시간 있으세요? 보석 세공에 대한 당신의 기술은 탁월합니다. 내 학생 중 누구도 내 가르침만으로 그러한 수준의 장인 정신을 달성한 경우는 거의 없습니다. 이것을 보는 데는 대가가 필요하지 않습니다. 당신은 이 기술을 최대한 연마하기 위해 태어났습니다. $B$BWhile 당신은 내 기대를 엄청나게 뛰어넘었습니다. 슬프게도 나는 이미 당신에게 가르칠 수 없습니다. 하지만 걱정하지 마십시오. 나의 주인인 테그렌이 내가 실패한 부분을 도와줄 수 있습니다. $B$BShould 당신은 자신의 기술을 전문화하고 보석 세공, 즉 능력을 강화하기 위해 보석을 조작하는 기술의 달인이 되고 싶다면 테그렌을 검색하세요. 현재 문명 이전의 고대 기사단의 일원으로서 그는 황무지의 황무지에서 은둔 생활을 하는 은둔자의 삶을 선택했습니다. 고대 도시 코르탄의 폐허 근처에서 그를 찾아보세요. 그는 아무에게도 말하지 않지만, 이 수정을 그에게 보여주면 장담합니다. 그는 당신의 주장을 들어줄 것입니다. 그곳은 조심하세요. 그 음울한 곳으로 가는 것은 위험한 여정입니다!"},objectives={{70,1271057286},"황야의 땅에 있는 코르탄 폐허로 가서 테그렌을 찾으세요."},progress={{85,1833991464},"<돌 피부가 덥은 dwarf는 당신이 그의 시간의 가치가 아니더라도, 이젠 그만을 갖습니다.>"},completion={{132,1222917783},"<Thegren의 가제 스위치와 크리스탈 사이 당신으로 가져. 시간에 당신을 위해 당신에게에 스타팅 후, 그는 nods.>"}}
rows[41278]={title={{18,1644081333},"보석학 마스터하기"},description={"$N, what a splendid sight to have you here with me once more. I have noticed - and you surely, too - that your progress in the craft has grown astronomically! Really, it has been too long since I've witnessed such prodigal skills at hand. This sadly means that my means of teaching are at an end. Your eagerness to learn more is apparent however; good thing  I can assist you one last time.$B$BShould you wish to strengthen your understanding in the field of gemology, there is someone - a secretive man, that can aid you in your ambitions. Older than anything I know, he is part of an ancient order, one that mastered the knowledge over Azeroth's minerals. As such, he values his privacy; meaning he will most likely not speak with you. Here, take this crystal with you. It is proof of my tutelage under him, and it will show him you can be trusted. Please, take care on your journey to him, for I wish you the safest of travels.$B$B<Gulmire does a short, cordial bow.>","$N, 당신이 나와 다시 한 번 여기에 함께하게 되어 정말 멋진 광경입니다. 나는 당신의 기술 발전이 천문학적으로 증가했다는 것을 알았습니다. 당신도 마찬가지입니다! 사실, 이런 엄청난 기술을 직접 목격한 것은 너무 오랜만이었습니다. 이것은 슬프게도 나의 가르치는 수단이 끝났다는 것을 의미합니다. 그러나 더 많은 것을 배우려는 귀하의 열망은 분명합니다. 다행이군요. 제가 마지막으로 도와드릴 수 있습니다. $B$BShould 당신이 보석학 분야에 대한 이해를 강화하고 싶은데, 당신의 야망을 도와줄 수 있는 비밀스러운 사람이 있습니다. 내가 아는 그 누구보다 나이가 많은 그는 아제로스의 광물에 대한 지식을 통달한 고대 조직의 일원입니다. 따라서 그는 자신의 프라이버시를 소중히 여깁니다. 이는 그가 당신과 이야기하지 않을 가능성이 높다는 것을 의미합니다. 자, 이 크리스탈을 가져가세요. 그것은 내가 그 사람 밑에서 지도를 받았다는 증거이며, 그 사람에게 당신이 신뢰할 수 있다는 것을 보여줄 것입니다. 가장 안전한 여행이 되시길 바랍니다. $B$B<Gulmire does a short, cordial bow.>"},objectives={{70,1271057286},"황야의 땅에 있는 코르탄 폐허로 가서 테그렌을 찾으세요."},progress={{85,1833991464},"<돌 피부가 덥은 dwarf는 당신이 그의 시간의 가치가 아니더라도, 이젠 그만을 갖습니다.>"},completion={{132,1222917783},"<Thegren의 가제 스위치와 크리스탈 사이 당신으로 가져. 시간에 당신을 위해 당신에게에 스타팅 후, 그는 nods.>"}}
rows[41279]={title={{13,656110655},"생명의 피"},description={{619,835237873},"<당신은 당신이 보는 것이 지구의 얼굴에 미소입니다. 거인의 몸에서 거친 보석은 그의 넓은 손에 작은 모습. 아니, 그게 모두 그가 제공하는, 한 번 더 무릎을 꿇기 전에.$B$B그 자리에 앉을 때, 당신은 지금 많은 것을 명확하게 볼, 절차는 여전히 당신을 세금. 세 보석은 당신의 안 눈 앞에 자신을 나타납니다. 운이, 당신은 그들을 인식: emberstone, 스타 루비, 그리고 감귤류. 당신이 볼 다음 것은 당신이 전에 결코 본 적이 없는 얼굴로 잘라 동일한 보석입니다. 조심스럽게, 당신은 움직임을 기억. 지혜는 당신의 마음에서 의약.>"},objectives={{98,2068011661},"코르단 폐허 동쪽의 적갈색 거인을 찾아 발견한 것을 가지고 테그렌에게 돌아가십시오."},progress={{56,1792338009},"<그런은 자신의 공예를 계속하고, 관심을 지불하지 않습니다.>"},completion={{638,1354319612},"<당신은 당신이 보는 것이 지구의 얼굴에 미소입니다. 거인의 몸에서 거친 보석은 그의 넓은 손에 작은 모습. 아니, 그게 모두 그가 제공하는, 더 많은 것을 무릎을 내기 전에.$B$B그 자리에 다시 한 번, 당신은 더 명확하게 지금, 절차는 여전히 당신을 세금을 갖는 것을 볼 수 있습니다. 세 보석은 당신의 안 눈의 앞에 스스로 나타납니다. 운이 좋을, 당신은 그들을 인식합니다: emberstone, 스타 루비와 시린. 당신이 보는 다음 것은 당신이 전에 결코 본 적이 없는 얼굴에 잘라 동일한 보석입니다. 조심스럽게, 당신은 움직임을 memorize. 지혜는 당신의 마음으로 편두어.>"}}
rows[41280]={title={{13,106625917},"데모"},description={{629,1942550122},"<당신의 비전을 다시 시작, Thegren은 그의 손 사이에 무언가와 팅입니다. 더 가까운 검사에, 그는 당신이 단지 목격 같은 얼굴에 스타 루비를 쉽게 절단하는 것이 좋습니다. 그가 그의 테이블에 그것을 배치 한대로, 다른 보석은 그의 파악에서 볼 수 있습니다, 시트린. 그는 같은 프로세스--그리고 다시 Emberstone로 반복합니다.$B$B엄밀한 모습으로, 예술의 포인트, 그의 공예에 그리고 그 후 당신에게 자신의 베어를 선물, 손을 뻗었다. 간접의 짧은 양 후, Thegren의 제스처는 당신을 감안하기 시작: 그는 당신이 단지 5 번 가르침을 3 잘라 당신을 복제 할 것으로 예상.$B$B너무 열심히 일하지 않아야합니까?>"},objectives={{83,236838034},"테그렌의 장인정신 테스트를 완료하고 그 후에 그에게 당신의 작품을 보여주세요."},progress={{41,1361332370},"<그런은 엄격한 표현을 기다립니다.>"},completion={{279,730131524},"<Dwarf의 흠없는 컷에 그들을 비교, 당신은 그의 기술을 복제하는 부과 시도를 거의 embarrased를보고. 그러나, 당신의 놀라움에, 다른 미소는 그들과 성취의 돌진에 자신의 얼굴에 자신을 울립니다.$B$B다음 단계가 당신을 기다리고 있습니다.>"}}
rows[41281]={title={{11,2048609343},"준비"},description={{592,122249830},"<무엇을 갖는 것은, 당신은 당신의 새로운 주인의 가르침의 다음 시각을 받기 위하여 무릎을 꿇습니다.$B$B의원은 의원을 갖는 의원을 갖는 의원을 갖는다. 의원은 의원을 갖는 의원을 갖는다. 의원은 의원을 갖는 의원을 갖는다. 의원은 의원을 갖는 의원을 갖는다. 의원은 의원을 갖는다. 의원은 의원을 갖는다. 의원은 의원을 의원으로 의원을 의원한다.$B$B당신은 당신의 발에 위로 돌아와 Thegren에 nod, 그는 단순히 자신의 일을 재시작하기 전에 자신의 가슴에 자신의 주먹을 배치.>"},objectives={{115,449702461},"마라우돈에서 산사태의 시체 조각을 회수하여 황무지의 코르탄 폐허 근처에 있는 테그렌에게 가져가십시오."},progress={{34,788644629},"<그런 팅커는 몇 가지 보석을 가지고 있습니다.>"},completion={{341,1242162761},"<돌의 무거운 석판을 기념하여 Thegren에게는 흥분을 가진 자신의 호박 눈 gleam을 볼 때 자부심을 느끼게합니다. 돌의 크리스탈 빛은 배원의 가혹한 태양에서 아름답게 반영하며 모든 힘든 작업을 더 끄는 데 도움이됩니다.$B$B그레나는 당신에게 턴하고 승인에 nods. 마지막 단계는 당신을 앞서있다.>"}}
rows[41282]={title={{13,1595750568},"최종 컷"},description={{507,1991877347},"<Thegren의 앞에 테이블에 놓인 3개의 것입니다. Boreghast의 몸에서 걸린 Lifeblood 주옥, Landslide의 대리석 돌 피부 및 시간의 통행에 의해 비난되는 것 같이 절묘한 피복 조각. 그들에는 광대하게 관찰해, 당신은 그(것)들을 돕습니다 - 다만 당신의 덩어리 표정에, 그의 망막이 해석을 위해 다량을 남겨두지 않는.$B$B이것은 최종 테스트입니다. 보석 절단에 대해 가르쳐준 것을 사용하여이 fiery 돌을 완벽한 모양으로 잘라내십시오.>"},objectives={{21,1173882747},"기말고사를 풀어보세요."},progress={{45,526857674},"<그는 그가 움직이는 altogether처럼 보인다.>"},completion={{327,727464489},"<아리잔은 얼굴을 띠는 Lifeblood Gem을 검사합니다. 그의 호박 눈은 반짝이는 붉은 보석의 모든 커트와 가장자리를 분명히 관찰합니다. 평가를 끝내면, 그는 당신을 보석을 뒤로 덮습니다. 존경을 깎기 전에.$B$B시험을 통과했습니다! Thegren은 자신의 테이블에 당신을 안내하고, 새로운 학생과 그의 지식을 공유하기 위해 노력합니다.>"}}
rows[41283]={title={{35,401042301},"장신구는 마음을 성장하게 만듭니다."},description={{446,903468745},"알았어, 솔직하게 말해 보자. 나는 자선을 베풀고 싶은 마음으로 당신에게 나의 비밀 공예 기술을 가르치지 않을 것입니다. 나는 당신에게 확신할 수 있습니다. 나는 절대 그렇게 하지 않을 것입니다. 그 대신, 당신은 내가… 내 보급품을 보충하는 데 도움을 주고, 그 결과 내 금세공에 관한 상당한 양의 지식을 얻게 될 것입니다. 완벽한? Perfect.$B$BPlease 다음 사항을 가능한 한 빨리 가져옵니다. 저는 너무 오래 기다리는 유형이 아닙니다."},objectives={{37,828141483},"탈바쉬에게 필요한 재료를 가져오세요."},progress={{32,872060022},"없으시면 가서 가져가세요!"},completion={{299,2063451151},"음, 음, 제가 예상했던 것만큼 초라하지는 않습니다. 그러나 그것은 분명히 Mayva의 조잡한 장인정신을 담고 있습니다. 이제 당신을 내 손에 맡길 수 있어서 다행입니다. 곧 당신을 유용한 보석 세공인으로 만들어 드리겠습니다! 여기에서 이 사랑스러운 장신구를 만드는 것부터 시작하세요. 복제하는 데 문제가 없을 것입니다… 바라건대."}}
rows[41284]={title={{27,1538549208},"반지를 끼워야 해"},description={{679,830637698},"믿거나 말거나, 산 아래 산다고 해서 창고에 보석이 꾸준히 유입되는 것은 아닙니다. 일부 거짓 소문으로 인해 이곳에서 선하고 정직한 거래에 참여하는 것이 방해된다면 확실히 도움이 되지 않습니다. 내가 아직 놈리건에 있었다면 이 모든 것이 더 쉬웠을 텐데, 내 말을 믿으세요. 그럼에도 불구하고 보석은 보석세공의 빵과 버터입니다. 보석도, 보석도, 거래도, 돈도, 임대료도 없습니다. 당신은 아이디어를 얻습니다. 그리고 집주인을 달래는 것이 절실히 필요하기 때문에, 말하자면 내 손실을 메우기 위해 반짝이는 미녀가 꽤 많이 필요합니다.$B$BAre 우리도 같은 입장인가요? 물론 그렇습니다. 다음 보석을 충분히 가져오시면 작은 것을 건네드리겠습니다."},objectives={{37,828141483},"탈바쉬에게 필요한 재료를 가져오세요."},progress={{106,843186393},"이런 것들은 나무에서 자라지 않아요, 아시죠? 아니면 지하. 아니면 어디든. 신경쓰지 마세요. 그냥 지나가세요!"},completion={{250,636091130},"당신은 어떨지 모르겠지만, 탐사자의 렌즈 빛 아래에서 이 작은 보물들이 빛나고 반짝이는 것을 보는 것은 결코 질리지 않을 것입니다. 확실히 당신은 이해합니다. 이제 그 내용을 다루었습니다. 자, 잘 들어보세요. 반복하지 않겠습니다!"}}
rows[41285]={title={{17,613624404},"나쁜 믿음으로 남겨진"},description={"Whatever you've been told about me - it's all lies! I one hundred percent NEVER made any sort of cursed item for anyone. I have integrity for my craft and an oath to keep! Please don't ask who I made an oath with. Strictly confidential. And definitely NOT shady.$B$BRegardless, it seems the misfortune of some ill adventurer now befalls me instead, slandering my good name once again. A daring mage sought me out for a spell-enhancing necklace on his ventures to the recently re-discovered Gilneas City to the north. Ofcourse I obliged and crafted one for him, rent was due anyway, yet his spelunking in that accursed place did not end… let's say favorably for him. Too bad his group of fellow adventurers now blame me for his demise, lying to everyone in Ironforge that I enchanted the necklace with a foul spell!$B$B$N, I want you to delve into Gilneas City yourself and bring me back that necklace! The last thing I want is people using it as false evidence against me.","당신이 나에 대해 무슨 말을 하든 그건 모두 거짓말이에요! 나는 100퍼센트 누군가를 위해 어떤 종류의 저주받은 아이템도 만든 적이 없습니다. 나는 내 기술에 대한 성실성을 갖고 있으며 지켜야 할 맹세를 갖고 있습니다! 내가 누구와 맹세했는지는 묻지 마세요. 엄격하게 비밀이 보장됩니다. 그리고 확실히 shady는 아닙니다. $B$BRegardless, 어떤 나쁜 모험가의 불행이 이제 나에게 닥친 것 같습니다. 내 좋은 이름을 다시 한 번 비방합니다. 한 대담한 마법사가 최근 북쪽에서 재발견된 길니아스 시를 향한 그의 모험에서 주문을 강화하는 목걸이를 찾기 위해 나를 찾아왔습니다. 물론 나는 그를 위해 의무를 다하고 하나를 만들었습니다. 어쨌든 임대료는 지불해야 했지만 그 저주받은 장소에서의 그의 동굴 탐험은 끝나지 않았습니다… 그에게 호의적으로 말합시다. 안타깝게도 그의 동료 모험가 그룹은 내가 목걸이에 사악한 주문을 걸었다고 아이언포지의 모든 사람들에게 거짓말을 하며 그의 죽음에 대해 나를 비난하고 있습니다!$B$B$N, 당신이 직접 길니아스 시티에 들어가서 그 목걸이를 다시 가져오길 바랍니다! 내가 원하는 마지막 것은 사람들이 그것을 나에 대한 거짓 증거로 사용하는 것입니다."},objectives={{73,1394874356},"모험가의 목걸이를 가지고 아이언포지에 있는 탈바쉬 델 키셀에게 돌아가세요."},progress={{75,1073962157},"<Talvash sighs deeply.>$B$BOh, 놈리건으로 돌아오려면 얼마나 주고 싶은데요!"},completion={{415,2087656947},"피투성이이고, 흠뻑 젖고, 진흙으로 가득 차 있습니다. 아, 내 훌륭한 작품 중 하나가 이렇게 무례한 상태에 있는 것을 보니 마음이 아프네요. 그럼에도 불구하고 구해주셔서 감사드립니다. 그의 구타당한 시체에서 그것을 어디서 찾았습니까? 아니면 다른 사람의 더러운 손이 그에게서 그것을 훔쳤습니까? 그거 알아? 말하지 마세요. 차라리 잊어버리고 싶습니다. $B$BAs 당신의 고귀한 행위에 대한 보상으로 이 초커를 직접 만드는 방법을 가르쳐 드리겠습니다."}}
rows[41286]={title={{13,1094957660},"기술자"},description={{846,495839173},"바로 이거야, 좋은 여행자여. 다른 곳에서는 배울 수 없는 것보다 내가 가르칠 수 있는 것은 많지 않습니다. 그래도 지식에 대한 갈망으로 인해 여기서 멈출 수 없다면 내가 얻은 멋진 비법을 모두 알려 드리겠습니다. $B$BTechnically 이런 말을 해서는 안 되지만 긴급한 도움으로 보상 없이 떠나게 할 수는 없습니다. 멀리 서쪽, 적대적인 잊혀진 평원에서 문명으로부터 고립된 나만의 멘토를 찾을 수 있을 것입니다. 비록 그는 방해받지 않고 있기를 바랐지만 어떤 사람들과 함께 있어도 개의치 않을 것이라는 것을 나는 알고 있습니다. 그가 처음에 당신과 이야기하지 않더라도 낙심하지 마십시오. 지식을 추구하려는 사람들에게 끈기는 끈기를 가장 중요하게 생각합니다! $B$BLook 바다가 내려다보이는 거대한 탑의 경우, 제가 그를 마지막으로 본 곳이 바로 그곳입니다. 이제 이 문제를 해결했으니 집주인이 내가 암시장 활동에 참여하고 있다고 생각하기 전에 빨리 떠나는 것이 좋습니다!"},objectives={{38,23696864},"잊혀진 땅에서 신비한 가정교사를 만나보세요."},completion={{190,169409373},"<The Highborne eyes you dismissively.>$B$BFirst 저 아래에 있는 이 멍청한 인간, 그리고 지금 당신은요? 예술가는 인생에서 단 한 번도 평화와 고요함을 찾을 수 없을까요? 누가 당신을 The Artificer로 보냈는지 말해 보세요."}}
rows[41287]={title={{18,383228588},"균열 속의 모래"},description={{424,356835006},"솔직하게 말씀드리자면, 이곳 광야에서는 우리의 공급품이 당신을 제대로 가르칠 만큼 충분하지 않습니다. 오그리마에 있는 우리 키 작은 녹색 친구들이 가지고 있는 무한한 자원을 나한테 갖고 있는 것 같지는 않아요. 그러나 우리가 함께 일할 수 없는 것은 없습니다. 다행스럽게도 이 땅에는 천연 자원이 풍부하여 강의 자료로 사용할 수 있습니다. $B$BTake 이는 자신이 얼마나 능력이 있는지 확인하는 일종의 테스트입니다."},objectives={{63,153625204},"황야의 땅 카르가스에 필요한 재료를 자칼에게 가져가세요."},progress={{70,1689540886},"저 밖에 돌아다니는 오우거들을 조심하세요. 제가 좋아하는 것보다 너무 많습니다."},completion={{307,1761718969},"잘했어요. 이곳에서 보석세공에 필요한 재료를 이렇게 많이 가지고 있는 경우는 거의 없었습니다. Gulmire가 나에게 새로운 보고서를 기다리는 동안 할 수 있는 실질적인 일을 주었기 때문에 어떤 형태로든 감사가 필요할 것 같습니다. 그러나 $B$BBack는 귀하에게 있습니다. 이 섬세한 장신구를 만드는 방법을 보여 드리겠습니다."}}
rows[41288]={title={{18,463676690},"광채의 돌"},description={{396,1980493555},"여러분도 분명히 아시겠지만, 보석, 귀중한 돌, 광물은 보석세공에 필수적입니다. 그것들 없이는 패셔너블한 작품을 만드는 것이 확실히 가능할 수도 있습니다. 하지만 솔직히 말해서 요점이 무엇일까요? 제 소견으로는 섬세한 보석이나 심지어 화려한 보석은 보석의 목적과 의미를 부여하는 요소입니다. $B$BBring 우리가 그 속성을 함께 분석할 수 있도록 아제로스의 보석을 충분히 확보해 주세요."},objectives={{65,1989375035},"황야의 땅 카르가스에서 필요한 재료를 자르칼에게 전달해야 합니다."},progress={{131,645328272},"진주는 아제로스 전역의 두꺼운 조개 껍질에서 흔히 발견됩니다. 물에 사는 많은 생물들은 그것들을 가지고 다닙니다."},completion={{267,897663297},"희미할 수도 있지만, 이 보석에서 나오는 힘이 있습니다. 최고의 보석 세공인은 강력한 정수를 추출하여 전례 없는 수준으로 증폭시킬 수 있습니다. 그리고 제가 이렇게 말할 수 있도록 허락하신다면, 당신은 언젠가 그 지점에 도달할 수 있는 좋은 길을 가고 있습니다."}}
rows[41289]={title={{17,170878570},"외국 지식"},description={{738,216634924},"우리 부족은 제거 가능하거나 영구적인 금세공 및 현혹에 대한 광범위한 역사를 가지고 있습니다. 제가 옛날 잔달라 금세공 관습에 대한 통찰력을 공유하는 동안, 다른 지식의 원천으로도 시야를 넓히는 것이 중요합니다. $B$BWhat 제가 여러분이 탐구하고 싶은 것은 예복을 만드는 인간적인 방식입니다. 우리의 버려진 동맹국의 땅에서 멀지 않은 북쪽에 길니아스라는 나라가 있을 것입니다. 내가 듣기로는 옛날의 유물이 이제 그 위험과 위험을 극복하려는 열망을 가진 사람들에게 새롭게 공개되었다고 들었습니다. 여행하는 모험가들의 이야기에 따르면 산 능선 꼭대기에 있는 길니아스 시티는 상업, 교역, 축제의 장소입니다. $B$BIt는 우리가 분석하기에 적합한 다이제스트를 찾을 수 있는 곳입니다."},objectives={{101,573168547},"길니아스 시에서 딱 맞는 책을 찾아 황야의 땅 카르가스에 있는 자칼 모스멜드에게 가져가세요."},progress={{61,444042377},"나는 이 보석을 얻는 것이 당신에게 문제가 되지 않을 것이라고 확신합니다."},completion={{300,271891672},"참혹한 소식. 당신이 설명하는 내용은 너무도 친숙합니다. 이전의 많은 트롤 제국은 자만심에 빠져 스스로를 자기 민족이나 심지어 로아보다 우월하다고 생각했습니다. 무사히 돌아오셔서 더욱 다행입니다. $B$BNow 그럼, 변색된 이 페이지에서 정보를 캐어볼까요?"}}
rows[41290]={title={{13,1094957660},"기술자"},description={{816,1683046933},"좋은 여행자님, 제가 오랫동안 할 수 없었던 이 기술을 연습하게 해주셔서 감사합니다. 나는 계속해서 기술을 연마하겠다고 약속했지만, 지난 몇 년 동안 호드에 대한 나의 봉사로 인해 더 이상 이 맹세를 추구할 수 없었습니다. 하지만, 어쩌면 당신 같은 모험가들이 더 많이 찾아온다면 결국 그렇게 할 수 있을 것입니다. $B$BFor 긴급한 도움, 제대로 보상해 드리겠습니다. 제가 금세공의 숙련도를 강화한 곳을 공유해 드리겠습니다. 멀리 서쪽, 적대적인 잊혀진 평원에서 문명으로부터 고립된 나만의 멘토를 찾을 수 있을 것입니다. 비록 그는 방해받지 않고 있기를 바랐지만 어떤 사람들과 함께 있어도 개의치 않을 것이라는 것을 나는 알고 있습니다. 그가 처음에 당신과 이야기하지 않더라도 낙심하지 마십시오. 지식을 추구하려는 사람들에게 끈기는 끈기를 가장 중요하게 생각합니다! $B$BLook 바다가 내려다보이는 거대한 탑의 경우, 제가 그를 마지막으로 본 곳이 바로 그곳입니다."},objectives={{38,23696864},"잊혀진 땅에서 신비한 가정교사를 만나보세요."},completion={{190,169409373},"<The Highborne eyes you dismissively.>$B$BFirst 저 아래에 있는 이 멍청한 인간, 그리고 지금 당신은요? 예술가는 인생에서 단 한 번도 평화와 고요함을 찾을 수 없을까요? 누가 당신을 The Artificer로 보냈는지 말해 보세요."}}
rows[41291]={title={{25,835267072},"불행한 상황"},description={{617,632198529},"그렇다면 당신은 금세공 기술을 배우는 데 확고한 의지가 있습니까? 보통은 내가 학생을 뽑는데… 만약 예전 학생 중 한 분이 당신을 추천해 주셨고 심지어 불확실한 검색에 당신을 보냈다면 나는 당신의 요청을 결코 거부할 수 없습니다. 즉시 시작할 수도 있지만, 우리가 직면한 작은 곤경이 있습니다. 불행하게도 나는 해변으로 밀려온 광물을 수집하던 중 소중한 보석 세공사 키트를 잃어버렸습니다. 바다 거인에게 깜짝 놀라서 그것을 버려야 했고, 그것을 회수할 안전한 순간을 찾을 수 없었습니다. 내 싸움의 날은 끝났으니 내 기술을 배우고 싶다면 나 대신 그것을 되찾아야 합니다."},objectives={{66,126092858},"보석공 도구를 잊혀진 곳에 있는 에델레소르에게 기술병을 가져가야 합니다."},progress={{51,1456616749},"내 악기가 조수로 인해 손상되지 않기를 바랍니다."},completion={{99,879807585},"눅눅하고 물이 뚝뚝 떨어지지만 여전히 손상되지 않았습니다. 내 감사는 보장됩니다, 학생. 그럼 계속 진행하겠습니다."}}
rows[41292]={title={{23,237401769},"금세공 기술"},description={{661,2026845373},"저를 '기술자'라고 부르시면 됩니다. 나는 수천 년 전 위대한 도시 엘드레탈라스가 함락되었을 때 이전 이름을 버렸습니다. 그 이후로 나는 칼림도어의 야생을 방황하면서 내 지혜를 받을 자격이 있다고 생각되는 필멸 종족들에게 내 지혜를 공유합니다. 당신을 여기로 보낸 이 친구는 믿을 수 없을 만큼 제가 가르친 사람 중 한 명입니다. 하지만 공예에 대한 그의 사랑은 시간이 지나도 식지 않은 것 같습니다. $B$BYou 인종, 문명, 세대 간에 전해 내려오는 수백 년 된 금세공 기술의 비밀을 배우고 싶으십니까? 나에게 당신의 능력을 증명해 보세요. 대지의 피가 노래하는 소리를 얼마나 잘 들을 수 있는지 보여주세요."},objectives={{100,442245269},"다음 장신구를 제작하세요. 기술을 입증한 후 기술병이 방법을 가르쳐 줄 것입니다."},progress={{121,2102514574},"끈기를 유지하십시오. 기꺼이 실패하려는 사람들은 스스로가 이 기술의 야심 찬 거장임을 계속해서 입증해 왔습니다."},completion={{716,198027279},"그토록 심오한 절단과 연삭 작업이 인상적입니다. 이 작품을 만들기 위해 쏟아부은 피와 땀, 눈물을 누구나 볼 수 있습니다. 예술 작품에 숨쉬는 생명력은 기술적 단계만큼이나 중요합니다. 영혼이 없는 보석은 단지 제품일 뿐이며, 수천 년 동안 이어온 공예품의 온전함에 대한 모독입니다. $B$BBut 당신은 당신의 심장이 아제로스의 조화와 조화를 이루며 뛰고, 자신을 아제로스의 본질에 맞추고 그 에너지를 당신의 예술로 전달한다는 것을 증명했습니다. 나의 새로운 학생으로서 나의 신성한 지식을 당신에게 전할 수 있게 허락해 주십시오. 당신은 그것을 얻었습니다.$B$BOh, 그리고 혹시 내 이전 학생을 다시 만나면 언제든지 나를 방문할 수 있다고 말해주세요. 어떤 회사는 몇 년 후에 해를 끼칠 수 없을 것 같습니다."}}
rows[41293]={title={{26,1171450856},"정교한 황금 팔찌"},description={{477,81851714},"그래서 그는 당신에게 그의 기술 중 일부를 가르쳤습니다. 뭐, 안심하세요. 그가 갖고 있는 지식의 대부분은 제가 그에게 전수한 것입니다. 그는 숙련된 보석세공가일지 모르지만, 그보다 더 이해하기 어려운 예술의 비밀은 그에게서 발견되지 않습니다. 공예의 깊이를 알고 싶다면 표면에 대한 심오한 이해가 있어야 합니다. $B$BWhich가 바로 제가 당신에게 원하는 것입니다. 금세공에 관해 당신이 가지고 있는 기본 지식이 무엇인지 보여주시면 어디서부터 시작해야 할지 알 수 있습니다."},objectives={{75,1219642806},"자신이 디자인한 주얼리와 다른 사람이 디자인한 주얼리를 The Artificer에게 선물하세요."},progress={{84,1292943396},"속도로 나에게 깊은 인상을 주려고하지 마십시오. 나는 시간을 들이는 사람들을 높이 평가합니다."},completion={{299,52511595},"<The Artificer inspects your work and the replica.>$B$BClose. 내 지도 없이도 당신은 내 제자의 발걸음을 따라하는 놀라운 일을 해냈습니다. 놀랄 만한. 그럼에도 불구하고, 당신의 진정한 잠재력을 측정하려면 내 지도에 따라 예술 작품을 만들어 보시기 바랍니다. 자, 잘 들어보시고 잘 들었다는 걸 보여주세요."}}
rows[41294]={title={{12,1833748707},"관찰"},description={{414,1946005278},"진정한 장인은 삶의 모든 측면을 자신의 작품에 담아냅니다. 삶, 죽음. 하늘과 땅. 우리 세계에서 활동하는 요소. 이미 알고 계시겠지만, 아제로스의 보석에는 잠재된 마법과 원소 속성이 있어서 옳은 사람이든 그른 사람의 손에서든 극도로 강력한 힘을 발휘할 수 있습니다. $B$BDemonstrate 당신이 보석을 만들 때 아제로스 보석의 에너지를 적절하게 다룰 수 있다는 점을 알려주세요."},objectives={{31,201544735},"Artificer에게 당신의 기술을 보여주세요."},progress={{173,1263874416},"우리 작품이 타인의 이익을 위해 사용되는지, 아니면 손해를 끼치기 위해 사용되는지 여부는 우리 관할권의 일부가 아닙니다. 아티스트는 사용자를 염두에 두지 않고 단순히 용도만 고려하여 창작물을 만듭니다."},completion={{293,693923539},"세상을 있는 그대로 인식하는 것은 단순하고 평범해 보일 수 있지만, 더 깊이 탐구하고자 하는 사람만이 세상의 진정한 본질에 대한 심오한 이해를 얻을 수 있습니다. $B$BYou는 당신도 그 중 하나라는 것을 나에게 보여주었습니다. 내 말에 주의를 기울이고 귀를 기울이십시오. 왜냐하면 그것이 당신에게 새로운 통찰력을 줄 것이기 때문입니다."}}
rows[41295]={title={{17,760518094},"친애하는 갈리트리아"},description={{842,1178128812},"나는 지난 세기에 여러 개의 습지가 있었고, 펑크 나는 얼마나 많은에 대한 잃어버린 수를 잃었습니다. 그러나, 항상 내 마음과 마음에서 생생하게 남아있을 것입니다. 젊은 엘프, 내가 전에 본 적이 같은 공정한 피부 중 하나입니다. 금장을위한 그녀의 호기심과 맹세는 내 마음과 마음에 감탄하지 않았다. 나는 그녀의 배심원 정신에 대해 감탄 한 속성.$B$B그녀는 비스듬한 예술에 접근하고 그것이 무엇인지 위해 그것을했다. 심장과 영혼의 표현. 그녀는 그녀의 최종 프로젝트를 완료 할 때, 중요한 품질의 직원, 모험의 바람은 나를 멀리 휩쓸. 내가 희망하는 동안 나는 나를 한 날에 돌아갈 것이다, 심지어 방문으로, 그녀의 슬픔으로 다시 시작.$B$B그녀의 존재 - 그리고 부족 - 나에게 마크를 왼쪽, 내 미래 학생의 모든 주장은 공예에 대한 그녀의 명확한 시력을 공유. 당신은 그녀의 예를 따를 수 있음을 보여줍니다."},objectives={{60,258397579},"기술공의 교훈을 이해하고 있음을 설득하세요."},progress={{139,46495954},"가끔 나는 그녀의 행방을 생각하면 감상적이 된다. 그러나 그녀를 걱정하는 것은 억누르기가 어렵지만 소용이 없습니다."},completion={{239,2114712170},"<The Artificer is surprisingly solemn at the view of your pieces. A soft chuckle escapes him, before turning back to you.>$B$BThank 당신. 당신이 나를 찾아줘서 기뻐요. 여기에서는 내가 지도하는 동안 Gallitrea가 디자인한 것을 여러분과 공유하겠습니다."}}
rows[41296]={title={{13,1285035590},"수집가"},description={{918,2138433694},"내 백성은 나뉘어졌습니다. 우리는 안전과 생존할 곳을 찾아 집에서 탈출하는 과정에서 많은 시간을 견뎌왔습니다. 하버리지에 있는 내 형제들은 회복력을 유지하고 희망에 매달렸지만, 잃어버린 형제들에 대해서는 똑같이 말할 수 없습니다. 그들의 광기는 그들의 마음속에 깊이 자리 잡았고, 그 뿌리는 더 이상 잘라낼 수 없습니다. 그들은 지옥 같은 드레노어로 돌아가려는 헛된 노력으로, 제대로 활용할 수 없다는 사실도 모른 채 해당 세계에서 강력한 보석인 드레니시스트 수정을 수집합니다. 그러나 항상 그런 것은 아닙니다. $B$BAmong 그들은 Kum'isha라는 이름의 강력한 균열 워커였으며, 휴경지 성역의 미친 드레나이와 헤어졌습니다. 그는 이제 신화와 전설을 찾아 남쪽 땅의 적대적인 평원을 배회하고 있습니다. 내가 찾고 있는 것은 우리의 신성한 수정에 대한 그의 지식입니다. 그러나 당신이 그를 설득하여 우리와 합류할 수 있다면; 제발, 주저하지 마세요."},objectives={{37,389959548},"저주받은 땅에서 쿰이샤를 찾으세요."},progress={{4,273767400},"응?"},completion={"You reek, $R, horribly. I can smell the despicable stench of naivety and senseless hope on you. Let me take a guess, Sanv K'la and his wretched followers sent you to pry knowledge from my great mind. If that is the case, then I cannot wait to see the disappointment in your face.","$R, 정말 악취가 나네요. 나는 당신에게서 순진함과 무의미한 희망의 비열한 악취를 맡을 수 있습니다. 추측해 보겠습니다. Sanv K'la와 그의 비참한 추종자들이 내 위대한 정신에서 지식을 캐내도록 당신을 보냈습니다. 그렇다면 나는 당신의 얼굴에 나타나는 실망을 빨리 보고 싶습니다."}}
rows[41297]={title={{15,2013038995},"구직자를 찾는 중"},description={{874,2010085152},"나는 잃어버린 자들을 남겨두고 떠났고, 그들의 지도자들은 그들의 진정한 잠재력을 잊어버린 채 신성한 드레니시스트에 침을 흘리는 서투른 바보들이 되었습니다. Sanv K'la도 다르지 않습니다. 희망은 그와 그의 수행자들의 마음을 오염시켰고, 그가 탐욕의 세계에 갇혀 있다는 사실을 무시했습니다. 그것은 당신에게도 해당됩니다. 수집가 쿰이샤여, 당신이 원하는 것을 나에게서 빼앗기 위한 것이 아니라면 당신이 내 앞에 서 있는 이유는 또 무엇입니까? 하지만 나는 당신과 당신 종족을 알고 있으며, 당신의 탐욕이 내 야망을 더욱 발전시킬 것입니다. $B$BRoaming 이 저주받은 땅은 아무 생각 없이 균열을 걷는 마법을 휘두르는 무의미한 드레나이입니다. 드레니시스트를 향한 끝없는 탐색 속에서 그들은 정신을 잃고 마치 해충처럼 모래를 수색하고 있습니다. 광포한 짐승들아, 그들 모두! 그들은 내 캠프를 습격하여 귀중한 수정 은닉처를 훔쳤습니다. 그들을 학살하고 내 소지품을 회수하면 당신의 유용성에 대한 보상을 받을 수 있습니다."},objectives={{112,145605001},"저주받은 땅의 드레나이에게서 뒤죽박죽된 상자를 찾아 저주받은 땅에 있는 쿠미샤에게 가져가야 합니다."},progress={{89,1309788243},"당신의 능력이 당신을 버렸나요? 쓸데없는 쓰레기야, 너랑 시간을 낭비하지 말았어야 했는데."},completion={{258,1150447371},"예상대로 손상되었습니다. 야만적인 짐승. 적어도 그 내용은 온전합니다. 그렇다면 당신은 행운아라고 생각할 수 있습니다. 그런데 이 두루마리가... 설마...? 더러운 자여, 당신의 탐욕은 나에게 큰 도움이 되었지만, 당신의 대가는 아직 요구할 준비가 되지 않았습니다."}}
rows[41298]={title={{16,2118814322},"드레노어의 사절"},description={{936,54930560},"<Kum'isha is studying the foreign scroll, his shifting body fading in and out of view. After finishing reading, he furiously rips the parchment into bits.>$B$BKarak-토칼! 그들은 무엇을 생각하고 있습니까? 이것은 모든 드레나이에게 이단이다, 이단이다! 그들이 드론처럼 죽음의 땅을 돌아다니는 것은 위험하지는 않지만 걱정스러웠습니다. 그러나 그들이 목표로 하는 것은 매우 그렇습니다. 이 성서에 따르면, 당신이 만난 구도자들은 마토가르라는 균열 워커인 사악한 생물을 위해 드레니시스트를 모으고 있습니다. 그것만으로도 내 야망에 대한 모욕이지만, 그의 진정한 목표는 역겨워서 막아야 합니다. 만약 그가 수정을 드레노어로 가져갈 수 있다면, 우리가 돌아갈 수 있는 유일한 길은 사라질 것입니다. 우리는 부패하고 부패하며 감옥에 갇혀 다시는 우리 집을 볼 수 없게 될 것입니다. $B$BYou는 그런 일이 일어나도록 놔두지 않을 것입니다. Kum'isha가 당신이 원하는 것을 당신에게 줄 것이기 때문입니다. 그의 머리 대신에. 그는 내 캠프 북서쪽에서 찾는 이들을 기다리고 있습니다."},objectives={{74,1782563398},"저주받은 땅에 있는 수집가 금이샤에게 마토가르의 머리를 가져가야 합니다."},progress={{162,596691457},"드레네시스트 수정을 드레노어로 옮기는 것은 황폐하고 역겨운 세상에 발이 묶인 모든 드레나이의 죽음을 의미합니다. 쿠미샤는 이런 일이 일어나도록 놔둘 수 없습니다."},completion={{408,1598713905},"<The broken draenei grabs the decapitated head with unexpected force. Spitting on the bloodied skin of Mato'gar's head, he throws it unto the ground before stomping it violently into the red sand.>$B$BPathetic 비열한 놈, 파멸과 황폐의 대사. 당신의 조상이 당신의 백성, 친척을 배신한 대가로 당신의 영혼을 갈기갈기 찢어 놓기를 바랍니다! 우리의 탈출 수단을 빼앗는 것은 내 마음을 아프게 합니다."}}
rows[41299]={title={{21,143274033},"금이샤의 감사"},description={{406,1088229760},"여기,이 스크롤을 가지고. 그것과 네이티브 샌프 K'la는 Draenethyst와 그것의 용도의 내 지식을 찾을 것입니다. 그가 무엇을 할 것인지, 그것은 내 계획과 방해하지 않는 한. 그것은 내 경고를 치유하는 그의 가장 관심에, 그는 Mato'gar와 같은 끝.$B$B너에게는 다음과 같이 말하고 말하길 원하지 않으려면, 나는 너희에 눈을 낳고 싶지 않습니다. 그렇게하면 Begone."},objectives={{67,1644238586},"Kum'isha의 두루마리를 가지고 슬픔의 늪에 있는 Sanv K'la에게 돌아가세요."},progress={{80,1526003685},"당신은 저주받은 황무지에서 돌아왔습니다. 그리고 혼자. 무슨 일이 일어났는지 말해주세요."},completion={{485,1516908074},"듣기만 해도 비극적이고 괴로워요. 우리 고향에서 온 드레나이의 개입과 해당 장소로 돌아가려는 금이샤의 간절한 소망 둘 다입니다. 나는 언젠가 다시 집으로 부를 수 있는 안식처, 안식처를 찾아 우리 백성을 이곳으로 이끌었습니다. 이 두루마리에 적힌 지혜와 드레니시스트의 마법으로 우리는 함께 이 일을 이룰 수 있습니다. $B$BBe 안심하십시오. 우리 백성을 위한 당신의 업적은 결코 잊혀지지 않을 것입니다. 당신은 스스로 그 페이지를 읽을 수 없기 때문에 이 성구에 대한 통찰력을 공유하겠습니다."}}
rows[41300]={title={{20,190291531},"친절하게 물어보세요"},description={{787,939826938},"아, 이건 나쁘다! 한 명의 노움이 얼마나 불행할 수 있습니까? 나는 끔찍한 실수를 저질렀고 이제 머리가 망가지거나 심지어 집까지 잃게 될 것입니다!$B$BSimply 넣어, 내 재정은 매우 건조합니다! 나는 절박했지만, 엄청난 금을 약속하는 의심스러운 상인의 제안을 받아들였습니다. 그러나 두 번째 방문에서 그는 두 명의 무서운 깡패를 대동하고 원래 동의했던 것보다 더 많은 물건을 나에게 요구했습니다! 내 공급품이 그의 요구를 충족시키지 못한다고 설명하는 내 탄원은 귀에 들리지 않았으며 이제 그들은 나를 위협하고 있습니다. 나, 장엄하고 타의 추종을 불허하는 Talvash del Kissel!$B$BPlease, 내 딜레마를 도와주세요! 정당한 보상을 받을 것을 약속드립니다. The Commons를 향해 떠난 악당들, 이 도둑들은 외곽 고리를 따라 수많은 집 어딘가에 숨어있을 것이라고 확신합니다!"},objectives={{72,682716627},"아이언포지에 있는 탈바쉬 델 키셀을 위협하는 수상한 사람들과 대화하세요."},progress={{11,819267740},"그것은 무엇입니까?"},completion={{124,2068929572},"문제를 해결하기 위해 스스로 괴짜를 보낸다고요? 이제 이것은 그 꼬불꼬불한 작은 노움에 대해 내가 예상하지 못했던 일입니다."}}
rows[41301]={title={{17,1404721063},"언더마켓 제안"},description={{787,1804920157},"그럼 당신은 무엇을 위해 여기에 있습니까? 자신의 약속을 지키고 싶지 않은 친구를 괴롭히지 말라고 정중하게 부탁하기 위해? 아니면 문제 해결을 위해 좀 더... 직접적인 접근 방식을 취하기 위해 여기에 오셨나요? 어느 쪽이든 둘 다 작동하지 않을 것임을 알려드리게 되어 유감입니다. 마감일은 우리 조직이 중요하게 생각하는 것이며 이를 지킬 수 없는 사람들... $B$B<He gestures to the two daunting guards standing behind you.>$B$BI 그러나 저는 환영받는 상인이며 실망스러운 거래 파트너에 대한 적개심을 위해 기회를 버리지 않을 것입니다. 대신 제가 제안을 하나 드리겠습니다. 탈바쉬가 아직 우리에게 빚지고 있는 물품의 두 배를 전달하면 나와 내 동포들은 그를 그대로 두는 것을 고려할 것입니다. 건전한 제안이죠? 내가 당신 입장이라면 최선을 다해 받아들일 텐데…"},objectives={{86,319175362},"아이언포지의 신비한 수호물에 있는 탈바쉬 델 키셀에게 돌아가서 그에게 지불금을 주어야 합니다."},progress={{154,1497156882},"직접 만드시든, 다른 곳에서 구입하시든 상관없습니다. 고품질인지 확인하세요. 우리의 후원자들은 특정 표준을 중요하게 생각합니다."},completion={{79,97552848},"돌아오신 것 같군요. 이제 당신도 떠날 수 있는지 확인해보자..."}}
rows[41302]={title={{16,751524200},"휴전 협상"},description={{369,1618322118},"<Motsog inspects the wares meticulously with a lens. While he does so, you can feel the bouncers breathing down your neck. After the shady merchant is done, he stores the jewelry in a box and tosses you a bag of money.>$B$BIt는 귀하와 거래하게 되어 기뻤습니다. 지금 당장 친구에게 달려가서 여기에서 두 사람의 얼굴을 다시는 보여주지 않는 것이 좋습니다. 가라."},objectives={{93,416043469},"Ironforge의 신비주의 지구에 있는 Talvash del Kissel.Kissel에게 돌아가서 그에게 지불금을 주십시오."},progress={"$N! What took you so long? I feared they gave you an early visit to the afterlife. So, what is it? Am I safe?","$N! 왜 그렇게 오래 걸렸나요? 나는 그들이 당신에게 사후세계를 일찍 방문하게 했을까봐 두려웠습니다. 그래서, 그것은 무엇입니까? 나는 안전합니까?"},completion={{606,1265344031},"<Talvash opens the bag and looks exasperated.>$B$BWhat?! 이건 내가 약속한 것의 절반에 불과해! 아, 이 빌어먹을 살인자, 질척질척한 슬라임백, 그리고 빌어먹을 그의 매우 위협적인 경호원들까지! 글쎄, 적어도 나는 죽지 않았지, 그렇지? 정말 고마워요! 정말 감사해요! 나한테 서슴없이 목을 내미는 너 요즘엔 흔하지 않은 일이잖아. 이 깡패들이 다시는 나를 귀찮게 하지 않기를 바랍니다. $B$BBut 나에게 말해주세요: 당신이 나 대신 배달한 보석, 당신은 우연히 보석 세공인인가요? 그렇다면 귀하의 용감한 영웅적 행위를 위해 제가 특허를 취득한 디자인 중 하나를 공유하겠습니다!"}}
rows[41303]={title={{15,453245459},"래칫에서 길을 잃다"},description={{698,319060723},"재앙, 바로 그거야! 금전적 종말이 나에게 닥쳤습니다. 내 이름은 더럽혀졌고, 내 명성도 사라졌습니다. 내 값비싼 보석은 무법항 경매로 가는 중이었는데, 그중에는 특히 귀중하고 무거운 반지가 있었습니다. 항구 도시까지 무사히 도착했다고 믿고 별 생각 없이 일을 계속했는데, 그것이 라쳇을 떠나지도 못한 채! 이제 나는 존경받는 상인들과 경매인들의 웃음거리가 되어 나의 무능함을 낄낄대고 있습니다. $B$BPal, 이 사태를 해결하는 데 도움을 주실 수 있습니까? 나의 신뢰 계약자인 Grizzby는 어디에도 없고 나는 나의 귀중한 창조물을 잃어버릴 여유가 없습니다. 단서가 없으니 래칫에게 정보를 물어보는 게 좋을 것 같아요."},objectives={{90,1842935067},"불모의 땅에 있는 래칫으로 가서 그리즈비와 그의 화물이 어디에 있는지 물어보세요."},completion={{100,2128695296},"그리즈비? 아니요, 그는 적어도 보트를 타고 래칫을 떠나지 않았습니다. 하지만 그가 여기에 성공했다는 건 확실해요."}}
rows[41304]={title={{21,1791797598},"친구의 친구?"},description={{636,782924093},"저는 그리즈비를 오랫동안 알고 지냈어요. 사교적이고 친구도 많아요. 자연스럽게 직업과 함께 제공됩니다. 그가 여기 부두에 왔을 때 나는 물류로 바빴고, 다음 배가 오랫동안 나타나지 않을 것이기 때문에 우리는 잠시 이야기를 나눴습니다. $B$BWhile 우리는 단지 시간을 보내고 있었는데, 이 다른 고블린이 마치 오랫동안 잃었던 형제를 다시 만난 것처럼 그에게 다가왔습니다. 그리즈비도 자기를 잘 아는 것처럼 행동했으니 친했겠지. 나는 그들이 무슨 말을 하는지 잘 알지 못했지만, 어떤 이유로든 그들이 남쪽으로 갈 것이라는 말을 우연히 들었습니다. $B$BIt 시간이 좀 지났고 그리즈비에게 최악의 상황이 올까 두렵습니다. 그가 안전한지 확인해주세요."},objectives={{81,1995564419},"Grizzby를 찾은 후 Sparkwater Port에 있는 Tacknazz Copperfire로 돌아가세요."},progress={"$N, where have you been? Did you find my jewelry, and where did you leave Grizzby?","$N, 어디 있었어? 내 보석은 찾았고, 그리즈비는 어디에 두고 갔나요?"},completion={{460,1234328579},"<Tacknazz reads the contract you found on the goblin. The further he reads, the redder his green skin becomes.>$B$BOh, 저 중상모략을 하고 딱지를 갉아먹는 혈거인들이여! Venture Co.를 떠나는 것은 Nert가 할 수 있었던 최고의 일이었습니다. 나는 그들의 수상한 전술에 지쳤습니다. 소중한 보석을 모두 잃어버렸을 뿐만 아니라 최고의 계약자도 잃었습니다. 대체품을 찾는 데는 오랜 시간이 걸릴 것입니다! 오, 그리즈비, 이 늙은이, 넌 더 나은 대우를 받을 자격이 있어, 훨씬 더 나은..."}}
rows[41305]={title={{26,1800616128},"금은 고블린의 심장이다"},description={{869,1316158704},"나는 이 계약서를 Nert에게 개인적으로 가져갈 것입니다. 그는 우리의 이전 고용주가 Kezan에 대해 어떤 음모를 꾸미고 있는지 알아야 합니다. 할 수만 있다면 나는 언더마인으로 왈츠를 추고 그들의 무역왕을 가장 깊은 빈민가에 던져버릴 것입니다. 하지만 그럴 수 없기 때문에 지금 할 수 있는 일을 최선을 다해야 합니다. $B$BWith 보석을 도난당하고 소모품이 고갈되어 다음 경매를 위해 거의 아무것도 준비할 수 없으며 해당 경매에서 무언가를 제시해야 합니다. 그렇지 않으면 내 평판이 공식적으로 망할 것입니다. 당신은 교활하고 재능이 있는 것 같군요. 한 번 더 저를 도와주실 수 있으신가요?$B$BWhat 제가 필요한 것은 엄청난 크기의 보석입니다. 여기 스파크워터를 지나가는 여행자들이 붉은십자군이 주먹만한 루비를 갖고 있다는 소문을 퍼뜨렸습니다. 그들의 지도자가 그것을 가지고 있을 것이라고 추측하겠습니다. 게다가 루비를 꽂을 수 있는 간단한 금목걸이도요. 아무것도 당신이 스스로 땜질할 수 없어야합니다."},objectives={{77,1634617407},"Tacknazz는 붉은십자군 수도원에서 황금 목걸이와 거대한 루비가 필요합니다."},progress={"Be quick, $N! Creating masterpieces can't be rushed and the next auction is just a few days away!","서두르세요, $N! 걸작을 만드는 것은 서두를 수 없으며 다음 경매가 며칠 밖에 남지 않았습니다!"},completion={{451,2127100840},"아, 와! 이거 거의 내 코만큼 크네요! 그 모험가들이 거짓말을 한 것은 분명 아니다. 그리고 당신이 가져온 목걸이는 믿을 수 없을 정도로 훌륭하고 정말 인상적이었습니다. 내가 말했듯이 당신은 보석세공에 대한 별명을 가지고 있습니다. 정말로, 당신은 나를 엄청나게 도와주었습니다. 무법항의 유명 인사들이 이 아름다움에 침을 흘리게 될 것입니다. 조금만 기다리세요! 여러분의 노고와 도움에 감사하는 마음으로 제가 개인적으로 가장 좋아하는 디자인 중 하나를 여러분과 공유하겠습니다."}}
rows[41306]={title={{17,761991196},"이제는 모두 오우거다"},description={{890,1243479919},"나는 나쁜 운으로 커 즈 져, 나는 당신을 말할 것입니다. 당신은, 무역 경로의 주위에 모든 해적 roaming과 함께, 배를 통해화물을 보내는 것은 그 swashbucklers에 직접 연결하고 정상에 활에. 그래서 명확하게 옵션이 아닙니다. 다른 대안은 발에 의해 전달되고, 똑같은 위험, 당신은 확실히 내가 얘기하는 것을 알고있다.$B$B어느 방법, 나는 내가 정말로, REALLY, 내가 래치트에서 가장 intimidating ogre에 대해보고이화물을 전달하기 위해 필요한 후자 옵션을 선택하고 Steamwheedle Port로 내 길을 동반하기 위해 그를 지불. 너무 나쁜 우리는 그와 함께 ogre와 내 귀화물을 모두 가지고 undead zombie quilboar에 의해 구부렸습니다.$B$B나는 여기 desperate를 얻고있다. Razorfen Downs에서 내 물건을 검색 할 수 있습니까? 나는 그들이 내 가거 감시에있을 것이라는 것을 의심하지만 여전히 살아야한다, 그는 어디 있는지 알 것이다."},objectives={{56,27660671},"가시덩굴 구릉에서 트랙시스의 잃어버린 경호원을 찾으세요."},completion={{35,1764536016},"불쌍한 사흐리를 도우러 오셨나요?"}}
rows[41307]={title={{18,1884206819},"그들은 그것을 먹고 있어요!"},description={{560,1990540612},"Sah'rhee는 자신이 실패해서 너무 미안해요. 샤리는 작은 녹색 친구를 보호할 만큼 강하지 않았고 못된 가시멧돼지가 나를 여기로 데려갔습니다. 날 먹고 싶어하는데 엄마는 늘 사리가 너무 통통해서 맛이 없을 거라고 하더군요. $B$BIf 당신이 트랙시스의 상자를 찾고 있는데, 여기 있는데 불쌍한 사리가 더 빨리 걷기 위해 때렸을 때 돌이 모두 떨어졌습니다. 이제 무서운 좀비와 유령도 반짝이는 보석을 모두 갖고 있어요! Sah'rhee는 집에 가고 싶어합니다. Traxis의 보석을 모아서 Tanaris에 있는 작은 노움에게 가져다 줄 수 있나요? Traxis'는 해변 마을에서 상자를 기다리고 있다고 말했습니다!"},objectives={{101,879008072},"트랙시스의 사라진 화물을 모아 타나리스 스팀휘들 항구에 있는 그의 계약자에게 전달하세요."},progress={{48,1671776504},"<그럼은 당신에 attentio를 지불하지 않습니다.>"},completion={{267,678144267},"이것은 무엇입니까? Traxis의 배달? 나는 이것을 오랫동안 기다려왔다! 그 고블린과 그의 형편없는 서비스는 어쩌고? 어쨌든 작업을 마무리해주셔서 감사합니다. 만약 그 사람이 그렇게 독점적인 접촉을 하지 않았다면, 내가 그 사람에게 주문하는 것은 이번이 마지막이 될 것입니다."}}
rows[41308]={title={{15,2067756772},"수상한 관행"},description={{982,1716966195},"알았어, 내가 방금 말한 걸 취소해. 나는 그에게 다시는 주문하지 않을 것입니다. 이 보석들은 모두 부서지기 쉬운 표면을 가지고 있습니다! 어떻게 이런 일이 일어날 수 있었습니까? 그 사람은 그들에게 무엇을 했나요?$B$B<You explain to Fanzy how the jewels ended up in several undead stomachs and have been ruined by their bodily fluids.>$B$BUgh, 그렇게 자세히 설명할 필요는 없었어요. 역겨운. 글쎄, 이것은 완벽합니다. 이제 내 손에는 추가 작업이 있고 그것이 지금 내가 감당할 수 있는 마지막 일입니다. 하지만 다행히도 당신이 도와주러 왔습니다. 오, 그런 표정 짓지 마세요. Traxis 대신 돈을 지불하겠습니다. 조만간 여기에 그의 지저분한 머그잔을 보여주지 않는 것이 그의 최선의 이익입니다. $B$BTo 필요한 보석을 좀 더 강력하게 고쳐주세요. 일반 보석 오일로는 여기서는 잘 맞지 않습니다. 여기서 멀지 않은 남쪽에는 해변 근처에 작은 만이 있습니다. 그곳에서 내 사업 파트너를 찾을 수 있을 것입니다. 해안에 있는 강철턱 도미의 기름샘과 더 큰 신비한 정수, 수정 약병을 그에게 가져오십시오. 내가 당신을 보냈다고 그에게 말해주세요."},objectives={{130,1640505408},"Steamwheedle 항구 남쪽에 있는 Fanzy의 신비로운 파트너에게 8개의 Steeljaw 분비선, 상급 신비 정수 및 수정 약병을 가져가십시오."},progress={{34,553421631},"당신이 원하는 것은 무엇입니까, 랜드워커?"},completion={{170,289701933},"나는 감히 그 작은 존재를 파트너라고 부를 수는 없지만 우리는 귀중한 지식을 많이 공유하므로 그녀의 존재와 요청을 용인합니다. 말해 보세요, 오늘 그녀에게 필요한 것은 무엇입니까?"}}
rows[41309]={title={{18,885738369},"부서지기 쉬운 노움 더보기"},description={{456,1665828516},"<Zalashji squeezes the oily glands into the vial. Muttering unintelligible words under his raspy breath, he casts foreign magic, making the concoction glow in a vibrant light.>$B$BTake 그것, 낯선 사람. 이 오일은 보석 표면의 균열을 봉쇄하는 동시에 정확한 절단을 가능하게 합니다. 이제 가십시오. 나는 그녀가 나를 자주 방문하도록 허용하지만 당신에 대해서는 똑같이 말할 수 없습니다. 내가 내 형제들보다 더 친절할지 모르지만 그렇다고 내 인내심이 끝이 없다는 뜻은 아닙니다."},objectives={{78,943755058},"잘라쉬지의 보석 오일을 가지고 스팀휘들 항구에 있는 팬지 스파크스프링에게 돌아가세요."},progress={{13,1077178813},"그렇게 빨리 돌아오나요?"},completion={{644,957503255},"오오, 이제 물건입니다. 나는이 기적 혼합물과 Traxis의 메시를 살 수있는 권리를 말할 수 있습니다. Zalashji와 함께 왔습니까? 그는 슬픔입니다 ... 남자? 뱀? 나는 알지 못하지만 지금까지 그는 오랜 철학적 이야기를하지 않았다. 누가 알고, 어쩌면 나는 우리가 만난 방법을 알려 줄 것입니다!$B$B당신은 불쾌한 고객 직면을 막기 위해 나를 도왔습니다, 나를 보상을 하자. 나는 보석뿐만 아니라 보석에 숙련 된 것을 확신? 놀라지 마십시오, 나는 아무것도이 공예에서 마스터하지 않습니다. 그냥 지불으로 내 지식의 일부를 공유하십시오."}}
rows[41310]={title={{17,1273138112},"탄라르의 클러치"},description={{508,1778800019},"<그 책은 엉망의 나머지로 보이지 않는 것 같습니다. Kirin Tor의 sigil와 함께, 당신은 강력한 마우스에 속해야 가정.$B$B페이지를 통해 플립, 당신은 전에 듣고있는 카도라는 마법사의 저널이다. 전은 Guardian Medivh에 대한 견해와 Lothar의 아들의 회원, 누가 두 번째 전쟁 동안 Draenor에 대한 동맹의 공격을했다.$B$B다른 미스터리를 앓고있는 예상, 당신은 더 집중된 내용을 연구합니다.>"},objectives={{56,646867627},"카드가의 일지를 읽고 그 뒤에 숨겨진 수수께끼를 밝혀보세요."},progress={{37,783527974},"당신이 돌아왔습니다. 당신에게 필요한 것은 무엇입니까?"},completion={{202,1103677062},"카드가? 오랫동안 들어본 적이 없는 이름이자, 그가 이 세상을 떠난 후 다시는 들을 수 없을 것이라고 생각했던 이름. 그가 어디에 있든, 살아 있든 없든 그의 영혼이 자유롭고 흐려지지 않기를 바랍니다."}}
rows[41311]={title={{9,966264152},"보바르케즈"},description={{815,1089022516},"나는 아서스가 그의 악마 군주들의 명령에 따라 달라란을 포위했을 때 그곳에 있었습니다. 메네실이 메디브의 책을 훔치는 임무에서 극악무도한 행위를 저질렀을 때, 그의 군대는 우리가 금고에 보관하고 있던 다른 위험한 유물들을 도시에서 약탈했습니다. 마법의 도시를 처음부터 끝까지 지키면서 나는 파괴와 대혼란을 노리는 강력한 파멸의 수호자 앞에 섰습니다. $B$BIf 당신이 찾고 있는 것은 Thanlar의 클러치입니다. 그렇다면 Doomguard를 찾는 것이 당신이 해야 할 일입니다. 달라란이 함락된 후 내가 회복하는 동안, 살아남은 다른 마법사들은 아키몬드와 그의 군대의 다음 목표에 대해 논의했습니다. 그들은 세계수 놀드랏실을 쫓아 서쪽, 바로 이 땅으로 가는 것으로 밝혀졌습니다. 파멸의 수호자가 아직 아제로스에 있다면, 그는 하이잘 산 근처에 있는 악마가 득실거리는 심연에서 복수를 계획하고 있을 것입니다."},objectives={{134,1464691892},"돌반이 알려준 파멸의 수호자를 처치하고 탄라르의 클러치를 가지고 돌아오세요. 그는 테라모어 남쪽에 있는 그의 집에서 당신을 기다리고 있습니다."},progress={"Heed caution, $N. If the demon survived the Third War, then he cannot be underestimated.","조심하세요, $N. 만약 악마가 3차 대전쟁에서 살아남았다면, 그는 과소평가될 수 없습니다."},completion={{182,1757763300},"거의 저주처럼 클러치가 나에게 돌아오는 길을 찾았습니다. 당신이 어느 정도 무사히 돌아와서 가장 인상 깊었습니다. 당신의 힘은 위대한 영웅과 맞먹습니다. 클러치에 관해서는 $B$BNow..."}}
rows[41312]={title={{11,2146276696},"복원"},description={{913,598339889},"그 클러치가 달라란의 키린 토 보관소에 있었을 때 나는 그 형태와 기능, 목적을 광범위하게 연구했습니다. 메디브는 비밀스러운 유형이었지만 그의 마법 도구와 장신구에는 모두 비슷한 마법 표시가 새겨져 있습니다. Guardian에 익숙하지 않은 마법사라도 그것을 느낄 수 있습니다. 조사하는 동안 저는 클러치가 거대한 무언가의 일부이고, 결과적으로 더 큰 무언가의 일부라는 결론에 도달했습니다. 그 형태로 미루어 볼 때, 그 보물의 꼭대기에는 거대한 보석이 자리잡고 있었던 것 같습니다. $B$BShould 당신이 유령의 탑에 가다가 그런 보석을 발견한 적이 있다면, 나는 유물을 원래 상태로 복원할 수 있는 능력을 확신합니다. 하지만 그러기 위해서는 내 에너지를 집중시킬 수 있는 강력한 비전 집중이 필요합니다. 아제로스 마법의 수호자인 푸른용군단이 이러한 물체를 관리하고 있지만, 실제로는 가장 강력한 구성원만이 이를 가지고 다닙니다."},objectives={{180,2114511028},"유물을 수리하고 싶다면 돌반에게 필요한 부품과 고위 청룡에게서 비전 집중 장치를 가져오세요. 마법사는 테라모어 남쪽 해안선을 따라 찾을 수 있습니다."},progress={{125,1992688926},"어떤 사람들은 불가능한 노력이라고 말할 수도 있습니다. 하지만 당신의 능력을 보여주는 것만으로도 당신과 당신의 인내심에 대해 충분히 알 수 있습니다."},completion={{727,1238792133},"보석이 갈라졌나요? 궁금하지만 탑의 상태를 고려하면 예상치 못한 것은 아닙니다. 그런데도 그렇게 숨긴 채 메디브는 무슨 생각을 한 걸까? 그리고 이 초점은... 마법을 다스리는 용군단의 영원한 책임에 대한 증거입니다. 살아있는 필멸자가 에너지의 흐름을 증폭시키기 위해 그런 장치를 만들어낼 수 있을지 의심스럽습니다. $B$BIt는 씁쓸하고 달콤합니다. 나는 마법사로서의 삶을 포기했지만 두 번째로 당신을 돕는 것을 부인할 수 없습니다. 이제 오랫동안 잊혀졌던 마음속의 느낌이 빛나고 있습니다. 당신이 이 임무에 성공하는 것을 목격한 후에는 탑의 공포를 잠재우길 바라는 마음이 커집니다. 완성된 머리를 가져가고 탑에서 나머지 부분을 찾으세요. 가장 확실하게, 이것은 카라잔을 탐험하는 데 중추적인 역할을 할 것입니다."}}
rows[41313]={title={{21,1756959628},"수맥 조사"},description={{823,356598748},"이 땅에는 마법이 풍부합니다. 내 연구를 위해 나를 여기로 오게 된 수많은 이유가 있으며, 지구를 관통하는 수많은 지맥도 그중 하나입니다. 흐르는 흐름에서 강력한 비전 에너지가 쏟아져 나와 이 세계와 다른 세계의 마나에 굶주린 셀 수 없이 많은 주민들을 유혹합니다. 나는 왜 이 잊혀지고 저주받은 풍경이 그러한 현상의 본거지인지 더 명확하게 이해하고 싶습니다. 호기심이 눈에 들어오지 않습니다. 제 노력을 도와주실 건가요? $B$BOther 문제로 인해 제가 탑에서 바쁘게 지내고 있으니 나가서 저를 위해 시약을 좀 구해 주시면 그 노력에 대한 보상을 받게 될 것입니다. 나에게 필요한 것은 지맥 에너지의 결정화된 형태입니다. 내 학생들은 여기서 동쪽과 남쪽에 두 곳을 찾을 수 있었습니다. 내 생각엔 이곳에 사는 푸른 비룡과 타락한 블러드 엘프가 우리의 최고의 단서일 것 같아요. 그곳에서 검색을 시작하세요."},objectives={{73,1964785742},"아즈샤라에 있는 대마법사 실렘의 탑에 있는 대마법사 실렘의 지맥 수정을 수집하세요."},progress={{192,616062930},"메나르 호수는 비전 에너지의 중심지입니다. 푸른용군단이 그 위치에 모이는 이유는 그리 놀랍지 않습니다. 하지만 여기서 블러드 엘프들이 정확히 무엇을 하고 있는지는 알 수 없습니다."},completion={"Those appear positively unnatural. Ley line crystals materialize themselves on rare occasions when fleeting ley essence seeps through the earth, but these... Their formation appears different, almost forced, in a sense. Hm, peculiar...$B$B<Archmage Xylem ponders for a bit, while inspecting the crystals further. Suddenly an epiphany strikes him.>$B$B$N, there are many plausible explanations for this. But to confirm my own theory, I need to conduct some tests first. Will you assist me?","그것들은 확실히 부자연스러워 보입니다. 지맥 수정은 일시적인 지맥 정수가 땅에 스며들 때 드물게 구체화되지만... 그들의 형성은 어떤 의미에서는 다르게, 거의 강제적으로 나타나는 것처럼 보입니다. 흠, 특이하네요...$B$B<Archmage Xylem ponders for a bit, while inspecting the crystals further. Suddenly an epiphany strikes him.>$B$B$N, 이에 대한 그럴듯한 설명이 많이 있습니다. 하지만 내 이론을 확증하려면 먼저 몇 가지 테스트를 수행해야 합니다. 나를 도와주실 건가요?"}}
rows[41314]={title={{18,2079974255},"우려의 원인"},description={{1009,51066887},"이 두 수정은 모두 동일한 통합 구조를 갖고 있습니다. 주홍색 수정을 제외하고는 약간의 내 마법과 공명할 때...$B$B<Xylem channels a miniscule amount of his power into the red crystal and violent sparks and lightning emit from it.>$B$BListen, 우리가 작업하고 있는 사실은 다음과 같습니다. 푸른 용군단은 어떤 이유에서인지 아직 발견하지 못했지만 메나르 호수에서 지맥 수정을 수집합니다. 인위적으로 가속. 거주하는 블러드 엘프 역시 이 수정을 소유하고 있지만, 상태는 다르고 불안정한 상태입니다. 이 두 가지 상황이 연관되어 있는지 여부는 우리가 밝혀내야 합니다. $B$BI는 이 수정의 안정성을 계속 측정할 것이며, 당신이 나를 위해 귀중한 유물을 회수하는 동안 우리는 연구를 완료하는 데 필요합니다. 내 예전 학생은 그것을 내 탑에서 꺼내도 눈에 띄지 않을 것이라고 어리석게 생각했습니다. Sanath는 나에게 그녀가 Timbermaw Hold 근처의 동쪽으로 급히 떠났다고 알려주었고, 의심할 바 없이 그들과의 우호적인 관계를 이용하여 자신을 숨겼습니다."},objectives={{55,931223919},"수상한 학생에게서 실렘의 집중 구체를 회수하세요."},progress={{48,1237894284},"내가 찾고 있는 것을 되찾는 데 행운이 있었나요?"},completion={{521,216187315},"안타깝고, 우려스럽습니다. 앞으로는 견습생을 선택할 때 더욱 신중해야 합니다. Tharessa가 그렇게 무모하게 행동한 것이 당황스럽기 때문에 나는 그녀에게서 그런 행동을 기대하지 않았습니다. 물론 그녀의 열망은 분명했지만 나는 그것이 그녀의 권력이 아닌 지식 추구에 뿌리를 두고 있다고 생각하고 바랐습니다. 그녀의 밑에서 일한 사람이 누구이든, 나는 그들이 그들의 행동에 대해 정의를 내릴 수 있도록 할 것입니다. $B$BNonetheless, 포커스 오브를 다시 내 소유로 삼아 우리는 마침내 이 지맥 수수께끼의 밑바닥에 도달할 것입니다."}}
rows[41315]={title={{21,1920801460},"미스터리를 밝히다"},description={{491,1462624275},"포커스 오브가 반환되었으니 마지막으로 확신해야 할 것이 하나 있습니다. 여기 수정과 보주를 가져다가 내 탑 앞에 있는 받침대에 올려 놓으세요. 그러면 내가 구체에 걸었던 주문이 지맥 수정과 반응하여 - 바라건대 - 그 성질에 대한 내 이론이 확증될 것입니다. $B$BDon 두려워하지 마세요. 제가 이 탑 안에서 당신을 관찰하고 필요하다면 개입할 것이기 때문입니다. 당신의 능력이 있으니 너무 걱정할 필요는 없습니다. 하지만 잊지 마십시오. 주의는 현명한 사람의 생명선입니다."},objectives={{63,802332977},"최종 테스트를 수행하고 아즈샤라에 있는 대마법사 실렘에게 돌아가세요."},progress={{148,1429771416},"포커스 오브는 마법 에너지가 수정에 과부하가 걸리지 않도록 해줍니다. 그러므로 바로 근처에서 격렬하게 폭발할 수도 있다는 것을 두려워하지 마십시오."},completion={{965,1111123676},"확실히 뛰어납니다. 우리가 목격한 것은 내 의심이 옳았다는 것을 증명했습니다. 지맥 수정은 집중된 양의 마법에 노출되면 신비한 괴물로 나타나는 에너지의 통로 역할을 합니다. 자세히 살펴보면 두 수정 잔해가 동일하다는 것은 블러드 엘프가 푸른 용군단으로부터 수정을 얻은 후 자신들의 수정을 변경했다는 뜻입니다. 강제로 얻었는지 협력으로 얻었는지 대답할 수 없습니다. $B$BThanks 당신에게 이 땅과 그 주민들에 대한 이해가 다시 높아졌습니다. 하지만 푸른용군단이 그런 의심스러운 행동을 하고 있다는 사실은 걱정스럽습니다. 그들은 필멸자들의 일에는 거의 관심을 두지 않지만, 아제로스의 마법 남용을 즉시 중단하는 데는 주저하지 않습니다. 지금은 최선의 결과를 관찰하고 희망합시다. $B$BAs 귀하의 보상에 대해; 당신은 유능한 보석세공인이군요, 그렇죠? 그럼 사용자의 마법 능력을 증폭시키는 지팡이를 만드는 방법을 보여드리겠습니다."}}
rows[41316]={title={{43,888988978},"고급 보석세공 XI: 다이아몬드처럼 단단함"},description={{322,1690374308},"<이 책은 한 번 더 묶고, 이전 빈 커버는 제목과 마술으로 채우고있다 - 고급 보석 XI : 다이아몬드로 단단한. 그것을 열어보십시오, 당신은 강렬한 솔링 통증을 느낍니다. 보석 런은 잠금 씰링 볼륨에 나타납니다. 아마도 보석의 마스터는 비밀을 저술 할 수 있습니다.>"},objectives={{54,1971936192},"보석세공에 능숙한 사람에게 책을 가져가세요."},progress={{54,69264851},"아, 익숙한 얼굴이군요. 더 많은 훈련을 받기 위해 돌아오시나요?"},completion={{335,2060843187},"이 책...! 나는 그것에 대해 들었습니다! 그것은 상상할 수 있는 가장 정교한 주얼리를 위한 훌륭하게 제작된 디자인과 계획 시리즈의 마지막 작품입니다! 특히 이것은 아제로스의 다이아몬드로 극도로 강력한 장신구를 만들기 위한 복잡한 가이드를 다룹니다.$B$BNow 질문은 단 하나뿐입니다. 이 망할 것을 어떻게 열 수 있습니까?"}}
rows[41317]={title={{16,1502275292},"블레이즈의 룬"},description={{898,1872194760},"나는 평생 동안 이 전설적인 보석세공 백과사전을 연구해 왔습니다. 그들은 고대 사회의 잔재이자 오늘날 우리가 알고 있는 인류의 조상이라는 소문이 있습니다. 고고학자들은 점점 더 많은 유적을 발견하고 있습니다. 그들은 Azotha라고 불립니다. 지금까지 그들의 책 중 5권만이 발견되었으며, 그중 11권이 존재한다는 소문이 있습니다. 나의 지인은 고대인과 마찬가지로 실제로 하나를 열어서 나에게 말했습니다. 그는 책들이 아제로스의 정령들이 발화한 고대 단어인 정령 룬을 사용하여 봉인되어 있다고 말했습니다. 그 이후로 계속 조사해 왔는데 여기 이 자물쇠에 있는 불의 룬은 블레이즈의 룬인 것 같습니다. $B$BWe에는 그 룬에 맞춰진 정령의 조각이 필요합니다. 검은바위 산의 가장 깊은 동굴인 화산 심장부가 타오르는 정령들로 가득 차 있다는 소리를 들었습니다. 나는 그곳에서 우리에게 필요한 것을 찾을 가능성이 가장 높다고 믿습니다."},objectives={{126,1291121284},"스팀휘들 항구에 있는 팬지 스파크스프링을 위해 화산 심장부에서 블레이즈의 룬에 맞춰진 정령 조각을 구하세요."},progress={{87,1950142861},"진심으로, 나는 이 책에 담긴 달콤하고 달콤한 계획을 빨리 손에 넣고 싶습니다!"},completion={{495,932875311},"아야, 그거 정말 뜨겁다! 정말 얻기 힘든 일이셨을 텐데요, 다행히도 당신은 인생에서 더 힘든 면에 속해 계시죠? 이제 더 이상 기다리지 말고 이 아름다움을 열어보세요!$B$B<Fanzy moves the shard over the heavy lock and with a sizzling heat emanating from it, it cracks open, before falling into the sands. Enthusiastically, Fanzy immediately starts flipping throught the tome.>$B$BEmpty. 비어 있는. 비어 있는. 비어 있는! 두 페이지를 제외하고는 모든 것이 비어 있습니다! 나는 이것을 믿을 수 없다! 이건 일종의 역겨운 농담인가?!"}}
rows[41318]={title={{27,78334880},"장인이 만든 다이아몬드 왕관"},description={"Okay, we got to roll with the punches. Let's work with this page first and see what's written here... ‘To illuminate the scripture, present to me the hearts of earth and fire. Extracted heat will unveil the knowledge that you seek.” These Azotha sure love their riddles. I can only guess, but I believe this is a similar situation to what we had before. We can only unlock this grimoire's secret if we have the appropriate materials present.$B$BHearts of earth and fire... this must surely mean the fiery and lava cores of powerful elememals. Extracted heat... perhaps the essence of fire? Yes, this must be it!$B$B$N, you know what to do. I'll be waiting here for you to bring the needed materials and try to wrap my head around this ‘extraordinary' book.","좋아, 우리는 펀치를 굴려야 해. 먼저 이 페이지를 작업하고 여기에 쓰여진 내용을 살펴보겠습니다... '성경을 밝히기 위해 땅과 불의 마음을 나에게 제시하십시오. 추출된 열은 당신이 찾고 있는 지식을 드러낼 것입니다.” 이 Azotha는 확실히 수수께끼를 좋아합니다. 추측만 할 수 있지만, 이전에 겪었던 상황과 비슷한 상황이라고 생각합니다. 흙과 불의 적절한 재료가 있어야만 이 마법서의 비밀을 풀 수 있습니다. $B$BHearts 대지와 불... 이것은 분명히 강력한 원소의 불타오르는 용암 핵을 의미할 것입니다. 추출된 열... 어쩌면 불의 본질일까요? 예, 바로 이것이어야 합니다!$B$B$N, 당신은 무엇을 해야할지 알고 있습니다. 나는 여기서 당신이 필요한 자료를 가져와 이 '특별한' 책을 둘러볼 때까지 기다릴 것입니다."},objectives={{64,244224013},"스팀휘들 항구에 있는 팬지 스파크스프링에게 재료를 전달하세요."},progress={{73,120105488},"내 노움 같은 지성을 과소평가하지 마세요. 곧 코드를 해독하겠습니다!"},completion={{559,997944874},"물건 가져왔어? 좋습니다. 이제 우리의 이론을 테스트해 보는 것은 어떨까요?$B$B<Fanzy opens the page of the book and holds it high above her head. When brought near the empty page, the cores and essences liquify and transfer themselves to the parchment - ultimately forming sentences, completing the instruction for this piece of jewelry.>$B$BWOW! 정말 놀라운 일이었습니다. 이 책에 대해 제가 말한 내용을 취소하세요. 이 책은 꽤 훌륭하다는 점을 인정해야 합니다. 인크레더블님, 여기로 오세요. 이 페이지를 함께 샅샅이 살펴보겠습니다. 여러분의 헌신이 없었다면 우리는 여기까지 오지 못했을 것입니다!"}}
rows[41319]={title={{29,44171330},"장인이 만든 다이아몬드 팔찌"},description={{980,614919388},"더 많이 읽을수록, 아니 오히려 읽지 않을수록, 이 책에 관한 모든 수수께끼는 그저 빨리 돈을 벌려고 콧물 흘리는 고블린의 계략일 뿐이라는 생각이 더 커집니다. 보잘것없는 두 페이지에는 무언가가 적혀 있는데, 이 페이지에는 단 한 문장도 있습니다! '결정화된 혈액을 통해 태양을 전달합니다.' 그게 도대체 무슨 뜻이지... 잠깐! 나는 깨달음을 얻었습니다! $B$B<Fanzy is rummaging through her belongings and pulls out a blueprint.>$B$BThese는 내가 만들려고 온 적이 없는 주얼리 렌즈에 대한 계획입니다. 금속을 조각하는 데 사용되는 매우 강력한 광선으로 빛을 묶도록 설계되었습니다. 이를 위해서는 매우 구체적인 재료가 필요합니다. 이것이 바로 여러분이 플레이하는 부분입니다. '결정화된 피'란 검은바위 깊은 곳에서 발견되는 매우 찾기 어려운 산의 피를 의미하는 것이 틀림없습니다. 렌즈 프레임도 필요합니다. 검은바위 나락에 있는 파이너스 다크바이어는 산의 가장 강한 열기에도 견딜 수 있는 렌즈를 가지고 있다고 알려져 있습니다. 둘 다 가져오면 페이지를 해독하는 데 사용할 도구를 만들 수 있어요!"},objectives={{140,796416392},"스팀휘들 항구에 있는 팬지 스파크스프링을 만들려면 산의 피와 파이너스 다크바이어의 검은무쇠 탐사 렌즈가 필요합니다."},progress={{205,915986645},"제가 원래 이 앰프에 대해 구상했던 렌즈는 강렬한 열을 견딜 수 있도록 절단되지 않았습니다. 하지만 산의 피와 검은 철갑이 있다면 우리는 성공할 가능성이 높습니다."},completion={{608,1133218156},"훌륭한 작업입니다. 이 보석 중 하나를 손에 넣는 것 자체가 대단한 일입니다. 세 개를 얻기 위해 얼마나 많은 노력을 쏟았는지 상상할 수 없습니다! 좋아, 모든 것을 넘겨주고 이제 MASTERPIECE!$B$B<Fanzy snatches the materials and hastily moves her tiny hands. After a few minutes, she holds the delicate lens into the sunlight, directly in front of the empty page. Surprisingly, instead of burning it, the focused beam of light creates elaborate sentences on the formerly clear paper.>$B$BEUREKA를 만들고 싶은 기분이 듭니다! 완전한 성공! 우리 노동의 결실을 수확할 시간입니다! 여기로 오세요, 함께 읽어보시죠!"}}
rows[41320]={title={{16,1995030383},"내 과거에 대해 알아보세요"},description={{528,648989140},"내 뒤에는 위험한 여행이 있습니다, 낯선 사람. 세계를 초월하는 것; 응, 세상. 리프트워커는 고대 마법, 즉 아제로스에 없던 마법을 소유하고 있습니다. 이 예술을 수행하려면 많은 양의 에너지가 필요하며, 경험이 부족한 균열지기들은 이를 위해 종종 우리 고향 세계의 생명혈인 드레니시스트 수정을 활용합니다. 당신이 나를 찾아오도록 한 것은 Sanv K'la의 현명한 판단이었습니다. 나는 나의 고향인 드레노어.$B$BSit로의 여행에서 겪은 일로 충격을 받고 지쳤기 때문입니다. 그리고 내 말을 들어주십시오."},objectives={{29,1404853725},"Akh Z'ador의 이야기를 들어보세요."},progress={{34,270506003},"제발, 앉아서 편안하게 지내십시오."},completion={{308,25937302},"보시다시피, 제가 목격한 일은 하버리지에 있는 내 형제들에게 암울한 그림을 그려줍니다. 나는 안전을 찾아 그들을 이 세계로 이끌었고, 이제 우리의 과거가 다시 한 번 우리를 괴롭힐 위협을 하고 있습니다. 이를 막아야 하는데 혼자서는 할 수 없습니다. 친애하는 낯선 사람이여, 당신이 Sanv K'la를 도운 것처럼 나를 도와주시겠습니까?"}}
rows[41321]={title={{18,1954021017},"균열 피로: 정신"},description={{647,1867214834},"내 부족을 구하기 전에 나 자신과 내 소지품을 모두 준비해야 합니다. 균열걷기는 사용자의 마음에 큰 부담을 주며, 방해받은 균열걷기는 더욱 그렇습니다. 정신력이 회복되지 않으면 구조는 불가능합니다. $B$BMy 사람들은 생물의 뇌가 삼켜지면 정신 회복을 엄청나게 가속화할 수 있다는 사실을 발견했습니다. 짐승이 지능이 높을수록 기분이 더 빨리 새로워집니다. 해안 아래에서 나는 뱀 인간들이 이리저리 기어다니는 것을 보았고, 그들 중 일부는 스스로 주문을 시전했습니다. 이 주문 시전자들에게서 손상되지 않은 두뇌 몇 개를 가져오세요. $B$BLet 여러분 세계의 종족이 제가 상상하는 것만큼 똑똑하기를 바랍니다."},objectives={{73,1409036365},"Akh Z'ador의 '정신적 회복'을 위해 아즈샤라에 사이렌 두뇌 3개를 가져오세요."},progress={{49,382250295},"뇌를 맛본 지 오래되었습니다."},completion={"<Akh Z'ador takes the slimy, bloody brains and chomps them piece by piece. It is revolting to look at.>$B$BHm, a bit on the spongy side, but not disgusting. I've had worse, trust me. Thank you, $N, I can feel the mental weakness fading already.","<Akh Z'ador takes the slimy, bloody brains and chomps them piece by piece. It is revolting to look at.>$B$BHm, 약간 해면질 같은 면이 있지만 역겹지는 않습니다. 나는 더 나쁜 일을 겪었습니다. 나를 믿으십시오. 고마워요, $N, 벌써 정신적 약함이 사라지는 걸 느껴요."}}
rows[41322]={title={{18,1929393693},"균열 피로: 신체"},description={{733,746676022},"뒤틀린 황천의 흐름에 노출되는 것은 위험한 행위이며, 그 결과는 여전히 내 몸에 남아 있습니다. 드레나이는 오랜 균열 이동으로 인한 부작용에 맞서기 위해 세대를 거쳐 전해 내려오는 고대 조리법을 가지고 있습니다. 전통적인 재료를 구할 수는 없지만 이곳의 토착 야생동물은 대체 치료법을 만들기에 충분할 것이라고 확신합니다. $B$BWhen 나는 동쪽으로 이 지역을 정찰하러 나갔고 크고 살찐 발톱을 가진 위협적인 생물을 만났습니다. 그들의 살은 충분한 자양분을 가져다줄 것입니다. 실제로 멀지 않은 서쪽에서는 털복숭이 존재들이 강렬한 냄새가 나는 약초를 모으고 있습니다. 그 냄새로 판단해 보면 약효가 있는 것이 확실합니다. 둘 다 충분히 가져오시면 피곤한 몸을 위한 약을 요리해 드릴 수 있습니다."},objectives={{104,380126210},"아즈샤라의 아크 자도르(Akh Z'ador)는 서쪽에서는 펄볼그의 약초가 필요하고 동쪽에서는 마크루라의 살이 필요합니다."},progress={{153,1155575766},"우리 부족의 요리법을 많이 알고 있음에도 불구하고 나는 훌륭한 요리사가 아닙니다. Harbourage의 누구에게나 물어볼 수 있습니다. Noburo조차도 나보다 더 나은 요리사로 간주되었습니다!"},completion={{321,1783029215},"풍미와 매콤함 - 드레나이 요리의 전형적인 조합입니다. 활력을 되찾을 수 있도록 충분한 음식을 제공해 주셔서 감사합니다. 당신의 친절은 큰 도움이 됩니다. 드레노어의 재료로 준비한 우리 부족의 전통 식사로 보답하고 싶습니다. 하지만 여기서는 감상이 소용이 없습니다."}}
rows[41323]={title={{21,1250657924},"리프트워커의 지팡이"},description={{947,1543761543},"이제 활력을 되찾았으니 다음 단계는 내 가장 소중한 소유물인 균열지기 지팡이를 되찾는 것입니다. 내가 이 절벽의 적갈색 풀 위에 좌초되었을 때 나는 좌우로 광포한 생물들에게 둘러싸여 있었습니다. 그들 중 하나는 사악한 주술과 저주를 휘두르는 뿔 달린 악마였는데, 그들의 모습은 불타는 군단의 공포를 연상시켰습니다. 내가 무방비 상태로 땅바닥에 누워 있는 동안 그들은 마치 상처 입은 동물에게 내려오는 포식자처럼 나에게 다가왔습니다. 간신히 탈출할 수 있었던 나는 리프트워커 지팡이를 남겨두고 떠났습니다. 큰 사고로 인해 큰 상처를 입었습니다. $B$BRegardless, 설사 그것을 회수한다 하더라도, 나의 리프트워크 실패로 인해 그 장비는 고갈되고 쓸모없게 되었습니다. 금단의술 전문가가 전하는 힘의 메아리를 거기에 주입해야 합니다. 슬픔의 늪으로 돌아가면 물에 잠긴 사원이 천개 위로 우뚝 솟아 있습니다. 그 안에는 죽은 트롤과 용에 대한 권위를 행사하는 대가의 위쳐가 살고 있습니다. 성전과 늪에 대한 그의 영향력을 끝내십시오. 그리고 그분의 힘의 조각을 나에게 가져오십시오."},objectives={{92,484226566},"아크 자도르의 균열방랑자 지팡이와 잠말란의 모조를 가지고 아즈샤라에 있는 아크 자도르에게 돌아가십시오."},progress={{219,1119492974},"아제로스로의 탈출이 모든 악으로부터 우리를 보호할 것이라고 생각하는 것이 순진하지는 않지만, 타락의 온상이 우리의 새로운 고향의 중심에 있다는 사실에 낙담할 수는 없습니다."},completion={"My cane! I've only seen it this disheveled after we escaped Draenor years ago. Eternal gratitude to you, $N. And this… mojo, you call it? This swirling energy is completely foreign to me. Your world will probably never cease to bewilder me.$B$B<Akh Z'ador hits his chest with his fist in respect for your deeds.>","내 지팡이! 몇 년 전 드레노어를 탈출한 후에야 이렇게 흐트러진 모습을 본 적이 있습니다. $N님께 무한한 감사를 드립니다. 그리고 이건… 모조라고 부르나요? 이 소용돌이치는 에너지는 나에게 전혀 낯설다. 당신의 세계는 아마도 나를 계속 당황하게 만들 것입니다.$B$B<Akh Z'ador hits his chest with his fist in respect for your deeds.>"}}
rows[41324]={title={{23,1504394006},"불모의 땅에서의 초보자"},description={{713,1065386678},"지금은 이것이 여기서 할 수 있는 전부입니다. 내 리프트워커 지팡이를 이 새로운 힘에 맞추는 데는 우리가 가진 시간보다 더 오랜 시간이 걸리므로 계속 진행해 주시기 바랍니다. 내가 지팡이에 활력을 불어넣는 동안 당신은 슬픔의 늪 남쪽에 있는 황폐한 황무지인 저주받은 땅으로 가게 될 것입니다. 붉은 사막이 내려다보이는 언덕 꼭대기에서 나의 수습생 카스탈이 기다리고 있습니다. 나는 이 모든 일이 일어나기 전에 그에게 어둠의 문 근처의 의심스러운 변동을 조사하라고 명령했습니다. 그는 확실히 나에 대해 걱정하고 걱정하고 있으니 더 이상 내 안전을 두려워할 이유가 없다고 확신시켜 주십시오. $B$BOnce 당신이 그를 찾으면 내가 그와 당신을 하버리지에서 만날 것이라고 전해주세요. 그러면 우리는 일어나지 않을 모든 상황에 대비할 수 있습니다."},objectives={{56,183568751},"저주받은 땅에서 아크 자도르의 견습생을 찾으세요."},completion={{236,1339324897},"Akh Z'ador님이 당신을 보내신다고?! 정말 다행이네요! 나와 부족은 걱정이 되었고 이미 최악의 상황을 두려워하고 있었습니다. 절친한 친구, 신뢰할 수 있는 지도자, 자신과 같은 뛰어난 균열 워커를 잃는 것은 우리 중 누구에게도 감당하기 힘든 일이었을 것입니다."}}
rows[41325]={title={{19,1998476167},"저 너머에서 들려오는 메아리"},description={"Master did great by sending you to me. I am sure we can thank his clairvoyance for that, as I witnessed something truly frightening mere moments ago. You see to your right the abominable Dark Portal, legacy of the orcish invasion of your world? Master's suspicions regarding the portal's energy were true. Just before your arrival, a huge surge in power and a terrible, crushing force washed over the red sands of this desert. $B$BMy intuition tells me whatever lingers in front of it must be terrifyingly powerful. $N, please do not face it alone. Although the master has put your trust in you, what we are dealing with might very well be too much for you alone.","스승님이 당신을 보내주셔서 정말 잘했어요. 나는 불과 몇 분 전에 정말 무서운 일을 목격했기 때문에 그의 투시력에 감사할 수 있다고 확신합니다. 당신의 오른쪽에는 오크가 당신 세계를 침략한 유산인 혐오스러운 어둠의 문이 보이시나요? 포탈의 에너지에 대한 스승님의 의심은 사실이었습니다. 당신이 도착하기 직전에 엄청난 힘의 급증과 끔찍하고 파괴적인 힘이 이 사막의 붉은 모래를 덮쳤습니다. $B$BMy 직관은 그 앞에 남아 있는 모든 것이 끔찍할 정도로 강력할 것이라는 것을 말해줍니다. $N, 혼자 맞서지 마세요. 비록 주인이 당신을 신뢰했지만 우리가 다루고 있는 일은 당신 혼자에게는 너무 벅찬 일이 될 수도 있습니다."},objectives={{97,1177229650},"어둠의 문을 방해하는 모든 것에 맞서고 저주받은 땅이 내려다보이는 카스탈로 돌아가세요."},progress={{77,1250105144},"주의해서 진행하세요. 우리는 어떤 다른 세상의 공포가 우리를 기다리고 있을지 모릅니다."},completion={"A shadowed specter? And it spoke of the enslavement of the Sanv tribe and Akh Z'ador?! This is grim news, $R. For all our sakes, let me be wrong, but I fear the Harborage is in danger, grave danger!","그림자 유령? 그리고 그것은 Sanv 부족과 Akh Z'ador의 노예화에 대해 이야기하고 있습니까?! 암울한 소식입니다, $R. 우리 모두를 위해 제가 틀렸다고 생각합니다. 그러나 Harbourage가 위험에 처해 있다는 것이 두렵습니다. 심각한 위험입니다!"}}
rows[41326]={title={{21,282883823},"피난처의 운명"},description={"Quickly, rush to the Harborage and warn Sanv K'la! If we do not evacuate all in time, who knows what horrible tragedy will befall us! I will attempt to contact Master Akh Z'ador in the meantime, hopefully he can aid us sooner than anticipated. $R, I place all my hopes on you. Perhaps there is still time.","빨리 Harbourage로 달려가 Sanv K'la에게 경고하세요! 제 시간에 대피하지 않으면 우리에게 어떤 끔찍한 비극이 닥칠지 누가 알겠는가! 그동안 마스터 Akh Z'ador에게 연락을 시도하겠습니다. 그가 예상보다 빨리 우리를 도와줄 수 있기를 바랍니다. $R, 나는 당신에게 모든 희망을 걸었습니다. 아마도 아직 시간이 있을 것입니다."},objectives={{39,1947211861},"Sanv K'la에게 임박한 위험을 알립니다."},progress={"$N, you are restless. Tell me, could you find Akh Z'ador?","$N, 당신은 불안합니다. 말해 보세요. Akh Z'ador를 찾을 수 있나요?"},completion={{585,329140404},"나는 충격을 받았습니다. 심지어 가장 거친 꿈에서도 이런 일이 일어날 것이라고는 상상할 수 없었습니다. 한때 우리 부족의 족장이자 고귀한 지도자로서 나의 멘토였던 산브 타스달은 불타는 군단의 달콤한 거짓말에 굴복했습니다. 당신과 Akh Z'ador가 아니었다면 나와 내 백성은 그를 따라 드레노어로 돌아가 남은 생애를 군단의 계략을 위한 일벌레로 살았을 것입니다. $B$BThe 피난처는 영원히 당신에게 빚을 지고 있습니다. 여러분의 헌신에 대한 제 감사의 마음은 말로 다 표현할 수 없습니다. 부디 이 겸손한 성역의 모든 드레나이에게 감사의 상징을 전해 주십시오."}}
rows[41327]={title={{19,1889537726},"드러난 이상한 점"},description={{448,47637605},"해야 할 일이 많이 있습니다. Harbourage는 혼란에 빠졌고 많은 사람들이 부상을 입었습니다. 나는 내 형제들을 돌보아야 하므로 양해해 주시기 바랍니다. 도움을 주시면 감사하겠습니다. 지금은 이 문제를 우리에게 맡기겠습니다. 당신은 이미 할 만큼 했고 더 많은 것을 요구하는 것은 무례한 일이 될 것입니다. $B$BBefore 당신은 떠나지만 Akh Z'ador는 긴급한 일에 대해 당신과 다시 이야기하고 싶어합니다. 밖에서 그를 찾을 수 있습니다. Enkil Toralar, 친구여, 좋은 소식을 전합니다."},objectives={{39,1966260312},"항구에 있는 Akh Z'ador와 대화하세요."},completion={"$N, I thank you from the bottom of my heart for all you have done for the Harborage. Kas'tal managed to contact me just in time. Any later and I fear for what might've happened. Now, to what I wanted to talk with you about…$B$B<Akh Z'ador presents a flawlessly round and shimmering teal crystal to you unlike anything you've seen before.>$B$BWhat you see here is a pure draenethyst gemstone, one of the most rare commodities my people valued back on Draenor. Its status is akin to myth, although they are not the fairytale one might assume. Althoug it is just a theory, I assume this one was created between the clash of Tas'dal's and my own rift magic. I want you to have it, as thanks - but also as a promise. The draenei of the Harborage will aid you if needed, for without you, we'd be no more. Enkil Toralar, friend, and may the winds of the Twisting Nether be in your favor.","$N, Harbourage를 위해 해주신 모든 일에 진심으로 감사드립니다. Kas'tal은 제 시간에 맞춰 저에게 연락했습니다. 나중에 무슨 일이 일어났을지 두렵습니다. 자, 제가 얘기하고 싶은 것은… $B$B<Akh Z'ador presents a flawlessly round and shimmering teal crystal to you unlike anything you've seen before.>$B$BWhat 여기에 보이는 것은 순수한 드레노어 원석입니다. 드레노어에서 우리 종족이 높이 평가한 가장 희귀한 물품 중 하나입니다. 그 상태는 신화와 유사하지만, 동화 같은 것은 아닙니다. 이론일 뿐이지만, 타스달의 균열 마법과 내 균열 마법의 충돌이 만들어낸 것이라고 생각합니다. 나는 당신이 그것을 감사의 의미로, 또한 약속의 의미로 갖기를 바랍니다. 필요하다면 항구의 드레나이가 당신을 도울 것입니다. 당신이 없었다면 우리는 더 이상 존재하지 않을 것이기 때문입니다. 엔킬 토랄라, 친구여, 뒤틀린 황천의 바람이 당신에게 은총을 빕니다."}}
rows[41328]={title={{13,1814653287},"부탁을 받았어요"},description={"$N! A pleasure seeing you again. How have you been faring? We are still in the process of restoration, but the morale of most stays high. Some are still anxious of the uncertain future we might face.$B$BI have been looking into the pure draenethyst gemstone I gave you and I am certain I can reproduce one with the knowledge I gained from its creation. It will require an incredible amount of energy to replicate the process, but it will definitely be worth your efforts. Should you wish to have another gemstone, please bring me the following and I am more than happy to deliver it to you.","$N! 다시 만나서 반가워요. 잘 지내셨나요? 우리는 아직 복구 과정에 있지만 대부분의 사기는 여전히 높습니다. 어떤 사람들은 우리가 직면하게 될 불확실한 미래를 아직도 걱정하고 있습니다. $B$BI는 제가 당신에게 준 순수한 드레니시스트 보석을 조사해 왔고, 제가 그 보석을 만들면서 얻은 지식으로 그것을 재현할 수 있다고 확신합니다. 프로세스를 복제하려면 엄청난 양의 에너지가 필요하지만 확실히 노력할 가치가 있을 것입니다. 다른 보석을 갖고 싶으시다면 다음을 가져오시면 기꺼이 전달해 드리겠습니다."},objectives={{130,1746579420},"Akh Z'ador가 순수한 드레니시스트 보석을 만들려면 다음을 가져오십시오. 그는 슬픔의 늪의 피난처에서 기다리고 있습니다."},progress={{34,1368230790},"당신이 필요할 때마다 나는 여기에 있을 것입니다."},completion={{91,1235600129},"힘든 과정이지만 여기 있습니다. 또 다른 순수한 보석. 잘 관리해주세요."}}
rows[41329]={title={{21,1708750042},"모든 것을 럼주로 - 빛"},objectives={{46,1939558478},"'Ale Saint' Grida에게 럼지 럼 라이트 10개 가져가기"},progress={{529,3784971},"어이, 선장님! 새로운 레시피를 몰래 엿볼 수 있었죠? 에일은 내 마음에 더 가깝다는 것을 알고 있으며 언제든지 나머지 젊은이들에게 제공하게 되어 기쁩니다. 그리고 나는 당신도 그럴 것이라고 믿습니다. 이것은 우리를 진짜 문제인 cap'n.$B$BSee로 데려갑니다. 에일은 괜찮지만 젊은이들은 불안해지고 있습니다. 하루 종일 에일만 마시기에는 밖이 너무 따뜻해요! 그리고 우리가 술에 취하지 않고 일한다면 바다 마녀가 될 것입니다. 그러니 이 승무원의 선장으로서 당신은 책임을 져야 합니다! 바, 내 혀가 내 입 주위에서 너무 많이 춤추고 있습니다. $B$BWe에는 럼주 Cap'n이 필요합니다."},completion={{35,2082958300},"아, 이게 네가 얻을 수 있는 최선이었어?"}}
rows[41330]={title={{20,683429528},"모든 것을 럼주로 - 다크"},progress={{529,3784971},"어이, 선장님! 새로운 레시피를 몰래 엿볼 수 있었죠? 에일은 내 마음에 더 가깝다는 것을 알고 있으며 언제든지 나머지 젊은이들에게 제공하게 되어 기쁩니다. 그리고 나는 당신도 그럴 것이라고 믿습니다. 이것은 우리를 진짜 문제인 cap'n.$B$BSee로 데려갑니다. 에일은 괜찮지만 젊은이들은 불안해지고 있습니다. 하루 종일 에일만 마시기에는 밖이 너무 따뜻해요! 그리고 우리가 술에 취하지 않고 일한다면 바다 마녀가 될 것입니다. 그러니 이 승무원의 선장으로서 당신은 책임을 져야 합니다! 바, 내 혀가 내 입 주위에서 너무 많이 춤추고 있습니다. $B$BWe에는 럼주 Cap'n이 필요합니다."},completion={{61,1541854636},"그게 좋은 일이에요! 젊은이들은 이미 입술을 핥고 있습니다."}}
rows[41331]={title={{27,1529750320},"모든 것을 뒤흔들려면 - 블랙 라벨"},progress={{529,3784971},"어이, 선장님! 새로운 레시피를 몰래 엿볼 수 있었죠? 에일은 내 마음에 더 가깝다는 것을 알고 있으며 언제든지 나머지 젊은이들에게 제공하게 되어 기쁩니다. 그리고 나는 당신도 그럴 것이라고 믿습니다. 이것은 우리를 진짜 문제인 cap'n.$B$BSee로 데려갑니다. 에일은 괜찮지만 젊은이들은 불안해지고 있습니다. 하루 종일 에일만 마시기에는 밖이 너무 따뜻해요! 그리고 우리가 술에 취하지 않고 일한다면 바다 마녀가 될 것입니다. 그러니 이 승무원의 선장으로서 당신은 책임을 져야 합니다! 바, 내 혀가 내 입 주위에서 너무 많이 춤추고 있습니다. $B$BWe에는 럼주 Cap'n이 필요합니다."},completion={{105,1820257102},"오, 그거 어디서 났어? 해적왕의 식탁에서 건배하고 싶은 것! 하나 있었다면..."}}
rows[41332]={title={{24,1829255873},"모든 것을 뒤흔들려면 - 휘발성"},progress={{529,3784971},"어이, 선장님! 새로운 레시피를 몰래 엿볼 수 있었죠? 에일은 내 마음에 더 가깝다는 것을 알고 있으며 언제든지 나머지 젊은이들에게 제공하게 되어 기쁩니다. 그리고 나는 당신도 그럴 것이라고 믿습니다. 이것은 우리를 진짜 문제인 cap'n.$B$BSee로 데려갑니다. 에일은 괜찮지만 젊은이들은 불안해지고 있습니다. 하루 종일 에일만 마시기에는 밖이 너무 따뜻해요! 그리고 우리가 술에 취하지 않고 일한다면 바다 마녀가 될 것입니다. 그러니 이 승무원의 선장으로서 당신은 책임을 져야 합니다! 바, 내 혀가 내 입 주위에서 너무 많이 춤추고 있습니다. $B$BWe에는 럼주 Cap'n이 필요합니다."},completion={{67,608200435},"나에게 목재를 떨게 해주세요! 저주받은 것은 사이렌의 키스처럼 느껴집니다."}}
rows[41333]={title={{19,335430851},"고급보석학Ⅰ"},description={{241,503513387},"<손에 들고있는 책은 슬림하지만 놀랍게도 무거운 것입니다. 그 페이지를 검사하면 대부분의 내용이 당신의 이해를 넘어 있습니다. 아마도 누군가 다른 사람이이 공예의 주인은 토미와 함께 당신을 도울 수 있습니다.>"},objectives={{74,805565205},"보석학에 관한 책을 해당 전문 분야의 고대 대가에게 가져가세요."},progress={{68,1664346802},"<그런의 stony expression은 당신을보고에 기쁨을 끄는 것 같다.>"},completion={{301,1737499572},"<그런은 큰 관심을 가진 책을 시험하고 있습니다. 그가 아니한 동안, 테이블에 책을 두고 당신으로 켭니다. 속임수적으로, 당신은 무릎을 꿇고, 그의 피부의 거친 질감을 느끼기 전에. 지식의 큰 파도에서, 당신의 마음 안쪽에 정교한 지석 표정을 자르기의 지시.>"}}
rows[41334]={title={{20,991768646},"고급 보석학 II"},description={{241,503513387},"<손에 들고있는 책은 슬림하지만 놀랍게도 무거운 것입니다. 그 페이지를 검사하면 대부분의 내용이 당신의 이해를 넘어 있습니다. 아마도 누군가 다른 사람이이 공예의 주인은 토미와 함께 당신을 도울 수 있습니다.>"},objectives={{74,805565205},"보석학에 관한 책을 해당 전문 분야의 고대 대가에게 가져가세요."},progress={{68,1664346802},"<그런의 stony expression은 당신을보고에 기쁨을 끄는 것 같다.>"},completion={{293,1950616444},"<Thegren은 훌륭한 관심을 가진 책을 시험하고 있습니다. 그가 nods가 한 후, 테이블에 책을 놓고 당신으로 켭니다. 결국, 당신은 무릎을 꿇고, 그의 피부의 거친 질감을 느끼기 전에. 지식의 큰 파도에서, 당신의 마음 안쪽에 공중 토파사 표정의 지시.>"}}
rows[41335]={title={{23,1849920863},"고급 금세공 I"},description={{241,503513387},"<손에 들고있는 책은 슬림하지만 놀랍게도 무거운 것입니다. 그 페이지를 검사하면 대부분의 내용이 당신의 이해를 넘어 있습니다. 아마도 누군가 다른 사람이이 공예의 주인은 토미와 함께 당신을 도울 수 있습니다.>"},objectives={{74,805565205},"보석학에 관한 책을 해당 전문 분야의 고대 대가에게 가져가세요."},progress={"Oh, $N! A pleasure to see you again. Tell me, has time been treating you well?","아, $N! 다시 만나서 반가워요. 말해봐, 시간이 당신에게 잘 대해줬나요?"},completion={{260,1788900056},"독특한 책이라는 점을 인정해야 합니다. 내가 알지 못하는 고대의 인장이 새겨져 있습니다. 가장 흥미롭습니다... 어느 쪽이든, 이 책을 해독하는 것은 나에게 아무런 방해가 되지 않을 것입니다. 잠시만 기다려 주시면 해당 페이지에서 어떤 지식을 얻을 수 있는지 공유해 드리겠습니다."}}
rows[41336]={title={{18,1982715422},"보이지 않는 장애물"},description={{846,2085147237},"흠, 정말 이상해요. 여기 이 문장은... 룬이 하나 빠져 있어서 룬이 없으면 이 문장을 해독할 수 없습니다. 우리가 멈춘 것 같습니다. 그러나 내가 지금 포기한다고 생각하지 마십시오. 잃어버린 룬처럼 단순한 것은 전혀 겁이 나지 않습니다. $B$B<The Artificer grabs a small tool from his table, which appears to be a miniscule staff, and moves it along the sentences inside the book. After a short contemplation, he faces you once more.>$B$BI 잃어버린 룬을 어디서 얻을 수 있는지 알아보세요. 이 마법서가 본질적으로 마법적인 것처럼, 그 경전도 마찬가지입니다. 우리가 찾고 있는 룬은 스칼로맨스의 그늘진 전당에서 찾을 수 있는 유사한 효과의 대체물로 대체될 수 있습니다. 참으로 끔찍한 곳이라는 말을 들었습니다만, 그들의 사악한 연구는 우리 문제에 대한 해결책을 제시합니다. 그 강령술 교사 중 한 명에게서 이 형상이 담긴 룬을 구해서 나에게 가져오세요."},objectives={{77,1569067403},"잊혀진 땅의 기술병을 위해 스칼로맨스에서 대체 룬을 수집하세요."},progress={{143,1383126113},"걱정하지 마세요. 룬은 사용되는 상황에 따라 그 힘을 표현합니다. 그렇다고 해서 책이 무시무시한 악마를 소환하게 되는 것은 아닙니다."},completion={{383,97819787},"엘드레탈라스로 돌아가서, 우리는 아즈샤라 여왕의 명령에 따라 신비한 성소에서 이제는 오랫동안 잊혀진 셀 수 없이 많은 룬 문자를 연구했습니다. 그 중 많은 것들은 시간이 지나면서 잊어버렸고, 다른 것들은 부끄러워서 잊어버렸습니다. 그럼에도 불구하고, 지난 시대의 나의 지식은 우리에게 새로운 지혜, 즉 당신의 재량에 따라 사용할 수 있는 지혜를 얻을 수 있게 해 준 것 같습니다. 자, 잘 들어보세요. 이제 새로운 교훈을 배울 시간이다, 학생."}}
rows[41337]={title={{24,1821464694},"고급 금세공 II"},description={{241,503513387},"<손에 들고있는 책은 슬림하지만 놀랍게도 무거운 것입니다. 그 페이지를 검사하면 대부분의 내용이 당신의 이해를 넘어 있습니다. 아마도 누군가 다른 사람이이 공예의 주인은 토미와 함께 당신을 도울 수 있습니다.>"},objectives={{74,805565205},"보석학에 관한 책을 해당 전문 분야의 고대 대가에게 가져가세요."},progress={"Oh, $N! A pleasure to see you again. Tell me, has time been treating you well?","아, $N! 다시 만나서 반가워요. 말해봐, 시간이 당신에게 잘 대해줬나요?"},completion={{260,1788900056},"독특한 책이라는 점을 인정해야 합니다. 내가 알지 못하는 고대의 인장이 새겨져 있습니다. 가장 흥미롭습니다... 어느 쪽이든, 이 책을 해독하는 것은 나에게 아무런 방해가 되지 않을 것입니다. 잠시만 기다려 주시면 해당 페이지에서 어떤 지식을 얻을 수 있는지 공유해 드리겠습니다."}}
rows[41338]={title={{22,1590063903},"혼란에 빠진 하이잘 산"},description={"$C, news spread from atop the sacred Mount Hyjal. Our greatest fear, the Nightmare, has taken root and seeps once more into our realm. Many brave souls venture to the great World Tree to offer assistance to our brethren's cause to quell the Nightmare's influence.$B$B$N, I implore you to ascend Mount Hyjal and aid the Wardens of Nordanaar in their endeavors.","$C, 신성한 하이잘 산 꼭대기에서 소식이 퍼졌습니다. 우리의 가장 큰 두려움인 악몽이 뿌리를 내리고 다시 한 번 우리 영역에 스며들었습니다. 많은 용감한 영혼들이 악몽의 영향력을 진압하기 위해 우리 형제들의 대의를 돕기 위해 위대한 세계수로 모험을 떠납니다. $B$B$N, 저는 여러분이 하이잘 산에 올라가 노르다나르 감시자들의 노력을 도와주시길 간청합니다."},objectives={{66,865374704},"하이잘에 있는 세계수 놀드랏실 기슭에서 드루이드를 찾아보세요."},progress={{101,1706440269},"안녕하세요, 모험가님. 우리 세계의 지속적인 존재를 보장하기 위해 우리는 기꺼이 도와주려는 사람을 받아들입니다."},completion={{149,742368294},"Moonglade가 지원을 보내준다는 말은 듣기만 해도 든든하다, 젊은이여. 우리가 직면하고 있는 혼란은 우리 모두의 관심사여야 하는데, 그것을 무시하는 것은 위험한 일이 아닌가?"}}
rows[41339]={title={{16,1402784660},"그림자 유령"},description={"$N, while our kind fights in the waking world, Ysera and her allies, the Wild Gods of Old, keep the Nightmare - an unfathomable evil rooting itself in the Emerald Dream - at bay with all their strength and might. $B$BYears ago, during the Third War, Shan'do Stormrage and High Priestess Whisperwind convened with a powerful being at a sacred hill in the lower mountains of Hyjal. While usually radiating with the remnant energies of their encounter, we have noticed ripples of discord emanating from it throughout the mountain. Given the current situation, we best uncover what hides behind it posthaste.$B$B$N, seek that site near the Darkhollow Pass to the south and return to me with your findings.","$N, 우리 종족이 깨어 있는 세계에서 싸우는 동안 이세라와 그녀의 동맹인 고대 야생 신들은 에메랄드의 꿈에 뿌리를 둔 헤아릴 수 없는 악인 악몽을 온 힘을 다해 막아냅니다. $B$BYears 전, 3차 대전쟁 당시 샨도 스톰레이지와 대여사제 위스퍼윈드는 하이잘 낮은 산에 있는 신성한 언덕에서 강력한 존재와 함께 모였습니다. 보통 그들의 만남의 남은 에너지를 발산하는 동안, 우리는 산 전체에서 그것으로부터 뿜어져 나오는 불화의 파문을 발견했습니다. 현재 상황을 고려하면 그 뒤에 숨어 있는 것이 무엇인지 빨리 알아내는 것이 가장 좋습니다. $B$B$N, 남쪽에 있는 Darkhollow Pass 근처의 해당 장소를 찾아 발견한 내용을 가지고 나에게 돌아오십시오."},objectives={{98,147186003},"어둠공허 고개 근처의 소란을 조사하고 노르다나르에 있는 대드루이드 드림윈드에게 보고하십시오."},progress={{131,67828791},"야생과 조화를 이루지 못하는 사람들도 언덕에 잠재된 마법을 느낄 수 있습니다. 악당을 끌어들이는 것은 우리가 무시할 수 없는 것입니다."},completion={{124,1268310588},"유령이라고요? 흰 수사슴의 형태로요? 당신의 눈이 목격한 것이 사실이라면, 우리는 더 이상 방황할 수 없습니다!"}}
rows[41340]={title={{19,486087095},"세나리우스의 아들"},description={"There is only one being in the history of Azeroth that fits the description of what you experienced - the Wild God Malorne, the Waywatcher. He was ancient when this world was young, one of the primal guardians roaming the untamed wilds years before the Sundering. His immense power and prideful presence strikes fear into his enemies and comrades alike, yet his loving way of fostering nature made him revered with the latter.$B$BWhat you experienced is horrid. To think the Nightmare might have taken a hold on even a fragment of the great Malorne is terrifying. We must act immediately. $N, while I send notice to Moonglade, I need you to gather twenty bright dream shards. They are imperative to shield you against the Nightmare's grasp. Assist us in our cause, scour the hills of Hyjal. However you acquire them, do it quickly!$B$BOnce you have them all, bring them to Keeper Remulos in Moonglade. He will give you further instructions.","아제로스의 역사에서 당신이 경험한 것과 일치하는 존재는 야생 신 말로른, 즉 길감시자(Waywatcher) 단 한 명뿐입니다. 그는 이 세계가 젊었을 때 나이가 많았고, 세계의 분리가 일어나기 수년 전에 길들여지지 않은 야생을 배회하던 원시 수호자 중 한 명이었습니다. 그의 엄청난 힘과 자부심 넘치는 존재감은 적과 동료 모두에게 두려움을 불러일으키지만, 자연을 가꾸는 그의 사랑스러운 방식은 그를 후자에게 존경받게 만들었습니다. 당신이 경험한 $B$BWhat는 끔찍했습니다. 악몽이 위대한 말로른의 일부분이라도 사로잡았다고 생각하는 것은 끔찍합니다. 우리는 즉시 행동해야 합니다. $N, 제가 Moonglade에 통지를 보내는 동안, 빛나는 꿈의 조각 20개를 모아주세요. 악몽의 손아귀로부터 당신을 보호하는 데 꼭 필요합니다. 우리를 도와 하이잘 언덕을 샅샅이 뒤져보세요. 어떻게 얻든 빨리 처리하세요!$B$BOnce 모두 가지고 있으니 달숲에 있는 수호자 레물로스에게 가져가세요. 그는 당신에게 추가 지침을 줄 것입니다."},objectives={{64,1704489679},"달숲에 있는 수호자 레물로스에게 밝은 꿈 조각 20개를 가져가세요."},progress={"$N! Arch Druid Dreamwind informed me about what transpired on Mount Hyjal. Do you have the dream shards with you?","$N! 대드루이드 드림윈드가 하이잘 산에서 무슨 일이 일어났는지 알려줬어요. 당신은 꿈의 파편을 가지고 있나요?"},completion={"Well done, $C. Seeing you complete this task so quickly reassures me to not be doubtful of what I will be asking of you. You may be unaware, but my brethren and I are Malorne's scions. It was his union with the Moon Goddess Elune that bore life to our father Cenarius - and he in turn created us. This is not only a concern for the safety of Mount Hyjal or even to my family, but also to all of Azeroth.","잘했어요, $C. 당신이 이 작업을 매우 빨리 완료하는 것을 보면 내가 당신에게 무엇을 요구할지 의심하지 않을 수 있다는 확신이 듭니다. 당신은 모르실 수도 있지만, 나와 내 형제들은 말로른의 자손입니다. 우리 아버지 세나리우스에게 생명을 불어넣은 것은 바로 그가 달의 여신 엘룬과의 결합이었습니다. 그리고 그는 차례로 우리를 창조했습니다. 이는 하이잘 산이나 우리 가족의 안전뿐만 아니라 아제로스 전체의 안전에 대한 우려입니다."}}
rows[41341]={title={{17,2089526415},"묶인 추억"},description={{987,1010908531},"말로른은 악몽에 빠질 수 없습니다. 다행스럽게도 악몽이 장악한 에메랄드의 꿈에서는 자신의 영혼이 그의 영혼에서 분리되어 나온 것으로 보입니다. 하지만 웨이와처의 일부분만으로도 이미 우리를 상대로 한 이 전쟁에서 극복할 수 없는 이점을 얻기에 충분합니다. 할아버지의 이 오염을 정화하려면 할아버지의 친족을 생각나게 하는 유물이 필요합니다. $B$BThe 세나리우스의 가지는 우리 아버지의 뿔 조각입니다. 그가 잿빛 골짜기에 쓰러진 후, 우리는 그의 시신을 가지 그림자로 가져간 뒤 달숲으로 돌려보내 매장했습니다. 아마도 그곳의 용혈족 사이에서 찾을 수 있을 것입니다. $B$BYsera는 말로른의 소중한 친구이자 우리 아버지의 양어머니입니다. 그녀의 비늘 피부가 우리 대의에 확실히 도움이 될 것입니다. 그녀가 가장 사랑하는 아이들은 모두 하나를 소유하고 있습니다. 불행하게도 그들 대부분은 엘룬의 추억인 에메랄드의 꿈.$B$BLastly에 살고 있습니다. 그녀가 선택한 수호자인 달빛야수는 여명의 설원에 그녀의 많은 유물을 보관하고 있으며 그곳에서 그것들을 찾고 있습니다."},objectives={{57,657739004},"달숲에 있는 수호자 레물로스에게 필요한 유물을 수집하세요."},progress={{104,2060261057},"자연에 대한 사랑과 보살핌이 우리가 아는 것보다 우선하는 말로른과 같은 고귀한 존재는 보호되어야 합니다."},completion={{369,974656692},"이 강력한 장신구를 보면 당신과 같은 필멸자들은 이 세상에 존재하는 힘을 떠올릴 수 있습니다. 그것이 사람의 이해를 넘어서는 것일 수도 있지만, 이 모든 것에서 당신의 역할을 과소평가하지 마십시오. 필멸자들은 아제로스의 운명을 바꾸는 데 중요한 역할을 한다는 사실을 거듭해서 입증해 왔습니다. 당신이 하는 모든 일은 즉각적이든 궁극적이든 그에 따른 결과를 낳습니다."}}
rows[41342]={title={{14,1214243841},"더 화이트 스태그"},description={{452,1649635823},"자, 젊은이여, 당신이 나에게 가져온 유물과 꿈의 파편에서 창조된 이 기억의 홀을 가져가십시오. 이를 사용하면 말로른의 파편을 손아귀에서 떼어낼 수 있을 만큼 오랫동안 악몽을 견딜 수 있습니다.$B$BNevertheless, 조심하세요. 악몽이 먹이를 그렇게 쉽게 버릴지는 의심스럽습니다. 동맹국과 같은 생각을 가진 사람들을 모아 할아버지의 영혼을 구하십시오. $B$BMake 서둘러, 할아버지가 우리 세상에 모습을 드러내지 않도록 하세요."},objectives={{92,1190420572},"하이잘에 있는 예언자의 언덕에 있는 소멸하는 망령을 정화하고 수호자 레물로스에게 돌아가세요."},progress={{69,911629981},"걱정하지 마세요. 모든 힘을 다해 악몽의 영향력을 물리치세요."},completion={{632,1123274918},"끝났습니다. 당신의 용감한 행동을 듣고 내 마음을 무겁게 짓누른 두려움은 사라지고 있습니다. 나는 에메랄드의 꿈을 응시하는 능력을 사용하여 이 조각을 할아버지께 돌려드리겠습니다. 그것을 쥐고 있는 것만으로도 그의 찬란하고 강력한 아우라를 다시 한 번 느낄 수 있습니다. $B$BIt가 완전한 힘을 회복하는 데는 상당한 시간이 걸릴 것이지만, 이세라와 그의 동료 야생 신들은 그의 곁에서 사랑하는 친구이자 멘토를 보호하고 있습니다. $B$BYour 흰 사슴과 그의 유산에 대한 헌신은 칭찬할 만합니다. 당신의 영웅적이고 비이기적인 본성을 기리기 위해 말로른의 사슴 형태 자체로 전환하는 방법을 가르쳐 드리겠습니다."}}
rows[41343]={title={{11,2088839285},"나는 쥐가 아니다"},description={"$R, here? Please, no kill. No kill Big Whiskers! Big Whiskers here by mistake. Big Whiskers called by weird see through human. Big Whiskers just want leave. But Big Whiskers can’t leave. No. Big Whiskers first needs BIG CANDLE!$B$BBig candle very important to Big Whiserks and his friends. Yes, yes. Big Whiskers give reward, reward, yes! Bring Big Whiskers big candle. Please?$B$BAsk Doorman, Doorman must know!","$R, 여기요? 제발, 죽이지 마세요. 큰 수염을 죽이지 마세요! 실수로 큰 수염이 여기에 있습니다. 인간이 꿰뚫어보는 이상한 괴물이라고 불리는 큰 수염. 빅 위스커스는 그냥 떠나고 싶어해요. 하지만 빅 위스커스는 떠날 수 없습니다. 아니요. Big Whiskers에는 먼저 BIG CANDLE이 필요합니다. $B$BBig 양초는 Big Whiserks와 그의 친구들에게 매우 중요합니다. 예, 그렇습니다. 큰 수염은 보상을 줍니다, 보상, 예! Big Whiskers에 큰 양초를 가져오세요. 제발?$B$BAsk 도어맨, 도어맨은 꼭 알아야 해요!"},objectives={{50,1037751492},"카라잔 하층 전당에 있는 도어맨 몬티그와 대화하세요."},progress={{16,1012490992},"메이지 뭔데?"},completion={{45,1121007839},"코믹하게 큰 양초. 당신은 농담꾼입니까?"}}
rows[41344]={title={{22,1209020439},"코믹하게 큰 양초"},description={{724,1349783593},"귀하의 요청을 숙고하는 동안 저는 웃음으로 응답해야 할지, 아니면 귀하의 정신 상태에 대해 걱정해야 할지 알 수 없는 불확실성에 빠져 있습니다. 이 상당한 규모에 대한 귀하의 요구 사항은 석사 도서관 내에서 어떤 종류의 실험에 대한 암시를 주는 거대하고 촛대를 의미합니다. $B$BWith 귀하가 달성하려는 모든 작업에 필요한 양초의 크기와 해당 장소에 대한 의심스러운 접근 수단을 설명하는 것에 대해 나는 갈등을 느낀다는 것을 인정합니다. 그럼에도 불구하고, 나는 당신에게서 뿜어져 나오는 뚜렷한 힘의 기운을 느끼며, 그 신비한 홀을 탐색할 수 있는 힘이 당신에게 있다고 믿게 만듭니다. $B$BHaving가 그렇게 말하면서, 나는 손님 홀 끝에 놓여 있던 상당한 크기의 촛불을 기억하는 것 같습니다."},objectives={{94,601448078},"그리시키일에게서 우스꽝스러울 정도로 큰 양초를 회수하고 카라잔 상층에 있는 큰 수염꾼에게 돌아가야 합니다."},progress={{17,1900840199},"큰 촛불은 어디에 있나요?"},completion={{132,1977411096},"큰 수염을 위한 큰 양초! 이 무서운 곳에서의 나의 임무는 끝났다. Big Whiskers가 감사의 뜻으로 이것을 드립니다. 아주 재미있는 책이에요, 보세요!"}}
rows[41345]={title={{24,1598691816},"고대 악의 제단"},progress={{210,25859708},"초보적인 제단은 원시적이고 불안한 기운을 발산합니다. 옆에 누워 있는 트롤은 그것이 어떤 힘을 가지고 있는지 암울하게 보여줄 수도 있습니다. 그래도 그 거친 표면에도 뭔가 제물을 바칠 수 있을 것 같군요..."},completion={{90,1308733672},"바다가 요동치고 공포의 물결이 아즈샤라를 덮칩니다. 바다에서 뭔가가 튀어나와요!"}}
rows[41346]={title={{15,1222783654},"이끼 낀 미스터리"},progress={{351,1590422741},"이 오래된 상자는 동굴 내부와 거의 매끄럽게 조화를 이루고 있습니다. 자물쇠 꼭대기에는 문자 'G'가 새겨져 있습니다. 그 옆에는 너덜너덜한 책, 아니 오히려 남아 있는 책. 얼른 훑어보면 이 상자가 여기 섬에 살았던 누군가의 것이었을 것이라고 짐작할 수 있습니다. 읽을 수 있는 마지막 항목에는 오늘 식사로 생선을 구하는 것에 대한 내용이 나와 있습니다."},completion={{207,1334554668},"상자가 열리고 젖은 냄새가 빠져나갑니다. 안에서는 녹슨 장신구 몇 개와 놀라울 정도로 흠집 하나 없이 부서진 무언가를 발견합니다. 그것을 집어들면 그로부터 오는 위험감을 느낍니다. 마음 아픈."}}
rows[41347]={title={{12,1412727974},"잃어버린 시간"},description={{988,1720844072},"나는 헤아릴 수 없을 정도로 지루하다. 내가 묶여 있는 이 영원한 연옥은 당신이 생각하는 것만큼 고통스럽진 않지만, 오히려 지독할 정도로 지루하다. 나는 더 이상 세상의 즐거움을 경험할 수 없으며, 보석을 착용할 수 없기 때문에 보석에 대한 나의 사랑도 줄어들었습니다. 그럼에도 불구하고, 내가 가장 좋아하는 장신구는 더 이상 내 손에 있지 않은 것 같습니다. $B$BWhen 메디브의 초대를 받았는데, 내 소지품 중에는 보석과 원석이 잔뜩 있었습니다. 무엇보다도 가장 귀중한 목걸이는 헤아릴 수 없을 만큼 가치가 있으며 순수한 아제로스 다이아몬드로 섬세한 아케이나이트 사슬로 장식되어 있습니다. 이 유령의 홀에서 일생 동안 소유했던 그 어떤 손님들보다 더 가치가 있습니다. 아, 내가 죽는 순간에만 그것을 몸에 지니고 있었다면 나는 아직도 그 아름다움을 간직할 수 있었을 것이다. 아아, 그것은 당신이 살고 있는 시간보다 몇 년 전에 도난당했습니다. 마지막으로 본 것은 스톰윈드에 있는 내 영지를 떠나기 전이었습니다. $B$BLiving 하나, 내 보물을 찾는 데 도움을 주시면 메디브가 직접 하사한 보석으로 보상해 드리겠습니다."},objectives={{113,1257889137},"틸리아 얼웨이크 백작부인은 훔친 목걸이를 찾고 있습니다. 그녀가 그것을 마지막으로 본 것은 스톰윈드 시티에 있는 자신의 사유지였습니다."},completion={{208,342921452},"<The blind drunkard is visibly intoxicated. Hiccups and burps are the only signs showing he is still with you. It appears he is almost at death's door.>$B$BWhaddya 원하시나요?! 내가 여기서 좀 바쁜 거 안보여?!"}}
rows[41348]={title={{16,1813089695},"얼웨이크는 이제 그만"},description={{956,1449997747},"이 잉카 부동산을 찾고 계십니까? 저를 웃지 마십시오. 즉, 잉카 장소가 아무것도 아니지만 기억이없고, 지상 년 전에 태우고, 모든 꿈과 희망이 있습니다. 무엇 ya가 전에 볼 것은 모든 것은 Earlwake 이름의 왼쪽입니다 -이 병리적, 실패의 무자 더미. $B$B<구로 burp가 그를 탈출하고 구토는 다음과 같은 정장, 그의 이미 더러운 셔츠에 떨어 뜨립니다.>$B$B우리는 모든 것을 잃었다! 그들은 우리의 treasury을 잃고 집 내부에 사람을 살았다. 심지어 ... 심지어 내 beloved Georgina... 그녀의 거짓말을, 평생을 보았... 다이아몬드 목걸이 나는 그녀를 위해 훔쳐, 여전히 빛나는 ... 그것은 짐승, 그 orc는 그녀를 찢어 졌지만 나는 여전히 그것을 볼 수 있습니다 ... 내 머리! 그가 웃고 그의 전장, 그 Doomhammer을 숭배! 나는 결코 잊지 않을 것입니다, 나는 그 몬스터를 잊지 않을 것입니다! 나는 그들을 맹세하지 않을 것입니다, 나는 그들을 맹세하지 않을 것입니다, 나는 그들을 맹세하지 않을 것입니다!$B$B내가 원해, 나는 그것을 가지고 있지 않습니다, 저 질문을 중지! 내 물고기를 떠나!"},objectives={{139,2086760247},"리드가 고갈되고 Archibald는 도움이 되지 않습니다. 하지만 아마도 그가 제공한 오크에 대한 설명이 틸리아의 목걸이를 찾는 데 도움이 될 수 있을 것입니다."},completion={{80,529059042},"<이 글은 희망이 밝히기 때문에이 글은 어떤 것도 수확하지 않습니다.>"}}
rows[41349]={title={{21,711579442},"로데론에서의 손실"},description={{123,322832527},"<Luckily, 당신은 금이 struck에 나타납니다. 이 orc의 저널의 페이지는 당신이 추구하는 목걸이에 대한 정보를 포함합니다.>"},objectives={{45,1787337189},"저널을 분석하고 검색을 계속하세요."},progress={{137,1535867714},"<먼저는 거의 장소 중 의심스러운 모습이 보인다. 과거의 반향은 시간과 필사자 손이 닿지 않는 한 시간의 통행에 의해 숨겨져있다.>"},completion={{414,921462588},"<분간의 몇 분 후에 먼지를 돌리고, 골격을 맞습니다. tusks에서 버려, 그들은 오해 남아 있습니다. 두 가지 것들은 관심을 잡습니다. 목걸이, 그의 저널에 설명 된 한 Gorak과 동일합니다. 이것은 그의 동료 Melar가되어야합니다. 슬러지게 Tillia의 목걸이가 아닙니다. 다른 것은 당신이 발견하는 것은 파괴 된 칼, 깨진, 시간 또는 전투에서 삼촌이되는지 여부입니다.>"}}
rows[41350]={title={{16,1117215106},"소드 마스터"},description={{446,1999948896},"검을 살펴보면, 겉보기에 낡은 상태 외에는 평범하지 않은 점을 발견할 수 없습니다. 칼날은 부서지기 쉽고 녹슬었고, 칼자루의 가죽은 손으로 만지면 부서집니다. 포멜은 놀랍도록 손상되지 않았으며 가장자리를 따라 섬세한 조각이 새겨져 있습니다. H. C. 그 위에 초승달 안에 로데론 엠블럼이 보입니다. 어쩌면 이 사람이 검의 주인일 수도 있다. 행운이 당신 편이라면 그 사람도 목걸이를 갖고 있을 것입니다."},objectives={{33,1993998067},"H.C를 찾아보세요. 로데론 어딘가에 있을 겁니다."},progress={{164,1868094188},"당신을 위해 단조된 훌륭한 칼날을 갖고 싶나요? 실망하게 될까봐 두렵습니다. 나의 대장간 시절은 끝났습니다. 오랫동안 잊혀진 이 장소에 대한 기억만이 지금의 나의 전부입니다."},completion={{164,612589193},"이 검은 내 의식 속에 깊이 새겨져 있어, 내가 원하더라도 잊을 수 없는 것이다. 시간이 허락하신다면 제가 가장 훌륭한 학생의 이야기를 들려드리겠습니다."}}
rows[41351]={title={{19,1998756153},"일격에 죽음"},description={"The broken blade you bring before me belonged to Razuv Ivaldi, one of Lordaeron's strongest knights. His sword alone fell more orcs than any other soldier on the fateful day of Lordaeron's siege, as he cut them down in one fell strike. $B$BFollowing the days after the invaders were repelled, he was heralded as a champion, as it was him who stopped that absolutely vicious orc woman who cut her way through our troops like butter. As a trophy of her death, he took a beautiful diamond necklace from her - one that the zealously held on to, proclaiming it to be the testament of his greatest achievement.$B$BHe was a good man and friend, but his obsession with that pendant and its meaning consumed him. The last I saw of him was at his return with the traitor Menethil, when he as one of his fellow death knights thrust his tainted runeblade into me. $N, I beg of you, find him and put his troubled spirit to rest. Please, do it in his master's stead.","당신이 내 앞에 가져온 부러진 검은 로데론의 가장 강력한 기사 중 한 명인 라주브 이발디의 것이었습니다. 그의 검만으로도 로데론이 포위된 운명적인 날에 다른 병사들보다 더 많은 오크를 쓰러뜨렸고, 한 번의 일격으로 그들을 베어넘겼습니다. $B$BFollowing 침략자들이 격퇴된 지 며칠 후, 그는 우리 군대를 버터처럼 뚫고 지나가던 그 절대적으로 사악한 오크 여인을 막은 사람으로서 챔피언으로 선포되었습니다. 그녀의 죽음에 대한 트로피로 그는 그녀에게서 아름다운 다이아몬드 목걸이를 가져갔고, 이 목걸이는 자신의 가장 위대한 업적의 증거라고 선언하며 열심히 간직했습니다. $B$BHe는 좋은 남자이자 친구였지만, 그 펜던트와 그 의미에 대한 집착이 그를 사로잡았습니다. 내가 그를 마지막으로 본 것은 배신자 메네실과 함께 돌아왔을 때였습니다. 그 때 그는 동료 죽음의 기사 중 한 명으로서 오염된 룬검을 나에게 찔렀습니다. $N, 그를 찾아 그의 불안한 영혼을 쉬게 해주세요. 부디 그의 주인을 대신하여 행하여 주십시오."},objectives={{113,69776165},"Razuv Ivaldi를 찾아 Tillia의 목걸이를 가져 가십시오. 하층 카라잔 전당의 오페라에서 그녀에게 그것을 돌려주십시오."},progress={"$N! A pleasure to see you. Say, has your search been fruitful?","$N! 만나서 반가워요. 검색 결과가 유익했나요?"},completion={{676,633166439},"<Tillia is speechless at the task you accomplished. Marveling at her long lost treasure, she regains her composure and begins speaking.>$B$BIncredible, 정말 놀랍습니다! 당신은 아주 짧은 시간에 이 10년간의 수수께끼를 해결하는 뛰어난 탐정입니다. 내가 내 영지로 돌아간다면 내 동생이 당신을 우리 개인 수행원으로 초대할 것입니다. 하지만 슬프게도 세상의 스릴이 당신을 부르고 있다고 믿습니다. 반면에 나의 죽음은 나를 이곳에 묶습니다. 하지만 너무 걱정하지 마세요. 목걸이를 돌려받으면 이 끝없는 지옥 같은 경멸을 견딜 수 있습니다. $B$BAs 약속대로, 당신은 탑의 군주인 수호자 메디브가 직접 만든 소중한 루비 반지를 받게 될 것입니다."}}
rows[41352]={title={{13,1342810957},"틸리아 아줌마"},description={{228,1782618237},"<손에 행하고 보상으로, 당신은 당신이 사용할 수없는 비싼 황금 반지로 왼쪽. 이 기술적으로 귀에 가족의 재산으로보고, 당신은 Archibald가 자신의 디어 상황에서 이것을 받아 들일 경우 ponder.>"},objectives={{64,66069444},"스톰윈드 항구에 있는 아치볼드 얼웨이크에게 황금반지를 가져가야 합니다."},progress={{100,1923791221},"<He appears to be somewhat sober compared to the last time you met.>$B$BWho 거기 간다?! 내가 당신을 알고 있나요?"},completion={{540,906712451},"이 반지는... 틸리아 이모가 준 거야? 아니, 그럴 리가 없어. 아줌마는 자신의 보석과 결코 헤어지지 않았으며, 그녀가 가장 소중히 여기는 것들만 선물로 받았습니다. 그 말은...? 그녀가 가장 아끼는 목걸이를 훔친 뒤에도... 낯선 사람, 그런데 이걸 어떻게 얻었나요?! 틸리아는 수십 년 전 수호자의 저주받은 탑으로 여행을 가던 중 실종되었습니다. $B$BIt는 상관이 없습니다. 싸구려를 가지고 가십시오. 어느 쪽이든 난 끝났어, 비싼 반지가 나에게 무슨 소용이 있겠어? 팔고, 입어도 상관없어요. 나를 비참하게 내버려두세요."}}
rows[41353]={title={{17,1481986485},"추운 밤이다"},description={{712,114958530},"한 번의 터치로 자수정은 당신의 눈을 영원히 사로잡을 수 있는 희미한 빛으로 빛나기 시작합니다.  그러나 당신의 마음을 사로잡은 것은 그 아름다움이 아니었습니다. 머릿속에 목소리가 울린다. 당신의 것이 아닌 것. 엄숙하면서도 부드러운 어조로 울려퍼집니다:$B$B\"너는 이 점을 더 깊이 생각해야 한다. 켈테릴로 돌아가서 내 앞에서 위안을 찾으라. 저 탑은 예측할 수 없고 그것이 기도하는 지맥은 순전히 혼란스럽다. 더 이상 속이지 마라, 친구. 다른 방법이 있다!\"$B$BThe 자수정이 빛난다 더 이상. 그리고 터치할 때마다 동일한 메시지를 말하게 됩니다. 당신이 우연히 발견한 이상한 아이템입니다. 아마도 켈테릴 호수를 탐험하면 일종의 답을 얻을 수 있을 것입니다."},objectives={{52,1836692392},"마법에 걸린 자수정의 신비를 조사하세요."},progress={{50,465443391},"나를 내 자신에게 맡기십시오. 여기에는 아무것도 없습니다."},completion={{76,350826810},"엘룬으로. 그 물건을 당신 손에 가져온 것은 우연이 아니었던 것 같아요."}}
rows[41354]={title={{20,1293460735},"달에 안겨"},description={{745,1987170094},"자수정이 마법을 잃어가고 있는 것 같습니다. 나는 그것이 작동하는 방식에 대해 의문을 제기하지 말라고 요청하고 싶습니다. 내 집이었던 이 집과 함께 죽어야 할 비밀입니다. $B$BAlas, 켈테릴에 오신 것을 환영합니다. 한때는 바라볼 수 있는 도시였지만, 이제는 나와 내 동족의 괴로워하는 영혼들의 고향입니다. 나는 당신이 왜 나를 찾았는지 모르겠습니다. 인칸타고스를 죽인 것이 죄인지 의심스럽습니다. $B$B<Al'Dorel sighs.>$B$BA 아버지를 기쁘게 하려고 애쓰는 어리석은 아들. 그러나 나 아니면 당신이 누구기에 그분의 길을 판단할 수 있겠습니까? 당신이 찾는 것이 답이라면 나를 도와야만 찾을 수 있을 것입니다. 호의에는 또 다른 호의가 있어야 하기 때문이다. 근처에 머물고 있는 명가들은 안식을 취해야 합니다. 호수 건너편에는 목적 없이 표류하는 모습이 보입니다. 그들을 풀어주면 감사를 표할 것입니다."},objectives={{85,789565297},"알도렐을 위해 켈테릴에 있는 고통받는 명가의 영혼을 구출하십시오."},progress={{51,859437603},"고통스럽든 괴로워하든 당신은 그들을 인도해야 합니다."},completion={{49,1393975112},"믿거나 말거나, 당신은 큰 친절을 베풀었습니다."}}
rows[41355]={title={{21,1140240975},"그리고 별들에게 길을 잃었다"},description={{901,2119603032},"인칸타고스는 불안정한 수맥과 그곳에 남아 있는 강렬한 힘을 찾아 탑을 찾았습니다. 인칸타고스는 푸른용군단에서 자신의 이름을 알리고 아제로스에 큰 충격을 가하는 목적을 달성하려고 했습니다. 그는 말리고스를 직접 만나려고 했으나 할레는 아직 만날 때가 아니라고 믿었기 때문에 그의 권리를 거부했습니다. $B$BI는 이유를 잘 모르겠습니다. 사실, 블루가 한때 동맹이라고 불렀던 사람들에게도 다소 공격적이 되기 시작하면서 나는 블루의 행동에 대해 날마다 의문을 갖기 시작했습니다. 폐허가 된 내 집에서 웜킨을 호스팅할 때도 있었습니다. 그런 시대가 지나고 이제 그들이 나에게 신성한 것을 훔쳐갔다는 것은 슬픈 일입니다. $B$BBefore 당신은 인칸타고스의 선택에 대해 더 많이 알게 되었으니 이 아이템을 나에게 돌려주십시오. 마법의 수정으로 하늘 너머를 볼 수 있는 깨끗한 달에서 단조된 망원경. $B$BThey 남동쪽의 마즈소릴 내부로 가져갔어야 했습니다."},objectives={{45,129086962},"마법의 망원경을 알도렐에게 다시 가져가세요."},progress={{60,1230228128},"당신의 탐구는 성과가 있었나요, 아니면 아직 임무를 완수하지 못했나요?"},completion={{72,651911084},"가장 소중한 물건입니다. 한때 강력했던 이 도시의 마지막 유물 중 하나입니다."}}
rows[41356]={title={{17,1111783311},"눈 속에서 잠들다"},description={{754,1250808127},"인칸타고스가 동부 왕국으로 떠나기 전에 나는 그에게 조언을 하려고 노력했습니다. 나는 진정으로 블루의 친구였기 때문이다. 나는 그가 추구하는 지맥은 불안정할 뿐이며 블루인 그조차도 그것을 진정으로 활용할 수 없다고 말했습니다. 아아, 나조차도, 심지어 위대한 수호자조차도 진정으로 그럴 수는 없었습니다. $B$BBefore 그는 떠났고, Frostwhisper Gorge에서 쉬기로 결정했습니다. 그는 내가 생각할 수 없는 이유 때문에 자이언츠 사이에서 위안을 찾았습니다. 드래곤은 깊은 잠에 빠지면 탈출합니다. 이 땅을 배회하는 요소들을 뒤흔들 수 있는 동안 배회하는 거인의 죽음을 찾으십시오. 우리에게는 이 저울이 필요합니다. 왜냐하면 그들이 우리에게 더 많은 것을 말해 줄 수 있기 때문입니다. $B$BDo 흔들리지 마세요, 친구. 아마도 당신은 나의 이러한 일이 무의미하다고 생각할 것입니다. 하지만 장담하는데, 이는 우리가 확인하지 않고 방치할 수 있는 문제가 아닙니다."},objectives={{43,1428701598},"알도렐에게 온전한 하늘빛 비늘 6개를 가져옵니다."},progress={{93,1677811457},"나는 당신이 이 거인보다 더 강한 적과 용감하게 맞서 싸웠다는 것을 느낍니다. 추가 협의가 필요한지 의심스럽습니다."},completion={{125,418325294},"당신은 다시 한 번 당신의 임무를 완수하는 데 성공했습니다. 당신이 떠난 친척이 무엇이든 그들이 당신을 생각할 때 자부심을 느끼기를 바랍니다."}}
rows[41357]={title={{14,850169519},"적의 누워"},description={{931,331374599},"친구 좀 보세요. 이 깨끗한 비늘은 한때 하늘색 톤에 감싸여 빛났습니다. 그러나 이제는 생명이 없는 형태로 인해 청금석의 원시 조각과 더욱 유사해졌습니다. 나는 당신에게 악의를 품고 있지 않습니다. 걱정하지 마십시오. 나는 단지 인칸타고스가 그의 죽음을 맞이한 것을 후회할 뿐입니다. 내가 조금만 더 빨랐다면 아마도 그는 살았을 것입니다. $B$BRegardless, 아직 진실에 가까워지지 않은 것 같습니다. 나는 이것이 두려웠다. 인칸타고스가 사라지면서 이 비늘의 마법도 사라진 지 오래입니다. 우리는 잠시 그들에게 생명을 돌려줄 수 있었습니다. 하지만 그렇게 하려면 다른 청룡의 생명을 빨아들이거나 그와 비슷한 일을 해야 합니다. $B$BI 당신이 다시 한 번 동쪽으로 여행하게 되어서 두렵습니다, 친구. 현재 남아있는 가장 큰 인간 왕국의 지하 감옥에서 당신은 그것을 찾을 수 있습니다. 그 비열한 창조물. 그가 무슨 이유로 그렇게 했는지 나는 결코 이해할 수 없습니다. 살아있는 아크티라스의 파편을 찾으세요. 그 중심에는 말리고스의 정수인 블루의 마법이 담겨 있습니다."},objectives={{44,1393784520},"아크티라스의 핵을 알도렐에게 다시 가져가세요"},progress={{34,1306796828},"그 물건은 파괴되는 편이 낫습니다."},completion={{371,1362466667},"모든 위대한 비전술사처럼 말리고스는 지식과 실험에 대한 갈증을 갖고 있습니다. 그는 노스렌드의 얼음에 자신의 마나를 주입했습니다. 아마도 정령이 탄생한 \"원시\" 장소에 가장 가까운 것이 무엇이든 될 것입니다. 즉, 그의 어리석은 실험은 좋게 끝나지 않았다. 보시다시피 그것은 정령처럼 보이지 않았습니다. 그러나 차갑고 무자비한 죽음의 수단."}}
rows[41358]={title={{17,1175519120},"일출에 깨어"},description={{807,2063964945},"이 물건들을 모아서 마침내 우리 둘 다 찾고 있는 답을 찾을 수 있었습니다. 잠시 시간을 내어 주문을 시전해 보세요. $B$B<Al'Dorel hums under his breath with his eyes closed.>$B$BThis는 받아들이기가 다소 어렵습니다. 어떻게 반응해야 할지 잘 모르겠습니다. 나-피할 가치가 없다고 생각합니다. 아리고스는 블루가 아제로스의 필멸 종족을 비전에 합당하지 않다고 여기기 때문에 탑의 지맥을 찾았습니다. 말리고스 본인도 준비하고 있는 것 같은데... 전쟁도 아니고 전투라고 부르지도 않을 것 같아요. $B$BWould 개미는 당신의 발을 전쟁이나 전투의 선언으로 본다? 아니면 순수한 근절. 모두가 이것이 올바른 길이라고 믿는지 나는 알아야 합니다. 저는 이곳을 떠날 수 없으니 제발 부탁드립니다. 저를 대신해서 할레와 통화해 주세요. 그녀는 칼림도어의 무리어미입니다. 그녀는 Mazthoril 꼭대기에 있으며 내부에는 그녀에게 접근하는 데 사용할 수 있는 룬이 있습니다."},objectives={{92,670523821},"여명의 설원에서 알도렐이 밝혀낸 진실에 대해 마즈소릴 꼭대기에 있는 할레와 대화하세요."},progress={{21,2090234471},"무슨 일로 여기까지 왔나요?"},completion={{81,2073746542},"정당한 우려입니다. 설명할 필요는 없지만 알도렐은 다르다고 생각합니다."}}
rows[41359]={title={{26,1767801039},"희미한 빛을 통해"},description={{1027,863973815},"그래서 인칸타고스는 죽었습니다. 알도렐이 당신을 보내지 않았다면 나는 말보다는 이빨을 사용했을 것입니다. 아아, 예상치 못한 일이 다시 한 번 Blue의 아이를 데려간 것 같습니다. $B$BIt는 모두 진정한 필멸자입니다. 우리는 필멸의 종족들에게서 비전을 빼앗을 준비가 되어 있습니다. 감히 의문을 제기하지 마시기를 바랍니다. 당신들의 어리석음이 대분열, 저주받은 불타는 군단, 그리고 그에 따른 모든 것을 가져왔을 뿐만 아니라. 다른 세계로 통하는 포털? 백만 번도 넘게 피를 흘린 위대한 업적입니다. $B$BAs 이 세계의 수호자 여러분, 우리는 비전에 대한 접근을 제한해야 합니다. 그러나 여러분 모두는 매우 자신감이 넘쳤고 오히려 강력해졌습니다. 최초의 마법사들을 가르친 바로 그 사람인 말리고스 경은 당신이 더 이상 이 책임을 맡을 자격이 없다고 결정했습니다. 아제로스는 치유할 수 있고, 새로운 종족이 탄생할 수 있습니다. $B$BSometimes 빈 캔버스가 문제를 해결하는 가장 좋은 방법입니다. 이것을 경고로 받아들이고 Incantagos의 결말에 참여한 사람에 대해 아직 약간의 동정심이 남아 있으므로 떠나십시오. 알도렐에게 그 사람만이 안전할 것이라고 전해주세요."},objectives={{18,1235293177},"알도렐에게 돌아가기"},progress={{10,1645490606},"무슨 소식이요?"},completion={{140,545622503},"나- 나는 그녀의 말에 어느 정도 동의해야 하는 것이 두렵습니다. 그러나 그러한 증오를 품고 전체 인종에 대한 대량 학살을 조장하는 것입니까? 내 마음이 가라 앉는다."}}
rows[41360]={title={{15,296626117},"날이 따뜻해"},description={{700,1488895065},"인칸타고스는 그의 탐구에 혼자가 아닌 것 같습니다. 그들은 어떻게 그토록 눈이 멀고 무자비할 수 있었습니까? 그들은 이것이 그들이 가야 할 길이 아니라는 것을 이해해야 합니다. 그래야 해요!$B$B<Al'Dorel sighs.>$B$BSo 거기 있어요, 친구. 공유한다고 해도 누구도 믿지 않을 진실. 우리가 할 수 있는 건 – 사는 것뿐이다. 이 추운 땅에서도 태양의 따뜻함을 느껴보세요. 종말과 죽음에 대한 약속이 우리가 오늘을 사는 것을 결코 방해해서는 안 됩니다. 걱정하지 마세요. 나는 블루의 친구였던 만큼. 나도 준비가 되어 있고 여러분도 준비되어 있을 것입니다. $B$BA 우리가 다시 한 번 서로의 얼굴을 볼 날이 올 것입니다. 가능한 한 오래도록 기도하겠습니다. 그때까지. 자, 우리가 오랫동안 잃어버린 인생에서 얻은 증표를 당신에게 주고 싶습니다."},objectives={{17,1918094380},"선물을 수락하세요."},progress={{49,113243933},"좀 더 좋은 환경에서 만났더라면 좋았을 텐데요."},completion={{389,1166233220},"나는 친구라고 불리는 사람과 싸워야 할 날이 두렵습니다. Alas.$B$BKel'theril은 다른 많은 귀족 정착지와 마찬가지로 마법으로 가득 차 있었습니다. 오랜 세월에 걸쳐 사라진 ​​마법 – 나는 아직 도망치지 못한 이 땅의 마지막 생존자입니다. 호수가 내 집을 삼킨 이후로 나는 이러한 용의 유물을 갖고 있었습니다. 하나를 가져가세요. 이제 당신의 것입니다. 나를 생각나게 하는 것. 다시 만날 때까지."}}
rows[41361]={title={{14,1682018433},"빛나는 피"},description={{334,1673087946},"<불확한 증기는 그것을 열심히 보고, 그러나 당신이 simmering 배경에 발견한 것은 진동하는 결정, 접촉에 확장입니다. 그것의 가치를 엄청난 높일 것이기 때문에, 당신은 보석에 일하고, 제대로 돌을 잘라내기 위하여 기술을 부족하는 것을 시도하지 않습니다. 그것은 당신이 그런 기술을 가르치는 누군가를 찾아내는 것을 필요로 합니다.>"},objectives={{54,1068824653},"끓는 보석에 대해 가르쳐 줄 사람을 찾으세요."},progress={{47,1248252530},"낯선 사람, 당신이 여기 있는 데에는 합당한 이유가 있는 게 좋을 것 같아요."},completion={{239,176107385},"산의 피! 타우릿산의 충성파들이 검은바위 안팎의 모든 채굴 작업을 장악한 이후로 그 아름다운 보석 중 하나를 손에 넣는 것은 정말 어려웠습니다. 그리고 이건 특별한 종류인 것 같은데..."}}
rows[41362]={title={{14,676995546},"마음을 자르려면"},description={{400,1491757712},"당신의 가정은 정확합니다. 내가 직접 산의 피를 자르는 방법을 가르쳐 드릴 수 있습니다. 하지만 그렇게 하려면 내가 접근할 수 없는 시약 세트가 필요합니다. 이 창고는 많을지 모르지만 타우릿산이 계획하고 있는 모든 계략 때문에 좋은 물건이 고갈되고 있습니다. $B$BHere, 이 재료를 나에게 가져오시면 산의 피를 자르는 오래된 검은무쇠 기술을 기꺼이 보여 드리겠습니다."},objectives={{103,1120973574},"록토스 다크바게이너에게 필요한 재료를 가져오세요. 그는 검은바위 나락에 있는 음울한 술꾼에서 기다리고 있습니다."},progress={{206,1871848146},"검은무쇠 부족은 산의 육체를 지배한다는 자부심을 가지고 있습니다. 검은무쇠 광석과 그 표면에서 발견되는 셀 수 없이 많은 독특한 보석을 조작하는 데 있어서 그토록 전문적인 기술을 보여준 사람은 거의 없습니다."},completion={"I appreciate the effort, $N. This was definitely not an easy task, yet you provided me with such quality materials in no time at all.$B$BGemstones like the Blood of the Mountain require an extraordinary amount of precision and patience. Just the tiniest bit of unnecessary pressure and the entire jewel cracks in two. Watch closely, for I have only one chance to teach you. You can keep the gemstone once I'm done. See it as thanks for bringing me such a peculiar example of a gem.","노력에 감사드립니다, $N. 이것은 분명 쉬운 일이 아니었지만, 제게 이렇게 좋은 재료를 단시간에 제공해 주셨네요. $B$BGemstones 산의 피와 같은 작업에는 엄청난 정확성과 인내가 필요합니다. 아주 작은 힘이라도 불필요한 압력을 가하면 보석 전체가 둘로 갈라집니다. 자세히 살펴보세요. 제가 당신을 가르칠 기회는 단 한 번뿐입니다. 내가 일을 마치면 보석을 가져가셔도 됩니다. 이렇게 특이한 보석의 예를 보여주셔서 감사하다고 생각하세요."}}
rows[41363]={title={{13,1429231518},"만연한 잡초"},description={{734,833067360},"당신은 이미 제 디스크 알란 닌자와 함께 살 수 있습니다, 그녀는 그 부상을 조사하기 위해 자신을 촬영하고있다 Wailing Caverns에서 충돌, Ashenvale의 Barrens 남쪽의 동굴의 커즈드 미로.$B$B이 식물은 식물의 재배에 영향을 미치는 영향을 나타내는 것입니다. 이 식물은 식물의 재배에 영향을 미치는 영향을 나타내는 것으로 알려져 있습니다. 이 식물은 식물의 재배에 영향을 미치는 영향을 나타내는 것입니다. 이 식물은 식물의 재배에 영향을 미치는 영향을 나타내는 것입니다. 이 식물은 식물의 재배에 대한 영향을 줄이기 위해 식물의 재배에 대한 영향을 최소화합니다.$B$BWailing Caverns 내에서 찾을 수있는 가장 폭력 식물의 충분한 샘플을 가져와서 보상을 받게됩니다."},objectives={{99,641194065},"아우버다인에 있는 툰드리스 윈드위버는 통곡의 동굴에 있는 기이한 과성장의 샘플이 필요합니다."},progress={{111,1070808347},"조심하세요. 이 악몽의 소굴은 매우 위험할 뿐만 아니라 호드 영토를 통과하는 여정도 매우 위험합니다."},completion={"Intriguing. These samples radiate a magic not unfamiliar to me, on first glance I'd even say they emanate druidic magic. Ofcourse, I shouldn't jump to conclusions. Further research within the Cenarion Circle will be needed. Surely their venerable druids can solve the origin of their volatile growth.$B$B$N, you have my appreciation. Please, take one of these as compensation for your troubles.","흥미롭다. 이 샘플은 나에게 낯설지 않은 마법을 발산합니다. 언뜻 보기에 드루이드 마법이 발산된다고 말할 수도 있습니다. 물론 성급하게 결론을 내리면 안 됩니다. 세나리온 의회 내에서 추가 연구가 필요할 것입니다. 확실히 그들의 존경받는 드루이드라면 그들의 변덕스러운 성장의 근원을 해결할 수 있을 것입니다. $B$B$N, 감사합니다. 당신의 문제에 대한 보상으로 이것들 중 하나를 가져가세요."}}
rows[41364]={title={{19,1665063456},"언데드를 지키기 위해"},description={"Hail $N. Still looking for more work? I have a report that needs to reach Duke Nargelas in Glenshire.$BFret not, you won't be delivering it to his hands personally. All you must do is give this scroll to Deathguard Markus, he should be stationed right outside the church Duke Nargelas haunts.$B$BIt simply to let them know we've decided to send adventurers into the Shadowfang Keep. Arugal mustn't be left alive. Getting to Glenshire shouldn't be that hard. You can either follow the path north or you can go back to Tirisfal Glades and reach it by traversing the Solliden Farmstead. Up to you.","$N 만세. 아직도 더 많은 일자리를 찾고 계신가요? Glenshire에 있는 Duke Nargelas에게 전달해야 할 보고서가 있습니다. $B$BFret 아니요, 직접 그의 손에 전달하지는 않을 것입니다. 당신이 해야 할 일은 이 두루마리를 죽음경비병 마르쿠스에게 주는 것뿐입니다. 그는 나겔라스 공작이 자주 출몰하는 교회 바로 바깥에 주둔해야 합니다. $B$BIt는 우리가 모험가들을 그림자송곳니 성채로 보내기로 결정했다는 사실을 그들에게 알리기 위한 것입니다. 아루갈을 살려두어서는 안 됩니다. 글렌셔(Glenshire)에 가는 것이 그렇게 어렵지는 않을 것입니다. 북쪽 길을 따라가거나 티리스팔 숲으로 돌아가 솔리덴 농장을 가로질러 도달할 수 있습니다. 당신한테 달렸습니다."},objectives={{52,458064392},"글렌셔에 있는 죽음경비병 마르쿠스에게 보고서를 가져가십시오."},progress={{28,1930758824},"우리는 여주인의 명령을 따릅니다."},completion={{115,1498883210},"그래서 Shadowfang Keep은 곧 습격당할 것입니다. 좋은. 당신이 여기 있는 동안 나한테 부탁 하나라도 해도 괜찮겠죠?"}}
rows[41365]={title={{17,1017504488},"Brightcopf를 돕기 위해"},description={{992,2028378638},"글렌셔에는 빛을 숭배하는 사람이 많지 않았지만 당시 우리 모두는 빛 가운데 태어났다고 믿었던 것이 분명합니다. 우리는 우리 땅을 안전하게 지키는 데 더 집중했습니다. 지금도 우리는 어둠의 재탄생 덕분에 다시 한 번 걸을 수 있게 된 만큼, 나의 충성은 이 곳 사람들에게 있다. 나는 살아서 공작을 지키지 못했으나 죽어서도 그렇게 하지 않을 것입니다. $B$BMy 야망은 차치하더라도, 내 요청에 대한 정당성을 표현하는 것이 필수적이었습니다. 브라이트코프 신부님은 과거에 눈부신 빛 속에서 우리를 인도하셨고, 지금은 우리가 그림자 속으로 기어가도록 돕고 계십니다. 그는 자신의 필요보다 포세이큰의 필요를 먼저 생각하며, 살아 있을 때 보여준 것과 똑같은 사심 없음을 죽음에서도 보여줍니다. 이곳의 $B$BNorth는 로데론 잔당의 마지막 캠프입니다. 우리의 제단 소년인 윌리엄 일병이 그들 사이를 걷고 있습니다. 우리는 그를 죽이기 위해 힘을 모을 수 없습니다. 그래서 나는 당신이 이 일을 수행하도록 요청합니다. William은 Shatterridge Tower에서 캠프 입구까지 순찰하는 것으로 알려져 있습니다."},objectives={{66,613215588},"윌리엄 일병을 처치하고 글렌셔에 있는 브라이트코프 신부에게 보고하십시오."},progress={{17,23639106},"당신의 작품을 말해보세요."},completion={{146,1292823222},"이제 산 자들은 위협으로 여겨지지만, 그의 죽음은 정당화될 수 없습니다. 꼭 해야 했던 일이었는데... $B$BI는 남은 평생 동안 당신을 애도할 것입니다, 윌리엄."}}
rows[41366]={title={{19,1810247858},"설교하기에는 너무 늦었습니다"},description={"Duke Nargelas and the Baron of Silverlaine were good friends in life. Because of the respect and friendship they held for one another I too decided to keep close communication with the Prelate of Silverlaine Keep. Prelate Ironmane soon became my closest friend. He was a man like no other.$B$BAt times I'd leave Glenshire simply to hear his sermons. The way he spoke of the Light and the peace it brought him made me feel inferior as a holy man, even jealous perhaps. He would be ashamed were he to see me in this state.$B$B<Father Brightcopf pauses for a few seconds.>$B$BI know how this sounds $N, but I hear the call of his spirit from the now corrupted keep. Ghosts face a different type of undeath, unlike ours. While I managed to regain myself after the Lich King's grasp weakened, he will forever be stuck in a certain place in time. Not even aware of his own death.$BPlease, allow my friend to rest.","Nargelas 공작과 Silverlaine 남작은 인생에서 좋은 친구였습니다. 그들이 서로에 대해 갖고 있는 존경심과 우정 때문에 나 역시 Silverlaine Keep의 고위 성직자와 긴밀한 의사소통을 계속하기로 결정했습니다. 아이언메인 고위 성직자는 곧 나의 가장 가까운 친구가 되었습니다. 그는 다른 누구와도 비교할 수 없는 사람이었습니다. $B$BAt 저는 단지 그의 설교를 듣기 위해 글렌셔를 떠나곤 했습니다. 그가 빛과 그에게 가져온 평화에 대해 말하는 방식은 나로 하여금 거룩한 사람으로서 열등감을 느끼게 만들었고, 어쩌면 질투심까지 갖게 만들었습니다. 그 사람은 내가 이런 상태에 있는 것을 보면 부끄러워할 것입니다. $B$B<Father Brightcopf pauses for a few seconds.>$B$BI 이 말이 $N처럼 어떻게 들릴지 알지만, 나는 이제 타락한 성에서 그의 영혼의 부름을 듣습니다. 유령은 우리와는 다른 유형의 언데드에 직면합니다. 리치 왕의 손아귀가 약해진 이후 나는 간신히 정신을 되찾았지만, 그는 영원히 특정 시간의 장소에 갇히게 될 것이다. 자신의 죽음도 모르고.$BPlease, 내 친구를 쉬게 해주세요."},objectives={{67,796288887},"아이언메인 정무관을 처치하고 글렌셔에 있는 브라이트코프 신부에게 돌아가십시오."},progress={{14,1107828421},"비극적 인 운명."},completion={{58,1628201889},"그의 영혼이 다시 한 번 빛 속에서 평화를 찾을 수 있기를 바랍니다."}}
rows[41367]={title={{24,975319702},"콜카르의 꿈에 맞서"},description={{579,109880591},"Naralex를 깨우는 것이 주요 목표여야 하지만, 다른 것들도 필요합니다. $B$BThrough 미끄럽게도 균열이 생긴 콜카르는 구불구불한 틈의 가지에 숨겨진 길을 발견했습니다. 이번 침공 동안 우리가 주목한 자들을 죽이려고 시도했을 때 그들 중 한 명이 통곡의 동굴을 자신들의 타고난 권리라고 주장했습니다. 물론 $B$BFar. 콜카르는 대지모신의 사랑을 짓밟고 그들이 적합하다고 생각하는 곳마다 파괴만을 가져옵니다! 이 열성적인 콜카르의 이름은 잔다라 윈드후프.$BAs 과격하게 들릴지 모르지만 그녀의 머리를 나에게 가져다주세요."},objectives={{95,652538777},"통곡의 동굴에서 잔다라 윈드후프를 처치하고 그녀의 머리를 불모의 땅에 있는 날팍에게 가져가십시오."},progress={{30,1475806441},"악몽이 연이어 발생했습니다."},completion={"The darkness of the nightmare loomed over my on thoughts, breaking free emotions that I would usually keep in check. In a way, I regret it has come to this.$B$B<Nalpak sets Zandara's head on the ground.>$B$BA job well done, is a job well rewarded. You have my thanks $N.","악몽의 어둠이 내 생각을 덮치며 평소 억제하던 자유로운 감정을 깨뜨렸다. 어떻게 보면 이렇게 된 게 후회스럽습니다. $B$B<Nalpak sets Zandara's head on the ground.>$B$BA 일을 잘했고, 보상도 잘 받는 일입니다. $N에게 감사드립니다."}}
rows[41368]={title={{20,1830741643},"강철을 연상시키는"},description={"We do what the living cann- bah! I am piss tired of acting like nothing happened!$BCongratulations $N, you get to hear exactly -HOW- tired. It must be a thrill, right? Right?!$B$B<Basil sighs deeply.>$B$BI apologise, it seems something just clicked in my noggin just now. Feeling just a tad melancholic you see.$BI used to be a top-notch blacksmith at what's now known as the dreaded Scarlet Monastery. I remember the days I used to forge armor within the blessings of the Light.$B$BAnd nowadays, nowdays these maggots stare at me for even the mention of our former faith. Fools, all of them.$BAs luck has it, I was away from the Monastery the day that evil spawn Arthas scourged this entire city -- and now I am bound to forge my work around in the muck. Outrageous, I tell you, outrageous!$BMy apprentice Daghelm should be alive somewhere in the armory. The fool probably holds the journal I had on lightforge ingots - I want it back, even if you have to pry it from his dead cold fingers.","우리는 살아있는 Cann-bah를 수행합니다! 아무 일도 없었던 것처럼 행동하다니 정말 지쳤어요!$BCongratulations $N, 당신은 정확히 -얼마나- 피곤하다는 말을 듣게 될 것입니다. 정말 스릴이 넘치겠죠? 그렇죠?!$B$B<Basil sighs deeply.>$B$BI 죄송합니다. 방금 내 머리에 뭔가가 걸린 것 같습니다. 약간 우울한 느낌이 듭니다. $BI는 ​​지금은 무서운 붉은십자군 수도원으로 알려진 곳에서 일류 대장장이였습니다. 나는 빛의 축복 속에서 갑옷을 만들던 시절을 기억합니다. $B$BAnd 요즘은 구더기가 우리의 이전 신앙에 대해 언급하는 것조차 나를 쳐다보고 있습니다. 모두 바보들아.$BAs 운이 좋게도 나는 악마의 자손인 아서스가 이 도시 전체를 휩쓴 날 수도원을 떠나 있었다. 그리고 이제 나는 진흙 속에서 내 일을 해야 한다. 터무니없다, 터무니없다!$BMy 견습생 다그헬름은 무기고 어딘가에 살아 있을 것이다. 그 바보는 아마 내가 라이트포지 주괴에 쓴 일기장을 갖고 있을 것입니다. 비록 당신이 그의 죽은 차가운 손가락에서 그것을 뜯어내더라도 나는 그것을 되찾고 싶습니다."},objectives={{81,529031922},"무기고 병참장교 다그헬름을 처치하고 언더시티에 있는 바실의 일지를 그에게 가져가야 합니다."},progress={{78,6348545},"Daghelm의 죽음에 대해 걱정하지 마십시오. 지금쯤이면 그는 아마도 정신병 열광자일 것입니다."},completion={{160,895237328},"귀중합니다. 이 노트는 정말 소중합니다. 매우 소중합니다. 이 시점에서 스칼렛이 더 많은 라이트포지 갑옷을 만드는 데 방해가 될지는 의문이지만, 적어도 그것은 내 손에 돌아왔습니다."}}
rows[41369]={title={{25,1566246754},"메디브의 홀 막대"},description={{875,361175993},"이방인이여, 당신에게서는 엄청난 힘의 흔적이 흘러나오고 있습니다. 저주받은 탑 내부를 순환하는 것과 유사한 흔적이 이 죽은 계곡 위로 어렴풋이 보입니다. 아주 오래전처럼 느껴지겠지만, 이 교단의 우리 주민들은 한바르가 얼마 전 당신을 위해 복원한 유물을 안전하게 보관하라는 임무를 받았습니다. 그것은 무한한 마법의 통로인 강력한 유물의 일부입니다. 이전에 Guardian이 직접 사용했던 이 부품은 이제 파손되었습니다. 악이 한때 그랬던 것처럼 아제로스를 해칠 목적으로 이를 남용하지 않도록 하기 위한 안전 조치입니다. $B$BIts 부품은 탑 전체뿐만 아니라 전 세계에도 흩어져 있습니다. 여행 중에 그것을 얻을 수 있다면 나에게 가져오십시오. 그러면 원래의 모습으로 되돌려 드리겠습니다. 그러나 이를 위해서는 충분한 양의 비전 에너지가 필요합니다. 나는 이곳을 떠날 수 없으니 그런 것을 나에게 가져오는 것은 당신에게 달렸습니다. 수호자의 탑이 그것을 찾기에 적합한 장소일 것이다."},objectives={{133,1934481833},"Medivh의 홀 막대를 복원하려면 저승바람 고개의 Morgan's Plot에 있는 천리안 Anelace가 많은 양의 비전 에너지가 필요합니다."},progress={{157,1909039732},"카라잔은 지맥의 중심점 위에 세워졌습니다. 첨탑 내부의 존재들은 그 연결로부터 끌어오며, 그로부터 극복할 수 없는 힘을 얻습니다. 조심하세요."},completion={{463,1240776141},"끔찍하다. 비록 이것이 단지 변덕스러운 정령의 잔해일지라도, 그로부터 오는 순전한 압력은 압도적입니다. 이 에너지의 원천으로 나는 막대와 결속을 결합하여 메디브의 홀 막대를 다시 만들 수 있을 것입니다. 지금은 복원되었으나 아직은 미완성이다. 홀 머리가 없습니다. 그러나 그것을 어디서 찾을 수 있는지는 내 지식을 넘어서는 것입니다. 그것이 당신 손에 들어가게 된다면 나에게 다시 말해주세요. 최선을 다해 다시 도와드리겠습니다."}}
rows[41370]={title={{18,1617316091},"티리스팔의 흔적"},description={{845,1240581186},"내가 당신에게서 느끼는 것은 이 마비되는 열기, 너무 큰 압박감, 도저히 참을 수가 없다는 것입니다! 당신은 홀 머리를 가지고 돌아왔고 홀 머리는 그 홀 머리와 재회하기를 갈망합니다. 시간을 낭비하지 마십시오. 이 아이템의 엄청난 힘이 감당하기에는 너무 과중하지 않도록 하십시오. $B$BIt는 남은 우주 잔여물의 도움을 받아 메디브의 홀을 완전한 영광으로 복원할 수 있는 능력을 갖고 있습니다. 그러나 그것은 피상적인 복원일 뿐이다. 홀은 수호자의 정수가 주입되지 않으면 쓸모없는 장신구일 뿐입니다. 홀을 깨운 것은 그의 손길이었기 때문입니다. 그것을 메디브와 조율할 방법을 찾지 않는 한, 그것을 활용하는 것은 불가능할 것입니다. $B$BSeeing 수호자는 더 이상 이곳에 거주하지 않기 때문에 그의 그런 희미한 빛을 찾는 것은 불가능해 보입니다. 제발, 당신과 내가 그것을 찾는 것이 필수적입니다. 그렇지 않으면 홀은 영원히 비활성화된 상태로 남아 있을 것입니다."},objectives={{140,721549514},"메디브의 홀에 힘을 불어넣으려면 메디브의 조각품이 필요합니다. 카라잔 외곽 모건의 부지에 있는 천리안 아넬레스에게 가져가세요."},progress={{48,55907061},"우리는 역사의 근본적인 순간 앞에 서 있습니다."},completion={{342,1366541942},"수호자의 정수를 보고 몸서리쳐지는데, 당신이 그것을 여기까지 가지고 왔다는 것은 당신의 정신적 회복력과 신체적 능력의 증거입니다. 이제 모든 조각이 조립되었으므로 홀을 복원하는 데 몇 분밖에 걸리지 않습니다. 한발 물러서십시오. 그 과정에서 불안정한 에너지와 맹렬한 마법이 분출될 것으로 예상됩니다."}}
rows[41371]={title={{33,933434632},"다른 세상의 메디브의 홀"},description={"The scepter is complete, yet... different to how I remembered it. It looks identical, but the presence it has feels dull, almost empty. While the guardian's power is very much noticeable, there is an unmistakeable residue of foreign energy within the scepter itself. This energy lies dormant, asleep and longs to be awakened. $N, I fear we are not done yet, before we have released this magic from the relic.$B$BWhen I focus my mind on the artifact, I recognize floating stone, a land tormented and fire being spewed from the ground. A race of traveling mystics, subdued by an emerald flame.$B$B$N, please forgive me for not being helpful enough. In order to harness the foreign magic of the scepter, I would need to harmonize it with an energized item from that plane I described to you. Where you would find such a thing, eludes my eyes, however.","홀은 완전했지만... 내가 기억했던 것과는 달라요. 겉모습은 똑같지만 그 존재감은 밋밋하고 공허한 느낌이다. 수호자의 힘은 매우 눈에 띄지만, 홀 자체에는 의심할 여지 없이 외부 에너지의 잔류물이 남아 있습니다. 이 에너지는 잠자고 있으며 깨어나기를 갈망하고 있습니다. $N, 유물에서 이 마법이 풀려나기 전에 아직 끝나지 않았나 싶습니다. $B$BWhen 나는 유물에 정신을 집중했고, 떠다니는 돌과 고통받는 땅, 그리고 땅에서 뿜어져 나오는 불을 인식했습니다. 에메랄드 불꽃에 휩싸인 여행하는 신비술사.$B$B$N, 충분히 도움이 되지 못한 점 양해 부탁드립니다. 홀의 외래 마법을 활용하려면 제가 설명드린 차원의 활력이 넘치는 아이템과 홀을 조화시켜야 합니다. 그러나 그런 것을 어디서 찾을 수 있는지는 내 눈을 피합니다."},objectives={{160,598763360},"카라잔 외곽 모건의 음모에 있는 천리안 아넬레스에게 유사한 마법의 원천을 가져와 메디브의 홀에 있는 맹렬한 외계 마법을 조율하세요."},progress={{134,1741730793},"내가 환상에서 본 장소를 생각해 보십시오. 아마도 당신이 들은 내용은 이미 여행 중에 만난 무언가나 누군가를 생각나게 했을 것입니다."},completion={{245,747121075},"나는 이전에 이런 보석을 본 적이 없습니다. 청록색, 구조, 표면은 여기 아제로스의 어떤 것과도 비교할 수 없습니다. 그러나 나는 당신이 진실을 찾기 위해 애쓰는 노력에 다시 한 번 놀랐습니다. 이제 마지막으로 마무리하겠습니다."}}
rows[41372]={title={{16,2127656197},"통로가 열렸습니다"},description={{106,624528733},"조율에는 내 시간과 에너지가 약간 필요합니다. 프로세스를 시작하고 싶으면 알려주시기 바랍니다."},objectives={{54,1171909219},"메디브의 홀이 만들어지는 과정을 목격하세요."},progress={{72,1104029123},"너무 오래 기다리지 말자. 우리는 마법이 길들여지지 않은 채로 남아 있기를 원하지 않습니다."},completion={{603,1965759115},"나는 당신에게 레이 마법의 통로이자 외계 세계의 원시 에너지인 메디브의 홀을 맡깁니다. 그것으로 당신은 카라잔 자체의 폭력적인 마법의 급류를 지휘할 수 있습니다. 만족하지 마십시오. 당신은 확실히 강력하지만 홀의 이전 소유자는 홀을 올바르게 휘두르는 유일한 사람입니다. 그럼에도 불구하고, 저주받은 탑의 가장 깊은 비밀이 이제 당신의 발 밑에 놓여 있으며, 그 위험한 손길을 용감히 감당할 만큼 강인한 사람이 공개해 주기를 간청하고 있습니다. $B$BGo 앞으로 나아가 당신이 그토록 용감하게 싸워온 진실을 주장하세요! 카라잔 정복이 영웅적 유산의 이정표가 되도록 하세요!"}}
rows[41373]={title={{16,1663244654},"셰프 폐하"},description={{659,542066043},"텍스트는 매우 느린 고블린 속어로 작성되었습니다. 페이지를 넘기다 보면 친숙한 요리법이 눈에 들어오지만 그다지 흥미롭지는 않습니다. 한숨을 쉬며 다음 페이지를 넘기면서 누락된 페이지를 발견합니다. 책이 여기서 끝나지 않을 거라 생각했다면 이제 가능성에 무게를 두게 되었을 것입니다. $B$BA 책을 덮기로 결정하면서 수십 가지 가정이 떠오릅니다. 뒷면을 보면 \"The Great Gastino\"라는 이름을 알 수 있습니다. 이 일반적인 책의 장점은 무엇입니까? 이 Gastino는 누구이며, 누가 당신에게 더 많은 것을 말해 줄 수 있습니까? 호기심이 마음 속 깊이 뿌리내리면서 카라잔의 아래쪽 홀에 있던 유령 요리사가 생각납니다."},objectives={{38,743728050},"카라잔 하층 전당에서 요리사를 찾으세요."},progress={{41,768366646},"모든 것이 마음에 드셨나요, 친애하는 손님?"},completion={{73,1084636804},"아, 다름 아닌 가스티노의 \"케잔의 요리법\", 그거 어디서 찾았나요?"}}
rows[41374]={title={{20,198413735},"요리사들 사이에서는 명예가 없다"},description={{602,646012198},"가스티노의 요리법 책은 여러분이 이미 알아차렸을 수도 있듯이 꽤 흔했습니다. 하지만 그 안에는 힐러의 집중력을 되살려주는 특정 레시피가 포함되어 있었습니다. 신기하게도 사제들은 도깨비의 탐욕스러운 야망을 인정하면서도 그가 남긴 이 조리법에 대해서는 감사하지 않을 수 없었다. $B$BIn 어찌 보면 그 단순함을 높이 평가한 것 같다. 모듬샐러드에 불과했으니까. 레시피를 외우지는 못하지만 이 누락된 페이지는 지하실 어딘가에 있을 것 같아요. 이 책은 그곳에 묻혀 있는 누군가의 것이었습니다. 조심하세요. 시간이 그 장소에 친절하지 않은 것 같아요."},objectives={{92,322619535},"카라잔 납골당에서 탐욕스러운 스트리고이를 처치하고 카라잔 하층 전당에 있는 요리사에게 돌아가세요."},progress={{27,409730358},"당신이 원하는 것을 찾았나요?"},completion={{140,1506655035},"구겨진 종이 한 장. 아무리 생각해도 이 정도로 줄어드는 게 안타깝다. 그것을 갖고 있으면 기억이 나니까 내가 당신을 위해 그것을 복원해 주겠습니다."}}
rows[41375]={title={{24,474424744},"마법의 나무에 대한 연구"},description={{924,1480837660},"얼핏 보면 그 책은 아주 평범한 책인 것 같았다. 그러나 당신이 그 내용을 연구하기 시작하면서, 당신은 그 외양이 전문적으로 쓰여진 작품이라기보다는 거친 일기장에 더 가깝다는 것을 금방 알아차렸습니다. 제목으로는 연구라고 주장했지만, 너덜너덜한 페이지와 엉성하게 그려진 텍스트는 마치 어린아이의 손을 거친 것 같았습니다. $B$B\"나는 엘드레탈라스 내의 고대인과 트렌트에 대한 아이디어를 두 팔 벌려 환영했지만 많은 형제들은 그것이 다소 불필요하다고 생각했습니다. 우리는 비전에 더 익숙해졌고, 그들의 마음 속에서 이 마법의 생물과 함께 일하는 것은 그들과 비슷한 마법을 휘두르던 드루이드들이 시간이 지나면서 두 가지 마법 나무의 모습이 꽤 잘 적응한 것 같았고, 일부 나무정령들은 심지어 푸른 색조의 잎사귀도 자라고 있었습니다.”$B$BAs 눈을 가늘게 뜨고 방금 읽은 텍스트 아래에 이름이 있음을 알 수 있습니다: Lydros."},objectives={{47,2094539002},"혈투의 전장으로 가서 현자 리드로스를 찾으십시오."},progress={{64,856712640},"당신은 눈에 띄는 무언가를 가지고 있는 것 같습니다. 좀 보도록 할게요."},completion={{118,1414990092},"당신은 나를 조롱하고 있습니까? 이건 어린아이의 실수인 것 같아요–$B$B<Lydros stares silently into thin air for a few moments.>"}}
rows[41376]={title={{17,18054668},"휘장을 감싸기"},description={{761,188887746},"나는 이 저널을 알아요. 내가 토르텔드린 왕자를 위해 보관하던 물건이에요. 우리는 그와 나뿐 아니라 대부분의 로어키퍼들을 만나서 다양한 일들을 논의하곤 했습니다. 엘드레탈라스는 지식의 장소였습니다. 안타깝게도 그것은 예전의 그림자일 뿐입니다. 이것을 다시 가져와 주셔서 감사합니다.$B$BIf 시간이 있으니 부탁이 있습니다. 이 책을 조사한 결과 마지막 페이지에 새겨진 불완전한 문양을 발견했습니다. 우리의 연구는 아직 끝나지 않았기 때문에 워프우드 지구로 가서 그 지역을 돌아다니는 오염된 나무정령들을 처치해 주시길 부탁드립니다. 운이 좋다면, 한때 그들을 장식했던 푸른색을 여전히 잎사귀에 가지고 다닐 수 있습니다. 이 나뭇잎을 나에게 가져오시면 조사 결과를 보상해 드리겠습니다."},objectives={{40,24600510},"현자 리드로스에게 푸른 잎사귀 5개 가져가기"},progress={{43,199042525},"어떤 향수가 내 뼈를 통해 흐릅니다."},completion={{120,756591285},"이제 글리프가 완성되어 사용할 수 있게 되었습니다. 선택 여부는 귀하에게 달려 있습니다."}}
rows[41377]={title={{21,781510573},"여신의 낫"},description={{520,1883090784},"이제 우르의 가르침을 탐구하는 데 시간이 좀 걸릴 것 같습니다. 중요한 세부 사항이 내 주의를 벗어나지 않도록 해야 합니다. 이 책은 방대하며, 우르는 마음이 예민한 사람들을 위한 비밀 메시지를 삽입하는 것으로 알려져 있습니다. $B$BIn 그동안 당신에게 할 일이 있습니다. 이 세상의 현명한 현자 중에서 우리 조직의 지도자인 판드랄 스태그헬름의 지혜와 통찰력을 소유한 사람은 거의 없습니다. 그는 다르나서스에 거주하고 있습니다.$B$BJourney 다르나서스에게 당신이 발견한 내용을 알려주세요. 분명히 그는 이 강력한 유물에 관해 귀중한 조언을 제공할 것입니다."},objectives={{59,1237729515},"다르나서스에서 대드루이드 스태그헬름을 찾아 그의 조언을 구하십시오."},progress={{11,819267740},"그것은 무엇입니까?"},completion={{138,2072048373},"그래서 전설적인 엘룬의 낫이 발견되었습니다. 비록 하이잘을 치료하려는 그의 노력이 잘못된 것임에도 불구하고 드림윈드께서 현명하게 당신을 나에게 보내셨습니다."}}
rows[41378]={title={{18,24120836},"보겐도르의 피"},description={{953,1514096679},"엘룬의 신비는 심오하며, 제가 아는 모든 지식을 가지고 있는 나조차도 때때로 그 신비를 이해하기 어려울 때가 있습니다. 나는 왜 그녀가 벨린데(예, 그것이 그녀의 이름이었습니다)에게 엘룬의 낫과 같은 유물을 맡기셨는지 완전히 이해하지 못합니다. 그러나 늑대인간을 소환하는 힘은 실제로 더 깊은 진실을 밝히는 열쇠일 수 있습니다. $B$BI는 오랫동안 여명초라고 알려진 독특한 약초에 대한 연구에 참여해 왔습니다. 흥미롭게도 내 연구에 따르면 카라잔 시대부터 낫에 달라붙어 있던 어둠의 에너지를 제거하는 데 도움이 될 수도 있다는 것이 밝혀졌습니다. 하지만 여명초를 활성화하려면 강력한 촉매제가 필요합니다. 그러니 나에게 피를 가져오십시오. 카라잔의 가장 어두운 구석에 숨어 길니아스 도시의 버려진 거리를 배회하고 그림자송곳니 성채의 그늘에 숨어 있는 다양한 부족들에게서 수집한 늑대인간의 피입니다.$B$BDo 이것을 가져다 주세요. 지체하지 마십시오. 낫의 힘은 나만큼 유능한 사람이 활용하고 이해해야 합니다."},objectives={{116,1995268417},"판드랄 스태그헬름을 위해 늑대인간의 피를 모아야 합니다. 그는 카라잔, 길니아스 시, 그림자송곳니 성채에서 혈액 샘플을 요구합니다."},progress={{45,1581617861},"낫을 정화하는 것이 필수적입니다."},completion={{69,85962268},"인상적이다. 자, 그 피를 나에게 주세요. 필요한 것을 준비하겠습니다."}}
rows[41379]={title={{9,1167045981},"늑대혈통"},description={{734,496067169},"늘 그렇듯 내 말이 옳았다. 여명초 덕분에 나는 당신이 모은 늑대인간 피에서 어둠을 성공적으로 제거했습니다. 자, 목격자님!$B$B<Arch Druid Fandral Staghelm extends his hand, displaying a vial of pure, blue blood.>$B$BThis가 여러분에게는 별 것 아닌 것처럼 보일 수도 있지만, 눈앞에 보이는 것은 그들의 혈통의 강함뿐만 아니라 엘룬과의 관계에 대한 증거이기도 합니다. 자세히 보세요. 그들의 혈액에서 그것을 눈치채셨나요?$B$BIndeed. 우리 달샘의 물처럼 순수합니다. 그것이 혈마법이 그들의 종족을 오염시키기 전의 모습이었습니다. 당장 드림윈드에게 가져가세요. 그는 다음에 무엇을 해야 할지 알고 있을 것입니다.$B$BAnd, 만약 당신의 지친 어깨에 낫을 너무 많이 휘두르는 부담이 느껴진다면... 당신은 나를 어디서 찾을 수 있는지 알고 있을 것입니다."},objectives={{70,1878626555},"하이잘의 노르다나르에 있는 대드루이드 드림윈드에게 순수한 늑대인간 피를 가져가야 합니다."},progress={{16,713679627},"당신은 돌아왔습니다."},completion={{116,1105240724},"우르의 설명과 같은 순수한 늑대인간 혈액... 예, 매우 유용할 것입니다. 하지만 이제 들어보세요. 제가 공유할 내용이 많으니까요."}}
rows[41380]={title={{21,781510573},"여신의 낫"},description={{927,1870351688},"이제 우르의 가르침을 탐구하는 데 시간이 좀 걸릴 것 같습니다. 중요한 세부 사항이 내 주의를 벗어나지 않도록 해야 합니다. 이 책은 방대하며, 우르는 마음이 예민한 사람들을 위한 비밀 메시지를 삽입하는 것으로 알려져 있습니다. $B$BIn 그동안 당신에게 할 일이 있습니다. 이 세상의 현명한 현자 중에서 우리 조직의 지도자인 판드랄 스태그헬름의 지혜와 통찰력을 소유한 사람은 거의 없습니다. 하지만 그 사람이 나만큼 당신의 존재를 받아들이지 않을 수도 있다는 걱정이 듭니다. $B$BYet, 모든 희망이 사라진 것은 아닙니다. 당신의 타우렌 동맹 중에는 판드랄만큼 현명한 사람이 있습니다. 나는 마가타 그림토템에 대해 이야기합니다. 때때로 그녀의 일족이 무질서함에도 불구하고 그들은 항상 Mu'sha라고 부르는 Elune을 존경해 왔습니다. $B$BTo 내가 아는 바로는 그녀는 이제 위대한 도시 Thunder Bluff에 살고 있습니다. 거기 가서 그녀의 조언을 구하세요. 어쩌면 그녀는 나조차 모르는 낫에 대한 지식을 갖고 있을지도 모릅니다. 당신의 여행은 아직 끝나지 않았습니다. 그림토템족의 지혜는 매우 귀중할 것입니다."},objectives={{44,1687796682},"마가타 그림토템을 찾아 그녀의 조언을 구하세요."},progress={{11,1252439580},"응, 얘야?"},completion={{106,505116936},"그리하여 전설적인 무샤의 낫이 발견되었습니다. 이 대드루이드 드림윈드는 현명하게도 당신을 나에게 보냈습니다."}}
rows[41381]={title={{34,2113109694},"늑대, 노파, 낫"},description={{828,2105627234},"나는이 무기와 그것을 부풀리는 vile 지방의 많은 이야기들을 들었다. 그러나, 전혀 잃지 않는다, 우리는 카라잔의 어둠 속에서 그것을 청소 할 수있을 수있다.$B$B최근, Cenarion Circle의 일부 회원, 특히 Fandral Staghelm에 가장 가까운, morrowgrain라는 특정 허브의 상당한 금액을 매료하고있다. Archdruid Hamuul이 나를 공유 한 것을에서, 나는이 허브가 Scythe를 순화하기 위해 열쇠가 될 것이라고 믿는다.$B$B그러나, 그것은 작동하기 위해, 강력한 촉매가 필요합니다. 우리는 카라잔의 가장 어두운 구석에 흠뻑 취하는 다양한 부족의 혈액이 필요하며, 길네사시의 포크 거리를 뚫고, Shadowfang Keep의 그림자 내에서 숨깁니다.$B$B그들의 혈액을 쫓아 내게 하세요. 함께, 우리는 아직 Scythe를 청소하고 진정한 목적에 회복할 수 있을지도 모릅니다."},objectives={{118,912303451},"마가타 그림토템을 위해 늑대인간의 피를 모아야 합니다. 그녀는 카라잔, 길니아스 시, 그림자송곳니 성채에서 혈액 샘플을 요구합니다."},progress={{33,400478832},"무샤의 낫을 정화해야 합니다."},completion={{46,265096045},"언제나처럼 절묘한 작업입니다. 이제 나에게 건네주세요."}}
rows[41382]={title={{9,1167045981},"늑대혈통"},description={{587,895915912},"판드랄의 하수인들이 여명초로 무엇을 계획하든 정말 대단한 일이겠군요... 하지만 저는 생각이 다릅니다. 피는 참으로 깨끗해졌습니다. 얘야, 여기 좀 봐라. $B$B<Magatha Grimtotem extends her hand, displaying a vial of pure, blue blood.>$B$BPure 달샘의 물이 별처럼 빛난다. 어떤 끔찍한 운명이 이 늑대인간에게 닥치기 전에는 의심할 바 없이 그들은 무샤가 가장 좋아하는 아이들이었습니다. $B$BBring 이것은 즉시 Dreamwind로 돌아왔습니다. 그는 알고 싶어할 것입니다.$B$BAnd 낫을 가까이 두세요. 세나리온 의회의 일부 구성원은 그것이 당신 손에 있다는 사실에 그다지 기뻐하지 않을 수도 있습니다."},objectives={{61,831466510},"노다나르에 있는 대드루이드 드림윈드에게 순수한 늑대인간 피를 가져가야 합니다."},progress={{16,713679627},"당신은 돌아왔습니다."},completion={{241,192910373},"우르의 설명과 마찬가지로 순수한 늑대인간의 피입니다. 예, 매우 유용할 것입니다. 그들은 한때 엘룬이 총애한 아이들이었으며, 타락하지 않은 피를 갖고 있었습니다... 그것이 의식의 핵심이 될 것입니다... 하지만 이제 들어보실 것이 많습니다."}}
rows[41383]={title={{12,660723786},"우르의 지혜"},description={"During your absence, I delved deep into the teachings of Ur, scrutinizing every passage, every word, and every hidden meaning within the tome. The knowledge I uncovered is both enlightening and deeply unsettling.$B$BStay awhile and listen, young $r. The wisdom contained in Ur's writings is profound, but it also reveals a grim truth about the Scythe of Elune and the nature of its power.","당신이 없는 동안 나는 우르의 가르침을 깊이 파고들어 그 책에 담긴 모든 구절, 모든 단어, 모든 숨겨진 의미를 면밀히 조사했습니다. 제가 발견한 지식은 계몽적이기도 하고 매우 불안하기도 합니다. $B$BStay 잠시 동안 들어보세요, 젊은 $r. 우르의 저서에 담긴 지혜는 심오하지만, 엘룬의 낫과 그 힘의 본질에 대한 암울한 진실도 드러냅니다."},objectives={{64,1809457079},"대드루이드 드림윈드가 당신이 없는 동안 무엇을 배웠는지 들어보세요."},progress={{23,617071365},"시간이 핵심입니다."},completion={{102,721742661},"이제 알 수 있습니다. 시간이 별로 없어요. 낫을 정화하려면 그들을 찾아야 합니다."}}
rows[41384]={title={{19,107223736},"프리콜리치 날문"},description={{966,867139464},"이제 수호자 날문을 쓰러뜨릴 시간입니다. 우리 세계의 운명이 그것에 달려 있습니다. 카라잔에서 그의 존재는 용납할 수 없는 재앙이며, 그의 계획은 결실을 맺기 전에 반드시 좌절되어야 합니다. 자연 자체의 균형이 위태로워졌습니다. $B$BYou는 책을 찾기 위해 이미 카라잔의 상층부로 모험을 떠났으므로 미로 같은 복도와 그림자가 드리워진 전당에 대해 잘 알고 있습니다. 앞으로의 여정은 쉽지 않을 것이지만 이전 경험이 도움이 될 것입니다. 날문은 카라잔의 암흑 마법의 중심부에 자리를 잡고 저주받은 곳에서 힘을 끌어내어 그의 사악한 계획을 추진하고 있습니다. $B$BBut 조심하세요. 날문은 평범한 적이 아니기 때문입니다. 그는 전설적인 힘을 지닌 혈마법사로서 수세기 동안 가장 어두운 예술에 손을 댔습니다. 혈마법에 대한 그의 지휘력은 타의 추종을 불허합니다. 그와 혼자 맞서는 것은 어리석은 일이다. 당신에게는 어둠의 조류에 맞서 당신과 함께 설 수 있는 강하고 용감한 동료, 동맹이 필요할 것입니다."},objectives={{73,113934849},"수호자 날문을 처치하세요. 그는 카라잔의 상층 방에서 찾을 수 있습니다."},progress={{16,2103791372},"주저하지 마십시오."},completion={{79,237191751},"사악한 프리코리치 나르문이 죽었습니다! 참으로 인상적입니다. 당신은 우리 모두를 구했습니다."}}
rows[41385]={title={{17,293429379},"길니아스 프리콜리치"},description={{987,1569459791},"내 까마귀들은 한때 길니아스 시의 거리를 뒤덮었던 어두운 존재에 대해 속삭였습니다. 바다 건너 멀리, 어둠과 안개 속에서, 늑대인간 혈법사가 사악한 마법을 휘두르는 것이 보였습니다. 이 생물은 이미 혼란스러운 땅에 지울 수 없는 흔적을 남겼습니다. 자세한 내용은 드물지만 한 가지는 확실합니다. 그는 길니아스의 악명 높은 섭정인 Harlows와 종종 공모했다는 것입니다. $B$BThe Harlows는 교활하고 무자비한 가족입니다. 어떤 대가를 치르더라도 자신의 야망을 진전시킬 수 있는 사람이라면 누구와도 동맹을 맺을 것이라고 합니다. 혈마법사는 자신의 필요에 맞는 한 자신의 어둠의 관행을 눈감아 주는 기꺼이 공범자로 삼았습니다. 혈법사 계획의 열쇠는 그들의 비밀스러운 거래에 있을 수 있습니다. $B$BIf 나는 하이잘의 신성한 숲을 떠날 수도 있고 길니아스로 직접 여행을 떠날 수도 있습니다. 하지만 젊은이여, 당신에게는 내가 할 수 없는 곳으로 모험을 떠날 자유가 있습니다. 당신의 길은 분명하며 길니아스 시의 안개로 뒤덮인 거리로 이어집니다."},objectives={{79,1854052858},"길니아스 시로 가서 두 번째 프리콜리치의 행방을 찾아보세요."},progress={{35,561224127},"아직은 놀드랏실을 떠날 수 없습니다."},completion={{311,1221545894},"라이칸 신부... 그림자가 가득한 이름이지만 우리 구원의 열쇠를 쥐고 있을 수도 있는 이름입니다. 당신이 발굴한 이 일지는 수수께끼이지만 그의 사악한 존재 뒤에 숨은 진실을 밝히는 촉매제가 될 수 있습니다. 우르의 가르침을 다시 한 번 파헤쳐 보겠습니다. 그 안에는 이 신비를 해독하는 지혜가 있기 때문입니다."}}
rows[41386]={title={{15,447994588},"프리콜리치 라이칸"},description={{972,1428381300},"우르가 집필한 고대 전설의 연대기에서는 프리콜리치의 이름을 부르는 것만으로도 그의 어두운 존재를 우리 영역으로 끌어들이는 등대가 될 수 있다고 속삭였습니다. 그러나 내 말을 주의 깊게 들으십시오. 그를 우리의 통제하에 끌어들이려는 계략, 교활한 계획이 존재하기 때문입니다. $B$BTake 이 비전 구체는 원시 마법의 정수가 주입된 과거의 유물입니다. 그것을 손에 들고 서쪽을 향해 원시적이고 강력한 에너지가 결합된 고대 권력의 원이 있는 곳으로 모험을 떠나세요. 그곳에서 속삭이는 바람과 바스락거리는 나뭇잎 속에서 프리콜리치의 이름을 말하십시오. $B$BBut 조심스럽게 그렇게 하십시오. 왜냐하면 그의 도착은 정밀하게 조율되어야 하기 때문입니다. 일단 소환되면 우리는 의회의 힘을 휘두르며 그를 가두어 그의 어둠의 힘을 제거하고 그를 취약하게 만들 것입니다. 그 약해진 순간에 우리는 그를 공격하여 그가 왔던 그림자 속으로 다시 추방하고 그의 사악한 손아귀에서 영원히 우리 영역을 확보할 것입니다."},objectives={{41,506271604},"권력의 원에서 라이칸 신부를 처치하세요."},progress={{11,56490833},"끝났나요?"},completion={{70,2083369811},"사악한 프리코리치 라이칸이 죽었습니다! 당신은 그를 막고 벨린데의 복수를 했습니다!"}}
rows[41387]={title={{18,206562274},"철의 결단력"},description={{724,259190379},"그러니 당신은 나보다 먼저 나아갑니다. 확실히 전쟁 기술에 대한 지도를 구하려는데, 왜 무기의 대가를 찾겠습니까? 당신은 무술에 대한 전문 지식을 얻고자 하는 많은 사람들 중 하나입니다. 그러나 실제로 그것을 달성할 수 있는 몇 안 되는 사람 중 하나가 되겠습니까? 나는 얼마나 많은 속기 쉽고 순진한 전사들이 내 가르침을 받을 가치가 있다고 생각하다가 사소한 도전에도 실패하는지 셀 수 없이 많습니다. 당신의 가치가 나에게 증명되지 않는 한, 나는 당신이 앞으로 일어날 일에 적합하다고 확신할 수 없습니다. $B$BHigh 북쪽 산 위에는 악령의 숲이라는 더럽혀진 숲이 있습니다. 더 북쪽으로 가면 Irontree Cavern이 있습니다. 내가 당신에게 요구하는 것은 이 동굴 안에서 철처럼 차갑고 똑같이 무거운 뿌리입니다. 뿌리를 따서 안전하게 나에게 가져오너라."},objectives={{67,882846907},"무쇠덩굴 뿌리를 가지고 프레이 섬에 있는 마티아스 브라이트하트에게 돌아가세요."},progress={{50,1797749398},"이 시련은 당신이 필요한 것을 얻었는지 나에게 보여줄 것입니다."},completion={{620,1346448277},"Ironvine 뿌리는 공격적인 식물입니다. 뿌리가 뽑히면 포획자 주위에 달라붙어 땅으로 끌어내리려고 시도하다가 결국에는 지치게 됩니다. 그러나 당신은 이 자연의 힘에 굴복하지 않았습니다. 당신의 마음은 맑았고 의지는 굳건했습니다. 이 테스트를 마지막으로 통과한 사람은 수년 전 나의 견습생 Sakgoth였습니다. 아마도 나는 당신에게서 특별한 사람을 발견했을 것입니다. 다가오는 시험에서는 내 가정이 맞는지 알려줄 것입니다. $B$B<Mathias takes a dagger and with a swift cut you almost couldn't see, he removes the gripping vines from your body.>$B$BWe는 낭비해서는 안 되며 이 뿌리로 훌륭한 차를 끓일 수 있습니다."}}
rows[41388]={title={{19,417821483},"실패로부터의 지혜"},description={{718,1623830472},"나의 경솔한 태도에 대해 사과드립니다. 하지만 당신이 전쟁의 길에 들어가지 않도록 확실히 해야 합니다. 당신은 무술에 대한 경험이 있을 수 있지만 내 길을 따르려면 지금까지 성취한 것보다 더 많은 것이 필요합니다. $B$BAs 앞서 언급했듯이 많은 야심 찬 사람들이 지금 당신이 있는 곳에 섰지만 소수만이 성공했습니다. 자신의 실수와 다른 사람의 실수로부터 배우는 것이 중요합니다. 나의 이전 학생들과 이야기를 나누면 그들은 실패에 대한 이야기를 나눌 것입니다. 당신이 그들의 잘못을 정말로 이해하는 경우에만 계속 진행할 것입니다. 이 섬에서는 Sakgoth와 Klannoc, 그리고 Tanaris에서는 Ka'fai와 대화하세요. 나는 사막의 스릴이 그를 가젯잔이라는 도시로 이끌었다고 들었습니다. 그렇게 하고 나면 돌아와서 그들의 말에 관한 내 질문에 대답해 주십시오."},objectives={{32,1502956593},"마티아스 브라이트하트의 테스트를 통과하세요."},progress={{120,228500851},"같은 수업은 없습니다. 그들과 저지른 실수 사이의 연관성을 이해하면 그들의 지혜를 이해할 수 있습니다."},completion={{107,709635385},"칭찬할 만하다. 이러한 교훈을 마음에 새기는 것은 당신이 택한 이 길에서 미래의 성공을 위해 필수적입니다."}}
rows[41389]={title={{5,1029938335},"증명"},description={{201,2145005885},"여기 유리구슬을 가져다가 삭고스에게 가져가세요. 그것은 당신의 행위에 대한 증거이며 당신이 그와 동등하다는 신호입니다. 항상 경계하고 배운 것을 기억하십시오. 당신의 더욱 성장하는 모습을 지켜볼 수 있어 기쁩니다!"},objectives={{50,1247946921},"유리구슬을 옆방에 있는 삭고스에게 건네주세요."},progress={{66,2070346863},"거기서 무슨 일이 일어났나요? 거기에서는 고기 타는 냄새가 나요."},completion={{431,1619953302},"주인은 수수께끼 같은 사람이고, 나는 아마도 그의 마음의 방식을 완전히 이해하지 못할 것입니다. 운 좋게도 우리가 여기 있는 이유는 그게 아니죠? $B$BThis 진주를 가져오셨는데, 정말 다른 것 같아요. 석사 과정의 모든 학생은 자신의 성취에 대한 증거로 그 사람, 엄밀히 말하면 나로부터 개인적인 선물을 받습니다. 내 것은 버섯구름 봉우리에서 내가 죽인 전갈의 독침이다. 그리고 당신을 위해서... 펜던트에 대해 어떻게 생각하시나요?"}}
rows[41390]={title={{18,2119014717},"서부 몰락지대의 드론"},description={{702,108721112},"안녕, 당신. 우연히 서부 몰락지대에 가셨나요? SI:7은 서부 몰락지대 외부의 개인을 연루시키는 데피아즈단의 계략을 주도하고 있습니다. 우리는 그들이 스톰윈드뿐만 아니라 나머지 동부 왕국에도 위협이 될 수 있는 일종의 고휘발성 화학 물질을 다루고 있는 것으로 의심합니다. 말하자면... '추가적인 힘'을 사용할 수 있습니다. 이 일은 은밀한 거래가 아닐 가능성이 높기 때문입니다. 우리 요원 $B$BOne는 서부 몰락지대 그늘숲으로 이어지는 다리, 버려진 마법사 탑 근처에 위치해 있습니다. 가서 그녀를 만나서 빨리 처리해 주셨으면 합니다. 조사할 가치가 있는 사건이 갑자기 발생했습니다. Kearnen은 그녀의 이름입니다. 일단 그녀를 찾으면 그녀가 말하는 대로 하세요."},objectives={{45,844267313},"서부 몰락지대 남부에 있는 커넨 요원을 만나세요."},completion={{55,1970586345},"렌직이 당신을 보냈나요? 좋은. 인력을 좀 더 쓸 수 있겠네요."}}
rows[41391]={title={{16,921118891},"벤처 납품"},description={{949,966229634},"나는 꽤 오랫동안 이 탑을 감시해왔는데 그 주변에서 일어나는 모든 일은 헤아릴 수 없을 정도로 이상했습니다. 이곳에는 데피아즈단이 드물지만 확실히 장비가 잘 갖추어져 있습니다. 그것만으로도 충분히 걱정되지만, 가장 당황스러운 것은 경계를 순찰하는 좀비들입니다. 때때로 데피아즈단 중 일부가 탑에 들어갑니다. 하지만 그들이 다시 떠나는 대신 완전히 새로운 좀비 표본이 추악한 얼굴을 드러냈습니다. $B$BI는 이 탑의 내부 계략을 더 조사하고 싶지만 SI:7의 지원군을 기다리고 있습니다. 당신이 여기 있는 목적은 매우 간단하지만 더욱 중요합니다. 탑 근처 부두에서 나는 상자를 가득 실은 노 젓는 배를 계류하고 있는 그늘진 고블린을 발견했습니다. 물론 어떤 종류의 전달이 필요하더라도 문서가 필요하며, 가급적이면 이러한 작업에 관련된 사람들의 이름이 포함되어 있어야 합니다. 그녀를 원하는 대로 처리하되 귀중한 정보가 있으면 SI:7 본부에 있는 렌직에게 직접 가져오세요."},objectives={{92,607097817},"고블린에게서 귀중한 문서를 찾아 스톰윈드에 있는 '칼' 렌직에게 가져가세요."},progress={{44,1640153030},"그렇게 빨리 돌아오나요? 빈손으로 하지 않기를 바라요..."},completion={{130,1583214709},"자레드 보스? 나는 이 이름이 여러 종을 울리는 것을 싫어합니다. 이 문서의 내용이 사실이라면 우리는 즉시 서둘러야 합니다."}}
rows[41392]={title={{19,682771808},"수도꼭지 끄기"},description={"Jared Voss is the son of William Voss, a highly skilled and educated alchemist. His father had an alchemy shop here in the Old Town, beloved by many. When Stormwind was burnt down a second time, his family's home was among those burned to ashes. During its rebuild by the Stonemason's Guild, Voss naturally assumed his house to be restored, given his importance as Stormwind's most renowned alchemist. Ironically, it would not come to pass.$B$BStormwind's nobility had different plans of reconstructing the city and in the end, Voss and his family became homeless. With a growing hatred in his heart, he condemned those responsible for their fate. We're assuming Voss sent his son to the Stonemason's before his death, who shared his disdain. It seems Jared succeeded his father in both hate and abilities.$B$B$N, Voss cannot be allowed to operate any longer. According to the list you brought, he dwells in the Deadmines. Liquidate him and bring me samples of his newest brew.","Jared Voss는 고도로 숙련되고 교육받은 연금술사인 William Voss의 아들입니다. 그의 아버지는 이곳 올드타운에서 많은 사람들에게 사랑받는 연금술 가게를 운영하고 있었습니다. 스톰윈드가 두 번째로 불타버렸을 때, 그의 가족의 집도 불타 잿더미가 되었습니다. 석공 길드가 재건축하는 동안 보스는 스톰윈드의 가장 유명한 연금술사로서의 중요성을 고려하여 자연스럽게 자신의 집을 복원할 것이라고 생각했습니다. 아이러니하게도 그것은 이루어지지 않았습니다. $B$BStormwind의 귀족들은 도시를 재건하려는 서로 다른 계획을 가지고 있었고 결국 Voss와 그의 가족은 노숙자가 되었습니다. 마음 속에 증오심이 커지면서 그는 자신의 운명에 책임이 있는 사람들을 정죄했습니다. 우리는 Voss가 죽기 전에 그의 아들을 석공의 집으로 보냈고, 그도 그의 경멸을 공유했다고 가정합니다. Jared는 증오심과 능력 모두에서 그의 아버지를 계승한 것 같습니다. $B$B$N, Voss는 더 이상 운영될 수 없습니다. 당신이 가져온 목록에 따르면 그는 죽음의 폐광에 살고 있다고 합니다. 그를 청산하고 그의 최신 맥주 샘플을 나에게 가져오세요."},objectives={{69,238826140},"서부 몰락지대의 죽음의 폐광에 침투하여 보스의 지글지글 맥주를 획득하세요."},progress={{52,2075719470},"시간을 낭비하지 마십시오. 나는 쇼 선생님만큼 인내심이 없어요."},completion={"By the mines of Kezan! This smells horrible. One whiff of it and any grown sailor will fall over in a heartbeat. $N, excellent job. While we were able to secure this end of the operations, we still have to investigate where exactly they're getting all the supplies from, as I am sure the Venture Co. is simply a middle man. Still, so far you did great and for that I've got a reward for you. Stay clear of trouble, adventurer, wouldn't want to see you getting killed.","케잔의 광산 옆에서요! 냄새가 끔찍해요. 그 냄새 한 번만 맡아도 다 자란 선원은 심장이 뛰는 순간 쓰러질 것입니다. $N, 훌륭해요. 우리는 작전의 최종 목표를 확보할 수 있었지만, Venture Co.가 단순히 중개자일 뿐이라고 확신하기 때문에 그들이 정확히 어디에서 모든 공급품을 가져오고 있는지 조사해야 합니다. 그래도 지금까지 잘 해냈고 그에 대한 보상을 받았어요. 모험가님, 문제를 피하세요. 당신이 죽는 것을 보고 싶지 않을 것입니다."}}
rows[50000]={title={{19,273314004},"말코비치 교수"},description={{156,252831948},"말코비치 교수님은 제 오랜 친구입니다. 그분이 해부학에 관심 있는 사람을 보내달라고 하셨죠. 언더시티의$B$B 약제상 맨 아래층에서 그분을 찾으실 수 있을 겁니다."},objectives={{75,2127984252},"언더시티의 약제실 맨 아래층에 있는 말코비치 교수에게 말을 걸어보세요."},completion={{43,1530499367},"훌륭해! 학생이구나! 내 말을 잘 들어봐..."}}
rows[50002]={title={{17,725858661},"인체 해부학"},description={{380,572719177},"오랫동안 언데드로 살아서 인체 해부학에 대해 몇 가지를 잊어버렸군. 옆방에 성가신 녀석이 하나 있는데, 그 녀석을 처리하고 머리를 가져와 줄래? 그래야 비명 지르지 않고 연구할 수 있거든. 걱정 마, 이미 우리에서 $B$B나왔어. 참, 머리를 잘 보관해서 가져다주면 인간으로 변장하는 법을 가르쳐 줄게."},objectives={{74,346805354},"성가신 농부를 없애버리고 그의 머리를 말코비치 교수에게 가져가세요."},progress={{49,1361803782},"어서! 그의 머리를 가져와! 시간이 없어."},completion={{152,813213364},"잘했어, 머리 상태는 완벽하군. 가까이 와 봐. 더러운 인간으로 변장하는 법을 보여주지.$B$B수업 노트 잊지 마!"}}
rows[50003]={title={{17,806937222},"파푸초 교수"},description={{156,471307747},"파푸초 교수님은 제 오랜 친구입니다. 그분이 제게 해부학에 관심 있는 사람을 보내달라고 하셨죠. $B$B아이언포지의 포를론 동굴 어딘가에서 그를 찾을 수 있을 겁니다."},objectives={{75,1674489288},"아이언포지의 황량한 동굴 안 어딘가에 있는 파푸초 교수와 대화해 보세요."},completion={{43,1530499367},"훌륭해! 학생이구나! 내 말을 잘 들어봐..."}}
rows[50004]={title={{18,2006496454},"오크족 해부학"},description={"Pssst… I've got a task for you, $C. Look behind me. I found this drunk orc spyin' around Ironforge and captured him, see? But I want to get a little “creative” with my payback. Bring me his head in good condition and I'll show you somethin' very worth your while.","쉿… , 자네에게 임무가 하나 $C있네. 내 뒤를 봐. 술 취한 오크 한 마리가 아이언포지 주변을 염탐하는 걸 발견하고 잡았거든. 그런데 복수를 좀 ‘창의적’으로 하고 싶어서 말이야. 그놈의 머리를 멀쩡한 상태로 가져오면 자네에게 아주 값진 걸 보여주지."},objectives={{71,942267049},"정신이 나간 오크족 하인을 죽이고 그의 머리를 파푸초 교수에게 가져오십시오."},progress={{81,1457099039},"뭘 기다리는 거야? 나 시간 없어, 임마. 술 취한 오크의 머리를 가져와."},completion={{464,509543594},"엄마는 늘 \"아껴 쓰면 부족함이 없다!\"라고 말씀하셨지.$B$B난 그 말을 마음속 깊이 새기고 내가 흉내 낼 수 있는 생물들을 \"재활용\"하기 시작했어. 고블린, 코볼드, 트로그 같은 것들 말이야.$B$B뭐, 내가 이 오크처럼 못 흉내 낼 거라고 생각하는 거야? 난 못할지 몰라도, 넌 분명히 할 수 있어.$B$B세상엔 재주만 있으면 할 수 있는 변장이 아주 많아. 가서 찾아보면 돼.\013\010이 메모를 잘 챙겨가고, 몸짓 게임에서 행운을 빌어!"}}
rows[50005]={title={{22,203943104},"올드 비긴스가 필요해"},description={{409,1464673804},"이 마법은 강력하지만, 자물쇠에 대한 제대로 된 기계적 이해가 없으면 세상에서 가장 열기 어려운 자물쇠도 열 수 없을 겁니다... 어쩌면 $B$B재능 있는 도적이나 대도적이 당신의 곤경을 해결해 줄 수 있을지도 모릅니다. 소문에 따르면 힐스브래드 구릉지 산기슭 북쪽 산맥 사이에 도적, 암살자, 그리고 비밀 요원들의 은신처가 있다고 합니다. 물론 그런 서비스를 받으려면 상당한 비용이 들겠지만요."},objectives={{83,681239933},"레이븐홀트 저택에서 올드 비긴스를 찾아 그의 가르침에 대한 대가로 금화 3개를 지불하세요."},completion={{232,1117488183},"나는 마법 냄새를 견딜 수 없어. 내가 널 도와주려면 내 시간과 네게서 풍기는 마법 냄새를 참아낸 것에 대한 정당한 보상을 받아야 한다는 걸 잘 알겠지? 돈을 내놓고 잘 들어. 그래야 내가 널 빨리 내보낼 수 있으니까!"}}
rows[50006]={title={{30,249810956},"빅긴스 아저씨가 또 필요해."},description={{216,929846733},"올드 비긴스를 기억하십니까? 힐스브래드 구릉지 구릉 북쪽 산맥 사이에 숨겨진 레이븐홀트 저택에 사는 제 친구 말입니다. 그는 금화를 더 주면 당신의 학습을 다시 도와줄 겁니다."},objectives={{91,1148727252},"레이븐홀트 저택에서 올드 비긴스를 찾아 다시 한번 그의 도움을 받아 학식을 쌓으세요."},completion={{87,1879446284},"또 너야!? 그 냄새... 돈만 주면 빨리 도와줄게. 다시는 안 오길 바란다!"}}
rows[50215]={title={{26,1362906155},"그림자 표범 가죽 장갑"},completion={{101,1684402494},"피의 동전 100개를 모으셨나요? 그렇다면 섀도우 팬서 가죽 장갑을 받으실 수 있습니다."}}
rows[50220]={title={{17,940433475},"노예의 밴드"},completion={{92,1821662430},"피의 동전 250개를 모았습니까? 그렇다면 노예의 띠를 얻을 수 있습니다."}}
rows[50227]={title={{19,833941558},"이상하게 거대한 알"},completion={{60,1316442230},"이미 크게 자란 무언가가 내부에서 나오고 있다..."}}
rows[50230]={title={{19,717510639},"밤의 탐험"},description={{557,988627162},"모험가여, 이리 $B$B오시오! 당신이 유능한 사람인 것을 보니 운명처럼 우리를 만나게 되었으니 유용한 것을 가르쳐 주겠소.$B$B 정글에서 살아가야 하니 도움이 될 만한 $B$B것이오! 저기 자킬리나에서 밧줄 하나, 무법항의 고블린들이 주는 기름 ​​하나, 그리고 캠프 주변에서 찾을 수 있는 두꺼운 곤봉 하나를 가져오면, 여행 중에 밤에 탐험을 하거나 야생 동물로부터 자신을 보호하는 데 사용할 수 있는 제대로 된 횃불을 순식간에 만드는 특별한 방법을 알려주겠소. 우리 캠프 근처에$B$B 있는 횃불들 보이지? 절대 꺼지지 않더오!"},objectives={{126,1433644219},"자퀼리나에서 밧줄을, 무법항에서 기름을, 캠프 주변에서 곤봉을 가져와 S. J. 얼가딘을 위해 네싱와리 탐험대에 전달하십시오."},progress={{32,578724376},"필요한 재료는 모두 모으셨나요?"},completion={{57,12502548},"아! 재료를 가져오셨군요. 훌륭합니다!$B$B잘 보세요!"}}
rows[50305]={title={{13,1100094958},"더 높은 위험 부담"},description={{439,1379892480},"이번엔 또 뭐야? 아, 또 너로군.$B$B 무슨 계란? 아, 맞다. 꼬리 채찍 악어 말이지. 계란 말고 다른 것도 요리하고 싶다고?$B$B 그럼 내가 가르쳐 줄 수 있지. 사우스퓨리 강이 어디에서 끝나는지 알아? 거기로 가야 해. 왜냐고? 자, 이제 판돈을 좀 더 높여 보려고! 악어 고기를 가져오면 제대로 요리하는 법을 가르쳐 줄게! 강가에 널려 있으니 어서 서둘러 가!"},objectives={{51,1092884460},"레이저 힐에 있는 토르카 요리사에게 악어 고기 8개를 가져다 주세요."},progress={{17,1737379887},"고기 가져왔어?"},completion={{206,1300441768},"좋아요.$B$B요리하려고 허둥지둥대기 전에 한 가지 알려줄게요. 고기가 익는 건 불의 크기가 아니라 양념의 양 때문이에요.$B$B뭐, 어쨌든 불은 필요하긴 하지만요…"}}
rows[50310]={title={{33,248197390},"고블린 공학 기술의 정수!"},description={"Ey, kid! Yes, you! I see you're an adventuring type and ready to jump into any fray if only there's one to jump into, right? Just as I thought. What? Of course there's a reward involved, how else could it be around here? It's a Mirage Raceway after all!$B$BWhat to do? Oh, that's so simple, I'm sure that even a gnome would manage to test our jolly vehicle on the sustain for … errh, durability conditions! Yes! So, if you're ready to earn some coins and crack some scorpids flat then you're at the right spot, kid! What helmet? Instruction? Bah! Who needs'em anyway?!$B$BYes, you might want to talk to our charming Dolores to register for the test race, $N.$B$BLet's blast it!","이봐, 꼬마! 그래, 너 말이야! 모험심 넘치는 녀석이군. 싸움만 있다면 뭐든 뛰어들 준비가 되어 있는 것 같아, 그렇지? 역시 내 생각대로군. 뭐? 당연히 보상이 있지, 그렇지 않고서야 어떻게 보상이 있겠어? 여긴 $B$B미라지 레이스웨이잖아!뭘 해야 하냐고? 아, 아주 간단해. 난쟁이라도 우리 멋진 차량의 내구성 테스트 정도는 거뜬히 해낼 수 있을 거야! 그래! 그러니 코인도 벌고 전갈도 박살낼 준비가 됐다면, 잘 왔어, 꼬마야! 헬멧? 설명서? 에이! 누가 그런 걸 필요로 해?!그래,$B$B 테스트 레이스에 참가하려면 우리 매력적인 돌로레스에게 말을 걸어봐,$N $B$B.자, 출발!"},objectives={{79,275943706},"돌로레스를 찾아 고블린 경주용 자동차를 타고 출발선에서 제대로 달릴 수 있는지 확인해 보세요."},progress={{83,825186815},"아, 드디어! 이 자료를 얼마나 기다렸는지 몰라요... 정말 고맙습니다, 진심으로 감사드려요."},completion={{118,1076562456},"데이터를 수집한 다음 처리해야 합니다. 이게 우리에게 얼마나 중요한지 아시겠습니까? 좋습니다. 그럼, 이제 어서 실행에 옮기세요!"}}
rows[50311]={title={{29,1563031322},"미라지 레이스웨이: 고블린 팀"},description={{246,867593041},"오, 살아 돌아와서 정말 다행이야! 물론 널 믿었지.자, 우리 $B$B고블린 공학 걸작을 다시 한번 시험해 볼 준비가 됐나 보군? 그럼, 요령을 알겠지? 그럼 어서 준비해서 또 한 번 1등을 차지해 봐!"},objectives={{47,1665317225},"데이지를 찾아 가장 빠른 기록으로 코스를 완주하세요."},progress={{83,825186815},"아, 드디어! 이 자료를 얼마나 기다렸는지 몰라요... 정말 고맙습니다, 진심으로 감사드려요."},completion={{118,1076562456},"데이터를 수집한 다음 처리해야 합니다. 이게 우리에게 얼마나 중요한지 아시겠습니까? 좋습니다. 그럼, 이제 어서 실행에 옮기세요!"}}
rows[50312]={title={{28,2041549837},"난쟁이들은 진정한 발명가입니다"},description={"I am sure that you're very well aware of the fact about us, gnomes, we're the best inventors. Assuming you're striving to improve your skills and knowledge you will eventually be considered to study from us. Obviously, no gnome is that stupid to decline this intriguing and exciting partnership, alas it might be costly sometimes.$B$BSpeaking shorter; we need someone to compliment our natural resourcefulness of brain activity with their muscle and durability!$B$BIf you successfully ride this awesome masterpiece of gnomish engineering any other dimwit goblin would simply call a race car then you will be granted an opportunity to represent our bright society of inventors even further in Mirage Races!$B$BCool, right?$B$BWell, here's the instructions we've specifically designed for other races for better understanding and comprehension.$B$BYes, you might want to talk to our charming Dolores to register for the test race, $N.$B$BGood luck, sentient one!","당신도 잘 알고 있듯이, 우리 드워프들은 최고의 발명가입니다. 당신이 기술과 지식을 향상시키고자 노력한다면, 언젠가는 우리에게서 배울 기회를 얻게 될 것입니다. 당연히, 이 흥미롭고 매력적인 제안을 거절할 만큼 어리석은 드워프는 없겠지만, 때로는 비용이 들 수도 있습니다. $B$B간단히 말해서, 우리는 타고난 두뇌 활동에 근육과 내구성을 더해줄 누군가가 필요합니다! 만약 당신이 다른 $B$B멍청한 고블린들이 그저 경주용 자동차라고 부를 만한 드워프 공학의 걸작을 성공적으로 운전한다면, 미라지 레이스에서 우리 뛰어난 발명가 사회를 더욱 널리 알릴 기회를 얻게 될 것입니다! 멋지지 않나요?$B$B 자, 다른$B$B 종족들이 더 잘 이해하고 따라할 수 있도록 특별히 제작한 설명서를 여기 첨부합니다. 테스트 $B$B레이스에 등록하려면 매력적인 돌로레스에게 문의하세요, N. 행운을 빕니다,$N$B$B 지성 있는 존재여!"},objectives={{78,1462013407},"돌로레스를 찾아 노움 경주용 자동차를 타고 출발선에서 과연 버틸 수 있을지 확인해 보세요."},progress={{50,103017108},"당연히 시동을 걸어야죠! 저어서 휘젓는 레버도 있고요!"},completion={{52,1796721626},"헬멧이요? 사용 설명서요? 에이! 그런 건 누가 필요로 하겠어요?!"}}
rows[50313]={title={{28,906452643},"미라지 레이스웨이: 그놈의 팀"},description={{500,1270043179},"존경하는 분, 안녕하십니까! 저희 기계 공학 장치 시험 운전에서 보여주신 결과에 매우 만족합니다. 분석에 필요한 귀중한 데이터를 제공해 주셔서 진심으로 감사드립니다. 저희 연구팀에 지속적으로 참여하실 수 있도록 허락해 드리고, 그에 대한 보상을 지급하기로 합의했습니다. $B$B데이터 수집을 진행하실 때는 제공된 지침과 권장 안전 수칙을 반드시 준수해 주시기 바랍니다. 좋은 $B$B하루 보내세요!"},objectives={{47,1665317225},"데이지를 찾아 가장 빠른 기록으로 코스를 완주하세요."},progress={{15,1390912922},"알겠습니다, 그렇죠?"},completion={{22,76875726},"페달을 바꾸지 마세요!"}}
rows[50315]={title={{31,1377393625},"가젯잔 타임즈: 속보!"},description={{366,1351766534},"자, 어서 가젯잔 타임즈 최신호를 구입하세요! 정말 놀라운 소식을 접하실 수 있습니다!$B$B뭐라고요? 아, 소식이… 정말$B$B 속보입니다!곧 여러분도 아시다시피 버섯구름 봉우리에 있는 반짝이는 평원에서 가장 모험심 넘치고 똑똑한 두 팀이 우주 전체에 알려진 ‘미라지 레이스’라는 매혹적인 경주에 참가합니다!"},objectives={{34,612562744},"가젯잔 타임즈 1호를 지금 바로 받아보세요!"},progress={{74,1957263489},"모든 고객님을 언제나 환영합니다!$B$B진심으로 감사드립니다. 최신 정보를 받아보세요!"},completion={{42,1127621156},"아무도 우리를 모른다는 게 무슨 말이야?!"}}
rows[50316]={title={{18,1815572317},"시간과의 싸움!"},description={{435,322173527},"하하하! 그들의 표정 봤어?! 정말 훌륭한 실력이야, $B$B친구! 자, 부끄러워할 필요 없어. 정말 잘했고, 시간 기록 경쟁에서는 더 잘할 수 있을 거야!$B$B 아주 간단한 임무야. 차에 올라타서 액셀을 밟고 최고 랩타임을 $B$B깨러 달려가면 돼! 양을 치거나, 길을 잃거나, 멈추지만 않으면 우승할$B$B 수 있을 거야! 상품이요? 물론이지. 걱정 마."},objectives={{97,1514885650},"최고 기록으로 레이스를 마치고 쉬머링 플랫츠에 있는 데이지에게 돌아와 보상을 받으세요."},progress={{71,1823131098},"정말 잘했어요! 다시 도전할 준비가 되면 꼭 돌아오세요!"},completion={{88,265286130},"아주 간단한 임무입니다. 차에 올라타서 가속 페달을 밟고 최고 랩 타임을 깨기 위해 질주하면 됩니다!"}}
rows[50318]={title={{22,763739457},"피할 수 없는 현실에 대비하기"},description={{698,1439983478},"우리가 이렇게 아름답게 장식된 소나무 주위에 모여드는 건 좋지만, 야생 동물들에게 심각한 문제가 닥쳐오고 있어요. 아시다시피, 우리가 살고 있는 생태계 전체가 일부 종들이 제 역할을 하지 못하게 되면 쉽게 파괴될 수 있죠. 제가 말하는 건 바로 달빛야수이에요. 아직 모르시는 분들을$B$B 위해 말씀드리자면, 우리는 달빛야수을 반드시 구해야 해요. \"어떻게?\" 무슨 말씀이세요? 우리가 뭔가 하지 않으면 어린 달빛야수들이 이번 겨울에 얼어 죽을 거예요... 아, 좋은 생각이 났어요!$B$B 따뜻한 에그노그를 가져다주는 거죠. 포옹도 좋지만, 무엇보다 에그노그를 가져다주는 게 중요하잖아요! 어디서 구하냐고요? 음, 분명 우리 레시피가 어딘가에 있을 거예요..."},objectives={{55,2053667981},"문킨 15마리에게 따뜻한 에그노그를 가져다 주세요."},progress={{38,1301910501},"문킨들에게 에그노그를 가져다주셨나요?"},completion={{82,900530419},"잘했어! 이제 우리는 반드시 버텨낼 거라고 장담할 수 있겠군!$B$B이거나 먹어라, 위대한 겨울의 아버지여!"}}
rows[50319]={title={{24,1300941042},"스노우볼 전쟁: 에피소드 1"},description={{81,2055967828},"겨울 축제 기간 동안 나열된 모든 직업의 플레이어에게 눈덩이를 던지세요."},objectives={{30,565790603},"평화는 애초에 선택지가 아니었다!"},progress={{9,696242909},"던져!"},completion={"Well done, $N.","잘했어요,$N."}}
rows[50320]={title={{25,772068494},"스노우볼 전쟁: 에피소드 II"},description={{81,2055967828},"겨울 축제 기간 동안 나열된 모든 직업의 플레이어에게 눈덩이를 던지세요."},objectives={{30,565790603},"평화는 애초에 선택지가 아니었다!"},progress={{9,696242909},"던져!"},completion={"Well done, $N.","잘했어요,$N."}}
rows[50321]={title={{14,755800070},"얼음의 위협"},description={{312,1695831288},"반짝이는 장갑을 잃어버린 나, 내가 가장 아끼던 장갑을 도둑맞았어. 아, 왜 눈물이 나지 않는 걸까?! 도둑놈들의 이름은 내 목록에 가득해. 얼어붙은 분노로 그들을 벌해라, 그들은 잘못을 저질렀으니! 이게 합법적이냐고? 내가 그렇게 만들겠다, 그것도 아주 빠르게! 나를 위해 이 일을 해 주면, 너를 위해 작은 나무 한 그루를 준비해 주겠다!"},objectives={{90,2128999628},"틴셀 로스트글러브스가 가장 아끼는 장갑을 훔쳐간 도둑들에게 복수할 수 있도록 도와주세요!"},progress={{9,696242909},"던져!"},completion={"Well done, $N.","잘했어요,$N."}}
rows[50322]={title={{14,1085019350},"수배: 하악스!"},description={{11,280453231},"하악스를 죽여라."},objectives={{324,1716929774},"최근 상상을 초월하는 악행을 저지른 흉악범이 목격되었습니다. 이러한 행위는 반드시 처벌받아야 합니다! 군과 왕실을 대표하여 이 자를 처단하라는 명령을 내립니다.\013\010\013\010용감하게 이 범죄자를 처치하는 자에게는 정당한 포상이 주어집니다.\013\010\013\010이름: 하악스\013\010\013\010포상: 평판 250점"},progress={{29,1610833496},"평화는 결코 선택지가 아니었다."},completion={"Well done, $N.","잘했어요,$N."}}
rows[50323]={title={{17,452047045},"거북이를 찾습니다!"},description={{14,831619},"거북이를 죽여라."},objectives={{327,227817005},"최근 상상을 초월하는 악행을 저지른 흉악범이 목격되었습니다. 이러한 행위는 반드시 처벌받아야 합니다! 군과 왕실을 대표하여 이 자를 처단하라는 명령을 내립니다.\013\010\013\010용감하게 이 범죄자를 처치하는 자에게는 정당한 포상이 주어집니다.\013\010\013\010이름: 터트\013\010\013\010포상: 평판 250점"},progress={{29,1610833496},"평화는 결코 선택지가 아니었다."},completion={"Well done, $N.","잘했어요,$N."}}
rows[50326]={title={{23,1084274996},"그리즐로어는 천둥을 원한다"},description={{144,564386745},"그리즐로어 - 나야! 술 더 줘! <딸꾹!$B$B>썬더… <딸꾹!> …맥주! 라거… <딸꾹!$B$B>그림부즈에서 잘 만들어. 거기 가 봐. 서부 몰락지대! <딸꾹!>"},objectives={{120,2048185403},"그리즐로어 퀘스트를 위해 웨스트폴의 그림부즈 썬더브루 또는 슬픔의 늪에 있는 여관 주인 카라쿨에게서 썬더브루 라거를 구입하세요."},progress={{80,885226175},"서부 몰락지대른 대거 힐즈는 그림부즈가 라거 맥주를 양조하는 곳이지… 어, 너 그거 가지고 있어?"},completion={{30,333070586},"크르릉!! 술 더 줘! 좋아!!"}}
rows[50328]={title={{25,457089002},"졸리 홀리 댄스 프롤리"},description={{421,1717681649},"어머, 예쁘고 귀여운 아가씨! 여기 있는 유쾌한 홀리와 함께 정말 재밌게 놀고 싶지 않아요, 자기?$B$B <웃음>물론이죠, 눈빛만 봐도 알겠어요. 하지만… 곧 엄청나게 짜릿한 즐거움이 기다리고 있다는 거 알고 있죠? 맛있는 음료와 술!홀리와 함께 즐거운$B$B 시간을 보내는 최고의 방법이죠!자,$B$B 마시고… 내 사랑스러운 아가씨, 달콤한 춤을 쭉 춰봐요! 하하!"},objectives={{54,1106146520},"홀리랑 같이 신나게 놀고 나서, 그녀와 춤을 춰."},progress={{18,1502974476},"윈터 베일과 결혼하세요!"},completion={{8,1660374930},"야아호!"}}
rows[50330]={title={{22,1215406078},"평화에는 대가가 따른다"},description={{278,1223603646},"그렘은 전사야. 내 임무는 보호하는 거야. 윈터 베일 베일이 위험에 처했어. $B$B무시무시한 늑대가 마을을 위협하고 있어. 며칠에 한 번씩 공격해 오거든. <그렘이 손가락 세 개를 보여준다.> $B$B넌 영웅 같아! 네가 도울 수 있어! 더 많은 용감한 전사들을 찾아! 스노볼이 자는 동안 공격해! 저기 아래에 있을 거야."},objectives={{70,411778442},"윈터 베일 베일 남쪽에서 거대한 다이어울프 눈덩이를 물리치세요."},progress={{48,160839945},"스노볼이 자는 동안 공격해! 저기 아래에 있어."},completion={{54,1889773842},"해냈군요! 정말 잘했어요! 존경과 감사를 표합니다!"}}
rows[50331]={title={{20,1574212456},"아리스토크세누스를 찾습니다!"},description={{17,697330558},"아리스토크세누스를 죽여라."},objectives={{347,877130065},"최근 상상을 초월하는 악행을 저지른 흉악범이 목격되었습니다. 이러한 행위는 반드시 처벌받아야 합니다! 군과 왕실을 대표하여 이 자를 처단하라는 명령을 내립니다.\013\010\013\010용감하게 이 범죄자를 처치하는 자에게는 정당한 보상이 주어집니다.\013\010\013\010이름: 아리스토크세누스, 종족: 인간, 레벨: 60\013\010\013\010보상: 평판 250점"},progress={{29,1610833496},"평화는 결코 선택지가 아니었다."},completion={"Well done, $N.","잘했어요,$N."}}
rows[50332]={title={{14,1237595980},"구함: 아즈텍!"},description={{11,433029861},"아즈텍을 죽여라."},objectives={{342,1596702632},"최근 상상을 초월하는 악행을 저지른 흉악범이 목격되었습니다. 이러한 행위는 반드시 처벌받아야 합니다! 군과 왕실을 대표하여 이 자를 처치하라는 명령을 내립니다.\013\010\013\010용감하게 이 범죄자를 처치하는 자에게는 정당한 보상이 주어집니다.\013\010\013\010이름: 아즈텍, 언데드, 레벨 60\013\010\013\010보상: 평판 250점"},progress={{29,1610833496},"평화는 결코 선택지가 아니었다."},completion={"Well done, $N.","잘했어요,$N."}}
rows[55000]={title={{14,1412604711},"라즐릭의 도구"},description={{544,835803322},"이봐, 너! 그래,$B$B 너! 내가 고쳐야 할 문제가 생겼는데, 확실히 말해줄게. 저절로 고쳐질 리가 없거든! 지금은 천국 같지만,$B$B 고블린들이 어떻게 사는지 알잖아. 결국엔 어떻게든 다시 그 석유 시추 플랫폼으로 돌아가게 될 거야. 문제는, $B$B투자개발회사 시절에 쓰던 공구 세트가 거기 있거든. 익숙해서 쓰고 있는데, 어떤 바다 생물이 그걸 물에 빠뜨려 영영 잃어버리는 건 절대 안 돼. 그러니까, 거기 올라가서$B$B 내 공구 좀 찾고 은화도 좀 챙겨 와, 어때, 꼬마야?"},objectives={{62,1355824231},"라즐릭이 잃어버린 도구는 항구 동쪽의 석유 시추 플랫폼에서 찾을 수 있습니다."},progress={{43,255172016},"벌써 구했어? 아니면 그냥 기다리고 있는 거야?"},completion={{181,828335127},"드디어 찾았네, 정말 놀랐어, 잃어버린 줄 알았거든!$B$B근데 내 공구를 더럽혔으니 은메달 하나 깎아야겠네, 기분 나쁘게 생각하지 마!"}}
rows[55001]={title={{21,950848288},"기름의 흐름이 멈춘다"},description={{615,78259949},"젠장, 빌어먹을, 멍청한, 아무짝에도 쓸모없는 놈들. 정말 끝내주지 않나? 저 석유 시추 시설 때문에 골치 아프기만 하고, $B$B벌써 일주일이나 뒤쳐졌어! 작업자 두 명이 바다에 빨려 들어가고 시추 시설이 바닷가재로 뒤덮인 걸 악몽이라고 안 부른다면, 넌 도대체 $B$B어디 출신인 거야! 석유는 계속 생산되어야 하고, 사장님이 이 사실을 알면 내 목을 $B$B칠 거라고! 누군가에게 책임을 전가할 수도 있겠지만, 우선 저기 가서 그 망할 생물들을 좀 없애버려야 해. 그래야 시추 시설을 다시 가동해서 밀린 작업을 만회할 수 있잖아!"},objectives={{85,2084420475},"항구 동쪽에 있는 석유 시추 플랫폼에서 마크루라 오일클로 5마리와 마크루라 스레셔 5마리를 처치하세요."},progress={{85,1034957943},"그것들을 처리했나요? 시간이 촉박해요. 플랫폼을 빨리 가동해야 하거든요!"},completion={{220,1067815719},"결국 계획을 세우긴 했는데, 화염방사기와 폭탄밖에 떠오르지 않았어. 석유 안전에 대해 조금이라도 안다면 절대 안 되는 물건이지!$B$B전부 다는 아니더라도 해산물이 조금 덜해지면 난 만족해!"}}
rows[55002]={title={{21,960071184},"항구로 물자를 공급"},description={{233,978145135},"너 레이저 힐에서 온 새 배달부니? 그 늙은 오크가 이렇게 빨리 주문을 받을 줄은 몰랐는데. 우리가 그 늙은이를 좀 괴롭혔다는 건 절대 말하지 마! 자기가 너무 잘한다고 생각할지도 몰라!"},objectives={{101,160764794},"봉인된 교역품을 레이저 힐 북동쪽에 위치한 인근 항구 도시 스파크워터로 배달하십시오."},progress={{48,371515979},"제가 도와드릴 일이 있었나요?"},completion={"You the new delivery $G boy:girl from Razor Hill? Didn't really think that old orc would get the order here that quick. You better not tell him we’ve just been giving him flak! He might start to think he's doing too good a job, or something!","너 레이저 힐에서 온 새 배달원 $G 소년/소녀 맞지? 그 늙은 오크가 이렇게 빨리 주문을 받을 줄은 몰랐네. 우리가 그 녀석을 좀 괴롭혔다는 건 절대 말하지 마! 자기가 너무 잘한다고 생각할지도 몰라!"}}
rows[55003]={title={{18,656314520},"새로운 에너지원"},description={{622,3088523},"기술자로서 우리 일은 모든 걸 제대로 돌아가게 유지하는 거잖아? 그런데 문제가 생겼어. 작은 문제라고 하지만, 사실은 큰 문제야! 플랫폼에서$B$B 석유가 안 들어오고 있어. 지금 있는 걸로 겨우겨우 버티고 있는 중이야! 게다가 석유통도 곧 바닥날 것 같아. 하지만 좋은 생각이$B$B 났어. 여기서 서쪽으로 멀지 않은 곳에 썬더 리지라는 곳이 있는데, 이름값을 톡톡히 하는 곳이야. 거기 있는 괴물들은 $B$B엄청난 힘을 가지고 있어! 걔네 에너지가 충전된 비늘 여섯 개만 구해 줘. 그걸로 에너지원을 만들어 보려고. 물론 걔네들이 비늘을 쉽게 내주지는 않을 테니, 힘을 좀 써야 할 거야!"},objectives={{154,2008750184},"서쪽 썬더 리지에 있는 번개 가죽과 천둥 도마뱀에게서 활성화된 비늘 6개를 모아 스파크워터 항구에 있는 기술자 스퍼즐에게 가져가세요."},progress={{58,774931816},"도마뱀 찾았어? 썬더 릿지에 있다고 했잖아!"},completion={{245,558813393},"<고블린은 재빨리 손에 넣은 비늘을 만지작거린다>$B$B이 녀석들 기운이 장난 아니군! 내 직감이 맞았어, 아마 효과가 있을 거야!$B$B오, 내가 수석 기술자로 승진할 확률이 확실히 15%는 올랐어!"}}
rows[55004]={title={{21,955839414},"약간의 따끔거림을 더하다"},description={"Hail, it is in times of peace that the body is set to engage within past-times of enjoyment. One such enjoyment for these goblins is that of eating, and eat they do, $R.$B$BAs much as they eat, I am still competing with the others around me, and I'm hoping to set myself apart.$B$BI have been wanting to experiment with new recipes from around the Barrens, and while I may never get tired of roasted boar meat, there is more I can do to make my food even more alluring.$B$BAll around Sparkwater Port there are Scorpids and Boars. Gather Chunks of Boar Meat and Scorpid Stingers from around the area and I will reward you for the effort.","안녕, 평화로운 시절에 몸은 즐거움을 누리기 위해 노력하지. 고블린들에게 있어 그러한 즐거움 중 하나는 먹는 것이지, 정말 많이 먹어. $R$B$B아무리 많이 먹어도, 난 여전히 다른 고블린들과 경쟁하고 있고, 남들과는 차별화된 모습을$B$B 보여주고 싶어. 불모의 땅 곳곳에서 새로운 요리법을 실험해 보고 싶었지. 구운 멧돼지 고기는 아무리 먹어도 질리지 않지만, 내 음식을 더욱 매력적으로 만들$B$B 방법이 더 필요해. 스파크워터 항구 주변에는 전갈과 멧돼지가 있어. 그 주변에서 멧돼지 고기와 전갈의 독침을 모아 오면 보상해 줄게."},objectives={{51,1767215898},"멧돼지 고기 5덩어리와 전갈 독침 5개를 모으세요."},progress={{40,1523953034},"제가 필요한 물건은 다 준비하셨나요?"},completion={{376,182468188},"하르고쉬는 음식을 천천히 준비하며, 온 힘을 다해 요리를 시작했다. 처음에는 끔찍한 냄새가 풍겼지만, 불이 붙으면서 점차 향긋해졌다. 얼마 지나지 않아 오크는 자신이 만든 음식을 한 입 베어 물었다.$B$B음... 좋아... 하! 딱이군. 오크 도끼처럼 강렬한 맛이야! 정말 고맙군."}}
rows[55005]={title={{18,929394868},"프로토타입 절도"},description={{512,894992565},"스니드와 나는 케잔에서 함께 일했던 친한 친구이자 동료였지. 그는 훌륭한 조수였어. 그런데 내가 그에게 준 돈에 만족하지 않았는지, 내 시제품 파쇄기 설계도를 훔쳐 달아났지! 이제야 겨우 여기서 모든 걸 정리할 $B$B시간이 생겨서, 그가 어디로 갔는지 알아내려고 지인들에게 몇 가지 부탁을 해 봤어. 그는 \"에드윈\"이라는 사람에게 고용된 것 같은데, 그 이후로는 소식이 끊겼더군. 시간은 $B$B돈이고, 그의 시간은 끝났어. 그를 찾아서 내 설계도를 되찾고, 나를 배신한 대가를 치르게 해야 해."},objectives={{61,215974617},"시제품 파쇄기 X0-1 설계도를 윅스 오즐넛에게 가져가십시오."},progress={{21,986419831},"그를 찾는 데 성공했나요?"},completion={{192,340741659},"잘했어. 그 사람이 직접 파쇄기를 만들었다고?$B$B역시 겉보기보다 똑똑했군. 널 포기하고 현상금까지 걸려고 했었는데. 현상금이나 받아가도 되겠어."}}
rows[55006]={title={{16,942869724},"백업 커패시터"},description={{828,230999952},"하마터면 큰일 날 뻔했어. 석유가 다 떨어지고 천둥 도마뱀 비늘에서 나오는 에너지도 거의 다 써버렸거든. \"전기 없이 일할 수 있다고?\" $B$B\"이봐, 여기 있는 대부분의 장비는 기름이 떨어졌을 때를 대비한 안전장치가 없어. 어떤 건 전원 버튼조차$B$B 없다고!\" \"이 마을은 시한폭탄이나 마찬가지야. 석유 시추 시설이 파괴되거나 다시 점령당하면 하늘 높이 폭발할 거라고. 그래서$B$B 비상 계획을 세워뒀지.\" \"있잖아, 그놈들이 비상시에 전체 설비에 몇 시간이고 전력을 공급할 수 있는 일종의 축전기를 발명했다는 소문을 들었어. 하지만 놈리건이 폭발해서 방사능에 오염된 후 그 축전기가 사라졌다는 얘기도 들었지. 그래서 아직 아무도 그걸 손에 넣지 못한 거였어.$B$B\" \"그곳에 가서 한번 찾아보는 게 어때? 친구들도 데려가 봐. 거기 뭐가 숨어 있을지 누가 ​​알겠어.\""},objectives={{52,752541966},"메가플럭스 커패시터를 그림즐로우 기술자에게 가져가세요."},progress={{67,1150532485},"시간이 촉박하고, 언제 스컬지이 닥칠지 아무도 모릅니다."},completion={{375,1353918147},"어떤 초록색 난쟁이가 그걸로 거대 로봇에 동력을 공급하고 있었다니? 정말 낭비야!$B$B<그림즐로우는 콘덴서를 집어 뒤에 있는 기계에 꽂는다.>$B$B자, 이 정도면 잘 작동할 거야. 폭발만 안 한다면 말이지. 수고해줘서 고마워. 보상으로 이 시제품 하나 가져가도 좋아. 그리고 갖고 싶으면 돌아가는 부품에 손가락 넣지 마."}}
rows[55007]={title={{25,2129482883},"새로운 방법을 찾아서"},description={{407,1813273701},"스파크워터의 기술자들은 아제로스 전역의 에너지원을 최적화하고 활용하는 더 나은 방법을 끊임없이 연구하고 있습니다. 현장에는 그 일을 하고 있는 사람들이 꽤 많죠! 아즈샤라에$B$B 있는 한 사람을 확인해 주셨으면 합니다. 마지막으로 목격된 곳은 발로르모크입니다. 그가 제가$B$B 맡긴 일을 제대로 하고 있는지 꼭 확인해 주세요. 고블린은 금화 낭비나 잠재력 낭비를 정말 싫어하거든요!"},objectives={{60,1860876879},"아즈샤라의 발로르모크 진영에서 가즈토글 크루파이프를 찾으세요."},progress={{23,638190843},"그를 찾으셨나요?"},completion={{250,916214164},"아즈샤라의 이 황량한 공허함을 좀 봐!$B$B주변에 아무것도 없다는 게 무슨 말이야? 내 말은, 여기선 아무도 일을 안 하고 있다는 거야. 이렇게 잠재력을 낭비하고 있잖아. 공장을 여기저기 세울 걸 그랬나, 내가 여기서 이렇게 시간을 보내고 있다니 참 안타깝네."}}
rows[55008]={title={{12,1288898633},"프릭스의 어리석음"},description={{649,1144089731},"아, 그래서 여기 오신 거였군요.$B$B.. 스파크워터에 필요한 새로운 에너지원을 찾으려고 연구하고 이것저것 실험하느라 정신이 없었습니다. 그런데$B$B 몇 가지 문제가 생겼는데, 주로 프릭스 때문입니다. 그가 며칠째 행방불명인데 소식이 전혀 없습니다. 게다가, 우리가 가진 유일하게 작동하는 측량 장비를 가진 녀석을 보냈는데 말이죠! $B$B마지막으로 들은 소식은 그가 남서쪽 근처 엘프 유적지로 가서 그 지역 사티로스 주변의 측량과 측정을 하러 갔다는 겁니다. 아마 죽었거나, 아니면 더 나쁜 상황으로 잡혔을지도 모릅니다! $B$B제발 그를 찾아주세요. 만약 그의 시신을 발견하게 된다면, 그와 함께 보낸 측량 장비를 꼭 찾아주세요!"},objectives={{48,461835310},"엘프 유적지 남서쪽에서 프릭스를 찾으세요."},progress={{23,477551492},"그 녀석 찾았어?"},completion={{235,1038680114},"이 죽은 고블린은 엘프 유적에서 죽은 고블린의 모습과 일치하는 것 같습니다. 온몸에 몸부림친 흔적, 멍, 그리고 자상이 있습니다.$B$B당신은 흩어진 뼈와 핏자국 속에서 측량 장비를 찾기 시작합니다."}}
rows[55009]={title={{12,1615409083},"빈손으로"},description={{196,1450857234},"프릭스 탤리코그의 시체와 주변 지역을 수색했지만, 회수해야 할 측량 장비의 흔적을 찾지 못했습니다. 조사 결과를 가즈토글 크루파이프에게 보고하십시오."},objectives={{60,524615855},"나쁜 소식을 전하기 위해 발로르모크에 있는 가즈토글 크루파이프로 돌아가십시오."},progress={{4,235686355},"흠?"},completion={{111,788521662},"아, 내 예상대로였군, 죽었어... 잠깐, 걔가 그걸 잃어버렸다고?!$B$B젠장, 프릭스, 이 망할 놈, 쓸모없는 놈..."}}
rows[55010]={title={{17,1266851839},"장비를 챙기기"},description={{468,248920639},"...으악! ​​저 멍청한 놈을 욕하며 시간을 낭비할 순 없어... 스파크워터의 고위 간부들이 내가 중요한 장비를 그놈 손에 넣었다는 걸 알기 전에 이 문제를 해결해야 $B$B해. 내 생각엔 측량 장비는 그놈이 죽은 곳에 아직 있을 거야. 사티로스들이 아마 그 장비를 빼앗아서 아직도 그 복잡한 고블린 기계가 뭔지 알아내려고 애쓰고 있을 테고, 아마 영원히 알아내지 못할 걸. $B$B그곳으로 돌아가서 내 고블린 측량 장비를 찾을 때까지 그놈들을 처치해!"},objectives={{68,1488015765},"할다르 야영지로 가서 고블린 측량 장비를 가져오세요."},progress={{38,1256890214},"측량 장비를 찾으셨나요?"},completion={{326,1937421474},"찾았어? 아...$B$B젠장, 짐 싸서 유배 갈 준비를 하고 있었는데, 정말 큰일 났네. 자, 이건 프릭스의 목걸이야. 떠나기 전에 나한테 줬는데, 금속 때문에 측량 장비가 고장 났대. 아마 불운이 깃들어 있을 거야. 절대 갖고 싶지 않아."}}
rows[55011]={title={{19,769449263},"비밀 결사를 고용하다"},description={{534,95974070},"안 좋은 일이야, 정말 안 좋은 일이군! 호드의 깃발 아래 안전할 줄 알았는데, 언더마인에서 옛 적이 우리 위치를 알아채고 찾아오려 한다는 소문이 들려와! 내 생각엔 좋지 않지만, $B$B외팔이 늙은 고블린 한 마리가 듀로타에 숨어 있는데, 만약 돈을 걸어야 한다면 (물론 돈 가지고 장난치진 않겠지만) 스파크워터에 있을 거라고 장담해. 이 종이 한$B$B 장과 동전 한 자루를 그에게 줘. 일을 맡기기 전에 돈을 주는 건 싫지만, 이번엔 어쩔 수 없어!"},objectives={{29,32287139},"듀로타르에서 그림 원암을 찾으세요."},progress={{42,1083775831},"어이, 어이, 그냥 가세요! 볼 거 없어요!"},completion={{188,1640942126},"날 더러운 자루에 넣고 기름칠이나 해! 난 모두가 날 잊어버린 줄 알았는데. 블래스텐톰이 이제 호드에 가담했다고? 그 편지 좀 보여줘 봐. 선불로 지불했다는 거야?"}}
rows[55012]={title={{27,1440915055},"5분짜리 짧은 모험"},description={{576,26485096},"보시다시피, 제 멍청한 파쇄기가 고장 났는데 고칠 부품이 없어요! 게다가 고향 사람들과 연락할 수단도 잃어버렸고요! 그래서,$B$B 잠깐 심부름 좀 부탁드려도 될까요? 별거 아닐$B$B 거예요. 네르트가 자기랑 다른 사람들이 정착했다고 한 새 곳에 필요한 건 다 있을 거예요. 아, 그렇게$B$B 쳐다보지 마세요. 당신이 제 도움이 더 필요한데, 거기까지 가는 게 그렇게 무리한 부탁은 아니잖아요. 걱정 마세요,$B$B 기다릴 수 있어요. 기름병이랑 구리관, 그리고 마법 가루만 좀 가져다주시면 나머지는 제가 알아서 할게요."},objectives={{47,633270119},"스파크워터 항구에서 필요한 물품들을 모으세요."},progress={{15,952892498},"정말 대단하네요!"},completion={{106,1469655613},"아, 괜찮아요. 필요한 물건은 다 챙겨주셨고, 생각보다 빨리 돌아오셔서 실망시키지 않으셨어요."}}
rows[55013]={title={{18,1789183018},"차가운 팔을 흔들다"},description={{447,1352393060},"내 슈레더가 고쳐졌으니 집으로 돌아가서 제일 아끼는 조수 중 한 명을 데려와 스파크워터에서 벌어지는 일에 도움을 줄 수 있겠군. 블래스텐톰에게 내가 간다고 전해 줘. 잘 곳 좀 마련해 두고 예쁜 고블린 아가씨들도 좀 데려와 둬야 할 거야. 새로운 $B$B프로젝트들을 진행하는 건 정말 재밌을 거야. 특히 그 못생긴 두꺼비 라즈덩크를 상대하는 일이라면 더더욱이지. 웩. 아, 그리고$B$B 블래스텐톰에게 꼭 상기시켜 줘. 내가 그를 돕긴 하겠지만, 그 호드 놈들에게는 아무런 빚도 없다고!"},objectives={{50,1614505098},"스파크워터 항구에 있는 네르트 블래스텐톰에게 보고하십시오."},progress={{18,1576814453},"그래서, 어떻게 됐어?"},completion={{181,1990152635},"그를 찾았을 뿐만 아니라 도와주겠다고까지 한다니? 좋아, 주머니를 뒤져봐야겠군.$B$B그는 돈을 펑펑 쓰는 사람이야! 하지만 그 미치광이가 만들어내는 것들은 그럴 만한 가치가 있지."}}
rows[55014]={title={{20,2021208252},"에테리얼 프로젝트"},description={{582,1811717157},"나와 프릭스는 아즈샤라에서 에너지원을 연구하는 데 꽤 많은 시간을 보냈어. 그리고 꽤 수익성이 좋은 사업이 될 만한 것들을 몇 가지 발견했지.$B$B 남서쪽에는 하이본의 죽은 유령들이 지키고 있는 듯한 폐허가 더 있어. 나는 이 $B$B영혼들을 에너지원으로 사용할 수 있을 거라고 생각해. 그들의 정수는 엄청나게 강력하거든. 유일한 문제는, 음, 그들에게서 그 정수를 얻는 거지.$B$B 그곳으로 가서 유령들의 정수를 모아 와. 도덕적인 건 신경 쓰지 마. 그들은 각자의 운명대로 갈 테니까! $B$B<가즈토글은 혼자 씩 웃었다.>"},objectives={{105,1001079695},"남서쪽으로 이동하여 하이본 유령과 하이본 리치링에게서 강력한 에테르 정수 8개를 모으세요."},progress={{38,269525013},"친구, 어서 유령 가루를 모으러 가!"},completion={{419,486354406},"드디어 알아냈군, 그렇지? 자, 이걸로 에너지를 좀 얻어낼 수 있는지 한번 시도해 보자.$B$B<가즈토글은 재빨리 작업을 시작하여 곧 여러 개의 작은 물체와 장치를 만들어냅니다. 그는 꽤 많은 양의 가루를 가져다가 기계 안에 하나씩 넣습니다. 몇 분 동안 시도해 보지만, 그는 정수를 사용하는 것을 포기하는 것 같습니다.>$B$B젠장! 이건 실제로 효과가 없는 것 같군. 다른 방법을 생각해 봐야겠어."}}
rows[55015]={title={{20,1556206770},"엘다라스 프로젝트"},description={{688,590480320},"늘 새로운 프로젝트들이 쏟아져 나오지만, 결국엔 쓸모없는 것으로 판명되곤 하죠!$B$B 이 지역은 저주받은 것 같아요. 아니면, 적어도 제 운이 지독해서$B$B 그런 걸지도 모르겠네요. 프릭스가 무덤에서 저를 괴롭히고 있지만, 그래도 몇 가지 프로젝트는 마무리 짓고$B$B 싶어요. 동쪽에는 고대 하이본 도시 엘다라스가 있습니다. 그곳에는 친절한 엘프는 없고, 뒤틀린 모습의 엘프들만 있을 뿐이죠... $B$B나가족이 유적의 거의 전체를 점령하고 있어요. 바로 그 때문에 저와 프릭스가 이 프로젝트를 추진하지 않았던 겁니다. 하지만$B$B 이제 당신이 있으니, 드디어 시험해 볼 수 있겠군요! 동쪽에 있는 엘다라스 유적지로 가세요. 그곳에서 엘다라스 레이 샤드라고 불리는 작은 에너지 조각들을 찾아보세요."},objectives={{64,941067193},"엘다라스 유적지로 가서 엘다라스 레이 샤드 5개를 찾으세요."},progress={{42,1590458674},"뭐야, 나가족이 너무 골칫거리야?"},completion={{370,2147463107},"무사히 돌아와서 다행이야. 자, 그 조각들은 가져왔나?!$B$B<고블린은 탐욕스럽게 지맥 조각들을 가져가서 이리저리 만지작거리기 시작한다. 얼마 지나지 않아 불안정한 조각들이 쩍쩍 소리를 내며 먼지로 변하기 시작한다.>$B$B젠장! 이 수정들은 쓸모없어, 쓰레기나 다름없어. 너무 불안정하고, 그것도 좋은 의미로 불안정한 게 아니잖아...$B$B머리를 좀 써야겠군."}}
rows[55016]={title={{22,1594495872},"스카이스토머 프로젝트"},description={{598,1563940394},"아즈샤라는 절망적으로 보이지만, 지금까지 온갖 방법을 다 써봤고 실패도 많았지만 아직 시도해 볼 만한 방법이 몇$B$B 가지 더 남아있어. 이 지역에는 썬더헤드라는 히포그리프 종이 있는데, 이 지역 곳곳에서 발견되지만, 진짜 힘을 가진 개체를 찾아야 최고의 결과를 얻을 수 있을 $B$B거야! 북동쪽, 아즈샤라 고원 가장자리 근처에는 썬더헤드 스카이스토머가 있어. 얘네들이야말로 썬더헤드 중에서도 최강자지. 스카이스토머 뿔 세 개를 가져와. 뿔에 힘이 집중되어 있을 거야. $B$B가져와 주면 에너지 관련 능력이 있는지 시험해 볼 수 있어."},objectives={{85,1697390614},"아즈샤라 북동쪽 먼 곳에서 썬더헤드 스카이스토머를 처치하여 스카이스토머 뿔을 획득하세요."},progress={{42,323426188},"뭐라고요? 그것들을 찾는 게 지겨워졌다고요?"},completion={"Ahh, took you long enough! Had trouble finding the blasted things? Oh well, gimme!$B$B<Gazztoggle takes the Antlers from you, quickly moving to test their power.>$B$BYes! Finally something! Who would have guessed this would be worth our time...$B$BThanks again, $N, for all you've done.","아, 오래 걸렸군! 그놈의 물건 찾는 데 애먹었어? 뭐, 괜찮아, 줘!$B$B<가즈토글이 당신에게서 뿔을 받아들고 재빨리 그 위력을 시험해 봅니다.>$B$B그래! 드디어 뭔가 찾았군! 이게 이렇게 가치 있는 일이 될 줄 누가 알았겠어...$B$B다시 한번 고마워,$N, 그동안 해준 모든 일에."}}
rows[55017]={title={{21,999022779},"스파크워터로 보고"},description={{398,87573435},"아... 드디어 보고할 게 생겨서 기분이 좋네요. 그림즐로우는 제가 이렇게 오래 걸린 걸 보면 꽤 화가 났을 게 분명해요! 스파크워터의$B$B 윗사람들이 보고서를 필요로 할 테니, 제가 여기서 일을 계속하는 동안 그쪽에 보고서를 보내주세요!$B$B 덕분에 제가 일을 계속하고 월급도 받을 시간을 벌 수 있겠네요! 어쩌면$B$B 프릭스처럼 끔찍한 사람이 아닌, 괜찮은 새 조수를 얻을 수도 있겠어요."},objectives={{37,135475611},"가즈토글의 보고서를 그림즐로우에게 가져다 주세요."},progress={{19,1282507901},"그는 스파크워터에 있어요!"},completion={{292,244346906},"아, 내가 자네를 아즈샤라로 보내지 않았나?$B$B설마 이 모든 시간 동안 선술집에 있었던 건 아니겠지!$B$B이건 가즈토글이 보낸 메시지야. 스파크워터의 돈을 가지고 도망쳤다고 생각해서, 사람들을 불러 모아 제대로 혼내주려고 했었지.$B$B그래도 뭔가 괜찮은 결과를 얻은 것 같군."}}
rows[55018]={title={{22,352623710},"빅 에너지 프로젝트"},description={{761,1298561608},"제게는 '대규모 에너지 프로젝트'라고 이름 붙인 마지막 프로젝트가 하나 있습니다. 이 프로젝트는 얼마 전 남동쪽 메나르 호수 주변에 나타난 푸른 용군단과 관련된 것입니다. 용들이$B$B 이런 일에 얽히는 경우는 흔치 않지만, 제가 알기로는 이 푸른 용들은 마법을 아주 좋아하거든요! 용족의$B$B 지팡이를 손에 넣을 수만 있다면, 얼마나 많은 가능성이 열릴지 상상해 $B$B보세요! 발로르모크의 오크들이 그들의 존재와 새로 부임한 중위에 대해 조금씩 이야기하고 있습니다. 다행히 제 긴 귀 덕분에 그 작은 정보까지 들을 수 있었죠! 그 중위를 찾아가서 그의 지팡이를 빼앗으세요. 분명 지팡이가 필요할 겁니다! 자, 친구들이나 동료 모험가들을 모으세요. 이건 혼자서는 할 수 없는 큰 작전이 될 겁니다."},objectives={{96,2081185145},"남동쪽에 있는 메나르 호수로 가서 그곳에 있는 중위에게서 아즈살루스의 지팡이를 가져오십시오."},progress={{69,699396395},"뭐라고요? 우리는 지금 위대한 성공을 눈앞에 두고 있는데, 그 인재들을 꼭 확보해야 해요."},completion={{221,706565913},"잠깐... 정말 해냈다고?$B$B드래곤킨을 그런 식으로 방해하다니 믿을 수가 없어! 하하!$B$B이 지팡이만 있으면 스파크워터에 몇 주 동안 전력을 공급할 수 있고, 어쩌면 여기에 내 가게까지 차릴 수 있을지도 몰라...$B$B자, 이거 받아!"}}
rows[55019]={title={{13,1830994081},"사라진 피"},description={{849,316479019},"제 동생이 최근 우리 병력의 최전방인 스토나드 진영으로 파견되었습니다. 대족장의 뜻을 제가 거스를$B$B 수는 없지만, 동생이 건강하고 튼튼하다고는 하지만 그곳에서 안전할지 걱정됩니다. 잦은 파병으로 서로 만나지 $B$B못한 지 벌써 몇 달이 지났는데, 하필이면 슬픔의 늪으로 가게 되다니요. 그나마 다행인 건 동생이 그곳 주둔지에서 $B$B중요한 직책으로 승진했다는 겁니다. 최전선이 아니라 부하들을 지휘하고 있을지도 모른다는 생각에$B$B 마음이 놓입니다. 동생이 나보다 더 중요한 존재가 되는 걸 보는 건 묘한$B$B 기분이지만, 어쩔 수 없죠. 의무가 우리를 부르고, 우리 모두 각자의 역할을 다해야 하니까요. $B$B부디 스토나드 슬픔의 늪에서 줄을 찾아 이 편지를 전해 주십시오."},objectives={{43,941715031},"스토나드에 있는 주울에게 루그나르의 편지를 전달하세요."},progress={{54,1655053138},"안녕하세요, 처음 오신 분. 스토나드에는 무슨 일로 오셨나요?"},completion={{60,1613636106},"줄을 찾으시는 건가요? 네, 바로 저입니다. 그런데 이게 뭐죠?"}}
rows[55020]={title={{15,2092650677},"잘못 얻은 명예"},description={{701,1417236887},"음, 좀 난감하군. 내 과장된 말이 엉뚱한 사람 손에 들어가 사태를 악화시킨 것 같군. 형 눈에 $B$B좀 더 성공한 사람이 되고 싶었는데, 형은 상인으로 꽤 잘 살고 있지만, 난 오그리마를 위해 수년간 봉사했지만 여전히 보병 신세에 머물러 $B$B있구나. $B$B(줄은 한숨을 쉬었다.) 솔직히 말해야겠군. 특히 동족에게는 정직하는 게 명예니까. 겉치레로$B$B 포장하려는 건 동맹 외교관이나 하는 짓이지, 듀로타르의 아들들이 할 짓이 $B$B아니지. 직접 가서 사과하고 싶지만, 그럴 수가 없군. 짧은 시간 안에 처리해야 할 일이 $B$B너무 많아. 지휘관에게 듀로타르에 잠시 다녀오고 싶다고 전해 주시오."},objectives={{53,302140486},"스토나드 요새에 있는 파견 사령관 루아그에게 말을 걸세요."},progress={{58,473978078},"그는 야영지 내의 큰 건물 안에 있습니다."},completion={{71,343694217},"루아그 사령관에게 무엇을 원하시는 겁니까? 중요한 일이어야 할 겁니다."}}
rows[55021]={title={{16,2057841035},"벽 너머"},description={"So, Zuul sent you? He wants to leave Stonard, that's it?$B$BHeh, well I'll make you a deal $R. Zuul has been an obedient grunt, one that listens well and does well when called upon, it's the only reason I'm offering this. You do a task for me, and I'll give him leave for a few days.$B$BThe local wildlife has been a continuous thorn in our side. There is no other presence than the large beasts that dwell within the shadows beyond the light of our torches.$B$BI've had orcs go missing and not turn up late at night, and there is no doubt in my mind that the beasts outside our walls are responsible.$B$BClear out the area outside our walls of what you find: jaguars, spiders and crocolisks. Make sure to thin their numbers.","그래서, 주가 당신을 보냈습니까? 그가 스토나드를 떠나고$B$B 싶어한다는 겁니까? 흠, $R좋습니다. 거래를 하나 제안하죠. 주는 순종적인 부하였고, 명령만 잘 듣고 시키는 일도 잘 해냈습니다. 제가 이런 제안을 하는 유일한 이유입니다. 당신이 제 부탁을 들어주면, 그에게 $B$B며칠 휴가를 주겠습니다. 이 지역의 야생 동물들이 우리에게 끊임없는 골칫거리였습니다. 우리 횃불 너머 그림자 속에 숨어 있는 거대한 짐승들 외에는 아무것도 보이지 $B$B않았습니다. 오크들이 밤늦게까지 사라지고 돌아오지 않는 일이 있었는데, 저는 우리 성벽 밖의 짐승들이 그 원인이라고 확신합니다. 성벽 밖에서$B$B 발견하는 모든 것을 제거해 주십시오. 재규어, 거미, 악어 등을 말입니다. 개체 수를 줄이는 것도 잊지 마십시오."},objectives={{113,1683854212},"어린 톱니악어 6마리, 슬픔방패 8마리, 늪재규어 8마리를 처치한 후, 지휘관 루아그에게 돌아가십시오."},progress={{42,136644376},"이 늪지는 이름값을 톡톡히 하죠, 그렇지 않나요?"},completion={{73,2007305351},"잘 해낸 것 같군. 오크들이 덜 사라지니 기쁘군."}}
rows[55022]={title={{12,1288019799},"휴가 신청"},description={{302,1595729789},"아... 좋아, 줄을 처리하도록 조치를 취하겠어. 사령관이라는 직책을 유지하려면 내 약속을 지켜야지.$B$B 줄에게 오그리마로 3일간 휴가를 주겠다고 전해. 넷째 날에는 스토나드로 돌아올 수 있도록 조치를 취해줄게. $B$B그리고 이 3일을 잘 활용하라고 전해줘."},objectives={{22,884035894},"그런트 주울과 대화하세요."},progress={{36,2101899151},"내 동생 소식 들었어?"},completion={{274,1512480842},"정말요? 사실 갈 기회가 생길 거라고는 생각도 못 했어요.$B$B이건 저에게 정말 큰 의미가 있어요. 잘못된 것을 바로잡고 옳은 일을 할 수 있는 기회니까요.$B$B형제 사이에 경쟁은 없어야 한다는 걸 깨달았고, 이 편지를 통해 우리가 누구인지에 대해 자부심을 가져야 한다는 걸 다시 한번 알게 됐어요."}}
rows[55023]={title={{18,1262335271},"구호와 재발견"},description={{338,1121529106},"친구, 마지막으로 부탁드릴 일이 하나 더 있습니다. 잠시만 더 도와주시면 정말 $B$B감사하겠습니다. 저는 아직 여기서 좀 더 기다려야 할 것 같습니다. 이 편지를 받아 제 동생에게 제가 곧 도착한다는 소식을 전해 주시면 정말 감사하겠습니다. 다시 한번 고맙습니다,$B$B 친구. 혈연과 명예를 걸고."},objectives={{60,652690719},"스파크워터 항구로 가서 루그나르에게 줄의 쪽지를 전달하세요."},progress={{67,1697647168},"내 메시지가 그에게 전달되었을지 궁금하네요. 어서 그를 만날 수 있으면 좋겠어요..."},completion={{221,1700661703},"어머, 편지였군요?$B$B<루그나르는 집중해서 읽기 시작한다.>$B$B뜻밖의 소식이군요. 그동안 해주신 모든 일에 감사드립니다. 이렇게 빨리 답장을 받을 줄은 전혀 예상하지 못했습니다. 수고에 대한 보답으로 이 편지를 받겠습니다."}}
rows[55025]={title={{10,552196161},"건조 은폐"},description={{468,716703994},"여기서 미쳐버릴 것 같아. 브라이트워터 호가 포탄에 몇 발 맞아서 한동안 지붕 아래에서 지내라는 말을 들었거든. 며칠째$B$B 피난처에 갇혀 있으니 정신이 나갈 것 같아! 아, 술 좀 구할 수만 있다면… 잠깐, 술 구할 수 있지? 우리가 구할 수 $B$B없으니, 솔티 세일러에 가서 다음 술 좀 사다 줘… 흠… 버번 위스키 $B$B5병\013\010미드 3병\013\010포트 와인 10병\013\010…그리고 체리 그로그 10병!"},objectives={{137,1499738199},"샬그리그 파이프샤크와 브라이트워터 선원들을 위해 버번 위스키 5병, 미드 3병, 포트 와인 10병, 체리 그로그 10병을 모아주세요."},progress={{41,1750974875},"술은 가져왔어? 우리 여기서 죽어가고 있어!"},completion={{82,2071119759},"아! 정말 오랜만에 술을 마시네요! 덕분에 살았어요."}}
rows[55026]={title={{25,1535600448},"모든 것이 가라앉는다"},description={{556,404422430},"이봐, 조심해! 지금 보고 있는 건 브라이트워터호의 선장이야. 호드 기준으로 보면, 이 배는 바다를 항해했던 가장 훌륭하고 강력한 배 중 하나지! 아.$B$B.. 정말 아름다운 배였는데, 그 빌어먹을 블러드세일 해적들이 우현에 포격을 가해 침몰시키기 전까지는 말이야. 솔직히 말해서, 2대 1 싸움은 너무 $B$B불공평했어. 내 선원들은 아직 무법항에 숨어 있는데, 정확히 어디 있는지 $B$B모르겠어. 거기 영주인 옛 친구 레빌가즈에게 부탁할 게 하나 있어. 내가 보냈다고 하고 내 선원들을 찾아줘."},objectives={{62,1952621966},"무법항 항구로 가서 레빌가즈 남작과 대화하십시오."},progress={{44,1022482291},"제가 도와드릴 일이 있을까요?"},completion={{237,1544160573},"네? 아... 그가 당신을 보냈군요?$B$B그 바보는 돈 때문에 호드에게 도움을 주려다가 이 지역 해적들을 얕봤고 결국 자기 배를 침몰시켰죠.$B$B이제 옛날 일을 들먹이려 드는군, 하하. 어서 끝내버리자."}}
rows[55027]={title={{13,956745411},"고용 도우미"},description={{670,558785840},"내가 가진 정보를 주기 전에, 대가로 뭔가를 받아야겠어. 그가 말하는 \"부탁\"은 들어주겠지만, 뭔가를 처리해 줘야 해. 벤처 $B$B컴퍼니가 여기서 문제를 일으키고 있는데, 주로 내 사업을 가로채서 자기들 몫을 챙기고 있어. 자네가 나서서 은밀하게 처리해 줬으면 하는 게 있어. 그들이 내 사업에$B$B 간섭하고 있는데, 나도 그들의 사업에 간섭하고 싶어. 물론 비밀리에 말이지. 나즈페리티 호수 근처$B$B 북동쪽으로 멀리 가 봐. 믿을 만한 소식통에 따르면 그들이 거기에 석유 시추 플랫폼을 설치하고 있다고 해. 거기에 투입된 정비공들을 몇 명 제거해 줘. 그러면 그들에게 엄청난 시간과 돈을 뺏길 수 있을 거야."},objectives={{69,1297486930},"킬 5 벤처 컴퍼니 정비공들이 나즈페리티 호수 근처 석유 시추 플랫폼에서 작업 중이었다."},progress={{40,449241871},"당신이 그들의 계획에 차질을 일으켰나요?"},completion={{147,1716590085},"그들은 자신들의 것이 아닌 것들을 함부로 만져왔으니, 이제 그 대가를 치를 때가 되었다. 그리고 그 대가는 나와는 절대 연관시킬 수 없을 것이다."}}
rows[55028]={title={{17,197823114},"\"히든\" 크루"},description={{547,1678363478},"좋아, 그럼 이 부탁이나 들어주고 다음으로 넘어가자. 우리 둘 다 시간을 쓸 만한 더 유익하고 보람 있는 $B$B일들이 많으니까. 브라이트워터호 선원들은 줄곧 여기 있었고, 그 불꽃놀이 같은 전투 후에 그들이 나타난 첫날 밤부터 알고 있었어. 그들이 $B$B정체를 숨기는 데는 그다지 능숙하지 못했지. 게다가 내 정보망은 아주 믿을 만하거든. 위그칙이 머무는$B$B 무법항 아래층에서 그들을 찾을 수 있을 거야. 다음에 $B$B\"캡틴\" 파즐을 만나면, 그의 시시한 부탁을 들어줬다고 전해줘."},objectives={{66,1214782520},"브라이트워터호 선원들은 무법항 하층에서 찾을 수 있습니다."},progress={{4,273767400},"예?"},completion={{60,876737689},"이봐, 우리에겐 여분의 구리가 더 이상 없어. 그러니까 꺼져."}}
rows[55029]={title={{22,2003102724},"정보가 필요"},description={{735,1059238659},"선장님이 보내셨다고요? 다행이네요. 거의 일주일 동안 아무 소식도 없이 여기서 발만 동동 구르고 있었거든요. 부티 $B$B베이에서 탈출할 방법을 생각해 보려던 참이었는데, 브루저들만이 우리를 지켜주고 있는 것 같습니다. 블러드세일 해적단은 우리가$B$B 그들의 배 한 척을 격침시킨 이후로 우리를 죽이려고 혈안이 되어 있습니다. 운 좋게도 그롬골 근처에서 매복 공격을 당했죠! 그들은 우리를 모두 $B$B없애버리려고 하고, 우리가 죽을 때까지 멈추지 않을 것 $B$B같습니다. 블러드세일은 조직이 제대로 갖춰지지 않은 집단입니다. 각 야영지나 배마다 선원과 지도자가 있고, 우리를 쫓는 이 무리는 우리가 그 지도자의 동생을 죽였기 때문입니다. 만약 누군가 이 일에 $B$B대해 알고 있다면, 레빌가즈일 겁니다."},objectives={{24,1761985523},"레빌가즈 남작과 이야기하십시오."},progress={{4,273767400},"예?"},completion={{77,1176517579},"또 너야? 설마 파즐이 또 뭘 요구하러 온 건 아니겠지?"}}
rows[55030]={title={{21,1042369978},"정보 획득"},description={{703,621961947},"파즐과 그의 일당은 정말 곤경에 처했지만, 블러드세일 해적단이라는 악당들을 상대해야 한다면 기꺼이 도와주겠다! 그들에 대한 단서는 많지만, $B$B브라이트워터 선원들의 유해를 찾는 작전을 누가 지휘하는지는 확실히 모르겠다. 하지만 아는 사람이$B$B 한 명 있다. 무법항 외곽에 내가 오랫동안 알고 지낸 정보원이 있는데, 그 해적단과 연루되어 도시에서 쫓아냈다. 내가 그들의 목숨을 구해줬으니,$B$B 그들은 내게 빚을 졌다. 블러드세일 배신자를 찾아서 레빌가즈가 부탁한다고 전해라. 그 정보를$B$B 얻으면 브라이트워터 선원들에게 알려주고, 알아서 처리하게 놔두도록 해라."},objectives={{119,546737159},"무법항 외곽에 있는 블러드세일 배신자에게서 정보를 얻고, 무법항 아래쪽에 있는 샬그리그 파이프샤크로 돌아가십시오."},progress={{34,358744580},"그래서... 뭔가 알아낸 게 있나요?"},completion={{139,706494276},"휴, 정말 다행이다! 누가 우리를 쫓는지 찾는 건 바다에서 물방울 하나 찾는 것만큼 어려울 줄 알았는데, 드디어 찾았네!"}}
rows[55031]={title={{17,726151345},"소금 이빨을 부숴버려!"},description={{482,1962481933},"그 근처에는 캠프가 하나밖에 없는데, 바로 솔트투스 선장이 있는 곳이겠군! 우리가 이 $B$B마을에서 나가려면 그놈을 없애야 해! 그러니까 도와줄 거지? 구루바시 투기장 근처 북쪽으로 가. 투기장 바로 $B$B남쪽, 서쪽 길가에 블러드세일 캠프가 있어. 거기서 솔트투스 선장을 찾아 죽이고, 그의 머리를 가져와. 그래야 일이 끝났다는 걸 알 수 있으니까. 아, 그리고 친구들도 데려와. 그놈은 꽤 많은 부하들을 거느리고 있을 거야!"},objectives={{74,1521005115},"솔트투스 선장을 죽이고 그의 머리를 증거로 샬그리그 파이프샤크에 가져오십시오."},progress={{50,1777002193},"그를 찾기 어려우신가요? 저도 그래요."},completion={{159,940705338},"<고블린이 오크의 머리를 응시한다.>$B$B와, 솔트 투스를 쓰러뜨리려면 꽤 많은 병력이 필요했겠군. 아니면 네가 생각보다 훨씬 강한 거겠지!"}}
rows[55032]={title={{18,1344896247},"광기에 빠지다"},description={{724,1269143409},"내 동족은 광기와 정신착란, 그리고 허무맹랑한 악몽에 사로잡혀 피에 굶주려 있습니다. 마치 그림자가 $B$B그들의 정신을 흐리게 하고, 모든 명료함을 가로막는 것 같습니다. 한때 알았던 $B$B사람들을 더 이상 알아보지 못하는 고통을 아십니까? 친구의 얼굴을 바라보아도, 마치 낯선 언어를 말하는 것처럼 야만적인 모습 외에는 아무것도 알아볼 수 없는 고통을 아십니까? 내 $B$B친족은 사라졌고, 이 숲 속에 더 이상 집이 없다는 사실을 인정하는 것은 너무나 고통스럽습니다. 이 광기를 멈추고 모든 것을 끝내기 위해 무언가를 해야 합니다.$B$B 바로 남쪽에 있는 그린포 마을로 가서, 한때 내 고향이었던 곳에 숨어 있는 파울위얼드 주술사들을 몰아내 주십시오. 그들은 예전의 모습이 아니며, 공포를 영속시키고 있습니다."},objectives={{56,27739071},"그린포 마을로 가서 파울웰드 샤먼 3명을 처치하세요."},progress={{93,1848494230},"아무 조치도 취하지 않으면 내 친구들과 친척들이 무고한 사람들을 무참히 학살할 것이다. 반드시 조치를 취해야 한다..."},completion={{247,726989435},"이 비극적인 결말을 상상하니 마음이 너무 아픕니다. 한때 아름다웠던 이 숲에는 더 이상 빛조차 남아 있지 않은 것 같습니다. 고통받는 이들의 마음을 달래주셔서 감사합니다. 어쩌면 저 세상에서라도 마음의 평안을 찾을 수 있을지도 모르겠습니다. 이것을 받아 가세요. 저는 더 이상 필요하지 않습니다."}}
rows[55035]={title={{20,1273674928},"숨겨진 보상"},description={{309,313138306},"고울팽, 네가 정말 잘해줬구나! 다른 어떤 놀도 나에게 이렇게 해준 적이 없었어! 모스하이드가 얼마나 훌륭하고 강한 놀인지 보여주려고 선물을 줄게! 댐$B$B 아래쪽 속이 빈 나무에 보물상자를 묻어두었으니, 누가 훔쳐가지 않았다면 아직 거기 있을 거야. 네가 찾으면 보물이 들어있지. 고울팽, 안에 뭐가 들어있는지는 필요 없어. 전부 네 거야."},objectives={{52,98138190},"숨겨진 이끼가죽 상자를 찾아 보상을 획득하세요."},progress={{79,825601435},"속이 텅 빈 나무 안에는 이상한 모양의 작은 진흙 더미가 보인다."},completion={{135,160250053},"진흙 속에서 무언가 반짝이는 것을 발견합니다. 이것이 바로 고울팽이 말했던 것임이 틀림없습니다. 더 자세히 살펴보니 마침내 보상을 얻게 됩니다."}}
rows[55036]={title={{21,808841123},"내 예티 털은 어디 있지?!"},description={{504,1957555011},"이봐, 배송이 늦어졌는데 빨리 처리해야 해. \"처리\"라는 건 최대한 빨리 고치라는 뜻이야. 타를로 $B$B파크랙은 내가 그 빌어먹을 예티 털을 받으면 일자리를 잃게 될 거야. 거의 일주일 전에 그를 그곳으로 보냈는데, 지금쯤이면 도착할 거라고 약속했었거든.$B$B 스파크워터에 대해 한 가지 알아둬야 할 게 있다면, 라즈에게 지킬 수 없는 약속은 하지 말라는 거야. $B$B힐스브래드 구릉지 산기슭에 있는 타렌 밀로 가서 이 예티 문제를 해결해. 그리고 일이$B$B 끝나면 타를로에게 이제 끝났다고 전해줘."},objectives={{41,610851816},"타렌 밀에 있는 타를로 파크랙과 대화하세요."},progress={{52,3117645},"어, 어디 있지...? 네?$B$B제가 지금 얼마나 바쁜지 안 보이세요!"},completion={{170,577318553},"...라즈가 보냈다고요? 오, 제발 제 무릎은 부러뜨리지 마세요! 그것만은 안 돼요...$B$B잠깐, 예티 털 처리하는 걸 도와주러 오셨어요?$B$B와, 다행이네요! 도움이 절실했거든요."}}
rows[55037]={title={{19,71834663},"밀린 주문 처리"},description={{495,1545112471},"도움이 절실히 필요해! 믿을 만한 공급책에게서 $B$B예티 털을 주문했는데, 그 사람이 갑자기 사라져 버렸어! 친구, 제발, 내 무릎을 지키고 $B$B아제로스에서 사라지지 않도록 도와줘. 정말 큰 도움이 될 거야. 남서쪽에 예티로 가득 찬$B$B 동굴이 있어. 거의 꽉 찼다고 해도 과언이 아니야. 예티 털 열 개만 구해다 줘. 라즈에게 가져다주기엔 충분할 거야. 그리고 제발, 빨리 와 줘! 시간이 없어! $B$B예티 털을 구해왔군. 라즈에게 보낼 수 있도록 빨리 포장해 줄게!"},objectives={{48,1949548966},"예티 털 10개를 모아서 타를로 파크랙에게 돌아가세요."},progress={{39,572033836},"예티 사냥에 성공하셨나요?"},completion={{74,90891554},"예티 모피를 구하셨군요! 라즈에게 보낼 수 있도록 얼른 포장해 드릴게요!"}}
rows[55038]={title={{15,699270432},"늦은 배송"},description={{295,1356431450},"자, 이제 포장 다 끝났습니다. 이 상자를 스파크워터 항구에 있는 라즈 씨에게 가져다 주시고, 늦어서 죄송하다고 전해주세요. 늦은 것에 대한 보상으로 약간의 돈도 넣어 두었습니다! 다시 한번 $B$B도와주셔서 정말 감사합니다. 당신이 없었더라면 훨씬 더 힘들었을 거예요."},objectives={{37,241102188},"타를로의 상자를 상인 라즈에게 가져다 주세요."},progress={{56,574613827},"스파크워터에 다시 오신 것을 환영합니다. 타를로 문제는 해결하셨나요?"},completion={{328,1288892937},"아, 너무 오래 걸렸군. 다시는 그 녀석이랑 거래 안 할 거야. 정말 형편없는 계약자야.$B$B고블린이라면 절대 늦으면 안 된다는 걸 알아야지, 특히 나랑 있을 때는 더더욱. 자, 여기, 이 모피를 구해다 준 공로로 그가 준 추가 금액.$B$B틀림없이 네가 이 모피를 여기까지 가져다준 거겠지. 네가 아니었으면 이 고급 망토들을 못 받았을 거야."}}
rows[55039]={title={{20,1965814257},"잃어버린 해답을 찾아서"},description={{759,711448716},"얼터랙 왕국은 얼라이언스를 배신한 후 폐허가 되었습니다. 배신자들의 나라가 곧 떠돌이 도적떼, 약탈자, 살인마로 전락한 것은 어쩌면 당연한 일일지도 모릅니다.$B$B 그들은 땅을 황폐하게 만들고 애초에 그들의 것이 아닌 것을 빼앗는 자들입니다.$B$B 신디케이트는 달라란에서 키린 토가 되찾아야 할 매우 중요한 책을 훔쳐갔습니다. 그것은 바위 정령 도감 3권입니다. 달라란 $B$B안팎에서 많은 건설 프로젝트가 진행 중이며, 우리 주변의 정령들을 통제하기 위해서는 그러한 책이 필요합니다. 신디케이트$B$B 마법사들은 그 책을 얼터랙 산맥의 작은 마을 스트라흐브래드로 가져갔습니다. $B$B우리에게서 빼앗긴 것을 되찾고, 무례한 자들에게 정의를 구현하십시오."},objectives={{89,100913665},"스트란브래드의 비밀결사대 마법사들에게서 '바위 정령 숙련: 개론서 III'을 되찾으십시오."},progress={"The tome is of great importance, do act quickly master $R.","이 책은 매우 중요하니,$R번 마스터님, 신속하게 조치를 취해 주십시오."},completion={{128,1045789630},"달라란은 당신의 노력에 진심으로 감사드립니다. 당신과 같은 모험가들의 노력 덕분에 이 새로운 세계에서 모든 것이 절망적으로 보이지는 않습니다."}}
rows[55040]={title={{18,386951851},"물건 반환"},description={{729,1285529964},"제3차 전쟁 중에 달라란 도서관의 수많은 귀중한 서적과 기록물이 소실되었습니다. 우리의 $B$B지식의 보고는 파괴되어 전 세계에 흩어졌고, 이제는 타락한 마법사와 강령술사들의 손에 넘어갔습니다. 그러한 힘의 책 중$B$B 하나가 이곳에서 멀지 않은 해안가에 있습니다. 비샤스 가문은 제3차 전쟁 전에 마법에 재능이 있던 아들을 위해 우리 도서관에서 책 한 권을 가져갔습니다. 저는 그들이$B$B 지금 로데론 폐허에서 붉은십자군의 타락에 휘말려 있다고 생각합니다. 저는 몇 차례 책을$B$B 되찾으려 했지만, 번번이 폭력 사태로 번졌습니다. 부디 그들과 이성적으로 협상해 주시고, 만약 이성적인 해결이 불가능하다면 다른 방법을 통해 책을 되찾아 주십시오."},objectives={{76,910735240},"달라란에 있는 안시렘 룬위버에게서 '물 짜기와 지휘' 책을 모으세요."},progress={{65,945846619},"이 책은 달라란에 매우 중요한 의미를 지니고 있으므로 반드시 되찾아야 합니다."},completion={{109,1648411035},"달라란 도서관이 예전의 모습을 되찾는 데 한 걸음 더 가까워졌습니다. 영웅이시여, 당신의 노고에 진심으로 감사드립니다."}}
rows[55041]={title={{19,423777875},"현자들의 지혜"},description={{688,211603171},"\"지식은 힘이다\"라는 말 들어보셨나요? 글쎄요, 제 고블린 동족 중 많은 이들이 그 말을 들어본 적이 없는 것 같습니다. 저는 지식을 추구하고, 새로운 기술을 배우고 싶어하는 자들에게$B$B 그 지식을 팔고 있습니다. 저는 \"현자의 지혜\"라는 제목의 오래된 책을 오랫동안 찾아왔습니다. 란다스라는 기록 보관자가 그 책을$B$B 가지고 있죠. 문제는 그가 그냥 책을 가진 사람이 아니라 달라란 출신의 마법사 중 한 명이라는 겁니다. 그래서 그 책을 손에 넣는 $B$B게 쉽지 않을 거예요. 그들은 자기 소유물을 아주 철저하게 지키기 때문에$B$B 당신의 도움이 필요합니다. 최근에 그가 달라란 근처 힐스브래드 구릉지 평원과 수용소가 내려다보이는 고지대에 있다는 정보를 입수했습니다. 그를 찾아서 그 책을 구해 주세요."},objectives={{66,2031511314},"\"현자들의 지혜\"라는 책을 찾아 현자 크레즈에게 가져다주세요."},progress={{76,547062039},"모든 높은 곳을 다 확인해 보셨나요? 그가 거기 있었다는 믿을 만한 소식통이 있어요."},completion={{106,1832271251},"음, 이게 전부인 것 같네요. 이 손상 때문에 나중에 되팔 때 가격이 꽤 떨어질 것 같아요."}}
rows[55042]={title={{21,1090852858},"샤크에 대한 만족"},description={{798,1327907764},"여기 오기 훨씬 전, 저는 투자개발회사에서 꽤 중요한 일원이었습니다. 하지만 $B$B그건 아주 오래전 일이고, 그때의 저는 지금과는 완전히 다른 사람이었죠. 그래도 기억에 남는 게 있다면, $B$B바로 그 바보 같은 별명일 겁니다. 제가 엔지니어였을 때, 스톤탈론의 숲을 파괴할 초대형 파쇄기 설계를 $B$B의뢰받았습니다. 그런데 다른 설계가 제 것보다 훨씬 더 나았죠. 그건 괜찮습니다만, 제가 정말 불만인 건 포맨 클릭스에게 \"실망시켰다\"는 이유로 해고당한 겁니다. 그는 저를 \"엉터리\"라고$B$B 불렀고, 이제 그 별명이 굳어졌죠. 그 자식은 마땅한 벌을 받을 겁니다. 제가 예전에 제재소에서 일했던 윈드셰어 절벽에서 그를 찾을 수 있을 겁니다. 늙은이가 되어서 아마 아직 거기 살고 있을 거예요. 그 자식의$B$B 반지를 좀 가져다 주세요. 중지에 끼고 다니는 엄청나게 큰 징 박힌 반지입니다."},objectives={{53,59563604},"포먼 클릭스를 처치하고 그의 스터드 링을 셰이크로 가져오세요."},progress={{34,1412814260},"그를 찾는 데 성공했나요?"},completion={{153,846551994},"<샤크는 반지를 자신의 손가락에 끼우고 낄낄거렸다.>$B$B드디어 그 바보 자식이 벌을 받았군. 이제 사람들이 날 그 이름으로 부르는 걸 그만두겠지!"}}
rows[55043]={title={{20,1777253224},"브라이트워터 로그"},description={{507,236211437},"브라이트워터호는 웅장한 배였지. 비열한 블러드세일의 매복 공격으로 비극적인 최후를 맞이한 게 참 $B$B안타깝군. 내가 스파크워터로 급히 와야 하는데, 난파선에서 항해일지를 $B$B가져와야 해. 그 안에는 내가 특정 인물들에게 넘겨주고 싶지 않은 중요한 정보가 들어있거든.$B$B 알겠지? 가시덤불 골짜기 정글의 그롬골로 가서 남쪽으로 조금만 가면 바닷속에 브라이트워터호와 다른 해적선의 잔해가 있을 거야. 찾는 건 어렵지 않을걸."},objectives={{66,1739654044},"스트랭글쏜에 있는 침몰선에서 브라이트워터 항해일지를 얻으세요."},progress={{46,1358433490},"내 침몰한 아름다운 배의 항해일지를 찾으셨나요?"},completion={{145,1435550520},"휴, 다행이다. 선장 마음이 놓이군. 누가 나보다 먼저 그 망할 물건을 찾으러 갈까 봐 걱정했어. 자, 한잔 같이 마시자!"}}
rows[55044]={title={{15,1744304193},"실종된 직원!"},description={{348,1395850897},"이 광산 작업은 힘든 일이고, 항상 최고의 일꾼들만 얻는 건 아니지, 무슨 말인지 알겠어? 악셀이라는$B$B 일꾼이 있는데, 광석 운반을 게을리하고 있어. 게다가 낮에 종종 사라지기도 해. 나는 게으른 녀석들이 $B$B아무것도 안 하고 내 돈을 뺏어가는 걸 용납할 수 없어. 그러니 가서 악셀을 찾아내서 내가 캐내야 할 구리를 가져오게 해."},objectives={{16,1321157681},"광부 악셀을 찾으세요."},progress={{50,924572169},"그는 분명 이 근처 어딘가에 있을 거야, 계속 찾아봐!"},completion={{48,1881037910},"안녕하세요, 경치 좋네요!$B$B아, 사장님이 보내셨군요?"}}
rows[55045]={title={{11,1643649259},"시간 내 광석"},description={{515,1745878808},"있잖아, 내가 그 사람한테 광석을 가져다주려고 했던 건 확실해. 매일 곡괭이로 바위를 부수는 게 너무 스트레스였어. 내가 더 나은 일을 할 수 있을 것 같아서 말이야.$B$B 혹시 부탁 하나만 들어줄래? 구리 광석 10개만 찾아줄 수 있어? 이 지역에 엄청 많거든. 네가 캘 수 있거나, 캘 줄 아는 사람을 알면 도와줄 수 있을 거야. 그걸로 밀린 배송금이랑 빚도 다 갚고, 오히려 조금 이득을 볼 $B$B수도 있을 거야! 정말 도움이 필요해. 아는 사람이 없거나 직접 캘 수 없으면 경매장을 이용하는 방법도 있어."},objectives={{50,533265072},"빅 프래글에게 광부 액셀을 위해 구리 광석 10개를 가져다 주세요."},progress={{27,760811515},"네? 그 사람 찾는 데 성공했나요?"},completion={{151,676541113},"이게 다 뭐야? 악셀이 보낸 건가?$B$B. 아무래도 거기서 일하고 있나 보네. 꽤 많은 양인데, 좋아. 그럼 악셀한테 하던 일 계속하라고 전해줘!"}}
rows[55046]={title={{8,283021188},"아곤 오어"},description={{529,1792880726},"애그몬드 엔드 근처 불모의 땅에는 오랫동안 정령들의 압력으로 인해 특별한 종류의 광석이 매장되어 있습니다. 이 광석은 매우 희귀하고 찾기도 어렵습니다.$B$B 여러 용도로 사용될 수 있지만, 저는 특히 드릴에 사용할 수 있는지 시험해 보고 싶습니다.$B$B 애그몬드 엔드에 있는 작은 드워프 야영지는 오래전에 트로그들에게 $B$B점령당했습니다. 드워프들이 광석을 전부 가져가지 못했을 테니, 트로그 중 일부가 광석을 가지고 있을 겁니다. 그곳으로 가서 트로그들을 처치하고 광석 조각을 찾아 가져오세요."},objectives={{46,1231186412},"아그몬드 엔드의 트로그족에게서 아곤 광석을 찾으세요."},progress={{49,451737600},"광석은 짙은 검은색일 거예요. 가서 찾아보세요!"},completion={"Ahh, finally a piece of this rare ore. Let me see if it can be used, thanks $N.","아, 드디어 이 희귀 광석 조각을 얻었군. 쓸 수 있는지 한번 살펴봐야겠어. 고마워,$N."}}
rows[55047]={title={{15,1817034198},"행운의 부츠"},description={{639,1203438288},"믿기 ​​어렵겠지만, 저는 항상 광부였던 건 아닙니다. 예전에는 $B$B해적질을 많이 했죠. 남해 해적단에서 배를 뺏고 원하는 걸 훔치곤 했습니다.$B$B 정말 멋진 인생이었지만, 다른 단원이 일으킨 분쟁으로 친구가 죽으면서 갑자기 끝이 났습니다. 그$B$B 후로 뒤돌아보지 않고 떠났습니다. 남해 해적단$B$B 시절에 행운의 부츠 한 켤레가 있었는데, 케잔을 떠난 후 거의 평생 동안 간직해 왔습니다. 아마 타나리스 동쪽의 히든 코브에 있는 제 숙소의 밀봉된 트렁크 안에 있을 겁니다.$B$B 찾으시면 후하게 드리겠습니다."},objectives={{31,1905575287},"빅 프래글의 행운의 부츠를 찾아보세요."},progress={{70,1094620346},"해적들은 골칫거리일 수 있지만, 당신은 스스로를 잘 지킬 수 있을 것 같군요."},completion={"Wow, I haven't seen these in a long, long time. This means a lot to me, $N.","와, 정말 오랜만에 보네요.$N님, 이건 저에게 정말 큰 의미가 있어요."}}
rows[55048]={title={{20,888176648},"수배: 구멍 탈출자"},description={{355,1724069291},"이 메시지를 읽는 자들에게 알립니다. 박실이라는 이름의 지역 죄수가 최근 땅굴을 파는 사건으로 감옥에서 탈출하여 해안가로 도망쳤습니다. 그는 $B$B서쪽 불모의 땅, 듀로타르 강변의 파 워치 포스트에서 목격되었다는 보고가 있습니다. 정의를 구현해야 합니다. 이 죄수를 산 채로든 죽은 채로든 잡아 히즐에게 돌아오십시오!"},objectives={{57,1584416422},"불모의 땅에 있는 파워치 초소에서 죄수 박실을 찾으세요."},progress={{9,2029072162},"이제 어떻게 해야 하지?"},completion={{177,553907587},"칠판에 답하셨죠?$B$B그 빌어먹을 죄수가 마지막 구멍으로 땅굴을 파고 탈출했더군요. 바다로 나간 후에야 구멍을 막아야 했습니다. 다행히 처리됐죠."}}
rows[55049]={title={{18,1802865464},"수배: 샤즈노크!"},description={{358,1974447906},"샤즈노크는 스파크워터 항구에 대한 범죄, 노조의 중요 정보 유출 및 영업 비밀 누설 혐의로 수배 중입니다. 그는 $B$B유출한 정보를 이용해 관리자 자리를 확보했습니다. 볼더로드 광산의 대강당에 있는 그의 새로운 직책에서 그를 찾아 그의 머리를 트레이드맨 라즈에게 가져오면 보상을 받을 수 있습니다."},objectives={{44,122296153},"볼더로드 광산에서 샤즈녹을 찾아 처치하세요."},progress={{9,2029072162},"이제 어떻게 해야 하지?"},completion={{176,1867143872},"당신처럼 세상에 질서를 가져다주는 사람들이 있다는 게 참 좋네요. 쥐 한 마리라도 줄어들면 우리 모두에게 좋은 일이죠. 좋은 일에 대한 보상으로 이걸 드립니다. 라즈는 언제나 좋은 일에는 보상을 해주거든요."}}
rows[55050]={title={{14,1923732123},"그리즐릭의 소원"},description={"<Little Grizlik presses his knuckle to his chest.>$B$BLok'tar, $R! I'm Grizlik, son of the Horde and future warrior of Orgrimmar!$B$B<The child flexes his scrawny arms, he almost seems cute.>$B$BHey, don't laugh at me! Come on, I've got a long way to go but the matron says if I put my mind to it, I too will have a big axe like the High Overlord, or who knows maybe shoot lightning like the Warchief!$B$B<Grizlik mimics a spell with his hands.>$B$BPew, pew!$B$BAnyway, you seem like a boring elder, you won't play with me, right? Can I ask you for a favour? Please take this to Torm Ragetotem in Thunder Bluff. When he was here last time, he brought us toys and taught me how to use a wooden axe!$B$BTake Squeaks with you too, he wants to see Thunder Bluff. You can keep him, he's more the adventuring type anyway. I'd be sad to keep him around forever if he wants to see the world!","<어린 그리즐릭이 가슴에 주먹을 얹는다.>록타르,$B$B $R! 저는 호드의 아들이자 오그리마의 미래 전사, 그리즐릭입니다!$B$B<아이는 앙상한 팔을 뽐내는데, 거의 귀여워 보인다.$B$B>저를 비웃지 마세요! 자, 아직 갈 길이 멀지만, 사제께서 마음만 먹으면 저도 대군주처럼 큰 도끼를 가질 수 있을 거라고 하셨어요. 아니면 대족장처럼 번개를 쏠 수도 있겠죠!<그리즐릭은 손으로 마법을$B$B 흉내 낸다.>뿅, 뿅!어쨌든, 당신은$B$B 재미없는$B$B 장로처럼 보이는데, 저랑 놀아주지 않으시겠죠? 부탁 하나만 드려도 될까요? 이 물건을 썬더 블러프에 있는 토름 라게토템에게 전해주세요. 지난번에 왔을 때, 그는 우리에게 장난감을 가져다주고 나무 도끼 사용법을 가르쳐줬어! $B$B스퀴크도 데려가. 썬더 블러프를 보고 싶어 하거든. 스퀴크는 네가 키워도 돼. 어차피 모험을 좋아하는 타입이니까. 스퀴크가 세상을 보고 싶어 한다면 평생 곁에 두기는 아깝잖아!"},objectives={{57,1624873322},"그리즐릭의 편지를 썬더 블러프에 있는 토름 라게토템에게 가져다 주세요."},progress={{17,1691942617},"제게 온 편지인가요?"},completion={"Ah, how unexpected. Young Grizlik had sent me a drawing of us training together, including a thank you message.$B$BHe aspires to be trained when he grows older. The future generation of the horde, $N. That's why we are all here.","아, 뜻밖에도. 어린 그리즐릭이 우리가 함께 훈련하는 그림을 보내주면서 감사 인사도 함께 보냈더군.$B$B그는 자라서 훈련받고 싶어해. 미래의 호드 세대,$N. 그래서 우리 모두가 여기에 있는 거지."}}
rows[55051]={title={{15,645241407},"항구로 돌아가세요!"},description={"I can't believe it's finally over, heh. No more sitting around in the this basement and getting drunk off cheap liquor, now I can sit around on a beach with the expensive stuff as celebration!$B$BIt's been a real pleasure $N and we couldn't have done it without you.$B$BHead to Sparkwater Port, let the Captain know that we're going to be on our way back when we can organize a ship to get us there. He should be sure to give you some sort of a reward for helping us out, surely.","드디어 끝났다니 믿기지 않네, 헤헤. 이제 더 이상 지하실에 앉아서 싸구려 술이나 마시며 빈둥거릴 필요 없어. 이제 비싼 술이나 마시면서 해변에서 축하 파티를$B$B 즐길 수 있겠어! $N정말 즐거웠어, N. 네가 없었으면 $B$B불가능했을 거야. 스파크워터 항구로 가서 선장에게 우리가 돌아올 배를 구할 수 있게 되면 곧 돌아올 거라고 전해줘. 분명 네가 우리를 도와준 것에 대한 보상을 해줄 거야."},objectives={{63,140822440},"스파크워터 항구에 있는 파즐 브라이트렌치에게 좋은 소식을 전하세요."},progress={{15,159386007},"도와드릴까요?"},completion={"Well, it certainly has been a while, you got any good news from Booty Bay?$B$BOh, they're on their way back? Oh and Revilgaz was upset huh? I don't blame him, heh.$B$BYou've saved my crew from an unknown fate and I thank ye for that, $N. Please, take this cutlass, no point in swashbuckling if the ship is gone.","오, 정말 오랜만이군. 무법항에서 좋은 소식이라도 들었나?$B$B아, 그들이 돌아오는 중이군? 아, 그리고 레빌가즈가 화가 났었나 보군. 그럴 만도 하지, 헤헤.$B$B자네 덕분에 우리 선원들이 알 수 없는 운명에서 벗어날 수 있었네. 정말 고맙네,$N. 자, 이 커틀러스를 받네. 배가 없는데 무슨 허풍을 떨겠어."}}
rows[55055]={title={{18,229756966},"전쟁 모드 취소됨"}}
rows[55100]={title={{16,655899329},"리그에 참여"},description={{473,112111988},"탐험가 연맹은 언제나 새로운 멤버를 찾고 있습니다. 아제로스의 바다를 누비며 잊혀진 유물과 묻힌 보물을 찾아 세상을 탐험하고 싶으신가요?! 그렇다면 탐험가 연맹의$B$B 수많은 발굴자이자 탐험가 중 한 명인 제 친구 메린 록위버를 찾아보세요! 그는 오래된 유물과 뼈를 발굴하는 데 열중하고 있답니다! 여기서$B$B 동쪽으로 가면 웰가르의 발굴 현장이 있습니다. 남쪽 산맥 기슭에 숨겨져 있으니, 탐험가 여러분, 눈을 크게 뜨고 찾아보세요!"},objectives={{55,691718061},"위대한 탐험가가 되려면 메린 록위버에게 보고하세요!"},progress={{54,1111742557},"네, 도와드릴까요? 여기 상황이 좀 복잡하네요."},completion={{156,2037141361},"메네틸 항구는 아직도 여기서 무슨 일이 일어났는지 모르고 있는 겁니까?$B$B산에 주둔하고 있는 그 얼간이 그로부그에게 보고하려면 증거가 필요해요. 도와주시죠?"}}
rows[55101]={title={{16,1032365036},"리그를 도와주시겠습니까?"},description={{494,611786698},"맹금류들이 우리 발굴 현장으로 천천히 다가오고 있다는 보고가 계속해서 들어왔지만, 산 위에 있는 그 멍청한 $B$B그로부그는 그 보고들을 무시했어. 던 아그라스에서 편안하게 자리를 잡고 있으면서, 여기 와야 할 사람이$B$B 1.2cm도 안 움직였지. 그로부그가 뭔가 조치를 취하도록 확실한 증거를 그의 면전에 대고 보여줘야 해.$B$B 맹금류 알이 딱 좋을 거야. 저 아래에서 맹금류들을 처치하고 알을 모아. 그 알들을 던 아그라스 남서쪽 산맥에 있는 그로부그에게 가져다 줘."},objectives={{84,236300102},"맹금류 알 10개를 모아 던 아그라스에 주둔하고 있는 그로부그 미스릴메인에게 가져다 주세요."},progress={{41,1896486601},"저는 중요한 리그 업무차 여기에 왔습니다."},completion={{219,1652472185},"이 사진들이 웰가르 유적지에서 나온 거라고요? 정말요?$B$B저는 그쪽 사람들이 과잉 반응하는 줄 알았는데, 말씀하신 대로 심각하다면 보고서를 작성해서 최대한 빨리 아이언포지에 보내야겠네요!"}}
rows[55200]={title={{27,1846167117},"모험을 위한 준비!"},description={{519,1903029748},"안녕하세요 친구! 세상을 다 보셨나요? 아제로스의 구석구석을 탐험하고 그 아름다움을 제대로 느껴보셨나요?I 아무도 다 해본 사람은 $B$B없을 것 같지만, 상상만 해도 설레지 않나요?I 저는 세계 여행을 준비 $B$B중인데, 필요한 물품이 몇 가지 있어요. 그중 하나가 횃불이에요.I 아이언비어드의 무덤 북쪽에$B$B 있는 점액질 생물들이 예전에 제가 횃불에 불을 붙이는 데 쓰던 끈적끈적한 점액질 타르 같은 걸 쓰곤 했거든요. 그 점액질 생물들에게서 끈적끈적한 점액질 타르 5개와 상인에게서 일반 나무 5개를 구해다 주세요."},objectives={{62,1693257837},"사무엘 비커스를 위해 끈적끈적한 점액질 타르 5개와 일반 나무 5개를 모으세요."},progress={{63,1175656295},"제 모험에 필요한 재료들을 다 모으셨나요?"},completion={"Quicker than I had imagined! You must be a seasoned explorer. Hopefully one day I will see as much as you have. Thanks, $N.","생각보다 훨씬 빠르시네요! 정말 노련한 탐험가시군요. 저도 언젠가는 당신처럼 많은 곳을 볼 수 있기를 바랍니다. 감사합니다,$N님."}}
rows[55201]={title={{21,1353412131},"도로를 되찾다"},description={{324,1600785166},"맹금류들이 메네틸 항구로 이주해 와서 그곳을 자신들의 영역으로 삼은 이후로 육로 연결이 끊겼습니다. 병력이 $B$B부족해서 그들을 몰아낼 수 없었고, 그 결과 우리는 지금 이곳에 고립되어 있습니다.$B$B 산기슭으로 내려가서 그곳에 있는 맹금류들을 처치하십시오. 증거로 발톱 다섯 개를 모아 오십시오."},objectives={{47,1671550484},"스노우비어드 선장을 위해 얼룩무늬 발톱 5개를 모으세요."},progress={{52,1464142136},"우리 앞길을 막고 있는 짐승들을 몇 마리 처치했습니까?"},completion={"Less raptors stalking at the base of our hills puts my mind to rest. Thanks for the work, $N.","언덕 기슭에서 사냥하는 맹금류가 줄어든 덕분에 마음이 놓입니다. 수고하셨습니다,$N님."}}
rows[55202]={title={{12,1224037554},"잃어버린 내기"},description={{343,1182640782},"반갑네, 친구! 혹시 던 아그라스 근처로 가는 길이 아니신가? $B$B남동쪽 산맥, 호크스 비질 근처쯤에 있지. 내 $B$B사촌 바를톡이랑 내기에서 졌는데, 드워프는 빚을 갚지 않고는 못 배기거든. 내 최신 수제$B$B 맥주 한 통을 가져다주면, 바를톡이 기분이 좋으면 꽤 괜찮은 보상을 해줄지도 몰라."},objectives={{46,1849968509},"던 아그라스에 있는 발톡에게 하긴의 맥주통을 전달해야 합니다."},progress={{37,1543994489},"그래, 무슨 필요한 거라도 있니?"},completion={{334,903618275},"사촌 하진이 드디어 좋은 걸 내놓는군! 정말이지, 이제야 제대로 된 걸 내놓다니! 만약 이 약이 그 녀석 말대로 좋다면 오늘 밤도 못 갈지도 몰라!$B$B수고비 고맙다, 꼬마야...$B$B<동전을 건네준다.>$B$B돈 벌 방법을 더 찾고 있다면, 호크스 비질에 있는 사무엘에게 말을 걸어 봐. 그는 모험가이기도 하고, 도움이 필요할지도 몰라."}}
rows[55203]={title={{25,469742246},"목재가 제시간에 도착했습니다!"},description={{571,1535100247},"안녕하세요! 제가 좀 곤란한 상황에 처했는데요. 여기에서 메네틸 항구까지 가는 길이 꽤 오랫동안 막혀 있어서, 이 화물을 빨리 그곳으로 보내야 합니다. 메네틸$B$B 항구에서 조선소 보수 공사에 필요한 목재를 더 요청했는데, 저희 제재소가 가장 가까운 곳이거든요.$B$B 분명히 그들이 목재를 빨리 받지 못하면 다른 곳에 맡길 겁니다. 부탁 하나만 $B$B들어주신다면, 이 화물을 메네틸 항구 쪽으로 가져다주셔서 제임스 할로란에게 전달해 주시면 정말 감사하겠습니다! 저희 사업에도 큰 도움이 될 거예요!"},objectives={{65,1316486437},"메네틸 항구에 있는 제임스 할로란에게 목재를 전달하십시오."},progress={{60,1326743355},"네, 저에게 주실 말씀 있으신가요? 제가 지금 꽤 바빠서요."},completion={{154,79728101},"배송이 늦어질 거라고 예상했어요. 여기 동쪽 도로 사정이 워낙 안 좋은데도 불구하고, 호크스 비질은 배송에 있어서는 여전히 믿을 만한 것 같네요."}}
rows[55204]={title={{21,1795889296},"스토우트피스트 보고서"},description={"You there, I need a report ran to my fellow Captain up in Dun Agrath up in the mountains to the south. You look capable of delivering a message.$B$BThis is of utmost importance, it is urgent and about the matters of trade, commerce and travel through the region of the Wetlands. Take this to him, and with urgency, $C.","거기 당신, 남쪽 산맥에 있는 던 아그라스에 있는 제 동료 대장에게 전할 보고서가 있습니다. 당신이라면 전할 수 있을 것 $B$B같군요. 이건 아주 중요한 긴급한 내용이며, 습지 지역의 무역, 상업, 그리고 여행에 관한 문제입니다. 그에게 이 보고서를 최대한 빨리 전해 주십시오.$C"},objectives={{59,1077221671},"스토우티스트의 보고서를 던 아그라스에 있는 스노우비어드 선장에게 가져다 주십시오."},progress={{125,363249823},"우리는 비록 산속에 있지만, 보급품 수송을 위해 지상에 있는 사람들에게 의존해야 하므로, 흔들리지 않고 굳건히 버텨야 합니다."},completion={{138,896663873},"스토우트피스트 대위가 보낸 거로군. 어디 보자...$B$B<드워프가 보고서를 읽는다.>$B$B내가 가진 몇 안 되는 산악인들이 드래곤마우를 막을 수 있다고 생각하는 건가?"}}
rows[55205]={title={{21,1501150584},"스노우비어드의 보고서"},description={{238,50320293},"그가 요구하는 대로라면 우리는 산속에서 무방비 상태가 될 겁니다.$B$B..이 보고서를 그에게 가져다주고 우리의 상황을 알려줘야 합니다. 그에게 아무것도 주지 않고 떠나는 것이 마음 아프지만, 이곳 사람들의 안전을 위해 어쩔 수 없습니다."},objectives={{64,781041394},"스노우비어드의 보고서를 메네틸 항구의 스타우트피스트 선장에게 가져다 주십시오."},progress={{55,770978104},"스노우비어드에게서 소식 들었어? 새로운 병사들이 오고 있나?"},completion={"He cannot even lend a single hand to assist us? What is it then we are supposed to do against the Dragonmaw?...$B$BThanks, $N. Take these coins for the trouble. I will have to think of a new plan.","그는 우리를 돕기 위해 손 하나 까딱할 수 없는 건가? 그럼 우리가 드래곤마우를 어떻게 상대하라는 겁니까?...$B$B고마워요,$N. 수고비로 이 동전들을 받으세요. 새로운 계획을 세워야겠네요."}}
rows[55206]={title={{17,2012371614},"드래곤마우 사냥"},description={{379,1198509480},"아이언포지나 가까운 동맹의 도움조차 기대할 수 없을 것 같군. 모험가 자네에게 부탁하건대, 고원을 배회하며 우리 상단을 습격하는 용아귀 무리를 소탕하는 데 힘을 $B$B보태주겠네. 우리가 이곳에 온 이후로 줄곧 골칫거리였던 그들이 더 큰 세력을 확장하기 전에 막아야 하네.$B$B 동쪽의 앵거팽 야영지로 가서 그들을 처치하오."},objectives={{114,1298719099},"드래곤마우 레이더 10마리, 드래곤마우 본워더 6마리, 드래곤마우 스웜프러너 6마리를 처치한 후, 스토우트피스트 선장에게 돌아가십시오."},progress={{94,1418201197},"드래곤마우는 행동에 더욱 용기를 얻지 못하도록 매번 점검해야 합니다."},completion={"You've done it!$B$BWe may finally sleep a night of peace knowing there are less of the blackbloods stalking the hills and preying upon our citizens. You have done a noble deed, $N.","해냈군요!$B$B이제 언덕을 배회하며 우리 시민들을 노리는 검은 피의 자들이 줄어들었으니, 우리는 마침내 편안한 밤을 보낼 수 있겠습니다. 당신은 숭고한 일을 해냈습니다,$N."}}
rows[55207]={title={{17,2028749914},"파이를 찾아서"},description={{304,1145497876},"아, 그 파이! 생각만 해도 입에 침이 고이네요, 정말 맛있어요! 얼마 전에 호크스 비질에 가서 하이디가 만든 환상적인 파이를 먹어봤는데!$B$B 더 먹고 싶어요, 당신이 구해다 줘야겠어요! 호크스 비질로 $B$B가서 여관 주인 하이디에게 말을 걸어 보세요. 그녀는 훌륭한 사람이고 빵 만드는 솜씨도 뛰어나답니다."},objectives={{36,1294268840},"란을 위해 하이디가 직접 만든 파이를 가져다 주세요."},progress={{41,1003499612},"안녕하세요, 여행자님. 제 여관에 오신 것을 환영합니다!"},completion={{65,466736743},"어머, 란이 보냈어요? 설마 그가 내 파이에 대해 장황하게 얘기한 건 아니겠죠!"}}
rows[55208]={title={{16,2139710866},"파이 배달"},description={{314,516229130},"란은 제 파이에 완전히 푹 빠졌어요. 여기까지 와서 상상도 못 할 만큼 많이 먹었답니다. 제 음식이 누군가에게 그렇게 맛있다고 하다니 정말 감격스러워요. 혹시 이$B$B 파이를 란에게 전해주시고 그의 소원을 들어주실 수 있다면 정말 $B$B감사하겠습니다. 그러면 언젠가 다시 와서 더 맛볼지도 몰라요!"},objectives={{39,1030848867},"하이디가 직접 만든 파이를 란에게 배달해 주세요."},progress={{46,1040557485},"이렇게 빨리 돌아왔다고? 내 파이 꼭 먹어!"},completion={{60,1882371320},"파이 파이 파이! 세상에!$B$B며칠 동안 이걸 꿈꿔왔어요!"}}
rows[55209]={title={{18,784546189},"회로도 실행!"},description={{454,615234458},"안녕하세요! 이 근처에는 손님이 별로 없어요. 특히 주변에 온갖 사악하고 음흉한 것들이 우글거려서요! 그래도 반가운$B$B 얼굴의 낯선 분을 뵙게 되어 기쁩니다. 호크스 비질에 제 친구가 한 명 있는데, 3차 전쟁 때 함께 일했던 친구입니다.$B$B 우리는 서로 새로운 발견들을 교환하곤 했죠. 제가 최근에 온갖 기발한 장치들을 만들어낸 것 같아요! 부탁인데,$B$B 가능하시다면 제 새 설계도를 그 친구에게 전해주시겠어요?"},objectives={{80,685702366},"스위프트기어의 설계도를 호크스 비질에 있는 바르토스 썬더크랙에게 가져가세요."},progress={{92,1664651350},"아, 무슨 용건으로 오셨나요, 아니면 제 신기술에 대해 이야기 나누고 싶어서 오신 건가요?"},completion={{218,1675292535},"오, 저 프래드 좀 봐! 온갖 최첨단 장비들을 다 갖췄네! 윙윙거리는 프래드뱅어, 충격적인 여성형 색소, 기울어지는 진동 억제기까지?!$B$B이거 전부 최첨단 장비들이네. 배송해줘서 고마워, 여행 갈 때 가져가."}}
rows[55210]={title={{30,302338705},"기울어짐 진동 억제제?!"},description={{421,1853138504},"이거 정말 대단하네요, 특히 이 기울어짐 진동 억제기는요!$B$B 제작 조건이 굉장히 특이하긴 하지만, 꼭 $B$B갖고 싶어요! 이 장치를 만들 수 있는 재료를 구해다 주시면, 하나 만들어서 아이템에 넣어 드릴게요. $B$B여기 재료 목록을 적어놨으니, 필요한 걸 모아서 가져오세요. 두 개 만들 수 있는 양일 거예요!"},objectives={{107,531566594},"바르토스의 공학 노트를 활용하여 철 막대, 강력 용융제, 청동 회전 장치, 퓨즈 배선을 모으세요."},progress={{67,541193724},"재료는 다 모았어?!$B$B머릿속에 아이디어가 샘솟아!"},completion={{101,1786801564},"다 구하셨군요?$B$B훌륭합니다! 이제 제가 제 것을 사용할 수 있도록 당신을 위해 이것저것 손봐야겠네요!"}}
rows[55211]={title={{26,1591361625},"진동 억제 디스크!"},description={{209,2090244106},"자, 그럼. 이제 제 다음 걸작을 만들어 볼까요! 오래 걸리지는 않을 테니, 뒤로 물러나서 적당한 거리를 유지하세요. 다치지 않도록 말이죠! 훌륭한$B$B 공학 기술에는 어느 정도의 위험이 따르는 법이니까요."},objectives={{60,1725876740},"바르토스 썬더크랙이 그의 위대한 발명품을 만들어낼 때까지 기다리세요."},progress={{31,1133755772},"잠깐만 기다려, 얘야. 나 지금 뭐 좀 만지고 있어!"},completion={{110,170941510},"자, 여기 제 작품이 있습니다!$B$B공학적 걸작이죠.$B$B부디 잘 사용하시길 바랍니다. 자, 이제 제 다른 작품들을 보러 가야겠네요!"}}
rows[55212]={title={{14,2009826469},"이것저것 손보면서"},description={{603,1730518561},"3차 전쟁 당시 나는 유명한 엔지니어였지. 비행기를 비롯한 온갖 기계 장치들을 현장에서 수리했었어. 어떤 이들은 내 발명품들이 그저 난쟁이들이 만든 것 같다고 하지만, 젠장!$B$B 난 항상 내 나름대로의 변형을 가해서 더 튼튼하게 만들고 드워프도 다룰 수 $B$B있게 만들었지! 난 호크스 비질에서 손꼽히는 엔지니어 중 한 명이지만, 수리할 재료가 좀 부족해. 여기 절벽 위 아이언포지 공항에 있는 녀석들이 재료를 잔뜩 가지고 있는 걸로 알고 $B$B있어. 거기 올라가서 내 친구 오리온 콜본을 찾아봐. 걔가 나한테 줄 만한 여분의 재료가 있을 거야!"},objectives={{75,880198591},"아이언포지 비행장으로 가서 바르토스 썬더크랭크의 보급품을 모으세요."},progress={{90,368784091},"비행장에 오신 것을 환영합니다! 상원이나 저희 운영과 관련하여 용건이 있으십니까?"},completion={{127,1749071715},"아, 바르토스가 보냈군요? 그는 항상 물자를 찾고 있어요. 예전에 저를 구해준 적이 있어서 정말 다행이에요. 아직 그에게 신세를 졌거든요!"}}
rows[55213]={title={{20,745174562},"바르토스 용품"},description={{319,970878727},"상원에서 이 모든 물자 분실 사건을 조사하면 엄청난 압박을 받을 겁니다. 하지만 바르토스를 그냥 내버려 둘 순 없어요... 자, $B$B제가 드릴 수 있는 건 이겁니다. 이 상자 하나면 당분간은 충분할 겁니다. 다음에 $B$B바르토스를 만나면 언제든 여기 와서 일해도 된다고 전해주세요. 엔지니어들이 필요하거든요."},objectives={{44,959424294},"바르토스에게 엔지니어링 자재를 전달하세요."},progress={{58,1315864255},"내가 보내드린 비행장에서 그 부품들 구해왔어?"},completion={{225,1563958394},"오, 오리온! 정말 좋은 친구야, 언제나 딱 필요한 순간에 나타나주지!$B$B난 이제 거의 다 됐어! 아이언포지 공항에서 일한다니 무슨 말이야?$B$B내 작업장에서 이것저것 만지작거릴 수 있는데 왜 굳이 그런 일을 하겠어!"}}
rows[55215]={title={{18,1339635903},"미스터리의 해명"},description={{654,931309340},"언뜻 보면 호크스 비질은 완벽한 안식처처럼 보일지도 모릅니다. 언덕은 울창하고 풀은 선명한 초록색이니까요. 하지만$B$B 겉모습에 속지 마십시오. 바로 우리 눈앞에서 불길한 일들이 벌어지고 있습니다. 우리 중 가장 뛰어난 몇몇이 마법의 기운을 $B$B감지했습니다. 비질 안에서 살인이 발생했고, 이 어둠은 여전히 ​​짙어지고 있습니다. 마지 블랙우드는 이 마법의 기운을 조사하기 위해 스스로 나섰고, 저는 이 사건의 진상을 밝히고 싶습니다. $B$B마지에게 보고하고, 이 미스터리를 푸는 데 도움을 줄 수 있는지 $B$B알아보십시오. 마지는 북동쪽 저택 안에 있습니다."},objectives={{26,1246073684},"마지 블랙우드에게 보고하십시오."},progress={{36,2000663084},"제가 도와드릴 일이 있을까요?"},completion={{172,606725969},"무슨 일이 벌어지고 있는지 꽤 오랜 시간 조사해 봤는데, 뭔가 섬뜩한 기운이 감돌고 있어요. 마치 금지된 마법의 기운이 호크스 비질에 스며드는 것 같아요."}}
rows[55216]={title={{21,788731320},"미스터리는 계속된다"},description={{373,1271209884},"제 연구는 계속 진행 중이지만, 미스터리는 여전히 풀리지 않았습니다. 제 친구이자 동료인 포피 자비니 역시 이 지역의 $B$B마법사입니다. 그 역시 이 문제를 연구하고 있지만, 저보다 훨씬 더 바쁜 것 같습니다. 그를 $B$B만나러 가주시겠습니까? 그는 지금 파란 지붕의 저택에서 북쪽으로 조금만 걸어가면 있는 곳에 있습니다."},objectives={{24,1722557068},"포피 자비니와 이야기해 보세요."},progress={{80,1549046588},"배울 것이 많으니, 그래서 나를 찾아오셨습니까?"},completion={{82,1428385558},"아, 마지 블랙우드가 보냈군요. 호크스 비질에 나오는 어둠의 마법 문제 때문에요? 그렇군요."}}
rows[55217]={title={{20,122140290},"자비니의 정보"},description={{677,1738822461},"호크스 비질에 스며든 어둠의 마법은 마치 갑자기 나타난 듯하며, 나와 내 동족은 한동안 그 존재를 감지하지 못했습니다. $B$B적어도 최근 몇 주 동안에야 비로소 나와 마지처럼 많은 이들이 알아차릴 정도로 강력해졌습니다. 나는 오랫동안 잠재되어$B$B 있던 힘이 서서히 강해지고 있었거나, 아니면 최근에 그토록 강력한 힘을 가진 무언가 또는 누군가가 호크스 비질에 나타난 것이라고 생각합니다. 이 어둠을 퍼뜨리는$B$B 원인을 찾는 데 행운을 빕니다. 나는 3차 전쟁 전에 비슷한 것을 감지했고, 그 경험을 다시 겪고 싶지 않습니다. 내가 아는 것을 마지에게 전해 주세요. 도움이 될지도 모릅니다."},objectives={{46,999141561},"자비니의 정보를 마지 블랙우드에게 가져다 주세요."},progress={{29,1040906744},"포피 자비니에서 돌아오셨나요?"},completion={{117,2081826980},"음... 그러니까 그는 이 원천이 이 지역에 새로 나타난 것일 수도 있다고 생각하는 건가?$B$B나는 그런 가능성은 생각해 본 적이 없네."}}
rows[55218]={title={{16,653895664},"잠재적인 단서"},description={{495,1929769895},"자비니의 말이 일리가 있을지도 몰라. 내가 아무리 조사해도 이 마법의 근원을 찾을 수가 없었거든. 누가 사용했든 간에, 그 기술은 상당한 것 같아.$B$B 하지만 자비니가 제공한 정보에 단서가 있을지도 $B$B몰라. 라이크 사령관은 호크스 비질의 모든 동향을, 특히 누가 새로 왔는지 잘 알고 있지. 만약 $B$B최근 몇 주 사이에 누군가 왔다면, 그 사람을 이 어둠의 근원으로 의심해 볼 수도 있고, 최소한 조사라도 해볼 수 있을 거야."},objectives={{31,122400724},"라이크 사령관과 대화하십시오."},progress={{59,1966270803},"다시 오신 걸 환영합니다. 마지 씨는 그 모든 문제에 대해 무슨 소식이라도 있나요?"},completion={{95,1551126075},"흥미로운 보고서네요. 제 기록을 확인해서 마을에 새로 온 사람들이 있는지 확실히 알아봐야겠습니다."}}
rows[55219]={title={{26,2141387101},"중복 조사"},description={{599,2012722877},"<라이크 사령관이 기록 검토를 마친다>최근$B$B 스톰윈드 출신의 할러스 애쉬버클이라는 사람이 마을로 이사 온 것 같소.그 사람은… 문제가$B$B 좀 있어서 내 관할 밖이지만, 현재 SI:7에서 그를 조사하고 $B$B있소. 우리 수사 때문에 알려드리는 거지만, 마을에 요원을 심문해서 그를 감시하고 있소.그 요원을 만나 보시오.$B$B 이름은 롭 더즐리이고, 마을 중심가 근처에서 자주 볼 수 있소.할러스라는$B$B 사람에 대한 정보를 좀 얻어내 보시오."},objectives={{49,1415461142},"잠복 요원 롭 더즐리와 대화하세요."},progress={{50,914206010},"라이크 사령관님이 저와 무슨 상관이 있겠습니까?"},completion={"Oh...$B$B<Robb Dursley's cheerful demeanor drops.>$B$BThat is why you've come?$B$BWhat we are going to speak of must remain a secret, understood, $N?","아...$B$B<롭 더즐리의 쾌활한 표정이 사라진다.>$B$B그래서 오셨습니까?$B$B우리가 이야기할 내용은 비밀로 해야 한다는 거, 알겠죠?$N?"}}
rows[55220]={title={{13,947998743},"롭의 보고서"},description={{652,668189774},"SI:7의 작전은 본질적으로 비밀스러운 것이며, 앞으로도 그렇게 유지되어야 $B$B합니다. 라이크 사령관의 의심이 사실이라면, 할러스 애쉬버클은 스톰윈드 귀족들에게 맹세한 서약을 어기는 셈입니다. 물론, 그 $B$B귀족들은 그가 금지된 마법을 사용하고 살인을 저지른 죄로 수배되었을 때 스톰윈드 감옥에서 그를 구해냈습니다. 비록 제가 귀족 가문을 싫어하지만, 저는 $B$B명령에 따를 수밖에 없습니다. 제 조사 결과를 담은 보고서를 스톰윈드$B$B 구시가지에 있는 SI:7의 수장인 마티아스 쇼에게 가져가십시오. 보고서는 봉인된 상태로 $B$B보관하십시오. 봉인이 깨지더라도 다시는 그에게, 그리고 저에게 모습을 드러내지 마십시오."},objectives={{60,711636200},"롭 더즐리의 봉인된 보고서를 마티아스 쇼 학장에게 전달하십시오."},progress={{37,2021304760},"SI:7에서 당신이 요구하는 것은 무엇입니까?"},completion={{219,697597986},"<마티아스가 보고서를 받아 읽기 시작한다.>$B$B흠, 짐작했던 대로군. 그 남자는 제정신이 아니었고 마법에 완전히 빠져 있었으니, 라이크 사령관께서 말씀하신 '더러운 오염'의 배후에 그가 있는 게 당연하지."}}
rows[55221]={title={{19,48791976},"요새의 수색"},description={{974,1818766653},"아, 네. 롭의 보고를 통해 결국 이 남자를 알게 될 거라고 생각했습니다. 당신은 그를 할러스 애쉬버클로 알고 있을지도 모르지만, 사실 그건 가명에 불과합니다. 당신이 정보를 수집하고 있는 사람은 로데론 출신의 마틴 코린스입니다. 그는 3차 전쟁 중에 남쪽 스톰윈드로 도망쳤고, 최근 감옥에서 풀려났습니다. 귀족 가문의 $B$B누군가가 그의 처형을 연기시켜 결국 그가 마법을 포기하고 추방당하겠다는 서약을 하는 조건으로 석방시켰습니다. 저는 그가 흑마법에 얼마나 큰 잠재력을 가지고 있는지 알고 있었기에 그를 예의주시해 왔습니다. 저는 그를 단순히 $B$B그의 마법 때문에 처형하기 전에 몇 가지 미스터리를 풀고 싶습니다. 이 모든 금지된 마법의 배후에 누가 있는지, 그리고 어떤 귀족이 그를 석방했는지 알아내고 싶습니다. $B$B최근 요새가 점령당했지만, 그곳은 마틴 코린스에게 중요한 정보가 남아 있는 마지막 장소입니다. 그곳으로 가서 정보를 찾아보세요."},objectives={{102,1687525371},"감옥을 샅샅이 뒤져 마틴 코린트에 대한 정보를 찾아내십시오. 그리고 그 결과를 마티아스 쇼에게 보고하십시오."},progress={{48,1896354082},"당신은 요새의 깊은 곳까지 용감하게 들어가 보셨나요?"},completion={{103,1255996576},"좋습니다. 이제 이 남자가 어디 출신인지 제대로 알아봅시다. 어쩌면 이 모든 것에 대한 단서를 찾을 수 있을지도 모릅니다."}}
rows[55222]={title={{21,1664705735},"고린도 조사"},description={{502,1932406472},"코린트 가문은 한때 로데론과 스톰윈드 귀족들과 상당한 연줄을 가지고 있었던 것으로 보입니다. 가문의 $B$B모든 구성원은 사망했지만 마틴은 살아남아 전쟁 후 스톰윈드로 도피했습니다. 일부 문서에 따르면 그는 망명 생활의 일환으로 메네틸 항구에 정착하려 했다고 하지만, 이는 사실이 아닌 것으로 알려져 있습니다. 하지만 어쩌면 그가 우리에게 무언가를 남겼을지도 모릅니다.$B$B 메네틸 항구의 여관 주인에게 마틴 코린트나 할러스 애쉬버클을 본 적이 있는지 물어보세요."},objectives={{70,2069851069},"메네실 항구의 딥워터 선술집을 방문해 정보를 알아보십시오."},progress={{52,903156236},"안녕하세요, 제 주점에 오신 것을 환영합니다. 방을 찾으시나요?"},completion={{106,1314950933},"아, 마틴 코린트라는 이름은 처음 들어보는데, 할러스 애쉬버클은 기억나네요. 그 사람들은 어땠나요?"}}
rows[55223]={title={{19,380963083},"증거를 밝히다"},description={{628,1108150982},"네, 사실 그는 며칠 동안 여기 머물렀고, 내내 방을 썼어요! 제가 $B$B기억하기로는 그는 꽤 괜찮은 사람이었고, 혼자 있는 걸 좋아했고, 맥주를 조금 마셨는데, 좀 우울해 보였어요. $B$B그는 편지를 많이 주고받았는데, 제가 매일 저녁 식사와 함께 그에게 가져다 드렸어요. 그의$B$B 개인 소지품을 찾으신다면 제가 크게 도움을 드릴 수는 없을 것 같아요. 제가 그의 얼마 안 되는 소지품들을 정리한 지 얼마 안 됐거든요.$B$B 그는 짧은 여행을 간다고 했고 몇 주 동안 나타나지 않았어요. 저는 그가 돌아오지 않을 거라고 생각해서 그의 물건들을 술집 옆으로 내놓았어요. 혹시 $B$B찾으시는 물건이 있다면 거기를 확인해 보세요. 이미 없어지지 않았다면요."},objectives={{70,2038344528},"마틴의 소지품을 찾아 스톰윈드에 있는 마티아스 쇼에게 가져다 주세요."},progress={{36,2136238467},"메네틸 소식 좀 들었어?"},completion={{112,1364648375},"음, 그러니까, 그는 메네틸 안에 뭔가를 남겨둔 모양이군. 다행히도 그 남자는 흔적을 완전히 지우지는 않았어."}}
rows[55224]={title={{15,446810221},"마티아스의 편지"},description={{567,1953438652},"라몬 공작, 확실히 그동안 미처 해결하지 못했던 많은 문제들이 해결됐습니다. 덕분에 우리 요원들이 다른 수사에서 빠져나올 수 있게 됐네요. 저는 라이크 $B$B사령관에게 전달할 편지를 준비했습니다. 이 편지에는 그가 이 남자를 처벌하는 데 필요한 모든 정보가 담겨 있을 겁니다. 귀족 가문에 $B$B말씀드리자면, 저희는 계속해서 수사를 진행할 것입니다. 현재로서는 귀족 한 명이 가족 친구를 도와 법 위에 군림하게 한 것일 가능성이 높아 보입니다. 부디 그게 전부이길 바랍니다."},objectives={{58,1648616236},"호크스 비질에 라이크 사령관을 데려오세요. 마티아스의 편지."},progress={{46,266487917},"돌아오셨군요, 스톰윈드에서 좋은 소식이라도 있나요?"},completion={{94,355275739},"그러니까 우리의 의심이 맞았다는 거네요. 여기에는 매우 불리한 정보가 많습니다."}}
rows[55225]={title={{16,831926484},"매의 경계"},description={{501,95218780},"호크스 비질 마을은 로데론을 뒤덮는 어둠을 피해 이곳으로 피난처를 찾아왔습니다. 그리고 우리는 이곳에서도 물러서지 않을 겁니다. 많은 $B$B주민들이 이곳에 와서 더 나은 삶을 꾸려나가려 하고 있으며, 이제 한 사람이 우리를 막을 수는 $B$B없습니다. 마티아스 쇼는 내게 부패와 악행, 순수한 악에 대한 이야기를 들려주었습니다. 할러스 애쉬버클이라는 자에게 정의를 구현하는 것은 당신의 몫입니다.$B$B 그를 처단하고, 이 땅에 헤아릴 수 없는 악이 자행되기 전에 그의 더러움을 영원히 없애버리십시오."},objectives={{22,2076094934},"할러스 애쉬버클을 죽여라."},progress={{33,1155029935},"이 괴물은 처리되었습니까?"},completion={"The town has been saved! I thank you again $N. Hawk's Vigil shall remain a place of peace as long as brave souls like yourself walk Azeroth.$B$BHere, take one of these as a token of the town's gratitude.","마을이 구원받았습니다!$B$B다시 한번 감사드립니다.$N당신처럼 용감한 영혼들이 아제로스를 걷는 한, 호크스 비질은 평화로운 곳으로 남을 것입니다. 자, 마을의 감사 표시로 이것을 받아가세요."}}
rows[55300]={title={{24,533168656},"제국 판금 장갑"},objectives={{57,1596345708},"장갑 제작을 위해 토륨 막대 20개가 필요합니다."},progress={{103,1933520386},"장갑 제작을 위해 토륨 막대 20개가 필요하군.$B$B괜찮니, 얘야? 얼굴이 새빨개졌잖아."},completion={{96,2121942151},"편안할 뿐만 아니라 스타일리시하기까지 하죠. 물론 보호 기능도 훌륭합니다."}}
rows[60005]={title={{17,1917563759},"양 한 마리"},description={{690,547213641},"내 양들이 사라졌어요! 양털 깎을 양 없이는 농장을 운영할 수가 없어요. 이 망할 늑대들이 너무 오랫동안 내 양들을 쫓아다녔어요. 정말 지긋지긋해요! 이제 양들은 엘윈 숲 곳곳에 흩어져서 값비싼 양털을 휘날리며 $B$B겁에 질려 떨고 있어요. 양이 없으면 이 농장도, 내 딸 줄리도 부양할 방법이 없어요. 양털로 핸드백부터 모자까지 온갖 걸 만들지만, 요즘 형편이 어려워요. 그런데, 당신 덩치 좋아 보이는데, 양들을 다시 잡아다 줄 수 있겠어요? 정말 큰 도움이 될 거예요. 보답으로 꼭 보답할게요.$B$B 줄리가 양들이 제일 좋아하는 간식을 만들었어요. 이 엘윈 트러플을 주면 금방 집으로 달려올 거예요."},objectives={{97,169314683},"엘윈 숲에서 길 잃은 농장 양 8마리를 찾아 엘윈 트러플을 먹여 농장으로 데려오세요."},progress={{70,1854199379},"서둘러! 양들이 없으면 우리 농장이 망해가고 있어. 어서 움직여!"},completion={{178,2098722558},"제 양들 때문에 마법사가 성기사 파티에 간 것처럼 걱정했었어요. 정말 안심이 되네요. 너무 고맙습니다. 수고비로 직접 만든 간식 좀 드릴게요."}}
rows[60007]={title={{30,589826254},"룰루는 루핀에게 매혹적인 모습을 보여줍니다"},description={{333,1379861247},"룰루는 농장을 둘러싼 늑대들을 경계심 가득한 눈으로 바라보고 있습니다. 마치 그녀의 작은 심장이 공포에 질려 쿵쾅거리는 소리가 들리는 듯합니다. 늑대들은 입맛을 다시며 공격할 기회를 엿보고 있습니다. 이렇게 순수하고 $B$B사랑스러운 아이가 자기 집에서 그토록 겁에 질려 있다는 건 있을 수 없는 일입니다. 룰루의 불안감을 덜어주는 건 당신의 몫입니다."},objectives={{76,2034180635},"엘윈 숲 주변에서 옴에 걸린 늑대 15마리를 처치한 후 황금골에 있는 룰루에게 돌아가십시오."},progress={{48,1720943955},"바아아아아아아!$B$B<룰루는 절망적인 공포에 떨고 있다.>"},completion={{298,659681053},"룰루는 눈에 새로운 반짝임을 담고 주위를 둘러봅니다. 룰루는 즐겁게 뛰어다니며, 가끔씩 고개를 숙여 맛있는 풀을 뜯어 먹습니다. 당신은 스스로에게 만족감을 느끼며, 무방비 상태의 생명체를 도왔다는 성취감에 흠뻑 빠져듭니다.$B$B룰루는 본능적으로 당신을 따라 다음 목적지까지 갑니다."}}
rows[60008]={title={{15,2100716109},"양모면 될 것 같아요."},description={{529,1071668404},"우리 엄마는 추운 계절에 우리를 따뜻하게 해 줄 멋진 장갑을 만드셨어요. 엄마가 안 계시니 매일 조금씩 더 추워지지만, 엄마는 제게 양모 옷 만드는 법을 모두 가르쳐 주셨어요. $B$B보시다시피 농장에서 양들이 하나둘씩 죽어가고 있어요. 숲에는 양들이 많지만, 저한테는 너무 위험해요. 아빠는 저랑 엄마를 둘 다 잃으면 안 돼요. 그러면 불쌍한 루루만 남게 되실 거예요.$B$B 아빠가 따뜻하게 입으실 수 있도록 양모 몇 뭉치를 모아 주세요. 그리고 당신을 위한 작은 선물도 하나 만들어 드릴게요."},objectives={{94,1388298821},"엘윈 숲에 있는 양들의 털 20묶음을 모아서 줄리 오스워스에게 가져다 주세요."},progress={{56,807908083},"너무 오래 꾸물거리지 마세요. 시간은 소중한 것입니다."},completion={"It brings back good memories to work with the same tools she passed down to me.$B$BI get to weave the same stitches as the ones she taught me before she passed, and that warms my heart.$B$BYou've been a real help to this little ol' farm family, $N. Bless you.","그녀가 물려준 도구들을 사용하니 좋은 추억들이 떠오릅니다.$B$B그녀가 돌아가시기 전에 가르쳐주셨던 것과 똑같은 바느질 기법으로 실을 엮을 수 있게 되어 마음이 따뜻해집니다.$B$B당신은 이 작은 농가 가족에게 정말 큰 도움이 되었습니다.$N축복합니다."}}
rows[60009]={title={{22,2146345417},"윈터베일 더미 퀘스트"},description={{114,418317081},"저희는 플레이어들이 추운 겨울밤에 따뜻함을 느낄 수 있도록 에그노그를 나눠주기를 바랍니다. 엘룬의 뜻이니까요."},objectives={{34,1362882945},"깃털을 모으면 보상을 받습니다."}}
rows[60010]={title={{16,504796798},"난쟁이를 도와주세요"},description={"Hey, $r, down here! If you have some spare time, I could really use your help.$B$BYou see, there's this kodo in Un'Goro Crater, their name is Dadanga. I've heard that they give you a gift if you feed them bloodpetals. It sounds like this gift could have a nice surprise in it, and I love surprises!$B$BAnyways, these bloodpetal sprouts are found all over the crater, and I'd love to get my hands on some. Bring me 30 Bloodpetal Sprouts and I'll pay you. I'll even give you something I cooked from one of my original recipes!","이봐,$r , 여기 아래! 시간 좀 있으면 도와줄래?있잖아,$B$B 운고로 분화구에 다당가라는 코도가 있는데, 피꽃잎을 주면 선물을 준다고 들었어. 그 선물에는 뭔가 특별한 게 들어있을 것 같아. 난 깜짝 선물을 $B$B좋아하거든!어쨌든, 이 새싹은 분화구 곳곳에서 자라는데, 좀 얻고 싶어. 피꽃잎 30개 가져다주면 돈을 줄게. 그리고 내가 직접 만든 요리도 줄게!"},objectives={{85,451084728},"리아스가 가젯잔에 있는 그녀에게 피꽃잎 새싹 30개를 가져다 달라고 부탁한 게 확실하죠?"},progress={{105,387085775},"꽃 받았어? 다당가가 얼른 영약 레시피를 줬으면 좋겠어. 돈이 거의 다 떨어졌거든..."},completion={{103,2101947915},"안녕하세요! 감사합니다! 약속대로 돈이랑 피자병 몇 개 드렸어요!$B$B아, 그거 얘기 안 했었나?"}}
rows[60011]={title={{14,1252025208},"관통하는 빛"},description={{660,1902278286},"성기사이여! 약자를 보호하는 자로서 우리는 악인에게 정의를 구현할 책임이 있습니다. 수없이 많은 적들을 마주하게 될 것입니다. 어떤 적은 흉포하고 잔인하며, 어떤 적은 교활하게 행동합니다. $B$B엘윈 숲 깊숙한 곳, 숲의 가장자리 끝자락에 그러한 적이 숨어 있습니다. 그 사악한 괴물의 이름은 호거입니다. 그는 자신의 놀 부하들을 거느리고 있으며, 그들 사이의 우두머리 역할을 합니다. 수적으로 열세에 몰리지 않도록 $B$B조심하십시오. 적에게 정의를 구현하려면, 당신을 인도할 빛을 믿어야 합니다. 믿음직한 동료들과 함께 모험을 떠나 더 이상의 해악을 끼치기 전에 이 악을 진압하십시오.$B$B 빛이 당신과 함께하길!"},objectives={{38,1044100480},"엘윈 숲 가장자리에서 호거를 물리치세요."},progress={{212,269114004},"적의 약점을 파악하고 정의를 실현하기 위해서는 당신이 가진 모든 역량을 총동원해야 할 것입니다. 무엇보다도 그 어느 때보다 빛에 대한 믿음이 필요할 것이며, 그 빛이 당신에게 힘을 줄 것입니다."},completion={{89,1943852607},"우리 팔라딘에게 허락된 열정은 오직 하나뿐입니다. 바로 섬기고 보호하려는 열정이죠."}}
rows[60012]={title={{14,1252025208},"관통하는 빛"},description={{524,597870274},"성기사이여! 약자를 보호하고 악인에게 정의를 구현하는 것은 막중한 책임입니다. 특히 분노와 결의로 당신이나 당신의 동료들을 파멸로 이끌 수 있는, 너무나 강력하고 흉포한 적과 맞서 싸워야 할 때가 있습니다. 바로 그런 적이 존재합니다. 그는 $B$B'얼음수염 노인'이라 불립니다.$B$B 적의 약점을 파악하고 정의를 구현하기 위해서는 당신이 가진 모든 역량을 총동원해야 합니다. 무엇보다도 그 어느 때보다 빛에 대한 믿음이 중요하며, 빛이 당신에게 힘을 줄 것입니다."},objectives={{39,658156262},"카라노스 서쪽에서 늙은 얼음수염을 물리치세요."},progress={{212,269114004},"적의 약점을 파악하고 정의를 실현하기 위해서는 당신이 가진 모든 역량을 총동원해야 할 것입니다. 무엇보다도 그 어느 때보다 빛에 대한 믿음이 필요할 것이며, 그 빛이 당신에게 힘을 줄 것입니다."},completion={{89,1943852607},"우리 팔라딘에게 허락된 열정은 오직 하나뿐입니다. 바로 섬기고 보호하려는 열정이죠."}}
rows[60013]={title={{15,43163073},"새해 복 많이 받으세요!"},description={{200,1467226968},"모두에게 행복한 연휴 보내시길 바랍니다. 저희 서버를 선택해주시고 변함없는 성원을 보내주시는 모든 거북이 여러분께 진심으로 감사드립니다. 새해에는 즐겁고$B$B 밝은 한 해가 되시길 바랍니다! 새해 복$B$B 많이 받으세요!"},objectives={{21,352859865},"2021년에도 멋진 모습 유지하세요!"}}
rows[60020]={title={{11,981809868},"여군주 자니라"},description={"Ishnu'alah, $C.$B\013\010Not long ago, a group of Sentinels was finally driving the Naga away from Solarsal. Unfortunately, that caught the attention of one of their champions and once she joined the fray they were quickly pushed back by her magic. Please, find and kill this Sea Witch. She can not be allowed to scour Solarsal of its arcane secrets and become stronger.$B$BThe last we saw of her, she was heading towards the ruined temple located in the hill near the tallest tower.","이슈누알라,$C .$B\013\010얼마 전, 파수꾼 무리가 마침내 솔라살에서 나가를 몰아내고 있었습니다. 하지만 불행히도 그 일이 나가의 용사 중 한 명의 눈에 띄었고, 그녀가 전투에 합류하자 파수꾼들은 그녀의 마법에 의해 순식간에 밀려났습니다. 부디 이 바다 마녀를 찾아 처치해 주십시오. 그녀가 솔라살의 신비로운 비밀을 파헤쳐 더욱 강해지는 것을 막아야 $B$B합니다.마지막으로 그녀를 본 것은 가장 높은 탑 근처 언덕에 있는 폐허가 된 사원으로 향하는 길이었습니다."},objectives={{51,1420049049},"솔라살 유적에 있는 레이디 자니라를 처치하세요."},progress={{100,2109260771},"만약 나가족이 그곳에 흩어져 있는 지식을 성공적으로 얻게 된다면, 어떤 세력도 그들을 쫓아낼 수 없을 것이다."},completion={"Thank you, $R!$B$BThat cursed Sea Witch has been driving back our Sentinels time and again, without her direction they will be easier to defeat.","고마워요,$R!$B$B저 저주받은 바다 마녀가 우리 파수꾼들을 계속해서 몰아내고 있어요. 그녀의 지휘가 없으면 파수꾼들을 물리치기가 더 쉬워질 겁니다."}}
rows[60030]={title={{26,1668213808},"패션에는 희생이 따른다"},progress={{525,1698637212},"친구, 당신을 보는 순간 패션 감각이 뛰어나다는 걸 알 수 있어요! 숨기려 하지 마세요. 무지한 속물들의 비웃음에도 아랑곳하지 않는 당신의 대담한 스타일에서 그걸 느낄 수 있어요.$B$B저는 당신의 멋진 스타일을 한층 더 끌어올릴 수 있도록 패션 코인을 기꺼이 제공해 드리고 싶습니다. 그 대가로, 제 차기 획기적인 디자인에 필요한 재료들을 제공해 주시면 감사하겠습니다. 함께라면 패션계를 뒤흔들 수 있을 거예요!$B$B필요한 재료 목록은 다음과 같습니다. 손상되지 않고 최고 품질의 재료인지 확인해 주세요."},completion={{202,785573795},"정말 훌륭합니다! 제가 요청한 모든 것이었고, 상태도 아주 좋네요. 앞으로도 계속 협력할 수 있기를 바랍니다. 혹시 동전이 더 필요하시면 언제든 연락 주세요."}}
