rows[60036]={title={{21,378998154},"올바른 선택을"},progress={{477,549190016},"오늘 여러분께 정말 놀라운 제안을 하나 드리겠습니다!$B$B소문에 따르면 스트라솔름에 사는 광신도들이 신성한 힘이 깃든 구슬을 가지고 다닌다고 합니다. 정의의 구슬이라고 불리죠. 또 다른 귀중한 진주, 완벽한 드레네시스트 구체는 황폐한 땅에 사는 모든 흉악한 악마들의 손아귀에 있다고 합니다.$B$B이 희귀한 보석들을 각각 하나씩 얻는 대가로 패션 코인을 세 개, 세 개나 드리겠습니다. 이 보석들 없이는 제 최신 디자인을 완성할 수 없거든요!"},completion={{226,1433738900},"세상에! 세상에, 세상에, 세상에! 네, 정말 완벽해요! 광택도, 매끄러움도, 모든 게 완벽해요!$B$B여기, 수고비로 이 동전들을 받으세요. 당신이 저를 실망시키지 않을 줄 알았어요. 당신은 정말 최고예요!"}}
rows[60040]={title={{21,187069951},"맛있는 호박 파이"},description={{312,146720897},"맹세컨대 지금 당장 오우거라도 잡아먹을 $B$B수 있을 것 같아! 혹시 스톤필드 농장에 가실 계획이 있으세요? 만약 그렇다면, 스톤필드 할머니께서 만드시는 유명한 엘윈 호박 파이 하나 사다 주실 수 있을까요? 농장은 여기서 남서쪽으로 가면 있어요. 길을 따라가면 절대 놓치지 않으실 $B$B거예요. 파이 사 오시면 꼭 다시 와 주세요!"},objectives={{58,763415152},"맛있는 호박 파이 하나를 황금골에 있는 지나 웰러에게 가져다 주세요."},progress={{41,1677265435},"파이 가져오시면 다시 오세요!"},completion={{99,905789204},"어머, 돌아오셨군요! 파이까지 가져오셨네요! 드디어 달콤하고 맛있는 호박 파이를 먹을 수 있겠어요!"}}
rows[60041]={title={{19,1028723797},"호박 도둑들"},description={{1007,1989212001},"이건 말도 안 돼! 뻔뻔스럽잖아! 먼저 몰래 돌아다니면서 가축들을 놀라게 하더니, 그다음엔 몰래 들어와서 헛간을 털었어. 다음엔 또 뭘 하려는 거야? 우리 집까지 털고? 자는 동안 우리 가족을 다 죽이려는 건가?! 경비병들이 이 상황에 대해 뭘 하고 $B$B있다고 생각하는 거야? 아무것도 안 하고 있잖아! 이 놀들은 날이 갈수록 더 대담해지고 있어, 난 이제 더 이상 참을 수 없어! 경비병들은 아무런 도움도 안 되지만, 네 눈빛에 불꽃이 타오르는 $B$B것 같군. 혹시 나와 내 가족을 지켜줄 수 있겠나? 뭐라고? 파이? 이봐, 그 놀들이 내 호박을 전부 훔쳐갔어! 그 조그만 야만인들은 대충 태우는 것 말고는 아무것도 요리할 줄 몰라! 그놈들이 호박을 가지고 뭘 하려는 거야?! 파이가 그렇게 먹고 싶으면 가서 $B$B내 호박이나 되찾아 와. 그 잡종들이 골드샤이어 너머 북쪽으로 도망치는 걸 봤어. 혹시 이스트베일 벌목 캠프에 있는 누군가 그 꼬맹이들이 어디에 숨어 있는지 봤을지도 몰라요. 거기 사람들한테 내 호박들이 어디로 갔는지 물어봐 주세요! 그리고 가는 김에 그 더러운 도적들도 닥치는 대로 잡아주세요!"},objectives={{50,1988167438},"엘윈 호박 7개를 스톤필드 할머니께 가져다 드리세요."},progress={{119,2020670847},"어머, 설마 그 더러운 짐승들을 땅에 묻어버린 건 아니겠죠! 제 호박들은요? 제 예쁜 호박들은 찾으셨나요?"},completion={"By the Light!$B$BMy dear child, I can't tell you what a blessing you've been to all of us here on the farm!$B$BYou've done more than enough to earn a pie, $N! Take it with my deepest gratitude!","빛으로!$B$B사랑하는 내 아이야, 네가 우리 농장 사람들에게 얼마나 큰 축복이었는지 말로 다 할 수 없구나!$B$B넌 파이를 받을 자격이 충분해,$N! 진심으로 감사하는 마음으로 받아가렴!"}}
rows[60042]={title={{20,1328223482},"리버포우 도태"},description={{443,1632576738},"드디어 지원군이 왔군!$B$B 엘윈 숲 전체에 페드펜넬이라는 강력한 놀이 이끄는 대규모 놀 진영이 있어. 소문에 따르면 그는 자기 라이벌에게 잡아먹혔다고 하던데… 이야기가 딴 데로 샜군. 그 진영은 북쪽으로 더 올라가 $B$B스톤 케언 호수 너머에 있어. 경비병들이 순찰하지 않는 외딴 곳에 숨겨져 있어서 놀들이 날뛰고 있지. 제발 그 놀 부대 하나를 전멸시켜 주면 적어도 일주일은 편히 잘 수 있을 거야."},objectives={{107,2068728886},"리버포 런트 10마리와 리버포 아웃러너 10마리를 처치하고 이스트베일 벌목 캠프의 감독관 라엘렌에게 돌아가십시오."},progress={"I hope you have some good news for me, $N!","$N님, 좋은 소식이 있기를 바랍니다!"},completion={{216,419630634},"뭐라고요? 혼자서 다 하셨다고요?$B$B와, 정말 다행이네요! 이제 그놀들이 우리를 괴롭히지 않겠어요.$B$B어떻게 아셨어요? 테리가 의뢰했나요? 어쨌든, 수고에 대한 보상으로 이걸 받으세요."}}
rows[60050]={title={{10,1279689822},"행운의 동전"},description={{683,687804775},"저기... 어, 실례합니다! 부탁이 하나 $B$B있어요! 하하, 말해버렸네요! 수도원을 나서는 사람에게 말을 거는 건 너무 떨리지만, 제 소원을 이룰 수 있는 유일한 방법이에요.$B$B 아! 부탁이요! 저는 스톰윈드 시티에 가서 갈리나 와이너리에 있는 제 친구 수제타를 만나는 걸 정말 좋아하는데, 무역 지구에 있는 분수대를 항상 지나치거든요. 은행 옆에 있는 그 분수대요! 혹시$B$B 스톰윈드 시티로 가시는 길이라면, 행운을 빌며 이 동전을 분수대에 던져주시겠어요? 동전을 던지면 소원이 이루어진다는 이야기를 들었거든요. 제 소원은 가능한 한 빨리 스톰윈드에 다시 가는 거예요! 아!$B$B 그리고 가능하시다면 수제타 갈리나에게 제 안부도 전해주세요!"},objectives={{125,251862194},"스톰윈드 시티의 무역 지구 분수에 동전을 던져 테레사를 찾은 다음, 갈리나 와이너리에 있는 수제타 갈리나에게 말을 걸세요."},progress={{28,1485051152},"안녕하세요! 여기 처음 오셨나요?"},completion={{55,1430842111},"테레사가 우리를 방문한다는 소식을 듣고 너무 기뻤어요!"}}
rows[60060]={title={{21,522381084},"뿌린 대로 거둔다"},description={{535,1047234435},"생존 자체는 방법을 알면 그렇게 어렵지 않습니다. 하지만 식량이 없을 때는 생존이 훨씬 더 어렵습니다. 사냥이요? 네, 시도해 볼 수는 있겠지만, 안타깝게도 사냥감을 잡기 전까지 간신히 버틸 수 있는 식량이 항상 있는 건 $B$B아닙니다. 당신은 일반 사냥꾼이나 덫 사냥꾼보다 상황을 좀 더 심각하게 고민하는 것 같으니, 야생에서 살아남을 수 있는 최선의 방법을 배워보는 건 어떻겠습니까? 필요한 $B$B것을 가져오시면 제가 알려드리겠습니다. 여기 목록이 있습니다. 잃어버리지 마세요."},objectives={{100,514752570},"컨트리 호박씨, 산딸기씨, 줄무늬 멜론씨, 그리고 환각버섯 샘플을 찾아보세요!"},progress={{69,614625399},"돌아왔군요. 필요한 건 다 찾으셨죠?"},completion={{61,543479874},"좋아요! 몇 가지 새로운 노하우를 알려드릴게요."}}
rows[60061]={title={{21,522381084},"뿌린 대로 거둔다"},description={{710,1547891508},"젊은이, 안녕! 네가 여기 온 유일한 이유는 자신만의 정원을 가꾸고, 다른 방법으로는 식량이 자라지 않을 곳에서 식량을 얻는 법을 배우고 싶어서겠지? 네 눈을 보니 그런 것 같군. 좋아. $B$B먼저 찾아야 할 특별한 씨앗이 있어. 그 씨앗들을 모두 구해 오면 사냥꾼이나 덫 사냥꾼조차도 폭력과 살생을 덜 하는 방법을 알지 못하는 법을 가르쳐주겠다. 이것은 우리 부족이 자랑스럽게 여기고 소중히 가꾸는 축복, 대지의 어머니께서 주신 축복이란다. 이 양피지에 적힌 씨앗들을 모두 구해 오면 다시 내게 오너라. 나는 너를 기다리고 있겠다… 다시. 순풍이 $B$B네 뒤를 따라오길."},objectives={{100,514752570},"컨트리 호박씨, 산딸기씨, 줄무늬 멜론씨, 그리고 환각버섯 샘플을 찾아보세요!"},progress={{79,1518244391},"저는 당신의 사업이 성공적이었고 필요한 모든 씨앗을 확보하셨을 것이라고 확신합니다."},completion={{187,1058065820},"아, 다시 뵙게 되어 반갑습니다. 젊은이들이 대지 어머니에 대한 존엄과 존경심을 가지고 제대로 생존해 온 최고의 전통의 뿌리로 돌아가는 모습을 보니 정말 감동적입니다!"}}
rows[60065]={title={{29,1959484449},"거미줄 짜는 자들의 공포"},description={"Listen closely, for I have no time or strength to repeat, I'm obviously dying here… Light … Elune, give me peace of death, I beg you…$B$B<Argent Watcher Mal'adaris gazes on you with fierce intent.>$B$BTwenty of those horrors $R, and only one … it! Destroy'em for all the living…$B$B<Argent Watcher Mal'adaris points you directly to the north.>$B$BCave … no, a tunnel… Don't go alone.","잘 들어, 다시 말할 시간도 힘도 없어. 난 분명히 여기서 죽어가고 있어… 빛… 엘룬이시여, 제게 죽음의 평화를 주소서… <은빛 감시자 말라다리스가$B$B 사나운 눈빛으로 당신을 응시합니다.> <저 끔찍한 괴물이 스무$B$B 마리나 있는데… 단 $R하나뿐이야… 바로 저거야! 모든 산 자들을 위해 저들을 없애버려…$B$B <은빛 감시자 말라다리스가 당신을 북쪽으로 가리킵니다.> $B$B<동굴… 아니, 터널이야… 혼자 가지 마.>"},objectives={{42,1982046877},"테러웹 터널에서 크립트 호러 20마리를 처치하세요."},progress={{4,273767400},"예?"},completion={{13,35340116},"네가 뭘 했다고?"}}
rows[60070]={title={{15,1313414440},"신뢰의 문제"},description={"Trust is something you can't buy, $R. Here's the deal, lad. You earn the trust of this gryphon over here and you'll get your ride to the camp. Fail and he'll have you as his breakfast.$B$BHah! Of course I'm pulling your leg here, lad. The winged beast won't even budge unless it trusts you completely. How, you ask? Food, of course. And a toy. Go figure. He likes to gnaw on them discarded bones the Lion's Pride Inn's cook throws out with the trash. He's gone and snapped all his, judging by the refuse at his talons.","신뢰는 돈으로 살 수 있는 게 $R아니야, . 자, 잘 들어. 여기 있는 이 그리핀의 신뢰를 얻으면 캠프까지 태워다 줄게. 실패하면 넌 아침 식사가 될 거야.하하! $B$B물론 농담이지, 꼬마야. 저 날개 달린 짐승은 널 완전히 믿지 않으면 꼼짝도 안 할 거야. 어떻게 믿냐고? 당연히 먹을 주면 되지. 그리고 장난감도 필요해. 저 녀석은 라이온스 프라이드 여관의 요리사가 쓰레기로 버리는 뼈를 씹는 걸 좋아하거든. 발톱에 묻은 걸 보니 이미 다 뜯어먹은 것 같군."},objectives={{110,188691942},"골드샤이어에 있는 켈튼의 그리핀 승용마에게 멧돼지 고기 5덩어리, 드워프 순한 치즈 3개, 씹는 장난감 1개를 가져다 주세요."},progress={{209,514849670},"그리핀은 당신을 빤히 쳐다보지만, 까악까악 울고 불안하게 횡설수설하는 모습에서 그다지 만족스러워 보이지 않습니다. 분명히 배고프고 짜증이 난 것 같습니다. 드워프의 유명한 순한 술 한 줌이면 좀 나아질까요?"},completion={{203,2114715203},"그리핀은 당신이 가져온 간식 냄새를 맡으며 흥분해서 주변 공기를 킁킁거립니다. 눈동자가 커지고 당신 손에 들린 자신이 가장 좋아하는 씹는 장난감을 보자 기쁨에 겨워 짹짹거립니다.$B$B정말 행복해 보이네요!"}}
rows[60071]={title={{23,806976348},"시든 껍질 깨기"},description={"Hey, $N, that was your name wasn't it?$B$BYou probably know that we have some troll problems, so we decided to hire more adventurers such as yourself, sounds good right?$B$BYour first target will be the Witherbarks to the east of Aerie Peak, they're too close for comfort and they brew deadly poisons right at our doorstep! Are you up for challenge?","이봐,$N , 네 이름이 그거였지?$B$B아마 우리 마을에 트롤들이 좀 골칫거리라서 너 같은 모험가들을 더 고용하기로 했어. 괜찮지?네 첫 $B$B번째 목표는 에어리 피크 동쪽에 있는 위더바크들이야. 너무 가까이에 있고, 바로 우리 코앞에서 치명적인 독약을 제조하고 있거든! 도전해 볼래?"},objectives={{160,640562694},"드라킨 스위프트액스는 당신에게 바일브랜치 스캘퍼 10마리, 바일브랜치 질럿 10마리, 바일브랜치 베놈블러드 5마리를 처치해달라고 부탁했습니다. 임무를 완료하면 그에게 돌아오십시오."},progress={{57,1943753437},"겁쟁이처럼 굴지 말고 가서 악플러들에게 누가 주인인지 보여줘!"},completion={{103,1544193903},"정말 해냈다고? 당연히 난 항상 널 믿었지! 자, 수고비로 금화 좀 받아가."}}
rows[60072]={title={{23,749240898},"사악한 가지 다듬기"},description={"Back for more, $N?$B$BThere is still more to do and more rewards to claim. Your next target will be the Vilebranchs, we think they're preparing something big. Their chanting can be heard even from here! Go to the Altar of Zul to the southeast, and trim their numbers!","?다시 돌아왔군!$N$B$B 아직 할 일도 많고 보상도 많다. 다음 목표는 사악한 가지들이다. 그들이 뭔가 큰일을 꾸미고 있는 것 같군. 여기서도 그들의 주문 외우는 소리가 들려! 남동쪽에 있는 줄의 제단으로 가서 그들의 수를 줄여라!"},objectives={{119,1752503487},"드라킨 스위프트액스는 당신에게 사악한 가지 예언자 15마리와 사악한 가지 두피 벗기는 자 30마리를 처치해 달라고 부탁합니다. 완료하면 그에게 돌아오세요."},progress={{58,285259340},"네가 그랬니? 저들을 막지 못하면 우린 끝장날지도 몰라."},completion={"I knew it was nothing for a $C like you! Here, take this for your troubles.","너 같은$C에게는 아무것도 아닐 거라는 걸 알고 있었지! 자, 수고에 대한 보상으로 이걸 받아."}}
rows[60073]={title={{20,33190300},"그들의 전열을 궤멸시켜라"},description={"Alright $N, we've chased the rats to their den. To the very southeast of the Hinterlands you'll find the troll city of Jintha'Alor. You'll encounter the very elite, practicing dark magic and foul rituals. I know you're powerful, but I'm not gonna lie, I don't think you can do this alone.$B$BBring some friends and kill EVERY. SINGLE. TROLL. Now go out there and sweep the city!","좋아, $N, 쥐들을 소굴까지 몰아냈어. 오지 남동쪽 끝에 트롤 도시 진타알로르가 있어. 거기서는 흑마법과 사악한 짓을 일삼는 최상위 트롤들을 만나게 될 거야.  네가 $B$B전능하다는 건 알지만, 솔직히 말해서 혼자서는 감당하기 힘들 것 같아. 친구들을 데려와서 모든 트롤을 처치해. 자, $B$B이제 나가서 도시를 휩쓸어버려!"},objectives={{212,334599082},"드라키르 스위프트액스는 당신에게 바일브랜치 버서커, 바일브랜치 섀도우 헌터, 바일브랜치 블러드 드링커, 바일브랜치 소울 이터 각각 20마리씩을 처치하라는 임무를 내렸습니다. 완료할 때까지 돌아가지 마십시오."},progress={{88,575673902},"네가 한 거야, 아니면 친구가 없는 거야? 내 알 바 아니니까, 가서 친구나 사귀고 도시를 싹 쓸어버려!"},completion={"You are a true hero, $N.$B$BI expected nothing less from you. Here take this, it has more power than you think.","당신은 진정한 영웅입니다,$N,$B,$B. 당신에게서 그 이상을 기대하지 않았습니다. 자, 이것을 받으세요. 생각보다 훨씬 강력한 힘을 가지고 있습니다."}}
rows[60074]={title={{25,318886216},"여사제를 쓰러뜨려라!"},description={{403,1256813363},"그동안 너희들에게 트롤들을 마구잡이로 처치하게 시켰지만, 이번에는 드디어 제대로 된 목표물이 생겼다! 악의 여사제 헥스가 악의 분파 트롤들을 규합해 에어리 봉우리를 공격하려 한다는 보고를 받았다! 절대 용납할 수 없지, $B$B그렇지?친구들을 모아 남동쪽 끝에 있는 진타알로르 성채로 올라가 헥스와 그녀의 특수 경비병들을 처치해라. 너희의 노고에 대한 보상은 쏠쏠할 것이다."},objectives={{194,24372386},"드라키르 스위프트액스는 에어리 피크의 최남동쪽에 위치한 진타알로르 시에서 사악한 여사제 헥스와 사악한 가지 아만자시 경비병 20명을 처치해 달라는 임무를 당신에게 맡겼습니다.\013\010\013\010임무를 완료하면 그에게 돌아오십시오."},progress={{95,2027423436},"시간이 흐를수록 공격 가능성이 높아지니, 그곳으로 가서 그녀의 계획을 막아라!"},completion={{145,64984760},"당신은 사악한 가지 트롤들에게 정말 큰 타격을 입혔습니다. 그들은 당분간 우리를 공격하지 못할 겁니다. 영웅이신 당신에게 걸맞은 보상을 드리겠습니다!"}}
rows[60104]={title={{29,1485598043},"미지의 세계로 [사용 중단됨]"},description={{726,275274790},"안녕하세요! 용감해 보이시네요. 제가 여행 방식을 완전히 바꿔놓을 장치를 개발 중이라고 말씀드리면$B$B 어떠시겠어요? 마법사들이 사용하는 마법 룬을 교묘하게 재조합하여 지구 반대편으로 순간 이동할 수 있는 웜홀을 여는 장치를 만들었습니다. 자, 여행의 방식을$B$B 바꿀 발명품을 소개합니다! 저는 이것을 휴대용 웜홀 생성기라고 부릅니다. 이제$B$B 남은 건 시험뿐인데... 바로 당신이 필요한 부분입니다.$B$B 생성기가 만들어낸 포털 안으로 들어가시면 반대편에 도착하게 되고, 그곳에서 제 파트너가 기다리고 있을 겁니다. 성공하시면 감사의 표시로 이 장치를 하나 드리겠습니다. 행운을 $B$B빌어요!"},objectives={{33,1889562779},"휴대용 웜홀 발생기 테스트."},progress={{42,1804683188},"두려워할 건 아무것도 없어요... 정말 아무것도요!"},completion={"By the Gods it actually worked! I can't believe it!$B$BI mean... of course it worked, worked just fine.$B$BThis changes everything. Thank you $R, it took no small amount of courage to step into that portal not knowing for certain what was on the other side. I'm sure you got promised a reward, so here it is, your very own Portable Wormhole Generator.$B$BUse it well, and for your own good don't fiddle around with it. Good luck!","세상에, 진짜 성공했어! 믿을 수가 없어!$B$B아니... 당연히 성공했지, 아주 잘 됐어.$B$B이건 모든 걸 바꿔놓을 거야. 고마워.$R그 너머에 뭐가 있는지 확실히 모르는 상태에서 그 포털로 들어가는 건 정말 용기가 필요한 일이었어. 보상으로 뭘 주기로 약속했는지 알아서 줄게. 자, 여기 네 전용 휴대용 웜홀 생성기야.$B$B잘 사용하고, 절대 함부로 만지지 마. 행운을 빌어!"}}
rows[60107]={title={{9,565124446},"발이 차가워요"},description={"The damned cold won't leave me. I thank you for the pelts, $N but I wonder if I may trouble you again?$B$BI paid a helpful soul, Calvin, to go to Solliden Farmstead to retrieve my slippers before you happened along. He hasn't returned and I've heard that he may be less than honest. Undeath doesn't change an opportunist it seems. My slippers are in a footlocker at the farmstead.$B$BThe reports I overheard about Scarlets in the area are the least concerning. The murlocs like anything shiny I've heard and I did keep that footlocker polished up...","지독한 추위가 가시지 않네요. 모피 주셔서 감사합니다,  $N님. 그런데 또 부탁드려도 될까요?  $B$B당신이 오시기 전에 제 슬리퍼를 솔리덴 농장에서 가져오라고 캘빈이라는 친절한 사람에게 부탁했는데, 아직 돌아오지 않았고 그가 정직하지 않다는 소문도 들었습니다. 언데드가 된다고 해서 기회주의자가 변하는 건 아닌 것 같더군요. 제 슬리퍼는 농장의 발 보관함에 있습니다.$B$B 이 지역에 스칼렛이 출몰한다는 소문은 별로 걱정할 게 없네요. 멀록들은 반짝이는 걸 좋아한다고 들었고, 저는 그 발 보관함을 항상 깨끗하게 닦아 놓았거든요…"},objectives={{83,2087072237},"솔리덴 농장 북쪽에 있는 반짝이는 발 보관함에서 그레첸의 슬리퍼를 가져오세요."},progress={"Hello again, $N. Have you made the trip to the shore North of Solliden Farmstead yet?","안녕하세요,$N님. 솔리덴 농장 북쪽 해안가에 다녀오셨나요?"},completion={{139,1065836413},"내 슬리퍼야! 정말 고마워! 큰 친절을 베풀어줘서 고맙다. 수고에 대한 보답으로 이 동전을 받아라. 어둠의 여신이 너를 지켜줄 것이다."}}
rows[60108]={title={{14,838287127},"아루갈의 어리석음"},description={"Greetings, $C!$B$BWe've been on the tail of Archmage Arugal for some time, since the end of the Third War actually. What did he do? When the Scourge came to Dalaran, we were devastated.$B$BSeeing our friends and family being turned undead really messed with his mind. He thought the solution was a summoning ritual, to summon something that could aid us and stop the Scourge's advance. Even though as his mentor I advised against his idea, my warnings fell on deaf ears.$B$BThe resulting monstrosities are the Worgen. Even though they killed the Scourge, they quickly turned on us, worsening the situation. After going mad with his failure, he adopted the worgen as his children and retreated to Shadowfang Keep.$B$BAfter what had transpired I moved to Stormwind to try to forget what happened. Although it pains my heart to say this, you must travel to Shadowfang Keep in southern Silverpine Forest and end his life.","안녕하세요,$C$B$B 님! 저희는 3차 전쟁이 끝난 이후부터 대마법사 아루갈을 추적해 왔습니다. 그가 무슨 짓을 저질렀냐고요? 스컬지가 달라란을 덮쳤을 때, 저희는 큰 $B$B충격을 받았습니다. 친구와 가족들이 언데드로 변하는 모습을 보고 그는 정신적으로 큰 충격을 받았죠. 그래서 스컬지의 진격을 막고 우리를 도울 무언가를 소환하는 의식을 치르기로 했습니다. 스승인 제가 아무리 반대해도 소용없었습니다. 그 결과 탄생한 괴물이$B$B 바로 늑대인간입니다. 스컬지를 처치하긴 했지만, 그들은 곧 저희에게 등을 돌려 상황을 더욱 악화시켰습니다. 실패에 미쳐버린 그는 늑대인간들을 자식처럼 키우며 그림자송곳니 요새로 도망쳤습니다. 그 후 저는 그 $B$B일을 잊기 위해 스톰윈드로 왔습니다. 하지만 이런 말씀을 드리기가 정말 마음 아프지만, 당신은 은빛소나무 숲 남쪽에 있는 그림자송곳니 요새로 가서 그의 목숨을 거두어 주셔야 합니다."},objectives={{105,724591581},"대마법사 안드로마스가 당신에게 대마법사 아루갈을 처치하라는 임무를 맡겼습니다. 임무를 완료하면 그에게 돌아가십시오."},progress={{41,292987710},"네가 한 거야? 더 이상 기다릴 수 없어."},completion={{79,649701033},"고마워요, 영웅이시여. 어쩔 수 없었어요. 이걸 받으세요. 그에 대한 마지막 추억입니다."}}
rows[60109]={title={{20,1620676496},"사라진 마법사"},description={{473,1556329819},"존경하는 동료 한 명이 사악한 대마법사 아루갈이 섀도팽 요새 안에서 꾸미고 있는 음모에 대한 중요한 정보를 수집하러 떠났는데, 그 이후로 소식이 없습니다. 저는 그곳이 아무리 강력하고 유능한 마법사에게라도 미치는 타락한 영향력이 걱정스럽고, 애쉬크롬브 마법사의 행방을 알아야 합니다. 실버파인 $B$B숲으로 가서 요새에서 그를 찾아주십시오. 빛의 뜻이라면, 그가 무엇을 알아냈는지 알아내 주십시오."},objectives={{133,287641587},"대마법사 안드로마스는 당신에게 은빛소나무 숲의 섀도팽 요새로 가서 마법사 애쉬크롬에게 무슨 일이 일어났는지 알아내 달라고 부탁합니다."},progress={{72,125578431},"이 벽 안에는 형언할 수 없는 어둠이 영원히 머물 것입니다."},completion={{252,217137695},"대마법사 안드로마스가 당신을 보냈습니까?$B$B세상에, 광기와 공포가 사방에서 펼쳐지는 것을 지켜보니 시간이 정말 빨리 지나가더군요.$B$B제가 알아낸 것을 가지고 돌아가서, 여기에 갇힌 자들과 같은 광기에 빠지지 않았다는 것을 그를 안심시켜야겠습니다."}}
rows[60110]={title={{17,730743823},"사악한 기티스"},description={"Iverron was attacked, you say? And by Githyiss herself, outside the Shadowthread Cave? This is grave news... To think that the broodmother of the webwood spiders has become this hostile.$B$BI had already heard rumors of her mercilessly overhunting the local wildlife. If she has gone so far as to attack our people, however... It pains me to say this, but I fear that she must be put down. Her violent nature now threatens the very balance of Shadowglen.$B$BTake great caution if you are to hunt her, $N; her poison is much stronger than any of her brood's. If you could, please bring back her venom sac so that I may further my research. I only hope it may yield answers to what is happening across Teldrassil.","이베론이 공격받았다고요? 그것도 그림자실 동굴 밖에서 기티스에게 직접 공격당했다니? 심각한 소식이군… 거미줄나무 거미의 어미가 이렇게까지 적대적으로 변하다니. 그녀가 지역$B$B 야생 동물을 무자비하게 사냥한다는 소문은 이미 들었지만, 우리 부족까지 공격했다니… 이런 말을 해야 할지 모르겠지만, 어쩔 수 없이 그녀를 처치해야 할 것 같소. 그녀의 난폭한 본성이 이제 그림자글렌의 균형을 위협하고 있소. 그녀를 사냥할 $B$B때는 각별히 조심하오, N. 그녀의 독은$N 새끼들의 독보다 훨씬 강력하오. 가능하다면 그녀의 독주머니를 가져와 주시오. 연구를 더 진행할 수 있도록 말이오. 텔드라실 전역에서 벌어지고 있는 일의 해답을 찾을 수 있기를 간절히 바라오."},objectives={{86,221286700},"사악한 기티스를 처치하고 그녀의 독주머니를 획득한 다음, 길샬란 윈드워커에게 돌아가십시오."},progress={{72,443106529},"우리는 어미 새를 처치해야 합니다. 유감스럽게도 다른 선택의 여지가 없습니다..."},completion={"Do not be troubled by what needed be done, $N. Githyss was aggressive beyond our ability to manage. The reason for this, I do not know, but one I hope to uncover in my research. Hold your head with pride; you have ensured the continued safety of Shadowglen.","해야 했던 일에 대해 걱정하지 마십시오,$N. 기티스는 우리가 감당할 수 없을 정도로 공격적이었습니다. 그 이유는 저도 모르지만, 연구를 통해 밝혀낼 수 있기를 바랍니다. 자부심을 가지세요. 당신 덕분에 섀도글렌의 안전이 계속 보장되었습니다."}}
rows[60111]={title={{15,32092643},"결정적인 일격"},description={"You have proven yourself a capable defender of our roads and our people, $c. I believe you will be a great asset in putting an end to those responsible for these attacks once and for all. Our scouts have pinpointed the locations of two of the leaders of the Gnarlpine, Agal and Greenpaw.$B$BAgal, who orchestrates ambushes upon those traveling the road to Darnassus, resides in a cave just below the road. Greenpaw is a powerful shaman who has entrenched himself and his kin deep in the Ban'ethil Barrow Den, desecrating our sacred grounds and terrorizing those within and in the lands surrounding the den.$B$BExercise caution, for they are well protected by their tribesmen. I suggest you enlist the aid of a dependable ally if you intend to strike at these two. May Elune protect you and guide you on your path.",", 당신은 우리 도로와 백성을 지키는 유능한 수호자임을 증명해 $c보였습니다. 저는 당신이 이러한 공격의 배후들을 완전히 소탕하는 데 큰 도움이 될 것이라고 믿습니다. 우리 정찰병들이 그날파인족의 지도자 두 명, 아갈과 그린포의 위치를 ​​파악했습니다.$B$B다르나서스로 가는 길을 지나는 사람들을 매복 공격하는 아갈은 길 바로 아래 동굴에 숨어 있습니다. 그린포는 강력한 주술사로, 그의 일족과 함께 바네틸 무덤 동굴 깊숙이 자리 잡고 우리의 신성한 땅을 더럽히고 동굴 안팎의 사람들을 공포에 떨게 하고 있습니다.그들은 부족원들의 철저한$B$B 보호를 받고 있으니 조심하십시오. 만약 이 둘을 공격할 생각이라면 믿을 만한 동맹의 도움을 받는 것이 좋겠습니다. 엘룬께서 당신을 보호하시고 당신의 길을 인도하시기를 바랍니다."},objectives={{129,497451428},"달의 여사제 아마라는 다르나서스로 가는 길 아래 동굴에서 아갈을, 그리고 바네틸 무덤 동굴 안에서 그린포를 처치해 달라고 부탁했습니다."},progress={"Agal and Greenpaw were once honorable and powerful allies. Now, in their madness, they pose a great threat to all who travel this road. There cannot be peace so long as they live, $c.","아갈과 그린포는 한때 존경받고 강력한 동맹이었지만, 이제 광기에 휩싸여 이 길을 여행하는 모든 이들에게 큰 위협이 되고 있다. 그들이 살아있는 한 평화는 있을 수 없다,$c."},completion={"Then it is done? It pains me greatly that it had come to this, but your actions today have ensured safe passage to Darnassus for our people.$B$BYour valor shall not go unrewarded, $c. Elune's blessing be upon you, always.","그럼 모든 게 끝난 겁니까? 이런 지경에 이르게 된 것이 너무나 마음 아프지만, 오늘 당신들의 행동 덕분에 우리 백성들이 다르나서스까지 무사히 갈 수 있게 되었습니다.$B$B너의 용맹함은 결코 헛되지 않을 것이다.$c엘룬의 축복이 언제나 당신과 함께하길 바랍니다."}}
rows[60112]={title={{18,1952971560},"쓰러진 모험가들"},description={{231,1501189614},"말라의 소원을 들어줘야 하지만, 사무엘의 친구들을 생각하지 않을 수 없습니다. 그들은 회복 불가능한 몸과 마음으로 영원히 재앙의 노예가 되었습니다. 부디, 그들을 보게 된다면… 편히 잠들게 해 주세요."},objectives={{140,2065388681},"수습 기사 엘레스가 카렐 그레이브스, 다니엘 울프만, 스티븐 바르텍을 처치해달라고 부탁했습니다. 그들은 데스넬의 문 근처 야영지에서 마지막으로 목격되었습니다."},progress={{167,1067619408},"그들은 모두 함께 티리스팔을 탐험하곤 했습니다. 카렐은 대장장이였고, 다니엘은 사냥꾼이었으며, 스티븐의 지혜는 그들 모두를 이끌었습니다. 그들이 이렇게 된 모습을 보니 마음이 너무 아픕니다."},completion={"Thank you, $N. It is a shame they never broke free of the Scourge's control. They would've made powerful allies.","$N님, 감사합니다. 그들이 스컬지의 지배에서 벗어나지 못한 것이 안타깝네요. 강력한 동맹이 되었을 텐데 말이죠."}}
rows[60113]={title={{9,86013502},"독성"},description={{210,507848463},"내 이론이 맞다면, 인간의 피는 내가 만들고 있는 역병에 반응할 것이다. 멀록 비늘을 모으러 나가는 김에 솔리덴 농장에 가서 농부들과 농장 일꾼들의 피를 가져오도록 해라."},objectives={{125,589347620},"연금술사 요한은 솔리덴 농장에 있는 티리스팔 농부들로부터 인간 혈액 5병을 모아 달라고 부탁했습니다."},progress={{166,1993276626},"솔리덴 농장을 찾는 건 어렵지 않을 거예요. 거기서 호박을 샀잖아요... 만약 기억이 안 난다면, 뇌 이식 수술을 받는 게 좋을 거예요."},completion={{126,1230579145},"좋아. 아주 좋아. 이 정도 피면 내 역병을 완벽하게 만들기에 충분하겠군. 다른 약제사들이 이 이점을 부러워할 거야."}}
rows[60114]={title={{26,189356300},"차가운 바람의 공포"},description={{245,1696552938},"저는 이 동굴에서 캠핑하는 걸 좋아하지만, 늙은 얼음수염이 이 근처에 사는 한 제 음식을 훔쳐갈까 봐 늘 불안합니다. 그의 수염을 가져다주시면 멋진 전리품이 될 뿐 아니라, 이곳도 훨씬 안전해질 겁니다."},objectives={{73,483648522},"툰드라 맥그랜이 당신에게 올드 아이스비어드를 처치하고 그 수염을 모아달라고 부탁했습니다."},progress={{71,1857710082},"그를 죽였습니까? 이제 조심하는 게 좋을 겁니다. 이건 평범한 웬디고가 아니니까요."},completion={{129,1932071778},"좋아요! 바로 그거죠! 여기 제 친구 한 명이 로크 모던으로 떠났다가 영영 돌아오지 않아서 남겨둔 물건들이 좀 있어요."}}
rows[60115]={title={{17,691535311},"예방적 파업"},description={{622,70500934},"샤프터스크 외에도 브리슬백 무리에는 간과할 수 없는 또 다른 위협이 있습니다. 우리 정찰병들이 가시멧돼지 무리 중 한 명이 브램블블레이드 협곡의 동굴에 숨어 우리 부족을 공격할 계략을 꾸미고 있다고 보고했습니다.$B$B 가시멧돼지들은 멀고어를 노리는 치밀한 계획을 세우지 않아도 충분히 흉포한 적입니다. 그러니 이 책략가를 살려둘 수는 없습니다. 가서 이 교활한 브리슬백을 찾아내 처치하고, 그의 죽음을 증명할 증거를 $B$B가져오십시오. 가능하다면 가시멧돼지들이 어떤 전술과 정보를 개발해 왔는지에 대한 단서를 제공하는 문서들을 꼼꼼히 살펴보십시오."},objectives={{186,889842459},"레드 클라우드 메사에 사는 용감한 윈드페더가 브램블블레이드 협곡 어딘가에 숨어 있는 브리스틀백 부족의 전략가를 찾아달라고 부탁했습니다. 이 멧돼지를 처치하고 그 증거를 가져오세요."},progress={"Have you found anything, $N?","$N님, 뭔가 찾으셨나요?"},completion={"Already I feel that our people are safer thanks to your decisive blow against the Bristlebacks, $N. Your actions speak highly of your dedication to protecting our tribe.$B$BMay the Earth Mother guide your path.","$N님, 브리슬백스에 대한 당신의 결정적인 타격 덕분에 우리 부족이 더욱 안전해졌다고 느낍니다. 당신의 행동은 우리 부족을 보호하려는 당신의 헌신을 여실히 보여줍니다.$B$B대지의 어머니께서 당신의 길을 인도하시기를 바랍니다."}}
rows[60116]={title={{19,1486148750},"장미를 붉게 칠하라"},description={"It's about time someone with some skills showed up around here! It's one thing to send fresh bodies after the lower Scarlet ranks, but I need an experienced $C if we're going to bring down the zealots on their own grounds.$B$BHmm. I seem to recall you being quite the efficient killer. Let me see that you've still got what it takes to serve. Thin the ranks outside the Monastery!","이제 실력 있는 사람이 나타날 때가 됐군! 스칼렛 하위 조직원들을 처리하는 데는 신병을 보내는 것도 좋지만, 광신도들을 그들의 본거지에서$C 소탕하려면 경험 많은 가 필요해.Hmm. 자네가 꽤$B$B 효율적인 살인자였다고 기억하는데. 자네가 아직도 우리를 섬길 만한 실력을 갖추고 있는지 확인해 보지. 수도원 밖 적들을 소탕해라!"},objectives={{103,668871869},"스칼렛 수도원 외부의 스칼렛 병력을 제거한 다음, 브릴에 있는 데스가드 ​​버제스에게 돌아가십시오."},progress={{5,914677037},"잘?"},completion={{121,540681454},"이제 우리 군대는 전투에 나설 최상의 컨디션과 기습 공격의 이점을 가지고 수도원에 진입할 수 있습니다. 바리마트라스 신께서 기뻐하실 것입니다."}}
rows[60117]={title={{17,1594506141},"분노로 붉게"},description={"You! $R! I wonder if you could do me a favor. Deathguard Burgess in Brill has been ranting about his station, and only having access to the inexperienced members of the horde. He has something that requires a more learned hand and he's prepared to pay.","당신!$R ! 부탁 하나만 들어주시겠어요? 브릴에 있는 데스가드 ​​버제스가 자기 직책에 불만을 토로하면서, 경험 없는 호드원들만 상대해야 한다고 하네요. 좀 더 숙련된 사람의 손길이 필요한 일이 있는데, 돈을 내겠다고 합니다."},objectives={{37,420748964},"브릴에 있는 데스가드 ​​버제스에게 말을 걸어보세요."},completion={"<The Deathguard looks you over approvingly.>$B$BYes, yes you'll do. Come here $C.","<데스 가드가 당신을 호의적으로 훑어봅니다.>$B$B네, 좋습니다. 이리 오세요$C."}}
rows[60119]={title={{13,776847722},"웨인 매너스"},description={"Excuse me, $R. I hope I'm not bothering you but I'd ask you a courtesy if you've the time.$B$BI lived in Strahnbrad a lifetime ago and my manor fell to ruin before the third war when the orcs came. There were a few items left behind that would serve me in this unlife so I sent someone for them.$B$BThe troll I sent has since returned with my heirlooms but I overheard her warning Melisara of the ogres in the area. Melisara has arranged for the maulers within the ruins of Alterac to be destroyed but has no interest in the weaker ogres in the surrounding caves.$B$BI have access to ample means to reward you if you would thin their numbers.","실례합니다,$R 님. 혹시 실례가 되지 않는다면, 시간이 되신다면 부탁드릴 일이 있습니다.$B$B$저는 아주 오래전 스트라흐브래드에 살았는데, 오크들이 침략해 오기 전 제 저택은 폐허가 되었습니다. 불멸의 삶에서 쓸 만한 물건 몇 가지가 남아 있어서 누군가를 보내 가져오게 했습니다.$B$B제가 보낸 트롤은 유물을 가지고 돌아왔지만, 멜리사라에게 이 지역에 오우거들이 있다고 경고하는 것을 우연히 들었습니다. 멜리사라는 알터랙 폐허 안에 있는 거대한 오우거들은 처리했지만, 주변 동굴에 있는 약한 오우거들에게는 관심이 없다고 합니다.$B$B$그들의 수를 줄여주신다면, 제가 충분한 보상을 해드릴 수 있습니다."},objectives={{50,1812520555},"크러쉬리지 오우거 15마리와 크러쉬리지 브루트 15마리를 처치하세요."},progress={{73,1417186391},"안녕하세요! 여기 계신 걸 보니 작업이 완료된 것 같네요? 아니라고요?$B$B아쉽네요."},completion={{218,1979796322},"다시 뵙게 되어 정말 반갑습니다! 제 집사가 산꼭대기에서 당신의 행동을 지켜봤습니다. 도로를 더 안전하게 만들어주셔서 정말 감사합니다. 언젠가 웨인 저택은 복원될 것이고, 그때는 도굴꾼들이 도처에 돌아다니는 것을 용납할 수 없겠죠!"}}
rows[60120]={title={{10,2062764127},"트리거됨!"},description={"Now that introductions are out of the way, you and I are kinda like partners, yeah? Here's the thing, more than the general supplies sent from Ratchet we had a special order those harpies took. Those feathery fiends got their claws on at least two crates of weapons and ammo meant for Orgrimmar.$B$BWorse than the harpies is the tauren merchant expecting the goods. She might use me for target practice if she finds out her order got lost in delivery a second time.$B$B$N, I gotta get those crates back!","자, 소개는 이쯤 하고, 우리 이제 파트너 같은 사이인 것 같죠? 문제는, 톱니항이 보낸 일반 물자 외에도 하피들이 훔쳐간 특별 주문품이 있다는 겁니다. 그 깃털 달린 악마들이 오그리마로 보내질 무기와 탄약 상자 두 개를 훔쳐갔어요. 하피들보다 더 심각한 건 그 $B$B물건을 기다리고 있는 타우렌 상인이에요. 만약 주문한 물건이 두 번째로 배송 중에 분실됐다는 걸 알게 되면 저를 표적 삼아 쏴버릴지도 몰라요. 어쨌든,$B$B$N 그 상자들을 되찾아야 해요!"},objectives={{96,682869974},"레이저윈드 협곡의 탄약 상자에서 카자의 탄약을 찾아 오그리마 근처의 레즐락에게 돌아가세요."},progress={{33,1109173477},"난 총 맞고 싶지 않아. 너도 그렇지?"},completion={{204,2070816206},"정말 다행이야, 찾았구나. 하피들이 소총을 들고 있을까 봐 걱정했거든. 저 발톱으로 방아쇠를 당길 수 있을까? 아, 생각해보니 그냥 잊어버리는 게 낫겠다."}}
rows[60121]={title={{24,385422489},"우편물은 반드시 통과되어야"},description={"You know, since there's another shipment coming, I might as well just wait for them here. I got a few more coins here to spare, and so far my eye for talent hasn't lead me wrong with you.$B$BNow I know I want to hire more $cs for later jobs, but we still have to get these weapon crates to Orgrimmar. A goblin's reputation is ninety percent of his business! How about it? Mind hauling this stuff the rest of the way for me?$B$BMy no good cousin Kozish should have made it there hours ago. He had more cargo to deliver and is probably drinking away his paycheck at the first pub he saw by now. Check there for him in the Valley of Strength.","있잖아, 또 다른 화물이 올 예정이니까 여기서 기다리는 게 좋겠어. 여유 자금도 좀 있고, 지금까지 내 안목이 너한테서 틀린 적이 없었거든.$B$B나중에 일을 위해 s를 $c더 고용하고 싶긴 하지만, 이 무기 상자들을 오그리마까지 운반해야 하잖아. 고블린에게 평판은 사업의 90%를 차지한다고! 어때? 남은 짐 좀 운반해 $B$B줄래?내 못된 사촌 코지쉬가 몇 시간 전에 도착했어야 했는데. 배달할 화물이 더 있어서 지금쯤이면 월급을 탕진하고 있을 거야. 힘의 계곡에서 한번 찾아보라고."},objectives={{65,1562990789},"레즐락의 화물을 오그리마에 있는 레즐락의 사촌 코지쉬에게 전달하세요."},progress={{19,274242597},"난 혼자 마셔, 친구."},completion={{167,1649934412},"<고블린이 컵을 벌컥벌컥 마시며 당신을 알아챕니다.>$B$B그래, 무슨 일이야? 아, 물자는 무사히 도착했나 보군. 안됐군, 난 이 일은 이제 그만둘래.$B$B어쩌면 해적이 되어볼 수도 있겠지..."}}
rows[60122]={title={{16,786669163},"배송 중"},description={{134,1248680822},"난 저 타우렌 근처에도 안 갈 거야!$B$B 나 실업자잖아, 기억 안 나? 임무를 완수하고 싶으면 네가 직접 카자에게 가."},objectives={{59,67233763},"레즐락의 나머지 화물을 오그리마에 있는 카자에게 전달하세요."},progress={{102,2115611864},"그녀는 주문 포장을 하던 도중 잠시 멈춰 당신을 희망에 찬 눈으로 바라봅니다. 당신의 빈손을 보고 그녀는 얼굴을 찌푸립니다."},completion={{170,225799432},"조상님들께 감사드려야겠군, 내 탄약을 얻었어! 앞으로 두 시간 안에 처리해야 할 주문이 산더미지. 레즐락이 이 물자를 얻기 위해 하피들과 싸웠다고요? 돈을 잘 쓴 셈이군."}}
rows[60124]={title={{24,721468993},"악몽에 갇히다"},description={"Ishnuallah, $C.$B$BThere is trouble brewing in the Barrens. No, its not the Horde or the centaurs, this is about the Wailing Caverns.$B$BIt was an attempt to turn the Barrens into a lush green oasis but it backfired. Naralex tried to tap into the power of the Emerald Dream but the Nightmare got to him first, putting him in eternal sleep and corrupting every beast and even his acolytes!$B$BYou can find the Wailing Caverns in Northern Barrens.$B$BFind his Disciple in the caverns, he will tell you how you can free him.","이쉬누알라,$C$B$B .불모의 땅에 문제가 생겼습니다. 호드나 켄타우로스 때문이 아니라, 울부짖는 동굴 때문입니다.불모의 땅를 $B$B푸른 오아시스로 만들려는 시도가 있었지만, 오히려 역효과를 낳았습니다. 나랄렉스는 에메랄드 꿈의 힘을 이용하려 했지만, 악몽이 먼저 그를 덮쳐 영원한 잠에 빠뜨리고 모든 짐승과 심지어 그의 추종자들까지 타락시켰습니다!울부짖는 $B$B동굴은 북부 불모의 땅에 있습니다.동굴에서 그의 $B$B제자를 찾으세요. 그가 나랄렉스를 해방시키는 방법을 알려줄 겁니다."},objectives={{212,196322894},"알란다리안 나이트송은 당신이 북부 불모의 땅의 울부짖는 동굴로 들어가 악몽에 갇힌 나랄렉스를 구출해 주기를 바랍니다. 동굴에서 그의 제자를 찾아 방법을 배우고, 나랄렉스를 구출한 후 그녀에게 돌아오세요."},progress={{66,214814012},"나랄렉스를 구할 수 있는 건 오직 당신과 당신의 친구들뿐입니다. 당신들이 우리의 유일한 희망이에요."},completion={{116,320671822},"당신이 도착하기 직전에 소식이 전해졌습니다. 정말 큰 은혜를 입었습니다.$B$B자, 당신 같은 영웅에게 어울리는 보상입니다."}}
rows[60125]={title={{12,138739412},"뱀꽃"},description={{356,948031127},"비록 당신의 주요 임무는 악몽으로부터 나랄렉스를 구하는 것이지만, 우리는 동굴을 오염시키는 타락에 대해 더 자세히 $B$B알아볼 수도 있습니다. 나랄렉스가 영원한 잠에 빠진 후 동굴 안에서 뱀꽃이라는 식물이 자라났고, 그 식물에는 뱀의 독이 있다고 들었습니다. $B$B저는 당신이 동굴로 들어가 이 식물 10개를 가져오기를 바랍니다."},objectives={{90,367702683},"오버딘에 있는 알란다리안 나이트송이 당신에게 뱀꽃 10개를 모으라는 임무를 맡겼습니다."},progress={{77,1979852018},"꽃을 모았나요? 그 꽃들이 악몽에 대한 단서를 줄지도 몰라요."},completion={{62,655337215},"찾으셨군요! 바로 달의 숲로 보내드리겠습니다."}}
rows[60130]={title={{19,1430343487},"그 더럽고 낡은 반지"},description={{461,511135089},"당신은 멀록의 손가락 사이사이에 닳아빠진 반지를 발견했습니다. 무언가가 당신을 끌어당기는 듯, 겉모습과는 달리 값진 가치를 지닌 듯, 당신은 그 반지를 주머니에 넣었습니다. 갑옷에 닦아보려 했지만, 먼지와 때만 더 번질 뿐이었습니다. $B$B당신은 이 반지가 겉으로 보이는 것 이상의 무언가, 마법을 품고 있다고 확신했습니다. 그래서 마법에 정통한 누군가에게 감정을 의뢰하기로 했습니다."},objectives={{74,1129989997},"황금골 지역에서 마법 전문가를 찾아 그 더러운 낡은 반지를 감정해 달라고 부탁해 보세요."},progress={{164,784958439},"왜 내게 이런 더러운 장신구를 보여주는 겁니까? 보세요, 지금 내 관심을 필요로 하는 어린 마법사들이 있어서 이런 데 신경 쓸 시간이 없어요… 오? 마법이라고요?"},completion={{385,1748494585},"흥미롭군... 누군가 이 반지에 저주를 걸었군. 아마도 도둑들이 가져가지 못하게 하려는 의도였겠지. 만약 멀록이 이 반지를 갖게 된다면, 저주는 본래 목적을 달성하지 못한 셈이 되겠군.$B$B<잘디마르가 손짓하며 주문을 외운다. 눈부신 섬광이 반지에서 폭발하며, 반지는 찬란한 금빛 띠처럼 보인다.>$B$B여기 있다."}}
rows[60131]={title={{13,598128803},"깊고 푸른 바다"},description={"Greetings, $C!$B$BMuch of Orgrimmar's food supply comes from the sea to the east. Grunts can assist with escorting the fishermen and crabbers through the scorpids and raptors but there's the issue of sharks that's getting the better of them.$B$BFishermen have reported aggressive sharks rising in number off the coast and attacking their boats. Go thin their number and be sure to take friends. Rid us of this menace before our food stores dwindle!","안녕하세요,$C$B$B !오그리마의 식량 대부분은 동쪽 바다에서 나옵니다. 그런트들은 어부와 게잡이들이 전갈과 맹금류를 피해 바다로 나갈 수 있도록 호위해 줄 수 있지만, 상어 문제가 심각합니다.어부들은 해안가에서$B$B 공격적인 상어의 수가 늘어나 배를 공격하고 있다고 보고했습니다. 가서 상어들을 소탕해 주십시오. 동료들과 함께 가십시오. 식량이 바닥나기 전에 이 위협을 없애주세요!"},objectives={{48,338500065},"듀로타르 동쪽 해안에서 모래상어를 처치하세요."},progress={"You smell of the sea, $c. Tell me the beast is slain so I can get the fisherman back to work.","$c, 너한테서 바다 냄새가 나. 그 괴물이 죽었다고 말해 줘. 그래야 어부를 다시 일터로 보낼 수 있잖아."},completion={"It's important to keep their numbers in check but not to hunt them to the brink. You've done a great service for the Horde this day, $c. Go with honor.","적의 수를 적절히 조절하는 것은 중요하지만, 그들을 벼랑 끝까지 몰아붙일 필요는 없습니다.$c님, 오늘 호드를 위해 큰 공을 세우셨습니다. 명예롭게 가시오."}}
rows[60132]={title={{19,1080794821},"저 사람들이 길을 막고 있어!"},description={"<Mu'uta stares into the distance, one hand rubbing a massive scar on his face and the other holding his bow at his side.>$B$BA spider, $C. A spider caused this wound. Not inflicted it, mind you, but caused it.$B$B<He lowers his hand and his one functioning eye fixes on you.>$B$BI was hunting raptors. I need their feathers, the butcher needs the meat, the claws can be used as weapons, they're good creatures. A worthy opponent. If you misstep, into a web in my case, they'll leave their mark.$B$B<He grimaces and points at his scarred face.>$B$BSpiders, on the other hand, are useless. Their web is too sticky to use for armor or fletching, their carapace too brittle to make decent armor. They're in the way, $C. Kill them.","무우타는 먼 곳을 응시하며 한 손으로는 얼굴의 커다란 흉터를 문지르고 다른 손으로는 활을 옆구리에 쥔 채 말했다. \"거미$B$B 때문이야,$C C. 이 상처는 거미가 낸 거라고. 낸 게 아니라, 낸 거라고.\" $B$B그는 손을 내리고 멀쩡한 한쪽 눈을 당신에게 고정시켰다. \"랩터 $B$B사냥을 하고 있었어. 깃털도 필요하고, 정육점 주인은 고기가 필요하고, 발톱은 무기로 쓸 수 있고, 좋은 생물이지. 만만치 않은 상대야. 네가 발을 헛디뎌 내 거미줄에 걸리면, 그 흔적을 남길 거야.\" 그는 얼굴을$B$B 찡그리며 흉터투성이 얼굴을 가리켰다. \"반면에$B$B 거미는 쓸모없어. 거미줄은 너무 끈적거려서 갑옷이나 화살촉으로 쓸 수 없고, 껍데기는 너무 약해서 제대로 된 갑옷을 만들 수 없어. 방해만 되는 존재라고, C.$C 죽여버려.\""},objectives={{44,296596289},"아라시 고원에서 평원 덩굴 괴물 20마리를 처치하세요."},progress={{23,2068972462},"다리가 여덟 개면 너무 많아."},completion={{60,582627365},"아제로스에는 거미가 적어지니 훨씬 더 나은 곳이 되었습니다."}}
rows[60133]={title={{22,1752833044},"병을 이겨내자"},description={{659,151127189},"내가 자네를 이곳 생명의 경이로운 근원을 발견하도록 보내는 이 순간에도, 이 땅은 악취로 물들어 있네. 온순한 가젤 무리가 병들고 있네. 우리는 병든 가젤을 치료하고 생명의 순환에 균형을 되찾으려 $B$B애쓰지만, 난관에 봉착했네. 썬더 블러프와 그곳의 형제들을 통해 문글레이드에 소식을 전했네. 세나리온 서클에서도 곧 도움을 줄 것이네. 자네가 기꺼이 돕고 싶다면, 기꺼이$B$B 자네를 이용하겠네! 가서 무리에서 뒤처진 불쌍한 가젤들을 추적하시오. 암사자들이 병든 가젤을 잡아먹기 전에 사냥해야 하네. 가젤들의 병이 무엇인지 연구할 수 있도록 샘플을 가지고 돌아오시오."},objectives={{66,657763420},"불모의 땅를 배회하는 병약한 가젤에게서 샘플 10개를 채취하세요."},progress={"It is with a heavy heart that I must send you to do this deed, $N.$B$BDo not delay, the herds only grow weaker.","$N,$B,$B, 무거운 마음으로 이 일을 당신에게 맡겨야 합니다. 지체하지 마십시오. 가축들은 점점 더 약해지고 있습니다."},completion={"Thank you, $N. The sacrifice of these poor animals will help me to unravel this mysterious taint seeping into the grassland and develop a cure for its effects.","$N님, 감사합니다. 이 불쌍한 동물들의 희생은 초원에 스며드는 이 불가사의한 오염의 원인을 밝히고 그 영향을 치료할 방법을 개발하는 데 도움이 될 것입니다."}}
rows[60134]={title={{17,1891443380},"독극물 예방"},description={"We've done it, $N! With the help of the druids, we have found a cure to the Dreadmist Poison affecting the Barrens. It will take time for the earth to heal from the poison's damaging effects, however. $b$bDruids are curing the remaining sickened beasts, but we can also act to protect the herds from the lingering poison until the land has recovered completely.$B$BTake this salve. Feed it to gazelles to strengthen them against the poisoned grasses.","우리가 해냈어,$N ! 드루이드들의 도움으로 불모의 땅를 오염시킨 공포안개 독의 치료법을 찾았어. 하지만 땅이 독의 파괴적인 영향에서 회복되려면 시간이 걸릴 거야. 드루이드들이 남은$b$b 병든 짐승들을 치료하고 있지만, 땅이 완전히 회복될 때까지 남아있는 독으로부터 가축 떼를 보호하기 위한 조치도 취해야 해.이 연고를 $B$B가져가. 가젤들에게 먹이면 독이 든 풀에 대한 저항력을 키울 수 있을 거야."},objectives={{62,817091870},"불모의 땅의 가젤 10마리를 백신 접종하여 위험으로부터 보호하십시오."},progress={{124,166323280},"다 된 건가요? 초식동물들만 이 독으로부터 보호된다면 지구 어머니 세상의 모든 생명체에게 닥칠 피해를 막을 수 있을 거예요."},completion={"I saw a small herd of gazelle pass by the Crossroads while you were gone. They traveled like the wind itself carried their hooves higher, and it gave me much joy to see them run freely. Thank you, $N, for your help.","당신이 없는 동안 작은 가젤 무리가 교차로를 지나가는 것을 보았습니다. 마치 바람이 그들의 발굽을 더 높이 들어 올리는 듯 자유롭게 달리는 모습을 보니 정말 기뻤습니다.$N님, 도와주셔서 감사합니다."}}
rows[60135]={title={{20,1116977836},"오래도록 남아있는 어머니"},description={{832,55729597},"이곳에서의 제 임무는 켄타우로스에 집중되어 있지만, 수호자로서 저는 세상이 고통받는 곳이라면 어디든 치유해야 할 $B$B의무가 있습니다. 이곳 남서쪽, 이 땅에는 고통에 몸부림치는 영혼이 있습니다. 살아생전에는 이름이 없었지만, 타우렌족은 그녀의 영혼을 팔케오테, 즉 그들의 언어로 \"회색 $B$B어머니\"라고 부릅니다. 팔케오테는 오래전, 세상이 갈라지기 전에 이 땅에서 아들을 잃었습니다. 하지만 그녀는 아들 곁을 떠나지 않았습니다. 나무가 자라고 세상이 변하는 동안, 그녀는 오랜 세월을 이곳에 머물렀고, 마침내 사랑하는 아들 곁에서 세상을 떠났습니다. 그녀는 여전히 $B$B이곳에 불안한 영혼으로 남아 있습니다. 오랜 세월을 살아오며 오직 한 가지 일에 헌신했던 그녀는 강인하지만, 이미 혈육에 대한 사랑의 온기는 떠나갔습니다. 영웅이시여, 그녀를 편히 쉬게 하려면 많은 동료가 필요하겠지만, 그것이 제가 당신에게 부탁하는 것입니다."},objectives={{39,1252589114},"팔케오테의 영혼을 찾아 물리치십시오."},progress={{31,408148201},"회색 엄마를 찾으셨나요?"},completion={"Well done, $R! At long last, Palkeote is at peace. You have done a great service today, and the beasts of this land know it in their own way.$B$BSuch an effort should be rewarded.","정말 잘했어요,$R! 마침내 팔케오테가 평화를 찾았군요. 오늘 당신은 정말 큰 공을 세웠고, 이 땅의 짐승들도 그들만의 방식으로 그것을 알고 있을 겁니다.$B$B이런 노력에는 마땅한 보상이 따르죠."}}
rows[60137]={title={{8,905209979},"팔케오테"},description={"Do you know the legend of Palkeote, the grey mother?$B$BShe is the spirit of an ancient kodo who walked this land in the distant past, in the days even before the sundering. This land was green then, and she roamed it for many years with her mate and her children.$B$BOne day, one of her sons fell ill with a sickness that would not leave him. He fell further behind the pack with each passing day, until he finally collapsed northwest of here, near a river that has now gone dry.$B$BPalkeote stayed with her son, but she could do nothing to stop his passing. She would not leave even then. Her herd moved on and the seasons passed around her, but still she remained, until she herself passed away beside him. Her watch did not end even then, and she remains as a mighty spirit.$B$BThe Earthmother pities the suffering of all life, and she pities the suffering of mothers most of all. Palkeote's vigil has made her strong, but it is time for her to rest. Muster your allies and end her long watch, $C.","회색 어미 팔케오테의 전설을 아시나요? 그녀는 $B$B아주 먼 옛날, 대분열 이전 시대에 이 땅을 걸었던 고대 코도의 영혼입니다. 그때 이 땅은 푸르렀고, 그녀는 짝과 자식들과 함께 수년 동안 이 땅을 누볐습니다. 어느 날, 그녀의 아들 중 하나가 $B$B낫지 않는 병에 걸렸습니다. 날이 갈수록 무리에서 점점 뒤처지더니, 마침내 이곳 북서쪽, 지금은 말라버린 강 근처에서 쓰러졌습니다. 팔케오테는 아들 곁을 지켰지만, 그의 죽음을 막을 수는 없었습니다.$B$B 그녀는 그 후에도 떠나지 않았습니다. 무리는 이동했고 계절은 그녀 주위를 스쳐 지나갔지만, 그녀는 여전히 그 자리에 남아 있다가 마침내 아들 곁에서 숨을 거두었습니다. 그녀의 보살핌은 거기서 끝나지 않았고, 그녀는 여전히 강인한 영혼으로 남아 있습니다. 대지의 어머니는 $B$B모든 생명의 고통을 가엾게 여기며, 특히 어미들의 고통을 가장 가엾게 여깁니다. 팔케오테는 아들을 지켜보며 강해졌지만, 이제는 쉴 때가 되었습니다. 동맹들을 규합하여 그녀의 기나긴 감시를 끝내십시오, $C."},objectives={{39,1252589114},"팔케오테의 영혼을 찾아 물리치십시오."},progress={{92,270802528},"팔케오테를 찾았습니까? 혼자서 그녀와 맞서지 마십시오. 희망 없는 사냥에는 명예가 없습니다."},completion={{151,1421282937},"<하르노르가 고개를 숙인다.>$B$B회색 어머니께서 마침내 평화를 찾으셨다니 기쁩니다.$B$B당신과 당신의 동맹들에게 저와 이 땅의 모든 코도족의 감사를 전합니다."}}
rows[60138]={title={{9,652098492},"코도 헌트"},description={"The kodo is the mightiest of the beasts of Mulgore, and therefore the greatest of its hunts. You are ready, young $C, to hunt them yourself.$B$BYou have probably already seen the kodo herds wandering Mulgore during your earlier travels. Find one of the herds, and challenge its matriarch and bull.$B$BKodos are not aggressive creatures, but they are fearsome when provoked – you will need all the skills you have learned to overcome their elders, $R.$B$BReturn to me when you have conquered them.","코도는 멀고어에서 가장 강력한 짐승이며, 따라서 가장 흥미진진한 사냥감이기도 합니다. 젊은 , 당신은 이제 $C직접 코도를 사냥할 준비가$B$B 되었습니다.아마도 이전 여행에서 멀고어를 배회하는 코도 무리를 이미 보았을 것입니다. 무리 중 하나를 찾아 암컷과 수컷 우두머리에게 도전하십시오.$B$B코도는 공격적인 동물은 아니지만, 자극을 받으면 무시무시해집니다. , 그들의 우두머리를 제압하려면 지금까지 배운 모든 기술이 필요할 $R것입니다.$B$B코도를 정복하면 저에게 돌아오십시오."},objectives={{79,88990219},"멀고르 평원에서 코도 무리를 찾아 암컷 코도와 수컷 코도를 물리치세요."},progress={{136,805186081},"코도는 멀고르 지역 곳곳을 돌아다닙니다. 무리를 찾으려면 시간이 좀 걸릴 수도 있습니다. 인내심은 코도 사냥에서 배워야 할 중요한 교훈 중 하나입니다."},completion={"You have overcome the greatest trial a Mulgore hunter can face, and you have emerged with greater strength – and wisdom – for your efforts.$B$BCarry it with you as you step further into the world, young $C, and honor the memory of the beasts you defeated by remembering their lessons.","멀고어 사냥꾼이 직면할 수 있는 가장 큰 시련을 극복한 당신은 그 노력으로 더욱 강인하고 지혜로운 존재가 되었습니다.$B$B젊은이여, 세상으로 나아갈 때 이 상을 간직하고, 물리친 짐승들의 교훈을 기억하며 그들의 기억을 기리십시오.$C"}}
rows[60139]={title={{12,543393941},"더 이상 짜증나지 마세요!"},description={{549,1789434941},"둠해머의 이름으로 맹세컨대, 왜 이 역병이 온 땅을 뒤덮은 겁니까? $B$B전갈 때문입니다! 전에는 이렇지 않았는데, 레이저 힐을 나설 때마다 전갈이 나타납니다! 텐트에도, 신발에도, 갑옷에도, 항상 전갈이 붙어 있어요! 위험한 존재라기보다는 성가신 존재에 가깝지만, 쏘일 때마다 회복 물약을 마시거나 마을로 돌아가 도움을 요청해야 합니다. 정말 지긋지긋해요!$B$B 지금도 방금 쏘인 상처를 치료하고 있지만, 자네는 사냥을 할 만한 자네 같군. 나가서 보이는 전갈을 모두 처치해 주네! 자네가 전갈을 찾는 데 어려움을 겪을 리는 없겠지만…"},objectives={{137,2139960832},"갑옷전갈 10마리를 처치하세요. 꼬리를 밟을 필요는 없지만, 밟으면 기분이 더 좋아질 수도 있습니다. 레이저 힐에 있는 옐나기 블랙암에게 돌아가세요."},progress={{62,2021702244},"다 끝났습니까? 그 해로운 위협을 찾기 위해 온 땅을 샅샅이 뒤지셨습니까?"},completion={"For the first time in weeks I think I can close my eyes and not hear their chittering. It's done.$B$B<Blackarm laughs aloud, exasperated>.$B$BYou will be counted among the great heroes of the Horde for this effort, $c, if I have anything to say about it. Have some of these healing potions for your trouble. With any luck, I won't need so many anymore.","몇 주 만에 처음으로 눈을 감아도 그들의 재잘거리는 소리가 들리지 않는 것 같군. 끝났어.$B$B<블랙암이 짜증스럽게 크게 웃는다>.$B$B내가 가만히 있지 않는다면, 자네는 이 공로로 호드의 위대한 영웅 반열에 오를 것이네.$c수고에 대한 보답으로 이 회복 물약을 좀 줘. 운이 좋으면 이제 이렇게 많이 필요하지 않을 테니까."}}
rows[60140]={title={{30,1604675622},"머리를 (일부라도) 잃지 마세요"},description={{433,834999899},"어떤 사람들은 정말 운이 없군!$B$B 오스틸은 여관 건너편에 있는 콜먼 파딩을 노려보며 $B$B말했다. \"오, 난 가족을 잃었어. 흑사병 때문에 집도 잃었고.\" 그는 끝도 없이 불평을 늘어놓았다! 알겠어! 흑사병이 우리 모두의 집과 가족을 앗아갔다고! 하지만 적어도 우리 중 일부는 턱뼈 하나라도 멀쩡하게 $B$B살아남았잖아! 오스틸은 부러진 뼈를 제자리에 $B$B맞춰 넣으며 말했다. 쓸모 있는 일을 하고 싶다면, 내 남은 부분을 붙들 수 있도록 붕대나 좀 가져다 줘!"},objectives={{170,970181120},"브릴에 있는 교수형 집행장 여관의 오스틸 드 몽에게 아마포 붕대 10개를 가져다 주세요. 붕대는 응급 처치 기술로 만들거나 해당 기술을 가진 사람에게서 구입할 수 있습니다."},progress={"Every minute that passes is another minute for pieces to fall off of me, $N!","시간이 흐를수록 내 몸에서 조각들이 하나씩 떨어져 나가는 거야,$N!"},completion={{333,1497563135},"<오스틸은 붕대를 가져와서 느슨한 팔다리를 제자리에 고정시키는 데 사용한다.>$B$B아, 고마워요. 이 정도면 괜찮겠네요.$B$B아까 짜증 냈다면 미안해요. 몸 일부가 언제라도 튀어나올 것 같으니 좀 예민해지기 쉽잖아요.$B$B하지만 지금은 훨씬 나아졌어요. 파딩 할아버지께 가서 얘기라도 해 볼까 봐요."}}
rows[60141]={title={{17,1942099661},"빛에 대한 의무"},description={{900,1328392529},"스톰윈드의 귀족들에게 성기사은 전장에서 용맹을 떨치고 정의로운 분노로 왕국의 적들을 응징하는 정예 병사로 인정받고 있습니다. 하지만 빛의 종복으로서$B$B 우리를 정의하는 것은 이러한 자질이 아닙니다. 약하고 가난한 이들에 대한 우리의 친절과 연민이야말로 백성들의 믿음을 얻는 이유입니다. 가장 $B$B단순한 친절조차도 성기사의 의무와 유산의 초석이며, 몽둥이를 든 어리석은 자와 우리를 구분 짓는 것입니다. 이스트베일$B$B 벌목 캠프에 있는 한 가족이 한 해 동안 먹을 식량을 비축하는 데 어려움을 겪고 있습니다. 저는 가능한 한 그들을 돕고자 하지만, 최근 왕국 전역에 위협이 고조되고 있어 골드샤이어에 대한 의무를 다해야 합니다. 부디 $B$B저 대신 그들을 도와주십시오. 남쪽 숲 가장자리 강둑 근처에서 발견되는 바위가죽 멧돼지를 사냥하여 고기를 이스트베일 벌목 캠프로 가져다주십시오."},objectives={{76,648229132},"이스트베일 벌목 캠프에 있는 엘드린에게 록하이드 멧돼지 고기 8조각을 가져다 주세요."},progress={{153,198586230},"스톰윈드에서 오셨나요?$B$B전에 말씀드렸듯이, 프레스토 부인께 드릴 돈이 한 푼도 남지 않았습니다! 제가 먹여 살려야 할 가족이 있다는 걸 모르시나요?"},completion={"<You explain why Brother WIlhelm sent you. Eldrin's angry, defensive posture softens as you explain, and eventually you see the shine of tears in his eyes.>$B$BMiles away and as busy serving the Light as he is, yet he still finds time to help us. It pains me to burden him so yet again. He's already done so much for us, you see.$B$BThings've been hard this year, so I've been goin' without so Sara and Eric don't have to, and... Well, thank you. Bless Brother Wilhelm, and bless you, $N.$B$BHere. I know it's not much, but Sara makes them for the locals. Maybe you can find some use in it. Take it! It's the least we can do in return for your selfless deed.","<빌헬름 형제님이 왜 당신을 보냈는지 설명하세요. 당신의 설명을 듣자 엘드린의 분노에 찬 방어적인 태도가 누그러지고, 마침내 그의 눈에 눈물이 글썽이는 것을 볼 수 있습니다.>$B$B멀리 떨어져 계시고 빛을 섬기느라 바쁘신데도 불구하고 저희를 도와주실 시간을 내주시다니요. 또다시 그분께 부담을 드리는 게 마음 아픕니다. 그분은 이미 저희를 위해 너무나 많은 일을 해주셨거든요.$B$B올해는 여러모로 힘든 일들이 많아서 사라와 에릭이 고생하지 않도록 제가 좀 부족하게 지내왔습니다. 그리고… 정말 감사합니다. 빌헬름 형제님과 당신께 축복이 있기를 바랍니다.$N$B$B자, 여기요. 큰 건 아니지만 사라가 마을 사람들을 위해 만드는 거예요. 혹시라도 쓸모가 있을지도 몰라요. 받으세요! 당신의 숭고한 행동에 대한 최소한의 보답입니다."}}
rows[60142]={title={{17,1557144397},"마음의 변화"},description={"Pardon me $c, might I ask a favor of you? I'm sure my association with Grimrizz and his dark rituals does little to put you at ease, but I assure you I'm no power-thirsty demon-dabbler! This doesn't suit me...$B$BTruth be told, I always wanted to be a blacksmith. No, not an engineer. Not all gnomes are engineers, you know! From the moment I laid eyes on the Great Forge, I've dreamed of working beside the great Tormus Deepforge.$B$BThe suffocating heat of the forge's flames, the shrill cry of hammers striking hot iron, the glint of a finely crafted blade. Yes, nothing would make me happier!$B$BIf you're headed to Ironforge, won't you please take this letter to Tormus Deepforge for me? It's an application to join the Blacksmith Guild in Ironforge. Tormus should be near the Great Forge.","실례합니다,$c 님. 부탁 하나 드려도 될까요? 제가 그림리즈와 그의 어둠의 의식들과 연관되어 있다는 사실이 당신을 불편하게 할 거라는 건 알지만, 저는 권력에 눈먼 악마 사냥꾼이 절대 아닙니다! 이건 $B$B제게 어울리지 않는데…사실은, 저는 항상 대장장이가 되고 싶었습니다. 아니, 엔지니어가 아니라요. 모든 노움이 엔지니어는 아니잖아요! 대대장간을 처음 본 순간부터, 저는 위대한 토르무스 심연 대장간에서 일하는 $B$B꿈을 꿔왔습니다. 숨 막힐 듯한 불꽃의 열기, 뜨거운 쇠를 내리치는 망치 소리, 정교하게 만들어진 칼날의 번쩍임. 네, 그 어떤 것도 저를 더 행복하게 할 수$B$B 없을 겁니다!혹시 아이언포지에 가시는 길이라면, 이 편지를 토르무스 심연 대장간으로 전해주시겠어요? 아이언포지 대장장이 길드 가입 신청서입니다. 토르무스는 대대장간 근처에 있을 겁니다."},objectives={{71,152915449},"토그의 편지를 아이언포지의 대형 대장간에 있는 토르무스 딥포지에게 가져다 주세요."},progress={{53,1758028130},"대장장이 망치질하는 법을 배우러 오셨나요, 친구?"},completion={"<Tormus takes the letter and reads it. He furrows his brows before giving a hearty laugh.>$B$BA gnome looking to be a blacksmith? It has been a long time since we had a gnome join our ranks. Well, why not? Perhaps he'll be the next Klockmort Spannerspan!$B$BI appreciate you bringing this to me, $c. Here, some extra stones to give your weapon an extra edge in battle.","<토르무스는 편지를 받아 읽고는 눈살을 찌푸리다가 크게 웃었다.>$B$B노움이 대장장이가 되려 한다니? 우리 부대에 노움이 들어온 건 정말 오랜만이군. 뭐, 안 될 것도 없지. 어쩌면 그가 다음 클록모트 스패너스팬이 될지도 모르지!$B$B이걸 가져다줘서 고맙군,$c. 자, 여기 네 무기에 전투력을 더해줄 돌 몇 개를 더 주겠다."}}
rows[60143]={title={{20,2093242176},"브래놀의 재봉 키트"},description={"Have you ever stood at the edge of Teldrassil and looked out over the Veiled Sea? It's a magnificent sight, $N. I cannot recommend enough that you experience it at least once.$B$BI often travel with my sewing kit to the waterfalls near Wellspring Lake, right as they pour over the side of the trunk. It is a wonderfully serene spot where I may work in peace. The last time I was there, however, I was attacked by maddened timberlings and fled without my kit!$B$BThose tools have been with me for as long as I can remember, and I can't bear the thought of them tumbling over into the sea, lost forever. Would you kindly recover my kit for me, $N?","텔드라실 절벽 끝에 서서 베일드 해를 바라보신 적 있나요? 정말 장엄한 광경이에요, . 꼭 한$N 번쯤은 경험해 보시길 강력 추천합니다. 저는 종종 바느질$B$B 도구를 가지고 웰스프링 호수 근처, 나무줄기 옆으로 쏟아지는 폭포로 갑니다. 그곳은 제가 평화롭게 작업할 수 있는 더없이 고요한 장소죠. 하지만 지난번에 그곳에 갔을 때는 미쳐 날뛰는 팀버링들에게 공격당해서 도구도 없이 도망쳐 나왔어요!그$B$B 도구들은 제가 기억하는 한 항상 저와 함께해 왔는데, 그것들이 바다에 빠져 영원히 잃어버렸다고 생각하니 너무 괴로워요. , 부디 제 도구를 찾아주시겠어요?$N"},objectives={{62,641916794},"브란놀의 바느질 도구를 되찾아 돌라나르에 있는 그에게 돌려주세요."},progress={"Have you found my sewing kit, $N?","제 재봉틀 세트$N을 찾으셨나요?"},completion={"Oh, you've found it! You have my eternal gratitude, $N!$B$BWill a well-tailored shirt suffice as compensation for your efforts? I keep a number of different colors in stock to suit any taste. Please, take your pick.$B$BIf a shirt is not to your liking, perhaps I could interest you in some raw material for your own purposes?","오, 찾으셨군요!$N님, 정말 감사드립니다!$B$B수고에 대한 보상으로 잘 재단된 셔츠 한 벌은 어떠시겠어요? 다양한 색상의 셔츠를 구비해 두었으니 취향에 맞는 것을 골라보세요.$B$B셔츠가 마음에 들지 않으신다면, 혹시 직접 사용하실 수 있도록 원단을 몇 가지 구매하실 생각은 없으신가요?"}}
rows[60145]={title={{17,6593240},"산등성이 아래쪽"},description={"Hold, $N. I've one more piece of intel for you if you're heading into the Echo Ridge Mine. One of my scouts spoke of a kobold much larger than the rest hiding deep within the heart of the mine.$B$BIts size suggests it may be coordinating the other kobolds, which makes its mere existence a great threat to Northshire. Slay it, and we may very well deal a decisive blow to the kobold infestation.$B$BI want you to go down into the Echo Ridge Mine and kill the foul creature. Your efforts will be rewarded appropriately.","잠깐만요,$N . 에코 리지 광산으로 향하신다면 알려드릴 정보가 하나 더 있습니다. 제 정찰병 중 한 명이 광산 깊숙한 곳에 다른 코볼드들보다 훨씬 큰 코볼드가 숨어 있다고 했습니다. 그 $B$B크기로 보아 다른 코볼드들을 지휘하고 있을 가능성이 높으며, 따라서 그 존재 자체가 노스샤이어에 큰 위협이 됩니다. 그 코볼드를 처치한다면 코볼드 소굴에 결정적인 타격을 줄 수 있을 겁니다. $B$B당신이 에코 리지 광산으로 내려가서 그 흉악한 생물을 처치해 주길 바랍니다. 당신의 노고에 합당한 보상을 드리겠습니다."},objectives={{75,1345756795},"스너플스나우트를 처치한 후 노스셔 수도원에 있는 맥브라이드 보안관에게 보고하십시오."},progress={{30,580095245},"당신이 그 짐승을 죽였다고 생각해도 되겠네요?"},completion={{144,223188857},"당신의 여정은 이제 막 시작되었지만, 이미 노스샤이어에 없어서는 안 될 소중한 존재임을 증명해냈습니다.$B$B보상을 선택하세요. 당신은 그럴 자격이 있습니다."}}
rows[60147]={title={{24,705700817},"펠스토커를 추적하다"},description={{180,791729733},"당신은 마녀 집단 밖에서 사악한 소환수들과 싸웠지만, 계곡의 오염은 더욱 깊숙이 스며들어 있습니다. $B$B당신은 마녀 집단 안으로 들어가 펠스토커들을 처치해야 합니다. 돌아오면 보상을 받을 것입니다."},objectives={{64,1965292904},"펠스토커 10마리를 처치하세요. 은신처 밖에 있는 주레타 파르가제에게 돌아가세요."},progress={{25,517617190},"뭘 기다리고 있는 거야?"},completion={{92,1801090513},"당신은 적의 수적에 큰 타격을 입히고 무사히 돌아왔습니다.$B$B하나 가져가세요, 당신은 그럴 자격이 있습니다."}}
rows[60148]={title={{20,215956857},"공허의 어머니"},description={{237,2103835694},"우리는 계속해서 거미를 죽였지만 다음 날이 되어도 그 수가 변하지 않았습니다. 뭔가 이상한 것 같습니다. $B$B아래층으로 내려가서 조사해 보세요. 무사히 돌아오면 보상을 받을 겁니다. 어미$B$B 거미가 알을 낳고 있는 것 같습니다."},objectives={{88,1621137904},"집행자 아렌은 당신에게 나이트 웹 할로우를 조사하고 그곳의 어미를 처치하라고 명령합니다."},progress={{42,593229470},"그들이 계속 돌아오는 걸 보니 뭔가 이상해."},completion={{102,2003624432},"훌륭해!$B$B이제 어미를 제거했으니 우리는 마침내 광산을 완전히 청소할 수 있겠군."}}
rows[60150]={title={{22,1414713567},"브리슬백의 공격성"},description={{225,251640810},"최근 가시덤불 계곡에서 가시멧돼지의 활동이 증가하고 있습니다. 나라체 야영지를 공격하려는 것으로 의심됩니다. 계곡으로 가서 $B$B그들의 수를 줄여라. 그들은 비겁하게 싸우고 명예도 받을 자격이 없다."},objectives={{99,840149863},"나라체 캠프의 그룰 호크윈드는 당신에게 브리스틀백 퀼보어 6마리와 브리스틀백 샤먼 4마리를 처치해달라고 부탁합니다."},progress={{45,944305593},"우리가 함부로 간섭받을 존재가 아니라는 것을 그들에게 보여주자."},completion={{96,1622100968},"당신 같은 영웅들이 있다면 멀고어에서 그들을 몰아낼 수도 있을 겁니다.$B$B하나만 가져가세요. 그 정도는 해줄 수 있잖아요."}}
rows[60152]={title={{30,2139411639},"사람들은 그를 폭풍 모건이라 부른다."},description={"$N, I hear you are on your way to slay the scoundrels they call leaders of the worst crew of pirates, the Bloodsail Buccaneers.$B$BYou see these fools took a new member and they in their deluded mind think he will aid them greatly.$B$B<Baron Revilgaz scoffs.>$B$BI have a man on the inside, his name is Morgan Storm, look for a fellow that won't shank you on sight.","$NN, 자네가 악명 높은 해적단 '블러드세일 버커니어스'의 우두머리들을 처단하러 가는 길이라고 들었네. 이 얼간이들이 새 $B$B조직원을 영입했는데, 망상에 빠져서 그놈이 자기들에게 큰 도움이 될 거라고 생각하는군. <레빌가즈 $B$B남작이 코웃음을 쳤다.> $B$B내 안에 정보원이 한 명 있는데, 이름은 모건 스톰이야. 널 보자마자 칼로 찌르지 않을 놈을 찾아봐."},objectives={{21,525193567},"폭풍 모건을 찾아라"},progress={{54,1866929214},"이 얼간이들을 없애버려라. 내 부하들은 누구보다 뛰어나다."},completion={{130,993251615},"남작께서 당신을 보내셨다고요? 정말 친절하시군요. 이리 와서 들어보세요, 친구. 내 말 좀 들어봐. 차마 입 밖으로 꺼낼 수가 없거든!"}}
rows[60153]={title={{14,1174693240},"아이언 패치"},description={{506,1286646740},"나는 이중 스파이로서 그들이 그 오크를 배에 태울 때 그들의 배에 함께 있었어. 전투 기술이 전혀 없는 걸 보니 그다지 좋은 생각은 아니었지. 하지만 그는 완벽한 해적이야. 거짓말쟁이에 도박꾼, 술꾼, 뭐든지 다 하지.$B$B 그들은 그를 소규모 함대의 선장으로 임명하고 그의 전투 경험이 신병들에게 전수되기를 바라는데, 완전 헛소리야. (이안은$B$B 땅에 침을 뱉는다.) 배$B$B 중 하나에서 그를 찾아서 죽이고 그의 머리를 남작에게 가져다 줘. 나는 몸을 숨길 테니, 아무도 우리를 보기 전에 가!"},objectives={{52,176334164},"아이언패치를 처치하고 그의 머리를 레빌가즈 남작에게 가져가십시오."},progress={{35,2046837155},"어서 치워! 안 그러면 우리 둘 다 목숨을 잃을 거야!"},completion={"Good work, $N, I'll feed this to the crocodiles.$B$B<The Baron tosses the head into a bucket.>$B$BWhat's this?$B$BHe still has an eyepatch on, you can have it if you want, or I will give you this pearled necklace, you can only take one.$B$BThank you for your services, do stick around, you never know when I'll need more muscle.","잘했어,$N. 이건 악어들에게 먹이로 주겠다.$B$B<남작은 머리를 양동이에 던져 넣는다.>$B$B이건 뭐지?$B$B아직 안대를 하고 있군. 원하면 가져가도 좋고, 아니면 이 진주 목걸이를 줄게. 하나만 가져갈 수 있어.$B$B수고했어. 계속 여기 있어 줘. 언제 힘이 더 필요할지 모르니까."}}
rows[60154]={title={{22,441865093},"재스퍼로드 침입"},description={{541,511703608},"자스퍼로드 광산 정찰에서 돌아온 직후, 황혼의 숲에서 거미 떼가 광산 깊숙한 곳으로 이동하고 있다는 보고를 받았습니다. 더 심각한 것은, 그 거미들이 광산 안의 코볼드들을 잡아먹어 개체 수를 늘리고 있다는 것입니다. 코볼드, $B$B데피아, 그리고 이제는 거미까지? 더 이상 병력을 분산시켜 또 다른 위협에 대처할 여유가 없습니다. 자스퍼로드 광산으로 돌아가 엘윈 숲 전체로 번지기 전에 거미떼를 소탕하십시오!"},objectives={{106,304959051},"황금골 북동쪽에 있는 재스퍼로드 광산에서 광산 거미 8마리를 처치한 다음, 황금골에 있는 마셜 더건에게 돌아가십시오."},progress={{88,1593996639},"당신이 시간을 허비하는 매 순간 그들의 수는 늘어나고 있습니다. 더 이상 기다릴 여유가 없습니다."},completion={{124,1817694683},"이제 더 이상 거미들이 엘윈 숲을 위협하지 않게 되어 정말 다행입니다. 스톰윈드를 대표하여 이 동전을 받아주십시오."}}
rows[60155]={title={{19,282152585},"남태평양의 진미"},description={{410,1580523392},"게 다리는 정말 맛있죠! 어떤 음식과도 잘 어울려요! 언더마인 클로 차우더, 골드쏜 티, 심지어 다른 게 다리에도요! 혹시 게를 잡아서 제가 필요한 게 다리를 구해다 주실 수 있을까요? 무법항 $B$B바로 남쪽에 있는 와일드 쇼어에서 찾을 수 있어요. 하지만 조심하세요. 블러드세일 해적들이 그 해안을 침략했다는 소문이 들리더라고요. 제 공급책이 더 이상 오지 않는 이유가 그거였나 봐요."},objectives={{70,1977415854},"무법항에 있는 여관 주인 스킨들에게 남부 모래게 다리 10개를 가져다 주세요."},progress={{40,2121178557},"어서 서두르세요! 손님들이 기다리고 계세요!"},completion={{111,532885805},"오, 멋진 다리네요! 구워도 좋고, 삶아도 좋고, 냄비에 넣어도 좋아요.$B$B보상이라도 원하세요? 이 정도면 충분할 것 같은데요."}}
rows[60160]={title={{16,967004350},"야수를 길들이기"},description={{454,119965809},"이봐, 친구! 꽤 잘하고 있군. 마을에서 화제의 인물이 된 것 같아. 이제 다음 단계로 나아갈 준비가 된 것 같아. 자, 네 애완동물을 $B$B길들이는 법을 알려줄게. 다른 생물을 지배하는 건 쉬운 일이 아니야. 여러 번 시도해야 할지도 몰라. 그러니$B$B 낙심하지 마. 동쪽에 있는 검은독전갈을 한번 잡아봐. 꽤 어려울 거야."},objectives={{96,2033274187},"길들이기 지팡이를 사용하여 검은독전갈을 길들인 다음, 러스트게이트 능선에 있는 메이튼 붐라이플에게 돌아가십시오."},progress={{74,818513001},"집중력을 유지해야 합니다. 그렇지 않으면 동물이 당신의 뜻대로 움직이지 않을 것입니다."},completion={{148,1905302561},"이 꼬맹이는 당신과 함께 있는 게 그다지 즐거워 보이지 않네요. 뭐, 그럴 만도 하죠. 그래도 잘했어요! 다음 단계로 넘어가죠."}}
rows[60161]={title={{16,967004350},"야수를 길들이기"},description={{437,1995748905},"좋아, 좋아. 하지만 단순히 짐승 한 마리를 길들이는 것만으로는 주인과 하인의 개념을 이해하기에 충분하지 않아. 네 애완동물은 네 야망을 위한 도구 그 이상이 될 수 있어. 넌 곧 네가 인정하고 싶지 않을 만큼 애완동물에게 정이 많이 든다는 걸 깨닫게$B$B 될 거야. 북동쪽 멀리에는 머크리프 크롤러가 있어. 수생 짐승을 길들이는 건 육상 동물을 길들이는 것과는 달라. 이 게들을 길들여 보고, 멋진 갑각류 친구를 얻어 돌아와 봐."},objectives={{94,1699693706},"길들이기 막대를 사용하여 머크리프 크롤러를 길들인 다음, 러스트게이트 능선에 있는 메이튼 붐라이플에게 돌아가십시오."},progress={{73,1346899414},"집게발에 물리면 꽤 아플 수 있지만, 그것 때문에 집중력을 잃지 마세요."},completion={{132,1456418946},"결연한 표정이시네요. 마음에 들어요. 저도 새 소총을 시험해 볼 때면 그런 표정을 짓곤 하죠. 생각만 해도 가슴이 두근거려요!"}}
rows[60162]={title={{16,967004350},"야수를 길들이기"},description={{452,1699458278},"자, 이제 마지막입니다. 개인적으로 저는 날아다니는 동물을 길들이는 게 제일 어렵습니다. 너무 재빠르거든요. 하지만 당신은 저보다 더 능숙할지도 모르죠. 제 경험상 한 가지 말씀드리자면, 가장 잡기 힘든 짐승일수록 최고의 동료가 됩니다. 여기 $B$B북쪽, 물웅덩이 근처 동쪽에 애쉬페더 스우퍼가 있습니다. 한 마리 길들여서 저에게 돌아오세요. 이게 마지막 과제입니다. 최선을 다해 보세요!"},objectives={{96,1477903350},"길들이기 막대를 사용하여 애쉬페더 스우퍼를 길들인 다음, 러스트게이트 능선에 있는 메이튼 붐라이플에게 돌아가십시오."},progress={{75,742057595},"난 네가 해낼 거라고 확신해. 여기까지 오게 해준 네 능력을 믿어, 친구."},completion={{233,213038679},"잘했어, 친구. 야생 짐승 길들이기에 대해 내가 너에게 가르쳐줄 수 있는 건 이게 전부야. 이 지식을 활용하면 아제로스에서 만나는 대부분의 동물을 부르고, 해제하고, 길들일 수 있을 거야. 자랑스럽게 생각해. 나한테서 이걸 배우는 사람은 극소수에 불과하거든."}}
rows[60163]={title={{18,534037912},"야수를 훈련시키다"},description={{477,724299160},"아쉽게도 제가 아는 건 여기까지입니다. 이런 짐승들을 훈련시키는 건 제 전문 분야가 아니거든요. 하지만 누가 가르쳐줄 수 있는지는 알고 있습니다. 오그리마 명예의 계곡에 있는 오르막 그림샷이 훨씬 더 적임자입니다. 가직의 작업장에서 스파크워터 항구까지 말을 타고 갈 수 있고, 거기서 수도까지는 조금만 걸어가면 됩니다. 듣기로는 오르막은 용사의 전당 근처에서 주로 시간을 보낸다고 하더군요. $B$B행운을 빕니다, 친구! 당신과 당신의 멋진 '붐' 소리가 정말 그리울 겁니다."},objectives={{39,1862177294},"오그리마에 있는 오르막 그림샷과 대화하세요."},completion={{428,75983342},"오호, 젊은 고블린이로군. 요즘 들어 너희 종족을 더 자주 보게 되는군. 듀로타르 노동조합은 호드의 소중한 자산이지.$B$B애완동물을 훈련시키는 법을 배우고 싶나? 좋아, 내 가르침을 받으면 애완동물에게 새로운 기술을 가르치고, 먹이를 주고, 전투에서 쓰러졌을 때 되살릴 수 있게 될 거야.$B$B더 배우고 싶다면, 너와 네 애완동물이 여정을 통해 더 많은 경험을 쌓은 후에 다시 찾아오너라."}}
rows[70000]={title={{25,917454016},"특별한 종류의 소환"},description={"The Mage District is always so quiet, isn't it $N? Well if you are to ignore that heavily insistent calling to visit the Blue Recluse of course. You have grown into a very capable mage, many whisper your name and some have spread rumors about you.$B$BAnd so it reached a very unlikely fellow, one I would tell you not to approach but after all it is your call to make.$B$BSitting atop his tower in Azshara, there's an Archmage that has heard of your growth and name and wishes to meet you personally. Xylem is known to take in apprentices if they are found worthy enough of his teachings, maybe this has something to do with it.$B$BI advise you to be careful, the man is very dangerous. To reach his tower you must find his apprentice, Sanath Lim-yo, he's known to be a very joyful and pleasant elf.","마법사 지구는 언제나처럼 조용하죠, ? 물론,$N 푸른 은둔자를 찾아가라는 강렬한 부름을 무시한다면 말이죠. 당신은 아주 유능한 마법사로 성장했고, 많은 이들이 당신의 이름을 속삭이며 소문을 퍼뜨리고 있습니다.그리고 그 소문은 아주 뜻밖의$B$B 인물에게까지 전해졌는데, 제가 감히 접근하지 말라고 말씀드리고 싶지만, 결국 결정은 당신이 해야 할 일입니다.$B$B아즈샤라의 탑 꼭대기에 앉아 있는 대마법사가 당신의 성장과 이름에 대한 소문을 듣고 당신을 직접 만나고 싶어 합니다. 자일렘은 자신의 가르침을 받을 만한 자격이 있는 제자들을 받아들이는 것으로 유명한데, 아마도 이것과 관련이 있을지도 모릅니다.$B$B조심하세요, 그는 매우 위험한 인물입니다. 그의 탑에 가려면 그의 제자인 사나스 림요를 찾아야 합니다. 그는 매우 명랑하고 유쾌한 엘프로 알려져 있습니다."},objectives={{32,1997398028},"아즈샤라에 있는 대마법사 자일렘을 찾아가세요."},completion={{134,483802545},"드디어 도착하셨군요. 당신에 대해 많은 이야기를 들었는데, 그중 절반이라도 사실이라면 당신을 지켜보는 건 정말 흥미로울 것 같습니다."}}
rows[70001]={title={{17,1303644351},"모래 속에 길을 잃다"},description={"You are the first I have personally summoned in years, $N, my expectations are quite big. You've probably figured it out by now, I would like you to become my apprentice. But you must prove yourself worthy of my knowledge.$B$BGather your friends and your enemies and venture into the sands! In the Ruined Temple of Ahn'Qiraj a creature that devours magic may be found, its name is Moam, slay it and carve out the piece of obsidian on its forehead.$B$BSucceed and I will help you break out from your shell.",", 자네는 내가 수년 만에 직접 소환한 첫 번째 $N존재로, 내 기대는 상당히 크네. 아마 이미 짐작했겠지만, 자네가 내 제자가 되기를 바라네. 하지만 자네는 내 지식을 전수받을 자격이 있음을 $B$B증명해야 하네.친구와 적을 모두 모아 사막으로 나아가라! 안퀴라즈의 폐허가 된 사원에는 마법을 삼켜버리는 괴물, 모암이 있다. 그 괴물을 처치하고 이마에 있는 흑요석 조각을 캐내라.성공한다면, 내가$B$B 자네가 껍질을 깨고 나올 수 있도록 도와주겠네."},objectives={{49,989997534},"완벽한 흑요석 조각을 대마법사 자일렘에게 가져다 주세요."},progress={{69,2048419537},"저는 어디에도 가지 않을 예정이지만, 제 인내심은 시험받을 만큼 강하지 않습니다."},completion={"Well done, $N, truly well done.\013\010You have earned your place as my apprentice, for your first lesson you must read this tome. The survival of your group depends on you to be able to hand out as many refreshments as you can.$B$BRemember, you must not take anything lightly! Thirst may be your worst enemy under some circumstances.$B$BNow go study my newest apprentice.","정말 잘했어,$N, 정말 훌륭해.\013\010넌 내 제자로서의 자격을 얻었어. 첫 수업은 이 책을 읽는 거야. 너희 그룹의 생존은 네가 최대한 많은 간식을 나눠주는 능력에 달려 있어.$B$B명심해, 어떤 것도 가볍게 여겨서는 안 돼! 어떤 상황에서는 갈증이 너의 가장 큰 적이 될 수도 있어.$B$B자, 이제 가서 내 새 제자를 관찰해."}}
rows[70002]={title={{25,649871614},"미치광이의 안내"},description={"We have kept a close eye on your growth $N.$BYou have outwitted several demons under your command, conquered many foes, and kept a lot of allies at your side. There is very little any of us may teach you at the moment, you have gone above and beyond any of our expectations.$B$BHowever, there is someone that may yet have something to teach you about the ways of the warlock.$BVenture to the Blasted Lands and seek the one called Daio, there is a slight chance you might've already met.","우리는 자네의 성장을 면밀히 지켜봐$N$B 왔네, 자네는 휘하의 악마들을 여러 차례 속여넘기고, 수많은 적들을 물리쳤으며, 많은 동맹을 얻었네. 지금 당장 우리가 자네에게 가르칠 것은 거의 없네. 자네는 우리의 모든 기대를 뛰어넘었지. $B$B하지만, 자네에게 흑마법사의 길에 대해 가르쳐 줄 만한 자가 아직 한 명 있네. $B황폐한 땅으로 가서 다이오라는 자를 찾아 보시오. 어쩌면 자네가 이미 그를 만났을지도 모르네."},objectives={{55,589387233},"오염된 흉터로 가서 쇠락한 다이오를 찾아라."},completion={"Welcome $C, I assume you are here to learn about the secrets of the Twisting Nether and how you may claim them as your own.$B$BI may have something to teach you, but it won't be easy in the slightest.","$C님, 환영합니다. 당신은 뒤틀린 황천의 비밀과 그것을 손에 넣는 방법에 대해 배우고 싶어 이곳에 오신 것 같군요.$B$B님, 제가 가르쳐 드릴 것이 있지만, 결코 쉽지는 않을 겁니다."}}
rows[70003]={title={{23,81603728},"유층 배수"},description={{563,2115428474},"당신의 임무는 쉽지 않겠지만, 그 보상은 그만한 가치가 있을 겁니다. $B$B가시덤불 골짜기 계곡의 정글 트롤들이 그들의 신, 영혼 파괴자 하카르를 부활시키려 하고 있습니다. 누군가 이미 당신에게 그들을 막아달라고 의뢰했겠죠. 제가 부탁할 $B$B것은 조금 다릅니다. 그의 정수를 가져오세요. 직접 보면 무슨 말인지 알게 될 겁니다. 제가 가르쳐줄 것을 위해서는 이 정수가 필요할 겁니다. 당신과 당신의 동료들에게 아주 유용하게 쓰일 테니, 알아두세요. 자, 이제$B$B 가서 동료들을 모으고, 악마들을 소환해서 그 늙고 한심한 신을 물리치세요."},objectives={{80,260878225},"영혼 파괴자 하카르를 처치하고 우물의 정수를 쇠약해진 다이오에게 가져다주세요."},progress={{85,862611110},"만약 당신이 다시 돌아온다면, 당신은 앞으로 수년 동안 이 위업을 기억하게 될 것입니다."},completion={"<Daio laughs maniacally>$B$BYou actually pulled that one off, who would've thought. You're insane $N, maybe even more than this old fool.$B$BNow get ready it's time for a lesson not many are worthy of.","<다이오가 미친 듯이 웃는다>$B$B네가 그걸 진짜 해냈다고? 누가 생각이나 했겠어. 넌 미쳤어.$N어쩌면 이 늙은이보다도 더 미쳤을지도 몰라.$B$B자, 준비해. 웬만한 사람은 받을 자격이 없는 특별한 교훈을 줄 시간이야."}}
rows[70010]={title={{9,601716015},"듀얼 스펙"},description={{40,1219913873},"500g에 한해 무료 특수화 스위치 증정"}}
rows[70020]={title={{24,323105978},"형제의 걱정스러운 마음"},description={{516,1972975223},"제 남동생 타우포는 재능 있는 드루이드이고 제가 감히 넘볼 수 없을 만큼 훌륭하지만, 그래도 여전히 제 남동생입니다. 그는 $B$B악마의 타락을 막는 일 등을 위해 전쟁노래 벌목 캠프로 가는 길이었습니다. 펠파이어 언덕을 지나가야 하는데, 혹시라도 위험에 처할까 봐 걱정됩니다. 제발, 제 $B$B남동생을 찾아주세요. 제가 직접 찾아 나설 수도 있지만, 그가 제가 무능하다고 생각하는 걸 원치 않습니다. 그래도 걱정은 됩니다. 그는 얼마 전에 동쪽으로 난 큰길, 벌목 캠프로 가는 길을 따라 떠났습니다."},objectives={{75,1788825649},"펠파이어 언덕 초입에서 로룩의 형제인 타우포 포레스트스트라이더를 찾으세요."},progress={{4,273767400},"예?"},completion={{83,1423200493},"로룩이 당신을 보내서 제 안부를 확인하라고 했습니까? 아직도 제가 뿔 없는 어린 송아지라고 생각하는 겁니까?"}}
rows[70021]={title={{12,1164926071},"타우포의 의무"},description={"It was Earthmother's blessing to be born with such a worried elder brother, and as fate has it there you are, just the help that I needed.$B$BWhile I was making my way to the Lumber Camp I saw this Tauren bravely fight those demons and I have stopped to tend to his wounds. My skills helped stop his bleeding, but we need a salve to fully mend him.$B$BIn the river you will find Boglings, slay them and bring me the cores, they will help bring our newest friend back on his feet, and do not worry $N, this is all in the name of balance.","걱정 많은 형을 둔 건 대지의 어머니의 축복이었고, 운명처럼 당신이 바로 제가 필요로 했던 사람이군요. 제가 벌목장으로 $B$B가는 길에 이 타우렌이 용감하게 악마들과 싸우는 걸 보고 그의 상처를 치료해 주려고 멈춰 섰습니다. 제 기술로 출혈은 멈췄지만, 완전히 치료하려면 연고가 필요합니다. 강가에 보글링이 $B$B있으니, 그들을 처치하고 핵을 가져오세요. 그 핵이 우리 새 친구를 회복하는 데 도움이 될 겁니다. 그리고 걱정하지 마세요, . $N이 모든 건 균형을 위한 겁니다."},objectives={{36,1373565184},"타우포 늪지 생물 핵 10개를 가져오세요."},progress={{4,273767400},"예?"},completion={"Thank you $N, this will mend our friend.","$N님, 감사합니다. 이 덕분에 우리 친구가 고쳐질 거예요."}}
rows[70022]={title={{19,787219671},"창의 노르보크"},description={{430,1332927220},"워송 벌목 캠프로 가는 길에 악마들과 마주쳤는데, 이 드루이드가 아니었으면 무사히 도착하지 못했을 겁니다. 저는 현 $B$B사령관인 그루샤크 사령관께 드릴 아주 중요한 보고서가 있습니다. 당장이라도 달려가고 싶지만, 상처가 아직 아물지 않았고, 창도 전투 중에 잃어버렸습니다. 타우포가 저를 치료하는 동안$B$B 창을 찾아주시길 부탁드립니다. 찾는 동안 어떤 악마도 용서하지 마십시오."},objectives={{43,29619337},"불타는 지옥불정령 10마리와 지옥수호병 10마리를 처치하세요."},progress={{4,273767400},"예?"},completion={"My horns are ready and sharpened, alas my spear was stolen by those demons, the vermin felt the blessings of the Earthmother on it!$B$BIt's not your fault $N, you've bravely fought them and for that I am in your debt, here, have this necklace as a token of my gratitude.","내 뿔은 날카롭게 갈려 있지만, 아아, 내 창은 저 악마들에게 도둑맞았군. 그 벌레 같은 놈들이 대지의 여신의 축복을 느꼈나 보군!$B$B네 잘못이 아니야$N네가 용감하게 싸워준 덕분에 내가 은혜를 갚을 수 있어. 감사의 표시로 이 목걸이를 주겠다."}}
rows[70023]={title={{27,1339989742},"그루샤크 사령관에게 보고하십시오."},description={"I am aware I am not going anywhere anytime soon $N, there is no need for you to stare at me that way.$B$BYou will have to give my report to Commander Grushak, tell him I sent you, he will be glad to have you by his side, he's a bit strict but that's what will keep you alive out there. Seek him in the first tower as you reach the Lumber Camp.$B$BAs a personal request however, do keep an eye out for my spear, it carries years worth of history, been passed through my lineage from the first Hawkspear to the last and I do not wish it to be lost at the hands of demons.$B$BTravel safe my friend and may the Earthmother guide you.",", 내가 당분간 어디 가지 않을 거라는 건 $N알고 있어. 그렇게 빤히 쳐다볼 필요는 없어.$B$B그루샤크 사령관에게 내 보고서를 전해 줘야 해. 내가 보냈다고 말해. 자네가 곁에 있으면 기뻐할 거야. 좀 엄격하긴 하지만, 그게 자네가 살아남는 데 도움이 될 거야. 벌목 캠프에 도착하면 첫 번째 탑에서 그를 $B$B찾아.개인적으로 부탁인데, 내 창을 잘 살펴봐 줘. 오랜 세월의 역사가 담겨 있고, 최초의 매의 창부터 마지막까지 우리 가문을 통해 전해 내려온 거라 악마의 손에 넘어가는 걸 원치 않아.친구, $B$B부디 안전하게 가렴. 대지의 여신이 자네를 인도하길."},objectives={{47,877793582},"벌목 캠프에 있는 그루샤크 사령관에게 보고하십시오."},progress={{4,273767400},"예?"},completion={"I was expecting someone else to give me this report, $R, what happened to Norvok?","저는 다른 사람이 이 보고서$R을 저에게 줄 거라고 예상했었는데, 노르보크에게 무슨 일이 있었던 거죠?"}}
rows[70024]={title={{16,1515506824},"산사나무의 위협"},description={"The camp is as productive as the day it was built from the ground, which frankly doesn't mean much at all.$B$BThe Wildthorn Lurkers have ascended upon our camp and are giving the peons  and laborers a hard time, while my scouts are giving their all to slay them it is not enough.$B$BGo help the cause, $N, after all I take you bringing this report as volunteering your aid, clean the camp of the wildthorn menace and I will see you rewarded.","캠프는 처음 지어졌을 때처럼 여전히 활기가 넘치지만, 솔직히 말해서 별 의미는 없어. 가시덤불$B$B 괴물들이 우리 캠프에 쳐들어와서 하인들과 노동자들을 괴롭히고 있거든. 우리 정찰병들이 온 힘을 다해 녀석들을 처치하려 하지만 역부족이야. 가서 도와줘,$B$B N. 어쨌든 $N네가 이 보고서를 가져온 걸 보면 자원해서 도와주겠다는 뜻으로 받아들이겠어. 가시덤불 괴물들을 소탕해 주면 보상해 주겠어."},objectives={{49,1394819135},"워송 벌목 캠프에서 와일드쏜 러커 10마리를 처치하세요."},progress={{67,138480729},"캠프에서 야생 가시덤불을 제거하면 보상을 주겠다."},completion={{13,577946303},"이미 완료하셨나요?"}}
rows[70025]={title={{20,2120185468},"칼귀 스토커"},description={{273,1625708677},"저 칼날 귀를 가진 놈들이 우리를 숲에서 쫓아내려고 하고 있어! 걔네들이 은신한 무리를 보내 우리 밭 주변에 숨어서 우리 농부들을 죽이고 있어! 반드시 막아야$B$B 해! 가서 직접 나서서 한 명도 살려두지 말고, 더 이상 농부들이 죽지 않도록 해!"},objectives={{27,1556772888},"애쉬엔베일 스토커 20마리를 처치하세요."},progress={{97,1145658636},"가서 직접 손을 더럽히고, 살아남는 자는 한 명도 남기지 말고, 더 이상 하층민들이 죽지 않도록 해라."},completion={"With the interference of the elves gone we can resume our duty in peace, thank you $N, you are more capable than I thought you will.","엘프들의 방해가 사라졌으니 이제 평화롭게 우리의 임무를 재개할 수 있겠군요.$N님, 감사합니다. 생각했던 것보다 훨씬 유능하시군요."}}
rows[70026]={title={{24,1363613264},"피온의 옷장 변신"},description={"With most of the tasks done, I only have but a favor to ask of you, our poor peons have been wearing the same tattered clothing since we've come to this damned forest, they can't take another day in those rags and I most certainly won't be the one blamed for naked peons chopping wood!$B$BI need you to hunt and skin some bears for me, North of Splintertree Post and in its immediate vicinity to the left you will be able to find bears, grab enough for our leatherworker to craft new cloths for those poor miserable souls, but remember $N, only hunt the eldest of the bears.","대부분의 일은 끝났으니, 부탁 하나만 드리겠습니다. 우리 불쌍한 일꾼들이 이 지긋지긋한 숲에 온 이후로 계속 해진 옷만 입고 있는데, 더 이상 하루도 그 누더기를 입고 버틸 수가 없습니다. 벌거벗은 일꾼들이 나무를 베는 $B$B걸 제가 책임질 순 없잖아요! 스플린터트리 기지 북쪽, 바로 근처 왼쪽에 곰들이 있을 겁니다. 가죽 세공사가 새 옷을 만들 수 있도록 충분히 잡아다 주세요. 하지만 명심하세요, 곰 중에서 $N제일 늙은 곰만 잡아야 합니다."},objectives={{38,614483255},"엘더 애쉬엔베일 곰 가죽 10개를 모으세요."},progress={{44,1929169151},"곰은 반드시 가장 나이가 많은 개체만 사냥해야 한다는 것을 명심하십시오."},completion={"You have my thanks $N, your work helped me and my men more that you'd imagine, as a sign of gratitude the leatherworker made this for you.","$N님, 정말 감사합니다. 당신의 도움은 저와 제 부하들에게 상상 이상으로 큰 힘이 되었습니다. 감사의 표시로 가죽 세공사가 당신을 위해 이것을 만들어 드렸습니다."}}
rows[70027]={title={{15,1237422313},"파시어 그리메이"},description={{484,1514895206},"들판은 깨끗해졌고, 일꾼들은 행복해 보이며, 생산성은 예전보다 훨씬 좋아졌습니다. 바로 그 때문에 자네를$B$B 다른 임무에 보내는 겁니다. 자네가 돕고 싶어 하는 것 같고, 솔직히 예언자는 도움이 절실히 필요하거든요. 그는 심술궂은$B$B 늙은 오크이니, 그의 불만을 약점으로 절대 생각하지 마시오. 자네에게 힘든 일을 맡기겠지만, 자네가 잘 해낼 거라고 믿어 의심치 않습니다. 지금 가서 이 양피지를 전해주시오. $B$B그는 여기 북동쪽에 있는 성채에 있을 겁니다."},objectives={{54,145118925},"사령관 그루샤크의 보고서를 선견자 그림아이에게 전달하세요."},progress={{68,1072576111},"그래서 그루샤크가 드디어 자기 부하들이 제 역할을 하는 모습을 보고하는 건가?"},completion={{27,1102022479},"자, 이제 널 어떻게 해야 하지?"}}
rows[70028]={title={{17,1140278377},"데몬 폴 캐니언"},description={"What do you see here $N? I will tell you what I see; a roaming pack without its Alpha. Simple minded buffoons who lost their commander.$B$BSometimes I ask myself what would have happened if Hellscream… doesn't matter now.$B$BFalling down into the Demon Fall Canyon you will see numerous spawns of the Burning Legion. As you should know, a great demon fell there, hence the namesake, I suppose.$B$BYour mission is clear, yet, not so simple. Wreak havoc and cull their numbers. I expect you do whatever you see fit to leave none alive.","여기서 뭘 보고 있지,$N ? 내가 보는 건 이렇지. 우두머리를 잃은 떠돌이 무리일 뿐이야. 지휘관을 잃은 어리석은 바보들이지. 가끔 헬스크림이$B$B 있었다면 어떻게 됐을까 생각해 보곤 하는데… 뭐, 이제 와서 중요한 건 아니지만.$B$B 악마의 폭포 협곡으로 내려가면 불타는 군단의 수많은 새끼들을 보게 될 거야. 알다시피, 거대한 악마가 그곳에 떨어졌지. 그래서 그런 이름이 붙었겠지. 네 임무는 명확하지만,$B$B 그리 간단하지는 않아. 궤멸을 일으키고 그들의 수를 줄여라. 살아남는 자는 한 명도 없도록 네가 할 수 있는 모든 것을 다 하라는 뜻이야."},objectives={{91,1972321532},"마노록 채찍꾼 10마리, 작열하는 지옥불정령 10마리, 지옥수호병 10마리를 처치하십시오. 예언자 그림아이에게 보고하십시오."},progress={{57,116855324},"당신은 겁쟁이가 아닌 것 같은데, 그렇다면 왜 아직 여기 있는 겁니까?"},completion={{224,271143305},"좋아. 적의 수는 군단이나 되고 우리 무기는 쉴 틈도 없지만, 우리는 오직 살아남고자 하는 강한 열망으로 그들의 정복 계획을 극복하고 승리할 것이다.$B$B자, 내가 결제 수단으로 몇 가지 물건을 준비해 두었으니, 마음에 드는 걸로 골라."}}
rows[70029]={title={{12,500133721},"우리가 알고 있는 것"},description={{570,2050102222},"우리 병사들이 나이트 엘프 한 마리가 어슬렁거리는 것을 발견했습니다. 그 기형적인 생명체의 시체에서 편지가 발견되었죠. 그 끔찍한 언어를 해독하려 애쓰면서 느꼈던 역겨움은 차마 말로 설명할$B$B 수 없습니다. 협곡 위쪽에 무덤 굴이 하나 있을 겁니다. 칼날 귀를 가진 이 잡종들이 파놓는 구덩이 중 하나죠. 도르다닐 무덤 굴에는 가지 마세요. 당신이 찾는 무덤 굴은 능선에 있습니다. 제가 그 편지에서 알아낸 바로는, 가장 깊은 곳에 엄청난 위협이 도사리고 있다고 합니다. 그곳에$B$B 무엇이 숨어 있는지 알아내고 바람처럼 빠르게 제게 돌아오세요."},objectives={{25,1394028611},"진짜 위협을 발견하세요."},progress={"Hopefully you will survive to tell the story, $C.","$C님, 부디 살아남아 이 이야기를 전할 수 있기를 바랍니다."},completion={{140,1129154460},"하필이면 공포의 군주라니? 쉽지는 않겠군. 지금 네 상태로는 회오리바람 속의 나뭇가지에 불과하지만, 다른 방법도 있지."}}
rows[70030]={title={{23,1763592203},"아주 불쾌한 트롤"},description={{432,877371044},"우리는…<늙은$B$B 오크가 한숨을 $B$B쉬었다>내 오랜 \"친구\"의 도움이 필요할 거야. 주술사의 마법만큼 강력한 건 없으니 자네를 스톤탈론으로 보내네.진질을$B$B 찾아서 이 편지를 전해 주게. 그의 마법은 드레드로드의 크기를 줄이고 약화시켜 자네가 처치할 수 있을 만큼 강력하거든.$B$B하지만! 그가 자네에게 임무를 줄 거야. 아마 쉽고 별 의미 없는 일일 테니 거기서 너무 시간을 낭비하지 마. 우린 드레드로드를 처치해야 하니까."},objectives={{50,484717304},"진질을 찾아 그리메이가 보낸 편지를 전해주세요."},progress={{71,2058460227},"나무를 껴안고 있는 세 꼬마 엘프들, 진질 할아버지가 곧 요리를 시작하실 거예요!"},completion={{53,1476394022},"아, 안녕하세요, 못 봤네요. 무슨 용건이세요?"}}
rows[70031]={title={{14,1014771304},"진질의 스튜"},description={{309,135294588},"그리미아이가 드레드로드 처치에 내 마법을 써주길$B$B 원한다고?그래, 진질을 도와주면 진질도 널 도와줄 거야. 이 스튜에 재료가 더 $B$B필요하거든!네가 재료를 가져오면 내가 마법을 $B$B줄게.멜론 주스, 드워프 순한 술, 멧돼지 정강이살, 그리고 진정 효과가 있는 향신료가$B$B 좀 필요해!가자, 진질이 가마솥을 휘젓고 기다릴게!"},objectives={{43,1273233726},"진질의 스튜에 필요한 모든 재료를 모으세요."},progress={"Hey, $N, I wonder what $R tastes like.$B$BBut don't worry I won't be eating you! Maybe.","이봐,$N,$R는 무슨 맛일까 궁금하네.$B$B하지만 걱정 마, 널 먹지는 않을 거야! 어쩌면."},completion={{102,776814235},"스튜가 거의 다 됐어, 맛 좀 보자.$B$B끔찍해!$B$B그래도 아내가 만든 것보다는 맛있네."}}
rows[70032]={title={{13,1117214587},"굿 모조"},description={{263,1556644259},"자, 이 소포를 받아 그리미아이에게 전해줘. 진질이 그 심술궂은 오크 영감탱이에게 필요한 것보다 더 많은 마법을 넣어줬거든. 내 안부 좀$B$B 전해 주고, 우리가 뼈 속에서 뒹굴었을 때 걔가 나한테 돈을 갚아야 한다고 전해 줘! $B$B난 절대 잊지 않을 거야!"},objectives={{39,586518997},"그 소포를 파시어 그리메이에게 전달하세요."},progress={{24,1573814021},"왜 이렇게 오래 걸렸어?"},completion={"That daft fool just won't let go of it! I told him we were not playing on coin, gah.$B$B<Grimeye clears his throat.>$B$BIn any case $N, well done. Now let's go kill us a dreadlord.","저 멍청이가 도무지 놓지 않네! 동전으로 게임하는 거 아니라고 했잖아, 젠장.$B$B<그리미아이가 헛기침을 한다.>$B$B어쨌든$N잘했어. 자, 이제 가서 드레드로드 처치하러 가자."}}
rows[70033]={title={{19,703531412},"구도자의 최후"},description={"This is it $N, your most dangerous task yet, but I am more than sure you will succeed.$B$BYou showed courage I have not seen in so long, may the ancestors guide your steps and may you return unharmed.$B$BYou have my blessings and the ancestors at your side.$B$BRemember that where you stand a great warrior once stood and you too shall walk in his steps, slay them with pride in your heart!","이것이 바로$N 네게 주어진 가장 위험한 임무다, . 하지만 난 네가 반드시 성공할 거라고 $B$B확신한다. 네가 보여준 용기는 정말 오랜만에 보는 것이라. 선조들이 네 발걸음을 인도하시고 무사히 돌아오길 기원한다.$B$B 내 축복과 선조들의 가호가 네 곁에 있으리라. 네가 서$B$B 있는 이 자리에 위대한 전사가 서 있었음을 기억하거라. 너 또한 그의 발자취를 따라 걸으며, 자부심을 가지고 적들을 물리치도록 하거라!"},objectives={{68,1183303806},"탐색자 디아토루스를 처치하고 그의 머리를 파시어 그리메이에게 가져가십시오."},progress={{52,610227849},"그의 잘린 머리를 가져오면 불태워 버리겠다!"},completion={"You have done something not many can do, $C, walk with pride from this day onward.$B$BThis old orc is reminded of the past but from now on he will dream of the future.$B$BI will set fire to the head and mention you the slayer to our clan, but the ancestors tell me your path only begins my dear friend.$B$BI truly hope you will one day find what you seek.","$C, 자네는 많은 이들이 할 수 없는 일을 해냈네. 오늘부터 자부심을 가지고 나아가게.$B$B이 늙은 오크는 과거를 떠올리지만, 이제부터는 미래를 꿈꿀 것이네.$B$B나는 자네의 머리에 불을 지르고 우리 부족에게 자네를 살인자로 칭송하겠지만, 조상들은 자네의 길은 이제 막 시작되었다고 말하네, 친구여.$B$B자네가 언젠가 원하는 것을 찾기를 진심으로 바라네."}}
rows[70034]={title={{11,2018210514},"매의 부리"},description={{351,1607809151},"노르보크는 가문의 유물을 찾으러 나갈 만한 상태가 아니지만, 완전히 회복되기 전에 무작정 나가려 할까 봐 걱정됩니다.$B$B 그가 남겨둔 창의 흔적이라도 찾아주시면 저와 노르보크에게 큰 도움이 될 것입니다. 동쪽의 악마들이 $B$B있는 곳이 가장 유력한 수색 대상이니, 어서 가십시오!"},objectives={{71,1080905979},"애쉬엔베일에서 노르보크 호크스피어를 위해 노르보크의 무기 흔적을 모두 찾아내십시오."},progress={{6,130161156},"네?"},completion={{469,1582378542},"이 창은 우리 가문에서 여러 세대에 걸쳐 사용되었습니다.$B$B내가 그 일을 끝맺게 하고 부족에 수치를 안겨주었다는 사실이 슬픕니다.$B$B<노르복은 커다란 콧구멍으로 깊이 숨을 들이쉬고는 미소를 지으며 숨을 내쉬었다.>$B$B슬퍼하지 마, 내 새로운 친구. 네가 생각하는 것보다 훨씬 더 많이 도와줬어. 이건 끝이 아니라 단지 시작일 뿐이야.$B$B칼날을 다시 벼려 더 튼튼하게 만들어야겠다. 어쨌든 매의 날개를 잘라도 부리는 여전히 위험하니까."}}
rows[70040]={title={{25,1868007001},"무덤을 강화하다"},description={"I never gave up on my dream, $N, my mission still stands even in death, I lived to forge and help our proud soldiers protect themselves, alas, you too will help me to do that.$B$BOur men face peril down to Silverpine Forest, the last of the Scourge, the magi of Dalaran and the foul beasts Arugal summoned upon our lands.$B$BI'd imagine the Sepulcher it's short supplied, bring them these items. You will be expected.$B$BUpon delivery you will be rewarded with plans for a new set of armor, so you too will be ready to face our enemy.",", 저는 제 꿈을 결코 포기하지 $N않았습니다. 제 임무는 죽음조차도 유효합니다. 저는 자랑스러운 우리 병사들이 스스로를 지킬 수 있도록 갑옷을 제작하고 돕기 위해 살았습니다. 아아, 당신도 $B$B저를 도와야 할 것입니다. 우리 병사들은 은빛소나무 숲에서 스컬지의 잔당, 달라란의 마법사들, 그리고 아루갈이 우리 땅에 소환한 흉악한 짐승들과 맞서 싸워야 $B$B합니다. 아마도 무덤에는 물자가 부족할 겁니다. 이 물품들을 가져다주십시오. 당신의 도움이 필요할 $B$B것입니다. 물건을 전달하면 새로운 갑옷 제작 도면을 보상으로 받게 될 것입니다. 그러면 당신도 적을 상대할 준비가 될 것입니다."},objectives={{112,249735995},"바질 프라이는 은빛소나무 숲에 있는 에드윈 할리에게 룬이 새겨진 구리 벨트 4개와 무거운 구리 망치 4개를 가져다 달라고 부탁했습니다."},progress={{19,69431974},"아직 여기 계세요?"},completion={"This will be a great help, $C.","$C님, 이것은 큰 도움이 될 것입니다."}}
rows[70049]={title={{12,703702003},"텐트를 치세요"},description={"It seems that drunkard is getting quite the laugh from me paying you out of pocket, $N. This dwarf wants me to repair some tents! Do I look like I know how to repair a tent?! And he's cracking jokes about how even an ogre knows how to pitch a tent!$B$BLook, $N, help me out here so I don't make a complete fool of myself.$B$BWe're going to need some cloth to repair these tents and apparently those ogres to the west may have what we're looking for. But, believe me, I have no idea what that dwarf is talking about!","술주정뱅이가 내가 네게 사비를 쓰는 걸 보고 꽤 웃고 있군, . 이 $N드워프는 나보고 텐트를 고치라고 하잖아! 내가 텐트를 고칠 줄 아는 것처럼 보여?! 게다가 오우거도 텐트를 칠 줄 안다고 농담까지 하고 있잖아!$B$B ,$N 좀 도와줘. 내가 완전히 바보가 되지 않도록. 텐트를$B$B 고치려면 천이 필요한데, 서쪽에 있는 오우거들이 우리가 찾는 걸 가지고 있을지도 몰라. 하지만, 솔직히 말해서, 저 드워프가 무슨 말을 하는지 하나도 모르겠어!"},objectives={{58,738192980},"배드랜드의 놀리에게 가져갈 튼튼한 텐트 천 10장을 모으세요."},progress={{35,988080416},"내가 필요한 그 천을 찾으셨어?"},completion={"Thank you, $N. You know I've been thinking about what that dwarf said about ogres pitching tents and it just dawned on me!$B$BI'm going to make sure there's at least one dwarf who can't pitch a tent anymore!$B$BAnyways, here is your reward. ","고마워,$N. 드워프가 오우거가 텐트를 치는 것에 대해 했던 말을 생각해 봤는데, 갑자기 좋은 생각이 떠올랐어!$B$B이제 텐트를 칠 수 없는 드워프가 적어도 한 명은 생기도록 만들어야겠어!$B$B어쨌든, 보상은 이거야."}}
rows[70050]={title={{11,976437124},"만능 해결사님!"},description={"That drunken fool! He's absolutely outrageous! I am here for serious matters, not mundane, meaningless tasks. I will not stand for this, no, no!$B$B$N, please, help me out. I'd rather pay you than give that man the satisfaction that he convinced someone of my intellect to do this laborsome chore.$B$BThere should be some old lumber around these ruins. This desolate place has no trees, it's just a barren wasteland as far as I can see! Try and find any lumber you can and bring it back to me so we can prepare a fire.","저 술주정뱅이 바보! 정말 뻔뻔스럽군! 난 심각한 일 때문에 여기 온 거지, 시시하고 무의미한 일을 하러 온 게 아니야. 이런 짓은 용납할 $B$B$N수 없어, 절대 안 돼! 제발, 좀 도와줘. 저 사람이 나처럼 똑똑한 사람을 설득해서 이런 고된 일을 시켰다는 걸 알게 하는 것보다 차라리 $B$B돈을 내는 게 낫겠어. 이 폐허 주변에 낡은 목재가 좀 있을 거야. 이 황량한 곳에는 나무 한 그루 없어. 내가 보기엔 온통 불모지뿐이야! 찾을 수 있는 목재가 있으면 좀 가져다줘. 그래야 불을 피울 수 있잖아."},objectives={{61,623159037},"마른 장작을 좀 모아서 불모의 땅에 있는 놀리에게 돌아가세요."},progress={{63,932938325},"저 술 취한 늙은 난쟁이! 으악! 제발 최대한 빨리 돌아와 줘."},completion={{90,2070458426},"당신의 도움이 저에게 얼마나 큰 의미인지 당신은 상상도 못 하실 거예요.$B$B감사의 마음을 담아 작은 선물을 드립니다."}}
rows[70051]={title={{16,822657345},"기름 얼룩진 금"},description={{473,475332109},"쉿, 친구. 잠깐 이리 와볼래? 어이,$B$B 오늘 잘 지내? 너한테 알려줄 만한 좋은 정보가 있어. 잘 들어봐. 저기 해안가에 침몰한 배들이 있는데, 옛날 얼라이언스 함선들이야. 연료가 아직 남아있다고 하더라고. 연료는 우리 고블린한테 아주 귀중한 자원이거든. 그 배들이 널 기다리고$B$B 있어! 그 난파선에서 건져낸 게 있으면 나한테 가져다줘. 그럼 꼭 보상해 줄게."},objectives={{56,1878549950},"레이저 힐에 있는 페지크 빌라마르에게 석유 5배럴을 가져다 주세요."},progress={{98,218118198},"이봐, 친구. 저 배들이 어디로도 안 가는 건 알지만, 어서 일어나서 가볼래?"},completion={{146,2017781243},"그래, 완벽해! 정말 완벽해! 이 고블린은 너무 기뻐서 눈물이 날 지경이야. 자, 여기 보수다. 어서 가, 나 연료 팔러 가야 하니까."}}
rows[70052]={title={{19,250516634},"상인의 불행"},description={"These pirates are an infestation to our port, even worse than the rats we have to exterminate each month.$B$BIt's absolutely ridiculous, $N.$B$BWhat's even worse is the fact that some foolish trader decided to do business with them. Whatever idea crossed his small brain to do that I will never know.$B$BWhile you're out there hunting for pirates, be on the lookout for Tazan and take care of him as well.$B$BCome see me after and I'll be sure to reward you.","이 해적들은 우리 항구에 골칫거리야. 매달 박멸해야 하는 쥐떼보다 더 심각해.$B$B 정말 어처구니없군,$N$B$B N. 더 심각한 건 어떤 멍청한 상인이 그들과 거래를 하기로 했다는 거야. 도대체 무슨 생각으로 그랬는지 도무지$B$B 이해할 수가 없어. 해적 소탕하러 나가는 김에 타잔도 잘 살펴봐. 나중에$B$B 꼭 나한테 와. 보상은 꼭 줄게."},objectives={{57,270937624},"타잔을 처치하고 라쳇을 타고 부두 관리인 디지윅에게 돌아가십시오."},progress={{87,1007065608},"살다 보면 후회할 선택을 하게 되는데, 타잔은 이번 선택을 분명히 후회하게 될 것이다."},completion={{147,938829776},"돌아왔구나, 잘됐어.$B$B그리고 트로피로 뭘 좀 가져갔나 보네. 이상하긴 하지만, 네 취향이라면 뭐든 좋아!$B$B수고비로 돈 좀 줄게."}}
rows[70053]={title={{15,874545813},"로크 메너스"},description={"Something's wrong with the threshadons, $N. They are out of their hiding place and are eating all the fish of the lake!$B$BFor a while now, our local fishing business has been in a decline thanks to that. I am afraid we'll have to accept the fact that we must cull their numbers so that we can maintain a certain balance.$B$BThey are beautiful creatures we've shared the lake with for generations, so it pains me that we must take such extreme actions against them.$B$BIt's only expected of me to ask an outsider to do what we can't, and are not willing to do.",", 쓰레샤돈에 문제가 생겼어요. $N숨어 있던 곳에서 나와 호수의 물고기를 싹쓸이하고 있어요! 그 때문에$B$B 우리 지역 어업이 한동안 침체되어 왔습니다. 균형을 유지하려면 쓰레샤돈 개체 수를 줄여야 한다는 사실을 받아들여야 할 것 같습니다. 수 세대 동안 호수를 함께 공유해$B$B 온 아름다운 생물들인데, 이렇게 극단적인 조치를 취해야 한다는 것이 너무나 마음 아픕니다. 우리가 할 수 없고, 하려고$B$B 하지도 않는 일을 외부인에게 부탁하는 것은 어쩔 수 없는 일인 것 같습니다."},objectives={{74,1366037701},"로흐 모단에서 스레샤돈을 처치하고 로흐 모단의 워그 딥워터로 돌아가십시오."},progress={"Are you done already, $N?","$N님, 벌써 끝나셨나요?"},completion={{268,643763738},"크기가 더 작았다는 말씀이시군요? 그렇다면 그들이 배고팠던 이유가 설명되겠네요.$B$B하지만, 왜 그렇게 일찍 둥지를 떠났을까요? 그리고 왜 하필 모두였을까요?$B$B<워그는 잠시 생각에 잠겼다가 당신에게 돌아섭니다.>$B$B약속대로 지불했습니다. 더 자세히 조사해 보겠습니다."}}
rows[70054]={title={{15,983724318},"심각한 불의"},description={"These lands aren't what they used to be, $C. Monsters have taken what's left of it, both the living and the dead.$B$BThere have been reports of grave robbers in the cemetery at Raven Hill. A crime this vile and depraved cannot go unpunished.$B$BPlease, head west to the cemetery and investigate this matter. If you find any grave robbers, get rid of them.$B$BThe place was already desecrated by the Scourge. The living shouldn't disturb the dead even further.","이곳은 예전 같지 않아, . $C괴물들이 산 자와 죽은 자 모두를 앗아갔어.레이븐 힐 $B$B묘지에서 도굴꾼들이 출몰했다는 보고가 있어. 이렇게 사악하고 끔찍한 범죄는 처벌받지 않고 넘어갈 수$B$B 없어.부디 서쪽 묘지로 가서 이 사건을 조사해. 도굴꾼을 발견하면 처리해.이곳은 이미$B$B 재앙에 의해 더럽혀졌어. 산 자들이 죽은 자들을 더 이상 건드려서는 안 돼."},objectives={{56,2116009636},"묘지에서 벌어지는 도굴꾼들의 활동을 조사하십시오."},progress={{62,154038090},"암울한 시기에 베푸는 선행, 바로 그것이 당신이 하려는 일입니다."},completion={"Good work, $C. What's that shovel you've got there? I think I recognize the initials.","잘했어,$C. 네가 들고 있는 삽은 뭐야? 이니셜이 왠지 익숙한데."}}
rows[70055]={title={{18,419521010},"황혼숲의 데피아스"},description={"I can only think of one person with those initials and that would be Sven Yorgen. He used to own the Yorgen Farmstead. In all of the chaos the farmstead was lost to the Defias Brotherhood who slowly made their way from Westfall.$B$BI assume Sven has nothing to do with the grave robbers, but the Defias might. Seems to me it's only a coincidence. In any case, the Defias must be brought to an end. We have enough on our plate when it comes to enemies and culling some of their numbers will bring peace to those who have yet to given up on their home.$B$BTherefore I ask that you slay any Defias in your way. The Night Watch has seen their activity in Addle's Stead prior to your investigations, so perhaps it'd be best to start there, $N.","그 이니셜을 가진 사람은 스벤 요르겐 한 명밖에 생각나지 않습니다. 그는 예전에 요르겐 농장을 소유했었죠. 그 혼란 속에서 농장은 서부 몰락지대에서 천천히 진격해 온 데피아즈 형제단에게 넘어갔습니다. 스벤은 무덤 도굴꾼들과는$B$B 관련이 없을 거라고 생각하지만, 데피아즈 형제단과는 연관이 있을지도 모릅니다. 제 생각엔 단순한 우연의 일치인 것 같습니다. 어쨌든 데피아즈 형제단은 반드시 소탕해야 합니다. 이미 적들이 너무 많은데, 그들의 수를 줄이는 것이 아직 고향을 포기하지 않은 이들에게 평화를 가져다줄 겁니다. 그러니$B$B 당신의 길을 막는 데피아즈들을 모두 처치해 주십시오. 나이트 워치는 당신의 조사 이전에 애들 농장에서 그들의 활동을 목격했으니, 그곳부터 시작하는 게 좋을 겁니다, $NN."},objectives={{79,633722756},"황혼의 숲에서 데피아즈 형제단의 구성원들을 처치하고 감시자 페이지에게 돌아가십시오."},progress={"My trust rests with you, $N. Please, do not fail me.","$N, 당신을 전적으로 신뢰합니다. 부디 저를 실망시키지 말아 주세요."},completion={{98,833645290},"그들의 수가 줄어든 것은 다행이지만, 직간접적으로 생명을 앗아가는 것은 결코 내 마음에 드는 일이 아니다."}}
rows[70056]={title={{19,1080006526},"다크샤이어에 보고"},description={"You have done me and the people of Duskwood a great favour, one I would like you to report to my commander.$B$BI am more than sure she will like to hear of your success against the Defias, and she will probably have another job for you.$B$BTake this parchment to Commander Althea Ebonlocke. She is stationed in front of the town hall so she'll be hard to miss.$B$BOh, and, $N, thank you.","당신은 저와 더스크우드 주민들에게 큰 은혜를 베풀어 주셨습니다. 이 일을 제 사령관께 보고해 주시길 $B$B바랍니다. 데피아족과의 전투에서 거둔 당신의 성공을 사령관께서 기뻐하실 것이 분명하며, 아마도 당신에게 다른 임무를 맡기실 $B$B겁니다. 이 양피지를 알테아 에본록 사령관께 가져다 주십시오. 그녀는 시청 앞에 서 계시니 찾기 쉬울 겁니다. 아, $B$B그리고, $N고맙습니다."},objectives={{72,109901242},"감시자 페이지의 보고서를 다크샤이어에 있는 알테아 에본록 사령관에게 가져다 주십시오."},progress={"Yes, $C?","예,$C?"},completion={{147,479114998},"페이지를 도와주셔서 정말 감사합니다. 그녀는 오랫동안 그 캠프에 있었어요.$B$B하지만 안타깝게도 지금 상황에서는 저희가 할 수 있는 일이 거의 없습니다."}}
rows[70057]={title={{15,1792515262},"단순한 기억"},description={{486,1662846194},"스벤이 레이븐 힐 묘지 근처의 오두막에 피신해 있다는 소식을 들었습니다. 그는 후회와 분노에 가득 차 있을 $B$B것 같습니다. 그의 집터에서 이 삽을 찾았으니, 어쩌면 그가 좋아할지도 모르겠습니다. 부디 $B$B조심해서 삽을 주인에게 돌려주세요. 그가 좋아할지도 모르고, 아니면 반으로 부러뜨릴지도 모릅니다. 누가 알겠습니까. 다시 한번 모든 도움에 감사드립니다."},objectives={{32,520123009},"삽을 스벤 요르겐에게 가져다 주세요."},progress={{11,819267740},"그게 뭐죠?"},completion={"What do you have there, $C?$B$BOh, where did you find this?$B$BThis was the shovel my father had given me back when we worked the farmstead years ago. It served me well, and reminds me of him.$B$BMemories of a better time.$B$B<Sven stares at the shovel and hands it back to you.>$B$BIt was a nice gesture of you to bring me this, $N, but I have no use for it anymore.$B$BDo with it what you will.","$C, 그게 뭐야?$B$B아, 이건 어디서 찾았어?$B$B이건 아버지가 오래전 농장에서 일할 때 내게 주신 삽이야. 아주 유용하게 썼고, 아버지를 떠올리게 해.$B$B좋았던 시절의 추억이지.$B$B<스벤은 삽을 바라보다가 당신에게 돌려준다.>$B$B이걸 가져다줘서 고맙지만,$N난 이제 필요 없어.$B$B마음대로 해."}}
rows[70058]={title={{10,7850322},"법과 오거"},description={{518,1393862867},"페이지에게 당신의 능력을 증명해 보였고, 솔직히 말해서 나이트 워치에는 언제나 $B$B일손이 더 필요합니다. 우리 병력이 늑대인간과 스컬지에 집중하는 동안, 남쪽의 불골 오우거 언덕으로 가서 오우거 개체 수를 $B$B줄여주시길 바랍니다. 언덕에 대해 아는 정보는 많지 않지만, 오우거들을 제거해야 한다는 것은 확실합니다. 그들은 우리 정찰병과 서부 몰락지대 및 가시덤불 골짜기으로 가는 길에 위협이 $B$B됩니다. 물론, 돌아오시면 보상이 기다리고 있습니다."},objectives={{51,1580864295},"불골 오우거 언덕에서 스플린터 피스트 오우거를 처치하세요."},progress={{13,1077178813},"벌써 돌아오셨네요?"},completion={{156,959151619},"당신은 야간 경비대에 큰 도움이 될 인재이지만, 경비 근무에 지루해할 리는 없겠죠. 수고 많으셨습니다. 작은 보상으로 드리겠습니다."}}
rows[80100]={title={{16,1846981859},"새로운 광고 사업"},description={{697,1772333074},"자, 친구, 잘 들어! 투자개발회사에서 맡은 첫 임무인 거 아니까 천천히 말해줄게.여기 귀중한$B$B 보물을 찾으러 온 거야, 알겠어? 언더마인에 있는 보석 절반보다 더 값비싼 보물이라고 하더군. 보스가 어서 손에 넣고 싶어 안달이 났어. 지난번에 보낸 팀은 아무것도 안$B$B 가져왔거든.도둑놈들이 보스한테서 도망칠 수 있을 거라고 생각했나? 보스가 절대 쫓아오지 않을 거야. 빈손으로 돌아오지 말라고 했으니, 어서 일을 시작하자.$B$B여기 내려오는 길에 우리 비행선에서 몇몇 장비들이 부서지긴 했지만, 다행히 지난번 팀이 로봇들을 두고 간 것 같아. 가서 로봇들을 좀 챙겨 와 줄래?"},objectives={{86,2101958694},"회전하는 로봇에게서 회전하는 마법 도구 8개를 모은 다음, 네르트 블래스텐톰에게 돌아가세요."},progress={{48,1407013173},"\"시간은 돈이다\"라는 말 아시죠, 직원 여러분."},completion={{123,1408412918},"잘했어, 꼬마야. 이대로 계속하면 18년이나 19년 후에는 반장이 될 수도 있겠어.$B$B경쟁이 치열하잖아요."}}
rows[80101]={title={{16,679841762},"벤처 벌처스"},description={{459,1342541205},"이건 정말 최악이야!$B$B 투자개발회사는 재미와 모험, 그리고 달콤한 수익을 위한 회사였는데, 지금까지 우리가 한 일이라고는 아무것도 없는 오지로 날아가서 밥도 없이 빈둥거리는$B$B 것뿐이잖아. 들어봐, 넷이 뭐라고 하든 상관없어. 저녁도 안 먹고는 더 이상 일 못 해. 너 숲에 갈 거지? 그럼 독수리 고기 좀 가져와. 무법항 스테이크만큼은 아니겠지만, 스프랫이 어떻게 요리하는지 보여줄 테니까!"},objectives={{55,1136798790},"정어리 노즐톤에게 고원독수리 고기 6조각을 가져오세요."},progress={{33,1606732264},"저는 어디에서도 찾아볼 수 없는 최고의 식사를 제공합니다!"},completion={{180,1108610479},"좋아! 두고 봐. 엄마 스프랫이 이 독수리 조각들로 마법을 부릴 거야.$B$B넌 썩은 시체를 먹는 새를 먹고 있다는 사실조차 모를 걸!$B$B어... 방금 한 말은 잊어버려."}}
rows[80102]={title={{18,613501708},"녹색 대 녹색"},description={{530,1897090974},"농담하는 거지? 여긴 산길보다 1마일이나 높은 곳인데, 여기에 엘프가 있다고? 이봐, $B$B꼬마야, 엘프는 세상에서 제일 이성 없는 생물이야. 착한 고블린은 숲을 보면 돈만 생각하지! 하지만 엘프는 뭘 보겠어? 곰? 올빼미? 눈 큰 아기 다람쥐? 생각만 해도 역겨워. 축하해,$B$B 오늘은 네가 해결사 노릇을 하게 됐군. 나가서 나무꾼들 좀 베어버려. 그리고 김에 그 이상한 살아있는 식물들도 좀 베어버려. 덩굴을 타고 다니는 건 하나도 믿을 수가 없거든."},objectives={{91,372734977},"스톤탈론 환경운동가 7명과 하이피크 래셔 5명을 처치한 후 네르트 블래스텐톰으로 돌아가십시오."},progress={{211,174213777},"멍청한 엘프들은 나무를 너무 좋아해. 해안가에 살려고 거대한 나무를 키웠다는 거 알아?$B$B도시만 한 나무를 키울 마법이 있으면서도 목재 시장 생각은 전혀 안 해. 정말 미친 짓이야."},completion={{297,2051524046},"잘했어, 신병! 넌 이제 내 최고 직원 명단에 공식적으로 올라 있어. 나랑 같이 있으면 크게 성공할 거야!$B$B아, 음... 자네한테 싸움을 시킬 거라면 날카로운 재치 말고 다른 무기를 줘야겠군. 이 무기를 공짜로 줬다는 건 아무한테도 말하지 마!"}}
rows[80103]={title={{15,952433605},"라이즌 오일블레이즈"},description={{514,390222212},"음, 엘프들이 왜 여기 있는지 이제 알겠군. 저 앞쪽 숲 전체가 불타고 있어! 그것도 분명 고블린 짓이야.그렇게 오래 타는$B$B 기름은 다른 종족이 쓰는 게 아니야! 그건 언더마인에서나 쓰는 거라고, 꼬마야. 노움이 그걸 구할 리가 없어. 여기 무슨 일이 벌어지고 있는지는 모르겠지만, 영 마음에 안 들어.가서 $B$B그 기름 좀 가져와. 우리가 오기 전에 무슨 일이 있었는지 단서를 찾을 수 있을지도 몰라. 설령 못 찾더라도, 적어도 우리 기름은 충분히 모을 수 있을 테니까!"},objectives={{103,33048878},"불타는 들판에 있는 부활한 기름불꽃에서 살아있는 석유 8개를 모은 다음 네르트 블래스텐톰으로 돌아가세요."},progress={{144,676905880},"이건 내버려 두면 몇 년 동안 탈 거야. 고블린의 비밀 기술인 데는 다 이유가 있지. 하지만 숲 전체를 태워버리는 건 이득이 없잖아!"},completion={{110,1149118219},"이건 말이 안 돼. 왜 그렇게 귀중한 물건들을 두고 갔을까?$B$B도대체 다들 어디로 간 거야?"}}
rows[80104]={title={{20,1593728084},"또 다른 하얀 메카"},description={{363,109464481},"돈 벌려고 머리통 깨는 것보다 더 좋아하는 게 있다면, 바로 새 기계 장치를 만드는 거지. 저 불타버린 숲 속에는 온갖 부품들이 널려 있는데, 친구, 저 녀석들로 푸짐한 기계 잔치를 벌이고 싶어서 입에 침이 고여! 왜 다른$B$B 탐험대가 그렇게 많은 걸 남겨두고 갔는지 모르겠지만, 난 상관없어. 어서 그 부품들을 좀 가져다줘!"},objectives={{91,14199539},"기계 닭에게서 기계 닭다리 5개를 모아 스프랫 노즐턴에게 돌아가세요."},progress={{119,1293952344},"자, 뭘 기다리고 있는 거야?$B$B넌 이제 뭔가 거창하고 강인한 해결사 역할을 해야 하잖아, 그렇지? 어서 부품 좀 가져와!"},completion={{331,2109807651},"아시다시피, 가끔 농부들이 자기네 닭이 내 닭보다 낫다고 말하곤 해요. 자기네 닭은 폭발하지 않는다고요.$B$B개인적으로는 제 닭이 더 낫다고 생각해요. 똑같은 이유로요. 어쨌든, 부품 좀 가져다주셔서 감사합니다.$B$B이 계곡에서 무슨 일이 벌어지고 있는지는 모르겠지만, 뭔가 도움이 될 만한 걸 만들어낼 수 있기를 바랍니다."}}
rows[80105]={title={{16,834213705},"너무 멀리 나아갔다"},description={{355,1481070373},"정령의 잔해 속에서 기름에 흠뻑 젖어 가장자리가 그을린 쪽지를 발견합니다. 글씨 대부분은 거의 알아볼 수 없지만, 중요한 부분 하나를 해독할 수 있습니다.>... 멍청한 $B$B사장이 이 장소에 대해 아무것도 말해주지 않았어. 평범한 곳이 아니야... 무덤이야. 뭔가 끔찍한 게 묻혀 있어... 숲 $B$B한가운데에...<이건 반장에게 보고해야 할 것 같아.>"},objectives={{72,1292186108},"기름에 그을린 쪽지를 착륙 지점에 있는 네르트 블래스텐톰에게 가져다 주세요."},progress={{75,1506980135},"꼬마야, 왜 나한테 종이를 가져오는 거니? 내가 네 선생님으로 보이니?"},completion={{303,595338146},"<네르트가 쪽지를 살펴본다.>$B$B음... 좋은 징조는 아닌 것 같군. 하지만 지난번 일행이 겁먹고 도망갔다고 해서 여기까지 올 순 없지. 빈손으로 사장님께 돌아갈 순 없잖아?$B$B<네르트는 걱정스러운 표정으로 손을 흔들며 당신을 배웅한다. 아마도 당신보다는 스스로에게 모든 게 괜찮다고 확신시키려는 듯하다.>"}}
rows[80106]={title={{19,596238585},"투덜거리는 숲"},description={{547,2094030268},"좋아, 잘 들어. 보물 사냥꾼은 가끔 유령이 나오는 숲을 발견할 수도 있어. 알겠지? 그리고 우리는 빈손으로 보스에게 돌아갈 순 없어. 절대 안 돼. 만약 빈손으로 돌아가면 우리를$B$B 광산으로 보내버릴 거야. 그래서 우리가 할 일은 이거야. 전리품을 챙겨서 여기서 빨리 빠져나가는 거지. 자네는 지금까지 잘해줬으니까 이번 임무도 맡길게.$B$B 저 계곡 안쪽에 지난번 일당의 메카들이 더 있는 것 같고, 어... 좀 이상해 보이는 독수리들도 있어. 놈들을 처리하고 나면 안에 뭐가 있는지 보자."},objectives={{74,2035077253},"투덜거리는 숲에서 움직이는 파쇄기 5마리와 중얼거리는 독수리 5마리를 처치하세요."},progress={{79,1440053788},"나도 너만큼이나 저 옷들이 마음에 들지 않아, 꼬마야. 하지만 우리에겐 다른 선택지가 없잖아?"},completion={{85,760619682},"여기는 왠지 으스스해. 여기서 빨리 나가면 좋겠지, 그렇지 얘야?"}}
rows[80107]={title={{21,250155014},"고원 위의 그림자"},description={{845,2034555847},"지금 네 상황이 안 좋군, 꼬마야. 봐, 저 이상한 독수리들이 숲에서 제일 끔찍한 건 아니야. 다른 덩치 큰 녀석들이 주변을 둘러보다가 울다만에서 온 것 같은 오래된 무덤을 하나 발견했더군. 가까이 $B$B가려고 했는데 안에서 이상한 소리가 들렸다고 하더군. 이 녀석들은 예전에 보스의 \"설득\" 인터뷰에도 몇 번이나 참석했었는데, 그런 소리는 처음 들어봤다고 하네. 마치 있지도 않은 나무에 부딪혀 메아리치는 것처럼 언덕에 울려 퍼졌다고 하더군. 난 엘프랑 싸울 수도 있고, 식물 $B$B괴물이랑 싸울 수도 있고, 우리 편 탱커들이랑 싸울 수도 있어! 하지만 저 고대의 저주받은 무덤은 건드릴 수 없어. 자네가 저 아래로 내려가서 문 뒤에 뭐가 있는지 알아내고 처리해 주게. 그렇게 해 주면 우린 평생 친구가 될 수 있을 거야. 앞으로 승진할 기회도 있을지도 모릅니다."},objectives={{76,1298521133},"투덜거리는 숲에 있는 무덤을 조사한 다음 네르트 블래스텐톰에게 돌아가십시오."},progress={{39,982119162},"이곳은 왠지 모르게 소름이 끼쳐요."},completion={{144,1068130803},"앞으로 이런 일이 또 생길 거라고? 아니, 절대 안 돼. 사장님이 뭐라고 하시든 상관없어. 화난 귀신한테 저주받고 싶진 않아. 여기서 나가야 해, 꼬마야."}}
rows[80108]={title={{22,1729383879},"나는 오크가 아니다"},description={"We're in a tough spot. The boss is scary, but he ain't worth fighting hordes of ghosts or some ancient curse. When he finds out we bailed on this gig, he'll have us hunted to the ends of Azeroth.$B$BAs much as it pains me to say, we're gonna have to cower and hide behind some real muscle if we don't all want to end up six feet under.$B$BThere's only one force in Azeroth that even the boss wouldn't cross: The Horde. Sure, they don't like us, but we've got better odds with the Horde than with the boss!$B$BWe ain't got many choices. No one else would take a bunch of deadbeat Venture Co. refugees. If there's even a chance we can win them over, we've at least gotta try.$B$BIt's that or spend the rest of our lives on the run. Time for us to go straight, $N.","우린 곤란한 상황에 처했어. 보스는 무섭지만, 유령 떼나 고대의 저주와 싸울 가치는 없어. 우리가 이 일을 포기했다는 걸 알게 되면, 아제로스의 끝까지 우리를 쫓아다닐 거야. 정말 $B$B안타깝지만, 우리 모두 땅속에 묻히고 싶지 않다면 진짜 힘센 놈들 뒤에 숨어야 할 것 같아. 아제로스에서 보스조차도 감히 거스르지 못하는$B$B 세력은 딱 하나 있어. 바로 호드지. 물론 그들도 우리를 좋아하지는 않지만, 보스와 싸우는 것보다는 호드와 싸우는 게 훨씬 나을 거야! 선택의 여지가 많지 $B$B않아. 투자개발회사에서 쫓겨난 한 무능한 놈들을 누가 받아주겠어. 조금이라도 호드의 마음을 얻을 가능성이 있다면, 최소한 시도는 해봐야지. 그렇지 않으면 $B$B평생 도망자 신세로 살아야 할 거야. 이제 제대로 된 삶을 살아야 할 때야, $NN."},objectives={{61,469832398},"네르트 블래스텐톰과 함께 듀로타로 가서 호드에 합류하세요."},progress={{109,860669917},"좋아, 드디어 듀로타에 도착했어.$B$B1단계 완료. 이제 내가 방금 생각해낸 마스터 플랜의 2단계로 넘어가자."},completion={{105,1634073655},"좋아, 듀로타에 도착했어. 1단계 완료.$B$B이제 내 거창한 계획의 2단계로 넘어가자... 방금 지어낸 계획이지만 말이야."}}
rows[80109]={title={{20,498119713},"주크주그 아니면 뭐 그런 거"},description={{591,667318476},"우리 상황이 좋지 않아. 호드가 도와주지 않으면 어디로 가야 할지 모르겠어. 하지만 계획이 하나 있어, 알겠지? 내 오랜$B$B 친구가 저 감시탑 바로 아래에 있는 오크 마을, 레이저 힐에서 요리사로 일하고 있어. 토르카랑 나는 가끔 편지를 주고받는데, 그 친구는 자기 요리 솜씨를 자랑하는 데 거리낌이 $B$B없거든. 심지어 자기네 멧돼지 갈비는 거기 사령관도 무릎 꿇게 할 수 있다고까지 했어. 우린 그걸 노리고 있어. $B$B멧돼지를 좀 사냥해서 고기를 토르카에게 가져다 줘. 토르카가 요리해 주고 우리에 대해 좋은 말 한마디 해 줄 거야, 알겠지? 고블린이라면 누구나 좋은 말 한마디가 사람을 정상까지 올려준다는 걸 알 거야!"},objectives={{73,1498024198},"멧돼지 고기 5덩어리를 모아서 레이저 힐에 있는 요리사 토르카에게 가져다 주세요."},progress={{68,1705496678},"안녕, 고블린. 우리가 기다리고 있는 라쳇의 행렬에 네가 함께 있는 건가?"},completion={{139,676098045},"이게 뭐지? 멧돼지 고기인가? 물자를 전달하는 게 아니라 마치 제물처럼 이걸 내게 바치는 건가...$B$B네르트가 보냈다고? 네르트 블래스텐톰?"}}
rows[80110]={title={{14,1823931505},"녹색이 빨간색으로 변"},description={{547,2077425305},"네르트는 좋은 친구이고, 직업 선택은 좀 그렇지만, 나쁜 사람이라고는 생각하지 않아. 하지만 가르톡을 설득해서 너희 모두를 호드에 영입하는 건… 정말 어려운 일이지! 가르톡이 내$B$B 멧돼지 갈비를 좋아할지는 몰라도, 투자개발회사 출신들을 밥 한 끼 대가로 영입할 만큼 어리석지는 않을 거라고 생각해. 내가 적어도 이 갈비는 $B$B요리해 줄게. 이 계획을 꼭 실행하고 싶다면, 내 충고를 들어. 가르톡에게 너희들이 기꺼이 복종할 난민이라고 말해. 투자개발회사 이야기는 절대 꺼내지 마. $B$B네르트에게 안부 전해줘."},objectives={{94,1670063372},"토르카의 멧돼지 바비큐 갈비를 레이저 힐에 있는 가르톡에게 가져다주고 호드에 가입할 수 있도록 도와달라고 요청하세요."},progress={{219,1882366787},"당신은 라쳇에 나오는 카라반처럼 생기지 않았군요. 레이저 힐에 무슨 용무로 오셨습니까?$B$B<가르톡은 코를 킁킁거리며 침을 흘리기 시작한다.>$B$B토르카가 요리하는 냄새가 나는데? 그의 멧돼지 갈비를 먹을 수 있다면 얼마나 좋을까..."},completion={{497,1917840004},"당신과 당신의 고블린 난민 동료들을 대신해서 드리는 선물이라고요? 호드에 합류하고 싶다고요?! 잘 들어보시오, 고블린…$B$B<당신은 먹음직스럽게 멧돼지 갈비를 건네고, 잠시 망설이던 가르톡은 허겁지겁 갈비를 받아들였다. 그는 맛있게 음식을 게걸스럽게 먹어 치우며 주변을 어지럽혔지만 만족스러운 표정을 지었다.>$B$B고블린이 음식을 공짜로 주다니. 흠, 내가 뭘 할 수 있을지 한번 알아보지… 우선, 형식적인 절차부터.$B$B대족장의 군대에서 명예롭게 싸울 준비가 되었소? 미지의 땅에서 그의 칼과 방패가 될 준비가 되었소?"}}
rows[80115]={title={{21,982997631},"기름때 묻은 편지"},description={"Hey, $N! Employee of the day! How's about an unpaid break?$B$BWhile you were busy doing my... I mean YOUR job, Grizzie the Enforcer came around looking for you. Said something about him owing you a favor?$B$BHere, he mentions it in this letter... which I may or may not have dropped into my buzzard wings.$B$BDon't take too long, though. Your break is already half over!","이봐,$N ! 오늘의 직원! 무급 휴식 어때?네가 내$B$B 일을… 아니, 네 일을 하느라 바쁜 동안, 집행관 그리지가 널 찾으러 왔었어. 그가 너에게 신세를 졌다고 했던 것 같은데?$B$B여기, 그가 편지에 언급해 놨어… 내가 독수리 날개 주머니에 넣었을지도 몰라.하지만 $B$B너무 오래 쉬지 마. 휴식 시간이 벌써 반이나 지났어!"},objectives={{65,506727170},"기름때 묻은 편지를 읽고 집행관 그리지에게 말을 걸어보세요."},progress={"$N, pal, great to see ya. Let's have a quick chat.","$N, 친구, 만나서 반가워. 잠깐 얘기 좀 하자."},completion={"If it isn't my old buddy, $N! Man, we've made some good memories together, yeah?$B$BI ain't giving out no discounts, though. You know how it is.","내 오랜 친구$N이 아니냐! 우리 같이 좋은 추억 많이 만들었지, 그렇지?$B$B하지만 할인은 안 해줄 거야. 무슨 말인지 알잖아."}}
rows[80116]={title={{19,588762388},"진물로 뒤덮인 편지"},description={"Glad you're back, $N. You know I love me some gossip, and I bet you do, too. Maybe you'd care to shed a little light on why your name is on the lips of such bad news?$B$BI hear you owe Leyti Quicktongue some money. Did you gamble all of your savings back home or what?$B$BIs she your loan shark? Do I have to pay for your health insurance? That's not gonna happen, pal.$B$BLook, just take this letter she left for you. I don't want to hold this thing anymore, especially with that nasty looking green stuff dripping off the corner. Probably acid or poison or something.$B$BShort break, and I mean short!",", 돌아와서 $N반가워. 너도 알다시피 난 가십을 좋아하는데, 너도 그럴 거라고 생각해. 네 이름이 왜 이렇게 안 좋은 소문에 휩싸였는지 좀 알려줄래?  네가$B$B 레이티 퀵텅에게 돈을 빚졌다는 소문을 들었어. 고향에서 저축한 돈을 다 도박에 탕진한 거야?$B$B  그녀가 네게 사채를 줬어? 내가 네 건강 보험료까지 내줘야 하는 거야? 절대 안 돼, $B$B친구.  저기, 그녀가 남긴 이 편지 좀 받아 줘. 더 이상 들고 있기 싫어. 특히 모서리에 끈적끈적한 초록색 액체가 뚝뚝 떨어지고 있어서. 아마 산성 물질이나 독극물 같은 거겠지.  $B$B잠깐 쉬는 거야, 정말 잠깐!"},objectives={{60,52340881},"점액으로 뒤덮인 편지를 읽고 레이티 퀵텅과 대화하세요."},progress={"If it ain't $N. You thieving scoundrel.$B$BWhat do you mean it was your gig?","$N이 아니잖아. 이 도둑놈아.$B$B네 일이었다니 무슨 소리야?"},completion={{218,955423820},"그래서, 피치, 내 돈 있어? 없어? 없다고?!$B$B쯧, 여전히 하급 도둑이군. 그렇다면 내가 요령을 가르쳐 줄 수도 있겠지.$B$B내가 널 좋아하는 건 아니지만... 그래도 갚아야지!"}}
rows[80117]={title={{22,886586722},"가죽으로 덮인 편지"},description={"Back for more work, $N? I appreciate your dedication to all this scut work, but Mayten Boomrifle is looking for you. Gave me this letter for you and everything, said something about teaching you some proper shootin'!$B$BHeh, like you need some so-called expert to teach you how to launch metal projectiles or harness explosions. We're goblins!$B$BWhatever... Here, take this letter and go pay him a visit. Hurry it up. No stalling, or no meals for you today!","또 일하러 왔나,$N ? 이런 허드렛일 다 해주는 데 고맙긴 한데, 메이튼 붐라이플이 널 찾고 있어. 네 편지를 전해줬는데, 제대로 쏘는 법도 가르쳐주겠다고 하더군!흥, 금속 $B$B투사체 쏘는 법이나 폭발 다루는 법을 전문가한테 배울 필요가 있겠어? 우린 고블린이라고!어쨌든..$B$B. 자, 이 편지 받아들고 가서 그를 찾아가. 빨리 가. 꾸물거리면 오늘 밥은 없을 거야!"},objectives={{62,482369839},"가죽으로 덮인 편지를 읽고 메이튼 붐라이플과 대화하십시오."},progress={"Shhhh, $N. Not so loud. I'm trying to take that buzzard out of the sky.","쉿,$N. 너무 크게 말하지 마. 저 독수리를 하늘에서 떨어뜨리려고 하는 중이야."},completion={"You got my letter, $N?$B$BGood, good. Let's do something about your shoddy aim. Before you know it, you'll be putting holes in gold pieces from a hundred yards away.$B$BWhat? No, no, no! It was a figure of speech! Don't go wasting perfectly good coin.","$N, 내 편지 받았어?$B,$B좋아, 좋아. 네 형편없는 사격 실력을 좀 고쳐보자. 그러다 보면 곧 100야드 거리에서 금화에 구멍을 낼 수 있게 될 거야.$B,$B뭐라고? 아니, 아니, 아니! 비유적인 표현이었어! 멀쩡한 동전을 낭비하지 마."}}
rows[80118]={title={{12,2102495269},"화려한 편지"},description={"Great work so far, $N. I knew having a mage in our labor force would come in handy. Speaking of handy, how's about conjuring up some water for your poor parched foreman?$B$BWhat? You don't know how to conjure water yet? You kidding me?$B$BLucky for you, ol' Nert's got a letter for you from someone who can help. Wizette Icewhistle's looking for you, so maybe she can teach you some spells.$B$BGet moving, and don't come back without some sparkling water!","지금까지 정말 $N잘했어, . 우리 노동력에 마법사가 있는 게 얼마나 유용한지 알고 있었지. 유용한 얘기가 나왔으니 말인데, 목이 마른 네 불쌍한 반장님을 $B$B위해 물 좀 만들어 줄래?뭐? 아직 물 마법을 못 쓴다고?$B$B 농담이지?다행히도, 네르트가 도와줄 수 있는 사람에게서 온 편지를 받았어. 위젯 아이스휘슬이 널 찾고 있거든. 아마 그녀가 마법을 좀 가르쳐$B$B 줄 수 있을 거야.어서 가서 탄산수 좀 가져오고 와!"},objectives={{54,1744881098},"멋진 편지를 읽고 위제트 아이스휘슬과 이야기하세요."},progress={"I been looking for you, $N! I got a new spell I'd like to try out, and I need an assistant.","$N, 당신을 찾고 있었어요! 새로 만든 마법을 시험해 보고 싶은데, 조수가 필요하거든요."},completion={{91,631600891},"안녕, 얘야! 만나서 반가워. 마마 위즈가 너에게 반짝이는 마법 주문들을 가르쳐줄 준비됐니?"}}
rows[80119]={title={{20,829138902},"끔찍하게 생긴 편지"},description={"$N, pal! Back so soon? W-we're pals, right? Heh heh...$B$BBeing honest, you kinda give me the creeps, not unlike Amri Demondeal. She came looking for you, and boy I hope I never have to speak to her again.$B$BYou, uh, do all that freaky demon stuff, too? With the green fire and blood circles and such?$B$BLook, I didn't see nothin'! J-just take this letter Amri left and go do your business. Take as long as you want!","$N, 친구! 벌써 돌아왔어? 우, 우, 우 친구잖아,$B$B 그렇지? 헤헤... 솔직히 말해서, 넌 좀 소름 끼쳐. 암리 데몬딜이랑 비슷해. 걔가 널 찾으러 왔는데, 다시는 걔랑 얘기하고 싶지 $B$B않아. 너, 어, 그 이상한 악마 짓도 하는 거야? 초록색 불꽃이랑 핏빛 원 같은 거 $B$B말이야? , 난 아무것도 못 봤어! 그냥 암리가 남긴 이 편지 가져가서 볼일 봐. 얼마나 걸리든 상관없어!"},objectives={{58,395268462},"끔찍하게 생긴 편지를 읽고 암리 데몬딜과 이야기하세요."},progress={"$N! Welcome, welcome. The dark arts await, friend.","$N! 어서 오십시오, 어서 오십시오. 어둠의 마법이 당신을 기다립니다, 친구여."},completion={{48,1403843581},"오, 딱 맞춰 왔네! 그림자를 받아들일 준비 됐어?"}}
rows[80120]={title={{11,1329096580},"쓰레기 수거부"},description={{288,1844928212},"이봐, 너! 그래, 너 말이야! $B$B하루 종일 우리 팀 쓰레기를 줍느라 정말 쉴 시간이 필요해. 저기,$B$B 네가 잠깐 청소 좀 하는 게 어때?$B$B 난 여기 그늘에서 잠깐 눈 좀 쉴게. 내가 일어날 땐 여기가 깨끗해야 하거든. 자,$B$B 어서 일해!"},objectives={{76,1226856194},"카즈닉 씨가 공사 현장 곳곳에 버려진 쓰레기를 수거해 달라고 부탁했습니다."},progress={{24,181437565},"어머, 벌써 돌아오셨군요?"},completion={{51,165936289},"잘했어!$B$B사장님께 내가 쉬는 동안 있었다는 건 비밀로 해 줘."}}
rows[80121]={title={{22,1569258073},"[사용 중단됨] 이것은 내 계약서에 명시되어 있습니다."},description={{653,1093615201},"네르트는 그림자 마법을 조금 무서워할지도 모르지만, 너와 나는 우리가 뭘 하는지 잘 $B$B알잖아, 그렇지? 자, 이제 네가 첫 번째 악마를 소환하는 법을 배울 시간이야! 그래, 지금 우리가 위기 상황에 처해 있는 건 알지만, 악마의 도움을 $B$B받는 것보다 더 좋은 때가 어디 있겠어? 게다가 우린 마법사잖아. 위기는 우리 특기라고! 그리고 난 계약상 네게 $B$B\"집행\"을 위한 무기를 줘야 할 의무가 있어. 네가 네르트의 심부름을 하는 동안, 어둠을 내뿜는 무언가를 찾아와. 그 에너지가 응축되어 이런 보라색 수정이 되는 거야, 보이지? 죽지 않고 저 수정 하나를 $B$B집어봐. 저 수정 하나를 가져오면 임프를 소환하는 법을 가르쳐 줄게. 공정한 거래지, 그렇지?"},objectives={{75,2084728245},"투덜거리는 숲의 생물 중 하나에게서 울부짖는 수정을 얻으세요."},progress={{87,708912867},"내 말이 명확하지 않았나요? 소환 마법을 걸려면 그림자 마법이 가득 담긴 수정이 필요해요."},completion={{147,276512751},"아름답군! 이 정도면 충분해.$B$B자, 잘 보고 배워라, 꼬마야. 악마를 공허에서 처음으로 강제로 끄집어내는 건 인생에서 단 한 번뿐이니까."}}
rows[80200]={title={{16,2107864314},"[사용 중단됨] 원정순찰대 산장"},description={"At last, $N, you are awake. It would seem that we survived the perilous journey south from the remnants of Lordaeron. We will have to make the best of our situation and work to make this our new home.$B$BThere is much to be done if we are to make this more than a temporary settlement for our people, $N. This lodge has only had to accommodate a handful of hunters and hasn't seen much traffic since the Second War, thus why its maintenance is questionable at best.$B$BVyrin Swiftwind resides in the lodge and has held station here much longer than any of us. If we are to make a home for ourselves here, then we should seek her counsel and ask where to focus our efforts.","드디어 $N깨어났군, . 로데론의 잔해에서 남쪽으로 향하는 위험한 여정에서 무사히 살아남은 것 같군. 우리는 주어진 상황을 최대한 활용하여 이곳을 우리의 새로운 보금자리로 만들어야 할$B$B 것이다. 이곳을 우리 부족을 위한 임시 정착지 이상으로 만들려면 할 일이 산더미 같군,$N . 이 오두막은 지금까지 소수의 사냥꾼들만 수용해 왔고, 제2차 전쟁 이후로는 거의 드나들지 않았으니, 관리 상태가 엉망인 것은 분명해. 비린 $B$B스위프트윈드가 이 오두막에 살고 있는데, 우리보다 훨씬 오래전부터 이곳에 머물렀지. 우리가 이곳에 정착하려면 그녀의 조언을 구하고, 어디에 노력을 집중해야 할지 물어보는 것이 좋을 거야."},objectives={{48,253539467},"파스트라이더 롯지에 있는 바이린 스위프트윈드에게 말을 걸어보세요."},completion={"You wish to assist?$B$BWell, your offer is welcome, $c. I have been the lone ranger at this lodge for years, so you can imagine my shock at seeing so many of my kind arriving with news that my homeland has fallen. Now, I have to contend with a hundred refugees.$B$BWe have much work to do, friend, but the burden will be lessened with the refugees assisting. We Quel'dorei must stand united now more than ever; we only have each other now.","도와주시겠습니까?$B$B좋습니다,$c. 저는 수년 동안 이 은신처에서 홀로 지내왔습니다. 그래서 고향이 함락되었다는 소식을 전하며 이렇게 많은 동족들이 도착하는 것을 보고 얼마나 충격을 받았는지 짐작하실 수 있을 겁니다. 이제 저는 백 명이 넘는 난민들을 돌봐야 합니다.$B$B친구여, 할 일이 많습니다. 하지만 난민들이 도와준다면 부담이 줄어들 것입니다. 우리 퀘르도레이는 지금 그 어느 때보다 단결해야 합니다. 이제 우리에게 남은 것은 서로뿐입니다."}}
rows[80201]={title={{19,635820393},"땔감 비축하기"},description={"Wagons full of refugees have arrived from the north, and more are surely on the way.$B$BBecause this was used as a dwarven hunting lodge, the larders are fully stocked with meat. Unfortunately, most of the meat was in the process of being salted and the lodge does not have ample firewood. Some of the refugees have already begun chopping wood for the lumber supply.$B$BGo out and collect some of the bundles of wood they've prepared. You'll find them near the trees growing around the lodge, but be careful not to venture too far out into the valley: The creatures of Loch Modan are too dangerous for a young $c such as yourself.","북쪽에서 난민들을 가득 태운 마차들이 도착했고, 더 많은 난민들이 곧 $B$B도착할 것이다. 이곳은 드워프들의 사냥 오두막으로 사용되었기 때문에 식량 창고에는 고기가 가득 차 있다. 하지만 대부분의 고기는 소금에 절이는 중이었고, 오두막에는 장작이 충분하지 않다. 난민들 중 일부는 이미 장작을 패기 시작했다. 나가서 $B$B그들이 준비해 둔 장작 묶음을 좀 가져오너라. 오두막 주변에 자라는 나무들 근처에서 찾을 수 있을 것이다. 하지만 계곡 깊숙이 너무 멀리 나가지 않도록 조심해라. 로크 모단의 괴물들은 너 같은 어린아이에게는$c 너무 위험하다."},objectives={{58,1068632868},"파스트라이더 롯지 밖에서 나무 묶음 8개를 모으세요."},progress={"Do you have the wood, $N?","$N님, 나무 있으세요?"},completion={"Thank you, $N. With this, we should have more than enough wood to keep our people warm and bellies full.","감사합니다,$N님. 이 덕분에 우리 병사들이 따뜻하게 지내고 배를 채울 수 있을 만큼 충분한 나무를 확보했습니다."}}
rows[80203]={title={{19,1554971525},"해충 박멸"},description={"Excuse me, $R, can I have your attention for a moment?$B$BI am Kathy Wake. I am a part of a branch of the Alliance military responsible for ensuring the safety and prosperity of Alliance lands. We've recently been sent here with a large contingent of men. Although I personally believe we are needed more back home, it is not my place to question orders.$B$BOur mission has been to ensure your people arrived safely to the lodge, and also to get you settled in. However, it is not easy to keep everyone safe from the dangers out here. While my men have been dealing with the larger problematic elements in the region, smaller ones have been left unattended for too long, and now they have been allowed to run rampant.$B$BThe refugee caravans could be in danger if something is not done quickly. I take it you can fight? If so, please go out there and take care of the troggs that have been infesting the area around the lodge!","실례합니다,$R 님, 잠시 주목해 주시겠습니까?$B$B 저는 캐시 웨이크입니다. 저는 얼라이언스 영토의 안전과 번영을 책임지는 얼라이언스 군대의 한 부서 소속입니다. 최근 많은 병력과 함께 이곳에 파견되었습니다. 개인적으로는 본국에 더 필요한 존재라고 생각하지만, 명령에 이의를 제기하는 것은$B$B 제 소관이 아닙니다.저희의 임무는 여러분의 일행이 안전하게 숙소에 도착하도록 돕고 정착을 지원하는 것입니다. 하지만 이곳의 위험으로부터 모두를 안전하게 지키는 것은 쉽지 않습니다. 저희 부대가 이 지역의 큰 문제들을 처리하는 동안, 작은 문제들은 너무 오랫동안 방치되어 이제는 날뛰고 $B$B있습니다.신입 난민 행렬이 위험에 처할 수 있으니 신속하게 조치를 취해야 합니다. 전투에 능숙하시죠? 그렇다면 나가서 숙소 주변을 들끓게 하는 트로그들을 처리해 주십시오!"},objectives={{20,798684812},"트로그 버민 8마리를 처치하세요."},progress={"Well, $R, has the deed been done?","자,$R님, 일이 마무리되었나요?"},completion={"Well done, $N. This is only the beginning, but removing those vermin will ensure the refugees remain safe for now.$B$BWe have more work to do, though. The more assistance we get from you, the more help we can provide your people.","$N님, 정말 잘하셨습니다. 이것은 시작에 불과하지만, 해충들을 제거함으로써 난민들이 당분간 안전하게 지낼 수 있을 것입니다.$B$B하지만 아직 할 일이 더 많습니다. 여러분의 도움이 많을수록 저희는 여러분의 국민들에게 더 많은 도움을 제공할 수 있습니다."}}
rows[80204]={title={{15,2012012503},"정보 수집"},description={{845,124764687},"이제 경험이 좀 쌓였으니 다행이군. 네가 $B$B물리친 쥐새끼들은 이 계곡에 도사리고 있는 다른 존재들에 비하면 그저 성가신 존재일 뿐이야. 어젯밤에 도착한 난민들 중 일부는 숲 속에서 붉은 눈을 가진 키 작은 형체가 주변을 배회하는 것을 봤다고 하더군. 어떤$B$B 이들은 긴 여정의 피로 때문이라고 치부했지만, 내 생각엔 섀도우포지 습격대의 정찰병일지도 몰라. 섀도우포지는$B$B 검은무쇠 부족 중 하나야. 그들은 타락한 붉은 눈의 드워프들로, 아이언포지 왕국과 적대 관계에 있지. 목격자가 나타난 서쪽 지역을 조사해 보되, 발굴 현장에는 너무 가까이 가지 마. 그곳에는 네가 아까 싸웠던 쥐새끼들보다 훨씬 강한 트로그들이 우글거리고 있어. $B$B명심해: 절대 교전하지 마. 뭔가 발견하면 목격 사실을 확인하고 즉시 여기로 돌아와."},objectives={{62,484405642},"파스트라이더 로지 남서쪽 지역을 조사하십시오."},progress={{39,284536849},"섀도우포지 정찰병을 발견하셨나요?"},completion={"A whole armed camp? Damn, this is a problem. We'll need to devote resources into dealing with it that we don't have. Thank you for your help, $N! We may call upon you again once we figure out how to handle this.","무장한 캠프라니? 맙소사, 큰일 났군. 우리가 가진 자원보다 더 많은 자원을 투입해야 할 것 같아. 도와줘서 고마워,$N! 이 문제를 어떻게 해결해야 할지 알게 되면 다시 도움을 요청할지도 몰라."}}
rows[80205]={title={{20,1750440089},"갈증 해소"},description={"Hello again, $N.$B$BThe wood you gathered helped feed many refugees. However, the situation is far from resolved.$B$BThe drinking water stores are running low. Soon, we will not be able to care for the refugees, but luckily there is a well to the north near the border of this valley. Go there, and fill this barrel with water.$B$BThere are volunteers trying to dig a new well here, but that will take time.$B$BPlease, $N, I know I can count on you!","안녕하세요, $N$B$B님. 당신이 모아주신 나무 덕분에 많은 난민들이 식량을 구할 수 있었습니다. 하지만 상황은 $B$B아직 완전히 해결된 것은 아닙니다. 식수도 부족해지고 있습니다. 곧 난민들을 돌볼 수 없게 될 것 같습니다. 다행히 이 계곡 경계 근처 북쪽에 우물이 하나 있습니다. 그곳에 가서 이 통에 물을 채워주세요. $B$B자원봉사자들이 이곳에 새 우물을 파려고 노력하고 있지만 시간이 걸릴 겁니다. 제발,$B$B 님,$N 저는 당신을 믿고 있습니다!"},objectives={{47,1244584407},"빈 통에 우물물을 채우세요."},progress={{41,1489771434},"알아들었어? 아이들이 목말라."},completion={"You got the water?$B$BThank you, $N. At least that's one less problem we have to deal with.$B$BThe children will have water, and the progress on the well is going wonderfully!","물 확보됐어?$B$B고마워,$N. 적어도 문제가 하나 줄었네.$B$B아이들도 물 마실 수 있겠어. 우물 공사도 순조롭게 진행되고 있어!"}}
rows[80206]={title={{12,309823180},"번트 휠즈"},description={"<Vyrin appears distressed as she looks in your direction.>$B$BWe found a wagon burned down with the corpses of the accompanying escorts nearby and no sign of the refugees. It's... terrible, $N, it's absolutely terrible!$B$BPlease speak to your companion, Malvinah, was it? I am trying to keep people calm as we figure this out, but she is very disturbed. She's spreading panic and confusion among the refugees.","<바이린이 당신 쪽을 바라보며 괴로워하는 표정을 짓습니다.$B$B>불에 탄 마차와 그 근처에서 호위병들의 시신을 발견했어요. 난민들은 어디에도 없어요. 정말… 끔찍해요, , 정말 $N끔찍해요!동료, 말비나였죠?$B$B 그녀와 이야기 좀 해 주세요. 저는 사람들을 진정시키면서 이 상황을 파악하려고 애쓰고 있는데, 그녀가 너무 불안해하고 있어요. 난민들 사이에 공포와 혼란을 퍼뜨리고 있어요."},objectives={{59,436024364},"말비나 선블레이드와 대화한 후 캐시 웨이크에게 보고하세요."},progress={"What is it, $N? Now is not the time.","그게 뭐죠,$N인가요? 지금은 때가 아니에요."},completion={"So, you know about it, then? My scouts have confirmed it.$B$BIt's that damned Shadowforge raiding party you found. We should have struck right away, but instead I wanted to prepare... damn it!$B$BIt's as if they knew we were onto them. You didn't attack any of them, did you?$B$BWell, no matter. There is no time for regret. It is time to act!$B$BThe refugees have been put in cages, and the Dark Irons are preparing to ritually sacrifice them to their god, the Firelord Ragnaros.$B$BWe can't allow it, $N! I'm going to need your help with this!","그래서, 알고 있었군? 내 정찰병들이 확인해 줬어.$B$B네가 찾아낸 그 빌어먹을 섀도우포지 습격대 때문이군. 당장 공격했어야 했는데, 대신 준비하고 싶었어… 젠장!$B$B마치 우리가 그들을 추적하고 있다는 걸 알고 있었던 것 같군. 자네는 그들을 공격하지 않았지, 그렇지?$B$B뭐, 상관없어. 후회할 시간은 없어. 지금 당장 행동해야 해!$B$B피난민들은 우리에 갇혔고, 다크 아이언 부족은 그들을 불의 군주 라그나로스에게 제물로 바치려고 하고 있어.$B$B절대 안 돼,$N! 자네의 도움이 필요해!"}}
rows[80207]={title={{19,1158729962},"검은무쇠 스크랩핑"},description={"Alright, $N, here is the plan. We have established a perimeter around the Dark Iron camp, but we believe that if we move in force, then they will execute the refugees. We have been ordered to stand down.$B$BHowever, if we do not act now, the refugees will be killed. We need an outsider to sneak into their camp, kill the fire cleric, acquire the key to the cells, and free the refugees.$B$BI can think of no one more worthy of this task than you. You have proven yourself to be strong and resourceful in the short time we've known each other.$B$BI believe in you, $N! Now go and save those people!","좋아, ,$N 계획은 이렇다. 우리는 검은무쇠 진영 주변에 경계선을 설정했지만, 만약 우리가 직접 진격한다면 그들이 난민들을 처형할 거라고 생각한다. 우리는 철수 명령을 받았지만, 지금 $B$B당장 행동하지 않으면 난민들은 죽임을 당할 것이다. 외부인이 그들의 진영에 잠입해서 화염 사제를 처치하고 감옥 열쇠를 얻어 난민들을 구출해야 한다. , 이 임무에 $B$B당신보다 더 적합한 사람은 없다고 생각한다. 우리가 서로 안 지 얼마 안 됐지만 당신은 강인하고 기지가 넘치는 사람이라는 걸 증명해 보였다. ,$B$B 당신을 믿는다!$N 자, 가서 그들을 구해다오!"},objectives={{86,2123226463},"섀도우포지 화염 사제를 처치하고, 어둠의 열쇠를 획득하여 하이 엘프 난민들을 구출하십시오."},progress={"Time is of the essence, $N. Do not delay!","시간이 촉박합니다,$N. 지체하지 마십시오!"},completion={"They are all safe. I can't believe it, we averted a disaster! I can't thank you enough, $N! We take our duty very seriously, and losing those people would have been terrible.$B$BNow, we need to take care of that raiding party. There is someone who wants to speak with you about that. Go see Vyrin.","모두 무사해. 믿을 수가 없어, 큰 사고를 막았어!$N, 정말 고맙다! 우리는 임무를 매우 중요하게 생각하는데, 그 사람들을 잃었다면 정말 끔찍했을 거야.$B$B자, 이제 저 습격대를 처리해야 해. 그 일에 대해 얘기하고 싶어 하는 사람이 있어. 바이린을 찾아가 봐."}}
rows[80208]={title={{16,125581586},"선블레이드 리유니언"},description={"You're the hero of the hour, $N! All the refugees are speaking your name!$B$BI believe there is a friend of yours who is particularly grateful. Why not go and speak with Malvinah Sunblade?",", 당신은 지금 이 순간의 $N영웅이에요! 모든 난민들이 당신의 이름을 부르고 $B$B있어요!I는 당신의 친구 중에 특히 고마워하는 사람이 있다고 들었어요. 말비나 선블레이드에게 가서 이야기해 보는 건 어때요?"},objectives={{27,802276524},"말비나 선블레이드에게 말을 걸어보세요."},progress={{34,245754202},"그 시대의 영웅이 돌아온 건가?"},completion={"You did well, $N. You deserve all the praise you're getting.$B$BIt may not seem like much to save a few refugees, but consider that this is just the start of your journey. You exhibited great courage, too.$B$BI can safely say that I am proud to have met you. However, there is another matter we must talk about.$B$BSeveral of the refugee caravans have decided to move on to Stormwind. We can escort them part of the way there, but eventually they will arrive in a region beset by strife.$B$BBandits and beasts run amok while we are ordered to outlying areas such as this lodge.$B$BWe can't go against our orders, but adventurers like you can make a difference back home.$B$BThink about it and talk to me again.","$N, 정말 잘했어요. 칭찬받아 마땅해요.$B,$B난민 몇 명을 구하는 게 대수롭지 않게 보일지 몰라도, 이건 당신의 여정의 시작일 뿐이에요. 정말 용감했어요.$B,$B당신을 만나게 되어 자랑스럽습니다. 하지만, 이야기해야 할 다른 사안이 있어요.$B,$B난민 행렬 중 일부가 스톰윈드로 이동하기로 했습니다. 우리가 그들을 일부 구간까지는 호위할 수 있지만, 결국 그들은 분쟁에 휩싸인 지역에 도착하게 될 겁니다.$B,$B우리가 이 숙소 같은 외곽 지역으로 파견된 동안 도적과 짐승들이 날뛰고 있어요.$B,$B우리는 명령을 어길 수 없지만, 당신 같은 모험가들이 고향에 큰 변화를 가져올 수 있을 겁니다.$B$B생각해보고 다시 얘기해 줘."}}
rows[80209]={title={{20,871307569},"골드셔로 이동"},description={"You've decided to assist, then? I am grateful, $N!$B$BThe situation back home is dire and we cannot return to help at the moment. I do not know what kind of affliction ails the Stormwind nobles, but ever since King Varian disappeared, the Kingdom has been run into the ground!$B$BAlas, while we can't control the nobles, we can deal with the problems in the kingdom's provinces! Elwynn Forest is a good place to start. The capital is located in this region, and it has been surrounded by issues. Kobolds rule the mines, gnolls raid the towns, and bandits seize the roads.$B$BMy friend Marshal Dugan is stationed in Goldshire, and he can put you to good use. I believe the Magistrix here can teleport you to Goldshire.","도와주기로 결정했군? 고맙다, !고향 상황이$N$B$B 심각해서 지금 당장은 돌아갈 수 없어. 스톰윈드 귀족들이 무슨 문제에 휘말렸는지는 모르겠지만, 바리안 왕이 사라진 이후로 왕국은 완전히 망가졌어!안타깝게도 귀족들은 우리가 통제할 수 없지만,$B$B 왕국의 지방 문제들은 해결할 수 있어! 엘윈 숲이 좋은 시작점이 될 거야. 수도가 이 지역에 있는데, 주변이 온갖 문제에 시달리고 있지. 코볼드들이 광산을 장악하고, 놀들이 마을을 약탈하고, 산적들이 길을 점령하고 있어.내 친구인 두간 원수가 골드샤이어에$B$B 주둔하고 있는데, 그가 자네를 도와줄 수 있을 거야. 여기 있는 마법사가 자네를 골드샤이어로 순간이동시켜 줄 수 있을걸."},objectives={{91,553111366},"마법사 이샬라에게 말을 걸어 골드샤이어로 순간이동한 다음, 보안관 두간에게 보고하십시오."},progress={{49,1613353497},"하이 엘프시군요? 무슨 일로 오셨습니까, 낯선 분?"},completion={{473,1603826429},"캐시 웨이크가 보냈다고요?! SI… 아니, 연합군 소속이 보냈다면 인맥이 꽤 넓으시군요!$B$B도와주러 오셨다면, 저희에게는 도움이 절실히 필요합니다. 수도에 여러 번 지원군을 요청했지만 아무런 응답도 받지 못했습니다.$B$B캐시가 보증을 섰다면, 저는 충분하다고 생각합니다. 첫 번째 임무는 이미 생각해 두었습니다!$B$B아, 그리고 여관에 들르는 것도 잊지 마세요. 거기서 귀환석을 조율해 두는 게 좋을 겁니다."}}
rows[80210]={title={{25,1018629541},"균형 잡힌 식단 제공"},description={"Greetings, $N! You've made amazing progress so far, but there is still so much to do.$B$BWhile the lodge is stocked with an abundance of grain and meat, we're lacking other types of nourishment like fruits and vegetables.$B$BLuckily, the area around the lodge has an abundance of pumpkins and berries this time of the year. Can I count on you to search the area for berries and pumpkins?$B$BOur peoples' welfare depends on it!","안녕, $N! 지금까지 놀라운 진전을 보여주셨지만, 아직 할 일이$B$B 많습니다. 숙소에는 곡물과 고기는 풍족하지만, 과일과 채소 같은 다른 영양분이 부족합니다. $B$B다행히 숙소 주변 지역에는 이맘때쯤이면 호박과 열매가 풍부합니다. 그 지역에서 호박과 열매를 찾아주시겠습니까? 우리 부족의$B$B 안녕이 달려 있습니다!"},objectives={{102,2136458996},"파스트라이더 롯지 주변 지역에서 로크 모단 호박 4개와 로크 모단 열매 8개를 모으세요."},progress={{37,1400719162},"호박이랑 열매는 가져왔어?"},completion={{157,700074928},"훌륭해! 동맹에서 물자를 구할 때까지 한동안은 이걸로 버틸 수 있겠어.$B$B호박 씨앗을 이용해서 우리만의 호박밭을 만들 수도 있겠어."}}
rows[80211]={title={{15,2021681648},"순찰자의 편지"},description={"$N, the fall of our homeland has affected us all. But, even if our education down this path was cut short, there are still ways to learn.$B$BRecently, someone left a letter on the desk and it was addressed to you.$B$BPerhaps you should read it and see what it says?","$N네, 조국의 몰락은 우리 모두에게 영향을 미쳤습니다. 하지만, 비록 이 길을 따라가는 우리의 교육이 중단되었다 하더라도, 배울 길은 여전히 $B$B​​있습니다. 최근에 누군가 책상 위에 편지를 놓고 갔는데, 네게 온 편지였다.$B$B 혹시 읽어보고 무슨 내용인지 알아보는 게 어떨까?"},objectives={{55,2139835368},"레인저의 편지를 읽고 루비나 선스워른과 대화하세요."},progress={{16,1215561900},"네? 무슨 일이죠?"},completion={"So you've chosen to begin your training? I am pleased, $N. Very pleased. Talk to me again and I will do my best to guide you with my knowledge.$B$BIn time, I believe you will grow to become someone all rangers can be proud of calling a comrade!$B$BMy bearded friend, Claude Erksine, can also assist you with beast-related training once you are ready.","훈련을 시작하기로 결정했군요? 아주 기쁩니다,$N. 정말 기쁩니다. 다시 이야기하면 제가 가진 지식을 바탕으로 최선을 다해 지도해 드리겠습니다.$B$B시간이 지나면 당신은 모든 레인저들이 자랑스러워할 만한 동료로 성장할 거라고 믿습니다!$B$B제 수염 난 친구 클로드 에르신도 당신이 준비가 되면 야수 관련 훈련을 도와줄 수 있을 겁니다."}}
rows[80212]={title={{16,1801193941},"팔라딘의 편지"},description={"$N, the fall of our homeland has affected us all. But, even if our education down this path was cut short, there are still ways to learn.$B$BRecently, someone left a letter on the desk and it was addressed to you.$B$BPerhaps you should read it and see what it says?","$N네, 조국의 몰락은 우리 모두에게 영향을 미쳤습니다. 하지만, 비록 이 길을 따라가는 우리의 교육이 중단되었다 하더라도, 배울 길은 여전히 $B$B​​있습니다. 최근에 누군가 책상 위에 편지를 놓고 갔는데, 네게 온 편지였다.$B$B 혹시 읽어보고 무슨 내용인지 알아보는 게 어떨까?"},objectives={{57,314632748},"팔라딘의 편지를 읽고 성스러운 로르타스와 대화하십시오."},progress={{17,1645703771},"빛을 따라가세요."},completion={"Light be with you, $N!$B$BIt honors and brings me endless joy to see you take the first step on the path of becoming a paladin.$B$BKnow that I shall do my utmost to guide you through the tenets and through your training.$B$BTalk to me again whenever you wish to seek my counsel.","빛이 너와 함께하길,$N!$B$B네가 팔라딘이 되는 길에 첫발을 내딛는 모습을 보니 영광스럽고 한없는 기쁨을 느낀다.$B$B내가 최선을 다해 네가 교리를 배우고 훈련을 받을 수 있도록 인도할 것을 약속한다.$B$B언제든 내 조언이 필요할 땐 주저하지 말고 다시 이야기하렴."}}
rows[80213]={title={{15,576170210},"신부의 편지"},description={"$N, the fall of our homeland has affected us all. But, even if our education down this path was cut short, there are still ways to learn.$B$BRecently, someone left a letter on the desk and it was addressed to you.$B$BPerhaps you should read it and see what it says?","$N네, 조국의 몰락은 우리 모두에게 영향을 미쳤습니다. 하지만, 비록 이 길을 따라가는 우리의 교육이 중단되었다 하더라도, 배울 길은 여전히 $B$B​​있습니다. 최근에 누군가 책상 위에 편지를 놓고 갔는데, 네게 온 편지였다.$B$B 혹시 읽어보고 무슨 내용인지 알아보는 게 어떨까?"},objectives={{54,431202939},"사제의 편지를 읽고 마엘라 선스원과 이야기하십시오."},progress={{35,1112278373},"햇살이 당신을 비추기를 바랍니다."},completion={"By the Sun, you've come!$B$BMany of our people have lost their faith in the Light of the Sun as they wander like sheep lost in the dark. Together, we can be the beacon guiding them to salvation and to the warmth of the Sun!$B$BI shall do my best to be your beacon, $N. Ask and I will teach you what I can.","태양이시여, 당신이 오셨군요!$B$B우리 백성 중 많은 이들이 어둠 속에서 길을 잃은 양떼처럼 방황하며 태양의 빛에 대한 믿음을 잃었습니다. 우리 함께 그들을 구원과 태양의 따뜻함으로 인도하는 등불이 되어 줍시다!$B$B제가 최선을 다해 당신의 등불이 되어 드리겠습니다.$N무엇이든 물어보십시오. 제가 아는 것을 가르쳐 드리겠습니다."}}
rows[80214]={title={{17,446637533},"판사의 편지"},description={"$N, the fall of our homeland has affected us all. But, even if our education down this path was cut short, there are still ways to learn.$B$BRecently, someone left a letter on the desk and it was addressed to you.$B$BPerhaps you should read it and see what it says?","$N네, 조국의 몰락은 우리 모두에게 영향을 미쳤습니다. 하지만, 비록 이 길을 따라가는 우리의 교육이 중단되었다 하더라도, 배울 길은 여전히 $B$B​​있습니다. 최근에 누군가 책상 위에 편지를 놓고 갔는데, 네게 온 편지였다.$B$B 혹시 읽어보고 무슨 내용인지 알아보는 게 어떨까?"},objectives={{58,1972720102},"마법사의 편지를 읽고 마법사 알라쇼르와 대화하십시오."},progress={{75,229437760},"마법사협회는 마법사가 소속될 수 있는 가장 명망 있는 단체입니다."},completion={"Ah, $N, I take it you're here to become my apprentice?$B$BIf so, then know that I will not coddle you. You will be serving under a proud member of the Magisterium.$B$BAs such, you will be taught what I deem necessary for your progress. Continue to perform adequately and I shall continue to guide you.$B$BEventually, you will be fit enough for the Magisterium.$B$BTalk to me again once you are prepared.","아,$N, 제 제자가 되려고 오신 모양이군요?$B$B만약 그렇다면, 제가 당신을 과보호하지 않을 것임을 알아두십시오. 당신은 마지스테리움의 자랑스러운 일원인 저의 지도 아래 있게 될 것입니다.$B$B따라서, 저는 당신의 발전에 필요하다고 생각하는 모든 것을 가르칠 것입니다. 꾸준히 성실히 수행한다면, 저는 계속해서 당신을 지도하겠습니다.$B$B결국 당신은 마지스테리움에 들어갈 자격을 갖추게 될 것입니다.$B$B준비가 되면 다시 저에게 말씀하십시오."}}
rows[80215]={title={{12,749023884},"수상한 편지"},description={"$N, the fall of our homeland has affected us all. But, even if our education down this path was cut short, there are still ways to learn.$B$BRecently, someone left a letter on the desk and it was addressed to you.$B$BPerhaps you should read it and see what it says?","$N네, 조국의 몰락은 우리 모두에게 영향을 미쳤습니다. 하지만, 비록 이 길을 따라가는 우리의 교육이 중단되었다 하더라도, 배울 길은 여전히 $B$B​​있습니다. 최근에 누군가 책상 위에 편지를 놓고 갔는데, 네게 온 편지였다.$B$B 혹시 읽어보고 무슨 내용인지 알아보는 게 어떨까?"},objectives={{52,611238277},"수상한 편지를 읽고 그림자 릴라와 대화하세요."},progress={{32,929989406},"그림자 속에 숨어 있으렴, 제자야."},completion={{301,149469161},"그래서, 정말 왔군?$B$B재밌군. 자, 첫 번째 시험은 통과했지만, 이게 마지막이라고 생각하지는 마라.$B$B내 훈련을 받으면 얼마나 잘 해낼지 두고 보자. 준비가 되면 다시 말해 보거라. 그럼 몇 가지 비법을 가르쳐주지. 계속해서 가능성을 보여준다면, 앞으로도 계속 가르쳐줄 테니 기대해도 좋다."}}
rows[80216]={title={{18,2120284734},"검객의 편지"},description={"$N, the fall of our homeland has affected us all. But, even if our education down this path was cut short, there are still ways to learn.$B$BRecently, someone left a letter on the desk and it was addressed to you.$B$BPerhaps you should read it and see what it says?","$N네, 조국의 몰락은 우리 모두에게 영향을 미쳤습니다. 하지만, 비록 이 길을 따라가는 우리의 교육이 중단되었다 하더라도, 배울 길은 여전히 $B$B​​있습니다. 최근에 누군가 책상 위에 편지를 놓고 갔는데, 네게 온 편지였다.$B$B 혹시 읽어보고 무슨 내용인지 알아보는 게 어떨까?"},objectives={{58,1903029981},"검사의 편지를 읽고 발라노스 던파이어와 대화하세요."},progress={{57,23039513},"검을 휘두르는 것은 강력한 만큼이나 위엄 있는 행위입니다."},completion={{366,971274508},"당신의 모습이 제게 희망을 준다고 말씀드리고 싶습니다.$B$B우리 민족 중 검의 길을 택하는 사람은 드뭅니다. 길고 험난한 여정이지만, 제 가르침을 통해 당신이라면 극복할 수 있을 거라고 믿습니다.$B$B레인저나 마법사가 몇 명이나 있든 상관없습니다. 결국 전투에서 승리하려면 최전선에 나설 누군가가 필요합니다.$B$B그 책임을 맡을 준비가 되면 다시 이야기해 주세요."}}
rows[80217]={title={{15,161772911},"[사용 중단됨] 모피와 상아"},description={"To prove yourself to me, $N, I will have you go around the lodge and search for the many piglets and cubs that made their home close to here.$B$BYour kin will also need clothes and armor made from their hides. While I am not the best leatherworker, I could still make a few pieces of gear.$B$BFive pelts of the bear cubs and five chunks of meat from the piglets will be enough to prove your worth.$B$BCome back when you have everything.",", 당신이 제게 능력을 $N증명하려면, 오두막 주변을 돌아다니며 이 근처에 둥지를 튼 새끼 곰들을 찾아와야 합니다. 당신의 가족에게는$B$B 곰 가죽으로 만든 옷과 갑옷도 필요할 겁니다. 제가 최고의 가죽 세공가는 아니지만, 몇 가지 장비는 만들어 드릴 수 있습니다. 새끼$B$B 곰 가죽 다섯 장과 새끼 돼지 고기 다섯 덩어리면 당신의 능력을 증명하기에 충분할 겁니다. $B$B모든 것을 가져오면 다시 오십시오."},objectives={{100,1787137276},"파스트라이더 로지에 있는 마렉 아이언하트에게 어린 곰 가죽 5장과 어린 멧돼지 고기 5조각을 가져다주세요."},progress={"Are you done yet, $N? We need the supplies.","$N번, 작업 다 끝났나요? 물품이 필요해요."},completion={"Ah, yes. While these clearly weren't harvested by an expert, you did a pretty good job. Very well, $N, you've proven to be a capable $R. You know, some might not see them as very dangerous, but indeed they are. Here, some coin for your troubles, and I made you a cape from the remaining pelts.","아, 그래. 전문가가 채취한 건 아니지만, 꽤 잘했어. 아주 훌륭해,$N. 넌 유능한$R임을 증명했군. 어떤 사람들은 얘네들을 별로 위험하지 않다고 생각할지도 모르지만, 사실은 아주 위험해. 자, 수고비로 동전 좀 줄게. 그리고 남은 가죽으로 망토 하나 만들어 줄게."}}
rows[80219]={title={{7,453530319},"쾅!"},progress={{545,1475666722},"고블린에게 늘 필요한 게 있다면 바로 다이너마이트지!$B$B땅을 파거나, 적을 폭파시키거나, 아니면 그냥 쾅! 하는 소리를 구경하는 데 쓰든 말이야!$B$B어쨌든, 중형 다이너마이트 20개만 가져오면 내가 잘 봐주겠어. 질 좋은 다이너마이트로 가져와야 해.$B$B어디서 구하든 상관없지만, 노움 시체에서 주워온 거라면 얘기가 달라. 그럴 땐 소독제로 깨끗이 닦아서 가져와야 해.$B$B노움은 특유의 불쾌한 냄새가 나는데, 솔직히 말해서 난 그 냄새가 역겨워."},completion={"Nice job, $N. I'll be sure to tell the others of your help.","$N님, 수고하셨습니다. 다른 분들께도 도움을 주신 사실을 꼭 알려드리겠습니다."}}
rows[80220]={title={{24,30256234},"스톰윈드의 새로운 장소"},description={"You're a $R right?$B$BYou aren't the first I've seen around here recently. A lot of your people have arrived and have settled up in Stormwind.$B$BIn the outer section of the Dwarven district bordering the canal, there is an entrance with the banner of your people, go there and you can meet them should you wish to greet your own folk.","당신은 $R 가문 $B$B사람 맞죠?최근에 이 근처에서 본 사람이 당신이 처음은 아닙니다. 당신 가문의 많은 사람들이 스톰윈드에$B$B 도착해서 정착했습니다.운하에 접한 드워프 구역 외곽에 당신 가문의 깃발이 걸린 입구가 있습니다. 그곳으로 가시면 원하시면 당신 가문 사람들을 만나실 수 있습니다."},objectives={{147,895152518},"스톰윈드에 있는 하이 엘프 구역을 찾아가세요. 드워프 구역 외곽에 파란색 깃발이 걸려 있을 겁니다. 그곳에서 하이 엘프 대표와 대화하세요."},progress={{27,1644240294},"네? 무엇을 도와드릴까요?"},completion={{564,1525939829},"아, 파스트라이더 로지에서 오셨군요?$B$B우리 부족이 무사히 정착했다니 다행입니다. 저는 퀘르도레이 대표 일리아나 던스타입니다.$B$B귀족회에서 이 거리를 난민들을 위한 임시 거처로 제공해 주었습니다. 물론 당신도 머물 수 있습니다. 숙소가 마련되어 있지만, 영구 거주 건물은 이미 꽉 찼습니다. 여관에서 며칠 동안 묵을 수 있는 침대를 드릴 수 있습니다.$B$B우리 부족의 상황을 영구적으로 개선하기 위한 계획이 진행 중이니 안심하십시오. 아, 이제 장부 정리를 하러 돌아가야겠군요. 조심히 가세요!"}}
rows[80250]={title={{33,1561362409},"[사용 중단됨] 태양의 아이들을 돕기"},description={"Bal'a dash, malanore, $R! I represent a group of my people who seek to restore our former glory.$B$BWe seek to settle a new home for us and your assistance would be more than welcome.$B$BWhen you have the time, journey to Stormwind and speak to Caledra Dawnbreeze in the Stormwind Keep.$B$BTrust that you will be well compensated for your aid!","발라 대시, 말라노르,$R ! 저는 옛 영광을 되찾고자 하는 우리 민족을 대표하여 왔습니다.$B$B저희는 새로운 정착지를 찾고 있으며, 여러분의 도움을 진심으로 환영합니다.$B$B시간이 되시면 스톰윈드로 오셔서 스톰윈드 요새에 있는 칼레드라 던브리즈에게 말씀해 $B$B주십시오.도움에 대한 보상은 반드시 해 드리겠습니다!"},objectives={{46,1079086532},"스톰윈드 요새에 있는 칼레드라 던브리즈에게 말을 걸어보세요."},progress={{37,184713286},"네? 무슨 일로 오셨습니까, 낯선 분?"},completion={{339,1117390583},"아, 저희의 노력을 도와주시려는 거군요?$B$B정말 훌륭합니다…$B$B저희 부족은 스트라솔름 북쪽 해안, 퀘탈라스와 접경 지역에 알라탈라스라는 새로운 정착지를 세웠습니다. 하지만 새로운 보금자리를 마련하는 것은 쉽지 않고 여러 가지 문제에 부딪혔습니다.$B$B당신의 도움은 정말 큰 도움이 될 것입니다! 저희 상황을 간략하게 설명해 드리겠습니다."}}
rows[80251]={title={{15,204808632},"[사용 중단됨] 알라탈라스께!"},description={{388,1088189855},"이제 우리가 어떤 상황에 처해 있는지, 그리고 우리의 역사를 $B$B알게 ​​되었으니… 행동할 때가 왔습니다. 진정으로 우리를 돕고 싶다면, 이것이 바로 그 $B$B길입니다. 우리 중 가장 재능 있는 마법사 중 한 명이 알라탈라스와 마법진 연결을 $B$B만들었습니다. 마법사 지구의 마법사 탑으로 가서 엘샤린과 이야기하십시오. 그녀가 당신을 그곳으로 안내해 줄 것입니다. 도착하면 누군가가 당신을 도와줄 것입니다."},objectives={{85,864595096},"스톰윈드 마법사 탑의 차원문을 지나면 엘샤린을 만날 수 있습니다."},progress={"Oh my! What can I do for you, $R?","어머나!$R님, 무슨 일로 오셨나요?"},completion={"Oh you've come to assist Alah'thalas!$B$BI'm quite happy I must say, I knew Caledra could find nice people! I'm surprised she found a $C as capable as you!$B$BThe loss of Quel'thalas has grieved me greatly, but now I see hope, hope that our people can have a future again!$B$BTalk to me when you are ready and I will send you to Alah'thalas!","오, 알라탈라스를 도우러 오셨군요!$B$B정말 기쁩니다. 칼레드라가 좋은 사람들을 찾아낼 줄 알았죠! 당신처럼 유능한 사람을 찾다니 놀랍습니다!$C$B$B퀘르탈라스의 죽음은 저에게 큰 슬픔을 안겨주었지만, 이제 희망이 보입니다. 우리 민족에게 다시 미래가 찾아올 수 있다는 희망 말입니다!$B$B준비가 되면 저에게 말씀해 주십시오. 그러면 알라탈라스로 보내드리겠습니다!"}}
rows[80252]={title={{20,216824627},"[사용 중단됨] 명확한 작업"},description={"Greetings, $R. Since you're here this means you've come to help so listen up. We have a situation here... You might be aware that our buildings use arcane magic to operate.$B$BWhile our central crystal is the main power source, we use smaller crystals to effectively channel the arcane energy from the nexus to the outlying ley points of the structure.$B$BThe downside is that these crystals break down overtime, if we had found this outpost a decade later the entire Academy could have collapsed.$B$BFortunately, our predecessors built this site on a location with arcane crystal deposits. While the automated constructs have long since stopped working or malfunctioned, the mine remains full of intact crystals.$B$BI need you to head down there and bring me some crystals. Eight should do for now.$B$BAre you still here? Get moving.","안녕하세요,$R . 여기까지 오신 걸 보니 도와주러 오신 거겠죠? 잘 들어주세요. 문제가 생겼습니다… 저희 건물들이 마법을 이용해 운영된다는 걸 알고 계시겠죠?$B$B 중앙의 수정이 주요 에너지원이지만, 작은 수정들을 이용해 중심에서 나오는 마법 에너지를 건물 곳곳의 지맥으로 효율적으로 전달하고 있습니다. 문제는 이 $B$B수정들이 시간이 지남에 따라 부식된다는 겁니다. 만약 저희가 이 전초기지를 10년 후에 발견했다면 아카데미 전체가 붕괴될 수도 $B$B있었을 겁니다. 다행히도 저희 선조들은 마법 수정이 매장된 곳에 이 기지를 건설했습니다. 자동화 시설들은 오래전에 작동을 멈추거나 오작동을 일으켰지만, 광산에는 아직 온전한 수정들이 가득합니다.$B$B 그곳으로 가서 수정을 좀 가져다주세요. 여덟 개면 충분할 겁니다. $B$B아직 계신가요? 어서 가세요."},objectives={{65,1636789654},"알라탈라스에 있는 실버 선 광산에서 마법 수정 8개를 모으세요."},progress={{137,1365117681},"수정은 얻었나요?$B$B무슨 일이 있더라도 상관없어요... 쥐든 뭐든 간에, 이 임무는 끝내놓으세요!"},completion={"Oh? That's a nice haul... Good to see that you can be counted on, $R!$B$BAlright, time to calibrate these crystals so they can be integrated into the network...$B$BYou are still here?... Oh right, you want a reward, yes, yes. Now move along.","어? 꽤 많은 걸 얻었군... 역시 믿을 만하군,$R!$B$B좋아, 이제 이 수정들을 네트워크에 통합할 수 있도록 보정해야겠어...$B$B아직도 여기 있군?... 아, 맞다, 보상을 원했지, 응, 응. 자, 이제 가자."}}
rows[80253]={title={{17,1520619802},"[사용 중단됨] 페랄라스의 유물"},description={{819,1468240805},"음, 음... 지금까지 자네가 유용하다는 걸 증명했으니, 수정 가져오기보다 더 중요한 임무를 $B$B맡겨볼까. 우리 종족은 하이본의 후손으로, 한때 칼도레이 사회의 정점에 서서 위대한 제국을 다스렸지… 동부 왕국에는 그 흔적이 거의 남아 있지 않지만, 칼림도르에는 아직 약탈당하지 않은 유적들이 가득해! 자네가 $B$B페랄라스의 정글로 가주었으면 좋겠네. 그곳은 한때 엘드레탈라스 도시 국가가 있던 곳이지. 엘드레탈라스 바로 남쪽에 유적이 있을 거야… 현지인들은$B$B 그곳을 하이 와일더니스라고 부르는 것 같네. 우리 정찰병들이 보고하길, 유적을 점령한 오우거들이 실수로 귀중한 마법 유물을 파냈다고 하더군. 자네가 그곳에 가서 그 유물들을 가져와… 저 덩치$B$B 큰 녀석들이 발로 밟아 부수기 전에 말이야! 자, 어서 가자!"},objectives={{62,1745265128},"페랄라스의 고지대 황야에서 마법 유물 4개를 모으세요."},progress={{130,14828820},"뭘 기다리고 있는 거야?$B$B네가 지체하는 매 순간 뚱뚱한 오우거가 귀중한 유물을 부숴버릴 수 있어!$B$B어서 가! 널 믿고 있어."},completion={"What's that you got there?...$B$BBy the Sunwell! These are perfect! Yes yes, I'm sure some of these will assist our cause! You have my thanks $R, you have my thanks indeed...$B$BHere is your little trinket, now get going!$B$BI have research to do.","그게 뭐죠?...$B$B선웰 근처군요! 완벽해요! 네네, 분명 이 중 일부는 우리 목적에 도움이 될 겁니다! 정말 감사합니다$R, 정말 고맙습니다...$B$B여기 작은 장신구입니다. 자, 이제 가세요!$B$B저는 조사할 게 있어요."}}
rows[80254]={title={{19,581060794},"[더 이상 사용되지 않음] 줄마샤르 박살내기"},description={"Greetings, $N! I see that you have done quite a lot of work for Anu'delen, but now the time has come for something more serious than fetching artifacts.$B$BAlah'thalas is not far from the Scourge or the Amani, after the fall of Quel'thalas our people can no longer keep the rampaging Forest Trolls in check.$B$BOur scouts have reported that the Troll population of Zul'mashar in the Eastern Plaguelands is being converted to the Undead at a rapid pace.$B$BWe cannot have this, Forest Trolls are bad enough, we don't need to deal with an Undead version.$B$BGo there, exterminate both the living and the dead, we can't allow those beasts to go out of control.","안녕, ! $N아누델렌을 위해 많은 일을 해 주셨지만, 이제 유물 수집보다 더 중요한 일이 생겼습니다. 아라탈라스는 스컬지나 아마니족과 멀지$B$B 않은 곳에 있습니다. 쿠엘탈라스가 함락된 후, 우리 백성은 날뛰는 숲 트롤들을 더 이상 통제할 수 없습니다. 정찰병들이 보고한 바에 $B$B따르면, 동부 역병지대의 줄마샤르에 있는 트롤들이 빠른 속도로 언데드로 변하고 있습니다. 이대로 둘 수는 없습니다. 숲 트롤만으로도$B$B 충분히 골칫거리인데, 언데드까지 상대할 필요는 없습니다. 그곳으로 가서 산 자와 $B$B죽은 자 모두를 섬멸하십시오. 저 짐승들이 통제 불능 상태가 되도록 내버려 둘 수는 없습니다."},objectives={{153,2096342435},"동부 역병지대의 줄마샤르로 가서 이끼살처 정찰병, 이끼살처 그림자사냥꾼, 감염된 이끼살처, 이끼살처 식인종을 각각 5마리씩 처치하십시오."},progress={{28,1230855987},"자, 그럼? 일이 끝난 건가요?"},completion={{254,152370209},"정말 잘했어, 친구! 정말 훌륭해… 이대로 계속 나아가면 우리 선조들이 시작한 일을 이어갈 수 있을 거야.$B$B사악한 숲의 트롤과 재앙이 번성하도록 내버려 둘 순 없어. 그들을 억누르고 결국에는 완전히 박멸하는 것이 우리의 의무야."}}
rows[80256]={title={{22,1947821137},"[지원 중단됨] 알라탈라스에 오신 것을 환영합니다"},description={{791,396137129},"저는 타닐라 선키스입니다. 알라탈라스와 스톰윈드 마법사 탑을 연결하는 차원문을 관리하는 레이 기술자죠. 스톰윈드로 돌아가야 할 때는 저에게 말을 걸면 됩니다. 여기는 $B$B황금 새벽회 연구소입니다. 숙박 시설을 제공하고 있으며 새로운 여행자들을 환영합니다. 제 앞에는 순간 이동의 오브가 있습니다. 이걸 사용하면 알라탈라스로 내려갈 수$B$B 있습니다. 아래 탑에 있는 마법사 아누델렌이 광산 문제 때문에 도움을 요청했습니다. 연구소에는 여관 주인 조알라르가 있으니 식사를 하거나 귀환석을 충전하고 싶으시면 그곳으로 $B$B오세요. 저 큰 부유 구조물은 태양의 요새라고 합니다. 이곳에는 새로운 마법사 본부, 레인저 본부, 그리고 평의회 회의장이 있습니다. $B$B자, 이제 더 이상 시간을 끌지 말고 마법사에게 가세요!"},objectives={{133,426236671},"황금 새벽 학원 아래 탑에 있는 마법사 아누델렌에게 말을 걸고, 순간 이동의 오브를 사용하여 아래쪽 땅으로 순간 이동하세요."},progress={{31,462203331},"또 방해하네! 이게 뭐지?"},completion={{85,692784583},"저를 도와주시겠다는 말씀이시군요?... ​​제가 해야 할 일을 잠시 설명해 드릴 수 있을 것 같습니다."}}
rows[80258]={title={{18,1797485420},"[사용 중단됨] 양귀비의 눈물"},description={"Sinu a'manore, $C.$B$BYou have answered our call for aid, for which we are truly grateful.$B$BWith the fall of Quel'Thalas we, the Quel'dorei, have been left without a home. It is here where we shall focus our wits and strengthen our will. This is the beginning of our quest for vengeance, and you shall be part of it, among others.$B$BYou see, as we prepare for a war against death itself we need to have as less casualties as possible but we can only prevent so many.$B$BWhere there is a battle there shall be dead and wounded. I ask of you on this day and many to come to aid us in our effort to supply our numbers with a means to mend and heal. There is a small and not so elegant flower growing in Redrige Mountains. We call it poppy. I shall not bore you with the alchemical details, you only need to know that the concoction will ease the pain of the wounded. I know it's a simple task  but it is not meaningless.$B$BReturn to me when you have a handful of them.","시누 아마노레,$C $B$B.저희의 도움 요청에 응답해 주셔서 진심으로 감사드립니다.퀘르탈라스가$B$B 함락되면서 저희 퀘르도레이는 고향을 잃었습니다. 바로 이곳에서 저희는 지혜를 모으고 의지를 굳건히 할 것입니다. 이것이 저희의 복수 여정의 시작이며, 당신은 다른 이들과 함께 그 여정에 동참하게 될 것입니다.아시다시피, $B$B죽음 그 자체와의 전쟁을 준비하는 지금, 저희는 최대한 적은 사상자를 내야 하지만, 막을 수 있는 것은 한계가 있습니다.전투가 $B$B있는 곳에는 죽음과 부상이 있기 마련입니다. 오늘, 그리고 많은 이들이 저희의 노력을 도와 부상당한 병사들을 치료하고 회복시킬 수 있도록 해 주시기를 부탁드립니다. 붉은마루 산맥에는 작고 그다지 아름답지 않은 꽃이 자라고 있습니다. 저희는 그것을 양귀비라고 부릅니다. 연금술적인 세부 사항은 생략하겠습니다. 다만 그 약이 부상당한 이들의 고통을 덜어줄 것이라는 것만 알아두시면 됩니다. 간단한 일인 건 알지만, 결코 무의미한 일은$B$B 아닙니다. 몇 개 모으면 제게 돌려주세요."},objectives={{41,1388676332},"레드리지 산맥에서 양귀비 열 송이를 따세요."},progress={{81,1547308304},"이는 앞으로 다가올 전투의 승패를 좌우할 것이므로, 결코 가볍게 여겨서는 안 됩니다."},completion={"These will do just fine. Not all of them are of the highest quality but they will be useful. Thank you $C.$B$BAh yes, here is your reward.$B$BReturn soon, $C.$B$BSelama Ashal'anore!","이것들로 충분할 겁니다. 모두 최고급은 아니지만 유용하게 쓰일 거예요. 감사합니다,$C.$B$B아, 네, 여기 보상입니다.$B$B곧 다시 오세요,$C.$B$B셀라마 아샬라노레!"}}
rows[80260]={title={{32,1546992754},"[사용 중단됨] 동정심이 필요한 문제에 대한 도움"},description={{485,1018989934},"자네와 상의해야 할… 곤란한 문제가 있네. $B$B스톰윈드에서 온 아이가 있는데, 쉴 새 없이 옹알거리고$B$B 있네. 솔직히 말해서, 내 일에 방해가 되고 있어. 내가 그 아이를 돌볼 자격이 가장 충분하다고 생각했는데, 자네가 ‘영웅’이 되고 싶어 하는 성향이 있으니, 그 아이의 애원을 좀 $B$B달래주면 좋겠네. 그래, 좋아! 자네 조건에 그게 포함된다면,$B$B 보상도 해주겠네. <아누델렌은 콧등을 찡그리며 목 옆의 핏줄이 불거져 나왔다.>"},objectives={{72,1059247059},"아누델렌의 불만을 덜어주고 싶다면 그와 다시 이야기해 보세요."},progress={{17,254303697},"도움이 필요해요!"},completion={{215,649747830},"선웰 신이시여 감사합니다! 이게 제게 얼마나 큰 의미인지 당신은 상상도 못 할 거예요.$B$B이렇게 중요한 일을 할 때는 평화롭고 조용한 환경이 필수적이죠.$B$B이 호루라기로 그 아이를 불러서, 제 얘기 대신 그 아이의 고민을 들어주세요."}}
rows[80261]={title={{19,1329296158},"[사용 중단됨] 테슬리나의 검색 I"},description={{408,339232334},"오, 위대한 모험가님! 제 이름은 테슬리나예요. 제발 도와주세요! $B$B엄마와 저는 북쪽에서 온갖 나쁜 일들을 피해 도망쳐 나와 파스트라이더 여관에 있었는데, 스톰윈드에 도착했을 때 헤어졌어요! 엘샤린 아주머니가 저를 발견하고 여기로 데려오셨는데, 엄마도 여기 계실 거라고 생각하셨나 봐요. 하지만 엄마는 안 계세요! 저기 있는 심술궂은 아저씨는 저보고 구석에 앉아서 조용히 있으라고만 했어요. 저를 도와주실 거죠?"},objectives={{39,948879942},"스톰윈드에서 테슬리나의 엄마를 찾아보세요."},progress={{40,1075858426},"제발, 저 좀 도와주시겠어요?$B$B제발 부탁드려요?"},completion={{53,936493917},"그녀는 마법사 지구에 없어요. 하지만 포기할 순 없어요!"}}
rows[80262]={title={{20,191621396},"[사용 중단됨] 테슬리나의 탐색 II"},description={{73,1784304516},"드워프 구역, 공원, 그리고 우리 부족 구역 순으로 가보자!"},objectives={{39,948879942},"스톰윈드에서 테슬리나의 엄마를 찾아보세요."},progress={{50,1197967932},"만약 그녀를 찾지 못하면 정말 펑펑 울 것 같아요!"},completion={{47,304821814},"그녀도 여기 없네... 엄마, 어디 있어요?!"}}
rows[80263]={title={{21,1480082864},"[사용 중단됨] 테슬리나의 탐색 III"},description={{220,82874393},"다음엔 큰 성에 가보자! 왕자님이 참 친절하시대. 구시가지도 구경해 보자. 거기 선술집도 있는 것 같아. 아, 그리고 소문으로만 듣던 그놈족 전차도 한번 봐야겠다! 어쩌면 그녀가 거기서 기다리고 있을지도 몰라."},objectives={{39,948879942},"스톰윈드에서 테슬리나의 엄마를 찾아보세요."},progress={{82,1752973511},"우린 포기할 수 없어! 그녀를 찾아야 해. 그녀 없이는 어떻게 살아야 할지 모르겠어."},completion={{52,1405037725},"엄마는 어딘가에 계실 거예요. 계속해 주세요!"}}
rows[80264]={title={{20,191621409},"[사용 중단됨] 테슬리나의 탐색 IV"},description={{190,1774059513},"구시가지에 있는 병영을 찾아볼 수도 있겠네요. 아, 그리고 그 거대한 대성당도요! 어쩌면 그녀가 거기서 저를 찾았을지도 몰라요. 근처에 꽤 큰 건물에 길 잃은 아이들을 위한 시설이 있다고 들었어요!"},objectives={{39,948879942},"스톰윈드에서 테슬리나의 엄마를 찾아보세요."},progress={{42,1368846037},"제발, 계속 도와주세요. 그녀는 멀지 않았을 거예요!"},completion={{48,824854199},"엄마... 아니, 분명히 찾을 수 있을 거예요, 그렇죠?"}}
rows[80265]={title={{19,1329296171},"[사용 중단됨] 테슬리나의 검색 V"},description={{148,1856008593},"이제 남은 곳은 얼마 안 되는 것 같아요. 우리가 놓친 곳들을 모두 찾아보죠. 대성당에도 볼거리가 더 있고, 무역 광장도 둘러볼 수 있어요!"},objectives={{59,1496738788},"스톰윈드에서 테슬리나의 엄마를 찾는 데 도움을 줄 수 있는 사람을 찾아보세요."},progress={"Yes? What can I do for you, $R?","네?$R님, 무엇을 도와드릴까요?"},completion={{569,1845293015},"어머니가 실종됐다고요? 잠시만 기다려 주십시오. 저희가 보유한 방대한 기록에서 찾아보겠습니다.$B$B소녀의 이름이 테슬리나인가요? 저희는 테슬리나와 어머니가 다른 난민들과 함께 스톰윈드에 도착했다는 기록은 가지고 있지만, 두 사람은 시청에 등록하러 오지 않았습니다.$B$B심각한 문제입니다. 스톰윈드에서 실종자가 발생해서는 안 됩니다. 제가 조사해 보겠습니다. 조사가 완료될 때까지 소녀를 돌봐주시겠습니까?$B$B스톰윈드에 등록되어 있으니, 소녀에게 적절한 식사를 제공할 수 있도록 보증금을 지급하겠습니다."}}
rows[80289]={title={{20,772595769},"첫 번째 정착지"},description={"Ah, there you are, $N. You have proven to be of some use in the past. I have observed that you have an uncanny knack for running errands. My ancestors were exiled from Kalimdor seven thousand years ago, but you're mistaken if you think they created Quel'thalas right away.$B$BThey landed in what is today known as the Tirisfal Glades. According to records left behind in Alah'thalas, the first settlement was known as Ishnu'danil. Naturally, this is something we consider worthy of exploring further, which is why I have sent my subordinate Thas'alah to investigate this ancient location.$B$BHowever, I have not heard a word from him since, and to make matters worse, the records we found mention a curse of some kind that affected the minds of our ancestors who lived there. I need you to go there and find out what became of Thas'alah.","아, 여기 있었군,$N . 자네는 과거에 꽤 도움이 되었던 것을 기억하네. 심부름을 처리하는 데 탁월한 재능이 있다는 걸 눈여겨봤지. 우리 조상들은 7천 년 전에 칼림도르에서 추방당했지만, 그들이 곧바로 쿠엘탈라스를 세웠다고 생각한다면 오산이야.$B$B 그들은 오늘날 티리스팔 숲으로 알려진 곳에 상륙했지. 알라탈라스에 남겨진 기록에 따르면, 최초의 정착지는 이쉬누다닐이라고 불렸어. 당연히 우리는 이곳을 더 자세히 조사할 가치가 있다고 생각해서, 내 부하 타사라를 이 고대 유적지로 보냈지. 하지만 그 이후로 타사라에게서$B$B 아무 소식도 듣지 못했고, 설상가상으로 우리가 발견한 기록에는 그곳에 살았던 우리 조상들의 정신에 영향을 미친 저주에 대한 언급이 있더군. 자네가 그곳에 가서 타사라에게 무슨 일이 일어났는지 알아봐 주었으면 좋겠네."},objectives={{63,647035782},"티리스팔 숲 서쪽에서 스크라이어 로르달 타살라를 찾으십시오."},progress={"Who are you, $r?","$r님, 당신은 누구십니까?"},completion={{357,349059511},"마법사 아누델렌이 보냈나? 드디어 좋은 소식이군. 이 망할 원정대는 그야말로 재앙의 연속이었어. 처음에는 진전이 있었지만 얼마 지나지 않아 모든 게 내리막길이었지.$B$B우리 장비가 고장 났고, 사람들은 그곳이 귀신이 나오는 곳이라고 생각했으며, 심지어 어떤 사람들은 누군가 말을 걸어오는 소리를 들었다고 주장하기도 했습니다. 하지만 마지막 이야기는 완전히 허무맹랑한 소리입니다."}}
rows[80290]={title={{16,452770415},"잃어버린 석판들"},description={{633,738362185},"이곳에서 벌어지고 있는 모든 일들을 생각하면, 당신 같은 모험가의 도움이 절실히 필요합니다. 아시다시피, 우리 조상들은 마법을 사용하여 땅을 빚고 이런 건물들을 지었는데, 이 건물은 미완성 상태로 버려진 것 같습니다. 제가 직접 $B$B안으로 들어가 보려 했지만, 곧바로 공포와 두려움에 휩싸였습니다. 마치 건물이 저를 집어삼키는 듯한 느낌이 들어서 밖으로 도망쳐 나왔습니다. 하지만 당신은 쉽게 겁먹지 않는 것처럼 보이시군요. 제가 떠나기 전에 절벽에 새겨진 석판을 발견했습니다. 혹시 이 석판에 $B$B이곳에서 무슨 일이 일어났는지에 대한 단서가 있을지도 모릅니다. 부디 저를 위해 석판을 가져다주실 수 있을까요?"},objectives={{49,767859108},"미완성 건물 안에서 태블릿을 구하세요."},progress={{15,1203322150},"이해하셨어요?"},completion={{764,1041535135},"결국 그곳은 귀신이 나오는 곳이었던 건가? 영혼과 대화할 수 없었던 건 아쉽지만, 어쩌면 다행일지도 모르겠군. 어쨌든, 저 석판을 보자. 아, 탈라시안어로 쓰여 있군. 덕분에 좀 더 이해하기 쉽겠어. 이 석판에는 하이본과 알라하란의 새로운 고향으로 이쉬누다닐이 세워졌다는 내용이 적혀 있군.$B$B그런데 이 부분을 봐. 우물에 대한 구절인데, 정확히 말하면 힘의 우물에 대한 구절이야. 그리고 이건 뭐지? 여기 아래쪽을 봐. 여기에 새겨진 글귀가 있는데, 이전과는 다른 필체로 쓰여 있군. 이렇게 쓰여 있어:$B$B<샬라아란을 피하라. 이쉬누다닐을 피하라. 이곳에는 오직 어둠뿐이다.>$B$B이쉬누다닐은 '행운의 봉우리'라는 뜻이고, 샬라아란은 '그림자 우물'을 의미한다. 만약 그토록 강력한 무언가가 이 근처 어딘가에 있다면, 우리는 반드시 그것에 대해 더 자세히 알아내야 해!"}}
rows[80291]={title={{15,2024181875},"그림자 우물"},description={{200,2080806657},"이미 제 하인 탈로를 그곳으로 보냈지만 아직 돌아오지 않았습니다. 이 그림자 우물이 이 글에서 주장하는 것처럼 강력하고 위험한 곳이라면, 더 자세한 정보를 알아두는 것이 중요할 것입니다."},objectives={{28,272045763},"그림자 우물을 조사하세요."},progress={{70,1618488035},"돌아왔구나!? 잘됐군. 거기서 뭘 찾았는지 말해봐."},completion={{371,2070076489},"탈로를 찾지 못했다면, 그 해골은 분명 그의 것이었겠군요. 뭐, 어쩔 수 없죠. 그리고 우물물에서 검은 점액이 나온다는 건 또 뭐죠? 그들이 맞았군요, 정말 흥미롭습니다.$B$B어쨌든, 도와주셔서 감사하지만, 이제 가실 시간인 것 같습니다. 저는 아직 조사할 게 남아있고, 아르카니스트에게 우리의 발견을 알려야 하지 않겠습니까?"}}
rows[80292]={title={{17,45631003},"외로운 귀향"},description={{324,135279159},"저에 대해서는 걱정하지 마세요. 저는 여기 혼자 있지 않을 겁니다. 제 경호원들이 함께 있어요. 그리고 이곳이 너무 중요한 곳이라 방치할$B$B 수 없다는 데 동의하시겠죠? 아, 그리고 환청 이야기는 하지 말아 주시면 정말 감사하겠습니다. 아누델렌이 보내줄지도 모르는 조력자들을 겁주고 싶지 않거든요."},objectives={{35,1552165269},"알라탈라스의 아누델렌으로 돌아가십시오."},progress={"Took you long enough, $N. You're alone. Where is Scryer Thas'alah?","오래 걸렸군,$N. 자네는 혼자야. 스크라이어 타살라는 어디 있지?"},completion={{528,577691067},"탐험대원 대부분이 죽었는데, 그는 거기에 남기로 한 건가? 제정신이 아닌가!? 어둠의 속삭임과 타락한 우물에서 괴물이 나온다는 소문이 도는 으스스한 장소는 우리가 거기서 발견하길 바란 게 절대 아니었어.$B$B하지만 네가 가져온 정보는 우리에게 귀중한 자료가 될 수도 있겠군. 정말 많은 정보인데, 그렇게 강력한 우물이 타락했다니 정말 안타깝군. 자, 이제 네 임무는 여기서 끝나고 내 임무가 시작되는군. 아, 그리고 잊을 뻔했는데, 수고에 대한 보답으로 작은 선물을 줄게."}}
rows[80300]={title={{15,1626565808},"터스켄족 사건"},description={{476,1031363893},"안녕하세요! 저는 호드와 더욱 긴밀한 관계를 맺기 위해 고향을 떠난 레반투스크 트롤 무리를 대표하여 왔습니다. 저희는 대격변 이전에 $B$B파괴된 잔달라 사원 근처, 돌발톱 산맥에 진을 치고 있으며, 여러분의 도움이 절실히 필요합니다. 시간이 되시면 대족장의 오두막에$B$B 있는 볼즈드라자에게 말을 걸어주세요. 그녀가 안내해 줄 뿐만 아니라 도움에 대한 보상도 보장해 줄 것입니다."},objectives={{37,948400132},"그롬마쉬 요새에 있는 볼즈드라자와 대화하세요."},progress={{21,2090234471},"무슨 일로 오셨나요?"},completion={{283,2066561953},"우리를 돕고 싶다고? 좋아, 좋아. 대족장께서 내가 여기에 머물면서 우리를 도울 호드의 하수인들을 임명하는 것을 허락하셨지.$B$B우리는 새로운 거처를 아마니알로르라고 이름 지었고 이미 정착을 시작했어. 하지만 짐작하시겠지만, 새로운 땅에 정착하는 데에는 여러 가지 어려움이 따르지."}}
rows[80301]={title={{18,2037659612},"장작더미에 불을 붙이다"},description={{646,711380181},"우리가 처음 이곳에 왔을 때, 우리만의 보금자리를 만들기 위해 구조물을 세우는 것이 중요했습니다. 이곳을 정리하던 중, 우리는 사원 입구를 무너뜨리고 무너진 잔해들을 치웠습니다. 과거에는 $B$B많은 로아, 특히 죽음의 로아가 이곳에서 숭배되었습니다. 우리가 무덤 안의 영혼들을 방해했는지, 과거의 트롤들이 되살아나 사원을 괴롭히고 있습니다. 이 복수심에 불타는 언데드들은 평화로운 숭배자들을 포함하여 그들의 복도를 지나가려는 자들을 공격합니다. 우리의$B$B 임무는 무덤 안의 장작더미에 불을 붙여 괴로워하는 영혼들을 달래고 사원을 정화하는 것입니다. 언데드가 방해가 된다면, 그들을 저승으로 돌려보내십시오."},objectives={{37,831362422},"무덤 안에 있는 8개의 영혼의 불덩이에 불을 붙이세요."},progress={{46,1589675450},"다 끝난 건가요? 영혼들은 이제 편히 쉴 수 있을까요?"},completion={{190,1907332777},"지독한 악취가 서서히 사라지고 있군. 잘했어, 친구. 네 노력에 대한 보상을 받을 자격이 있어.$B$B시간이 흐르면 ​​이곳은 레반터스크뿐 아니라 호드 전체에 귀중한 자산이 될 거라는 걸 알아둬."}}
rows[80302]={title={{14,140269056},"아마니알로르께!"},description={{543,662253028},"저는 지금 외교적인 문제로 골머리를 앓고 있어서 제대로 인사를 드릴 수가 없네요. 레반터스크 부족을 진심으로 돕고 싶으시다면, 저희는$B$B 진심으로 감사히 받겠습니다. 레반터스크 부족이 그동안 오지에서 저희에게 베풀어준 모든 도움에 보답하고 미래를 향해 나아갈 때가 왔습니다. 검은창 부족의 데이노가 아만알로르를 오갈 수 있는 차원문을 열어주었습니다. 영혼의 계곡에서 $B$B데이노를 만나실 수 있습니다. 아만알로르에 도착하시면 신비주의자 구야진을 찾아가 레반터스크 부족을 어떻게 도울 수 있는지 물어보세요."},objectives={{68,388743977},"영혼의 계곡에 있는 데이노에게 말을 걸어 아마니알로르로 가는 교통편을 문의하세요."},completion={{347,895449826},"레반투스크 부족도 돕고 싶으신 건가요? 훌륭한 호드 외교관이시군요.$B$B그들은 마지막으로 제정신을 유지하는 숲 부족이자 우리의 사촌이니, 기꺼이 돕겠습니다. 아제로스의 트롤들은 오랫동안 서로 반목해 왔는데, 호드 아래 부족들이 단결하는 모습을 보니 희망이 생기네요.$B$B혹시 아만니알로르로 가고 싶으시다면, 언제든 저에게 말씀하세요."}}
rows[80303]={title={{26,547453530},"퀘르리시엔 여관 습격"},description={"It's good to see you again, $c. Our scouts have reported increased activity from our ancient enemy in the Eastern Plaguelands.$B$BThey are preparing to outfit an expedition with trinkets stolen from our people to protect them against corruption.$B$BTravel to the lodge and put an end to their expedition before they can benefit from our stolen relics.",", 다시 만나서 반갑습니다.$c 우리 정찰병들이 동부 역병지대에서 오랜 적의 활동이 증가했다고 보고했습니다.$B$B 그들은 우리 백성에게서 훔친 장신구로 원정대를 꾸려 타락으로부터 자신들을 보호하려 하고$B$B 있습니다. 은신처로 가서 그들이 훔친 유물을 이용하기 전에 원정대를 막아주십시오."},objectives={{151,211409273},"동부 역병지대에 있는 퀘르리센 오두막으로 가서 퀘르리센 길잡이 6마리, 퀘르리센 나무꾼 6마리, 퀘르리센 정찰병 6마리를 처치하십시오."},progress={{64,737886201},"혹시 장신구를 되찾는 데 성공했나요? 전투 이야기를 들려주세요."},completion={"You've proven your worth yet again, $c. We may not have been able to recover what they stole, but at least we set them back from launching their expedition.","$c, 당신은 또 한 번 당신의 가치를 증명해냈습니다. 비록 그들이 훔쳐간 물건을 되찾지는 못했지만, 적어도 그들의 탐험대 출정을 저지하는 데는 성공했습니다."}}
rows[80304]={title={{17,932563912},"치유의 수단"},description={{647,1173097286},"트롤들은 로아의 축복을 받아 뛰어난 재생력을 지녔지, 친구. 작은 상처든 팔다리 전체든, 우리는 스스로 치유할 수 있어. 하지만 재생에 너무 오랜 시간이 걸릴 때도 있으니, 그런 상황에 대비하는 것도 나쁘지 않지. $B$B애쉬엔베일의 스플린터트리 전초기지에 있는 우리 동맹들이 얼마 전 자신들도 모르게 작은 주술적 해결책을 발견했어. 숲 가장자리, 탈론딥 길 근처의 미스트랄 호수에는 두꺼비들이 돌아다니는데, 그 두꺼비들은 미끈미끈한 기름으로 덮여 있어. 그 기름으로 강력한$B$B 연고를 만들 수 있지. 친구, 가서 그 두꺼비들을 짜서 기름을 좀 가져다주면, 수고에 대한 보상을 해줄게."},objectives={{55,1180518642},"아마니알로에 있는 전쟁지도자 졸마진에게 두꺼비 기름 10개를 가져가야 합니다."},progress={{28,390237332},"짜는 건 잘 돼가고 있어, 친구?"},completion={"Spirits be with ya, $r. Ya efforts will keep us trolls healing up nicely. The Horde been nothing but kind to us, and we'll see to it ya be repaid in kind.","$r님, 부디 좋은 일만 가득하시길 바랍니다. 당신의 노력 덕분에 저희 트롤들은 꾸준히 회복할 수 있을 겁니다. 호드는 저희에게 늘 친절했으니, 저희도 당신에게 그에 상응하는 보답을 해드리겠습니다."}}
rows[80305]={title={{13,1369718510},"쿼크의 오두막"},description={{871,42884934},"이봐 꼬마, 재밌니?아니,$B$B 전혀 안 재밌어 보이네. 얼굴에 다 드러나. 여기는 꽤 낡고 지루하고 할 것도 없잖아, 그렇지?$B$B음, 만약 네가 뭔가 재밌는 걸 원한다면, 그것도 돈으로 하는 재밌는 걸 말이야, 내가 뭘 좀 해줄까! 하지만, 정보는 $B$B공짜가 아니라는 거 알지?내 입을 좀 $B$B열어주려면 은화 한 닢 정도면 어떨까?<고블린은 씩 $B$B웃으며 손을 펴고 기다린다.>자, 이제 우리 친구가 됐으니, 이 작은 비밀을 알려줄게. 마을에서 들은 얘기인데, 명예의 계곡에 새로 술집이 생겼거든. 꽤 아이러니하지 않나?I 쿼크라는 $B$B고블린이 가게를 열었는데, 회원제로 운영된다고 하더군.I 난 굳이 거기 가볼 생각은$B$B 없지만, 돈 좀 벌 수 있다고 하더군!자, 정보 제공에 대한 대가로$B$B 50코퍼를 드리겠습니다. 좋은 하루 보내세요, 친구."},objectives={{55,1274062592},"명예의 계곡으로 가서 쿼크의 오두막을 찾으세요."},progress={"Why are you still here, $N?$B$BIf you wanted to buy me a drink, I'm sorry, but I you're not my type. Unless, of course, you've got enough coin. Then, maybe something can be arranged.","$N, 왜 아직 여기 있어요?$B,$B. 혹시 술 한 잔 사주고 싶으셨다면 죄송하지만, 당신은 제 타입이 아니에요. 물론 돈이 많으시다면 얘기는 다르겠지만요. 그럼 뭐, 생각해 볼 수도 있겠죠."},completion={{46,149268139},"그래, 그래, 친구, 금방 갈게!$B$B왜 그렇게 급해?"}}
rows[80306]={title={{20,1344629203},"당신의 것은 우리의 것입니다"},description={{567,1906942786},"이봐, 조심해! $B$B어머, 이게 뭐지? 제대로 된 $B$B손님이시군. 쿼크의 오두막에 오신 걸 환영합니다. 사업차 $B$B오셨나요, 아니면 재미로 오셨나요? 여기는 동전 감정가들을 위해 제가 만든 술집입니다. 여기 오셨다면, 동전도 좀 따시고 재미도 좀 보세요. 도박을$B$B 하고 싶으시면 아그네에게 말씀하세요. 그녀가 뼈를 담당합니다. 뭐, 주사위를 한 번도 굴려본 적이 없다고요? 걱정 마세요, 친구. 돈은 금방 되찾으실 수 있을 겁니다! 혹시 정신을 맑게 하고 생각을 마비시킬 무언가가 필요하시면 언제든 다시 저를 찾아오세요."},objectives={{31,660305509},"주사위를 굴리려면 아그네에게 말을 걸어보세요."},progress={{83,135218575},"안녕, 자기. 동네 미녀 아그네랑 간단한 행운 게임 한 판 해볼래?"},completion={{43,1609767826},"초기 투자자가 가장 큰 이자를 거둔다."}}
rows[80307]={title={{39,818987127},"오그리마 상공에 또 다른 연기 구름이 나타났다."},description={{695,1477467772},"재밌게 보내고 계세요,$B$B 사장님? 좋아요, 좋아요. 자, 보세요, 방금은 무료 체험이었어요. 당신이 이기든 지든 저한테는 상관없지만, 제가 '동전 감정가'라고$B$B 했으니 회원비는 내셔야 해요. 어이, 어이, 어디 가세요? 그러지 마세요. 부탁 하나만 들어주시면 회원 카드를 $B$B드릴 수도 있어요. 언더마인에서 우리 물담배에 쓸 새 물건을 주문했거든요. 이 물건은 아주 중요하고 값비싼 물건이에요. 제 물건을 가져다주시면 동전도 좀 드릴게요. 그 동전은 제 바에서 마음껏 쓰셔도 돼요. 물건은 오늘쯤 톱니항에 도착할 예정이니까 어서 와주시면 정말 감사하겠습니다."},objectives={{45,203085889},"쿼크의 화물에 대해 여관 주인 와일리에게 문의하십시오."},progress={"I'm running really low on my supplies, here, $N. Could seriously use that cargo right about now!","여기$N지역, 제 물자가 정말 부족해요. 지금 당장 그 화물이 절실히 필요합니다!"},completion={{172,495666316},"쿼크의 담배요?$B$B문제가 생길지도 몰라요.$B$B잠깐! 공격적일 필요는 없어요. 들어보세요.$B$B<와일리는 떨리는 작은 손으로 당신의 폭력을 만류하기 위해 동전 몇 개를 던져 넣습니다.>"}}
rows[80308]={title={{15,1680880500},"담배 도둑들"},description={{577,671198358},"음... 해적들이 좀 출몰하는 문제가 생겼어요. 언더마인에서 화물을 운송하던 중에 이 망할 해적들이 배를 습격해서 약탈해 갔거든요. 선원들은 무사히 탈출했지만, 더 중요한 건 화물이 전부 사라졌다는$B$B 겁니다! 엄청난 손실이에요. 쿼크가 대량 화물을 기다리고 있었는데, 대부분이 타버리거나 바다에 빠져버렸어요. 최대한 되찾아오시면 제가 어떻게든 금액을 조정해 볼 수 있을 $B$B거예요. 해적들은 남쪽 해안가에 있을 겁니다. 쿼크가$B$B 그 화물을 기다리고 있으니 서둘러야 해요. 없는 것보다는 나을 테니까요."},objectives={{27,888572099},"담배 상자 20개를 가져오세요."},progress={{73,834541846},"만약 제가 잃어버린 화물들을 되찾지 못하면 큰 문제가 생길 겁니다."},completion={"What, pirates?! Pirates?!$B$BScrew pirates, sweet mother of goblins!$B$BFor crying out loud, argh, gnomish bastards!$B$BI guess these crates will do. I owe you one, $N. Er—actually, I don't. Here, just take this membership card instead. You've earned it. You're officially a member of Quark's Shack, now. Gamble your heart away, pal.","뭐라고?! 해적이라고?!$B$B해적 따위는 집어치워, 빌어먹을 고블린 자식들아!$B$B맙소사, 으악, 그놈 자식들!$B$B뭐, 이 상자들이면 되겠지. 신세를 졌군,$N. 어, 사실은 안 졌어. 자, 대신 이 회원 카드를 받아. 자네가 받을 자격이 있어. 이제 자네는 쿼크의 가게 정식 회원이야. 마음껏 도박이나 해 봐, 친구."}}
rows[80309]={title={{17,908884924},"오도의 직감"},description={{617,1448980576},"'이봐, 빨리 이리 와 봐. 오도가 할 말이 있대. 네가 쿼크의 도박장 주변을 어슬렁거리는 걸 봤는데, 왠지 뭔가 수상한 낌새가 느껴져. 걔가 몰래 뭔가를 꾸미고 있는 것 같아. 믿을 만한 고블린은 아름다운 트롤 여자만큼이나 드물거든. 게다가 트롤들은 꽤 못생겼지. 그러니까 오도 좀 눈여겨봐. 이건 공식적인 일이고, 내가 돈도 줄게. 가서 화물이랑 서류 좀 확인하고, 스터크라는 놈도 잘 살펴봐. 걔가 쿼크의 동료야. 내 생각엔 걔가 밀수를 하고 있는 것 같아.'"},objectives={{62,1641549733},"화물과 바를 검사하여 유죄를 입증할 만한 서류를 찾아내십시오."},progress={{53,2039597247},"이봐, 내 직감이 진짜야! 범인을 잡아!"},completion={{114,968482678},"오도가 또 맞았군. 내 직감을 의심한 적은 없어. 쿼크에게 가서 스터크를 체포하라고 요구해야겠어."}}
rows[80310]={title={{15,82598270},"쿼크의 정의"},description={{466,1963505971},"저 망할 쥐새끼. 내 물건을 훔쳤군, 그렇지? 당장 넘겨주겠다. 하지만 그 전에, 저 잡종놈 눈을 똑바로 쳐다보고 잡혔다는 걸 알려줘. 죽도록 패주고$B$B 나서 오도에게 넘겨. 그 후에는 로브에게 가서 주변을 감시하고 보안을 강화하라고 전해. 내 오두막에 도둑이 들끓게 둘 순 없잖아? 다 끝내면 내게 돌아와. 보상해 주겠다."},objectives={{56,381871517},"배신자를 체포하세요. 보안 관련 사항은 로브에게 문의하세요."},progress={{64,1157716907},"저 녀석을 내 눈앞에서 치워버려! 안 그러면 제대로 한 방 먹여줄 테니까!"},completion={{216,1426640096},"자, 이제 일이 끝났으니 잃어버린 돈을 되찾을 방법을 찾아야겠군. 도와줘서 고마워, 친구. 계속 같이 있어 줘. 넌 이제 우리 팀의 소중한 일원이야. 그리고 여기! 큰돈은 줄 수 없지만, 오늘 술은 내가 살게."}}
rows[80311]={title={{20,419898957},"신비의 달인"},description={{673,1085623796},"<우레다가 실망한 표정으로 당신을$B$B 쳐다봅니다.>당신의 실력은 아직 갈고닦아야 할 게 많고, 자세는 오만함을 드러내는군. 자기 실력보다 자신감이 앞서는 초보 수습생의 전형적인 모습이지. 뭐, 내 알 바는 아니지만. $B$B그건 당신 문제야.마법사가 되려는 자는 언제나 주문을 준비해 두고 두 수 앞을 내다봐야 해. 그러니 당신의 부족한 판단력을 만회하기 위해 스스로 해결할 수 있는 일을 맡겨야겠군.$B$B썬더 리지에서 멀지 않은 사우스퓨리 강둑에… “마법사” 한 명이 살고 있지. 그 마법사가 당신에게 맡길 일은 처음에는 어려워 보일지 모르지만, 머리를 써서 잘 해낸다면 분명 좋은 결과를 얻을 수 있을 거야."},objectives={{64,1971036049},"불모의 땅의 사우스퓨리 강둑에서 초크가록에게 말을 걸세요."},progress={{63,1576110984},"흠? 그래, 뭐지?$B$B초크가록. 그래, 우리야! 그래, 머리가 두 개지!"},completion={{127,1070331031},"또 다른 지식에 대한 갈증을 가진 분이시군요? 좋아요, 좋아요! 당신이 무엇을 필요로 하는지, 무엇을 원하는지 알고 있습니다!$B$B네, 당신이 무엇을 갈망하는지 알고 있습니다!"}}
rows[80312]={title={{11,534924656},"비전 암즈"},description={{561,634552686},"우레다는 오직 자격 있는 마법사만 보낸다! 우레다는 $B$B최악이야! 두 머리는 놀란 표정으로 서로를 바라보았다. 우리는 $B$B네가 마법사로서 진정으로 필요한 것이 무엇인지 알고 있고, 부품을 어디서 구할 수 있는지도 알고 있다. 네가 부품과 정수를 가져오면, 우리가 너를 위해 $B$B무기를 만들어주겠다! 부품을 어디서 구하냐고? 동굴에 있다. 불모의 땅! 그래, 그래. 울부짖는 동굴이라고 불리는 곳. 드루이드와 뱀이 있는 동굴! 그래. 달빛에 물든 나무, 뱀의 수정, 그리고 영원히 변하는 정수를 찾아와. 그래, 그 정수! $B$B네가 그것들을 모두 가져오면, 우리가 훌륭한 무기를 만들어주겠다! 분명 고마워할 것이다!"},objectives={{122,759796380},"울부짖는 동굴에서 달빛에 물든 나무 5개, 뱀의 수정 1개, 그리고 끊임없이 변하는 정수 1개를 초크가록에게 가져다주세요."},progress={{50,1803332388},"부품은 준비됐어? 응, 응, 부품 가져와!"},completion={{187,765339910},"그래, 그래! 바로 이거야! 이 마법은 강력해서 계속 이어갈 수 있겠군! 맞아, 강력한 마법 시전이야!$B$B자, 이 무기를 받아라. 자랑스럽고 강해지도록. 그래, 그래.$B$B초크가록, 강력하군, 맞아!"}}
rows[80313]={title={{21,877749250},"아마니알로르에 오신 것을 환영"},description={{665,1958118011},"오호, 데이노가 더 많은 도움을 보냈나? $B$B구야진이 기뻐하겠소. 나는 레반투스크 부족의 주술사이자 우리 부족의 정신적 지도자인 구야진이오. 오그리마로 통하는 이 차원문을 내가 안정적으로 유지하고 있으니, 언제든 영혼의 계곡으로 돌아가고 싶다면 구야진을$B$B 찾아오시오. 마니알로는 우리 부족에게 축복과 같은 곳이오. 로아와 깊은 연결고리를 가진 고대 잔달라 사원이지. 우리는 본거지 사원에서 멀리 떨어져 있지만, 이곳에서 지역 로아에게 도움을 청하고 고향의 로아와 연결을 $B$B유지할 수 있소. 아직 좀 미숙해 보이는군. 주변을 둘러보고 방향을 잡는 게 어떻겠소? 첫 번째 임무를 수행할 준비가 되면 내게 말하시오. 이곳에는 할 일이 많소."},objectives={{67,378239873},"레반투스크에 대한 자원 지원을 시작하려면 구야진에게 다시 말을 걸어보세요."},completion={{67,1400335997},"좋아, 좋아. 할 일이 많으니 아직 서두르지 마, 친구."}}
rows[80314]={title={{28,1144282147},"서로의 등을 긁어주는 것"},description={{337,1648368568},"검은창 부족의 도움은 정말 반가운 소식입니다. 트롤들이 다른 부족과 의견 차이를 보이는 것보다 차라리 눈을 뽑아버리려 드는 시대에, 이러한 화합은 진정한 기적입니다.$B$B 호의의 표시로 졸마진은 당신을 센진 마을의 가드린 스승님께 보내드릴 겁니다. 이 인형을 그분께 바치십시오. 오래된 트롤 전통이니, 그분도 이해하실 겁니다."},objectives={{65,366779186},"졸마진의 부두 인형을 센진 마을의 가드린 스승에게 가져가세요."},progress={{39,2135883873},"야, 친구? 나한테 줄 거 있어?"},completion={{387,1256977053},"오랜만에 이런 걸 받네, 친구. 이 행동의 의미를 알겠어?$B$B이건 전쟁 지도자 졸마진의 부두 인형인데, 다른 트롤에게 비밀리에 건네진 거야. 이 인형은 결국 볼진에게 갈 테니, 졸마진은 자신의 목숨을 다크스피어 부족에게 맡기는 셈이지.$B$B이건 부족 간의 깊은 신뢰를 상징하는 거야. 이 행동은 시간이 지나면 그에 상응하는 보답을 받을 수 있을 거야."}}
rows[80315]={title={{11,1335019497},"하루에 사과 한 개"},description={{310,1951103454},"저는 살면서 꽃이 피는 걸 몇 번밖에 경험해 보지 못했는데, 이번 시즌은 뭔가 달라요. 보통 이맘때쯤이면 잎 끝에 분홍색 꽃잎이 돋아나 있어야 하는데, 이번에는 가지에 아무것도 없어요! 이건 정상적인 게 아닌 것 같아요. 혹시 드루이드분들이 제게 무슨 문제가 있는지 아실까요? 그분들은 저보다 훨씬 나이가 많고 현명하시잖아요."},objectives={{112,28306634},"애플보우를 살펴보고 과일이 다시 자라도록 도와주세요. 근처에 있는 드루이드에게 애플보우의 병이 무엇인지 물어보세요."},progress={"Please hurry, $R. I don't know how much longer my leaves have before they completely fall away.","$R님, 제발 서둘러 주세요. 잎들이 완전히 떨어지기까지 얼마나 남았는지 모르겠어요."},completion={"I can feel the life flowing back into my leaves, $R. That druid really worked some magic with that salve. I wonder what's inside? I'll study it closely until I find out so that other trees like me don't get sick, too!","내 잎사귀에 생기가 다시 흐르는 게 느껴져,$R. 그 드루이드가 만든 연고가 정말 마법 같았어. 안에 뭐가 들어있는지 궁금하군. 다른 나무들도 나처럼 병들지 않도록 자세히 연구해서 알아내야겠어!"}}
rows[80320]={title={{15,1336946800},"불타는 다리"},description={"Hey $c! I've got a business proposition for you. My boss sent me to track down defectors from the cartel that joined up with the Burning Blade and I've found out that Fizzle isn't the only goblin playing with demon fire around here.$B$BKnobby Tinfault's hiding in Dustwind Cave on top of the Drygulch Canyon. Find him and bring me anything he's carrying that has so much as a strange mark on it. We need to get any info back to Gazlowe so we can find out if there's more to their schemes.","이봐,$c ! 사업 제안 하나 할게. 우리 사장이 불타는 칼날에 합류한 카르텔 탈주자들을 찾아내라고 했는데, 피즐만 악마의 불을 가지고 노는 게 아니라는 걸 알게 됐어. 노비 틴폴트가 드라이걸치$B$B 협곡 꼭대기에 있는 더스트윈드 동굴에 숨어 있어. 그를 찾아서 그가 가지고 있는 물건 중에 이상한 표식이 있는 게 있으면 뭐든 가져와. 가즈로에게 정보를 보내서 그들의 음모가 더 있는지 알아내야 해."},objectives={{63,1701883158},"노비 틴폴트를 죽이고 그가 떨어뜨린 물건들을 마일리에게 가져다주세요."},progress={{34,204138941},"다 끝났나요? 뭐 발견한 거 있어요?"},completion={{194,484157565},"벨트라니, 영리하고 기발하군. 하지만 벨트 안에 숨겨진 비밀 공간 같은 건 함부로 들여다보지 않는 게 좋겠어. 라쳇에게 가져다줘서 안전하게 조사하게 해야겠어. 정말 큰 도움이 됐어! 고마워!"}}
rows[80321]={title={{21,85201387},"우리를 묶는 거짓말"},description={{412,1830125601},"마일리가 이걸 찾는 걸 도와준 사람이 당신이죠?$B$B<가즐로우가 더스트윈드 동굴에서 찾은 벨트를 들어 $B$B올린다.> 제가 좀 알아봤는데 누가 만들었는지 알겠어요. 오그리마에 사는 키로라는 여자예요. 좀 공격적이긴 하지만 꽤 $B$B괜찮은 여자죠. 가능성은 낮겠지만, 키로에게 이 비문에 대해 아는 게 있는지 알아봐 주셨으면 해요. 저는 이미 해독했지만, 키로가 더 많은 걸 알고 있을지도 몰라요."},objectives={{50,66325329},"노비의 벨트를 명예의 계곡에 있는 키로에게 주세요."},progress={{25,398957990},"무엇을 찾고 계신가요?"},completion={"Yes, $C, I made this. What of it?","네,$C, 제가 만들었어요. 그래서 어쩌라는 거죠?"}}
rows[80322]={title={{21,85201387},"우리를 묶는 거짓말"},description={{481,2012835642},"하! 가죽 세공인이 만든 흔적은 $B$B아니야. 이건 악마 마법이지. 불모의 땅에 추방자가 한 명 있어. 우리 세계의 대장장이인데, 악마 마법에 특별한 재능이 있어. 마법의 근원을 감지할 수 $B$B있지. 그를 찾아가려면 대가를 지불해야 하고, 운도 따라줘야 할 거야. $B$B우리 중 일부는 과거를 되살리는 걸 좋아하지 않아. 우리 혈통에 묻은 오점이 그를 여전히 괴롭히고 있지. 이제 날 내버려 $B$B둬. 불모의 땅 북쪽 산기슭을 따라 도로 서쪽에서 브랑을 찾아봐."},objectives={{66,2033283339},"노비의 벨트와 은화 20개를 가지고 불모의 땅에 있는 브랑 와일드고어에게 가세요."},progress={"A customer! Greetings, $C. Take a look at what I have to offer.","고객님! 안녕하세요,$C님. 제가 제공하는 상품들을 살펴보세요."},completion={{271,2141117096},"키로가 보낸 게 틀림없어. 그 저주받은 여자한테 내 능력을 알려줘서 손님을 보내게 할 생각은 전혀 없었어!$B$B만약 그녀에게 정말 급한 이유가 있다면, 그냥 동전을 주고 악마의 표식을 보여줘. 하지만 그 표식의 출처에 대한 내 대답이 마음에 들지는 장담 못 해."}}
rows[80323]={title={{21,85201387},"우리를 묶는 거짓말"},description={"The magic that etched this belt came from Neeru Fireblade. I still cannot read the inscription, but with Neeru's hand in this, I can assure you that it is powerful. Go on your way now, $C. I don't need the wrath of Neeru or his minions targeting me.","이 벨트에 새겨진 마법은 네루 파이어블레이드의 힘에서 비롯된 것이다. 아직 그 문양을 해독할 수는 없지만, 네루의 손길이 닿은 만큼 강력한 마법임은 확실하다. 자, 이제 $C가거라, . 네루와 그의 부하들의 분노를 사고 싶지 않으니."},objectives={{37,1702637702},"노비의 벨트를 가지고 가즈로에게 돌아가세요."},progress={"Welcome back, $N. You still have the belt?","$N님, 다시 오신 것을 환영합니다. 벨트는 아직 가지고 계신가요?"},completion={"Interesting.$B$B<Gazlowe turns the belt over in his hands.>$B$BNeeru Fireblade, eh? I wonder what Neeru is trying to pull right under Thrall's nose?$B$BGo on, now, $N. I've got a few contacts to reach out to. I'll get in touch with you when the next step is to be taken.","흥미롭군.$B$B<가즐로우가 벨트를 손에 쥐고 이리저리 돌려본다.>$B$B네루 파이어블레이드라니? 네루가 스랄의 코앞에서 무슨 짓을 꾸미고 있는 걸까?$B$B자, 어서.$N연락해야 할 사람들이 몇 명 있어. 다음 단계가 정해지면 다시 연락드리지."}}
rows[80330]={title={{17,1574151063},"사냥꾼의 길"},description={{359,989869023},"안녕하세요, 젊은 사냥꾼이시군요. 보아하니 짐승을 다루고 길들여 동반자로 삼을 만큼 실력이 좋아 보이네요. 저희 $B$B사냥꾼들은 보통 애완동물을 곁에 두지만, 당신 같은 분들은 좀... 독특한 방법을 쓴다고 들었습니다. 어쨌든, 자신만의 애완동물을 길들이는 법을 배우고 싶다면 레이저 힐에 있는 비즈 피즈비스트에게 말을 걸어보세요."},objectives={{65,703208141},"칼바위 언덕에서 비즈 피즈비스트와 대화하십시오."},completion={{160,725318553},"내가 너에게 뭘 가르쳐주길 바라는 거야?"}}
rows[80331]={title={{16,967004350},"야수를 길들이기"},description={{663,1992024935},"워워, 진정해, 꼬맹이! 야생 짐승을 길들이고 싶어 안달난 건 알겠는데, 함정이 있어. 우리 고블린들은 자연과 그렇게 잘 지내는 사이가 아니거든, 무슨 말인지 알지?<비즈는 $B$B씁쓸하게 웃는다.>$B$B 내가 고블린식으로 어떻게 하는지 보여줄게. 이 막대기 보이지? \"친구 요청\"이라고 부르는 특별한 목걸이가 달려 있어. 이걸 야생 동물의 목에 걸어주면 그 동물이 네 절친이 되는 거야, 알겠어?<비즈는 으레 쉬운$B$B 것부터 시작해야겠군. 흉포한 얼룩무늬 멧돼지는 간단할 거야. 레이저 힐 바로 외곽에서 어슬렁거리는 걸 볼 수 있을 테니까.<비즈는 으레 꼬맹이도$B$B 그 정도는 할 수 있을 거야. 그러니 멧돼지 한 마리도 안 가져오고 다시 와서 내 시간을 낭비하지 마!"},objectives={{127,1173508487},"길들이기 막대를 사용하여 흉포한 얼룩무늬 멧돼지를 길들이세요. 길들이기 기술을 연습한 후, 레이저 힐에 있는 비즈 피즈비스트에게 길들이기 막대를 돌려주세요."},progress={{33,2036953147},"자, 그럼 어서 해 봐. 누가 보스인지 보여줘 봐."},completion={{98,1022556016},"그러니까 당신이 완전히 무능한 건 아니라는 거군요. 좋아요, 그럼 당신의 야수 조련 실력을 제대로 시험해 볼까요!"}}
rows[80332]={title={{16,967004350},"야수를 길들이기"},description={{704,2030879179},"꼬마야, 애완동물을 한 마리씩 모을 때마다 넌 더 강해지는 거야. 애완동물은 마치 너의 일부와 같단다. 우리 고블린들은 힘은 약할지 몰라도 머리는 최고지. 동물을 네 힘의 원천으로 삼고, 넌 계획을 세워! 그리고 누가 $B$B우두머리인지 보여줄 때도 마찬가지야, 알겠어? 짐승을 억지로 굴복시키려 하지 말고, 머리로 따돌리면 되지 $B$B않겠어? 자, 이제 난이도를 한 단계 높여볼까. 다음 녀석을 잡으려면 발을 물에 담가야 할 거야. 이 녀석은 바다를 정말 좋아하는데, 특히 남쪽 트롤 마을 근처를$B$B 좋아하거든. 어디 있는지 알지? 센진 마을? 에코 제도 근처에 있는 곳 말이야. 서핑 크롤러를 잘 찾아 \"친구 신청\"을 보내고, 나한테 데려와 줘."},objectives={{122,852672860},"길들이기 막대를 사용하여 서핑 크롤러를 길들이세요. 실력을 갈고닦은 후, 길들이기 막대를 레이저 힐에 있는 비즈 피즈비스트에게 돌려주세요."},progress={{104,259748420},"자, 어때? 꼬맹아! 게 한 마리도 못 길들이는데 악어를 길들이겠다는 꿈은 접는 게 좋을 거야!"},completion={{196,1789528147},"정말 쉽게 해내는 것 같군! 자네는 사냥꾼으로서 밝은 미래가 기다리고 있어. 금세 용들을 사냥하게 될 걸세.$B$B그건 확실해요. 전 이런 일에 직감이 좋거든요."}}
rows[80333]={title={{16,967004350},"야수를 길들이기"},description={{593,79843444},"자, 이제 마지막 시험 시간이야, 챔피언. 제대로 준비하는 게 좋을 거야. 안 그러면 숨도 못 쉬고 돌아올 테니까. 우리 오크 친구들은 이 $B$B녀석들을 갑옷 전갈이라고 부르지. 이 녀석들은 작은 다리로 재빠르게 움직이고, 껍데기는 가볍지만 단단해. \"갑옷\"이라는 이름에 딱 어울리지. 게다가 치명적인 독침까지 가지고 있으니, 하나라도 손에 넣으면 다시는 누구도$B$B 널 함부로 대할 수 없을 거야. 돌아오면 정말 멋진 걸 보여줄게. 친구, 이 기술들은 정말 대단해! 원하는 짐승은 뭐든지 길들일 수 있고, 마음대로 부르고 불러낼 수 있게 될 거야."},objectives={{126,677416557},"길들이기 막대를 사용하여 갑옷전갈을 길들이세요. 실력을 갈고닦은 후, 길들이기 막대를 레이저 힐에 있는 비즈 피즈비스트에게 돌려주세요."},progress={{155,422885195},"어서 움직여, 꼬마야. 전설적인 야수 조련사가 될 기회를 놓치고 싶니? 전갈 독에 중독되어 죽는 것도 마찬가지니까... 그렇게 큰 위험을 감수하지 마."},completion={{657,1024300027},"꼬마야, 정말 많이 컸구나! 이렇게 빨리 자랐다니. 이 늙은 고블린도 눈물이 날 것 같군. 거의. 상품 고마워. 정말 훌륭한 상품들이군. 자, 이제 네가 직접 하나를 골라야 해.$B$B내가 아는 모든 걸 가르쳐줬고, 내 여분의 목걸이도 줬지. 거의 부서지지 않지만, 그래도 조심해서 다뤄야 해, 알겠지?$B$B이제부터 원할 때마다 애완동물을 소환하고 해제할 수 있어. 이 훈련을 통해 쌓아온 자신감을 마음껏 발휘하면 머지않아 이 땅의 모든 생물들이 너를 주인님이라고 부를 거야.$B$B곧 너와 네 애완동물은 누구도 막을 수 없는 콤비가 될 거야! 아, 그리고 그날이 오면 수업료를 내야지."}}
rows[80334]={title={{16,967004350},"야수를 훈련시키다"},description={{475,158547294},"마지막으로 한 가지 팁을 주겠다, 꼬마야! 물론 네 계산서에 약간의 추가 비용이 들겠지만 말이지. 오그리마에 오르막 그림샷이라는 오크가 있는데, 그 녀석이 네가 길들인 짐승들을 훈련시키는 법을 가르쳐$B$B 줄 거야.뭐? 네가 멋진 사냥꾼이 되려고 애완동물을 데리고 다니면서 그 애완동물이 멋진 재주를 부리지 못하게 하려는 거야? 꼬마야, 마음에 드는데.$B$B 재밌는 녀석이군!오르막은 오크들이 명예의 계곡이라고 부르는 곳에서 찾을 수 있어. 자, 이제 가거라! 다음에 만날 때는 내가 네 집 문 앞에 나타나서 내 보수를 받을 때겠지."},objectives={{39,1862177294},"오그리마에 있는 오르막 그림샷과 대화하세요."},completion={"A young $c, I see. Yes, I will grant you the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.$B$BNow, go, $c. We will speak again, at a later date.","젊은$c이로군. 좋아, 네 애완동물을 훈련시키고 이끌어줄 기술을 전수해 주겠다. 애완동물에게 새로운 능력을 가르칠 수 있을 뿐만 아니라, 먹이를 주고 전투에서 쓰러진 애완동물을 되살릴 수도 있게 될 것이다.$B$B자, 이제 가거라,$c. 나중에 다시 이야기하자."}}
rows[80339]={title={{17,1574151063},"사냥꾼의 길"},description={{269,839076493},"안녕하세요, 젊은 사냥꾼이시군요. 보아하니 짐승을 다루고 동료로 훈련시킬 만큼 실력이 있어 보이네요. $B$B보통이라면 그리프 와일드하트에게 보내겠지만, 동족의 도움이 필요할 것 같으니 카라노스에 있는 클로버 스핀피스톨에게 부탁해 보는 게 좋겠습니다."},objectives={{41,873017933},"카라노스에 있는 클로버 스핀피스톨과 대화하세요."},completion={{54,1498463555},"안녕하세요! 음... 제가 도와드릴 수 있을 것 같네요!"}}
rows[80340]={title={{16,967004350},"야수를 길들이기"},description={{637,156569906},"저는 클로버 스핀피스톨, 등산가이자 저격수입니다. 사격 솜씨는 좋지만, 안타깝게도 우리 같은 작은 생명체들은 근접전에는 그다지 적합하지 않죠. 하지만 걱정 마세요! 짐승이 대신 싸워주면 되니까요! 팅커 $B$B타운 최고의 천재들이 최근 놀라운 과학적 발견을 해냈습니다. 우리를 맛있고 한입 크기로 여기는 큰 동물들을 상대하는 데 있어서 우리의 부족한 실력을 해결할 수 있는 방법이죠.$B$B 자네는 유망한 명사수 같군. 놈리건을 되찾기 위한 우리의 노력에 꼭 필요한 인재야! 이를 위해 특허받은 G.N.O.E.M.R. 길들이기 지팡이 사용법을 가르쳐주지.$B$B 이걸 받아서 큰 바위멧돼지에게 써보도록 해. 꼭 큰 멧돼지여야 해!"},objectives={{128,656948769},"길들이기 막대를 사용하여 대형 바위 멧돼지를 길들이세요. 실력을 갈고닦은 후, 길들이기 막대를 카라노스에 있는 클로버 스핀피스톨에게 돌려주세요."},progress={{127,1050207351},"길들이는 데 성공했나요? 잘 됐나요? 걱정 마세요. 이 멧돼지의 성격이 마음에 안 들면 다른 멧돼지를 길들일 수 있어요."},completion={{125,91480470},"와! 정말 잘하셨네요. 이 낚싯대는 확실히 추가 테스트가 필요하고, 그 과정에서 더 나은 짝을 찾을 수도 있을 거예요."}}
rows[80341]={title={{16,967004350},"야수를 길들이기"},description={{427,467402724},"하하! 와, 저 멧돼지는 정말 크네요! 하지만 당신은 노움에게 더 어울리는 동물을 원할 것 같군요. 재빠르고 위풍당당한 눈표범은 어떠세요?여기 남쪽과 $B$B동쪽에서 찾을 수 있어요. 제가 당신의 G.N.O.E.M.R. 길들이기 막대를 충전해 놨으니, 이제 나가서 눈표범을 잡으러 가세요!하지만 조심하세요.$B$B 눈표범은 저 멧돼지보다 훨씬 사납답니다! 절대 얕보지 마세요. 그렇지 않으면 고양이 사료 신세가 될지도 몰라요!"},objectives={{125,714364862},"길들이기 막대를 사용하여 눈표범을 길들이세요. 실력을 갈고닦은 후, 길들이기 막대를 카라노스에 있는 클로버 스핀피스톨에게 돌려주세요."},progress={{87,792635213},"눈표범은 눈 속에 잘 위장하기 위해 흰색 바탕에 점박이 무늬를 가지고 있습니다. 그래서 찾기가 어려울 수 있습니다."},completion={{120,390502187},"멋지네요! 정말 예쁜 고양이군요! 물론, 결국 어떤 동물을 길들이고 싶은지는 당신에게 맡기겠습니다."}}
rows[80342]={title={{16,967004350},"야수를 길들이기"},description={{626,1323748621},"한 가지 말씀드릴 점은 멧돼지와 표범 모두 공격적인 애완동물이지만 방어 능력은 다소 부족하다는 것입니다. 우리의 원거리 무기는 어떤 적이든 쉽게 처치할 수 있으므로, 적들의 주의를 분산시킬 무언가가 필요합니다. $B$B음... 좋은 생각이 났어! 얼음발톱곰은 튼튼하고 끈질기지. 화난 곰을 마주했을 때 누가 조그마한 노움을 공격하겠어?$B$B 얼음발톱곰은 카라노스 동쪽에서 찾을 수 있어. 이제 충분한 경험과 기술을 갖췄으니 충분히 상대할 수 있을 거야. 모든$B$B 준비가 끝나면, 원하는 대로 애완동물을 길들일 수 있도록 완성된 길들이기 지팡이를 줄게!"},objectives={{127,48618511},"길들이기 막대를 사용하여 얼음 발톱 곰을 길들이세요. 실력을 갈고닦은 후, 길들이기 막대를 카라노스에 있는 클로버 스핀피스톨에게 돌려주세요."},progress={{33,1897251272},"아이스 클로 베어 얻으셨나요?"},completion={"Well done, $N! Marvelous! Together we've proven to those snooty dwarves that we gnomes are just as capable Mountaineers as they are! Your brilliant success is more than enough to stifle any further snickering and teasing.$B$BFor that, I thank you, $N. As promised, here's the schematic and instructions for the G.N.O.E.M.R. Taming Rod!$B$BNow get out there, find yourself a companion, and show the world Gnomeregan's best!","정말 잘했어,$N! 훌륭해! 우리 둘이서 거만한 드워프들에게 우리 노움들도 그들 못지않게 유능한 산악인이라는 걸 증명해냈어! 네 눈부신 성공 덕분에 더 이상 비웃거나 놀릴 필요가 없겠군.$B$B, 고맙다,$N. 약속대로 G.N.O.E.M.R. 길들이기 지팡이의 설계도와 설명서를 보내주지!$B$B자, 이제 나가서 동료를 찾고 그놈레건 최고의 실력을 세상에 보여주렴!"}}
rows[80343]={title={{18,534037912},"야수를 훈련시키다"},description={"Now that you've got your rod and all, $N, you can tame companions of your own to help advance the cause of all gnomekind!$B$BHowever, taming them isn't enough on its own. They also need training, and sadly, I don't have that knowledge to share. Even though you've done well under my tutelage, I can't mentor your pet! For that, you'll need to find someone else.$B$BI know just the person for the job, too! If you're ever in Ironforge, there's a dwarf named Belia Thundergranite in the Hall of Arms. She should be able to help you out. Be sure to tell her I sent you!$B$BGood luck!","이제 지팡이도 얻었으니, , 너도 $N자신만의 동료들을 길들여 모든 노움 종족의 대의를 위해 힘을 보탤 수 $B$B있겠구나!하지만 길들이는 것만으로는 충분하지 않아. 훈련도 필요하지. 그런데 안타깝게도 난 그 지식을 전해줄 수 없어. 내 가르침 아래서 꽤 잘해왔지만, 네 애완동물을 훈련시켜줄 순 없단다! 그러려면 다른 사람을 찾아야$B$B 할 거야.$내가 딱 맞는 사람을 알고 있지! 아이언포지에 가게 되면 무기고에 벨리아 썬더그래나이트라는 드워프가 있어. 그녀가 도와줄 수 있을 거야. 꼭 내가 보냈다고 전해줘!행운을$B$B 빌어!"},objectives={{45,734694239},"아이언포지에 있는 벨리아 썬더그래나이트와 대화하세요."},completion={"Spinpistol sent you? That must mean her hairbrained scheme panned out after all. That wee lass you trained with actually managed to accomplish her crazy scheme of taming beasts, then? I'll be... And you helped her? You're clearly more than meets the eye, already on your way to becoming a great $c, I see.$B$BVery well. I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, but you will also be able to feed your pet as well as revive it if it falls in battle.$B$BRemember that the key to getting the most from your new pet is to respect it and treat it well. In turn, your pet will be your most loyal friend.","스핀피스톨이 보냈다고요? 그럼 그 엉뚱한 계획이 결국 성공했군. 네가 같이 훈련했던 그 꼬맹이가 짐승 길들이기라는 미친 계획을 정말로 이뤄냈다는 말인가? 세상에... 그리고 네가 그 애를 도왔다고? 넌 겉모습보다 훨씬 대단한 재능을 가졌군. 벌써 위대한$c이 될 자질을 갖췄군.$B$B좋아. 네 애완동물을 훈련시키고 이끌어줄 기술을 전수해 주겠다. 애완동물에게 새로운 능력을 가르칠 수 있을 뿐만 아니라, 먹이를 주고 전투에서 쓰러진 애완동물을 되살릴 수도 있게 될 것이다.$B$B새 애완동물을 최대한 활용하는 비결은 존중하고 잘 대해주는 것임을 기억하거라. 그러면 네 애완동물은 너의 가장 충실한 친구가 될 것이다."}}
rows[80350]={title={{11,1157957720},"새겨진 룬"},description={{253,1331318142},"네가 날 도와주는 동안, 이 룬을 받았는데 너에게 전해달라는 거야. 시간 날 때 한번 읽어 봐. 아마 사냥꾼 훈련가 토르가스가 준 것 같아. 룬을 잘 살펴보고, 시간 나면 안빌마르 안에서 토르가스를 찾아가 봐."},objectives={{70,497645633},"새겨진 룬 문자를 읽고 콜드리지 계곡에 있는 토르가스 그림슨과 대화하세요."},progress={"Ya made it! Good to hear! Betcha didn't have to track me to find the place either. Haha!$B$BOur profession is pretty steeped in tradition, $N. Learning the ways of the land. Learning to track a bear through the mountains. Even just surviving on wits alone takes a great deal of courage and cunning. Think you're capable?$B$BCan't say I'm sure ye've got what it takes. A gnome hunter, eh? I can see you're determined to succeed and put your own twist on the profession, though, so who am I to stop ye?","오셨군요! 잘됐네요! 저를 쫓아올 필요도 없었겠죠? 하하!$B$B우리 직업은 전통이 아주 깊습니다.$N이 땅의 풍습을 배우고, 산속에서 곰을 추적하는 법을 배우는 거죠. 오로지 지혜만으로 살아남는 것조차 상당한 용기와 기지가 필요합니다. 할 수 있겠습니까?$B$B글쎄요, 확신할 수는 없겠네요. 노움 사냥꾼이라니? 하지만 성공하겠다는 의지가 강하고, 이 직업에 자신만의 색깔을 입히고 싶어 하는 것 같으니, 제가 뭐라고 말리겠습니까?"},completion={{534,664575140},"한 가지 꼭 기억해야 할 것은 당신이 살고 있는 세상을 존중해야 한다는 것입니다. 당신과 함께 싸우기로 선택한 짐승들, 무기의 반짝임, 탄약의 무게, 매서운 바람의 감촉, 이 모든 것을 속속들이 알아야 합니다.$B$B드워프들이 기술과 기계에 아무리 집착한다 해도, 사냥꾼에게 자연에 대한 존중은 필수적이라는 것을 절대 잊지 마십시오. 제가 할 수 있는 한 도와드리겠지만, 대부분의 일은 당신에게 달려 있습니다. 언제든 준비가 되었다고 생각되면 돌아와서 이야기하십시오. 제가 할 수 있을 때 훈련시켜 드리겠습니다."}}
rows[80352]={title={{20,1976358198},"돈 낭비"},description={"They had one job, $N, one!$B$BI asked those fools to be careful while transporting the oil and look at what they did. They probably had the mindless ogre on the ship's wheel.$B$BPlease sweety, do me a favour will you?$B$BGet as much oil as you can from the barrels, we need it for our machinery to work. This swamp isn't at all forgiving, we need to defend ourselves, you know.$B$BAnyway good luck comes with good coin so as soon as you have it come back.","그들에게는 딱 한$N 가지$B$B 일만 시키면 됐는데! 내가 그 바보들에게 기름 운반할 때 조심하라고 했는데, 꼴 좀 봐. 아마 그 멍청한 괴물이 키를 잡고 $B$B있었겠지. 여보, 부탁 하나만 $B$B들어줄래? 드럼통에서 기름을 최대한 많이 꺼내 줘. 기계 돌아가려면 기름이 필요해. 이 늪은 정말 가혹해. 우리 스스로를 지켜야 하잖아. $B$B어쨌든 행운은 돈과 함께 찾아오니까, 돈 생기는 대로 돌아와 줘."},objectives={{56,1277712739},"머드스프로켓에 있는 빅시 댐프놉에게 기름 5통을 가져다 주세요."},progress={{25,1713360491},"석유를 찾는 데 성공했나요?"},completion={"$N, you're a doll! This is great, I can't thank you enough.$B$BIf you get any more you know where to find me.","$N, 정말 최고예요! 너무 감사해요.$B$B혹시 더 필요하면 저한테 연락 주세요."}}
rows[80353]={title={{20,538954554},"불명확한 지침"},description={{438,1154692442},"오우거에게 나무를 좀 패달라고 부탁했더니, 결국 걔가 딴 나무를 가져가는 걸 잊어버릴 줄 누가 알았겠어? $B$B멍청한 놈이 나무를 계속 패더니 돌아올 땐 아무것도 안 가져왔잖아! 내가 직접 가지러 갈$B$B 수도 있지만, 지금 좀… 바빠서. 그러니까 네가 좀 해 줄래? 여기 $B$B사람들은 일하는 사람을 존중해. 네가 한 일에 대한 대가를 줘야 해. 가서 $B$B나무 몇 묶음 가져와."},objectives={{71,1865014910},"갓 자른 나무 10묶음을 모아 머드스프로켓에 있는 퀵 페들린에게 가져다 주세요."},progress={{79,1092522141},"믿을 수 있어? 그가 다시 자르기 시작했어!$B$B제발 몇 개라도 돌려받았다고 말해줘."},completion={{129,1331855506},"아, 그래요, 정말 좋네요. 저기 던져 놓으세요. 여기 급여입니다.$B$B필요하면 언제든 여기서 일할 수 있어요."}}
rows[80360]={title={{24,1551510211},"빼앗긴 권력, 주어진 권력"},description={{556,2029004412},"옛 세계의 숲에서 칼림도르의 새로운 보금자리까지 오는 여정은 우리에게 고된 여정이었을 뿐만 아니라, 그 여정에서 우리를 지켜준 로아들에게도 마찬가지였습니다. 수천 년 동안 누비던 숲에서 너무나 멀리 떨어진 이곳에서, 그들은$B$B 약해져 있습니다. 남쪽 멀리 줄파락의 모래분노 트롤들은 구루바쉬의 정글에서 멀리 떨어져 있음에도 불구하고 킴불과 연결을 유지해 왔습니다. 킴불의 힘을 찾아 내게 가져오시오. 모래분노가 부여한 힘을 사용하여 이 이국땅에서 우리 로아들의 존재감과 힘을 강화하겠습니다."},objectives={{59,1891851070},"킴불의 주주 5개를 얻어 신비로운 구아이진에게 가져가세요."},progress={{73,1405782029},"아킬다라는 그녀가 가진 모든 힘으로 당신의 등 뒤에서 불어오는 바람을 축복했습니다."},completion={{253,2126889266},"우리의 로아들이 이곳을 자신들의 집처럼 느끼기까지는 시간이 걸릴 것이며, 우리 또한 이곳을 우리의 집으로 받아들이기까지는 시간이 걸릴 것입니다. 우리는 함께 성장하며 그들의 영혼을 보살필 것이고, 그들은 우리의 집을 지켜줄 것입니다. 그때까지 할라치의 교활함이 당신의 정신을 지켜주기를 바랍니다."}}
rows[80366]={title={{17,1574151063},"사냥꾼의 길"},description={{547,920783551},"안녕, 젊은 레인저, 잘 지내는 것 같군! $B$B우리 부족은 어려움을 겪고 있지만, 우리는 견뎌내야 하고, 이전보다 더 강해져야$B$B 한다. 우리 레인저들은 쿠엘탈라스와 그 숲을 지키도록 훈련받았지만, 이제는 완전히 새로운 환경에서 활동해야 $B$B한다. 나는 레인저 부대의 남은 역량을 향상시키기 위해 동맹의 기술을 배워야 한다고 생각한다. 던 $B$B모로그에는 그리프 와일드하트라는 드워프가 있는데, 그는 짐승들을 마음대로 조종할 수 있다고 한다. 그런 기술은 자네에게 유용할 것이니, 그에게서 배워보도록 하시오."},objectives={{38,92303317},"카라노스에 있는 그리프 와일드하트와 대화하세요."},progress={{4,273767400},"예?"},completion={{103,1106713024},"이게 뭐지? 빌어먹을 엘프가 내게 배우러 왔다고? 하하, 영광이로군. 그래, 어쩌면 자네가 배울 때가 된 것 같군."}}
rows[80369]={title={{14,1790825835},"따뜻한 느낌"},description={"Ah, you have made your way back once more, $N. That is simply splendid, for I may have another task for you.$B$BNestled far in the south lies a coven of supremely ferocious creatures known as Owlbeasts. The place of their dwelling, known as Owl Wing Thicket, is renowned for being the home of a particularly bizarre herb.$B$BMight I trouble you to kindly gather me around twenty of these precious plants? The Owlbeasts should have them on their person as a light snack.","아, 다시 돌아오셨군요, . 정말$N 반갑습니다. 자네에게 또 다른 임무가 있을지도 $B$B모르겠습니다. 남쪽 먼 곳에는 올빼미 괴물이라 불리는 극도로 흉포한 생물들이 살고 있습니다. 그들의 서식지인 올빼미 날개 덤불은 아주 특이한 약초의 산지로 $B$B유명합니다. 부디 이 귀한 약초를 스무 개 정도 구해다 주시겠습니까? 올빼미 괴물들이 간식으로 즐겨 먹는 식물입니다."},objectives={{35,775650380},"동계차 잎 20장을 모으세요."},progress={{24,35458892},"사냥은 잘 되셨나요?"},completion={{71,1850063667},"아, 좋습니다. 잠시만 기다려 주시면 차를 끓여 드리겠습니다. 맛보세요."}}
rows[80370]={title={{39,1293671337},"양모 기증: 실버문 자투리"},progress={{445,1300183339},"현재 양모 천 기부를 받고 있습니다. 양모 천 60장을 기부해 주시면 알라탈라스께서 당신의 관대한 행동에 대해 온전히 인정해 주실 것입니다. 저희 창고에는 양모가 충분히 있어서 60장만 있으면 됩니다. 영역 내 다른 분들로부터도 충분한 양을 구할 수 있을 것입니다.$B$B양모 천 60장을 가지고 계시고 기부하실 준비가 되셨다면 지금 바로 받아 가겠습니다."},completion={"Wonderful! We thank you for your generous donation, $N!","정말 감사합니다!$N님의 아낌없는 기부에 진심으로 감사드립니다!"}}
rows[80371]={title={{39,1121744605},"실크 기증: 실버문 잔해"},progress={{435,1594521582},"다른 대부분의 직물과 마찬가지로 저희 실크 재고도 역대 최저 수준입니다. 저희 매장 사정상 실크 60장만 있으면 목표량을 달성할 수 있을 것 같습니다. 다른 분들의 도움도 주시면 충분히 가능할 것 같습니다.$B$B실크와 같은 귀한 기증은 지역 사회에서 귀하의 위상을 높이는 데 큰 도움이 될 것입니다! 실크 60장을 가지고 계시고 기증하실 의향이 있으시다면 지금 바로 받아갈 수 있습니다."},completion={"Wonderful! We thank you for your generous donation, $N!","정말 감사합니다!$N님의 아낌없는 기부에 진심으로 감사드립니다!"}}
rows[80372]={title={{44,2053323719},"마법직물 기증: 은달의 잔해"},progress={{415,645832727},"마법직물이 부족해지고 있습니다. 재고를 채우는 데 여러분의 도움이 절실히 필요합니다! 공동체 전체의 도움을 받는다면, 여러분께서 마법직물 60장만 기부해 주시면 목표 달성이 가능합니다. 이러한 관대한 기부는 알라탈라스 신들께서 결코 잊지 않으실 것입니다!$B$B만약 마법직물 60장을 가지고 계시고 기부하실 의향이 있으시다면, 지금 바로 받아가겠습니다."},completion={"Wonderful! We thank you for your generous donation, $N!","정말 감사합니다!$N님의 아낌없는 기부에 진심으로 감사드립니다!"}}
rows[80373]={title={{44,1537208393},"룬천 기증: 실버문 잔해"},progress={"$N, you've been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We'll initially accept a single donation of sixty, and then we'll go from there.","$N님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 도움을 주시면 정말 감사하겠습니다!$b님,$b님, 가능하시다면 여분의 룬천을 가져다주시면 감사하겠습니다. 처음에는 60개씩 한 번에 기증받고, 그 후 상황을 봐가면서 진행하겠습니다."},completion={{363,695128813},"정말 훌륭합니다! 이 물품들은 바로 사용하겠습니다. 다시 한번 도움 주셔서 감사합니다! 당신이 없었다면 정말 큰일 날 뻔했어요.$b$b지금까지 보내주신 모든 기부금 덕분에 앞으로 추가로 기부해 주시는 룬천도 기꺼이 처리해 드리겠습니다. 저에게 알려주시면 당신의 선행이 헛되지 않도록 제가 직접 확인하겠습니다!"}}
rows[80374]={title={{41,409716785},"추가 룬천: 실버문 잔해"},progress={{73,1454875748},"룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다."},completion={"Greetings once again, $N! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of Alah'thalas.","$N님, 다시 한번 인사드립니다! 저희는 룬천이 항상 필요하며, 기꺼이 나눠주신다면 언제든 환영입니다. 룬천 20묶음을 추가로 보내주시면 알라탈라스를 위해 꾸준히 노력해주시는 데 대한 감사를 표하겠습니다."}}
rows[80375]={title={{35,465167675},"양모 기증: 레반터스크 부족"},progress={{444,328549793},"현재 양모 천 기부를 받고 있습니다. 양모 천 60장을 기부해 주시면 아마니알로르께서 당신의 관대한 행동에 대해 온전히 인정해 주실 것입니다. 저희 창고에는 양모가 충분히 있어서 60장만 있으면 됩니다. 왕국 내 다른 분들로부터도 충분한 양을 구할 수 있을 것입니다.$B$B양모 천 60장을 가지고 계시고 기부하실 준비가 되셨다면 지금 바로 받아 가겠습니다."},completion={"Wonderful! We thank you for your generous donation, $N!","정말 감사합니다!$N님의 아낌없는 기부에 진심으로 감사드립니다!"}}
rows[80376]={title={{35,2077962219},"실크 기증: 레반터스크 부족"},progress={{435,1594521582},"다른 대부분의 직물과 마찬가지로 저희 실크 재고도 역대 최저 수준입니다. 저희 매장 사정상 실크 60장만 있으면 목표량을 달성할 수 있을 것 같습니다. 다른 분들의 도움도 주시면 충분히 가능할 것 같습니다.$B$B실크와 같은 귀한 기증은 지역 사회에서 귀하의 위상을 높이는 데 큰 도움이 될 것입니다! 실크 60장을 가지고 계시고 기증하실 의향이 있으시다면 지금 바로 받아갈 수 있습니다."},completion={"Wonderful! We thank you for your generous donation, $N!","정말 감사합니다!$N님의 아낌없는 기부에 진심으로 감사드립니다!"}}
rows[80377]={title={{40,516505450},"마법매듭 기증: 레반터스크 부족"},progress={{414,970187363},"마법직물이 부족해지고 있습니다. 재고를 채우는 데 여러분의 도움이 절실히 필요합니다! 공동체 전체의 도움을 받는다면, 여러분께서 마법직물 60장만 기부해 주셔도 목표 달성이 가능합니다. 여러분의 이러한 관대한 마음은 아마니알로르 신께서 결코 잊지 않으실 것입니다!$B$B만약 마법직물 60장을 가지고 계시고 기부해 주실 의향이 있으시다면, 지금 바로 받아가겠습니다."},completion={"Wonderful! We thank you for your generous donation, $N!","정말 감사합니다!$N님의 아낌없는 기부에 진심으로 감사드립니다!"}}
rows[80378]={title={{40,668440256},"룬천 기증: 레반투스크 부족"},progress={"$N, you've been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We'll initially accept a single donation of sixty, and then we'll go from there.","$N님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 도움을 주시면 정말 감사하겠습니다!$b님,$b님, 가능하시다면 여분의 룬천을 가져다주시면 감사하겠습니다. 처음에는 60개씩 한 번에 기증받고, 그 후 상황을 봐가면서 진행하겠습니다."},completion={{363,695128813},"정말 훌륭합니다! 이 물품들은 바로 사용하겠습니다. 다시 한번 도움 주셔서 감사합니다! 당신이 없었다면 정말 큰일 날 뻔했어요.$b$b지금까지 보내주신 모든 기부금 덕분에 앞으로 추가로 기부해 주시는 룬천도 기꺼이 처리해 드리겠습니다. 저에게 알려주시면 당신의 선행이 헛되지 않도록 제가 직접 확인하겠습니다!"}}
rows[80379]={title={{37,1832788967},"추가 룬천: 레반투스크 부족"},progress={{73,1454875748},"룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다."},completion={"Greetings once again, $N! Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them. For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of Amani'alor.","$N님, 다시 한번 인사드립니다! 저희는 룬천이 항상 필요하며, 기꺼이 나눠주신다면 언제든 환영입니다. 룬천 20묶음을 추가로 보내주시면, 아마니알로르를 위해 꾸준히 노력해주시는 데 대한 감사를 표하겠습니다."}}
rows[80380]={title={{18,429448426},"리지의 경쟁자"},description={{799,1847259307},"많은 사람들에게 음식을 대접해야 하는데, 경쟁자 중 한 명이 내 고기 공급처를 모두 $B$B끊어버렸어! 그놈이 누군지는 몰라도 내 최고급 갈비와 맥주 반죽 해산물 튀김을 질투하는 게 분명해. 내 명성대로라면 내가 그 자리를 채우는$B$B 건 쉽지 않겠지. 하지만 내가 만든 최고의 바비큐로 그들이 나를 건드린 걸 후회하게 만들어 줄 거야! 자, 그럼 뭘 해줄까? 솔트크랩 가문의 비법을 하나 알려줄게. 어떤 장소든 멋진 피크닉 장소로 만들$B$B 수 있는 비법이지. 작은 게와 악어 가족들을 모두 모아서 작별 인사를 하게 한 다음, 내장을 가져와.$B$B 사슴고기는 네가 모험을 하다 보면 알게 될 몇몇 공급업체에서 구할 수 있고, 바비큐에 바를 맥주도 $B$B필요해. 서둘러, 파티 시작 전에 다 요리해야 하니까!"},objectives={{61,846311929},"리지가 지금까지 누구도 맛보지 못한 최고의 바비큐를 만들 수 있도록 도와주세요."},progress={"Time's a-tickin', bub. Can't waste what's left of it before this big palooza so I can surprise the culprit with my amazing spicy crab souffle. It's a cutthroat cooking competition out here that drives people to do these crazy things, $N, but I'm always one step ahead.","시간이 얼마 안 남았어, 친구. 이 큰 축제 전에 남은 시간을 낭비할 순 없어. 범인을 놀라게 해 줄 환상적인 매콤한 게살 수플레를 만들어야 하거든.$N, 이 요리 경쟁은 정말 치열해서 사람들이 이런 미친 짓까지 하게 만드는 거야. 하지만 난 언제나 한 발 앞서 있지."},completion={"You got the goods? Sweet! I'll get cookin', but first, I promised you the Saltcrabs formula for a perfect brunch, didn't I? Well first, you set down a blanket, then you put up an umbrella! That was worth the effort, now wasn't it? Thanks for the meats, $N. I'm gonna knock the pants off these partygoers!","재료 준비됐어? 좋아! 이제 요리 시작할게. 근데 그전에 내가 솔트크랩스에서 완벽한 브런치를 만드는 비법을 알려주겠다고 약속했었지? 자, 먼저 담요를 깔고, 그다음에 우산을 쳐! 수고한 보람이 있지? 고기 고마워,$N. 오늘 파티 참석자들 제대로 한바탕 해 줄게!"}}
rows[80381]={title={{10,1223397896},"쉘코인"},description={{449,1678758635},"다들 내가 미쳤다고 생각하지만, 5년쯤 지나면 다들 후회하게 될 거야! 소위 \"경제학자\"들이 믿지 않더라도, 난 이 조개껍데기들이 새로운 경제의 핵심이 될 거라고 확신해. 바닷속에 흩어져 있는 반짝이는 $B$B조개껍데기들, 내가 \"셸코인\"이라고 부르는 이 조개껍데기들이 앞으로 대세가 될 거야. 다들 내가 투자하는$B$B 걸 보고 바보라고 하지만, 시장이 폭등하면 난 엄청난 부자가 될 거고, 그들은 내 조개껍데기를 캐내느라 바빠질 걸세."},objectives={{85,115578805},"반짝이는 조개껍데기 20개를 모아 조개 코인 경제를 활성화하고 엘로디아로 돌아가세요."},progress={{92,886541842},"뭘 기다리고 계세요? 지금 바로 사세요!$B$B시세가 폭등하기 전에 서두르세요!"},completion={{189,1333364865},"훌륭한 일이야. 셸코인 가치가 1000골드에 도달하면 내 저택 내부를 구경시켜 줄게.$B$B그동안 내가 입던 낡은 옷 좀 가져가. 네게 맞을 것 같군."}}
rows[80382]={title={{11,379131258},"VIP 초대"},description={{421,1449671903},"무역왕 두 명이 없으면 해변 파티가 무슨 재미가 있겠어? 이번 파티에는 유명 인사들이 꼭 필요해, 안 그러면$B$B 망할 거라고!가장 멋진 옷을 입고 톱니항의 무역왕 가즈로와 무법항의 레빌가즈 남작에게 이 특별 초대장을 전해 줘.$B$B그들이 오면 분명 더 많은 사람들이 따라올 거야. 해변에 사람이 많을수록 내 주머니도 두둑해지잖아, 알겠지? 보답으로 아주 좋은 걸 줄게."},objectives={{93,1727873245},"리사의 해변 파티 초대장을 라쳇에 있는 개즈로와 무법항에 있는 레빌가즈 남작에게 전달하세요."},progress={{98,2144259832},"서둘러요, 안 그러면 내 계획이 망쳐지잖아요! 그 사람들이 내가 초대장을 제일 나중에 보냈다고 생각하면 안 되잖아요."},completion={{358,508665746},"좋아, 내 파티 완전 대박일 거야! 이 친구들이 얼마나 영향력을 발휘할지 정말 기대돼.$B$B진짜 부자라면 바에 있는 술을 통째로 사 올지도 몰라.$B$B다시 한번 도와줘서 고마워. 이 아름다운 해변에서 우리랑 같이 놀지 않을래? (하지만 그런 모습은 아니겠지.) 나랑 어울리려면 제대로 된 옷차림을 갖춰야 해. 이거 받아서 신어봐."}}
rows[80383]={title={{28,407302395},"상어는 친구이지, 먹이가 아닙니다."},description={{531,17162945},"물 위로 솟아오른 등지느러미가 보이시나요? 저건 상어입니다. 해안선에$B$B 너무 가까이 다가온 것 같은데, 이 종에게는 매우 이례적인 일입니다. 저는 해양생물학자인데, 저 불쌍한 생물을 한동안 지켜봐 왔습니다. 상어가 여기에 갇힌 이유는 여러 가지가 $B$B있겠지만, 고블린들은 저 상어를 덫에 걸린 돼지처럼 죽이려고 합니다! 고블린들은 저 상어가 물속에 있는 사람들에게$B$B 위협이 된다고 생각하지만, 상어는 아마 겁에 질리고 혼란스러워하는 것일 뿐입니다. 저는 $B$B그렇게 되도록 내버려 둘 수 없습니다. 당신이 물에 들어가서 상어를 쫓아내야 합니다."},objectives={{77,412807236},"물속의 상어를 해안에서 멀리 쫓아낸 다음 토치 플리퍼에게 돌아가세요."},progress={{72,1190964665},"상어의 골격이 뼈가 아니라 연골로 이루어져 있다는 사실을 알고 계셨나요?"},completion={{253,126341538},"해냈어! 이제 저 상어는 고블린들이 트로피처럼 매달아 놓으려던 짓을 그만두고 바다의 최상위 포식자로서의 삶을 되찾을 수 있겠군.$B$B보상으로 작은 기념품을 줄게. 잘 간직해 둬, 알았지?"}}
rows[80384]={title={{13,1013526427},"소금 한 꼬집"},description={{372,1939141418},"이 게들, 정말 골칫덩어리들이야!$B$B 발톱으로 내 그물을 찢어놓고 물고기들을 다 쫓아내잖아! 내가 쫓아갈 때마다 모래 속에 숨어버리고, 라우티키도 젊었을 때처럼 날렵하지 못하더군. $B$B이제 복수할 때가 됐어, 성가신 조개껍데기 밟는 녀석들이 라우티키를 괴롭힌 대가를 치르게 될$B$B 거야! 녀석들을 잡아서 껍데기를 가져오면 비밀 하나를 알려줄게."},objectives={{46,225493693},"라우티키는 당신에게 게 껍데기 8개를 가져다 달라고 합니다."},progress={{33,96945018},"저것들을 사냥해서 껍데기를 가져오너라!"},completion={{280,2014297767},"아하하하! 잘했어, 친구! 내 몫은...$B$B<라우티키가 껍데기 하나를 깨서 그 안에서 뭔가를 꺼낸다.>$B$B비밀은 이거야, 친구. 이 작고 성가신 녀석을 길들여서 먹이를 주면 꽤 유용할 거야. 하지만 완전히 믿지는 마. 손가락을 깨무는 걸 좋아하거든."}}
rows[80386]={title={{16,919968962},"매일 새로운 기기 하나씩..."},progress={{622,1503773634},"새로운 시작을 하게 될 줄은 꿈에도 생각 못 했어. 호드의 깃발 아래에서 그런 일을 하게 될 줄은 더더욱 상상도 못 했지. 하지만 어쩌다 이렇게 됐는지.$B$B우리는 주머니에 고깃덩어리와 먼지만 가지고 도망쳐 나온 작은 고블린 무리일 뿐이지만, 천천히 이름을 떨쳐낼 거야. 그리고 원한다면 너도 그 일원이 될 수 있어.$B$B노동조합은 날마다 성장하고 있고, 많은 고블린들이 호드의 품에서 새로운 삶의 의미를 찾으러 우리에게 오고 있지만, 우리에게는 수단과 자원이 부족해.$B$B노동조합의 미래에 함께하고 싶다면, 시간이 될 때마다 윙윙거리는 청동 장치를 한 움큼 가져다 줘. 언젠가는 보상을 받게 될 거야."},completion={{50,1205576347},"도와주셔서 정말 감사해요, 계속 보내주세요!"}}
rows[80388]={title={{25,1660270289},"잠시 머물면서 들어보세요..."},description={{627,1026863882},"흠, 또 다른 사람이군? $B$B좋아. 자네는 백성들에게 자신의 능력을 증명하고 싶어하지 않나? 누구보다 강자로 우뚝 서고 싶어하지 않나? 역사 속에서 하찮은 방랑자로 사라지는 대신 용기와 영웅의 유산을 남기고 싶어하지 않나?$B$B 내 말에 귀 기울이는군. 그렇다면 자네에게 딱 맞는 제안이 있지. 영광을 향한 여정에서 죽음을 극복한다면 불멸의 존재가 될 기회를 주겠네. 하지만… $B$B만약 죽는다면 다시는 돌아오지 못할 것이네. 자네의 영혼은 영원히 육체와 분리될 것이네.$B$B 이 제안은 오직 지금 이 자리에서만 하네. 거절한다면 두 번 다시 기회는 없을 것이네."},objectives={{242,546148909},"이 퀘스트를 완료하여 필멸자가 되십시오. 이 모드에서는 목숨이 하나뿐이며, 다른 필멸자 플레이어와만 거래 및 파티를 맺을 수 있습니다. 한 번 죽으면 다시는 돌아올 수 없습니다. 고객 지원팀은 어떤 이유로든 쓰러진 영웅을 부활시키지 않습니다."},completion={"Well then, have you decided, $c? Do you have what it takes to become Immortal? Once you start walking this path, you will not be able to abandon it. It will forever dominate your destiny. Only those who follow the same path will be of aid to you.$B$BNo mail will ever bring you good news. No auction will take your money.$B$BVery well. Should you die, your soul will forever be mine. If you survive the trials ahead, we shall meet again one day.","자, 그럼,$c, 결심했나? 불멸자가 될 자질이 있나? 이 길을 걷기 시작하면 결코 벗어날 수 없을 것이다. 이 길이 영원히 네 운명을 지배할 것이다. 오직 같은 길을 걷는 자만이 너를 도울 수 있을 것이다.$B,$B어떤 우편물도 너에게 좋은 소식을 가져다주지 않을 것이다. 어떤 경매도 네 돈을 가져가지 않을 것이다.$B,$B좋아. 네가 죽으면 네 영혼은 영원히 내 것이 될 것이다. 앞으로 닥칠 시련에서 살아남는다면, 우리는 언젠가 다시 만날 것이다."}}
rows[80390]={title={{21,158388949},"머드스프로켓에게 보내는 편지"},description={{527,1234508957},"투자개발회사 소속이었던 고블린 무리가 호드에 합류했습니다.$B$B 그중 일부는 더스트왈로우 습지에 정착해 머드스프로켓이라는 마을을 세웠는데, 아직 과거의 죄를 용서받지는 못했지만, 보스는 돈 좀 벌 수 있는 사람을 보내 이 편지를 책임자에게 전달하라고 했습니다. 언더마인이$B$B 이 소식을 어떻게 받아들일지는 모르겠지만, 솔직히 제가 신경 쓸 일도 아닙니다. 어쨌든 그들은 더스트왈로우 습지 남쪽에 있으니 조심하세요. 드래곤의 소굴로 착각하지 않도록 주의하십시오.$B$B 잘 가시오."},objectives={{48,1541087902},"그 편지를 머드스프로켓의 리더에게 전달하세요."},progress={{55,511407076},"듀로타르 노동조합, 이름이 꽤 괜찮지 않나요?"},completion={{35,1205758781},"이게 뭐지? 가즈로위한테서 온 편지인가?"}}
rows[80391]={title={{17,440762885},"고기를 찾아 기어가는 중"},description={{980,836988505},"안녕하세요! 환영합니다. 저는 모아키 항구의 이눈쿠아크입니다. 몇 주간의 항해 끝에 이 낯선 땅에 도착했습니다. 제$B$B 이야기는 겨울 타우렌 친구인 부니크가 카누를 타고 제 정착지를 방문하면서 시작됩니다. 그녀는 저를 타운칼레 마을로 초대했습니다. 하지만 제가 카누에 오르자마자 강한 얼음바람이 불어 부니크의 손에서 밧줄을 놓아버렸습니다. 순식간에 강한 해류가 저를 망망대해 한가운데로 휩쓸어갔습니다!$B$B 부니크가 노를 젓고 있었기에 저는 필사적으로 카누에 매달려 그저 운에 맡길 수밖에 $B$B없었습니다. 결국 해류는 저를 고향과는 전혀 다른 이 따뜻한 땅으로 데려왔습니다. 친구여, 카누에 식량이 조금 있었지만 며칠 전에 다 먹어버렸습니다. 근처에 있는 이 껍데기 달린 생물들의 고기를 좀 모아주시겠어요? 북쪽$B$B 먼 곳에도 비슷한 생물들이 있는데, 제가 직접 손질할 도구도 지식도 부족해서 접근하기가 어렵네요. 제 생각에는 먹을 수 있는 생물인 것 같은데, 만약 그렇게 해주시면 정말 감사하겠습니다."},objectives={{34,1317825627},"크롤러 고기 8묶음을 모으세요."},progress={{48,1890370255},"고기는 구했나요? 힘이 빠지는 것 같아요..."},completion={{418,1735629019},"드디어 배고픔이 해결됐어! 배가 너무 고파!$B$B내가 도구를 찾으려고 뒤지다가 발견한 이 이상한 물건들과 내 우정, 그리고 감사를 너에게 줄게. 언젠가 고향으로 돌아갈 수 있기를 바라.$B$B친구, 정말 고마워. 이제 내게는 힘이 있고, 곧 도구를 구해서 스스로 사냥을 하며 고향으로 돌아갈 길을 찾을 거야. 더 이상 걱정하지 마. 언젠가 다시 만날 수 있기를."}}
rows[80392]={title={{21,829051557},"퀘르다닐로 가는 소포"},description={{470,1568951674},"실례합니다, 잠시 제 얘기 좀 들어주시겠어요? 제$B$B 이름은 리에렌입니다. 당신은 노련한 여행자처럼 보이는데, 부탁드릴 일이 하나 있습니다. 제가 지금 꽤 바빠서요. 여기 동쪽에 있는 퀘르다닐로 소포를 가져다 주셔야 하는데, $B$B괜찮으시다면 도와주시겠어요? 거기 있는 엘프 숙소를 찾아서 제 여동생에게 가져다주시면 됩니다. 제 여동생은 저랑 생김새가 비슷한데, $B$B순수 엘프 혈통입니다. 소포에 당신의 돈을 동봉해 두었으니, 자, 꼬맹이, 도와주시겠어요?"},objectives={{61,118983183},"리에렌의 소포를 퀘르다닐로 가져가서 로아니아에게 전달하세요."},progress={{50,1052015600},"퀘르다닐에 오신 것을 환영합니다. 무엇을 도와드릴까요?"},completion={{159,338104803},"제 여동생이 저한테 보낸 소포인가요? 정말 감사합니다. 약속드린 대로 송금했습니다.$B$B사실 한 가지 더 부탁드릴 게 있어요..."}}
rows[80393]={title={{21,633262341},"퀘르다닐 심부름"},description={{495,745810019},"너무 무리한 부탁이 아니길 바라지만, 당신은 강인해 보이시군요. 퀘르다닐$B$B 사람들은 제 가족과도 같은데, 그들은 오랫동안 끔찍한 위더바크 트롤들과 싸워왔습니다! 그들의 수를 줄여주시길 부탁드립니다. 더 이상의 고통은 보고 싶지 않습니다. 우리는 이미 너무나 많은 것을 잃었습니다. 샨드라로르는 잔혹한 $B$B트롤들과 그들의 애완 거미들을 거느리고 있는데, 그곳을 집중적으로 처리해 주시면 좋겠습니다. $B$B일이 끝나면 제 양어머니인 볼다나에게 보고해 주십시오. 그녀는 오두막 안쪽 깊숙한 곳에 계십니다!"},objectives={{70,846839212},"샤드라알로르에서 시든 나무껍질 가학증 환자 10마리와 시든 나무껍질 유충 경비병 8마리를 처치하세요."},progress={"Yes, $C? What brings you here?","네,$C번이시군요? 무슨 일로 오셨나요?"},completion={"You have my deepest gratitude, $C, and of course I'll make sure to thank Loania, too. You must be curious why a human is among us. If you are interested, then I shall tell you...","$C님, 진심으로 감사드립니다. 물론 로아니아에게도 감사 인사를 전하겠습니다. 인간이 우리 사이에 있는 이유가 궁금하시겠죠? 궁금하시다면 말씀드리겠습니다..."}}
rows[80395]={title={{24,793805913},"눈부신 기회"},description={"Hey, $R! In addition to the usual weapons in my stock, I have an opportunity for you.$B$BWhile I was doing my run from Ratchet to the Crossroads I saw a weird light on the mountain just south of Ratchet. There seems to be a ramp up just outside Ratchet, some raptors call the thing home though, so be careful.$B$BNow I don't know what it is, but you adventurin' types like to dive right in when it comes to dangerous situations right? It could be some HUGE deal like a demon cult or whatever for all I know and them doing nasty stuff to Ratchet would be very bad for MY business. Consider whatever spoils you find as payment.","이봐,$R ! 내 무기고에 있는 일반 무기 외에도 자네에게 줄 만한 $B$B기회가 있어.톱니항에서 크로스로드로 가는 길에 톱니항 바로 남쪽 산에서 이상한 빛을 봤거든. 톱니항 외곽에 경사로가 하나 있는데, 거기 랩터들이 서식지로 삼고 있으니 조심해야 해.그게$B$B 뭔지는 잘 모르겠지만, 자네 같은 모험가들은 위험한 상황에 뛰어드는 걸 좋아하잖아? 어쩌면 악마 숭배 집단 같은 엄청난 소굴일지도 몰라. 걔네들이 톱니항에 무슨 짓을 저지르면 내 사업에 큰 타격을 줄 테니까. 자네가 뭘 찾든 그건 보상이라고 생각해."},objectives={{42,172435256},"라쳇 남쪽에 있는 산을 조사하세요."},progress={{30,14778094},"어머, 반갑습니다! 누구세요?"},completion={{330,450036341},"오, 불빛을 조사하러 온 모험가시군요? 걱정 마세요, 저는 특수 물질 전송 장치를 실험 중이었을 뿐이고 누구에게도 위험하지 않습니다!$B$B제 실험이 성공하면 모두에게 유용할 테니 안심하세요! 하지만 이 지역을 더 안전하게 유지하고 싶으시다면, 당신에게 맡길 일이 하나 있습니다!"}}
rows[80396]={title={{18,862622706},"피 묻은 선행"},description={{798,1636529251},"저는 케이나 스핀피스톨입니다. 기계공이자 의무병이며, 악당들을 $B$B처치하는 킬러죠. 지금 저는 수많은 무고한 사람들의 목숨을 위협하는 위험한 적을 추적하고 있습니다. 나중에 이 문제를 해결하는 데 당신의 도움을 요청할 수도 있지만, 지금은 당신에게 다른 임무를 맡기겠습니다. 잘 수행한다면$B$B 후한 보상을 드리겠습니다! 근처에 있는 콜카르 부족이 교차로를 습격할 준비를 하고 있습니다. 제가 도구를 사용해서 그들의 텐트에 몰래 들어가 칸의 명령을 들었거든요. 하지만 이 습격은 막을 수 있습니다. 당신이 그곳으로 가서 그들을 모두 처치해 준다면 많은 생명을 구할 수 있을 겁니다. $B$B그들은 서쪽 오아시스 주변에 있습니다. 임무를 마치면 저에게 돌아오세요. 제가 없으면 수정구를 다시 만져주세요. 그러면 누군가 기다리고 있다는 것을 알 수 있을 겁니다. 자, 이제 가서 그들을 모두 처치하세요!"},objectives={{125,1554711334},"콜카르 블러드차저 6마리, 콜카르 팩 러너 4마리, 콜카르 마라우더 4마리를 처치하세요. 수정구를 사용하여 케이나 스핀피스톨을 다시 소환하세요."},progress={{20,104887316},"자, 당신은 해냈나요?"},completion={"Wonderful. I wonder what it felt like to have their blood splatter all over you, or what came into your mind as you heard them scream in pain and fall like the vermin they are.$B$BI wish I could have been there to see it for myself, heh.$B$BNonetheless, know that thanks to your violent deeds many lives were saved. Now, of course I'll be sure to reward you… Hmm, let's see… Yes, this will be something you can either use or sell for compensation.$B$BI'll make sure to tell others of your deeds. Hopefully we'll meet again, $N.","훌륭하군. 그들의 피가 온몸에 튀는 기분이 어땠을지, 그들이 고통에 비명을 지르며 벌레처럼 쓰러지는 소리를 들었을 때 무슨 생각이 들었을지 궁금하군.$B$B나도 직접 볼 수 있었으면 좋았을 텐데, 하하.$B$B어쨌든, 네 용감한 행동 덕분에 많은 생명이 구해졌다는 걸 알아둬. 자, 이제 당연히 네게 보상을 해줘야지… 음, 어디 보자… 그래, 이건 네가 쓰거나 팔아서 보상금을 받을 수 있는 걸로 줄게.$B$B네 공적을 다른 사람들에게 꼭 알리도록 하지. 언젠가 다시 만날 수 있기를 바라.$N"}}
rows[80397]={title={{18,1867039087},"그들의 힘을 약화시키다"},description={"Welcome, $C. We don't see many adventurers up this way — and not without reason.$B$BThe greed of the Venture Company has tainted the land itself. Every ancient tree that they fell only adds to my troubles.$B$BThe powerful sap that once nourished the trees of this forest now congeals into those awful sap beasts. Their corrosive nature harms the delicate balance we've fought to maintain here.$B$BWorse still, many have recently made their way to Stonetalon Peak itself! Their corrosive sap kills the herbs I need for cooking and simple potions.$B$B$C, venture forth and rid the Peak of these things. You'll find many just south of here, over the ridge that holds the old ruins. We've little enough use for coin up here, but perhaps a few potions might serve as payment?","어서 $C오세요, . 이쪽에는 모험가들이 많이 오지 않는데, 그럴 만한 이유가 $B$B있습니다. 투자개발회사의 탐욕이 이 땅을 더럽혔거든요. 그들이 베어낸 고대 나무 한 그루 한 그루가 제게 더 큰 고통을 $B$B안겨줄 뿐입니다. 한때 이 숲의 나무들을 살찌우던 강력한 수액은 이제 끔찍한 수액 괴물로 굳어버렸습니다. 그 부식성 때문에 우리가 애써 지켜온 섬세한 균형이 깨지고 있죠. 설상가상으로,$B$B 최근 많은 수액 괴물들이 스톤탈론 봉우리까지 올라왔습니다! 그 부식성 수액 때문에 제가 요리와 간단한 물약을 만드는 데 필요한 약초들이 죽어버리고$B$B$C 있어요. , 모험을 떠나 봉우리에서 그 괴물들을 없애주세요. 여기 남쪽, 옛 유적이 있는 능선 너머에 많이 있을 겁니다. 여기서는 돈이 별로 필요 없지만, 물약 몇 개 정도는 보상으로 드릴 수 있을지도 모르겠네요."},objectives={{80,415202228},"수액 괴물 10마리와 부식 수액 괴물 6마리를 처치한 후 여관 주인 파랄리아에게 돌아가십시오."},progress={{99,447493959},"산꼭대기에서 그 수액 괴물들을 모두 처치했습니까? 여기서 잠시 쉬면서 기력을 회복하세요."},completion={"Thank you, $N! With the Venture Company's activities unchecked, this surely isn't the end of those sap beasts, but for now the forest is quiet and already healing. Here, take a few of my potions in thanks for your hard work. They should help you travel swiftly in this mountainous terrain. ","고맙습니다,$N! 벤처 컴퍼니의 활동이 제재받지 않는 한, 저 수액 괴물들이 완전히 사라지지는 않겠지만, 지금은 숲이 조용해지고 이미 회복되고 있습니다. 수고에 대한 보답으로 제 물약 몇 개를 드리겠습니다. 이 물약들이 산악 지형에서 빠르게 이동하는 데 도움이 될 겁니다."}}
rows[80398]={title={{16,1580361544},"쿵쾅거리는 뇌"},description={{176,1007348185},"파운더의 메인프레임이 놀랍도록 온전한 상태라는 것을 알게 됩니다. 이건 꽤 가치 있는 $B$B물건일지도 몰라요!그놈족 공학 전문가에게 가져가 보면 뭔가 조치를 취할 수 있을 겁니다."},objectives={{62,1923660956},"메인프레임을 어떻게 처리해야 할지 알아낼 수 있는 사람을 찾아보세요."},progress={"Hello there, $R, are you here for one of my inventions?","안녕하세요,$R님, 제 발명품 때문에 오셨나요?"},completion={{227,1709597052},"저거 진짜 멀쩡한 파운더 메인프레임 맞아?! 어디서 구했어?$B$B이거로 할 수 있는 게 무궁무진하네! 좋아, 이 메인프레임에서 데이터 복사하는 거 허락해 주면 너도 파운더 메인프레임 만들어 볼 수 있게 도와줄게!"}}
rows[80399]={title={{21,1896345263},"잘라잔의 제자"},description={{359,1694157864},"한때 나의 충실한 제자였던 마카스가르가 오만해져서 나를 버렸다. 그는 내가 미래의 계획을 위해 비축해 두었던 막대한 양의 어둠의 마법을 가지고 해안을 따라 $B$B북쪽으로 도망쳤다. 자네와 자네 부하들이 그의 목과 함께 이 유물을 되찾아온다면 거래를 할 수 있겠나? 내게 마땅히 속한 것을 가져오면 자네가 원하는 것을 돌려주겠네."},objectives={{212,1788185371},"편지를 읽은 후, 당신은 잘라잔의 옛 제자를 직접 찾아가 그의 목숨을 살려주기로 결심합니다.\013\010\013\010그의 머리와 잘라잔의 마법약을 센진 마을의 가드린 스승에게 가져다주면 보상을 받게 됩니다."},progress={"What do you have there, $N?","$N, 거기에 뭐가 있나요?"},completion={{122,1223174851},"잘라잔의 마법과 그의 제자의 머리라니? 아주 잘했군. 자, 보상으로 뭘 줄까. 둘 중 하나를 골라 봐."}}
rows[80400]={title={{13,1638770416},"재조립 도구!"},description={{764,453766331},"난쟁이는 당황한 듯 작은 소리로 중얼거렸다. \"저 $B$B자식들을 갈기갈기 찢어버려야겠어.$B$B..\" \"오, 안녕. 딱 좋은 타이밍이군, 친구. 자네의 도움이 절실히$B$B 필요했지! 자, 잘 들어봐. 최근에 책을 완성하고 새 발명품에 필요한 부품들을 구하러 가려던 참이었어. 잠깐 캠프를 비웠는데, 세상에! 빌어먹을 트로그들이 와서 내 물건들을 엉망으로 만들어 $B$B놨더군! 아, 책이 갈기갈기 찢어졌고, 남은 부분을 보니 완벽하게 그려진 도면과 설계도가 담긴 25페이지가 전부 $B$B날아가 버렸어. 지금 내가 신경 쓰는 건 책 페이지들을 되찾는 것과 그 망할 트로그들이 고통받는 거야. 코볼드처럼 멍청한 놈들이지만, 코볼드처럼 무리를 지어 다니니까 조심해야 해!\""},objectives={{80,312597799},"드워프 문서 10개를 찾아 불모의 땅에 있는 탐험가 브로탈루스에게 가져다주세요."},progress={{212,892489380},"내 캠프를 망가뜨리고, 내 물건을 훔치고, 내 해기스를 먹고, 심지어 내 캠프에 불을 지르는 것도 내 예쁜 책을 훔친 것만큼 끔찍한 죄는 아니야!$B$B날개가 잘린 그리핀보다 더 고통스럽게 만들어 버려!"},completion={"Oh, me bonnie, precious, darling book! What did those scunnered bampots dae to ye?$B$BThank ye, $c, I'll never forget yer kindness.$B$BI'll be sure to add a dedication to yer name once I put me book back together!","오, 내 사랑스럽고 소중한 책아! 그 못된 놈들이 너에게 무슨 짓을 한 거니?$B$B고마워,$c네 친절을 절대 잊지 않을게.$B$B내 책을 다시 조립하면 꼭 네 이름에 헌사를 남길게!"}}
rows[80401]={title={{18,758850765},"파운더를 만들기 위해"},description={{811,1316757568},"안타깝게도 파운더를 만드는 건 쉽지 않습니다. 대부분의 부품은 제가 제공하겠지만, 몇 가지 특별한 부품은 구해주셔야 합니다. 어떻게 구할지는 당신에게 달려 있습니다. 제가 $B$B필요한 것은 다음과 $B$B같습니다. 섀시용 토륨 튜닝 서보입니다. 제가 아는 한 단 하나뿐인데, 스칼렛 광신도들이 잠가 버렸습니다. 아마 무기고에 그들이 이단으로 여기는 물건들을 보관하는 것 같습니다. 가서 구해다 $B$B주세요! 또한 파운더에 사용할 완벽한 코어도 필요합니다. 검은바위 심층부의 검은무쇠 골렘이 좋은 공급원입니다. 골렘 군주 아르겔마크가 하나 가지고 있을 가능성이 $B$B높습니다. 마지막으로 내골격에 사용되는 고품질 아다만타이트 막대가 필요합니다. 과거 스트라솔름의 대장간에서 이런 막대를 만들었던 것으로 알고 있습니다. 도시의 현재 상황은 모르지만, 막대가 아직 그곳에 남아있을지도 모릅니다."},objectives={{217,1764528485},"스칼렛 수도원 무기고에서 토륨 튜닝 서보를 획득하고, 블랙록 심층부의 골렘 군주 아르겔마크에게서 완벽한 골렘 핵을 얻고, 스트라솔름에서 아다만타이트 막대를 찾으십시오. 오글소프 오브노티쿠스에게 돌아가십시오."},progress={{55,865984728},"다시 오신 걸 환영합니다! 어떻게 진행됐나요? 아이템은 다 받으셨나요?"},completion={{231,1335296513},"모든 부품이 다 왔군요! 훌륭합니다!$B$B당신이 없는 동안 저는 당신의 파운더를 설계하느라 바빴습니다. 이제 당신이 가져온 부품들을 조립하고 도색만 하면 됩니다.$B$B아직 도색은 안 했으니 색깔을 고르세요!"}}
rows[80403]={title={{18,221241213},"제플린 추락 사고"},description={{504,1568883267},"얼마 전, 고블린 비행선 한 대가 동쪽에 추락했습니다. 며칠 전 스팀휘들 카르텔의 한 직원이 이곳을 지나갔는데, 비행선의$B$B 화물과 조종사 비질에 대한 정보를 찾고 있었습니다. 하지만 우리 중 누구도 추락 현장을 제대로 살펴보지 못했습니다. 그녀가 혼자서 잔해를 수습하거나, 비행선에 실려 있었을지도 모르는 화물을 회수하는 것은 거의 불가능할 겁니다. 시간이$B$B 되시면, 이곳에서 동쪽으로 산 근처에 있는 비질의 난파선에 가서 그녀를 찾아보시는 게 좋을 겁니다."},objectives={{47,611752260},"비질의 난파지에 있는 목시 스틸그릴과 대화하십시오."},progress={{39,66446044},"어떻게 하면 당신을 믿을 수 있을까요?"},completion={"I suppose I can use the help. There's not much here a $C would be interested in, anyway.","도움이 필요할 것 같네요. 어차피$C이 관심을 가질 만한 건 별로 없으니까요."}}
rows[80404]={title={{20,71466800},"드라짓 배송"},description={{214,1863619690},"드라짓은 곧 제 연락을 기다릴 텐데, 제가 떠나기엔 현장이 충분히 안전하지 않은 것 같습니다. $B$B혹시 시간이 되시면, 회수한 화물을 머드스프로켓에 있는 드라짓에게 좀 가져다주시겠어요?"},objectives={{60,866636302},"머드스프로켓에 있는 드라짓 드립밸브까지 제플린 카고를 타고 가세요."},progress={{4,273767400},"예?"},completion={{245,743576598},"<드라짓이 당신에게서 화물을 받습니다.>$B$B너무 배고파서 용이라도 잡아먹을 수 있을 것 같아! 목시가 드디어 그 화물을 여기로 좀 가져다 줘서 정말 다행이야. 그동안 우리는 목시가 사냥에서 잡은 걸 얻으려고 오우거랑 주사위 놀이를 해야 했어!"}}
rows[80405]={title={{17,1908447854},"화물을 단단히 고정"},description={{402,445984777},"이 비행선은 머드스프로켓에 6개월 치 보급품을 싣고 가고 있었어요! 물론 필요한 물품 중 일부는 물물교환으로 얻었지만, 영원히 버틸 수는 없을 $B$B겁니다. 저는 화물을 수습하기 위해 이곳에 파견되었는데, 잔해가 이 지역 습지 곳곳에 흩어져 있어요. 추락으로 많은 화물이 파손되었을 거라고 생각하지만, 수습할 수 있는 부분을 도와주시겠습니까?"},objectives={{84,1840320377},"비질의 난파선에 있는 목시 스틸그릴이 제플린 화물 8개를 회수해 달라고 부탁합니다."},progress={{80,1234577593},"<목시는 걱정으로 안절부절못하는 표정이다.>$B$B화물은 무사했나요? 혹시라도 찾으셨나요?"},completion={{195,7282354},"와! 예상했던 것보다 훨씬 더 많은 걸 찾아냈네요. 드라짓이 우리가 여기서 얼마나 많은 걸 발견할 거라고 생각했는지는 모르겠지만, 일단은 이 정도면 만족해야 할 것 같아요."}}
rows[80407]={title={{22,1874084308},"친구의 편지"},description={"Hey!$B$BYou're $N, right? I received a letter from a certain Kheyna Spinpistol. She paid me handsomely to direct you to a crashed gnomish rocket car north west of town.$B$BShe said you'll know what to do when you find 'it' .","어이!$B$B 당신$N N 맞죠? 케이나 스핀피스톨이라는 분에게서 편지를 받았는데, 마을 북서쪽에 추락한 그놈족 로켓 자동차 위치를 알려주면 후한 보수를 주겠다고 하더군요. '그것'을$B$B 찾으면 어떻게 해야 할지 알게 될 거라고 했어요."},objectives={{66,1959694472},"가젯잔 북서쪽에 추락한 그놈족 로켓 자동차를 조사하세요."},progress={{4,273767400},"예?"},completion={"Hello again, $N! I see that Reas succeeded in her task.$B$BGood, good! I have need of your aid again! ","안녕하세요,$N님! 리아스가 임무를 성공적으로 완수했군요.$B$B잘됐네요! 다시 한번 도움을 요청드립니다!"}}
rows[80408]={title={{22,385428879},"두뇌를 위한 학살"},description={{816,517298792},"숙적을 찾는 여정은 계속되지만, 그 여정이 계속되는 만큼 해야 할 일도 많습니다. 제겐 두뇌가 필요합니다! 저는 현재 놀랍도록 혁신적인 기술을 연구 중인데, 모든 종족이 사용할 수 있도록 완성해야 합니다. 샘플이 더 필요하고,$B$B 어디서 구할 수 있는지 정확히 알고 있습니다! 가젯잔 남쪽, 약간 동쪽에 있는 이스트문 유적이라고 알려진 트롤 유적지를 찾아보세요! 그곳에 오우거들이 있습니다. 녀석들을 사정없이 처치하세요! 녀석들이 타나리스의 물 저장소를 공격해서 많은 사람들이 갈증으로 죽을 겁니다. 물은 지금도$B$B 비싸지만, 저 짐승들이 저장소를 파괴하면 가격이 폭등해서 대부분의 사람들이 물을 살 여유가 없어질 겁니다. 그런 일이 일어나지 않도록 막아야 합니다. 녀석들을 모두 처치하세요. 뇌를 확보하면 리아스에게 가져다주고, 다시 수정으로 돌아오세요."},objectives={{117,1916274857},"동쪽 달 유적의 두네마울 오우거에게서 매끈한 오우거의 뇌 12개를 폭력적으로 획득한 다음, 리아스에게 전달하십시오."},progress={{4,273767400},"예?"},completion={{54,828722411},"너 진짜 뇌가 12개나 있어?! 대단하네! 뭐, 돈은 돈이니까."}}
rows[80409]={title={{16,1207697065},"케이나로 돌아가기"},description={{77,1088152802},"지시받은 대로 처리하겠습니다. 당신은 당신을 보낸 사람에게 돌아가는 게 좋을 겁니다."},objectives={{53,1814819030},"수정으로 돌아가서 케이나 스핀피스톨과 대화하세요."},progress={" Hello, $N!","안녕하세요,$N님!"},completion={{770,1807248648},"당신이 도와준 그 여자는 역사를 바꾸려 하고 있습니다. 게다가 당신이 사용하던 수정은 단순한 발명품이 아니라 시간의 수정인데, 어쩐지 변질되고 뒤틀려 있습니다!$B$B저는 황무지에서 시간이 뒤틀렸을 때 처음 이 사실을 알아차리고 관찰하려고 했지만, 지금은 더 이상 모른 척할 수 없습니다. 이 변질된 시간의 수정을 가져가고, 그 노움을 찾아 체포하겠습니다.$B$B이 사건 전체를 철저히 조사할 것이며, 나중에 당신의 도움이 필요할지도 모릅니다. 더 이상 그녀를 위해 일하지 마십시오. 그렇지 않으면 벌을 받을 수밖에 없습니다. 그리고 수정 옆 상자에서 이것을 발견했는데, 아마 당신의 보상이었던 것 같습니다. 보통이라면 압수하겠지만, 다음에 그녀가 나타날 때 당신이 그녀를 잡는 것을 도와준다면 눈감아 주겠습니다."}}
rows[80410]={title={{18,472942990},"시의적절한 상황"},description={"Excuse me, $N. I received a peculiar message from the Cenarion Circle recently, but it wasn't addressed to me, it was addressed to you.$B$B<Rayne hands you a letter, as you open it, the letter only contains a few words and no signature: \"It is time. Meet me inside the inn of Andorhal on the second floor.\">","실례합니다,$N . 최근 세나리온 서클에서 이상한 메시지를 받았는데, 제게 온 것이 아니라  씨에게 온 것이었습니다.$B$B<레인이 당신에게 편지를 건네줍니다. 편지를 열어보니 서명 없이 몇 단어만 적혀 있습니다. \"때가 되었습니다. 안도르할 여관 2층에서 만나십시오.\">"},objectives={{60,1662720811},"안도르할 여관으로 가서 편지를 보낸 사람을 찾아보세요."},progress={"There you are, $N! You're late! Or early. Well, it doesn't matter, at least you came.","여기 있었군요,$N! 늦었네요! 아니면 일찍 왔을지도. 뭐, 상관없어요. 어쨌든 와줘서 고마워요."},completion={{119,1164257683},"타나리스에서 때가 되면 연락드리겠다고 했던 거 기억나? 드디어 그 때가 왔어. 그녀를 찾았어!"}}
rows[80411]={title={{16,931656824},"무한한 사냥"},description={{382,843311165},"저는 한동안 그녀를 추적해 왔지만, 그녀는 정말 잡기 힘들어요! 가까이 다가갈 때마다 도망치죠. 하지만 그녀는 다시 당신과 접촉하려 합니다. 이번에는 함정을 설치할게요. 세라데인에게 가서 에메랄드 포털을 피하고 가장 큰 사원으로 가세요. 그곳에서 그녀의 타락한 시간 수정 하나를 찾을 수 있을 겁니다. 그걸 사용해서 그녀를 소환하세요. 그러면 제가 나타나서 함께 그녀를 물리치겠습니다!"},objectives={{75,467627737},"세라데인의 신전으로 가서 안트노르미를 물리치고 안도르할에 있는 크로미에게 돌아가십시오."},progress={{51,23242806},"자, 보세요. 곰곰이 생각해 볼 거리가 많아졌네요."},completion={{654,1736228219},"이 수수께끼의 용이 시간의 흐름을 오염시키려 하는 것 같습니다. 케이나가 일으킨 혼란 때문에 그녀와 의견이 달랐지만, 지금은 더 큰 위협 때문에 일단 접어두었습니다. 그녀가 사냥하던 용이 특정 시점에 심각한 혼란을 일으킨 것 같습니다. 그녀는 또한 그 용의 주인을 언급했으니, 다른 용들도 있을지도 모릅니다. 때가 되면 당신의 도움이 절실합니다. 지금은 상황을 안정시키면서 앞으로 어떻게 나아가야 할지 방법을 강구하겠습니다. 케이나는 엄격한 감독 하에 우리와 협력할 것입니다. 그녀의 운명은 이 일이 해결된 후에 결정될 것입니다. 이 복제 검은 당신의 보상으로 준비했습니다."}}
rows[80604]={title={{26,1753717327},"동굴 속으로의 여정"},description={{316,181643981},"우리의 적은 더 이상 이 시대에 있지 않지만, 과거에 있을 가능성이 있다고 생각합니다. 더 자세한 내용을 알려드리겠지만, 여기서는 말하지 않겠습니다. 누가 듣고$B$B 있을지 모르니까요. 타나리스의 시간의 $B$B동굴로 가십시오. 당신이 이 일에 연루되어 있으니 들어갈 수 있도록 허가했습니다.$B$B 도착하면 다시 이야기하십시오."},objectives={{51,1396074449},"시간의 동굴로 가서 크로미와 대화하세요."},progress={{109,157326365},"자, 보세요... 시간의 흐름 속으로 발을 들여놓지 않도록 조심하고, 무슨 일이 있어도 모래시계 안으로 들어가려고 하지 마세요."},completion={{547,783071526},"여기 이상한 점들을 너무 신경 쓰지 마세요. 다 시간 여행이니까요.$B$B익숙해질 거예요... 아마도요. 어쨌든, 와주셔서 감사합니다. 시간의 동굴에 오신 것을 환영합니다!$B$B이곳은 청동용군단이 사는 곳이자, 역사 속 여러 시대로 통하는 시간의 통로가 있는 곳이기도 합니다.$B$B여러분이 보고 있는 이 통로들은 끊임없이 변화하고 있습니다.$B$B순식간에 눈앞의 통로가 다른 통로로 바뀔 수도 있죠.$B$B안타깝게도 여러분은 시간 감각이 제한되어 있어서 시간의 통로를 진정으로 경험할 수는 없을 겁니다.$B$B하지만 이야기가 딴 데로 샜네요. 우리는 할 일이 있습니다!"}}
rows[80605]={title={{36,626998909},"어둠의 문이 처음으로 열리다"},description={{601,1844378659},"약 17년 전, 살게라스의 지배를 받던 마지막 수호자 메디브가 어둠의 문을 열어 오크 호드를 이 세계로 들여보냈습니다. 우리는 케이나와 $B$B안트노르미가 있었던 곳에서와 같은 에너지와 일치하는 시간 이상 현상을 감지했습니다. 케이나는 안트노르미가$B$B 이 일의 배후에 있다고 거의 확신하고 있습니다. 오른쪽 시간 통로를 이용해 안트노르미가 역사를 파괴하기 전에 막아주십시오. 저는 여기서 상황을 지켜보겠습니다.$B$B 이것이 나쁜 일이라고 생각하기 전에, 오크들은 군단을 물리치는 데 결정적인 역할을 했습니다. 만약 그들이 오지 않았다면 결과는 재앙적이었을 겁니다!"},objectives={{88,1547709031},"시간의 통로를 통해 블랙 모라스의 과거로 들어가 안트노르미를 처치하십시오. 그녀의 머리를 케이나에게 가져오세요."},progress={{33,1057127892},"제발... 그녀가 이기게 놔두면 안 돼요!"},completion={{804,292373984},"<케이나는 침울하게 머리를 응시하며, 그녀의 안구 임플란트가 잠시 수축한다.>$B$B안트노미는 한때 내게 자매와 같았어.$B$B다른 결말을 맞았으면 좋았겠지만… 어쩔 수 없었지.$B$B크로미가 나를 어떻게 할지 결정할 때까지 당분간 여기에 머물 거야. 나도 한때 청동 드래곤이었으니까. 치료법을 찾으면 다시 청동 드래곤이 될 수 있을지도 몰라.$B$B내가 너에게 뇌를 모으라고 시켰던 거 기억해? 그 노력이 결실을 맺어서, 두개골에 구멍을 뚫지 않고도 네 뇌에 연결할 수 있는 임플란트를 만들었어.$B$B네가 한 일에 대한 보상이야. 받아. 도움이 될 거야.$B$B저도 제대로 소개하고 싶었어요. 제 본명은 케리도르미입니다. 저는 친구가 많지 않았는데, 저에게 해주신 모든 것에 감사드립니다.$B$B언젠가 다시 만날 수 있기를 바랍니다. 몸조심하세요!"}}
rows[80606]={title={{24,1396835736},"게임 마스터들에게 복수하라!"},description={{539,857072515},"혹시 파란색 옷에 두건과 로브를 두르고 다니며, 남들에게 불쾌감을 주는 자들을 벌주는 신비로운 사람들을 본 적 있나요? 그런 사람들을 본 사람도, 아는 사람도 많지$B$B 않을 거예요. 오히려 그들이 벌을 받아야 할 차례죠! 제 장갑을 가져간 것도 분명 그들이겠죠.$B$B 제 손에서 장갑을 감쪽같이 사라지게 할 사람이 누가 있겠어요?! 그런 사람을 어디서 찾을 수$B$B 있을지는 모르겠지만, 혹시라도 나타나면 제 대신 그들의 얼굴에 눈덩이를 던져 주세요. 그런 짓은 용납되지 않을 거라고요!"},objectives={{34,1006863812},"게임 마스터에게 눈덩이를 던져 보세요!"},progress={{60,1668232801},"당신은 이 세상의 신비로운 거장들 중 한 명을 찾아냈나요?"},completion={{171,718958600},"해냈어? 대단해!$B$B이제 내 장갑을 없애기 전에 두 번 생각하겠지.$B$B잠깐, 내 장갑은 안 가져갔다고?$B$B그럼, 이제 다른 장갑도 가져가지 않겠지..."}}
rows[80700]={title={{19,67452003},"특정한 편지"},description={"I've been looking for you all around the city! Although I am more of an announcer than a mailman I was instructed to give this letter to you by well… I am not sure who he was.$B$BThe figure's face was covered and his voice didn't seem familiar at all. He said you will understand when you read it.$B$BI am not one to pry, $N, but be more careful, I wouldn't let the guards know I associate myself with those kinds of people.","온 도시를 다 뒤져 당신을 찾았어요! 저는 우편배달부라기보다는 안내원에 가깝지만, 이 편지를 당신에게 전해달라는 지시를 받았는데… 그 사람이 누구였는지는 잘 $B$B모르겠어요. 그 사람은 얼굴을 가리고 있었고 목소리도 전혀 낯설었어요. 읽어보면 이해할 거라고 하더군요. 저는 $B$B캐묻는 걸 좋아하지 $N않지만, 조심하세요. 제가 그런 부류의 사람들과 어울린다는 걸 경비원들이 알게 되면 안 돼요."},objectives={{48,1810930179},"갓맨의 불안감을 덜어주기 위해 의심스러운 편지를 받아들였다."},progress={{78,309068637},"경비원들이 우리가 수상한 짓을 한다고 생각하기 전에 어서 가져가 줘."},completion={{56,1388154965},"여기 편지가 있습니다. 다시는 이런 일을 겪지 않기를 바랍니다."}}
rows[80701]={title={{16,1694937029},"찾기 힘든 SI:7"},description={"Burn this after you've read it.$B$B$N,$B$BI dearly hope this letter finds you in good health, I wish I could've delivered the message in person but you must understand that we like to keep secrecy at hand.$B$BI am not sure if you're aware of what our organisation does, or who we entirely are, but we have discovered valuable information and we might need your help.$B$BIn the envelope you will find a ring, keep it at hand while you come visit us, it will be the sign you've accepted our mission and that the letter was burnt.$B$BUntil we meet,\010Mathias Shaw.","이 편지를 읽으신 후에는 $B$B$N$B$B태워버리십시오. 부디 건강하게 잘 받으시길 바랍니다. 직접 전해드리고 싶었지만, 저희는 비밀 유지를 중요하게 생각하기 때문에 그러지 못했습니다. 저희 조직이 $B$B무엇을 하는지, 저희가 누구인지 정확히 알고 계신지는 모르겠지만, 저희가 귀중한 정보를 입수했고 당신의 도움이 필요할지도 모릅니다. 봉투 안에 반지가 $B$B들어 있습니다. 저희를 방문하실 때 반지를 잘 간직해 주십시오. 이 반지는 당신이 저희의 임무를 수락했고 편지가 태워졌다는 증표가 될 것입니다. 다시$B$B 뵙겠습니다.\013\010마티아스 쇼."},objectives={{56,1614724099},"SI:7에 보고하고 마티아스 쇼에게 반지를 보여주십시오."},progress={{29,1817556788},"어떻게 도와드릴까요, 낯선 분?"},completion={{152,314665773},"아, 내 반지군.$B$B. 무사히 도착했군. 비밀로 해서 미안하지만 조심해야 해. 우리 벽에도 우리 조직과는 상관없는 귀가 있거든."}}
rows[80702]={title={{17,842341544},"젊고 어리석은"},description={{469,978181741},"내 첩보원들이 보고한 바에 따르면, 스칼렛 십자군 행렬이 여러 마을을$B$B 지나가기 시작했습니다. 이미 레이크셔, 다크셔, 메네틸, 사우스쇼어까지$B$B 갔다고 합니다. 제 생각에는 스칼렛 수도원, 하스글렌, 스트래솔름에서 벌어진 사건 이후 십자군을 인수한 세력이 병력 부족을 깨달은 것 $B$B같습니다. 레이크셔 주민들과 이야기를 나눠보세요. 최소한 뭔가 목격했을 겁니다."},objectives={{88,623927318},"호숫골 주민들을 심문하여 진실을 밝혀내십시오. 그리고 마티아스 쇼에게 보고하십시오."},progress={{23,1124725107},"업무는 어떻게 진행되고 있나요?"},completion={"So we were right, this would've been valuable information if we didn't already receive another report.$B$BSorry about that, $N. I will be needing your help once more.","그러니까 우리 생각이 맞았네요. 이미 다른 보고서를 받지 않았더라면 이 정보는 매우 유용했을 텐데 말이죠.$B$B죄송합니다,$N. 다시 한번 도움을 요청드리겠습니다."}}
rows[80703]={title={{12,401441988},"탄돌 스팬"},description={{318,617777015},"그래 친구, 내가 아는 건 이게 다야. 내가 이 정보를 알려준 대가로 보상을 받을 자격은 없지만, 주시면 정말 감사하겠습니다. (키슬이$B$B 손바닥을 내밀었지만 당신은 지불을 거부합니다.) $B$B좋아, 그럼 저 다리, 탄돌 스팬인가 뭐시기로 가는 길로 가버려. 스칼렛츠가 네가 그렇게 재수 없게 군 것에 대해 너를 혼내주길 바란다!"},objectives={{87,536689835},"블라데우스 스프링리버를 메네틸 항구로 데려와 스토우트피스트 선장에게 보고하십시오."},progress={{42,642807658},"붉은 십자군은 반드시 종식되어야 한다."},completion={{129,1071773249},"우리 캠핑카를 고의로 파괴한 멍청이들에게서 건져낼 수 있는 게 고작 이거였군, 그렇지?$B$B저놈을 감옥에 처넣어 버리겠어, 잘했어."}}
rows[80704]={title={{28,1934330541},"당신은 본성에 충실한가요?"},description={"We've been trying to no avail to interrogate the young lad you brought back, $N. He simply wouldn't talk, me and the other guards tried to persuade him as best as we could.$B$BConsidering you were there to put an end to their masquerade, I'd assume you'd have a better chance to draw some information out of him.$B$BCredits given where credits are due, you did a great job putting piece to piece together and finding them.$B$BTake whatever approach you'd like, just see it done.",", 당신이 데려온 그 어린 녀석을 심문하려고 애썼지만 소용이 없었습니다.$N 그는 도무지 입을 열지 않았고, 저와 다른 경비병들은 최선을 다해 설득해 $B$B봤습니다.당신은 그들의 위장 행각을 끝내기 위해 그곳에 있었으니, 그에게서 정보를 얻어낼 가능성이 더 높을 거라고 $B$B생각합니다.공로는 인정해야죠. 당신은 단서를 모아 그들을 찾아내는 데 훌륭한 일을 해냈습니다.어떤 $B$B방법을 택하든 상관없지만, 끝까지 해내십시오."},objectives={{31,1882985367},"블라데우스를 어떻게 할지 결정하세요."},progress={{106,1098012414},"당신 앞에 있는 형체는 당신을 보는 것이 불쾌하며, 마음속으로 당신을 갈기갈기 찢어발기고 있습니다."},completion={{461,858717011},"당신은 어떻게 해야 할지 몰라 난감한 상황에 처해 있습니다. 주어진 상황에서 최선을 다해야 합니다.$B$B문제를 고민하는 동안 방 안을 둘러보니 스토우트피스트와 다른 경비병들이 당신에게 접근할 수 있는 방법을 남겨두었음을 알게 됩니다.$B$B이제 포로를 어떻게 심문할지 결정해야 할 시간입니다.$B$B왼쪽에는 그를 설득할 수 있는 가장 좋은 방법이 있고, 오른쪽에는 그를 고문할 수 있는 가장 좋은 방법이 있습니다."}}
rows[80705]={title={{23,1174477022},"설득의 수단"},description={{320,378531000},"당신은 아제로스를 누비며 수많은 위험과 적들을 마주했지만, 눈앞의 이 남자는 그렇지 않습니다. 당신은 $B$B그가 악한 인물이 아니라는 것을 확신하고, 본래의 성격대로 가볍게 접근하기로 했습니다. 여러 $B$B선택지 중에서 가장 효과적인 설득 방법을 고르고, 이제 시작할 준비가 되었습니다."},objectives={{50,804113208},"설득력을 발휘하여 블라데우스를 심문하십시오."},progress={{115,1009332124},"보고서가 불완전해 보입니다. 수감자에 대한 기본적인 정보 외에는 실질적으로 유용한 내용이 없습니다."},completion={{111,1428821495},"깃펜과 잉크를 집어 들고 블라데우스에게서 얻은 정보를 기록하며 보고서를 완성합니다."}}
rows[80706]={title={{29,1390858615},"정의를 추구하는가, 아니면 복수를 추구하는가?"},description={{460,618908017},"당신은 아제로스를 누비며 수많은 적들을 만나왔습니다. 마침내 무언가가 당신 안에서 깨달음을 주었습니다. 이 $B$B뒤틀린 세상에 저주받은 평화를 가져다주기 위해 얼마나 더 많은 악당들을 때려눕히고, 불구로 만들고, 죽여야$B$B 할까요? 붉은 성전은 당신에게도 개인적인 골칫거리였습니다. 이제 정의를 구현할 때일까요, 아니면 복수를 할 때일까요? 필요한 것을 $B$B얻는 데 도움이 될 도구들이 가득한 테이블을 앞에 두고, 당신은 내면의 악마를 받아들일 준비가 되었습니다."},objectives={{43,508843851},"어떤 수단을 써서라도 모든 것을 알아내라."},progress={{115,1009332124},"보고서가 불완전해 보입니다. 수감자에 대한 기본적인 정보 외에는 실질적으로 유용한 내용이 없습니다."},completion={{111,1428821495},"깃펜과 잉크를 집어 들고 블라데우스에게서 얻은 정보를 기록하며 보고서를 완성합니다."}}
rows[80707]={title={{25,317754592},"정보의 가격"},description={{505,904867157},"당신은 블라데우스에게서 얻을 수 있는 모든 정보를 추출했습니다. 이제 그와의 일은 끝났다고 판단하고, 그를 쉬게 한 후 다음 행동을 생각해 봅니다.$B$B 화이트메인의 죽음과 스트라솔름에 드리워진 악마의 영향력에 대한 소식이 붉은십자군의 마지막 진정한 지도자인 아벤디스 부인의 귀에 들어간 것 같습니다. $B$B그녀의 부하 중 하나가 젊은 남녀를 속여 십자군에 가담하게 하고, 강제로 복종하게 함으로써 병력을 다시 확보하려 하고 있습니다. 당신은 이 $B$B사실을 스토우트피스트에게 보고하고 그의 의견을 묻기로 결정합니다."},objectives={{28,1370878955},"스토우트피스트 선장에게 보고하십시오."},progress={{51,1671972140},"당신은 말없는 응시 외에는 아무런 환영도 받지 못합니다."},completion={{221,879927407},"원하는 것을 얻은 것 같군. 포로는 스톰윈드로 돌려보내 그들이 그의 운명을 결정하게 하겠다.$B$B이 정보를 얻기 위해 무슨 짓을 했든 간에, 나는 판단하지 않겠다. 다만 네 선택에 만족하길 바랄 뿐이다."}}
rows[80708]={title={{11,674605441},"붉은십자군의 지원"},description={{765,460704015},"내 부하들이 포로를 스톰윈드로 이송할 준비를 마쳤습니다. 그는 스톰윈드 관할 구역에 속하므로 그곳에서 운명이 결정될 것입니다. $B$B당신은 큰 도움을 주셨고, 이 사건을 더 파헤치고 싶어 하실 거라고 생각합니다. 제가 단서를 하나 얻었는데, 얼마나 도움이 될지는 모르겠습니다. 대성당$B$B 지구의 예배당 아래에 붉은 예복을 입은 사제가 있습니다. 쇼의 부하들에게서 얻은 정보에 따르면 그의 이름은 크로울리 형제이고, 붉은십자군의 사절로 도시에 파견되었다고 합니다. 그의 임무는 빛의 이름으로 $B$B싸울 의지가 있는 자들을 모집하는 것이었는데, 붉은십자군가 스스로에게 하는 그 어리석은 거짓말을 위해 싸우는 것이겠죠. 어쨌든$B$B 크로울리는 그다지 활동적이지 않았습니다. 그가 이들을 모집하는 사람인지는 확실하지 않지만, 시도해 볼 가치는 있습니다."},objectives={{79,1491048239},"스톰윈드의 대성당 지구로 가서 크로울리 형제와 대화하십시오."},progress={{17,1736587820},"어떻게 도와드릴까요?"},completion={"Bold accusation, $r, I almost feel offended.$B$BI fear it was not me, things would’ve been simpler. I assume you got a name from your prisoner, tell me what happened.","$r, 대담한 비난이군요. 거의 모욕감을 느낍니다.$B$B제가 한 짓은 아닌 것 같습니다. 제가 했다면 일이 더 간단했을 텐데요. 포로에게서 이름을 들었겠죠? 무슨 일이 있었는지 말해 주세요."}}
rows[80709]={title={{20,653254171},"붉은 깃발을 달고"},description={{663,2107719583},"아벤디스를 막아야 해. 자네는 그녀에게 골칫거리가 될 텐데, 내부에서 막는 것보다 더 좋은 방법이 어디 $B$B있겠나? 비록 내가 마법에는 재능이 없지만, 나처럼 그녀의 몰락을 간절히 바라는 친한 친구가 예전에 외모를 바꿀 수 있는 두루마리 몇 개를 준 적이 있지. 아무에게도$B$B 말하지 않는다는 조건으로 자네에게 하나 주겠네. 원래는 더 중요한 일에 쓰려고 했던 것이지만, 절박한 상황에서는 어쩔 수 없지. 이 두루마리는 $B$B티르의 손 근처에서만 사용해. 자네가 파괴한 대상 행렬의 제자 중 한 명이라고 주장하고, 아라티의 오우거들에게 살해당했다고 말해."},objectives={{52,1992216529},"티르의 손으로 가서 메이블 브라이트우드에게 보고하십시오."},progress={{28,590133143},"빨리 말씀하시거나 자리를 옮기세요."},completion={{100,1152462952},"우리는 한 명이 아니라 최소한 몇 명의 신입 사원을 예상하고 있었습니다.$B$B즉시 해명하세요."}}
rows[80710]={title={{24,1934163094},"모든 건 두뇌에 달려있어"},description={{441,1460902003},"첫 번째 임무를 수행할 준비가 $B$B되었나? 네 갑옷은 초라하고 칼날은 무뎌 보이지만, 네 몫을 제대로 해낼 수 없다면 빛의 수고를 들일 가치도 없다. 역병 지대를 $B$B누비며 네 길에 있는 모든 언데드를 처치하고 그들의 뇌를 가져오너라. 그들의 뇌는 대장군께서 계획하신 일에 필수적이다. 그저 네 임무를 수행하고 아무것도 묻지 마라. 어서 가라, 이 $B$B바보야. 빛은 누구도 기다려주지 않는다. 가서 네 영광스러운 목적을 쟁취하라."},objectives={{61,866170747},"역병지대 곳곳에서 언데드를 사냥하고 그들의 뇌를 모으십시오."},progress={{55,2076264743},"세부적인 사항에 신경 쓰지 말고, 시키는 대로 하세요."},completion={{176,1813270086},"완벽한 상태군. 이렇게 썩은 걸 굳이 다른 말로 표현할 수 있을까? 역겹군.$B$B빌어먹을 재앙이로군. 장군님 말씀이 맞기를 바라야겠어.$B$B자, 이제 다음 임무로 넘어가라, 신병."}}
rows[80711]={title={{16,1602196390},"우리가 필요로 하는 물품들"},description={{674,1163348495},"다음 임무는 별것 아닌 간단한 물건 몇 가지를 모으는 것입니다. $B$B정령이나 식물과 싸우면서 세상의 위험한 지역에서 찾을 수 있을 겁니다. 빛에 선택받은 자라면 분명 성공할 거라고 확신합니다. 야만적인 잎사귀와 원소의$B$B 핵을 각각 50개씩 가져오세요. 우리가 이루고자 하는 목표에 큰 도움이 될 겁니다. 돌아오면$B$B 정식으로 우리 일원이 되고, 비밀 훈련 장소 입구가 표시된 지도를 드리겠습니다. 빛이 당신의 영혼을 축복하길.$B$B 돌아온다면 우리는 당신을 형제처럼 맞이할 것이고, 돌아오지 않더라도 우리는 단 한순간도 슬퍼하지 않을 겁니다."},objectives={{63,578126795},"세계를 여행하며 요청받은 물품들을 가져오세요."},progress={{60,2084887526},"간단한 임무야, 죽이고 채집하는 것, 더 뭘 바라겠어?"},completion={{241,2014692394},"형제여, 돌아온 것을 환영한다. 앞으로 다가올 날들에 빛의 축복이 우리 둘 모두에게 함께하길.$B$B여기 당신의 휘장과 입구 지도를 드리겠습니다. 총사령관께서 당신을 매우 반갑게 맞이하실 겁니다.$B$B붉은 십자군을 위하여, 빛을 위하여, 그리고 로데론을 위하여!"}}
rows[80720]={title={{17,1905506057},"끔찍한 소환"},description={"$N, is it?$B$BLord Varimathras tasked me to seek you out at once.$B$BI believe you know where to find him — he stands by the Dark Lady, forever bound to linger in her shadow.$B$BAnd now it is his shadow that looms over you; I would not try his patience.","$NN 씨 $B$B맞으시죠? 바리마트라스 경께서 제게 당신을 즉시 찾아오라고 명하셨습니다.$B$B 당신은 그분이 어디 계신지 아실 거라고 생각합니다. 그는 어둠의 여왕 곁에 있으며, 영원히 그녀의 그림자 속에 머물러 있을 $B$B겁니다. 그리고 지금 그 그림자가 당신을 덮치고 있습니다. 그의 인내심을 시험하고 싶지 않습니다."},objectives={{35,2102367257},"언더시티의 바리마트라스에게 보고하십시오."},progress={{59,1692152852},"필멸자여, 마음껏 무릎 꿇어라. 나는 아첨하는 모습을 보는 걸 아주 즐기거든."},completion={"Ah, $N, here to do my bidding. I expect you to be quicker if you deem yourself worthy of remaining in my service.","아,$N, 내 명령을 수행하러 왔군. 내 부하로 남을 자격이 있다고 생각한다면 더 빨리 움직여야 할 것이다."}}
rows[80721]={title={{9,813024449},"암울한 소식"},description={{449,432131040},"전선에서 이상한 일들이 벌어지고 있다는 소식이 들려왔습니다. 여왕$B$B 폐하의 가장 훌륭한 신하들 중 일부가 실종되었습니다. 너무나 많은 수가 너무나 빠르게, 그리고 너무나 정확하게 사라졌는데, 단순한 전쟁의 불운이라고$B$B 하기에는 무리가 있습니다. 제 데스스토커들은 훨씬 더 위험한 임무에 몰두하고 있으니, 자네는 브릴, 무덤, 그리고 타렌 제분소로 가서 그들을 대신해 현지 유언집행인들의 회계를 받아오도록 하세. $B$B내게 돌아오게 하고, 내가 만족한다면 자네에게 보상을 해 주겠네."},objectives={{151,948450588},"브릴, 무덤, 그리고 타렌 제분소로 가십시오. 최고 집행관 다르탈리아, 집행관 지가드, 그리고 최고 집행관 하드렉과 대화하십시오. 바리마트라스에게 보고하십시오."},progress={{84,659027931},"만약 네가 내 앞에서 한순간이라도 더 꾸물거린다면 네 혈관을 싹 비워버리겠다."},completion={{128,2022425410},"이 모든 일의 배후에는 붉은 십자군의 광신도들이 있는 건가?$B$B그들의 교활한 두뇌를 빼앗기다니, 정말 어이가 없군."}}
rows[80722]={title={{17,1410074994},"쥐를 잡으려면..."},description={{516,324424860},"이 계략의 진실을 밝혀내려면 스칼렛츠가 우리 손에 들어올 수 있도록 유도해야 할 겁니다. 이를 위해 데스가드 $B$B​​한 명을 당신에게 맡겼습니다. 그의 이름은 매버린, 혹은 무버리시입니다. 인간 이름은 제 입에 거슬리는 이름이죠. 북쪽 $B$B수도원으로 가는 길 근처 묘지에서 그를 찾을 수 있을 겁니다. 그를 미끼로 쓰세요. 그는 그다지 귀중한 자산은 아닙니다. 그런 다음 스칼렛츠를 처치하고 그들의 무기고에 있는 이 기묘한 신무기를 손에 넣으세요. 저를 $B$B실망시키지 마십시오."},objectives={{92,223828145},"데스가드 매버릭을 찾아 스칼렛 크루세이드를 위한 함정을 설치하십시오. 바리마트라스에게 보고하십시오."},progress={{63,631095532},"벌써 돌아오셨군요.$B$B메베리우스는 어떻습니까? 너무 심하게 더럽혀지지는 않았겠죠?"},completion={"I can smell the sweet stench of man-blood on you, $N. Good, very good.$B$BAs for Deathguard Mavonius there, the Undertakers and Apothecaries can tend to him, and I expect that to be the last of your concerns.","$N, 자네에게서 달콤한 남자 피 냄새가 나군. 좋아, 아주 좋아.$B$B저기 있는 데스가드 ​​마보니우스는 장의사와 약제사들이 처리할 테니, 그건 자네가 신경 쓸 마지막 문제겠지."}}
rows[80723]={title={{18,2036970634},"신뢰할 수 있는 약국"},description={{387,981997289},"이 물약이 바로 스칼렛 음모의 핵심이다. 밋밋하고 조잡하지만, 짜증 날 정도로 $B$B강력하지. 나는 연금술 같은 천한 짓에는 손대지 않는다. 다행히도, 우리 여왕 폐하의 왕실 약제사들은 증류기를 들여다보고 풀을 갈고 하는 $B$B기술을 선호한다.약국으로 가서 약제사 즈윙커를 찾아 네가 발견한 것을 보여주어라. 그녀는 내 부하다.$B$B어서, 그리고 신중하게 가라."},objectives={{79,960548262},"약병을 약국으로 가져가서 바리마트라스가 신뢰하는 약사에게 말을 걸세요."},progress={{56,1989039506},"즈윙커... 네, 바리마트라스 신께서 당신을 보내셨음을 알겠습니다."},completion={"My name is Zinge, $c.$B$BShow me what you've brought and I shall help you as I can, if such is my lord's command.","제 이름은 징게,$c입니다.$B$B가져오신 물건을 보여주시면, 주인님의 명령이라면 제가 할 수 있는 한 도와드리겠습니다."}}
rows[80724]={title={{20,116453140},"전문가와 상담하기"},description={{554,1462530973},"당신이 가지고 있는 물질에 대해 몇 가지 예비 검사를 해 보았습니다. 제가 알아낸 것은 그 물약에 평화의 꽃과 유령의 머리카락이 들어 있다는 것뿐입니다. $B$B하지만 그것만으로는 언데드에게 혼수상태를 일으키는 이유를 설명할 수 $B$B없습니다. 제 생각에는 이 혼합물에 어떤 고위 마법이 개입된 것 같고, 그것은 제가 밝혀낼 수 있는 범위를 넘어섭니다. 우리에게 필요한$B$B 답을 줄 수 있는 이는 오직 한 명뿐입니다. 그는 브릴 동쪽, 브라이트워터 호수 중앙에 살고 있습니다. 그에게$B$B 존경심을 가지고 다가가되, 말 한마디 한마디를 신중하게 하십시오."},objectives={{40,820237719},"티리스팔 숲에서 군터 아르카누스를 찾으세요."},progress={{16,1918324067},"또 다른 방문객입니다."},completion={{219,1707516646},"당신의 이야기와 이 물약의 효과가 사실이라면, 저를 찾아오신 것은 옳은 선택이었습니다.$B$B이것은 붉은 십자군이 절대 손에 넣어서는 안 될 무기입니다. 이것이 무엇인지에 대해서는 잠시만 기다려 주십시오."}}
rows[80725]={title={{18,1654532619},"군터의 호의로"},description={"I sometimes long for Dalaran and of the days I once lived as no more than a mere student of the arcane arts.$B$BWhen the Scourge shackled me to their dominion, my old memories were the only tether that kept me from losing myself utterly.$B$BI do not intend to burden you with my life's story, $N, but I already know what this vial is and how it was made, yet I need you to do me a favor before I tell you. Think of it as an equivalent exchange.$B$BGo to the decadent town of Ambermill: Behind its town hall I buried a locket and sealed it with magic.$B$BI will give you a scroll that will erase its warding spell, retrieve the locket, and return it to me. Then we shall talk.","가끔 달라란과 한때 마법을 배우는 한낱 학생에 불과했던 시절이 그리워집니다. 스컬지가 저를 그들의 지배하에$B$B 가두었을 때, 옛 기억만이 제가 완전히 자아를 잃지 않도록 붙잡아 준 유일한 끈이었습니다. 제 인생 이야기를 당신에게 $B$B늘어놓으려는 건 아니지만, 이 작은 병이 무엇이고 $N어떻게 만들어졌는지 이미 알고 있습니다. 하지만 그 이야기를 하기 전에 당신의 부탁이 하나 있습니다. 일종의 등가 교환이라고 생각하세요. 퇴폐적인$B$B 마을 앰버밀로 가십시오. 마을 회관 뒤편에 로켓을 묻고 마법으로 봉인해 두었습니다. 제가 봉인 $B$B마법을 풀 수 있는 두루마리를 드리겠습니다. 로켓을 찾아서 제게 가져다주세요. 그러면 이야기를 나눌 수 있을 겁니다."},objectives={{53,1755903298},"앰버밀 뒤쪽으로 가서 군터의 로켓을 찾아보세요."},progress={{20,1800631979},"성공하셨나요?"},completion={"You had to battle a mage for it?$B$BI presume he failed to speak his name as you slew him, but that ought to be no concern of ours.$B$BYou fulfilled your end of the bargain, $N, and it is now my turn to repay the debt.","마법사와 싸워야만 얻었단 말인가?$B$B그가 죽임을 당할 때 자신의 이름을 말하지 못했을 거라고 짐작은 하지만, 그건 우리와는 상관없는 일이지.$B$B자네는 약속을 지켰으니,$N이제는 내가 그 빚을 갚을 차례군."}}
rows[80726]={title={{16,267822164},"영혼과 연금술"},description={{603,1145735787},"당신이 회수한 스칼렛츠가 제조한 물약은 '잠자는 죽음의 물약', 혹은 학자들이 선호하는 명칭인 '죽음의 물약'으로 알려져 있습니다.$B$B 이 물약은 제2차 전쟁 당시 달라란에서 굴단의 죽음의 기사들이 휘두르는 불경스러운 힘에 맞서기 위해 처음 만들어졌습니다.$B$B 이 물약은 연금술에서 흔히 사용되는 '현자의 돌'이라는 특정한 도구로만 제조할 수 있습니다. 하지만 안타깝게도 저는 현자의 돌을 가지고 있지도 않고, 복제하는 방법도 모릅니다. $B$B일단은 당신이 알아낸 것을 가지고 언더시티에 있는 당신의 스승들에게 돌아가십시오. 저는 물약을 보관하고 다른 정보를 얻을 수 있는지 알아보겠습니다."},objectives={{35,758333524},"언더시티의 바리마트라스로 돌아가십시오."},progress={"My loyal $r returns.$B$BGo on, speak.","나의 충실한$r이 돌아왔습니다.$B$B자, 말해 보세요."},completion={{167,1994135524},"쳇, 물약, 마법약, 돌멩이라니. 이보다 더 지루한 게 있을까?$B$B적어도 그 소위 '리치'는 쓸모가 있었지. 너도 마찬가지고.$B$B넌 또 한 번 날 기쁘게 해줬어."}}
rows[80727]={title={{27,1960274365},"어두운 성격의 여인에게 어울리는 어두운 기질"},description={{286,491155991},"우리가 조사한 내용을 어둠의 여신께 전달할 보고서를 준비했습니다. 그녀는 이 보고서를 $B$B읽고 좋아하지 않을 것이며, 그녀의 분노가 당신의 최후가 된다면 참으로 안타까운 일일 것입니다. 그러니 그녀 앞에$B$B 무릎 꿇고, 그녀를 달래고, 나를 섬겼던 것처럼 충성스럽게 섬기십시오... 하지만 당신이 누구에게 속해 있는지는 잊지 마십시오."},objectives={{19,1707978758},"실바나스에게 보고하라."},progress={{63,1857445918},"실바나스는 당신이 건네준 보고서를 받습니다. 하지만 열어보지는 않습니다."},completion={"Do you think me a fool, $N? Did you think I would be unaware of what occurs within my own realm, within my own throne room?$B$B<Sylvanas shreds the report with her hands.>","$N, 날 바보로 생각하는 건가? 내 영역, 내 왕좌 안에서 무슨 일이 벌어지는지 내가 모를 거라고 생각했나?$B$B<실바나스는 손으로 보고서를 갈기갈기 찢어버렸다.>"}}
rows[80728]={title={{21,1976562833},"미래는 암울해 보인다"},description={{530,647987257},"나는 내 전사들의 정신을 흐리게 하는 모든 술의 악행, 네가 내 공포의 군주와 결탁한 사실, 그리고 그의 명령에 따라 낭비한 죽음의 수호자들을 모두 알고 있다.$B$B 하지만 어쩌면 자네는 바리마트라스에게 정이 들었는지도 모르겠군. 그의 장난감이 되고 싶은 건가? 한마디만 하면 자네를 그의 것으로 만들어주겠다. 영원히. $B$B아니라고? 아직도 네 영혼을 소중히 $B$B여기는 건가? 안타깝군. 그렇다면 내 말대로 동부 역병지대에 있는 티르의 손으로 가라. 그 열성적인 바보들에게서 붉은 제복을 가져와 군터에게 가져다주도록. 나머지는 그가 알 것이다. 이제$B$B 가거라, 내 눈앞에서 사라져라."},objectives={{147,632031015},"동부 역병지대에 있는 티르의 손으로 가서 붉은색 수련생 복장을 획득한 다음, 밝은 물 호수 섬에 있는 군터 아르카누스에게 돌아가십시오."},progress={{162,2083080871},"네, 밴시 여왕께서 당신의 도착을 미리 알려주셨습니다. 제복은 준비하셨나요?$B$B당신이 그녀에게 불러일으킨 불미스러운 감정을 만회하는 데 도움이 될지도 모르겠습니다."},completion={{70,1673313813},"그 정도면 충분합니다. 잠시 여기 놓아주세요. 오래 걸리지 않을 겁니다."}}
rows[80729]={title={{24,1190161101},"다른 색조의 붉은색"},description={"As you may have divined, we contrive to infiltrate you into the ranks of the Scarlet Crusade.$B$BUpon the uniform you've brought me I placed an illusion charm, as well as a few greater cloaking wards to keep the enchantment from easy detection.$B$BAll that is left is for you to introduce yourself as a novice to the recruiters in Tyr's Hand.$B$BOne such recruiter should be Mavel Brightwood.$B$BI wish you luck, $N. Have your wits about you and find out what you can of their meddlesome alchemists.","짐작하셨겠지만, 우리는 당신을 붉은십자군의 일원으로 잠입시키려는 계획을 세웠습니다.$B$B 당신이 가져온 제복에는 환영 마법과 함께 마법이 쉽게 발각되지 않도록 몇 가지 강력한 은폐 마법을 걸어 두었습니다. 이제 남은 일은 $B$B티르의 손에 있는 모집관들에게 신병으로 자신을 소개하는 것입니다. 그중 한 명은 메이블 $B$B브라이트우드일 겁니다. 행운을 빕니다, N.$B$B 정신을 바짝 $N차리고 그들의 참견쟁이 연금술사들에 대해 알아낼 수 있는 모든 것을 알아내십시오."},objectives={{52,1992216529},"티르의 손으로 가서 메이블 브라이트우드에게 보고하십시오."},progress={{28,590133143},"빨리 말씀하시거나 자리를 옮기세요."},completion={{55,1810060142},"아, 또 다른 신병이군. 여기까지 오는 데 왜 이렇게 오래 걸렸어?"}}
rows[80730]={title={{21,927138002},"카라반과 카라반의 만남"},description={{801,1635785072},"SI:7은 우리에게 매우 빠르게 연락할 수 있는 수단을 가지고 있으며, 믿기 어렵겠지만 매우 신뢰할$B$B 만합니다. 더 자세한 설명은 생략하겠지만, 에어리 피크에 도착할 예정이었던 드워프 대상 행렬이 저습지를 벗어나지 못했다는 $B$B사실만은 알아두십시오. 대상 행렬은 폐허가 되었고, 한때 드워프였던 자들의 훼손된 잔해만$B$B 남아 있습니다. 우리 요원들이 이미 그 지역을 수색했지만 아무것도 찾지 못했고, 현재 새로 모집된 스칼렛 광신도들을 추적하고 있습니다.$B$B 당신이 얼마나 뛰어난 탐정이라고 생각하는지는 잘 모르겠지만, 다시 한번 살펴보시기 바랍니다. 어쩌면 그들이 놓친 것이$B$B 있을지도 모릅니다. 만약 그 광신도들을 발견한다면, 스칼렛이 어떤 방식으로 그들을 세뇌했는지 알 수 없으니, 최대한 많이 살려주고 메네틸로 데려가 주십시오."},objectives={{46,1384535276},"캐러밴의 경로를 따라가며 단서를 찾아보세요."},progress={{51,475401577},"지금 뭐 사시려는 거예요, 아니면 그냥 저를 귀찮게 하려는 거예요?"},completion={{157,946648833},"이봐, 나 먹고 살려고 발버둥 치는 중이야. 그러니까 뭐라도 사든지 아니면 꺼져!$B$B물론 다른 얘기라도 있으면 괜찮지만, 빨리 말해!"}}
rows[80735]={title={{19,1614827128},"흔치 않은 요청"},description={{68,1462073483},"내 요청을 들어준다면, 나는 너에게 고대의 강력한 지식을 가르쳐주겠다."},objectives={{111,743248393},"오닉시아의 비늘 3개를 아우렐리우스에게 가져다주면, 그는 그것들을 정제된 오닉시아의 비늘로 변환하는 방법을 가르쳐 줄 것입니다."},progress={{28,1923331682},"오닉시아의 비늘 3개를 가져오시오."},completion={{77,130250930},"잘했어요. 이제 우리 계약을 지키기 위해 제가 아는 것을 가르쳐 드리겠습니다."}}
rows[80736]={title={{14,1288423857},"드문 요청"},description={{269,736511541},"잊혀진 지식을 찾아 이곳에 온 자는 당신뿐만이 아닙니다. 하지만 다른 모든 사람들과 마찬가지로, 그 지식은 쉽게 주어지지 않을 것입니다. 제 부탁을 들어주시면 제가 아는 모든 것을 가르쳐 $B$B드리겠습니다. 제 비밀을 전수해 준 훌륭한 연금술사의 도움이 필요할 것입니다."},objectives={{114,406425450},"정제된 오닉시아의 비늘 3개를 아우렐리우스에게 가져다주면, 그는 그것들을 충전된 오닉시아의 비늘로 바꾸는 방법을 가르쳐 줄 것입니다."},progress={{98,913381231},"뭘 기다리고 있는 거지? 오닉시아의 정제된 비늘 3개를 가져오너라. 내 지식을 갈망하지 않는 건가?"},completion={{19,1430544252},"잘했어요."}}
rows[80738]={title={{23,574578748},"레시피: 구루바시 검보"},description={{327,623209240},"구루바시 트롤들은 먹으면 의지력을 강화시켜주는 독특한 검보 레시피를 가지고 있습니다. 이 검보는 그들의 가장 용맹한 전사들이 전투 전에 즐겨 먹는 음식입니다. 저는$B$B 그 레시피를 입수했고, 투기장에서 실력을 증명하는 자에게 이 레시피를 넘겨줄 용의가 있습니다. 피의$B$B 토큰을 가져오시면 당신도 이 레시피를 배울 수 있습니다."},objectives={{87,1955794127},"스트랭글쏜 밸리의 구루바시 투기장에 있는 브래들리 스틸에게 피의 토큰 25개를 가져다 주세요."},progress={{22,1920851038},"그래서, 마음을 정하셨어요?"},completion={{108,1634896738},"구루바시의 비법을 마음껏 즐겨보세요. 당신은 그들의 가장 잔혹한 전사들만큼이나 명성이 자자할 겁니다."}}
rows[80739]={title={{40,508994055},"공식: 마법 장갑 - 강력한 힘 부여"},description={{325,51331543},"투기장에서의 치열하고 빠른 전투는 종종 극복할 수 있는 힘에 따라 승패가 결정됩니다. 그러한 힘은 $B$B준비되지 않은 상대를 제압하거나, 전투의 열기 속에서 승리하고자 하는 마지막 의지를 불어넣어 줄 수 있습니다. 그러한 힘은$B$B 한때 구루바시 트롤들이 지녔던 이 마법에서 찾을 수 있습니다. 대가를 치른다면, 당신도 그 마법을 손에 넣을 수 있습니다."},objectives={{87,1955794127},"스트랭글쏜 밸리의 구루바시 투기장에 있는 브래들리 스틸에게 피의 토큰 25개를 가져다 주세요."},progress={{22,1920851038},"그래서, 마음을 정하셨어요?"},completion={{101,111193530},"이제 당신의 손끝에 힘이 있습니다. 이 마법을 현명하게 사용하면 큰 장애물도 극복할 수 있습니다."}}
rows[80740]={title={{21,1508003572},"그들이 우리 용을 데려갔어요!"},description={"$N, the Lunar Festival needs you! During the celebration a sneaky satyr snuck in and stole our most special firework. It was a special kind of firework I managed to get from the Goblins of Booty Bay. He claims he managed to buy this off some traveling merchant that claimed he was from all the way to Pandaria.\010\010Its beauty would cover the entire sky of Moonglade in the form of a dragon serpent. You must retrieve it! It was supposed to be our greatest surprise for this year's Lunar Event.\010\010If the revelers are to be believed this satyr came at the behest of Lorgus Jett. A thievling cultist that hides in the Blackfathom Deeps. Retrieve my prize and I will offer you, yours!","$N, 음력 축제에 당신이 필요해요! 축제 도중 교활한 사티로스가 몰래 잠입해서 우리의 가장 특별한 불꽃놀이 폭죽을 훔쳐갔어요. 전 무법항의 고블린들에게서 어렵게 구한 특별한 폭죽이었죠. 그 사티로스는 판다리아에서 왔다는 떠돌이 상인에게서 샀다고 주장하더군요.\013\010\013\010그 폭죽은 용뱀 형상으로 달빛숲 하늘 전체를 뒤덮을 만큼 아름다웠어요. 꼭 되찾아 주셔야 해요! 올해 음력 축제의 가장 큰 선물이었거든요.\013\010\013\010축제 참가자들의 말에 따르면, 그 사티로스는 블랙패덤 심연에 숨어 있는 도둑 광신도 로르구스 제트의 사주를 받았다고 해요. 제 소중한 폭죽을 되찾아 주시면, 당신의 폭죽도 드리겠습니다!"},objectives={{119,56130360},"블랙패덤 딥스에 있는 로르구스 제트에게서 용의 불꽃놀이를 받아 무글레이드에 있는 달 축제 상인에게 가져가세요."},progress={{21,1201687826},"즐거운 음력 설날 보내세요!"},completion={{105,1424447718},"어머, 당신이었군요! 그걸 되찾았군요. 엘룬께서 직접 당신의 친절에 감사드린다고 하셨어요. 당신을 위해 깜짝 선물을 준비했습니다."}}
rows[80755]={title={{18,534037912},"야수를 훈련시키다"},description={{610,1615416812},"그래, 그래, 리오트가 자네를 내게 보낸 이유를 알겠네. 그 주문이 없었더라면 자네는 가장 사나운 짐승들 외에는 길들이기가 꽤 힘들었을 테지. 이제 자네는 세상의 모든 생명체를 길들일 수 $B$B있겠군! 하지만 그것만으로는 충분하지 않다는 걸 알아야 해. 자네가 마음대로 다루는 생명체의 진정한 힘은 야생에서 관찰한 재능을 부여하는 데 있다는 걸 깨달아야 한다. 단순히 야생 동물을 적에게 풀어놓는 것만으로는$B$B 부족해. 자네가 길들인 짐승의 진정한 잠재력을 끌어내고 싶다면 다시 한번 내게 말해 보네. 짐승 조련사의 비법을 하나하나 자세히 알려주겠다."},objectives={{65,1888671724},"지하도시 전쟁 구역에 있는 다이앤 윌로우필드와 대화하세요."},completion={{288,1489991670},"이제 네 애완동물을 훈련시키고 이끌어갈 수 있는 기술을 부여하겠다. 애완동물에게 새로운 능력을 가르칠 수 있을 뿐만 아니라, 먹이를 주고 전투에서 쓰러졌을 때 되살릴 수도 있게 되었다.$B$B자, 가라. 네 짐승들을 모아 어둠의 여왕의 편으로 이끌어라."}}
rows[140821]={title={{16,1341965035},"전략적 공격"},description={{356,1411838453},"병사들이여, 잘 들으십시오! 우리 정찰병들이 오크 전장의 지휘관 중 한 명을 발견했습니다. 그는 악순이라는 이름의, 극도로 잔인하고 교활한 검술의 달인입니다. 병력을 이끌고 그를 찾아 나서십시오. 이 위협적인 자를 하루빨리 제거할수록 전선을 사수할 가능성이 높아집니다. 이 야만인들이 인간의 땅으로 더 이상 진격해 들어오도록 내버려 둘 수는 없습니다."},objectives={{57,1513925529},"전장에서 검술의 달인 악순을 찾아 처치하라."},progress={"Clear your head of impure thoughts, $C. We must trust the light to guide us to victory.","$C님, 머릿속의 불순한 생각을 깨끗이 비우세요. 우리는 승리로 인도해 줄 빛을 믿어야 합니다."},completion={{71,490167827},"정말 잘했어요! 아무도 저 괴물을 쓰러뜨릴 수 없을 거라고 생각했었는데!"}}
rows[1140820]={title={{16,1341965035},"전략적 공격"},description={{353,1806584566},"너희 하찮은 병사들이 스스로를 도살장에 던져 넣는 모습을 보는 건 즐겁지만, 이런 식으로는 승리를 거둘 수 없다. 이 땅을 정복하려면 저들의 지도부를 제거해야 한다. 나머지 하급 병사들을 모아 인간들의 전략가인 카트린 여사를 찾아라. 지휘 체계가 무너지면, 저들의 보병들은 우리 전사들에게 손쉬운 먹잇감이 될 것이다."},objectives={{52,979670020},"전장에서 카트린 부인을 찾아 처치하십시오."},progress={{38,1030253649},"시간을 낭비할 시간이 없다. 당장 공격해야 한다!"},completion={"You have proven yourself a worthy warrior, $N. Well done.","$N님, 당신은 훌륭한 전사임을 증명해냈습니다. 정말 잘하셨습니다."}}
